(window.GIM_TP=window.GIM_TP||{})["Z.AchreiMot.0"]={"from":0,"a":[[["(ויקרא ט״ז:א׳) וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה. רִבִּי יְהוּדָה אָמַר, כֵּיוָן דִּכְתִּיב וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה, אֲמַאי זִמְנָא אָחֳרָא וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֶּר אֶל אַהֲרֹן אָחִיךְ, דְּהָא בְּמִלּוּלָא קַדְמָאָה סַגֵּי. אֶלָּא הָכִי תָּנֵינָן, כְּתִיב, וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר יְיָ' אֵלָיו. וּכְתִיב, (שמות כ״ד:א׳) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל יְיָ'. וְהָא אוּקְמוּהָ מִלָּה, דְּהָכָא דַּרְגָּא חַד. וּלְבָתַר, דַּרְגָּא אָחֳרָא. אוּף הָכָא, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה דַּרְגָּא חַד. וּלְבָתַר וַיֹאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, דַּרְגָּא אָחֳרָא. וְכֹלָּא, בְּחַד מַתְקְלָא סַלְּקָא, וּמִן שָׁרְשָׁא חָד כֻּלָּא אִתְחַבָּר.","אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי יִצְחָק פָּתַח, (תהילים ב׳:י״א) עִבְדוּ אֶת יְיָ' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. וּכְתִיב, (תהילים ק׳:ב׳) עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. הָנֵי קְרָאֵי קַשְׁיָין אֲהַדְדֵי, אֶלָּא הָכִי תָּאנָא, עִבְדוּ אֶת יְיָ' בְּיִרְאָה. דְּכָל פּוּלְחָנָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח קָמֵי מָארֵיהּ, בְּקַדְמִיתָא בָּעֵי יִרְאָה, לְדַחֲלָא מִנֵּיהּ, וּבְגִין דַּחֲלָא דְּמָארֵיהּ, יִשְׁתְּכַּח לְבָתַר דְּיַעֲבֵיד בְּחֶדְוָותָא פִּקּוּדֵי אוֹרַיְיתָא. וְעַל דָּא כְּתִיב, (דברים י׳:י״ב) מָה יְיָ' אֱלֹהֶיךָ שׁוֹאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה.","וְגִילוּ בִּרְעָדָה. דְּאָסִיר לֵיהּ לְבַּר נָשׁ לְמֶחְדֵּי יַתִּיר בְּעָלְמָא דֵּין. הַאי בְּמִלֵי דְּעָלְמָא, אֲבָל בְּמִלֵי דְּאוֹרַיְיתָא וּבְפִקוּדֵי דְּאוֹרַיְיתָא, בָּעֵי לְמֶחְדֵּי. לְבָתַר, יִשְׁתְּכַּח בַּר נָשׁ דְּיעָבִיד בְּחֶדְוָותָא פִּקּוּדֵי אוֹרַיְיתָא. דִּכְתִּיב, עִבְדוּ אֶת יְיָ' בְּשִׂמְחָה."],[[0,"וידבר ה׳ אל משה וגו׳:","וידבר ה׳ אל משה אחרי מות וגו'. ויאמר ה׳ אל משה. ר׳ יהודה אמר, כיון שכתוב, וידבר ה׳ אל משה, למה נאמר עוד פעם ויאמר ה׳ אל משה וגו', הרי בדיבור הראשון די. ומשיב, אלא כך למדנו, כתוב, ויקרא אל משה וידבר ה׳ אליו. וכן כתוב, ואל משה אמר עלה אל ה'. והרי העמידוה, שהדיבור שבכאן, דהיינו ויקרא אל משה, או ואל משה אמר, הוא מדרגה אחת, דהיינו המלכות, ואחר כך, דהיינו וידבר ה׳ אליו, או עלה אל ה', היא מדרגה אחרת, דהיינו ז״א. אף כאן, וידבר ה׳ אל משה, הוא מדרגה אחת, דהיינו מדרגת דין שנקרא דבור, ואח״כ, ויאמר ה׳ אל משה, הוא מדרגה אחרת, דהיינו מדת הרחמים שנקרא אמירה. ומה שכתוב בשניהם השם הוי״ה, הוא, כי במשקל אחד עולים. ומשורש אחד נתחבר הכל. כלומר שב׳ מדרגות דין ורחמים האמורים, הם ממשקל אחד ושורש אחד, שהוא ז״א הנקרא הויה."],[1,"אחרי מות שני בני אהרן:","ר׳ יצחק פתח, עבדו את ה׳ ביראה וגילו ברעדה. וכתיב, עבדו את ה׳ בשמחה באו לפניו ברננה. מקראות אלו סותרים זה את זה, שכאן אומר לעבוד ביראה ורעדה, וכאן אומר בשמחה וברננה. ומשיב אלא כך למדנו, עבדו את ה׳ ביראה. כי בכל עבודה שרוצה האדם לעבוד לפני רבונו. בתחילה צריך יראה, לירא מפניו, ובשביל יראת רבונו יזכה לאחר כך לעשות בשמחה מצות התורה. וע״כ כתוב, מה ה׳ אלקיך שואל מעמך כי אם ליראה. שעל ידה יזכה לכל."],[2,"וגילו ברעדה:","היינו שאסור לאדם לשמוח ביותר בעולם הזה. זה הוא בדברי העולם, אבל בדברי תורה ובמצות התורה צריך לשמוח. ולאחר שלא ישמח בדברי העולם ימצא האדם שיעשה מצות התורה בשמחה. שכתוב, עבדו את ה׳ בשמחה."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. וַיֹּאמֶר ה' אֶל מֹשֶׁה. רַבִּי יְהוּדָה אָמַר, כֵּיוָן שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה, לָמָּה פַּעַם אַחֶרֶת וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, שֶׁהֲרֵי בַּדִּבּוּר הָרִאשׁוֹן מַסְפִּיק? אֶלָּא כָּךְ שָׁנִינוּ, כָּתוּב וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו. וְכָתוּב (שמות כד) וְאֶל מֹשֶׁה אָמַר עֲלֵה אֶל ה'. וַהֲרֵי בֵּאֲרוּ אֶת הַדָּבָר, כָּאן דַּרְגָּה אַחַת, וְאַחַר כָּךְ דַּרְגָּה אַחֶרֶת. אַף כָּאן, וַיְדַבֵּר ה' אֶל מֹשֶׁה - דַּרְגָּה אַחַת. וְאַחַר כָּךְ, וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ - דַּרְגָּה אַחֶרֶת. וְהַכֹּל עוֹלֶה בְּמִשְׁקָל אֶחָד, וּמִשֹּׁרֶשׁ אֶחָד הַכֹּל הִתְחַבֵּר."],[1,"","אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רַבִּי יִצְחָק פָּתַח, (תהלים ב) עִבְדוּ אֶת ה' בְּיִרְאָה וְגִילוּ בִּרְעָדָה. וְכָתוּב (שם ק) עִבְדוּ אֶת ה' בְּשִׂמְחָה בֹּאוּ לְפָנָיו בִּרְנָנָה. הַפְּסוּקִים הַלָּלוּ קָשִׁים זֶה עַל זֶה. אֶלָּא כָּךְ שָׁנִינוּ, עִבְדוּ אֶת ה' בְּיִרְאָה - שֶׁכָּל עֲבוֹדָה שֶׁרוֹצֶה בֶּן אָדָם לַעֲבֹד לִפְנֵי רִבּוֹנוֹ, בָּרִאשׁוֹנָה צָרִיךְ יִרְאָה, לִפְחֹד מִמֶּנּוּ. וּמִשּׁוּם הַפַּחַד שֶׁל אֲדוֹנוֹ יִמָּצֵא אַחַר כָּךְ שֶׁיַּעֲשֶׂה בְשִׂמְחָה אֶת מִצְווֹת הַתּוֹרָה, וְעַל כֵּן כָּתוּב, (דברים י) מָה ה' אֱלֹהֶיךְ שּאֵל מֵעִמָּךְ כִּי אִם לְיִרְאָה."],[2,"","וְגִילוּ בִּרְעָדָה - שֶׁאָסוּר לָאָדָם לִשְׂמֹחַ יוֹתֵר בָּעוֹלָם הַזֶּה. וְזֶה בְּדִבְרֵי הָעוֹלָם. אֲבָל בְּדִבְרֵי תוֹרָה וּבְמִצְווֹת הַתּוֹרָה צָרִיךְ לִשְׂמֹחַ. אַחַר כָּךְ יִמָּצֵא אָדָם שֶׁיַּעֲשֶׂה בְשִׂמְחָה אֶת מִצְווֹת הַתּוֹרָה, שֶׁכָּתוּב עִבְדוּ אֶת ה' בְּשִׂמְחָה."]]],[["רִבִּי אַבָּא אָמַר, עִבְדוּ אֶת יְיָ' בְּיִרְאָה. רָזָא דְּמִלָּה הוּא, עִבְדוּ אֶת יְיָ' בְּיִרְאָה, מַה יִרְאָה הָכָא. אֶלָּא כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (משלי א׳:ז׳) יִרְאַת יְיָ' רֵאשִׁית דָּעַת, וּכְתִיב, (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת יְיָ'. יִרְאַת יְיָ', קוּדְשָׁא בְּרִיךְ הוּא הָכִי אִקְרֵי. רִבִּי אֶלְעָזָר אָמַר, עִבְדוּ אֶת יְיָ' בְּיִרְאָה, מַאן דְּבָעֵי לְמֶעְבַּד פּוּלְחָנָא דְּמָארֵיהּ, מֵאָן אֲתַר שָׁארֵי, וּבְאָן אֲתַר יְכַוִּון פּוּלְחָנָא לְיַחֲדָא שְׁמָא דְּמָארֵיהּ. הָדָר וְאָמַר בְּיִרְאָה, בְּיִרְאָה הוּא שֵׁירוּתָא, מִתַּתָּא לְעֵילָּא. (תא חזי בני אהרן האי אוקימנא והא אתמר מלה)","תָּא חֲזֵי, מַה כְּתִיב הָכָא אַחֲרֵי מוֹת, וּלְבָתַר דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְגוֹ' בְּזֹאת יָבֹא אַהֲרֹן, אֶלָּא מִכָּאן, שֵׁירוּתָא לְאַזְהָרָא לְכַהֲנֵי, כָּל מַאן, דְּבַעְיָין לְאִזְדַּהֲרָא בְּהַאי זֹאת, וְדָא הִיא יִרְאַת יְיָ'.","דָּבָר אַחֵר. אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי יוֹסֵי אָמַר, אַחֲרֵי מוֹת נָדָב וַאֲבִיהוּא, מִבָּעֵי לֵיהּ, מַאי טַעְמָא שְׁנֵי בְּנֵי אַהֲרֹן, וְהָא יְדִיעַ דִּבְנוֹי הֲווֹ. אֶלָּא הָכִי תָּאנָא, דְּעַד כָּאן לָאו בִּרְשׁוּתַיְיהוּ קַיְימֵי, אֶלָּא בִּרְשׁוּתָא דְּאָבוּהוֹן, וּבְגִין כָּךְ, בְּקָרְבָתָם לִפְנֵי יְיָ' וַיָמוּתוּ, דְּאִינּוּן דָּחֲקוּ שַׁעֲתָא בְּחַיֵּי דְּאָבוּהוֹן, וְכֹלָּא הֲוָה, בְּגִין הַהוּא חוֹבָא דְּעָבְדוּ, דִּכְתִּיב (במדבר ג׳:ד׳) בְּהַקְרִיבָם אֵשׁ זָרָה. דְּתַנְיָא, בְּאָתַר חַד, כְּתִיב בְּהַקְרִיבָם אֵשׁ זָרָה, וּבְאֲתָר חַד כְּתִיב, בְּקָרְבָתָם לִפְנֵי יְיָ'. וְהַאי וְהַאי הֲוָה, וּבְגִין כָּךְ כְּתִיב הָכָא בְּנֵי אַהֲרֹן, וּכְתִיב בְּקָרְבָתָם.","(תאנא) אָמַר רִבִּי חִיָיא, יוֹמָא חַד הֲוִינָא אָזִיל בְּאָרְחָא, לְמֵיהַךְ גַּבֵּיה דְּרִבִּי שִׁמְעוֹן, לְמֵילַף מִנֵּיהּ פַּרְשְׁתָּא דְּפִסְחָא. עַרְעִית בְּחַד טוּרָא, וַחֲמֵינָא בְּקִיעִין גּוּמִּין בְּחַד טִינְרָא, וּתְרֵין גּוּבְרִין בָה. עַד דַּהֲוִינָא אָזִיל, שְׁמַעְנָא קָלָא דְּאִינּוּן גּוּבְרִין, וַהֲווּ אַמְרִין, (תהילים מ״ח:א׳-ב׳) שִׁיר מִזְמוֹר לִבְנֵי קֹרַח גָּדוֹל יְיָ' וּמְהֻלָל מְאֹד וְגוֹ'. מַאי שִׁיר מִזְמוֹר. אֶלָּא הָכִי תָּאנָא מִשְּׁמֵיהּ דרִבִּי שִׁמְעוֹן, שִׁיר דְּאִיהוּ כָּפוּל, שִׁיר דְּאִיהוּ מְשׁוּבַּח מִשְּׁאַר שִׁירִין, וְעַל דְּאִיהוּ מְשׁוּבַּח מִשְּׁאַר שִׁירִין, תְּרֵין זִמְנִין אִתְּמַר בֵּיהּ שִׁירָתָא, וְכֵן (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. כְּהַאי גַּוְונָא, (שיר השירים א׳:א׳) שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, שִׁירָתָא לְעֵילָּא מִן שִׁירָתָא.","שִׁיר מִזְמוֹר, שִׁירָתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּקָא מְזַמְּרֵי בְּנֵי קֹרַח עַל אִינּוּן דְּיַתְבֵי, עַל פִּתְחָא דְּגֵיהִנָם. וּמַאן אִינּוּן, אֲחוּהוֹן דְּאִינּוּן דְּיַתְבֵי בְּתַרְעֵי דְּגֵיהִנָּם. וְעַל דָּא, שִׁירָתָא דָּא בְּיוֹם שֵׁנִי אִתְּמַר. קָרִיבְנָא גַּבַּיְיהוּ, אֲמֵינָא לְהוּ, מַאי עֲסָקַיְיכוּ בַּאֲתַר דָּא. אָמְרוּ מְזַבְּנֵי אֲנָן, וּתְרֵי יוֹמֵי בְּשַׁבְּתָא, בָּדִילְנָא מִיִשׁוּבָא וְנַעֲסֵק בְּאוֹרַיְיתָא. בְּגִין דְּלָא שַׁבְקִין לָן בְּנֵי נָשָׁא, כָּל יוֹמָא וְיוֹמָא. אֲמֵינָא זַכָּאָה חוּלָקֵיכוֹן.","תּוּ פָּתְחוּ וְאָמְרוּ. בְּכָל זִמְנָא דְּצַדִיקַיָא מִסְתַּלְּקֵי מֵעָלְמָא, דִּינָא אִסְתַּלָּק מֵעָלְמָא, וּמִיתַתְהוֹן דְּצַדִיקַיָא מְכַפֶּרֶת עָל חוֹבֵי דָּרָא. וְעַל דָּא פַּרְשְׁתָּא דִּבְנֵי אַהֲרֹן, בְּיוֹמָא דְּכִפּוּרֵי קָרֵינָן לָהּ, לְמֶהֱוִי כַּפָּרָה לְחוֹבֵיהוֹן דְּיִשְׂרָאֵל. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, אִתְעַסְּקוּ בְּמִיתָתְהוֹן דְּצַדִּיקַיָּא אִלֵּין, וְיִתְחַשֵׁב לְכוּ כְּאִלּוּ אַתּוּן מְקָרְבִין קָרְבְּנִין בְּהַאי יוֹמָא לְכַפְּרָא עָלַיְיכוּ. דְּתָנֵינָן, כָּל זִמְנָא דְּיִשְׂרָאֵל יֵהוֹן בְּגָלוּתָא, וְלָא יִקְרְבוּן קָרְבְּנִין בְּהַאי יוֹמָא, וְאִינּוּן תְּרֵין שְׂעִירִין לָא יַכְלִין לְקָרְבָא, יְהֵא לְהוּ דֻּכְרָנָא, דִּתְרֵי בְּנֵי אַהֲרֹן, וְיִתְכַּפֵּר עֲלַיְיהוּ.","דְּהָכִי אוֹלִיפְנָא, דִּכְתִּיב, (במדבר ג׳:ב׳) וְאֵלֶּה שְׁמוֹת בְּנֵי אַהֲרֹן הַכֹּהֲנִים וְגוֹ'. וּכְתִיב, הַבְּכֹר נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר. וְאֶלְעָזָר וְאִיתָמָר מִבָּעֵי לֵיהּ, מַהוּ אֶלְעָזָר וְאִיתָמָר. אֶלָּא שָׁקוּל הֲוָה אֲבִיהוּא כִּתְרֵי אֲחוּי. וְנָדָב כְּכֻלְּהוּ.","וְאִית דְּמַתְנֵי (לה אפכא) הַבְּכֹר נָדָב, דָּא בִּלְחוֹדוֹי, וַאֲבִיהוּא בִּלְחוֹדוֹי, וְכָל חַד אִתְחֲשִׁיב בְּעֵינֵיהּ, כְּתַרְוַיְיהוּ, כְּאֶלְעָזָר וְאִיתָמָר. אֲבָל נָדָב וַאֲבִיהוּא בִּלְחוֹדַיְיהוּ, שְׁקוּלִין הֲווֹ לְקָבֵל שִׁבְעִין סַנְהֶדְרִין, דַּהֲווֹ מְשַׁמְּשִׁין קָמֵי מֹשֶׁה. וּבְגִין כַּךְ, מִיתָתְהוֹן מְכַפְּרָא עַל יִשְׂרָאֵל. וְעַל דָּא כְּתִיב, (ויקרא י׳:ו׳) וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה. וְאָמַר רִבִּי שִׁמְעוֹן, הַבְּכֹר נָדָב, כְּלוֹמַר, הַהוּא, דְּכָל שְׁבָחָא וִיקָרָא דִּלֵּיהּ (מה שמיה). נָדָב וַאֲבִיהוּא, עַל אַחַת כַּמָּה וְכַמָּה, דְּהָנֵי תְּרֵי, לָא אִשְׁתְּכָחוּ כְּוָתַיְיהוּ בְּיִשְׂרָאֵל."],[[0,"ר' אבא אמר וכו׳:","רא״א, עבדו את ה׳ ביראה. סוד הדבר הוא, עבדו את ה׳ ביראה, מה יראה כאן. כלומר מה פירושו של יראה שבכאן. ומשיב, אלא כמו שהעמדנו, שכתוב, \u0003יראת ה׳\u0004 ראשית דעת, וכן כתוב ראשית חכמה \u0003יראת ה׳,\u0004 שהקב״ה נקרא כך, יראת ה'. דהיינו המלכות. ר׳ אלעזר אמר, הוא מפרש דברי ר׳ אבא, עבדו את ה׳ ביראה, פירושו, מי שרוצה לעבוד עבודת רבונו, מאיזה מקום הוא מתחיל, ובאיזה מקום יכוון עבודתו ליחד שם רבונו. חוזר ואומר \u0003ביראה,\u0004 כי ביראה שהיא המלכות, הוא התחלת העבודה, ממטה למעלה. כי ספירה הראשונה ממטה למעלה היא מלכות."],[1,"ת״ח מה כתיב וכו׳:","בוא וראה, מה כתוב כאן, אחרי מות, ואח״כ דבר אל אהרן אחיך וגו' ב \u0003זאת\u0004 יבא אהרן, איזה קשר יש בין אחרי מות אל בזאת יבא אהרן. ומשיב, אלא מכאן, ממיתת בני אהרן, הוא התחלה להזהיר את הכהנים, את כל אחד, שצריכים להזהר ב \u0003זאת\u0004 הזו, שזו היא יראת ה'. שהיא המלכות. כי מיתת בני אהרן היתה משום שלא נזהרו במלכות."],[2,"דבר אחר אחרי וכו׳:","פירוש אחר. אחרי מות שני בני אהרן. ר׳ יוסי אמר, אחרי מות נדב ואביהוא, היה צריך לומר, מה הטעם שאומר שני בני אהרן, והרי ידוע שבניו היו. ומשיב, אלא כך למדנו, כי עד כאן לא היו עומדים ברשות עצמם, אלא ברשות אביהם. וע״כ קראם הכתוב בני אהרן, ומשום זה בקרבתם לפני ה׳ וימותו, שהיו דוחקים את השעה להקריב קטרת בחיי אביהם, כמ\"ש להלן (אות ס״ח) והכל היה, כלומר שעוד דברים היו שגרמו למיתתם, דהיינו גם, בשביל אותו עון שעשו, בהקריבם אש זרה. שלמדנו, במקום אחד כתוב בהקריבם אש זרה, שמשום זה מתו. ובמקום אחד כתוב, בקרבתם לפני ה׳, שמשום ההקרבה מתו, משום שדחקו את השעה להקטיר קטרת בחיי אביהם, כנ״ל. היינו משום שזה וזה היו גורמים מיתתם, ומשום זה כתוב כאן בני אהרן, ללמד שהיו ברשות אהרן כנ״ל. וכתוב בקרבתם. שהמיתה היה מטעם שקרבו לפני ה׳, בחיי אביהם."],[3,"א״ר חייא יומא וכו׳:","אר״ח, יום אחד הייתי הולך בדרך ללכת לר׳ שמעון, ללמוד ממנו פרשת הפסח. פגשתי הר אחד, וראיתי בקיעות וחורים בסלע אחד, ושני אנשים בו. בעוד שהייתי הולך, שמעתי קול אלו האנשים, שהיו אומרים שיר מזמור לבני קרח גדול ה׳ ומהלל מאד וגו'. מהו שיר מזמור. ומשיב, אלא כך למדנו משמו של ר׳ שמעון, שיר שהוא כפול, דהיינו שיר ומזמור, הוא משום שהוא שיר המשובח משאר שירים, ומשום שהוא משובח משאר שירים, נאמר בו ב׳ פעמים שיר. וכן מזמור שיר ליום השבת יורה שהוא משובח משאר השירים. וכעין זה, שיר השירים אשר לשלמה, שפרושו, שיר שהוא למעלה מכל שיר."],[4,"שיר מזמור:","אף כאן שנאמר שיר מזמור, הוא משובח על שאר השירים. שיר של הקב״ה, שבני קרח היו מזמרים על אלו שיושבים בפתחו של גיהנם. ומי הם בני קרח. הם אחיהם של אלו היושבים בפתחו של גיהנם. כמ״ש חז״ל, על הכתוב, ובני קרח לא מתו, שמקום נתבצר להם בגיהנם (מגילה י״ד.) וע״כ שיר זה נאמר ביום שני בבית המקדש. קרבתי אצלם. אמרתי להם, מה אתם עושים במקום הזה. אמרו סוחרים אנו, ושתי פעמים בשבוע, אנו נפרדים מן הישוב ואנו עוסקים בתורה. כי בישוב, מטרידים אותנו בכל יום ויום, בני אדם, ואינם נותנים לנו לעסוק בתורה. אמרתי להם אשרי חלקכם."],[5,"תו פתחו ואמרו וכו׳:","עוד פתחו ואמרו. בכל זמן שהצדיקים מסתלקים מן העולם, מסתלקים מן העולם הדינים, ומיתתם של הצדיקים מכפרת על עונות הדור. וע״כ פרשת בני אהרן, אנו קוראים ביום הכפורים, שתהיה כפרה לעונות ישראל. אמר הקב״ה, התעסקו במיתתם של צדיקים אלו, ויהיה נחשב לכם, כאלו אתם מקריבים קרבנות ביום הזה לכפר עליכם. שלמדנו, כל זמן שישראל יהיו בגלות, ולא יקריבו קרבנות ביום הזה, ולא יוכלו להקריב שני שעירים, יהיה להם זכרון של שני בני אהרן, ויכופר להם."],[6,"דהכי אוליפנא וכו׳:","כי כך למדנו, שכתוב, ואלה שמות בני אהרן הכהנים וגו'. וכתוב, הבכור נדב ואביהוא אלעזר ואיתמר. שואל, ואלעזר ואיתמר היה צריך לומר, כמו שאומר ואביהוא, מהו אלעזר ואיתמר. למה חסר \u0003ו'\u0004 החיבור באלעזר. ומשיב, אלא שקול היה אביהוא כשני אחיו. ושיעור הכתוב, ואביהוא כמו אלעזר ואיתמר. ונדב שקול כנגד כולם."],[7,"ואית דמתני וכו׳:","ויש שלומדים כך. הבכור נדב, הוא בפני עצמו, ואביהוא, הוא בפני עצמו. ואח״כ אלעזר ואיתמר נקראים כמחוברים יחד, ללמד, שכל אחד מנדב ואביהוא נחשב בעיני הכתוב, כשניהם, כאלעזר ואיתמר יחדיו. אבל נדב ואביהוא שניהם בפני עצמם, הם שקולים כנגד שבעים סנהדרין, שהיו משמשים לפני משה. ומשום זה, מיתתם מכפרת על ישראל. וע״כ כתוב, ואחיכם כל בית ישראל יבכו את השריפה. וא״ר שמעון, ע״כ מדייק הכתוב, הבכור נדב, כלומר, ההוא, שכל השבח והיקר שלו. נדב ואביהוא שניהם יחד, על אחת כמה וכמה, כי שנים אלו, לא היה נמצא בישראל כמוהם"]],[[0,"","רַבִּי אַבָּא אָמַר, עִבְדוּ אֶת ה' בְּיִרְאָה - סוֹד הַדָּבָר הוּא. עִבְדוּ אֶת ה' בְּיִרְאָה, אֵיזוֹ יִרְאָה כָּאן? אֶלָּא כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (משלי א) יִרְאַת ה' רֵאשִׁית דָּעַת, וְכָתוּב (תהלים קיא) רֵאשִׁית חָכְמָה יִרְאַת ה'. יִרְאַת ה' - כָּךְ נִקְרָא הַקָּדוֹשׁ בָּרוּךְ הוּא. רַבִּי אֶלְעָזָר אָמַר, עִבְדוּ אֶת ה' בְּיִרְאָה - מִי שֶׁרוֹצֶה לַעֲשׂוֹת עֲבוֹדַת אֲדוֹנוֹ, מֵאֵיזֶה מָקוֹם מַתְחִיל, וּבְאֵיזֶה מָקוֹם יְכַוֵּן אֶת הָעֲבוֹדָה לְיַחֵד אֶת שֵׁם רִבּוֹנוֹ? חָזַר וְאָמַר, בְּיִרְאָה. בְּיִרְאָה הִיא הָרֵאשִׁית, מִמַּטָּה לְמַעְלָה. (בא ראה, בני אהרן הרי בארנו, והרי נתבאר הדבר)."],[1,"","בֹּא רְאֵה, מַה כָּתוּב כָּאן אַחֲרֵי מוֹת, וְאַחַר כָּךְ - דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְגוֹ' בְּזֹּאת יָבא אַהֲרֹן? אֶלָּא מִכָּאן הָרֵאשִׁית לְהַזְהִיר אֶת הַכֹּהֲנִים, כָּל מִי שֶׁצְּרִיכִים לְהִזָּהֵר בְּזֹּאת הַזּוֹ, וְזוֹהִי יִרְאַת ה'."],[2,"","דָּבָר אַחֵר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן - רַבִּי יוֹסֵי אָמַר, אַחֲרֵי מוֹת נָדָב וַאֲבִיהוּא הָיָה צָרִיךְ לִהְיוֹת! מָה הַטַּעַם שְׁנֵי בְּנֵי אַהֲרֹן, וַהֲרֵי יָדוּעַ שֶׁהָיוּ בָנָיו? אֶלָּא כָּךְ שָׁנָה, שֶׁעַד כָּאן לֹא עָמְדוּ בִרְשׁוּתָם, אֶלָּא בִּרְשׁוּת אֲבִיהֶם, וּמִשּׁוּם כָּךְ - בְּקָרְבָתָם לִפְנֵי ה' וַיָּמֻתוּ, שֶׁהֵם דָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם, וְהַכֹּל הָיָה בִּשְׁבִיל אוֹתוֹ חֵטְא שֶׁעָשׂוּ, שֶׁכָּתוּב (במדבר ג) בְּהַקְרִיבָם אֵשׁ זָרָה. שֶׁשָּׁנִינוּ, בְּמָקוֹם אֶחָד כָּתוּב בְּהַקְרִיבָם אֵשׁ זָרָה, וּבְמָקוֹם אֶחָד כָּתוּב בְּקָרְבָתָם לִפְנֵי ה'. וְזֶה וְגַם זֶה הָיָה, וּמִשּׁוּם כָּךְ כָּתוּב בְּנֵי אַהֲרֹן, וְכָתוּב בְּקָרְבָתָם."],[3,"","אָמַר רַבִּי חִיָּיא, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ לָלֶכֶת אֶל רַבִּי שִׁמְעוֹן לִלְמֹד מִמֶּנּוּ פָּרָשַׁת הַפֶּסַח. פָּגַשְׁתִּי בְּהַר אֶחָד, וְרָאִיתִי בְקִיעִים וְחוֹרִים בְּסֶלַע אֶחָד וּשְׁנֵי אֲנָשִׁים בּוֹ. עַד שֶׁהָיִיתִי הוֹלֵךְ, שָׁמַעְתִּי קוֹל הָאֲנָשִׁים הַלָּלוּ שֶׁהָיוּ אוֹמְרִים, (תהלים מח) שִׁיר מִזְמוֹר לִבְנֵי קֹרַח גָּדוֹל ה' וּמְהֻלָּל מְאֹד וְגוֹ'. מַהוּ שִׁיר מִזְמוֹר? אֶלָּא כָּךְ שָׁנוּ מִשְּׁמוֹ שֶׁל רַבִּי שִׁמְעוֹן, שִׁיר שֶׁהוּא כָּפוּל, שִׁיר שֶׁהוּא מְשֻׁבָּח מִשְּׁאָר הַשִּׁירִים, וְעַל שֶׁהוּא מְשֻׁבָּח מִשְּׁאָר הַשִּׁירִים, פְּעָמִים נֶאֱמָר בּוֹ שִׁירָה, וְכֵן (שם צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת. כְּמוֹ כֵן שִׁיר הַשִּׁירִים אֲשֶׁר לִשְׁלֹמֹה, שִׁירָה לְמַעְלָה מִשִּׁירָה."],[4,"","שִׁיר מִזְמוֹר, שִׁירָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁמְּזַמְּרִים בְּנֵי קֹרַח (על) אוֹתָם שֶׁיּוֹשְׁבִים עַל פֶּתַח הַגֵּיהִנֹּם. וּמִי הֵם? אֲחֵיהֶם שֶׁהֵם שֶׁיּוֹשְׁבִים בְּשַׁעֲרֵי הַגֵּיהִנֹּם. וְעַל כֵּן הַשִּׁירָה הַזֹּאת נֶאֱמֶרֶת בְּיוֹם שֵׁנִי. קָרַבְתִּי אֲלֵיהֶם וְאָמַרְתִּי לָהֶם: מָה עִסְקֵיכֶם בַּמָּקוֹם הַזֶּה? אָמְרוּ: סוֹחֲרִים אֲנַחְנוּ, וּשְׁנֵי יָמִים בַּשָּׁבוּעַ אָנוּ בְּדֵלִים מֵהַיִּשּׁוּב וְעוֹסְקִים בַּתּוֹרָה, כִּי לֹא עוֹזְבִים אוֹתָנוּ בְּנֵי אָדָם כָּל יוֹם וָיוֹם. אָמַרְתִּי: אַשְׁרֵי חֶלְקְכֶם."],[5,"","עוֹד פָּתְחוּ וְאָמְרוּ, בְּכָל זְמַן שֶׁצַּדִּיקִים מִסְתַּלְּקִים מִן הָעוֹלָם, הַדִּין מִסְתַּלֵּק מִן הָעוֹלָם, וּמִיתַת הַצַּדִּיקִים מְכַפֶּרֶת עַל חֲטָאֵי הַדּוֹר. וְלָכֵן פָּרָשַׁת בְּנֵי אַהֲרֹן קוֹרְאִים אוֹתָהּ בְּיוֹם הַכִּפּוּרִים שֶׁתִּהְיֶה כַּפָּרָה עַל חֲטָאֵי יִשְׂרָאֵל. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הִתְעַסְּקוּ בְמִיתַת הַצַּדִּיקִים הַלָּלוּ, וְיֵחָשֵׁב לָכֶם כְּאִלּוּ אַתֶּם מַקְרִיבִים קָרְבָּנוֹת בַּיּוֹם הַזֶּה לְכַפֵּר עֲלֵיכֶם. שֶׁשָּׁנִינוּ, כָּל זְמַן שֶׁיִּשְׂרָאֵל יִהְיוּ בַגָּלוּת וְלֹא יַקְרִיבוּ קָרְבָּנוֹת בַּיּוֹם הַזֶּה, וְאֶת אוֹתָם שְׁנֵי שְׂעִירִים לֹא יְכוֹלִים לְהַקְרִיב, יִהְיֶה לָהֶם זִכָּרוֹן שֶׁל שְׁנֵי בְּנֵי אַהֲרֹן, וְיִתְכַּפֵּר עֲלֵיהֶם."],[6,"","שֶׁכָּךָ לָמַדְתִּי, שֶׁכָּתוּב (במדבר ג) וְאֵלֶּה שְׁמוֹת בְּנֵי אַהֲרֹן הַכֹּהֲנִים וְגוֹ'. וְכָתוּב, הַבְּכֹר נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר. וְאֶלְעָזָר וְאִיתָמָר הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶלְעָזָר וְאִיתָמָר? אֶלָּא שָׁקוּל הָיָה אֲבִיהוּא כִּשְׁנֵי אֶחָיו, וְנָדָב כְּמוֹ כֻלָּם."],[7,"","וְיִשִׁ שֶׁשּׁוֹנִים (אתזההפוך), הַבְּכֹר נָדָב - זֶה לְבַדּוֹ, וַאֲבִיהוּא - לְבַדּוֹ, וְכָל אֶחָד נֶחְשָׁב בְּעֵינָיו כִּשְׁנֵיהֶם, כְּמוֹ אֶלְעָזָר וְאִיתָמָר. אֲבָל נָדָב וַאֲבִיהוּא לְבַדָּם שְׁקוּלִים הָיוּ כְּנֶגֶד שִׁבְעִים סַנְהֶדְרִין, שֶׁהָיוּ מְשַׁמְּשִׁים לִפְנֵי מֹשֶׁה. וּמִשּׁוּם כָּךְ מִיתָתָם מְכַפֶּרֶת עַל יִשְׂרָאֵל. וְעַל זֶה כָּתוּב, (ויקרא י) וַאֲחֵיכֶם כָּל בֵּית יִשְׂרָאֵל יִבְכּוּ אֶת הַשְּׂרֵפָה. וְאָמַר רַבִּי שִׁמְעוֹן, הַבְּכֹר נָדָב - כְּלוֹמַר, אוֹתוֹ שֶׁכָּל הַשֶּׁבַח וְהַכָּבוֹד שֶׁלּוֹ (מה שמו). נָדָב וַאֲבִיהוּא, עַל אַחַת כַּמָּה וְכַמָּה, שֶׁשְּׁנֵי אֵלֶּה לֹא נִמְצְאוּ כְמוֹתָם בְּיִשְׂרָאֵל."]]],[["וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רִבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיהו כ״ט:כ״ב) לָכֵן כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם וְגוֹ'. הַאי קְרָא קַשְׁיָא, לָכֵן כֹּה אָמַר יְיָ' אֲשֶׁר פָדָה אֶת אַבְרָהָם מִבָּעֵי לֵיהּ. מַאי, כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם.","אֶלָּא הָא אוּקְמוּהָ וְהָא אִתְּמַר, דְּיַעֲקֹב פָדָה אֶת אַבְרָהָם וַדַּאי. דִּבְהַהִיא שַׁעֲתָא דְּנָפַל בְּגוֹ נוּרָא דְּכַשְׂדָּאֵי, דָּנוּ דִּינֵיהּ (ס\"י ואמרו קמי קודשא בריך הוא, בגין מאי ישתזיב האי, זכות אבהן לית ליה. אמר ליה, ישתזיב בגין בנוי, דהכי תניא, ברא מזכי אבא). אָמְרוּ, הָא יִשְׁמָעֵאל דְּנָפִיק מִנֵּיהּ. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, הָא יִצְחָק, דְּיוֹשִׁיט קְדָלֵיהּ עַל גַּבֵּי מַדְבְּחָא. אַמְרוּ, הָא עֵשָׂו דְּנָפִיק מִנֵּיהּ. אָמַר, הָא יַעֲקֹב, דְּאִיהוּ כּוּרְסְיָא שְׁלֵימָתָא, וְכָל בְּנוֹהִי שְׁלֵימִין קָמַאי. אַמְרוּ, הָא וַדַּאי בִּזְכוּתָא דָּא יִשְׁתְּזִיב אַבְרָהָם הֲדָא הוּא דִכְתִיב, אֲשֶׁר פָדָה אֶת אַבְרָהָם.","לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ כִּי בִרְאוֹתוֹ יְלָדָיו מַעֲשֵׂה יָדַי בְּקִרְבּוֹ יַקְדִּישׁוּ שְׁמִי. מַאן אִינּוּן יְלָדָיו מַעֲשֵׂה וְגוֹ'. אִלֵּין אִינּוּן, חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. דַּאֲפִּילוּ גַרְמַיְיהוּ לְגוֹ נוּרָא יָּקִידְתָא לְקָדָשָׁא שְׁמֵיהּ לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב מַאי בָּעֵי הָכָא יַעֲקֹב, וְהָא כְּתִיב, (דניאל א׳:ו׳) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיאֵל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. בְּנֵי יְהוּדָה אִקְרוּן, וּבְגִין כָּךְ לֹא עַתָּה יֵבוֹשׁ יְהוּדָה מִבָּעֵי לֵיהּ, מַאי לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב.","אֶלָּא הָכִי תָּנֵינָן. בְּהַאי שַׁעֲתָא דְּאִתְּכְפִיתוּ, לְמִנְפַּל בְּנוּרָא, כָּל חַד אָרִים קַלֵיהּ וְאָמַר, גַּבֵּי כָּל אִינּוּן עַמִּין וּמַלְכִין וְאָפַרְכַיָא, חֲנַנְיָה אָמַר, (תהילים קי״ח:ו׳-ז׳) יְיָ' לִי לֹא אִירָא מַה יַעֲשֶׂה לִי אָדָם יְיָ' לִי בְּעוֹזְרָי וַאֲנִי אֶרְאֶה בְּשוֹנְאָי טוֹב לַחֲסוֹת בַּיְיָ' וְגוֹ'. מִישָׁאֵל פָּתַח וְאָמַר, (ירמיהו ל׳:י׳) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם יְיָ' וְגוֹ' כִּי אִתְּךָ אֲנִי נְאֻם יְיָ' לְהוֹשִׁיעֶךָ כִּי אֶעֱשֶׂה וְגוֹ'. בְּהַהִיא שַׁעֲתָא, דְּשַׁמְעוּ כֻּלְּהוּ שְׁמָא דְּיַעֲקֹב. תַּוְוהוּ וְחַיְיכוּ בְּלֵצָנוּתָא. עֲזַרְיָה פָּתַח וְאָמַר, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל יְיָ' אֱלֹהֵינוּ יְיָ' אֶחָד.","הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ד:ה׳) זֶה יֹאמַר לַיְיָ' אָנִי וְגוֹ'. זֶה יֹאמַר לה' אָנִי, דָּא חֲנַנְיָה, וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב, דָּא מִישָׁאֵל, וְזֶה יִכְתּוֹב יָדוֹ לַיְיָ' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה, דָּא עֲזַרְיָה, בֵּיהּ שַׁעֲתָא כָּנַשׁ קוּדְשָׁא בְּרִיךְ הוּא פָּמַלְיָא דִּילֵיהּ, אָמַר לוֹן, בְּמַאן מִלָּה, מֵאִינּוּן מִלִּין דְּאָמְרוּ אִלֵּין תְּלָתָא, אַשְׁזִיב לוֹן. פָּתְחוּ וְאָמְרוּ, (תהילים פ״ג:י״ט) וְיֵדְעוּ כִּי אַתָּה שִׁמְךָ יְיָ' לְבַדֶּךָ עֶלְיוֹן עַל כָּל הָאָרֶץ.","בָּה שַׁעֲתָא אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְכוּרְסְיָיא, כּוּרְסְיָיא דִּילִי, בְּמַאן מִלָּה מֵאִינּוּן מִלִּין, אַשְׁזִיב לְאִינּוּן צַדִּיקַיָּיא. אָמַר לֵיהּ, בְּהַאי מִלָּה דְּכֻלְּהוּ חַיְּיכִין בָה, אַשְׁזִיב לוֹן, לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ. כְּמָה דְּקָאִים יַעֲקֹב לְגַבֵּי דְּאַבְרָהָם בְּנוּרָא, יְקוּם הַשְׁתָּא לְגַבֵּי אִלֵּין, הֲדָא הוּא דִכְתִיב, כֹּה אָמַר יְיָ' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְגוֹ'. מֵהַאי כִּסּוּפָא דְּלֵצָנוּתָא.","תָּנָא, כֻּלְּהוּ דַּהֲווֹ חַיְיכִין מִמִּלָּה דָּא, אִתּוֹקָדוּ בְּהַהוּא נוּרָא, וְקָטַל לוֹן שְׁבִיבָא דְּנוּרָא. מַאן שֵׁזִיב לְאִלֵּין. עַל דַּהֲווֹ מְצָלָן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא וּמְיַחֲדָן שְׁמֵיהּ כְּדְקָא יֵאוֹת, וְעַל דִּמְיַחֲדָן שְׁמֵיהּ כְּדְקָא יֵאוֹת, אִשְׁתֵּזִיבוּ מֵהַהוּא נוּרָא יָקִידְתָּא.","תְּרֵי בְּנֵי אַהֲרֹן קְרִיבוּ אֶשָּׁא נוּכְרָאָה, דְּלָא אִתְיַחֲדוּ שְׁמֵיהּ כְּדְקָא יֵאוֹת, וְאִתּוּקָדוּ בְּנוּרָא. רִבִּי יִצְחָק אָמַר, כְּתִיב, אַחֲרֵי מוֹת. וּכְתִיב וַיָמוּתוּ. כֵּיוָן דְּאָמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, לָא יְדַעְנָא, דְּהָא וַיָמוּתוּ. אֶלָּא הָכִי תָּנֵינָן, תְּרֵי מִיתוֹת הֲווֹ, חַד לִפְנֵי יְיָ'. וְחַד, דְּלָא הֲווֹ לְהוּ בְּנִין, דְּכָל מַאן דְּלָא זָכֵי לִבְנִין מִית הוּא. בְּגִין כַּךְ, אַחֲרֵי מוֹת, וַיָמוּתוּ.","רִבִּי אַבָּא אָמַר, מַאי דִּכְתִּיב, (במדבר ג׳:ד׳) וַיָּמָת נָדָב וַאֲבִיהוּא לִפְנֵי יְיָ' בְּהַקְרִיבָם אֵשׁ זָרָה לִפְנֵי יְיָ' בְּמִדְבַּר סִינַי וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. מַאי דָּא לְגַבֵּי דָּא, דִּכְתִּיב, וּבָנִים לֹא הָיוּ לָהֶם, וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. אֶלָּא רָזָא דְּמִלְתָּא. הַאי דַּאֲמֵינָא, וַיָמוּתוּ, דְּלָא הֲווֹ לְהוּ בְּנִין. וְהָכִי הוּא וַדַּאי. אֲבָל לָא כִּשְׁאָר בְּנֵי עָלְמָא, אַף עַל גַּב דְּלָא אַנְסִיבוּ, דְּהָא אִלֵּין לָא מִיתוּ אֶלָּא מִיתַת גַּרְמֵיהוֹן, אֲבָל מִיתַת נַפְשָׁהוֹן לָא מִיתוּ."],[[0,"וידבר וגו׳ אחרי מות שני בני אהרן:","רבי חזקיה פתח ואמר, לכן כה אמר ה׳ אל בית יעקב אשר פדה את אברהם וגו'. מקרא זה קשה, שהיה צריך לומר, לכן כה אמר ה׳ אשר פדה את אברהם, מהו, כה אמר ה׳ אל בית יעקב אשר פדה את אברהם."],[1,"אלא הא אוקמוה וכו׳:","אלא כבר העמידוהו וכבר למדנו, שיעקב פדה ודאי את אברהם. כי בשעה ההיא שאברהם נפל בכבשן האש של הכשדים, דנו דינו לפני הקב״ה, בזכות מה ינצל זה, זכות אבות אין לו. אמר הקב״ה לבית דין של מעלה, ינצל בשביל בניו. שהרי למדנו, בן מזכה את אביו. אמרו, הרי ישמעאל יצא ממנו. אמר הקב״ה, הרי יצחק יצא ממנו, שיושיט צוארו לשחיטה על המזבח. אמרו, הרי עשו יצא מיצחק. אמר הקב״ה, הרי יעקב יצא ממנו, שהוא כסא שלם, וכל בניו שלמים לפני. אמרו, הרי ודאי בזכות זה ינצל אברהם. ז״ש, אשר פדה את אברהם."],[2,"לא עתה יבוש וגו':","כתוב, לא עתה יבוש יעקב ולא עתה פניו יחורו כי בראותו ילדיו מעשה ידי בקרבו יקדישו שמי. שואל, מי הם, ילדיו מעשה ידי וגו'. ומשיב, אלו הם, חנניה מישאל ועזריה שהפילו עצמם לתוך אש שורפת כדי לקדש שמי. שואל, \u0003לא עתה יבוש יעקב,\u0004 יעקב מה רוצה כאן, שהרי כתוב, ויהי בהם מבני יהודה דניאל וחנניה ומישאל ועזריה. הרי שבני יהודה נקראים, וע״כ היה צריך לומר, לא עתה יבוש יהודה, מהו לא עתה יבוש יעקב."],[3,"אלא הכי תנינן וכו׳:","ומשיב, אלא כך למדנו. באותה שעה שקשרו את חנניה מישאל ועזריה, להפילם באש, כל אחד הרים קולו ואמר, לפני כל אלו העמים והמלכים והשרים, חנניה אמר, ה׳ לי לא אירא מה יעשה לי אדם ה׳ לי בעוזרי ואני אראה בשונאי, טוב לחסות בה׳ וגו'. מישאל פתח ואמר, ואתה אל תירא עבדי \u0003יעקב\u0004 נאם ה׳ וגו' כי אתך אני נאם ה׳ להושיעך כי אעשה וגו'. באותה שעה ששמעו העמים והשרים את השם יעקב, תמהו וצחקו בליצנות, על ששם בטחונו ביעקב. עזריה פתח ואמר, שמע ישראל ה׳ אלקינו ה׳ אחד."],[4,"הה״ד זה יאמר וכו׳:","ז״ש, זה יאמר לה׳ אני וגו'. זה יאמר לה׳ אני, זהו חנניה, שאמר ה׳ לי וגו'. זה יקרא בשם יעקב, זהו מישאל, שאמר אל תירא עבדי יעקב, וזה יכתוב ידו לה׳ ובשם ישראל יכנה זהו עזריה, שאמר שמע ישראל ה׳ וגו'. בה בשעה קבץ הקב״ה את הפמליא שלו, דהיינו המלאכים, אמר להם, באיזה מלה, מאלו המלים שאמרו אלו השלשה, אצילם. פתחו ואמרו, וידעו כי אתה שמך ה׳ לבדך עליון על כל הארץ. דהיינו שיצילם משום שבטחו בה'."],[5,"בה שעתא אמר קכ״ה וכו׳:","באותה השעה אמר הקב״ה אל הכסא, שהוא המלכות: כסא שלי, באיזה מלה מאלו המלים שאמרו, אציל אלו הצדיקים. אמר לו, במלה ההיא שכולם צחקו ממנה, אצילם, דהיינו בזכות יעקב, לא עתה יבוש יעקב ולא עתה פניו יחורו. כי יראו שנצלו בזכותו. כמו שעמדה זכותו של יעקב לאברהם באש, (כנ״ל אות י״ג) תעמוד עתה לאלו, לחנניה מישאל ועזריה, ז״ש, כה אמר ה׳ אל בית יעקב אשר פדה את אברהם לא עתה יבוש יעקב וגו', דהיינו מהבזיון הזה של הלצנות שהעמים והשרים התלוצצו עליו (כנ״ל אות ט״ו)."],[6,"תנא כלהו דהוו וכו׳:","למדנו, כולם שהיו צוחקים ממלה זו, דהיינו מיעקב, נשרפו באש ההוא, ושביב אש הרג אותם. מי הציל את אלו. הוא, משום שהיו מתפללים לפני הקב״ה ומיחדים שמו כראוי, ועל שייחדו שמו כראוי, נצולו מאש שורפת ההיא."],[7,"תרי בני אהרן וכו׳:","שני בני אהרן הקריבו אש זרה, שלא ייחדו שמו כראוי ונשרפו באש. ר׳ יצחק אמר, כתוב, אחרי מות. וכתוב וימותו. בפסוק אחד, כיון שאמר אחרי מות שני בני אהרן, איני יודע, כי וימותו. ומשיב, אלא כך למדנו, שתי מיתות היו, אחת לפני ה'. ואחת, שלא היו להם בנים, שכל מי שאינו זוכה לבנים נחשב כמת. משום זה כתוב, אחרי מות, וימותו. שאחרי מות, הוא כפשוטו. וימותו, היינו מחמת שלא היו להם בנים."],[8,"רבי אבא אמר וכו׳:","רא״א, מה שכתוב, וימת נדב ואביהוא לפני ה', בהקריבם אש זרה לפני ה׳ במדבר סיני ובנים לא היו להם ויכהן אלעזר ואיתמר. שואל, מה זה אל זה, שכתוב ובנים לא היו להם, ויכהן אלעזר ואיתמר. וכי הם ירשו הכהונה מנדב ואביהוא, משום שלא היו להם בנים. ומשיב אלא סוד הדבר הוא, כי זה שאמרתי, אשר וימותו הוא, שלא היו להם בנים. ונחשבו מתים, כך הוא ודאי. אבל לא כשאר בני העולם, אע״פ שלא נשאו אשה, כי אלו לא מתו אלא מיתת גופם, אבל מיתת נפשם לא מתו."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. רַבִּי חִזְקִיָּה פָּתַח וְאָמַר, (ישעיה כט) לָכֵן כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם וְגוֹ'. פָּסוּק זֶה הוּא קָשֶׁה. לָכֵן כֹּה אָמַר ה' אֲשֶׁר פָּדָה אֶת אַבְרָהָם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם?"],[1,"","אֶלָּא הֲרֵי פֵּרְשׁוּהָ וַהֲרֵי נִתְבָּאֵר, שֶׁיַּעֲקֹב פָּדָה אֶת אַבְרָהָם וַדַּאי. שֶׁבְּאוֹתָהּ הַשָּׁעָה שֶׁנָּפַל בְּתוֹךְ אֵשׁ הַכַּשְׂדִּים, דָּנוּ דִינוֹ (ס\"י ואמרו לפני הקדוש ברוך הוא', בשביל מה זה ינצל, ' זכות אבות אין לו, אמר להם, שינצל בשביל בניו, שכך שנינו, הבן מזכה את האב). אָמְרוּ: הֲרֵי יִשְׁמָעֵאל שֶׁיֵּצֵא מִמֶּנּוּ. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הֲרֵי יִצְחָק שֶׁיּוֹשִׁיט צַוָּארוֹ עַל גַּבֵּי הַמִּזְבֵּחַ. אָמְרוּ: הֲרֵי עֵשָׂו שֶׁיֵּצֵא מִמֶּנּוּ. אָמַר: הֲרֵי יַעֲקֹב שֶׁהוּא כִּסֵּא שָׁלֵם וְכָל בָּנָיו שְׁלֵמִים לְפָנַי. אָמְרוּ: הֲרֵי וַדַּאי בִּזְכוּתוֹ שֶׁל זֶה יִנָּצֵל אַבְרָהָם. זֶהוּ שֶׁכָּתוּב, אֲשֶׁר פָּדָה אֶת אַבְרָהָם."],[2,"","לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ כִּי בִרְאוֹתוֹ יְלָדָיו מַעֲשֵׂה יָדַי בְּקִרְבּוֹ יַקְדִּישׁוּ שְׁמִי. מִי הֵם יְלָדָיו מַעֲשֵׂה וְגוֹ'? אֶלָּא הֵם חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה שֶׁהִפִּילוּ עַצְמָם לְתוֹךְ כִּבְשַׁן הָאֵשׁ לְקַדֵּשׁ אֶת שְׁמוֹ. לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב, מָה עוֹשֶׂה כָּאן יַעֲקֹב? וַהֲרֵי כָּתוּב (דניאל א) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיֵּאל חֲנַנְיָה מִישָׁאֵל וַעֲזַרְיָה. בְּנֵי יְהוּדָה נִקְרְאוּ, וּמִשּׁוּם כָּךְ לֹא עַתָּה יֵבוֹשׁ יְהוּדָה הָיָה צָרִיךְ לִהְיוֹת, מַה זֶּה לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב?"],[3,"","אֶלָּא כָּךְ שָׁנִינוּ, בְּשָׁעָה הַזּוֹ שֶׁנִּכְפְּתוּ לִפֹּל בָּאֵשׁ, כָּל אֶחָד הֵרִים קוֹלוֹ וְאָמַר אֶל כָּל אוֹתָם עַמִּים וּמְלָכִים וְשָׂרִים. חֲנַנְיָה אָמַר, (תהלים קיח) ה' לִי לֹא אִירָא מַה יַּעֲשֶׂה לִי אָדָם ה' לִי בְּעֹזְרָי וַאֲנִי אֶרְאֶה בְשׂנְאָי טוֹב לַחֲסוֹת בַּה' וְגוֹ'. מִישָׁאֵל פָּתַח וְאָמַר, (ירמיה ל) וְאַתָּה אַל תִּירָא עַבְדִּי יַעֲקֹב נְאֻם ה' וְגוֹ' כִּי אִתְּךְ אֲנִי נְאֻם ה' לְהוֹשִׁיעֶךְ כִּי אֶעֱשֶׂה וְגוֹ'. בְּאוֹתָהּ שָׁעָה שֶׁשָּׁמְעוּ כֻלָּם אֶת שֵׁם יַעֲקֹב, תָּמְהוּ וְצָחֲקוּ בְּלֵיצָנוּת. עֲזַרְיָה פָּתַח וְאָמַר, (דברים ו) שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד."],[4,"","זְהִוּ שֶׁכָּתוּב, (ישעיה מד) זֶה יֹאמַר לַה' אָנִי וְגוֹ'. זֶה יֹאמַר לַה' אָנִי - זֶה חֲנַנְיָה. וְזֶה יִקְרָא בְשֵׁם יַעֲקֹב - זֶה מִישָׁאֵל. וְזֶה יִכְתֹּב יָדוֹ לַה' וּבְשֵׁם יִשְׂרָאֵל יְכַנֶּה - זֶה עֲזַרְיָה. בְּאוֹתָהּ שָׁעָה כִּנֵּס הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַפָּמַלְיָא שֶׁלּוֹ, וְאָמַר לָהֶם: בְּאֵיזֶה דִבּוּר מֵאוֹתָם הַדִּבּוּרִים שֶׁאָמְרוּ אֵלֶּה הַשְּׁלֹשָׁה אַצִּיל אוֹתָם? פָּתְחוּ וְאָמְרוּ, (תהלים סג) וְיֵדְעוּ כִּי אַתָּה שִׁמְךְ ה' לְבַדֶּךְ עֶלְיוֹן עַל כָּל הָאָרֶץ."],[5,"","בְּאוֹתָהּ שָׁעָה אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לַכִּסֵּא: כִּסֵּא שֶׁלִּי, בְּאֵיזֶה דִבּוּר מֵאוֹתָם הַדִּבּוּרִים אַצִּיל אֶת אוֹתָם הַצַּדִּיקִים? אָמַר לוֹ: בְּאוֹתוֹ הַדִּבּוּר שֶׁכֻּלָּם צָחֲקוּ עָלָיו אַצִּיל אוֹתָם, לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחֱוָרוּ. כְּמוֹ שֶׁעָמַד יַעֲקֹב אֵצֶל אַבְרָהָם בָּאֵשׁ, יָקוּם עַכְשָׁו אֵצֶל אֵלֶּה. זֶהוּ שֶׁכָּתוּב, כֹּה אָמַר ה' אֶל בֵּית יַעֲקֹב אֲשֶׁר פָּדָה אֶת אַבְרָהָם לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְגוֹ'. מֵהַבּוּשָׁה שֶׁל הַלֵּיצָנוּת."],[6,"","שָׁנִינוּ, כָּל אוֹתָם שֶׁצָּחֲקוּ מֵהַדִּבּוּר הַזֶּה, נִשְׂרְפוּ בְּאוֹתָהּ אֵשׁ, וְהָרַג אוֹתָם שְׁבִיב שֶׁל אֵשׁ. מַה הִצִּיל אֶת אֵלֶּה? עַל שֶׁהָיוּ מִתְפַּלְלִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמְיַחֲדִים שְׁמוֹ כָּרָאוּי, וְעַל שֶׁמְּיַחֲדִים שְׁמוֹ כָּרָאוּי, נִצְּלוּ מֵאוֹתָהּ אֵשׁ יוֹקֶדֶת."],[7,"","שְׁנֵי בְּנֵי אַהֲרֹן הִקְרִיבוּ אֵשׁ זָרָה, שֶׁלֹּא יִחֲדוּ אֶל שְׁמוֹ כָּרָאוּי וְנִשְׂרְפוּ בָאֵשׁ. רַבִּי יִצְחָק אָמַר, כָּתוּב אַחֲרֵי מוֹת, וְכָתוּב וַיָּמֻתוּ. כֵּיוָן שֶׁאָמַר אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, לֹא יָדַעְנוּ שֶׁהֲרֵי וַיָּמֻתוּ? אֶלָּא כָּךְ שָׁנִינוּ, שְׁתֵּי מִיתוֹת הָיוּ, אַחַת לִפְנֵי ה', וְאַחַת שֶׁלֹּא הָיוּ לָהֶם בָּנִים. שֶׁכָּל מִי שֶׁלֹּא זוֹכֶה לְבָנִים, הוּא מֵת. מִשּׁוּם כָּךְ, אַחֲרֵי מוֹת, וַיָּמֻתוּ."],[8,"","רַבִּי אַבָּא אָמַר, מַה שֶּׁכָּתוּב (במדבר ג) וַיָּמָת נָדָב וַאֲבִיהוּא לִפְנֵי ה' בְּהַקְרִבָם אֵשׁ זָרָה לִפְנֵי ה' בְּמִדְבַּר סִינַי וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר. מַה זֶּה לְגַבֵּי זֶה, שֶׁכָּתוּב וּבָנִים לֹא הָיוּ לָהֶם וַיְכַהֵן אֶלְעָזָר וְאִיתָמָר? אֶלָּא סוֹד הַדָּבָר - זֶה שֶׁאָמַרְתִּי, וַיָּמֻתוּ, שֶׁלֹּא הָיוּ לָהֶם בָּנִים. וְכָךְ זֶה וַדַּאי. אֲבָל לֹא כִּשְׁאָר בְּנֵי הָעוֹלָם, אַף עַל גַּב שֶׁלֹּא נִשְּׂאוּ, שֶׁהֲרֵי אֵלּוּ לֹא מֵתוּ אֶלָּא מִיתַת עַצְמָם, אֲבָל מִיתַת נַפְשָׁם לֹא מֵתוּ."]]],[["מְנָא לָן, דִּכְתִּיב, (שמות ו׳:כ״ה) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּנְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם לְמִשְׁפְּחוֹתָם. אֵלֶּה, וְהָא פִּנְחָס בִּלְחוֹדוֹי הֲוָה. וּכְתִיב, רָאשֵׁי אֲבוֹת הַלְוִיִּם, בְּגִין כָּךְ, מִיתַת גַּרְמֵיהוֹן מִיתוּ, מִיתַת נַפְשָׁהוֹן לָא מִיתוּ. אָמַר רִבִּי אֶלְעָזָר וַדַּאי מַשְׁמַע אֵלֶּה, וּמַשְׁמַע רָאשֵׁי.","וּבְגִין כָּךְ כְּתִיב, (במדבר כ״ה:ז׳) פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וּכְתִיב וּפִנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הָיָה כֹּהֵן בַּיָמִים הָהֵם, פִּנְחָס בֶּן אֶלְעָזָר הַכֹּהֵן מִבָּעֵי לֵיהּ, אֶלָּא בְּכָל אֲתַר דְּאָתָא פִּנְחָס בֶּן אַהֲרֹן הַכֹּהֵן כְּתִיב, וְאֶלְעָזָר לָא כְּתִיב אֶלָּא אֶלְעָזָר הַכֹּהֵן. דִּכְתִּיב, (במדבר כ״ז:ב׳) וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן. (במדבר ל״א:כ״א) וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן וְגוֹ'. וְעַל דָּא מִיתַת גַּרְמֵיהוֹן מִיתוּ, מִיתַת נַפְשָׁהוֹן לָא מִיתוּ.","וְתָנֵינָן בְּרָזָא דְּמַתְנִיתִין, תְּרֵי זוּג, פֶּן חָס. וְהָא אִתְּמַר, יוֹ\"ד זְעֵירָא בֵּינֵי אַתְוָון דְּפִנְחָס. דְּהַאי יוֹ\"ד כָּלִיל תְּרֵי כַּחֲדָא, וְדָא הוּא רָזָא דְּמִלָּה, וְהָא אִתְּמַר.","רִבִּי אֶלְעָזָר שָׁאִיל לַאֲבוּי, אָמַר לֵיהּ, וְהָא תְּרֵי אִינּוּן וּתְרֵי הֲווֹ, אֲמַאי לָא אִשְׁתְּכָחוּ תְּרֵי. אָמַר לֵיהּ, תְּרֵי פַּלְגֵּי גּוּפָא הֲווֹ, דְּהָא לָא אַנְסִיבוּ, וּבְגִין כָּךְ, בְּחַד אִתְכְּלִילוּ, דִּכְתִּיב, וַתֵּלֶד לוֹ אֶת פִּנְחָס אֵלֶּה רָאשֵׁי וְגוֹ'.","וְיוֹ\"ד דְּפִנְחָס, לָא אִתְיְיהִיב בֵּיהּ לְחַבְּרָא אַתְוָון, אֶלָּא בְּשַׁעֲתָא דְּקַנֵּי לְּקוּדְשָׁא בְּרִיךְ הוּא, וְאָתָא לְיַשְּׁרָא עֲקִימָא, דְּחָמָא דְּהַאי אָת בְּרִית קַדִּישָׁא, עָיֵיל זִמְרִי בִּרְשׁוּתָא אָחֳרָא. וּבְמָּה דְּאִתְעַקָּם בְּקַדְמִיתָא, אִתְתָּקַן הָכָא. בְּנוּכְרָאָה אִתְעַקָּם בְּקַדְמִיתָא, דִּכְתִּיב, בְּהַקְרִיבָם אֵשׁ זָרָה, הָכָא בְּנוּכְרָאָה, אִתְתָּקַן, כְּמָה דִּכְתִיב, (מלאכי ב׳:י״א) וּבָעַל בַּת אֵל נֵכָר. מַה לְהַלָּן אֵשׁ זָרָה, אַף כָּאן נָמֵי אִשָׁה זָרָה.","מַאי אִתְחֲזֵי הָכָא. אֶלָּא בְּקַדְמִיתָא רְחִיקָא קְרִיבוּ, דִּכְתִּיב, בְּהַקְרִיבָם אֵשׁ זָרָה. אוּף הָכָא זִמְרִי, הֲוָה קָרִיב רְחִיקָא, שְׁמָא דְּמַלְכָּא, הֲוָה קָרִיב גַּבֵּי רְחִיקָא, מִיַּד, (במדבר כ״ה:ז׳) וַיַרְא פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וַיָּקָם מִתּוֹךְ הָעֵדָה. הָכָא אַתְקִין עֲקִימָא דְּקַדְמֵיתָא, כְּדֵין אִתְיְיהִיב יוֹ\"ד בִּשְׁמֵיהּ לְחַבְּרָא אַתְוָון כַּחֲדָא, וְאִתְבְּשַׂר בְּשָׁלוֹם, דִּכְתִּיב, (במדבר כ״ה:י״ב) לָכֵן אֱמוֹר הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. (בריתי ממש).","(נח ס\"ו ע\"ב) מַאי שָׁלוֹם הָכָא, אֶלָּא בְּהַהוּא כִּתְרָא, חָבוּ בְּקַדְמִיתָא, בְּהַהוּא כִּתְרָא, אַתְּעֲרוּ קְטָטוּתָא בְּקַדְמִיתָא, וְהַשְׁתָּא דְּאִתְתְּקַן, כְּתִיב הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. בְּרִיתִי מַמָּשׁ, תְּהֵא עִמֵּיהּ בְּשָׁלוֹם, וּבְגִין כַּךְ, אִתְיְיהִיב יוֹ\"ד זְעֵירָא בִּשְׁמֵיהּ, דְּהָא מֵאַתְוָון זְעִירָאן הִיא, לְאַתְחֲזָאָה דְּהָא אִתְתָּקַּן מַה דְּאִתְעַקָּם בְּקַדְמִיתָא, וְהָא אַשְׁלִימַת עִמֵּיהּ. אָתָא רִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי. אָמַר, בְּרִיךְ רַחֲמָנָא דְּשָׁאִילְנָא הַאי מִלָּה, וְלָא אִתְאֲבִיד מִנַּאי.","תָּאנָא אָמַר רִבִּי יוֹסֵי, בְּהַאי יוֹמָא דְּכִפּוּרֵי, אִתְתְּקַּן לְמִקְרֵי פַּרְשְׁתָּא דָּא, לְכַפְּרָא לְיִשְׂרָאֵל בְּגָלוּתָא, בְּגִין דָּא, סִדְרָא דְּיוֹמָא דָּא, הָכָא אִתְסָדַּר, וּבְגִין דְּמִיתַתְהוֹן דִּבְנֵי אַהֲרֹן, מְכַפְּרָא עַל יִשְׂרָאֵל.","מִכָּאן אוֹלִיפְנָא, כָּל הַהוּא בַּר נָשׁ דְּיִסּוּרֵי דְּמָארֵיהּ אַתְיָין עָלֵיהּ, כַּפָּרָה דְּחוֹבוֹי אִינּוּן. וְכָל מַאן דְּמִצְטָעַר עַל יִסּוּרֵיהוֹן דְּצַדִּיקַיָּא, מַעֲבִירִין חוֹבַיָּיא דִּלְהוֹן מֵעָלְמָא. וְעַל דָּא בְּיוֹמָא דָּא, קוֹרִין, אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, דְּיִשְׁמְעוּן עַמָּא, וְיִצְטַעֲרוּן עַל אֲבוּדְהוֹן דְּצַדִּיקַיָּא, וְיִתְכַּפֵּר לְהוֹן חוֹבַיְיהוּ. וְכָל דְּמִצְטָעַר עַל אֲבוּדְהוֹן דְּצַדִּיקַיָּא, אוֹ אָחִית דִּמְעִין עָלַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא מַכְרִיז עָלֵיהּ וְאוֹמֵר, (ישעיהו ו׳:ז׳) וְסָר עֲוֹנֶךָ וְחַטָּאתְךָ תְּכוּפָּר. וְלֹא עוֹד, אֶלָּא דְּלָא יְמוּתוּן בְּנוֹי בְּיוֹמוֹי. וְעָלֵיהּ כְּתִיב, (ישעיהו נ״ג:י׳) יִרְאֶה זֶרַע יַאֲרִיךָ יָמִים וְגוֹ'.","(ויקרא ט״ז:ב׳) וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ' רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא וְגוֹ'. אָמַר רִבִּי שִׁמְעוֹן, תַּוַּוהְנָא עַל בְּנֵי עָלְמָא, דְּהָא לֵית לְהוּ עַיְינִין לְמֵחֱזֵי, וְלִבָּא לְאַשְׁגְחָא, וְלָא יַדְעִין, וְלָא שַׁוְיָין לִבַּיְיהוּ לְאִסְתַּכְּלָא בִּרְעוּתָא דְמָאָרֵיהוֹן, הֵיךְ נַיְימִין, וְלָא מִתְעָרֵי מִשֵׁנָתַיְיהוּ, עַד לָא יֵיתֵי הַהוּא יוֹמָא דְּחָפֵי עָלַיְיהוּ חֲשׁוֹכָא וְקַבְלָא, וְיִתְבַּע הַהוּא מָארֵיהּ דְּפִקְדוֹנָא, חוּשְׁבָּנָא מִנַּיְיהוּ."],[[0,"מנ״ל דכתיב וכו׳:","מאין לנו זה, שלא מתו מיתת הנפש, שכתוב, ואלעזר בן אהרן לקח לו מבנות פוטיאל לו לאשה ותלד לו את פנחס אלה ראשי אבות וגו'. שואל אומר \u0003אלה,\u0004 והרי פנחס בלבדו היה. וכתוב, \u0003ראשי\u0004 אבות הלוים, על פנחס בלבדו. שהוא משום שנדב ואביהוא נתגלגלו בפנחס (כמ\"ש להלן פנחס דף רי״ז. ד״י) ע״כ אוה\"כ עליו אלה ראשי אבות, לשון רבים. לפי זה, מיתת גופם מתו, ומיתת נפשם לא מתו. כי נתגלגלו בפנחס. א״ר אלעזר ודאי הוא כך, וזה משמע משכתוב עליו \u0003אלה,\u0004 שהוא לשון רבים. ומשמע משכתוב עליו \u0003ראשי,\u0004 לשון רבים."],[1,"ובגין כך כתיב וכו׳:","ומשום זה כתוב, פנחס בן אלעזר בן אהרן הכהן. וכתוב, ופנחס בן אלעזר בן אהרן הכהן היה כהן בימים ההם, שהיה צריך לומר פנחס בן אלעזר הכהן, ולמה מזכיר, בן אהרן הכהן. אלא בכל מקום שמזכיר פנחס כתוב בו, בן אהרן הכהן, ואצל אלעזר לא כתוב אלא אלעזר הכהן, ולא נזכר בן אהרן. שכתוב, ולפני אלעזר הכהן. ויאמר אלעזר הכהן וגו'. שהוא מטעם שנדב ואביהוא בני אהרן נתגלגלו בפנחס, ע״כ מזכיר עליו הכתוב בן אהרן. וע״כ מיתת גופם מתו, ומיתת נפשם לא מתו. כי נתגלגלו בפנחס."],[2,"ותנינן ברזא דמתניתין וכו׳:","ולמדנו בסוד המשנה, שבשם פנחס יש שני שמות, שהם זוג, \u0003פן חס.\u0004 והרי נאמר \u0003י׳\u0004 קטנה בין האותיות דפנחס, כזה, פינחס, כי \u0003י'\u0004 זו כוללת שנים יחד, וזה הוא סוד הדבר, וכבר למדנו. פירוש, \u0003פן חס,\u0004 הם כנגד נדב ואביהוא. וה \u0003י׳\u0004 מתקנת אותם ומחבר אותם כאחד. כמ״ש לפנינו. (באות כ״ו)."],[3,"ר' אלעזר שאיל וכו׳:","ר״א שאל את אביו, אמר לו, והרי נדב ואביהוא שנים הם ושנים היו, למה אינם נמצאים שנים. כלומר למה לא נתגלגלו בב' אנשים, אלא בפנחס בלבד. אמר לו, שני חצאי גוף היו, שהרי לא נשאו אשה, ומי שלא נשא אשה הוא פלג גופא, ומשום זה נכללו שניהם באחד, שכתוב, ותלד לו את פנחס אלה ראשי וגו'. (כנ״ל אות כ״א)."],[4,"ויוד דפנחס וכו׳:","וה \u0003י׳\u0004 של פינחס, (כנ״ל אות כ״ג) לא ניתנה בו לחבר האותיות, אלא בשעה שקנא להקב״ה, ובא לישר העקום, שראה את אות ברית קדש שהכניס זמרי ברשות אחר. ובמה שנדב ואביהוא נתעקמו בתחילה, נתתקנו כאן, כי בנכריה נתעקמו, נדב ואביהוא בתחילה, שכתוב, בהקריבם אש זרה, וכאן בנכריה, שהרגה פנחס, נתתקנו. כמ״ש, ובעל בת אל נכר. ומה להלן אש זרה, אף כאן אשה זרה."],[5,"מאי אתחזי הכא וכו׳:","שואל, מה נראה כאן. כלומר מה ענין אש זרה לאשה זרה. ומשיב, אלא בתחילה הקריבו אל הקדושה הרחוקה מקדושה, ופגמו בקדושה, שכתוב, בהקריבם אש זרה. אף כאן זמרי עשה אותו החטא, שהיה מקרב הרחוק מקדושה, דהיינו אשה זרה, אל הקדושה, כי שם המלך, דהיינו אות ברית קודש, היה מקרב אל הרחוק, אל האשה הזרה, מיד, וירא פנחס בן אלעזר בן אהרן הכהן ויקם מתוך העדה. כאן התקין את העקום שמתחילה, אז ניתנה \u0003י׳\u0004 בשמו לחבר האותיות יחד, שה״ס יסוד המחבר ז״א ומלכות, ונתבשר בשלום, שהוא יסוד הנקרא שלום, שכתוב, לכן אמור לו הנני נותן לו את בריתי שלום. בריתי ממש, דהיינו יסוד."],[5,"","פירוש. השם פנחס כולל ב׳ שמות, \u0003פן חס,\u0004 כנ״ל. שהם רומזים על מלכות הנקראת \u0003פן,\u0004 וז״א שנקרא \u0003חס,\u0004 שהוא לשון רחמים. אשר נדב נתגלגל בחצי השם \u0003חס\u0004 שהוא ז״א, ואביהוא נתגלגל בחצי השם \u0003פן\u0004 שהוא מלכות. ופגם של נדב ואביהוא היה ביסוד, שהקריבו אש זרה שהיא קליפה אל יסוד דקדושה. וע״כ נפרדו האותיות \u0003פן חס,\u0004 שלא היו להם זווג כי היסוד נתעקם מכח אש זרה. וכן חטא זמרי היה שבעל בת אל נכר והכניס יסוד דקדושה בקליפה, שעי״ז פגם ביסוד ונתעקם היסוד. ובעת שפנחס הרג את זמרי, כדי לתקן היסוד שנתעקם בחטא זמרי, נמצא שגם החטא של נדב ואביהוא שהיו מגולגלים בו נתקן, ואז נתוסף לו \u0003י'\u0004 בשמו בסוד \u0003פינחס,\u0004 שה״ס היסוד שנתקן, שז״ס הנני נותן לו את בריתי שלום, שה״ס היסוד השלם. וז״ש, \u0003כדין אתייהיב יוד בשמיה לחברא אתוון\u0004 שז״א ומלכות, שהם סוד האותיות \u0003פן חס,\u0004 חזרו ונתחברו ע״י ה \u0003י׳\u0004 שה״ס היסוד."],[6,"מאי שלום הכא וכו׳:","שואל, מהו שלום כאן, שנאמר לו הנני נותן לו את בריתי שלום, ומשיב, אלא בספירה הזו, שהיא יסוד, חטאו בתחילה, בהקריבם אש זרה כנ״ל בדיבור הסמוך, בספירה ההיא, שהיא יסוד, פגמו ועוררו מריבה בתחילה, בין ז״א למלכות, כנ״ל בסמוך, ועתה שנתתקן, כתוב, הנני נותן לו בריתי שלום, בריתי ממש, דהיינו ספירת היסוד שנקראת ברית, תהיה עמו בשלום, דהיינו השלום בין ז״א למלכות, ומשום זה ניתנה \u0003י׳\u0004 קטנה בשמו, הרומזת על היסוד, שהוא מאותיות קטנות, להראות שכבר נתקן מה שנתעקם מתחילה, דהיינו היסוד שנתעקם חזר ונתיישר, כנ״ל בסמוך, וכבר נשלמה המלכות עם היסוד. בא ר׳ אלעזר ונשק ידיו. אמר, ברוך הרחמן ששאלתי דבר זה, ולא נאבד ממני."],[7,"תאנא א״ר יוסי וכו׳:","למדנו אר״י, ביום הזה של יום הכפורים נתתקן לקרות פרשה זו, של בני אהרן, לכפר על ישראל בגלות, שאין להם קרבנות, ומשום זה, סדר הקרבנות של יום זה יוה״כ, נסתדר כאן, בפרשת בני אהרן, והקריאה בהם היא במקום הקרבנות. ועוד, משום שמיתתם של בני אהרן מכפרת על ישראל."],[8,"מכאן אוליפנא כל וכו׳:","מכאן למדנו, שכל אדם שבאים עליו יסורים מרבונו, הם כפרת עונות. וכל מי שמצטער על יסורים של הצדיקים מעבירים עונותיהם מן העולם. וע״כ ביום הזה, יוה״כ, קוראים, אחרי מות שני בני אהרן, כדי שישמעו העם ויצטערו על הצדיקים שנאבדו, ויתכפרו להם עונותיהם. כי כל המצטער על צדיקים שנאבדו, או מוריד דמעות עליהם, הקב״ה מכריז עליו ואומר, וסר עונך וחטאתך תכופר. ולא עוד, אלא שלא ימותו בניו בימיו. ועליו כתוב, יראה זרע יאריך ימים וגו'."],[9,"ויאמר ה׳ אל וגו׳:","ויאמר ה' אל משה דבר אל אהרן אחיך ואל יבא בכל עת אל הקדש וגו': ר׳ שמעון פתח ואמר, כל הנחלים הולכים אל הים והים איננו מלא וגו'. אמר רבי שמעון, תמה אני על בני העולם, שאין להם עינים לראות, ולב להשגיח, ואינם יודעים, ואינם שמים לבם להסתכל ברצון אדונם, איך הם ישנים, ואינם קמים משנתם בטרם שיבא אותו היום שחשך ואפלה יכסו עליהם, ובעל הפקדון יתבע חשבון מהם."]],[[0,"","מִנַּיִן לָנוּ? שֶׁכָּתוּב (שמות ו) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ מִבְּנוֹת פּוּטִיאֵל לוֹ לְאִשָּׁה וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי אֲבוֹת הַלְוִיִּם לְמִשְׁפְּחֹתָם. אֵלֶּה, וַהֲרֵי פִּנְחָס לְבַדּוֹ הָיָה, וְכָתוּב רָאשֵׁי אֲבוֹת הַלְוִיִּם. מִשּׁוּם כָּךְ מֵתוּ מִיתַת עַצְמָם, וּמִיתַת נַפְשָׁם לֹא מֵתוּ. אָמַר רַבִּי אֶלְעָזָר, וַדַּאי מַשְׁמָע אֵלֶּה, וּמַשְׁמָע רָאשֵׁי."],[1,"","וּמִשּׁוּם כָּךְ כָּתוּב, (במדבר כה) פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, וְכָתוּב וּפִינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הָיָה כֹּהֵן בַּיָּמִים הָהֵם. פִּנְחָס בֶּן אֶלְעָזָר הַכֹּהֵן הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא בְּכָל מָקוֹם שֶׁבָּא פִּנְחָס, בֶּן אַהֲרֹן הַכֹּהֵן כָּתוּב. וְאֶלְעָזָר לֹא כָתוּב, אֶלָּא אֶלְעָזָר הַכֹּהֵן, שֶׁכָּתוּב (שם כז) וְלִפְנֵי אֶלְעָזָר הַכֹּהֵן. (שם לא) וַיֹּאמֶר אֶלְעָזָר הַכֹּהֵן וְגוֹ'. וְעַל כֵּן מִיתַת עַצְמָם מֵתוּ, וּמִיתַת נַפְשָׁם לֹא מֵתוּ."],[2,"","וְשָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, שְׁנַיִם זוּג - פֶּן חָס. וַהֲרֵי נִתְבָּאֵר, יוֹ\"ד קְטַנָּה בֵּין אוֹתִיּוֹת פִּנְחָס, שֶׁהֲרֵי יוֹ\"ד כּוֹלֶלֶת שְׁנַיִם כְּאֶחָד, וְזֶהוּ סוֹד הַדָּבָר, וְזֶה נִתְבָּאֵר."],[3,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת אָבִיו וְאָמַר לוֹ, וַהֲרֵי שְׁנַיִם הֵם וּשְׁנַיִם הָיוּ, לָמָּה לֹא נִמְצְאוּ שְׁנַיִם? אָמַר לוֹ, שְׁנֵי חֲצָאֵי גוּף הָיוּ, שֶׁהֲרֵי לֹא נִשְּׂאוּ, וּמִשּׁוּם כָּךְ הֵם נִכְלְלוּ בְאֶחָד, שֶׁכָּתוּב וַתֵּלֶד לוֹ אֶת פִּינְחָס אֵלֶּה רָאשֵׁי וְגוֹ'."],[4,"","וְיוֹ\"ד שֶׁל פִּנְחָס לֹא נִתַּן בָּהּ לְחַבֵּר הָאוֹתִיּוֹת, אֶלָּא בְּשָׁעָה שֶׁקִּנֵּא לַקָּדוֹשׁ בָּרוּךְ הוּא וּבָא לְיַשֵּׁר אֶת הֶעָקֹם, שֶׁרָאָה אֶת אוֹת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ שֶׁהִכְנִיס זִמְרִי לְרָשׁוּת אַחֶרֶת, וּבְמַה שֶּׁהִתְעַקֵּם בָּרִאשׁוֹנָה הִתְתַּקֵּן כָּאן. בְּנָכְרִיָּה הִתְעַקְּמוּ בַהַתְחָלָה, שֶׁכָּתוּב בְּהַקְרִיבָם אֵשׁ זָרָה, וְכָאן בְּנָכְרִיָּה הִתְתַּקְּנוּ, כְּמוֹ שֶׁכָּתוּב וּבָעַל בַּת אֵל נֵכָר. מַה לְּהָלְאָה אֵשׁ זָרָה, אַף כָּאן גַּם אִשָּׁה זָרָה."],[5,"","מַה נִּרְאֶה כָּאן? אֶלָּא בַּהַתְחָלָה הִקְרִיבוּ אֶת הָרְחוֹקָה, שֶׁכָּתוּב בְּהַקְרִבָם אֵשׁ זָרָה. אַף כָּאן זִמְרִי הָיָה מַקְרִיב אֶת הָרְחוֹקָה, אֶת שֵׁם הַמֶּלֶךְ הָיָה מְקָרֵב לָרְחוֹקָה, מִיָּד - (שם כה) וַיַּרְא פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן וַיָּקָם מִתּוֹךְ הָעֵדָה. כָּאן תִּקֵּן אֶת הֶעָקֹם שֶׁבָּרִאשׁוֹנָה, וְאָז נִתְּנָה יוֹ\"ד לִשְׁמוֹ לְחַבֵּר אֶת הָאוֹתִיּוֹת כְּאֶחָד וְהִתְבַּשֵּׂר בְּשָׁלוֹם, שֶׁכָּתוּב לָכֵן אֱמֹר הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. (בריתי ממש)."],[6,"","מָה הַשָּׁלוֹם כָּאן? אֶלָּא בְּאוֹתוֹ הַכֶּתֶר חָטְאוּ בַתְּחִלָּה, בְּאוֹתוֹ הַכֶּתֶר הֵעִירוּ קְטָטָה בַּתְּחִלָּה, וְעַכְשָׁו שֶׁתֻּקַּן, כָּתוּב הִנְנִי נֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, בְּרִיתִי מַמָּשׁ תִּהְיֶה עִמּוֹ בְשָׁלוֹם, וּמִשּׁוּם כָּךְ נִתְּנָה יוֹ\"ד קְטַנָּה בִּשְׁמוֹ, שֶׁהֲרֵי הִיא מֵהָאוֹתִיּוֹת הַקְּטַנּוֹת, לְהַרְאוֹת שֶׁהֲרֵי תֻּקַּן מַה שֶּׁהִתְעַקֵּם בַּתְּחִלָּה, וַהֲרֵי הִשְׁלִימָה עִמּוֹ. בָּא רַבִּי אֶלעָזָר וְנָשַׁק יָדוֹ וְאָמַר, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁאַלְתִּי דָבָר זֶה וְלֹא אָבַד מִמֶּנִּי."],[7,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, בְּיוֹם הַכִּפּוּרִים הַזֶּה תִּקְּנוּ לִקְרֹא פָּרָשָׁה זוֹ, לְכַפֵּר עַל יִשְׂרָאֵל בַּגָּלוּת, בִּשְׁבִיל זֶה סֵדֶר הַיּוֹם הַזֶּה כָּאן הִסְתַּדֵּר, וּמִשּׁוּם שֶׁמִּיתַת בְּנֵי אַהֲרֹן מְכַפֶּרֶת עַל יִשְׂרָאֵל."],[8,"","מִכָּאן לָמַדְנוּ, כָּל אוֹתוֹ בֶּן אָדָם שֶׁיִּסּוּרֵי רִבּוֹנוֹ בָּאִים עָלָיו - כַּפָּרַת חֲטָאָיו הֵם. וְכָל מִי שֶׁמִּצְטַעֵר עַל יִסּוּרֵי הַצַּדִּיקִים, מַעֲבִירִים חֲטָאֵיהֶם מִן הָעוֹלָם. וְעַל כֵּן בַּיּוֹם הַזֶּה קוֹרְאִים אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן, שֶׁיִּשְׁמְעוּ הָעָם וְיִצְטַעֲרוּ עַל אָבְדַן הַצַּדִּיקִים, וְיִתְכַּפְּרוּ לָהֶם חֲטָאֵיהֶם. וְכָל מִי שֶׁמִּצְטַעֵר עַל אָבְדָנָם שֶׁל הַצַּדִּיקִים אוֹ מוֹרִיד עֲלֵיהֶם דְּמָעוֹת, הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו וְאוֹמֵר: (ישעיה ו) וְסָר עֲוֹנֶךְ וְחַטָּאתְךְ תְּכֻפָּר. וְלֹא עוֹד, אֶלָּא שֶׁלֹּא יָמוּתוּ בָנָיו בְּיָמָיו. וְעָלָיו כָּתוּב, (שם נג) יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְגוֹ'."],[9,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְאַל יָבֹא בְעֵת עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, תְּמֵהַנִי עַל בְּנֵי הָעוֹלָם, שֶׁהֲרֵי אֵין לָהֶם עֵינַיִם לִרְאוֹת וְלֵב לְהַשְׁגִּיחַ, וְלֹא יוֹדְעִים וְלֹא שָׂמִים לִבָּם לְהִסְתַּכֵּל עַל רְצוֹן רִבּוֹנָם, אֵיךְ יְשֵׁנִים וְלֹא מִתְעוֹרְרִים מִשְּׁנָתָם טֶרֶם יָבֹא אוֹתוֹ הַיּוֹם שֶׁחֹשֶׁךְ וַאֲפֵלָה יְכַסּוּ עֲלֵיהֶם, וְיִתְבַּע אוֹתוֹ בַּעַל הַפִּקָּדוֹן מֵהֶם חֶשְׁבּוֹן."]]],[["וְכָרוֹזָא כָּל יוֹמָא קָארֵי עָלַיְיהוּ, וְנִשְׁמָתֵהוֹן, אַסְהִידַת בְּהוֹן בְּכָל יוֹמָא וְלֵילְיָא, אוֹרַיְיתָא רָאמַת קָלִין לְכָל עִבָר, מַכְרֶזֶת וְאוֹמֶרֶת, (משלי א׳:כ״ב) עַד מָתַי פְּתָאִים תְּאֶהֲבוּ פֶתִי (משלי ט׳:ה׳) מִי פֶתִי יָסוּר הֵנָּה חֲסַר לֵב אָמְרָה לוֹ. לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ, וְלֵית מַאן דְּיִתְּעַר לִבֵּיהּ.","תָּא חֲזֵי, זְמִינִין דָּרֵי בַּתְרָאֵי דְּיֵיתוּן, דְּיִתְנְשֵׁי אוֹרַיְיתָא מִבֵּינַיְיהוּ, וְחַכִּימֵי לִבָּא יִתְכַּנְּשׁוּן לְאַתְרַיְיהוּ, (ס\"א לאתרא קדישא) וְלָא יִשְׁתְּכַּח מַאן דְּסָגִיר וּפָתַח. וַוי לְהַהוּא דָּרָא. וּמִכָּאן וּלְהָלְאָה, לָא יְהֵא דָּרָא כְּדָרָא דָּא, עַד דָּרָא דְּיֵיתֵי מַלְכָּא מְשִׁיחָא, וּמַנְדְּעָא יִתְּעַר בְּעָלְמָא, דִּכְתִּיב, (ירמיהו ל״א:ל״ד) כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם.","תָּא חֲזֵי, כְּתִיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. וְתָנֵינָן, מַה שְׁמֵיהּ דְּהַהוּא נָהָר. אוֹקִימְנָא יוּבַל שְׁמֵיהּ, דִּכְתִּיב, (ירמיהו י״ז:ח׳) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וּבְסִפְרָא דְּרַב הַמְנוּנָא סָבָא, חַיִּים שְׁמֵיהּ, דִּמִתַּמָּן נָפְקִין חַיִּים לְעָלְמָא, וְאִינּוּן אִקְרוּן חַיֵּי מַלְכָּא. וְהָא אוֹקִימְנָא, הַהוּא אִילָנָא רַבָּא וְתַקִּיפָא, דְּמָזוֹן לְכֹלָּא בֵּיהּ. אִקְרֵי עֵץ חַיִּים. אִילָנָא דְּנָטַע שָׁרְשׁוֹי בְּאִינּוּן חַיִּים, וְכֹלָּא הוּא שַׁפִּיר.","וְתָאנָא, הַהוּא נָהָר אַפִּיק נַחֲלִין עֲמִיקִין, בִּמְשַׁח רְבוּת, לְאַשְׁקָאָה גִּנְתָּא, וּלְרַוָּואָה אִילָנִין וּנְטִיעִין, דִּכְתִּיב (תהילים ק״ד:ט״ז) יִשְׂבְּעוּ עֲצֵי יְיָ' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, וְאִינּוּן נַחֲלִין, נַגְדִּין וְאִתְמַשְּׁכָן וּמִתְכַּנְּשִׁין בִּתְרֵין קַיָימִין (נ\"א סמכין) וְאִינּוּן בִּרְיָיתֵי (תרי) קָרֵינָן לְהוּ, (מלכים א ז) יָכִי\"ן וּבוֹעַ\"ז, וְשַׁפִּיר. וּמִתַּמָּן נָפְקִין כָּל אִינּוּן נַחֲלִין, וְשַׁרְיָין לוֹן בְּחַד דַּרְגָּא דְּאִקְרֵי צַדִּיק, דִּכְתִּיב, (משלי י׳:כ״ה) וְצַדִיק יְסוֹד עוֹלָם. וְכֻלְּהוּ אַזְלִין וּמִתְכַּנְּשִׁין לְהַהוּא אֲתַר דְּאִקְרֵי יָם, וְהוּא יַמָּא דְּחָכְמְתָא, הֲדָא הוּא דִכְתִיב, (קהלת א׳:ז׳) כָּל (שמות נ' ע\"ב) הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְגוֹ'.","וְאִי תֵּימָא, דְּהָא מָטוּ לַאֲתָר דָּא, וּפַסְקִין, וְלָא תַּיְיבִין, לְבָתַר כְּתִיב, אֶל מְקוֹם שֶׁהַנְּחָלִים הוֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת, בְּגִין דְּהַהוּא נַהֲרָא לָא פָּסִיק לְעָלְמִין. הֵם שָׁבִים, לְאָן אֲתַר שָׁבִים, לְאִינּוּן תְּרֵין קַיְימִין, נֶצַח וְהוֹד. לָלָכֶת, בְּהַאי צַדִּיק, לְאַשְׁכְּחָא בִּרְכָאָן וְחִידוּ. וְהַיְינוּ רָזָא דְּתָנֵינָן, (תהילים ק״ד:כ״ו) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, דָּא צַדִּיק.","כֻּלָּם אֵלֶיךָ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ. מַאן עִתּוֹ. דָּא (עתו דצדיק) מַטְרוֹנִיתָא, דְּאִקְרֵי עִתּוֹ דְּצַדִּיק, וּבְגִין כָּךְ כֻּלְּהוּ מְחַכָּאן לְהַאי עִתּוֹ, כֻּלְּהוּ דְּאַתְּזְנָן לְתַתָּא, מֵאֲתַר דָּא אַתְּזְנָן, וְרָזָא דָּא אוֹקִימְנָא, (תהילים קמ״ה:ט״ו) עֵינֵי כֹל אֵלֶיךָ יְשַׂבֵּרוּ וְגוֹ' כְּמָה דְּאוֹקִימְנָא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּהַאי כֹּל, מְבַסֵּם לְעִתּוֹ, וּמִתְחַבְּרָא עִמֵּיהּ, כֻּלְּהוּ עָלְמִין בְּחֵידוּ, כֻּלְּהוּ עָלְמִין בְּבִרְכָּאן, כְּדֵין שְׁלָמָא אִשְׁתְּכַח בְּעִלָּאֵי וְתַתָּאֵי. וְכַד גַּרְמִין חַיָּיבֵי עָלְמָא, דְּתַמָן לָא אִשְׁתְּכָחוּ בִּרְכָאן דְּאִינּוּן נַחֲלֵי, וְיַנְקָא, הַאי עֵת, מִסִּטְרָא אָחֳרָא, כְּדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וּשְׁלָמָא לָא אִשְׁתְּכַח. וְכַד בָּעָאן בְּנֵי עָלְמָא לְאִתְבָּרְכָא, לָא יַכְלִין אֶלָּא עַל יְדָא דְּכַהֲנָא, בְּגִין דְּיִתְּעַר כִּתְרָא דִּילֵיהּ, וְיִתְבְּרַךְ מַטְרוֹנִיתָא, וְיִשְׁתְּכָחוּ בִּרְכָאן בְּכֻלְּהוּ עָלְמִין.","תָּאנָא, בְּהַהִיא שַׁעֲתָא, בָּעָא מֹשֶׁה קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, מִלָּה דָּא, אָמַר לֵיהּ, אִי בְּנֵי עָלְמָא יְתוּבוּן קַמָּךְ, עַל יְדֵי דְּמַאן מִתְבָּרְכָאן. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְלִי אַתְּ אוֹמֵר, דַּבֵּר אֶל אַהֲרֹן אָחִיךָ, דְּהָא בִּידֵיהּ מְסִירָאן בִּרְכָאן לְעֵילָּא וְתַתָּא.","וַיֹּאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. אָמַר רִבִּי אַבָּא, זִמְנִין אִית קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, לְאִשְׁתַּכְּחָא רַעֲוָון, וּלְאִשְׁתַּכְחָא בִּרְכָאן, וּלְמִתְבַּע בָּעוּתֵי, וְזִמְנִין, דְּרַעֲוָון לָא אִשְׁתְּכָחוּ, וּבִרְכָּאן לָא מִזְדַּמְנָן, וְדִינִין קַשְׁיָין מִתְעָרִין בְּעָלְמָא. וְזִמְנִין דְּדִינָא תָּלֵי. תָּא חֲזֵי, זִמְנִין אִית בְּשַׁתָּא, דְּרַעֲוָוא אִשְׁתְּכַח. וְזִמְנִין אִית בְּשַׁתָּא, דְּדִינָא אִשְׁתְּכַח. וְזִמְנִין אִית בְּשַׁתָּא, דְּדִינָא אִשְׁתְּכַח וְתַלְיָא. זִמְנִין אִית בְּיַרְחֵי, דְּרַעֲוָא אִשְׁתְּכַח בְּהוּ. וְזִמְנִין אִית בְּיַרְחֵי, דְּדִינִין אִשְׁתְּכָחוּ, וְתַּלְיָין עַל כֹּלָּא."],[[0,"וכרוזא כל יומא וכו׳:","והכרוז קורא עליהם בכל יום, ונשמתם מעידה בהם בכל יום ולילה, והתורה מרימה קולות לכל צד, ואומרת, עד מתי פתאים תאהבו פתי. מי פתי יסור הנה חסר לב אמרה לו. לכו לחמו בלחמי ושתו ביין מסכתי. ואין מי שיטה אזנו, ואין מי שיעורר לבו."],[1,"ת\"ח זמינין דרי וכו׳:","בוא וראה, עתידים דורות האחרונים שיבואו, שהתורה תשתכח מביניהם, וחכמי לב יתאספו למקומם, ולא ימצא מי שיסגור ויפתח בתורה. אוי לאותו הדור, ומכאן ולהלאה, לא יהיה כדור הזה, עד הדור שיבא המשיח, והדעת תתעורר בעולם, שכתוב, כי כולם ידעו אותי למקטנם ועד גדולם."],[2,"ת״ח כתיב ונהר וכו׳:","בוא וראה, כתוב, ונהר יוצא מעדן. ולמדנו מה שמו של אותו הנהר. והעמדנו שמו \u0003יובל\u0004 שהוא בינה, שכתוב ועל יובל ישלח שורשיו. ובספרו של רב המנונא סבא, אומר, שחיים שמו, שהוא בינה, שמשם יוצאים חיים לעולם. והם נקראים חיי המלך. והרי העמדנו, והוא, אותו אילן הגדול והחזק, שהוא ז״א, שמזון לכל בו, ונקרא עץ החיים, דהיינו אילן שנטע שרשיו באלו החיים שלמעלה, שהוא בינה. והכל הוא טוב."],[3,"ותאנא ההוא נהר וכו׳:","ולמדנו, נהר ההוא הוציא נחלים עמוקים, שהם ג׳ ספירות חג״ת דז״א, בשמן המשחה, להשקות את הגן שהוא המלכות, ולרוות האילנות והנטיעות. דהיינו ספירות המלכות, שכתוב, ישבעו עצי ה׳ ארזי לבנון אשר נטע, ואלו הנחלים, שהם חג״ת, נוזלים ונמשכים ומתקבצים בשני עמודים, שהברייתות קוראים להם \u0003יכין ובועז,\u0004 שהם נצח והוד. ויפים הם, השמות האלו. ומשם, מנו\"ה, יוצאים כל אלו הנחלים שהם חג״ת, והם שורים במדרגה אחת שנקראת צדיק, שהוא יסוד. שכתוב, וצדיק \u0003יסוד\u0004 עולם. וכולם הולכים ומתקבצים במדרגה ההיא הנקראת \u0003ים\u0004, והוא ים החכמה, שהוא המלכות. ז״ש, כל הנחלים הולכים אל הים."],[4,"ואי תימא דהא וכו׳:","ואם תאמר, כשמגיעים הנחלים למקום הזה, מלכות, הם פוסקים, ואינם חוזרים, כתוב אחר זה, אל מקום שהנחלים הולכים שם הם שבים ללכת, משום שהנהר ההוא אינו פוסק מימיו לעולם. \u0003הם שבים,\u0004 לאיזה מקום הם שבים. ומשיב, ששבים לאלו ב׳ עמודים, נצח והוד. \u0003ללכת,\u0004 בצדיק הזה, שהוא יסוד, למצוא ברכות ושמחה. וז״ס שלמדנו, לויתן זה יצרת לשחק בו, זהו צדיק."],[5,"כלם אליך ישברון לתת אכלם בעתו:","מהו עתו. זו היא מטרוניתא, שהיא המלכות, הנקרא \u0003עתו\u0004 של צדיק, שהוא יסוד. ומשום זה הכל מצפים ל \u0003עתו\u0004 הזה, כולם הנזונים למטה, ממקום הזה נזונים, שהתחתונים אינם מקבלים אלא ממלכות. וסוד זה העמדנו, עיני כל אליך ישברו וגו', כמו שהעמדנו."],[6,"ת״ח בשעתא דהאי וכו׳:","בוא וראה, בשעה ש \u0003כל\u0004 הזה, שהוא יסוד הנקרא \u0003כל,\u0004 מבשם ל \u0003עתו,\u0004 שהיא מלכות, ומתחברת עמו, כל העולמות הם בשמחה, כל העולמות הם בברכות, אז השלום נמצא בעליונים ובתחתונים. וכשרשעי עולם גורמים שאינם נמצאים שם הברכות של אלו נחלים, שהם חג״ת דז״א, ו \u0003עת\u0004 הזו יונקת מצד אחר, שהוא דין, אז דינים מתעוררים בעולם ושלום אינו נמצא. וכשרוצים בני העולם להתברך, אינם יכולים כי אם על ידי הכהן, כדי שיעורר הספירה שלו, שהוא חסד, ותתברך המטרוניתא, שהיא המלכות, והברכות תמצאנה בכל העולמות."],[7,"תאנא בההיא שעתא וכו׳:","למדנו, בשעה ההיא, אחר מיתת בני אהרן, בקש משה לפני הקב״ה, דבר זה, שהוא חסד. אמר לו משה, אם בני העולם ישובו לפניך, על ידי מי יתברכו. אמר לו הקב״ה, ולי אתה אומר, \u0003דבר אל אהרן אחיך,\u0004 כי בידיו מסורים הברכות למעלה ולמטה. שהוא מרכבה לחסד כנ״ל."],[8,"תאנא בההיא שעתא וכו׳:","למדנו, \u0003הקדש:\u0004 א״ר אבא, עתים יש לפני הקב״ה למצוא רצון ולמצוא ברכות ולבקש בקשות. ויש עתים, שרצון אינו נמצא, וברכות אינן באות, ודינים קשים מתעוררים בעולם. ולעתים שהדין תולה. בוא וראה, עתים יש בשנה, שהרצון נמצא, ועתים יש בשנה שהדין נמצא, ועתים יש בשנה שהדין נמצא ותלוי. כלומר שהדין תלוי ומאיים על העולם, אבל אינו פועל. עתים יש בחודש, שרצון נמצא בהן, ועתים יש בחדש שדינים נמצאים, ותלוים על הכל."]],[[0,"","וְהַכָּרוֹז בְּכָל יוֹם קוֹרֵא עֲלֵיהֶם, וְנִשְׁמָתָם מְעִידָה בָהֶם בְּכָל יוֹם וָלַיְלָה, הַתּוֹרָה מְרִימָה קוֹלוֹת לְכָל עֵבֶר, מַכְרִיזָה וְאוֹמֶרֶת: (משליא) עַד מָתַי פְּתָיִם תְּאֵהֲבוּ פֶתִי. (שם ט) מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב אָמְרָה לּוֹ לְכוּ לַחֲמוּ בְלַחְמִי וּשְׁתוּ בְּיַיִן מָסָכְתִּי. וְאֵין מִי שֶׁיַּרְכִּין אָזְנוֹ וְאֵין מִי שֶׁיָּעִיר אֶת לִבּוֹ."],[1,"","בֹּא רְאֵה, עֲתִידִים הַדּוֹרוֹת הָאַחֲרוֹנִים שֶׁיָּבאוּ שֶׁתִּשָּׁכַח תּוֹרָה מִבֵּינֵיהֶם, וְחַכְמֵי הַלֵּב יִתְכַּנְּסוּ לִמְקוֹמָם (לחדרקדוש), וְלֹא יִמָּצֵא מִי שֶׁסּוֹגֵר וּפוֹתֵחַ. אוֹי לְאוֹתוֹ הַדּוֹר! וּמִכָּאן וָהָלְאָה לֹא יִהְיֶה דוֹר כְּמוֹ הַדּוֹר הַזֶּה, עַד הַדּוֹר שֶׁיָּבֹא מֶלֶךְ הַמָּשִׁיחַ, וְהַדֵּעָה תִתְעוֹרֵר בָּעוֹלָם, שֶׁכָּתוּב (ירמיה לא) כִּי כֻלָּם יֵדְעוּ אוֹתִי לְמִקְּטַנָּם וְעַד גְּדוֹלָם."],[2,"","בֹּא רְאֵה, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן. וְשָׁנִינוּ, מַה שְּׁמוֹ שֶׁל אוֹתוֹ נָהָר? בֵּאַרְנוּ שֶׁשְּׁמוֹ יוּבַל, שֶׁכָּתוּב (ירמיה טז) וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו. וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא: חַיִּים שְׁמוֹ, שֶׁמִּשָּׁם יוֹצְאִים חַיִּים לָעוֹלָם, וְהֵם נִקְרָאִים חַיֵּי הַמֶּלֶךְ. וַהֲרֵי בֵּאַרְנוּ, אוֹתוֹ עֵץ גָּדוֹל וְחָזָק שֶׁבּוֹ יֵשׁ מָזוֹן לַכֹּל נִקְרָא עֵץ הַחַיִים. הָאִילָן שֶׁנָּטַע שָׁרָשָׁיו בְּאוֹתָם הַחַיִּים, וְהַכֹּל הוּא נָאֶה."],[3,"","וְשָׁנִינוּ, אוֹתוֹ הַנָּהָר הוֹצִיא נְחָלִים עֲמֻקִּים בְּשֶׁמֶן הַמִּשְׁחָה, לְהַשְׁקוֹת אֶת הַגָּן וּלְהַרְווֹת עֵצִים וּנְטִיעוֹת, שֶׁכָּתוּב (תהלים קד) יִשְׂבְּעוּ עֲצֵי ה' אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע. וְאוֹתָם הַנְּחָלִים שׁוֹפְעִים וְנִמְשָׁכִים וּמִתְכַּנְּסִים לִשְׁנֵי עַמּוּדִים, וְאוֹתָן בָּרַיְתוֹת (שתים) קוֹרְאִים לָהֶן יָכִי\"ן וּבוֹעַ\"ז, וְיָפֶה. וּמִשּׁוּם יוֹצְאִים כָּל אוֹתָם נְחָלִים, וּמַשְׁרִים אוֹתָם בְּדַרְגָּה אַחַת שֶׁנִּקְרֵאת צַדִּיק, שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם. וְכֻלָּם הוֹלְכִים וּמִתְכַּנְּסִים לְאוֹתוֹ מָקוֹם שֶׁנִּקְרָא יָם, וְהוּא יָם הַחָכְמָה. זֶהוּ שֶׁכָּתוּב (קהלת א) כָּל הַנְּחָלִים הֹלְכִים אֶל הַיָּם וְגוֹ'."],[4,"","וְאִם תֹּאמַר שֶׁהֲרֵי מַגִּיעִים לַמָּקוֹם הַזֶּה וְלֹא שָׁבִים - כָּתוּב אַחַר כָּךְ, אֶל מְקוֹם שֶׁהַנְּחָלִים הֹלְכִים שָׁם הֵם שָׁבִים לָלָכֶת, מִשּׁוּם שֶׁאוֹתוֹ נָהָר לֹא פוֹסֵק לְעוֹלָמִים. הֵם שָׁבִים, לְאֵיזֶה מָקוֹם הֵם שָׁבִים? לְאוֹתָם שְׁנֵי עַמּוּדִים, נֵצַח וְהוֹד. לָלָכֶת, בַּצַּדִּיק הַזֶּה, לִמְצֹא בְּרָכוֹת וְשִׂמְחָה. וְזֶהוּ הַסּוֹד שֶׁשָּׁנִינוּ, (תהלים קד) לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ, זֶה צַדִּיק."],[5,"","כֻּלָּם אֵלֶיךְ יְשַׂבֵּרוּן לָתֵת אָכְלָם בְּעִתּוֹ. מִי זוֹ עִתּוֹ? (זו עתו של צדיק) זוֹ הַגְּבִירָה, שֶׁנִּקְרֵאת עִתּוֹ שֶׁל צַדִּיק, וּמִשּׁוּם כָּךְ כֻּלָּם מְחַכִּים לָעִתּוֹ הַזּוֹ. כָּל אֵלּוּ שֶׁנִּזּוֹנִים לְמַטָּה, מִמָּקוֹם זֶה נִזּוֹנִים, וְסוֹד זֶה בֵּאַרְנוּ, (שם קמה) עֵינֵי כֹל אֵלֶיךְ יְשַׂבֵּרוּ וְגוֹ', כְּמוֹ שֶׁבֵּאַרְנוּ."],[6,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁהַכֹּל הַזֶּה מְבַשֵּׂם אֶת עִתּוֹ וּמִתְחַבֵּר עִמּוֹ, אָז כָּל הָעוֹלָמוֹת בְּשִׂמְחָה וְכָל הָעוֹלָמוֹת בִּבְרָכוֹת, אָז נִמְצָא שָׁלוֹם בָּעֶלְיוֹנִים וּבַתַּחְתּוֹנִים, וּכְשֶׁגּוֹרְמִים רִשְׁעֵי הָעוֹלָם שֶׁשָּׁם לֹא נִמְצָאוֹת בְּרָכוֹת שֶׁל אוֹתָם הַנְּחָלִים, וְהָעֵת הַזּוֹ יוֹנֶקֶת מִצַּד הָאַחֵר, אֲזַי מִתְעוֹרְרִים דִּינִים בָּעוֹלָם וְלֹא נִמְצָא שָׁלוֹם. וּכְשֶׁרוֹצִים בְּנֵי הָעוֹלָם לְהִתְבָּרֵךְ, לֹא יְכוֹלִים, אֶלָּא רַק עַל יְדֵי הַכֹּהֵן, כְּדֵי שֶׁיְּעוֹרֵר אֶת הַכֶּתֶר שֶׁלּוֹ וְתִתְבָּרֵךְ הַגְּבִירָה, וְיִמָּצְאוּ בְרָכוֹת בְּכָל הָעוֹלָמוֹת."],[7,"","שָׁנִינוּ, בְּאוֹתָהּ שָׁעָה בִּקֵּשׁ מֹשֶׁה מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא דָּבָר זֶה. אָמַר לוֹ, אִם בְּנֵי הָעוֹלָם יָשׁוּבוּ לְפָנֶיךְ, עַל יְדֵי מִי מִתְבָּרְכִים? אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלִי אַתָּה אוֹמֵר?! דַּבֵּר אֶל אַהֲרֹן אָחִיךְ, שֶׁהֲרֵי בְּיָדוֹ מְסוּרוֹת הַבְּרָכוֹת לְמַעְלָה וּלְמַטָּה."],[8,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'. אָמַר רַבִּי אַבָּא, יֵשׁ זְמַנִּים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁנִּמְצָאִים רְצוֹנוֹת וְנִמְצָאוֹת בְּרָכוֹת וּלְבַקֵּשׁ בַּקָּשׁוֹת, וְלִפְעָמִים שֶׁאֵין נִמְצָאִים רְצוֹנוֹת, וְאֵין מִזְדַּמְּנוֹת בְּרָכוֹת, וְדִינִים הַקָּשִׁים מִתְעוֹרְרִים בָּעוֹלָם. וְלִפְעָמִים שֶׁהַדִּין תָּלוּי. בֹּא רְאֵה, יֵשׁ בַּשָּׁנָה זְמַנִּים שֶׁנִּמְצָא רָצוֹן, וְיֵשׁ זְמַנִּים בַּשָּׁנָה שֶׁהַדִּין נִמְצָא וְתָלוּי. יֵשׁ זְמַנִּים בֶּחֳדָשִׁים שֶׁהָרָצוֹן נִמְצָא בָהֶם, וְיֵשׁ זְמַנִּים בֶּחֳדָשִׁים שֶׁנִּמְצָאִים דִּינִים, וּתְלוּיִים עַל הַכֹּל."]]],[["זִמְנִין אִית בְּשָׁבוּעֵי, דְּרַעֲוָון מִשְׁתַּכְּחָן, וְזִמְנִין אִית בְּשָׁבוּעֵי, דְּדִינִין מִשְׁתַּכְּחָן בְּעָלְמָא. וְזִמְנִין אִית בְּיוֹמֵי, דְּרַעֲוָוא אִשְׁתְּכַח בְּעָלְמָא וְעָלְמָא אִתְבַּסְמָא. וְזִמְנִין אִית בְּיוֹמֵי דְּדִינִין תַּלְיָין וּמִשְׁתַּכְחָן, וַאֲפִילּוּ בְּשַׁעְתֵּי. וְעַל דָּא כְּתִיב, (קהלת ג׳:א׳) וְעֵת לְכָל חָפֵץ וְגוֹ'. וּכְתִיב, (תהילים ס״ט:י״ד) וַאֲנִי תְפִלָּתִי לְךָ וְגוֹ'. וּכְתִיב, (ישעיה נה) דִּרְשׁוּ יְיָ' בְּהִמָּצְאוֹ. וּכְתִיב, (תהילים י׳:א׳) לָמָּה יְיָ' תַּעֲמוֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. וּכְתִיב, (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי. וְזִמְנִין דְּאִיהוּ קָרוֹב, דִּכְתִּיב, (תהילים קמ״ה:י״ח) קָרוֹב יְיָ' לְכָל קוֹרְאָיו. בְּגִין כָּךְ, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'.","רִבִּי שִׁמְעוֹן אָמַר, הָא אוֹקִימְנָא. מִלָּה בְּעִתּוֹ, וְהָכִי הוּא ודַּאי, וְהָכָא אָתָא קוּדְשָׁא בְּרִיךְ הוּא לְאַזְהָרָא לְאַהֲרֹן, דְּלָא יִטְעֵי בְּהַהוּא חוֹבָא, דְּטָעוּ בְּנוֹי, דְּהָא הַאי עֵת יְדִיעָא, בְּגִין כָּךְ לָא יִטְעֵי לְחַבְּרָא עֵת אָחֳרָא, לְגַבֵּי מַלְכָּא. הֲדָא הוּא דִכְתִיב, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. כְּלוֹמַר, אַף עַל גַּב דְּיֵחֱמֵי עִידָּן, דְּאִתְּמְסַר בִּידָא אָחֳרָא, לְאִתְנָהֲגָא עָלְמָא, וְיִתְמְסַר בִּידוֹי לְיַיחֵד בֵּיהּ לְקָרְבָא לֵיהּ לְקוּדְשָׁא, דְּהָא אֲנָא וּשְׁמִי חַד הוּא. וּבְגִּינֵי כַּךְ, (ס\"א לקרבא ליה לקודשא בריך הוא דהא האי עת ידיע, בגין כך) וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְאִי בָּעֵי לְמִנְדַּע בְּמָה יֵיעוּל. בְּזֹאת. בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. דְּהַאי זֹאת, הִיא עֵת דַּאֲחִידַת בִּשְׁמִי, בְּהַאי י', דִּרְשִׁימָא בִּשְׁמִי, יֵיעוּל אֶל הַקֹּדֶשׁ. (אבל) וְאַל יָבֹא בְכָל עֵת.","תָּאנָא אָמַר רִבִּי יוֹסֵי כְּתִיב (קהלת ג׳:י״א) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ הַאי מִלָּה אוֹקְמָהּ בּוּצִינָא (ס\"א בשמא) קַדִּישָׁא וְהָכִי הוּא דְּתַנִּינָא אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ וְהָכִי הוּא וַדַּאי. אֶת הַכֹּל וַדַּאי. עָשָׂה יָפֶה בְעִתּוֹ, דָּא בְּדָא, וְלָא יִתְעָרְבוּן אָחֳרָנִין בֵּינַיְיהוּ. בְעִתּוֹ מַמָּשׁ, וְלָא בָּאֳחָרָא. בְּגִינֵי כַּךְ, אַזְהָרוּתָא לְאַהֲרֹן, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. אֲבָל בְּמָה יֵיעוּל. בְּזֹאת, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ.","רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵי אֲבוּהָ, אָמַר לֵיהּ, כְּתִיב בִּכְנִישְׁתָּא דְּקֹרַח, (במדבר ט״ז:ל״ג) וְיֹּאבְדוּ מִתּוֹךְ הַקָּהָל, מַאי וְיֹּאבְדוּ. אֶלָּא כְּמָה דִּכְתִּיב, (ויקרא כ״ג:ל׳) וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִיא מִקֶּרֶב עַמָּהּ. (ס\"א כתיב בבני אהרן (ויקרא י׳:ב׳) ותצא אש מלפני יי' ותאכל אותם וימותו. וכתיב בכנישתא דקרח ואש יצאה מאת יי' ותאכל את החמשים ומאתים איש ס\"ד דשקילין דא כדא) אָמַר רִבִּי שִׁמְעוֹן, שָׁאנֵי אִינּוּן בְּנֵי אַהֲרֹן, דְּלָא כְּתִיב בְּהוּ אֲבֵדָה, כְּאִינּוּן דִּכְנִישְׁתָּא דְּקֹרַח, דִּכְתִּיב בְּהוּ, וְיֹּאבְדוּ מִתּוֹךְ הַקָּהָל. וּכְתִיב, (במדבר י״ז:כ״ז) הֵן גָּוַעְנוּ אָבַדְנוּ כֻּלָּנוּ אָבַדְנוּ. לְאַכְלְלָא אִינּוּן דְּאַקְרִיבוּ קְטֹרֶת בּוּסְמִין, מָאתָן וְחַמְשִׁין, דְּאִתְאֲבִידוּ וַדַּאי, וְאִלֵּין לָא אִתְאֲבִידוּ.","אָמַר לֵיהּ כְּתִיב, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וּכְתִיב, בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. כֵּיוָן דְּאָמַר, וְאַל יָבֹא בְכָל עֵת, אֲמַאי לָא כְּתִיב, בְּמָה זִמְנָא יֵיעוּל. אָמַר לֵיהּ אֶלְעָזָר, הָא אִתְּמַר, וּמִלָּה חַד הוּא, וְזִמְנָא חַד הוּא הֲווֹ יַדְעֵי כַּהֲנֵי. אֲבָל עַל מַה דְּחָאבוּ בְּנוֹי, בָּעָא לְאַזְהָרָא הָכָא, וְהָא אִתְּמַר. אָמַר לֵיהּ, וַאֲנָא הָכִי סָבִירְנָא, וּבְגִין לְאִתְיַישְּׁבָא מִלָּה בְּעֵינָא.","אָמַר לֵיהּ, אֶלְעָזָר בְּרִי תָּא חֲזֵי, כָּל קָרְבְּנִין וְכָל עִלָּוָון, נַיְיחָא הוּא דְּקוּדְשָׁא בְּרִיךְ הוּא, אֲבָל לָא הֲוָה נַיְיחָא, כְּמָה דְּהַאי קְטֹרֶת, דִּקְטֹרֶת מְעַלְיָא מִכֹּלָּא. וּבְגִין כָּךְ, הֲווֹ מַעֲלִין לֵיהּ לְגוֹ בְּגוֹ, בִּלְחִישׁוּ. וְהָא אִתְּמַר. וּבְגִין כָּךְ, לָא אִתְעֲנָשׁוּ כָּל בְּנֵי נָשָׂא בִּשְׁאָר קָרְבְּנִין וְעִלָּוָון כְּמוֹ בַּקְּטֹרֶת, דְּכָל פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא, הָכָא אִתְקְטַר וְאִתְקְשַׁר יַתִּיר מִכֹּלָּא. וְעַל דָּא אִקְרֵי קְטֹרֶת. וְהָא אִתְּמַר, (משלי כ״ז:ט׳) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב.","פָּתַח רִבִּי שִׁמְעוֹן וְדָרַשׁ, (שיר השירים א׳:ג׳) לְרֵיחַ שְׁמָנֶיךָ טוֹבִים וְגוֹ'. הַאי קְרָא אִסְתַּכַּלְנָא בֵּיהּ, וְהָכִי הוּא. לְרֵיחַ, מַאי רֵיחַ. רֵיחַ דִּקְטֹרֶת דְּאִיהוּ דְּקִיקָא וּמָעַלְיָא וּפְנִימָאָה מִכֹּלָּא, וְכַד סָלִיק הַהוּא רֵיחַ לְאִתְקַשְּׁרָא, בְּהַהוּא מְשַׁח רְבוּת דְּנַחֲלֵי מַבּוּעָא, אִתְּעֲרוּ דָּא בְּדָא וְאִתְקְטָרוּ כַּחֲדָא. וּכְדֵין אִינּוּן מִשְׁחָן טָבָאן לְאַנְהָרָא. כְּמָה דְאַתְּ אָמֵר, לְרֵיחַ שְׁמָנֶיךָ טוֹבִים.","וּכְדֵין אִתְרַק מִשְׁחָא מִדַּרְגָּא לְדַרְגָּא, בְּאִינּוּן דַּרְגִּין דְּאִקְרוּן שְׁמָא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב, שֶׁמֶן תּוּרַק שְׁמֶךָ עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. מַאי עֲלָמוֹת. כְּמָה דְּאוֹקִימְנָא עוֹלָמוֹת, עוֹלָמוֹת מַמָּשׁ, דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ו:א׳) עַל עֲלָמוֹת שִׁיר. וְכֹלָּא חַד.","וּבְסִפְרָא דְּרַב הַמְנוּנָא סַבָא כְּתִיב, מַאי עוֹלָמוֹת. כְּמָה דְּאַתְּ אָמֵר, (משלי ל״א:ט״ו) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרוֹתֶיהָ. נַעֲרוֹתֶיהָ הָנֵי עֲלָמוֹת, אֲהֵבוּךָ, לְבָרְכָא שְׁמָךְ, וּלְזַמְּרָא קַמָּךְ, וּמִתַּמָּן אִשְׁתַּכְּחָן בִּרְכָאן בְּכֻלְּהוּ תַּתָּאֵי, וּמִתְבָּרְכִין עִלָּאִין וְתַתָּאִין."],[[0,"זמנין אית בשבועי, וכו׳:","עתים יש בשבוע, שרצון נמצא, ועתים יש בשבוע שדינים נמצאים בעולם. ועתים יש בימים שהרצון נמצא בעולם והעולם נתבסם. ועתים יש בימים שדינים תלוים ונמצאים, ואפילו בשעה יש עתים שונות. וע״כ כתוב, \u0003ועת\u0004 לכל חפץ וגו'. וכתוב, ואני תפלתי לך ה׳ \u0003עת\u0004 רצון. וכתוב, דרשו ה׳ בהמצאו. וכתוב, למה ה׳ תעמוד ברחוק תעלים ל \u0003עתות\u0004 בצרה. וכתוב, מרחוק ה׳ נראה לי. ולעתים הוא קרוב, שכתוב, קרוב ה׳ לכל קוראיו. משום זה ואל יבא בכל \u0003עת\u0004 אל הקדש וגו'."],[1,"ר״ש אמר הא וכו׳:","ר׳ שמעון אמר, הרי העמדנו, דבר בעתו מה טוב, וכך הוא ודאי, וכאן בא הקב״ה להזהיר את אהרן, שלא יטעה באותו עון שטעו בניו, כי \u0003עת\u0004 זו ידועה, שהיא מלכות, משום זה לא יטעה לחבר \u0003עת\u0004 אחרת, אל המלך. ז״ש, ואל יבא בכל עת אל הקדש. כלומר, אע״פ שיראה ה \u0003עת,\u0004 שנמסרה בידי אחר, דהיינו בידי הס״א, להנהיג העולם, שתהיה נמסרת בידיו, כדי ליחד ולקרב העולם אל הקדש, כי אני ושמי אחד. שגם הס״א אינו אלא משמש אותי. ומשום זה, ואל יבא בכל \u0003עת\u0004 אל הקדש. ואם רוצה לדעת במה יבא, הוא ב \u0003זאת\u0004 שהיא המלכות דקדושה, בזאת יבא אהרן אל הקדש. כי \u0003זאת,\u0004 הזו, היא \u0003עת\u0004 הנאחזת בשמי ב \u0003י'\u0004 הזו, שהיא יסוד, הרשומה בשמי, ובה יבא אל הקדש. ואל יבא בכל \u0003עת.\u0004"],[2,"תאנא א״ר יוסי וכו׳:","למדנו אר״י, כתוב את הכל עשה יפה בעתו. דבר זה העמיד המאור הקדוש, וכך הוא, שלמדנו, את הכל עשה יפה בעתו, וכך הוא ודאי, את הכל ודאי שהוא יסוד הנקרא \u0003הכל,\u0004 עשה יפה בעתו, שהוא מלכות הנקראת \u0003עת,\u0004 זה בזה, ולא יתערבו אחרים ביניהם. \u0003בעתו\u0004 ממש, שהיא מלכות. ולא באחר, משום זה הוא אזהרה לאהרן, ואל יבא בכל עת אל הקדש. אבל במה יבא. ב \u0003זאת,\u0004 שהיא מלכות הנקרא זאת, כמו שהעמדנו, שכתוב בזאת יבא אהרן אל הקדש."],[3,"רבי אלעזר הוה וכו׳:","ר״א היה יושב לפני אביו, א״ל, כתוב בעדת קרח, ויאבדו מתוך הקהל, מהו ויאבדו. אלא הוא כמו שכתוב, והאבדתי את הנפש ההיא מקרב עמה. אמר ר״ש, משונים הם בני אהרן, מעדת קרח, שלא כתובה בהם אבדה, כמו שבעדת קרח, שכתוב בהם, ויאבדו מתוך הקהל. וכתוב, הן גוענו אבדנו כלנו אבדנו. שהוא כולל המאתים וחמשים איש שהקריבו קטרת הסמים, שהם נאבדו ודאי, ואלו, בני אהרן, לא נאבדו."],[4,"א״ל כתיב ואל וכו׳:","אמר לו כתוב, ואל יבא בכל עת אל הקדש. וכתוב, בזאת יבא אהרן אל הקדש. שואל, כיון שאמר, ואל יבא בכל עת, למה לא כתוב, באיזו עת יבא. שהיה לו לומר שבעשור לחדש יבא אל הקדש, והוא אומר, שבזאת יבא אל הקדש ולא פירש הזמן. אמר לו: אלעזר, הרי למדנו, ומלה אחת היא, ועת אחת היא, כי עת וזאת, הם מלה אחת, דהיינו ששניהם שמות המלכות, שהיו יודעים הכהנים. אבל על מה, שחטאו בניו רצה הקב״ה להזהיר כאן, דהיינו שלא יפגום בעת שהיא מלכות כמו שפגמו בניו, וכבר למדנו (באות מ\"א). אמר לו, וגם אני הייתי סבור כך, אלא רציתי לשמוע ממך כדי ליישב הדברים."],[5,"א״ל אלעזר ברי וכו׳:","אמר לו, אלעזר בני, בוא וראה, כל הקרבנות וכל העולות הם נחת של הקב״ה, אבל אין הן נחת לפניו, כמו הקטורת, כי הקטרת משובחת היא מכל. ומשום זה היו מעלים אותה לפני ולפנים, לקדש הקדשים, בלחש. ולמדנו זה. ומשום זה לא נענשו כל האנשים בשאר הקרבנות ועולות כמו בקטרת, שכל עבודת הקב״ה, נתקטר ונתקשר כאן יותר מכל. וע״כ נקרא קטרת. כי קטרת היא התקשרות בלשון ארמי. וכן נאמר, שמן וקטרת ישמח לב."],[6,"פתח ר״ש ודרש וכו׳:","פתת ר״ש ודרש, לריח שמניך טובים וגו'. מקרא זה הסתכלתי בו, וכך הוא. \u0003לריח,\u0004 מהו ריח. הוא, כי ריח הקטרת הוא דק ומשובח ופנימי יותר מכל, וכשעולה הריח ההוא להתקשר, באותו שמן המשחה של נחלי המבוע, שהם ספירות דז״א, מעירים זה בזה ומתקשרים יחד. ואז שמנים אלו טובים להאיר. כש״א לריח שמניך טובים."],[6,"","פירוש שמן ה״ס חסדים, וריח ה״ס הארת החכמה המאיר ממטה למעלה, מן המלכות. וחכמה זו אינה מאירה אלא בהתלבשות החסדים דז\"א. וע״י הקטרת מעלים הריח הזה מן מלכות אל חסדים דז״א להתלבש בהם, וגם החסדים דז״א, שנקראים שמנים, מתגלים ע״י הארת החכמה. וז״ש \u0003וכד סליק ההוא ריח לאתקשרא\u0004 וכו' \u0003אתערו דא בדא,\u0004 וכו', והריח שה״ס הארת חכמה מתקשר בשמן, והשמן שהוא חסדים מתגלה בהארת חכמה על ידי קליטת הריח. וז\"ש, \u0003וכדין אינון משחן טבאן לאנהרא,\u0004 שע״י קליטת הריח הם טובים להאיר."],[7,"וכדין אתרק משחא וכו׳:","ואז הורק השמן ממדרגה למדרגה, באלו המדרגות הנקראים שם הקדוש, שהוא המלכות, ז״ש, שמן תורק, שמך על כן עלמות אהבוך. מהו עלמות. כמו שהעמדנו עולמות, הם עולמות ממש. כי כיון שהשמן הורק אל המלכות שנקראת שם, מקבלים ממנה כל העולמות. פירוש אחר, על כן עלמות אהבוך. הוא כש״א, על עלמות שיר. דהיינו מדרגות שהן בבחינת חסדים, הנקראות עלמות מלשון העלם (כמ״ש לעיל ויצא אות רנ״ו ע״ש) והכל אחד הוא. כי השם עולמות הוא ג״כ על שהם נעלמים."],[8,"ובספרא דרב המנונא וכו׳:","ובספרו של רב המנונא סבא כתוב, מהו עולמות. הוא כש״א, ותתן טרף לביתה וחק לנערותיה, שה״ס ז׳ היכלות דבריאה המשמשים את המלכות, ונקראות ז׳ נערות (כנ״ל ויקהל ל׳ ד\"ה פירוש), נערותיה אלו, שהן עלמות, אהבוך, לברך שמך, ולזמר לפניך, ומשם נמצאות ברכות בכל התחתונים, ומתברכים העליונים והתחתונים."]],[[0,"","יִשִׁ זְמַנִּים בַּשָּׁבוּעוֹת שֶׁרְצוֹנוֹת נִמְצָאִים, וְיֵשׁ זְמַנִּים בַּשָּׁבוּעוֹת שֶׁדִּינִים נִמְצָאִים בָּעוֹלָם. וְיֵשׁ זְמַנִּים בַּיָּמִים שֶׁנִּמְצָא רָצוֹן בָּעוֹלָם וְהָעוֹלָם מִתְבַּשֵּׂם. וְיֵשׁ זְמַנִּים בַּיָּמִים שֶׁהַדִּינִים תְּלוּיִים וְנִמְצָאִים, וַאֲפִלּוּ בְּשָׁעוֹת, וְעַל זֶה כָּתוּב (קהלת ג) וְעֵת לְכָל חֵפֶץ וְגוֹ'. וְכָתוּב (תהלים סט) וַאֲנִי תְפִלָּתִי לְךְ וְגוֹ'. וְכָתוּב (ישעיה נח) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ. וְכָתוּב (תהלים י) לָמָה ה' תַּעֲמֹד בְּרָחוֹק תַּעְלִים לְעִתּוֹת בַּצָּרָה. וְכָתוּב (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי. וְלִפְעָמִים שֶׁהוּא קָרוֹב, שֶׁכָּתוּב (תהלים קמה) קָרוֹב ה' לְכָל קֹרְאָיו. מִשּׁוּם כָּךְ, וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ וְגוֹ'."],[1,"","רַבִּי שִׁמְעוֹן אָמַר, הֲרֵי בֵּאַרְנוּ הַדָּבָר בְּעִתּוֹ, וְכָךְ הוּא וַדַּאי, וְכָאן הַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהַזְהִיר אֶת אַהֲרֹן שֶׁלֹּא יִטְעֶה בְּאוֹתוֹ חֵטְא שֶׁטָּעוּ בָנָיו, שֶׁהֲרֵי הָעֵת הַזּוֹ יְדוּעָה, כְּדֵי שֶׁלֹּא יִטְעֶה לְחַבֵּר עֵת אַחֶרֶת לַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. כְּלוֹמַר, אַף עַל גַּב שֶׁיֵּרָאֶה זְמַן שֶׁנִּמְסָר לְיַד אַחֵר לְהַנְהִיג אֶת הָעוֹלָם וְיִמָּסֵר בְּיָדוֹ לְיַחֵד בּוֹ לְקָרְבוֹ לַקֹּדֶשׁ, שֶׁהֲרֵי אֲנִי וּשְׁמִי אֶחָד הוּא. וּמִשּׁוּם כָּךְ, (לקרב אותו להקדוש ברוך הוא, שהרי העת הזו ידועה. משום כך) וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְאִם רוֹצֶה לָדַעַת בַּמֶּה יִכָּנֵס - בְּזֹּאת. בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. שֶׁהַזֹּאת הַזּוֹ הִיא עֵת שֶׁאֲחוּזָה בִשְׁמִי, בַּי' הַזּוֹ שֶׁרְשׁוּמָה בִשְׁמִי יִכָּנֵס אֶל הַקֹּדֶשׁ, (אבל) וְאַל יָבֹא בְכָל עֵת."],[2,"","שָׁנִינוּ, אָמַר רַבִּי יוֹסֵי, כָּתוּב (קהלת ג) אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ. דָּבָר זֶה בֵּאֲרוֹ הַמְּנוֹרָה (בשם) הַקְּדוֹשָׁה, וְכָךְ הוּא שֶׁשָּׁנִינוּ, אֶת הַכֹּל עָשָׂה יָפֶה בְעִתּוֹ, וְכָךְ הוּא וַדַּאי. אֶת הַכֹּל וַדַּאי. עָשָׂה יָפֶה בְעִתּוֹ, זֶה עִם זֶה, שֶׁלֹּא יִתְעָרְבוּ אֲחֵרִים בֵּינֵיהֶם. בְעִתּוֹ מַמָּשׁ, וְלֹא בְאַחֵר. מִשּׁוּם כָּךְ אַזְהָרָה לְאַהֲרֹן, וְאַל יָבא בְכָל עֵת אֶל הַקֹּדֶשׁ. אֲבָל בַּמֶּה יִכָּנֵס? בְּזֹּאת, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ."],[3,"","רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי אָבִיו. אָמַר לוֹ, כָּתוּב בַּעֲדַת קֹרַח, וַיֹּאבְדוּ מִתּוֹךְ הַקָּהָל. מַה זֶּה וַיֹּאבְדוּ? אֶלָּא כְּמוֹ שֶׁכָּתוּב, (במדבר טז) וְהַאֲבַדְתִּי אֶת הַנֶּפֶשׁ הַהִיא מִקֶּרֶב עַמָּהּ. (כתוב בבני אהרן, (שם י) ותצא אש מלפני ה' ותאכל אותם וימתו. וכתוב בעדת קרח, ואש יצאה מאת ה' ותאכל את החמשים ומאתים איש. היעלה בדעתך ששקולים אלה כאלה ?!) אָמַר רַבִּי שִׁמְעוֹן, שׁוֹנִים בְּנֵי אַהֲרֹן, שֶׁלֹּא כָתוּב בָּהֶם אֲבֵדָה כְּאוֹתָם שֶׁל עֲדַת קֹרַח שֶׁכָּתוּב בָּהֶם, וַיֹּאבְדוּ מִתּוֹךְ הַקָּהָל, וְכָתוּב (במדבר יז) הֵן גָּוַעְנוּ אָבַדְנוּ כֻּלָּנוּ אָבָדְנוּ. לְהַכְלִיל אֶת אוֹתָם שֶׁהִקְרִיבוּ קְטֹרֶת בְּשָׂמִים, מָאתַיִם וַחֲמִשִׁים שֶׁאָבְדוּ וַדַּאי, וְאֵלֶּה (נדב ואביהוא) לֹא אָבְדוּ."],[4,"","אָמַר לוֹ, כָּתוּב וְאַל יָבֹא בְכָל עֵת אֶל הַקֹּדֶשׁ. וְכָתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ. כֵּיוָן שֶׁאָמַר וְאַל יָבא בְכָל עֵת, לָמָּה לֹא כָתוּב בְּאֵיזֶה זְמַן יִכָּנֵס? אָמַר לוֹ (רבי) אֶלְעָזָר, הֲרֵי נֶאֱמַר, וְדָבָר אֶחָד הוּא, וּזְמַן אֶחָד הוּא שֶׁיָּדְעוּ הַכֹּהֲנִים. אֲבָל עַל מַה שֶּׁחָטְאוּ בָנָיו רָצָה לְהַזְהִיר כָּאן, וַהֲרֵי זֶה נִתְבָּאֵר. אָמַר לוֹ, וַאֲנִי כָּךְ סָבַרְתִּי, וּכְדֵי לְיַשֵּׁב אֶת הַדָּבָר רָצִיתִי."],[5,"","אָמַר לוֹ, אֶלְעָזָר בְּנִי, בֹּא רְאֵה, כָּל הַקָּרְבָּנוֹת וְכָל הָעוֹלוֹת נַחַת הֵם לַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל לֹא הָיְתָה נַחַת כְּמוֹ הַקְּטֹרֶת הַזּוֹ, שֶׁהַקְּטֹרֶת הִיא מְעֻלָּה מֵהַכֹּל, וּמִשּׁוּם כָּךְ הָיוּ מַכְנִיסִים אוֹתָהּ לִפְנַי וְלִפְנִים בְּלַחַשׁ, וַהֲרֵי זֶה נִתְבָּאֵר. וּמִשּׁוּם כָּךְ לֹא נֶעֶנְשׁוּ כָּל בְּנֵי הָאָדָם בִּשְׁאָר הַקָּרְבָּנוֹת וְהָעוֹלוֹת כְּמוֹ בַּקְּטֹרֶת, שֶׁכָל הָעֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן נִקְשְׁרֶת וְנִקְטֶרֶת יוֹתֵר מֵהַכֹּל, וְלָכֵן נִקְרֵאת קְטֹרֶת. וַהֲרֵי נֶאֱמַר, (משלי כז) שֶׁמֶן וּקְטֹרֶת יְשַׂמַּח לֵב."],[6,"","פָּתַח רַבִּי שִׁמְעוֹן וְדָרַשׁ, (שיר א) לְרֵיחַ שְׁמָנֶיךְ טוֹבִים וְגוֹ'. בַּפָּסוּק הַזֶּה הִסְתַּכַּלְתִּי, וְכָךְ הוּא: לְרֵיחַ, מַה זֶּה לְרֵיחַ? רֵיחַ הַקְּטֹרֶת שֶׁהוּא דַּק וּמְעֻלֶּה וּפְנִימִי מֵהַכֹּל, וּכְשֶׁעוֹלֶה אוֹתוֹ הָרֵיחַ לְהִתקַשֵּׁר בְּאוֹתוֹ שֶׁמֶן מִשְׁחָה שֶׁל הַנְּחָלִים הַנּוֹבְעִים, מִתְעוֹרְרִים זֶה עִם זֶה וְנִקְשָׁרִים כְּאֶחָד. וְאָז הֵם שְׁמָנִים טוֹבִים לְהָאִיר, כְּמוֹ שֶׁנֶּאֱמַר לְרֵיחַ שְׁמָנֶיךְ טוֹבִים."],[7,"","וְאָז מוּרָק שֶׁמֶן מִדַּרְגָּה לְדַרְגָּה בְּאוֹתָן הַדְּרָגוֹת שֶׁנִּקְרָאוֹת הַשֵּׁם הַקָּדוֹשׁ. זֶהוּ שֶׁכָּתוּב שֶׁמֶן תּוּרַק שְׁמֶךְ עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ. מַה זֶּה עֲלָמוֹת? כְּמוֹ שֶׁבֵּאַרְנוּ עוֹלָמוֹת, עוֹלָמוֹת מַמָּשׁ. דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ - כְּמוֹ שֶׁנֶּאֱמַר (תהלים מו) עַל עֲלָמוֹת שִׁיר, וְהַכֹּל אֶחָד."],[8,"","וּבְסִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא כָּתוּב, מַה זֶּה עֲלָמוֹת? כְּמוֹ שֶׁנֶּאֱמַר (משלילא) וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. נַעֲרֹתֶיהָ אֵלּוּ הָעֲלָמוֹת. אֲהֵבוּךְ, לְבָרֵךְ אֶת שִׁמְךְ וּלְזַמֵּר לְפָנֶיךְ, וּמִשָּׁם יוֹצְאוֹת בְּרָכוֹת בְּכָל הַתַּחְתּוֹנִים, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים."]]],[["דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. שַׁפִּיר הוּא מַאן דְּאָמַר. עַל מָוְת אֲהֵבוּךָ, דְּהָא בְּמִלָּה דָּא מָארֵיהוֹן דְּדִינִין אִתְבַּסְּמָן, וּבְגִין דְּהַאי קְטֹרֶת, אִתְקְטַר בְּמִשְׁחָא דִּלְעֵילָּא יַתִּיר, אִתְחֲשָׁב קָמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, מִכָּל קָרְבְּנִין וְעִלָּוָון. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל, אֲנָא כִּקְטֹרֶת, וְאַנְתְּ כְּמִשְׁחָא, מָשְׁכֵנִי אַחֲרֶיךָ נָרוּצָה וְגוֹ'. נָרוּצָה: כְּמָה דְאַתְּ אָמֵר, עַל כֵּן עֲלָמוֹת אֲהֵבוּךָ. אֲנָא וְכָל אוּכְלוּסִין, דְּהָא כֻּלְּהוּ בִּי אֲחִידָן, וְעַל דָּא מָשְׁכֵנִי, דְּהָא בִּי תַּלְיָין.","הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. אִם יֵיעוּל לִי מַלְכָּא בְּאִדָרוֹי, נָגִילָה וְנִשְׂמְחָה בָּךְ, אֲנָא וְכֻלְּהוּ אוּכְלוּסִין. תָּאנָא. כֻּלְּהוּ אוּכְלוּסִין, בְּשַׁעֲתָא דִּכְנֶסֶת יִשְׂרָאֵל חַדָּאת וּמִתְבָּרְכָא, כֻּלְּהוּ חַדָּאן, וְדִינָא לָא שַׁרְיָא כְּדֵין בְּעָלְמָא. וְעַל דָּא כְּתִיב, (תהילים צ״ו:י״א) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ.","כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. אָמַר רִבִּי יְהוּדָה, זַכָּאִין אִינּוּן צַדִּיקַיָּא, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן. וְתָנֵינָא, מֶלֶךְ בָשָׂר וָדָם, אִי בַּר נָשׁ רָכִיב עַל סוּסְיָא דִּילֵיהּ, בַּר קַטָלָא הוּא, קוּדְשָׁא בְּרִיךְ הוּא אַרְכִּיב אֵלִיָּהוּ עַל דִּילֵיהּ, דִּכְתִיב, (מלכים ב ב׳:י״א) וַיָּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָׁמָיִם וְגוֹ'. הָכָא מַאי כְּתִיב, וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וְקוּדְשָׁא בְּרִיךְ הוּא עַיְילֵיהּ לְמֹשֶׁה בֵּיהּ, הֲדָא הוּא דִכְתִיב, (שמות כ״ד:י״ח) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, בְּתוֹךְ הֶעָנָן מַמָּשׁ, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. הֲדָא הוּא דִכְתִיב, (ישעיהו ד׳:ה׳) וּבָרָא יְיָ' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶיהָ עָנָן יוֹמָם וְעָשָׁן. וּכְתִיב, (שמות מ׳:ל״ח) כִּי עָנָן יְיָ' עַל הַמִּשְׁכָּן יוֹמָם.","וְתָאנָא, הַאי דִּכְתִּיב, (שמות לד) וַיֵּרֶד יְיָ' בֶּעָנָן. בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. תָּאנָא, אֲתַר דַּהֲווֹ שָׁרָאן אִינּוּן כְּרוּבֵי, כְּמָה דְּאוֹקִימְנָא, כְּרוּבִים עַל אָת הֲווֹ יַתְבִין. וְתָאנָא, ג' זִמְנִין בְּיוֹמָא אִתְרְחִישׁ נִיסָא, בְּגַדְפַיְיהוּ. בְּשַׁעֲתָא דְּאִתְגְּלֵי עָלַיְיהוּ קְדוּשָּׁה דְּמַלְכָּא, אִינּוּן מִגַּרְמַיְיהוּ סַלְּקִין גַּדְפַּיְיהוּ, וּפַרְסִין לוֹן, וְחַפְּיָין עַל כַּפּוֹרְתָא. לְבָתַר קְמִיטִין גַּדְפַיְיהוּ, וְנֶאֱחָזִין בְּגַּדְפַיְיהוּ (ס\"א ונאחזין בגופייהו) כְּמָה דְאַתְּ אָמֵר (שמות כ״ה:כ׳) וְהָיוּ הַכְּרוּבִים פּוֹרְשֵׂי כְנָפַיִם לְמַעְלָה, פּוֹרְשֵׂי וְלָא פְּרוּשֵׂי. סוֹכְכִים וְלָא סְכוּכִים. דָּא בְּאָת (ס\"א בזאת) הֲווֹ קַיְימֵי וְחַדָּאן בִּשְׁכִינְתָּא.","אָמַר רִבִּי אַבָּא, מַה בָּעָא הָכָא, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וּכְתִיב בְּזֹאת יָבֹא אַהֲרֹן, וְהָא כַּהֲנָא לָא חָמֵי לִשְׁכִינְתָּא בְּשַׁעֲתָא כַּד הֲוָה עָאל. אֶלָּא עֲנָנָא הֲוָה נָחִית, וְכַד הֲוָה נָחִית מָטָא עַל הַאי כַּפֹּרֶת, וּמִתְעָרִין גַּדְפַּיְיהוּ דִּכְרוּבִין, וְאַקְשֵׁי לְהוּ וְאַמְרֵי שִׁירָתָא.","וּמַה שִׁירָתָא אַמְרֵי (תהילים צ״ו:ד׳) כִּי גָּדוֹל יְיָ' וּמְהֻלָּל מְאֹד נוֹרָא הוּא עַל כָּל אֱלֹהִים. הַאי כַּד סַלְקֵי גַּדְפַּיְיהוּ. בְּשַׁעֲתָא דְּפַרְסִין לְהוּ אַמְרֵי, (תהילים צ״ו:ה׳) כִּי כָּל אֱלֹהֵי הָעַמִּים אֱלִילִים וַיְיָ' שָׁמַיִם עָשָׂה. כַּד חַפְיָין עַל כַּפּוֹרְתָא, אַמְרֵי, (תהילים צ״ח:ט׳) לִפְנֵי יְיָ' כִּי בָא לִשְׁפּוֹט אֵת הָאָרֶץ יִשְׁפּוֹט תֵּבֵל בְּצֶדֶק וְעַמִּים בְּמֵישָׁרִים.","וְקַלְהוֹן הֲוָה שָׁמַע כַּהֲנָא בְּמַקְדְּשָׁא, כְּדֵין שַׁוִּי קְטֹרֶת בְּאַתְרֵיהּ, וְאִתְכְּוָון בְּמָה דְּאִתְכָּוַּון, בְּגִין דְּיִתְבְּרַךְ כֹּלָּא (וקלהון). וְגַדְפֵּי כְּרוּבְיָיא, סַלְּקִין וְנַחְתִּין, וְזַמְרֵי שִׁירָתָא, מְחַפְּיָין לְכַפּוֹרְתָּא וְסַלְקֵי לְהוּ. הֲדָא הוּא דִכְתִיב סוֹכְכִים. סוֹכְכִים דַּיְיקָא ומְנָא לָן דְּקַלֵהוֹן אִשְׁתְּמַע, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל וְגוֹ'.","אָמַר רִבִּי יוֹסֵי, וְעַמִּים בְּמֵישָׁרִים. מַהוּ בְּמֵישָׁרִים. כְּמָה דְאַתְּ אָמֵר, מֵישָׁרִים אֲהֵבוּךָ, לְאַכְלְלָא תְּרֵין כְּרוּבִין, דְּכַר וְנוּקְבָּא, מֵישָׁרִים וַדַּאי. וְעַל דָּא, וְעַמִּים בְּמֵישָׁרִים.","וּכְתִיב, (במדבר ז׳:פ״ט) וְיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו מִבֵּין שְׁנֵי הַכְּרוּבִים וַיְדַבֵּר אֵלָיו. רִבִּי יִצְחָק אָמַר, מִכָּאן אוֹלִיפְנָא דִּבְכָל אֲתַר דְּלָא אִשְׁתְּכַח דְּכַר וְנוּקְבָּא, לָאו כְּדַאי לְמֵחֱמֵי אַפֵּי שְׁכִינְתָּא. הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ, וְתָנֵינָן, כְּתִיב, (דברים ל״ב:ד׳) צַדִּיק וְיָשָׁר הוּא, דְּכַר וְנוּקְבָּא, אוּף הָכָא כְּרוּבִים דְּכַר וְנוּקְבָּא. וְעָלַיְיהוּ כְּתִיב, (תהילים צ״ט:ד׳) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וְעַמִּים בְּמֵישָׁרִים. וּבְגִּינֵי כַּךְ, (שמות כ״ה:כ׳) וּפְנֵיהֶם אִישׁ אֶל אָחִיו, וְהָא אוֹקִימְנָא."],[[0,"ד\"א על כן עלמות אהבוך:","פירוש אחר, ע״כ עלמות אהבוך, יפה הוא מי שפירש על מות אהבוך, כי בדבר זה, דהיינו שמן, שהוא חסדים, בעלי הדין מתבשמים, כי עלמות היא אותיות על מות. פירוש, כשהחכמה שבמלכות היא בלי חסדים, נמשכים ממנה דינים קשים \u0003כמות,\u0004 (כנ״ל ב״א דף מ״ז אות ל\"ד ד״ה נפק) ובשביל זה המלכות ומדרגותיה אוהבים להתדבק בז״א שהוא חסדים, ודש על \u0003מות\u0004 אהבוך. כי הפירוד ממך קשה כמות. כי הקטרת הזו, שהיא הארת חכמה, מתקשרת בשמן של מעלה ביותר, שהוא חסדים, וחשובה לפני הקב״ה, מכל הקרבנות והעולות. אמרה כנסת ישראל, שהיא המלכות, אני כקטרת, כי המלכות ה״ס חכמה תתאה, ואתה, דהיינו ז״א, כשמן, שהוא חסדים, ע״כ, משכני אחריך נרוצה וגו'. \u0003נרוצה,\u0004 בלשון רבים, הוא כש״א, על כן עלמות אהבוך, דהיינו אני וכל חיילותי, כי כולם נאחזים בי. וע״כ \u0003משכני,\u0004 כי הם תלוים בי."],[1,"הביאני המלך חדריו:","אם יביא אותי המלך בחדריו, \u0003נגילה ונשמחה בך,\u0004 היינו אני וכל חיילותי. למדנו. כל החיילות, בשעה שכנסת ישראל שמחה ומתברכת, כולם שמחים, והדין אינו שורה אז בעולם. וע״כ כתוב, ישמחו השמים ותגל הארץ."],[2,"כי בענן אראה על הכפרת:","א״ר יהודה, אשרי הם הצדיקים שהקב״ה חפץ ביקרם. ולמדנו, מלך בשר ודם, אם אדם רוכב על סוס שלו, בן מות הוא, והקב״ה הרכיב את אליהו על שלו, שכתוב, ויעל אליהו \u0003בסערה\u0004 השמים וגו'. וכתוב, ויען ה׳ את איוב מן \u0003הסערה.\u0004 (איוב ל״ח). כאן מה כתוב, ולא ימות כי בענן אראה על הכפרת. והקב״ה הכניס את משה בענן, ז״ש, ויבא משה בתוך \u0003הענן,\u0004 בתוך הענן ממש, שהוא מלכות, באותו הענן שכתוב בו, כי בענן אראה על הכפרת. ז״ש, וברא ה׳ על כל מכון הר ציון ועל מקראיה ענן יומם ועשן. וכתוב, כי ענן ה׳ על המשכן יומם. שכל אלו עננים רומזים על המלכות."],[3,"ותאנא האי דבתיכ וכו׳:","ולמדנו, זה שכתוב, וירד ה׳ בענן. בענן אראה על הכפרת, למדנו, שהוא המקום דהיינו מלכות, שהיו שורים בו אלו הכרובים, שהם מטטרון וסנדלפון, כמו שלמדנו, הכרובים היו יושבים על נס, דהיינו על המלכות הנקראת נס, ולמדנו ג' פעמים ביום שה״ס ג׳ קוין, קרה נס, דהיינו שנתגלתה השכינה בכנפיהם. בשעה שנתגלתה עליהם קדושת המלך, הם מעצמם העלו כנפיהם, ופורשים אותן, ומכסים על הכפרת. ואחר כך סוגרים כנפיהם, ונאחזים בגופם. כש״א והיו הכרובים \u0003פורשי\u0004 כנפים למעלה, \u0003פורשי\u0004 כתוב, שהמשמעות שפעם \u0003פורשים\u0004 ופעם סוגרים, ולא כתוב, פרושי. כי אם היו בלתי פועלים היה צריך לומר פרושי. וכן, סוככים, ולא סכוכים. זהו שאמרו, בנס היו עומדים, ושמחים בשכינה."],[4,"א״ר אבא מה וכו׳",": אר״א, מה רוצה כאן הכתוב, כי בענן אראה על הכפורת. שמשמע שהכהן רואה השכינה. וכן ב \u0003זאת\u0004 יבא אהרן, שהיא השכינה הנקראת זאת. והרי הכהן לא ראה את השכינה בשעה שהיה נכנס לקדש הקדשים. ומשיב. אלא הענן שהוא השכינה, היה יורד, וכשהיה יורד ומגיע על הכפרת, מתעוררות כנפי הכרובים והיו דופקות בכנפיהם ואומרים שירה. ומכאן היה יודע הכהן, שהשכינה נראית כאן. ועל זה נאמר, כי בענן אראה על הכפרת."],[5,"ומה שירתא אמרי וכו׳:","שואל, איזו שירה היו אומרים, ומשיב, כי גדול ה׳ ומהלל מאד נורא הוא על כל אלקים. את זה היו אומרים כשמעלים כנפיהם. והוא בחינת קו ימין, דהיינו חסד הנקרא גדול. ובשעה שפורשים אותם היו אומרים, כי כל אלהי העמים אלילים וה' שמים עשה. והוא בחינת קו שמאל, המכניע את הס״א כולו. וכשמכסים על הכפורת, היו אומרים, לפני ה׳ כי בא לשפוט הארץ ישפוט תבל בצדק ועמים במישרים. והוא בחינת קו האמצעי, דהיינו ת״ת הנקרא משפט."],[6,"וקלהון הוה שמע וכו׳:","ואת קולם היה שומע הכהן בבית המקדש, אז נתן הקטרת במקומה, ונתכוון במה שנתכוון, כדי שיתברך הכל. וכנפי הכרובים היו עולות ויורדות, ומזמרות שירה ומכסות הכפורת ומעלים אותן. ו\"ש, סוככים סוככים הוא בדיוק (כנ״ל אות נ\"ב). ומאין לנו שקולם נשמע. היינו כש״א, ואשמע את קול כנפיהם וגו'."],[7,"אמר ר׳ יוסי וכו׳:","אר״י, ועמים במישרים, מהו במישרים. ומשיב, הוא כש״א \u0003מישרים אהבוך,\u0004 שהשכינה כוללת בזה שני הכרובים, שהם מטטרון וסנדלפון, הנקראים ודאי מישרים. וע״כ אומר, ועמים במישרים. שלפני כן אוה״כ, ישפוט תבל בצדק. אשר ישפוט הוא ז\"א, צדק הוא המלכות. ואח״כ כולל הכתוב גם את הכרובים, ואומר ועמים במישרים."],[8,"וכתיב וישמע וגו׳:","וכתוב, וישמע את הקול מדבר אליו מבין שני הכרובים וידבר אליו. ר׳ יצחק אמר, מכאן למדנו, שבכל מקום שלא נמצאים זכר ונקבה, אינו כדאי לראות פני השכינה. כי ע״כ שמע את הקול מדבר רק מבין שני הכרובים. ז״ש ישבו ישרים את פניך, דהיינו הכרובים שנקראים מישרים. ולמדנו, כתוב צדיק וישר הוא, שהם דכר ונוקבא, כי צדיק הוא דכר, דהיינו יסוד, וישר הוא נוקבא דהיינו מלכות. אף כאן הכרובים הם זכר ונקבה. ועליהם כתוב, אתה כוננת מישרים. וכן ועמים במישרים כנ״ל. ומשום זה, ופניהם איש אל אחיו. שה״ס זווג פנים בפנים. והרי העמדנו."]],[[0,"","דָּבָר אַחֵר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ - יָפֶה הוּא מִי שֶׁאָמַר, עַל מָוֶת אֲהֵבוּךְ. שֶׁהֲרֵי בַּדָּבָר הַזֶּה בַּעֲלֵי הַדִּינִים מִתְבַּשְּׂמִים, וּבִשְׁבִיל שֶׁהַקְּטֹרֶת הַזּוֹ נִקְשֶׁרֶת בַּשֶּׁמֶן שֶׁלְּמַעְלָה יוֹתֵר, נֶחְשֶׁבֶת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל הַקָּרְבָּנוֹת וְהָעוֹלוֹת. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל: אֲנִי כִּקְטֹרֶת וְאַתָּה כְּשֶׁמֶן, מָשְׁכֵנִי אַחֲרֶיךְ נָרוּצָה וְגוֹ'. נָרוּצָה, כְּמוֹ שֶׁנֶּאֱמַר עַל כֵּן עֲלָמוֹת אֲהֵבוּךְ, אֲנִי וְכָל הָאוּכְלוּסִים, שֶׁהֲרֵי כֻּלָּם אֲחוּזִים בִּי, וְלָכֵן מָשְׁכֵנִי, שֶׁהֲרֵי בִּי הֵם תְּלוּיִים."],[1,"","הֱבִיאַנִי הַמֶּלֶךְ חֲדָרָיו. אִם יַכְנִיס אוֹתִי לַחֲדָרָיו, נָגִילָה וְנִשְׂמְחָה בָּךְ, אֲנִי וְכָל הָאוּכְלוּסִים. שָׁנִינוּ, כָּל הָאוּכְלוּסִים בְּשָׁעָה שֶׁכְּנֶסֶת יִשְׂרָאֵל שְׂמֵחָה וּמִתְבָּרֶכֶת, כֻּלָּם שְׂמֵחִים, וְאָז הַדִּין לֹא שָׁרוּי בָּעוֹלָם. וְעַל זֶה כָּתוּב (תהלים צו) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ."],[2,"","כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם. וְשָׁנִינוּ, מֶלֶךְ בָּשָׂר וָדָם, אִם אָדָם רוֹכֵב עַל סוּסוֹ, הוּא בֶּן מָוֶת, וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִרְכִּיב אֶת אֵלִיָּהוּ עַל שֶׁלּוֹ, שֶׁכָּתוּב (מלכים ב ב) וַיַּעַל אֵלִיָּהוּ בַּסֳעָרָה הַשָּׁמָיִם וְגוֹ'. כָּאן מַה כָּתוּב? וְלֹא יָמוּת כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. וְהַקָּדוֹשׁ בָּרוּךְ הוּא הִכְנִיסוֹ לְמֹשֶׁה בּוֹ, זֶהוּ שֶׁכָּתוּב (שמות כד) וַיָּבֹא מֹשֶׁה בְּתוֹךְ הֶעָנָן, בְּתוֹךְ הֶעָנָן מַמָּשׁ, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. זֶהוּ שֶׁכָּתוּב, (ישעיה ד) וּבָרָא ה' עַל כָּל מְכוֹן הַר צִיּוֹן וְעַל מִקְרָאֶהָ עָנָן יוֹמָם וְעָשָׁן. וְכָתוּב, (שמות מ) כִּי עֲנַן ה' עַל הַמִּשְׁכָּן יוֹמָם."],[3,"","וְלָמַדְנוּ, מַה שֶּׁכָּתוּב (שם לד) וַיֵּרֶד ה' בֶּעָנָן. בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת. לָמַדְנוּ, מָקוֹם שֶׁהָיוּ שׁוֹרִים הַכְּרוּבִים הַלָּלוּ, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁהַכְּרוּבִים עַל אוֹת הָיוּ יוֹשְׁבִים. וְלָמַדְנוּ, שָׁלֹשׁ פְּעָמִים בַּיּוֹם הִתְרַחֵשׁ נֵס בְּכַנְפֵיהֶם. בְּשָׁעָה שֶׁהִתְגַּלְּתָה עֲלֵיהֶם קְדֻשַּׁת הַמֶּלֶךְ, הֵם מֵעַצְמָם הָיוּ מַעֲלִים כַּנְפֵיהֶם וּפוֹרְשִׂים אוֹתָם וּמְכַסִּים עַל הַכַּפֹּרֶת. אַחר כָּךְ סוֹגְרִים כַּנְפֵיהֶם וְנֶאֱחָזִים בְּכַנְפֵיהֶם (ונאחזים בגופם), כְּמוֹ שֶׁנֶּאֱמַר (שם כה) וְהָיוּ הַכְּרֻבִים פֹּרְשֵׂי כְנָפַיִם לְמַעְלָה. פֹּרְשֵׂי וְלֹא פְּרוּשֵׂי. סֹכֲכִים וְלֹא סְכוּכִים. זֶה בְּאוֹת (בזאת) הָיוּ עוֹמְדִים וּשְׂמֵחִים עִם הַשְּׁכִינָה."],[4,"","אָמַר רַבִּי אַבָּא, מָה רָצָה כָּאן, כִּי בֶּעָנָן אֵרָאֶה עַל הַכַּפֹּרֶת, וְכָתוּב בְּזֹּאת יָבֹא אַהֲרֹן, וַהֲרֵי הַכֹּהֵן אֵינוֹ רוֹאֶה אֶת הַשְּׁכִינָה בְּשָׁעָה שֶׁנִּכְנָס? אֶלָּא עָנָן הָיָה יוֹרֵד, וּכְשֶׁהָיָה יוֹרֵד, מַגִּיעַ עַל הַכַּפֹּרֶת הַזּוֹ וּמִתְעוֹרְרִים כַּנְפֵי הַכְּרוּבִים, וּמַקִּישִׁים בָּהֶם וְאוֹמְרִים שִׁירָה."],[5,"","וְאֵיזוֹ שִׁירָה אוֹמְרִים? (תהלים צו) כִּי גָדוֹל ה' וּמְהֻלָּל מְאֹד נוֹרָא הוּא עַל כָּל אֱלֹהִים. זֶה כְּשֶׁמַּעֲלִים אֶת כַּנְפֵיהֶם. וּבְשָׁעָה שֶׁפּוֹרְשִׂים אוֹתָן, אוֹמְרִים, כִּי כָּל אֱלֹהֵי הָעַמִּים אֱלִילִים וַה' שָׁמַיִם עָשָׂה. כְּשֶׁמְּכַסִּים עַל הַכַּפֹּרֶת, אוֹמְרִים, לִפְנֵי ה' כִּי בָא לִשְׁפֹּט הָאָרֶץ יִשִׁפֹּט תֵּבֵל בְּצֶדֶק, וְעַמִּים בְּמֵישָׁרִים."],[6,"","וְקֹוֹלוֹתֵיהֶם הָיָה שׁוֹמֵעַ הַכֹּהֵן בַּמִּקְדָּשׁ, אָז שָׂם קְטֹרֶת בִּמְקוֹמָהּ, וּמִתְכַּוֵּן בַּמֶּה שֶׁמִּתְכַּוֵּן, כְּדֵי שֶׁיִּתְבָּרֵךְ הַכֹּל (וקולותיהם). וְכַנְפֵי הַכְּרוּבִים עוֹלִים וְיוֹרְדִים, וְשָׁרִים שִׁירִים, מְכַסִּים לַכַּפֹּרֶת וּמַעֲלִים לָהֶם. זֶהוּ שֶׁכָּתוּב סֹכְכִים. סֹכְכִים דַּוְקָא. וּמִנַּיִן לָנוּ שֶׁקּוֹלוֹתֵיהֶם נִשְׁמָעִים? כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וָאֶשְׁמַע אֶת קוֹל וְגוֹ'."],[7,"","אָמַר רַבִּי יוֹסֵי, וְעַמִּים בְּמֵישָׁרִים. מַהוּ בְּמֵישָׁרִים? כְּמוֹ שֶׁנֶּאֱמַר מֵישָׁרִים אֲהֵבוּךְ - לְהַכְלִיל שְׁנֵי כְרוּבִים, זָכָר וּנְקֵבָה, מֵישָׁרִים וַדַּאי. וְעַל זֶה, וְעַמִּים בְּמֵישָׁרִים."],[8,"","וְכָתוּב, (במדבר ז) וַיִּשְׁמַע אֶת הַקּוֹל מִדַּבֵּר אֵלָיו (וגו') מִבֵּין שְׁנֵי הַכְּרֻבִים וַיְדַבֵּר אֵלָיו. רַבִּי יִצְחָק אָמַר, מִכָּאן לָמַדְנוּ, שֶׁבְּכָל מָקוֹם שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, אֵינוֹ כְּדַאי לִרְאוֹת פְּנֵי שְׁכִינָה. זֶהוּ שֶׁכָּתוּב (תהלים קמ) יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ, וְשָׁנִינוּ, כָּתוּב (דברים לב) צַדִּיק וְיָשָׁר הוּא, זָכָר וּנְקֵבָה, אַף כָּאן כְּרוּבִים זָכָר וּנְקֵבָה. וַעֲלֵיהֶם כָּתוּב, (תהלים צט) אַתָּה כּוֹנַנְתָּ מֵישָׁרִים. וְעַמִּים בְּמֵישָׁרִים. וּמִשּׁוּם כָּךְ, (שמות כה) וּפְנֵיהֶם אִישׁ אֶל אָחִיו, וַהֲרֵי בֵּאַרְנוּ."]]],[["תַּנְיָא אָמַר רִבִּי יוֹסֵי, זִמְנָא חֲדָא, הֲוָה צְרִיכָא עַלְמָּא לְמִטְרָא, אָתוּ לְקָמֵיהּ (ס\"א אזלו לגביה) דְּרַבִּי שִׁמְעוֹן, רִבִּי יֵיסָא וְרִבִּי חִזְקִיָּה וּשְׁאָר חַבְרַיָּיא. אַשְׁכְּחוּהוּ דְּהֲוָה אָזִיל לְמֵחֱמֵי, לְרִבִּי פִּנְחָס בֶּן יָאִיר, הוּא וְרִבִּי אֶלְעָזָר בְּרֵיהּ. כֵּיוָן דְּחָמָא לוֹן, פָּתַח וְאָמַר, (תהילים קל״ג:א׳) שִׁיר הַמַּעֲלוֹת הִנֵּה מַה טוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. מַאי שֶׁבֶת אַחִים גַּם יָחַד.","כְּמָה דְאַתְּ אָמֵר, וּפְנֵיהֶם אִישׁ אֶל אָחִיו, בְּשַׁעֲתָא דַּהֲווֹ חַד בְּחַד מַשְׁגִּיחִין אַנְפִּין בְּאַנְפִּין, כְּתִיב, מַה טוֹב וּמַה נָעִים. וְכַד מְהַדֵּר דְּכוּרָא אַנְפּוֹי מִן נוּקְבָּא, וַוי לְעָלְמָא. כְּדֵין כְּתִיב, (משלי י״ג:כ״ג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. בְּלֹא מִשְׁפָּט וַדַּאי, וּכְתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ, דְּלָא אָזִיל דָּא בְּלָא דָּא, וְכַד מִשְׁפָּט, מִתְרַחֵק מִצֶדֶק, וַוי לְעָלְמָא. (כדין כתיב, (משלי י״ג:כ״ג) ויש נספה בלא משפט).","וְהַשְׁתָּא חֲמֵינָא, דְּאַתּוּן אֲתִיתוּן, עַל דִּדְכוּרָא לָא שַׁרְיָא בְּנוּקְבָּא, אָמַר, אִי לְדָא אֲתִיתוּן גַּבָּאי תִּיבוּ. דְּהַאי יוֹמָא אִסְתַּכַּלְנָא, דְּיִתְהַדָר כֹּלָּא לְמִשְׁרֵי אַנְפִּין בְּאַנְפִּין. וְאִי לְאוֹרַיְיתָא אֲתִיתוּן, שָׁרוּ גַּבָּאי. אָמְרוּ לֵיהּ, לְכֹלָּא, קָא אֲתֵינָא לְגַבֵּי דְּמֹר, יִשְׁתְּמִיט חַד מִינָן, לְבַשְּׂרָא לַאֲחָנָא, שְׁאָר חַבְרַיָּיא, וַאֲנָן נֵתִיב לְקָמֵיהּ דְּמֹר.","עַד דַּהֲווֹ אַזְלֵי, פָּתַח וְאָמַר, (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, שְׁחוֹרָה אֲנִי בְּגָלוּתָא, וְנָאוָה אֲנִי בְּפִקּוּדֵי אוֹרַיְיתָא, דְּאַף עַל גַּב דְּיִשְׂרָאֵל בְּגָלוּתָא לָא שַׁבְקֵי לוֹן. כְּאָהֳלֵי קֵדָר, דְּאִינּוּן בְּנֵי קְטוֹרָה (ס\"א טורי), דְּאִתְקַדְּרוּ אַנְפַּיְיהוּ תְּדִירָא, וְעִם כָּל דָּא כִּירִיעוֹת שְׁלֹמֹה, כְּהַהוּא חֵיזוֹ שְׁמַיָא לְמִדְכֵּי, דִּכְתִּיב, (תהילים ק״ד:ב׳) נוֹטֶה שָׁמַיִם כַּיְרִיעָה.","אַל תִּרְאוּנִי שֶׁאֲנִי שְׁחַרְחוֹרֶת. מַאי טַעְמָא (ס\"א אני שחרחורת בגין ששזפתני) אַל תִּרְאוּנִי, בְּגִין שֶׁאֲנִי שֶׁחַרְחֹרֶת. שֶׁשְּׁזָפַתְנִי הַשָּׁמֶשׁ, דְּלָא אִסְתָּכַּל בִּי שִׁמְשָׁא, לְאַנְהָרָא לִי כְּדְקָא יֵאוֹת. יִשְׂרָאֵל מַה אִינּוּן אַמְרִין. בְּנֵי אִמִּי נִחֲרוּ בִּי. מַאן אִינּוּן בְּנֵי אִמִּי, אִלֵּין רַבְרְבִין מְמָנָן תְּרִיסִין עַל שְׁאָר עַמִּין.","דָּבָר אַחֵר, בְּנֵי אִמִּי מַמָּשׁ. כְּמָה דְאַתְּ אָמֵר, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ'. וְכַד הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ, שָׂמוּנִי נוֹטֵרָה אֶת הַכְּרָמִים. מַאי טַעְמָא. דְּכַרְמִי שֶׁלִּי לֹא נָטָרְתִּי. וְתָנֵינָן, בְּנֵי אִמִּי וַדַּאי אִסְתְכָּמוּ עָלַי, כְּלוֹמַר, כַּד אִתְעָדֵי אֶרֶץ, מִשָּׁמַיִם, כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (שמות ב׳:ד׳) וַתֵּתַצַּב אֲחוֹתוֹ מֵרָחוֹק.","וְהָכָא אִתְּמַר וַדַּאי, הִנֵּה מַה טוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. וּבְהוּ אוֹקִימְנָא (נ\"א והכא אוקימנא), גַּם יָחַד. כְּמָה דְאַתְּ אָמֵר (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם, שֶׁבֶת אַחִים בִּכְלַל, כֵּיוָן דִּכְתִּיב, גַּם, לְאַכְלְלָא כָּל אִינּוּן דִּלְעֵילָּא, דְּכָל שׁוּלְטָנוּתָא בְּהַהוּא אֲתַר אִשְׁתְּכַח.","דָּבָר אַחֵר. הִנֵּה מַה טּוֹב וּמַה נָעִים וְגוֹ'. אִלֵּין אִינּוּן חַבְרַיָּיא, בְּשַׁעֲתָא דְּאִינּוּן יַתְבִין כַּחֲדָא, וְלָא מִתְפָּרְשָׁן דָּא מִן דָּא. בְּקַדְמִיתָא אִתְחָזוּן גּוּבְרֵי מַגִּיחֵי קְרָבָא, דְּבָעוּ לְקָטְלָא דָּא לְדָא. לְבָתַר, אִתְהֲדָרוּ בִּרְחִימוּתָא דְּאַחְוָה. קוּדְשָׁא בְּרִיךְ הוּא מַהוּ אוֹמֵר, הִנֵּה מַה טּוֹב וּמַה נָעִים שֶׁבֶת אַחִים גַּם יָחַד. גַּם, לְאַכְלְלָא עִמְּהוֹן שְׁכִינְתָּא. וְלֹא עוֹד, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא אָצִית לְמִלּוּלַיְיהוּ, וְנִיחָא לֵיהּ וְחַדֵּי בְּהוּ. הֲדָא הוּא דִכְתִיב, (מלאכי ג׳:ט״ז) אָז נִדְבְּרוּ יִרְאֵי יְיָ' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב יְיָ' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו וְגוֹ'.","וְאַתּוּן חַבְרַיָּיא דְּהָכָא, כְּמָה דַּהֲוִיתוֹן בַּחֲבִיבוּתָא בִּרְחִימוּתָא, מִקַּדְמַת דְּנָא, הָכִי נָמֵי, מִכָּאן וּלְהָלְאָה לָא תִּתְפָּרְשׁוּן דָּא מִן דָּא, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא יַחְדֵּי עִמְּכוֹן, וְיִקְרֵי עָלַיְיכוּ שְׁלָם. וְיִשְׁתְּכַּח בְּגִינֵיכוֹן שְׁלָמָא בְּעָלְמָא. הֲדָא הוּא דִכְתִיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ.","אָזְלוּ. עַד דַּהֲווֹ אַזְלֵי, מָטוּ לְבֵי רִבִּי פִּנְחָס בֶּן יָאִיר. נָפַק רִבִּי פִּנְחָס, וּנְשָׁקֵיהּ. אָמַר, זָכֵינָא לְנַשְּׁקָא שְׁכִינְתָּא. זַכָּאָה חוּלָקִי אַתְקִין לְהוּ טִיקְלֵי דְּעַרְסֵי, קַפְטוּרֵי דְּקִילְטָא. אָמַר רִבִּי שִׁמְעוֹן, אוֹרַיְיתָא לָא בָּעֵי הָכִי, אַעְבָּר לְהוֹן, וְיָתִיבוּ. אָמַר רִבִּי פִּנְחָס, עַד לָא נֵיכוּל, נִשְׁמַע מִמָּארֵיהּ דְּאוֹרַיְיתָא מִלָּה. דְּהָא רַבִּי שִׁמְעוֹן כָּל מִלּוֹי בְּאִתְגַּלְיָיא אִינּוּן, אִיהוּ גַּבְרָא דְּלָא דָּחִיל מֵעֵילָּא וּמִתַתָּא, לְמֵימַר לוֹן, לָא דָּחִיל מֵעֵילָּא, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתָּכַּם בֵּיהּ, לָא דָּחִיל מִתַּתָּא, כְּאַרְיֵה דְּלָא דָּחִיל מִבְּנֵי עָנָא. אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר בְּרִיה, אֶלְעָזָר קוּם בְּקִיּוּמָךְ, וְאֵימָא מִלָּה חַדְתָּא, לְגַבֵּי דְּרִבִּי פִּנְחָס וּשְׁאָר חַבְרַיָּיא."],[[0,"תניא א״ר יוסי וכו׳:","למדנו אר״י, פעם אחת היה העולם צריך לגשמים, באו לפני ר׳ שמעון, ר׳ ייסא ור' חזקיה ושאר החברים. מצאוהו שהיה הולך הוא ובנו ר״א לראות את ר׳ פנחס בן יאיר. כיון שראה אותם, פתח ואמר, שיר המעלות הנה מה טוב ומה נעים שבת אחים גם יחד. שואל, מהו שבת אחים גם יחד."],[1,"כד״א ופניהם וגו׳:","ומשיב, הוא כש״א, ופניהם איש אל אחיו, אשר אחים פירושו דכר ונוקבא. כי בשעה שהיו ז״א ומלכות מסתכלים זה בזה פנים בפנים כתוב, מה טוב ומה נעים. וכשהדכר מחזיר פניו מן הנוקבא, אוי לעולם. אז כתוב, ויש נספה בלא משפט. בלא משפט ודאי, דהיינו בלא ז\"א הנקרא משפט, שאינו מסתכל ומשפיע אל הנוקבא הנקראת צדק. וכתוב, צדק ומשפט מכון כסאך, שאינו הולך זה בלא זה, וכשמשפט, שהוא ז\"א, מתרחק מצדק, שהוא מלכות, אוי לעולם."],[2,"והשתא חמינא דאתון וכו׳:","ועתה אני רואה, שאתם באתם, על מה שהדכר אינו שורה בנוקבא, שמשום זה אין גשמים בעולם. אמר, אם לזה באתם אלי, שובו. כי ביום הזה הסתכלתי שהכל יחזור לשרות פנים בפנים. ולא יחסר עוד שפע הגשמים בעולם. ואם באתם אלי ללמוד תורה, תשבו עמי. אמרו לו, לכל, באנו לאדוני, הן לגשמים והן ללמוד תורה, ילך אחד ממנו ויבשר לאחינו, ישועת הגשמים, שאר החברים, ואנו נשב לפני אדוני."],[3,"עד דהוו אזלי וכו׳:","בעוד שהיו הולכים, פתח ואמר, שחורה אני ונאוה בנות ירושלים וגו'. אמרה כנסת ישראל לפני הקב״ה, שחורה אני בגלות, ונאוה אני במצות התורה, שאע״פ שישראל בגלות אינם עוזבים את המצות. \u0003כאהלי קדר,\u0004 אע״פ שאני כאלו בני קטורה, שפניהם שחורים תמיד, ועם כל זה כיריעות שלמה, היינו כמראה השמים לטוהר, שכתוב נוטה שמים כיריעה. ושלמה זה הקב״ה, מלך שהשלום שלו"],[4,"אל תראוני שאני שחרחרת:","פירושו מהו הטעם אל תראוני, משום שאני שחרחרת. וע״כ לא תראוני. \u0003ששזפתני השמש\u0004 היינו כי לא נסתכל בי השמש, שהוא ז״א, להאיר לי כראוי. וישראל מה הם אומרים. \u0003בני אמי נחרו בי.\u0004 מי הם בני אמי, אלו הם השרים הממונים המגינים על שאר העמים."],[5,"ד״א בני אמי ממש:","פירוש אחר, שהשכינה אמרה, בני אמי ממש. שהם הספירות דז״א, שהם בני בינה, שהיא אם השכינה, כש״א, השליך משמים ארץ וגו'. וכשז״א השליך משמים ארץ שהיא השכינה, \u0003שמוני נוטרה את הכרמים.\u0004 שהם אומות העולם, שצריכה להשפיע לאומות העולם בשביל שישראל יזונו מהם. מהו הטעם. משום שכרמי שלי שהיא ישראל, לא נטרתי. כי חטאו. ולמדנו בני אמי ודאי, דהיינו ספירות דז״א, הסכימו עלי, להרחיקני. כלומר, בזה שהוסרה הארץ, שהיא המלכות, משמים, שהוא ז״א, כמו שהעמדנו שכתוב, ותתצב אחותו מרחוק. שהשכינה שנקראת אחותו דז״א, נתיצבה מרחוק, שהרחיקה ז״א."],[6,"והכא אתמר ודאי וכו׳:","וכאן, כנגד ותתצב אחותו מרחוק, נאמר ודאי, הנה מה טוב ומה נעים שבת אחים גם יחד, שהמלכות שהיא אחותו של ז״א לא תהיה מרחוק, אלא ביחד. ובהם, בז״א ומלכות, העמדנו, \u0003גם\u0004 יחד. כש״א, ואף \u0003גם\u0004 זאת בהיותם אשר \u0003גם,\u0004 ה״ס המלכות הנקראת זאת. וכן \u0003גם\u0004 יחד, היינו המלכות. אמנם בכלל שבת אחים היא, ולא היה צריך לכתוב \u0003גם,\u0004 וכיון שכתוב, \u0003גם,\u0004 הוא לכלול כל אלו שלמעלה, מז״א ומלכות, שהם ישסו״ת, שכל הממשלה היא נמצא במקום ההוא. בישסו״ת."],[7,"ד״א הנה מה וגו׳:","פירוש אחר. הנה מה טוב ומה נעים וגו'. אלו הם החברים, בשעה שיושבים יחד, ואינם נפרדים זה מזה. מתחילה הם נראים כאנשים עושי מלחמה, שרוצים להרוג זה את זה. ולאח״כ חוזרים להיות באהבת אחוה. הקב״ה מהו אומר עליהם, הנה מה טוב ומה נעים שבת אחים גם יחד. \u0003גם\u0004 בא לכלול עמהם השכינה. ולא עוד אלא הקב״ה מקשיב לדיבורם, ויש לו נתת והוא שמח בהם. ז״ש אז נדברו יראי ה׳ איש אל רעהו ויקשב ה׳ וישמע ויכתב ספר זכרון לפניו וגו'."],[8,"ואתון חברייא דהכא וכו׳:","ואתם החברים שבכאן, כמו שהייתם בחביבות באהבה מקודם לכן, גם מכאן ולהלאה לא תתפרדו זה מזה, עד שהקב״ה ישמח עמכם, ויקרא עליכם שלום, וימצא בזכותכם שלום בעולם. ז״ש, למען אחי ורעי אדברה נא שלום בך."],[9,"אזלו עד דהוו וכו׳:","הלכו. בעוד שהיו הולכים, הגיעו לבית ר׳ פנחס בן יאיר. יצא ר׳ פנחס בן יאיר, ונשקו, לר״ש. אמר, זכיתי לנשק את השכינה. אשרי חלקי. התקין להם מצעות המטה יקרי ערך. א״ר שמעון, התורה אינה צריכה כך, העביר את המצעות, וישבו. א״ר פנחס, מטרם שנאכל, נשמע מבעל התורה דבר. כי ר״ש כל דבריו בגלוי הם, הוא איש שאינו מתירא ממעלה ומלמטה לומר אותם, אינו מתירא מלמעלה, משום שהקב״ה הסכים עמו, אינו ירא מלמטה, כמו אריה שאינו מפחד מבני צאן. אמר ר״ש לרבי אלעזר בנו, אלעזר עמוד על עמדך, ואמור דבר חדש לר׳ פנחס ושאר החברים. \u0003טיקלי דערסי קפטורי דקילטא,\u0004 פירושו לפי הענין, מצעות המטה יקרי הערך."]],[[0,"","שָׁנִינוּ שֶׁאָמַר רַבִּי יוֹסֵי, פַּעַם אַחַת הָיָה צָרִיךְ הָעוֹלָם לְמָטָר, בָּאוּ לִפְנֵי (הלכו אצל) רַבִּי שִׁמְעוֹן רַבִּי יֵיסָא וְרַבִּי חִזְקִיָּה וּשְׁאָר הַחֲבֵרִים. מְצָאוּהוּ שֶׁהָיָה הוֹלֵךְ לִרְאוֹת אֶת רַבִּי פִּנְחָס בֶּן יָאִיר, הוּא וְרַבִּי אֶלְעָזָר בְּנוֹ. כֵּיוָן שֶׁרָאָה אוֹתָם, פָּתַח וְאָמַר, (תהלים קלג) שִׁיר הַמַּעֲלוֹת הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. מַה זֶּה שֶׁבֶת אַחִים גַּם יָחַד?"],[1,"","כְּמוֹ שֶׁנֶּאֱמַר וּפְנֵיהֶם אִישׁ אֶל אָחִיו. בְּשָׁעָה שֶׁהָיוּ אֶחָד עִם אֶחָד, מַשְׁגִּיחִים פָּנִים בְּפָנִים, כָּתוּב מַה טּוֹב וּמַה נָּעִים. וּכְשֶׁהַזָּכָר מַחֲזִיר פָּנָיו מִן הַנְּקֵבָה - אוֹי לָעוֹלָם, שֶׁאָז כָּתוּב, (משלייג) וְיֵשׁ נִסְפֶּה בְּלֹא מִשְׁפָּט. בְּלֹא מִשְׁפָּט וַדַּאי. וְכָתוּב (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ, שֶׁלֹּא הוֹלְכִים זֶה בְּלִי זֶה. וּכְשֶׁמִּשְׁפָּט מִתְרַחֵק מִצֶּדֶק - אוֹי לָעוֹלָם. (אז כתוב (משלי יג) ויש נספה בלא משפט)."],[2,"","וְעַכְשָׁו רָאִיתִי שֶׁאַתֶּם בָּאתֶם עַל שֶׁהַזָּכָר לֹא שׁוֹרֶה עִם הַנְּקֵבָה. אָמַר, אִם לְשֵׁם זֶה בָּאתֶם אֵלַי - שְׁבוּ, שֶׁהֲרֵי הַיּוֹם הִסְתַּכַּלְתִּי, שֶׁיַּחֲזֹר הַכֹּל פָּנִים בְּפָנִים לִשְׁרוֹת. וְאִם לַתּוֹרָה בָּאתֶם - שְׁבוּ לְפָנַי. אָמְרוּ לוֹ, לַכֹּל בָּאנוּ לִפְנֵי מוֹרֵנוּ, יִשְׁתַּמֵּט אֶחָד מֵאִתָּנוּ לְבַשֵּׂר לְאַחֵינוּ שְׁאָר הַחֲבֵרִים, וְאָנוּ נֵשֵׁב לִפְנֵי מוֹרֵנוּ."],[3,"","עַד שֶׁהָיוּ הוֹלְכִים, פָּתַח וְאָמַר, (שיר א) שְׁחוֹרָה אֲנִי וְנָאוָה בְּנוֹת יְרוּשָׁלָיִם וְגוֹ'. אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: שְׁחוֹרָה אֲנִי בַּגָּלוּת, וְנָאוָה אֲנִי בְּמִצְווֹת הַתּוֹרָה. שֶׁאַף עַל פִּי שֶׁיִּשְׂרָאֵל בַּגָּלוּת, אֵין עוֹזְבִים אוֹתָם. כְּאָהֳלֵי קֵדָר, שֶׁאוֹתָם בְּנֵי קְטוּרָה (הרים) שֶׁמְּקַדְּמִים פְּנֵיהֶם תָּמִיד, וְעִם כָּל זֶה - כִּירִיעוֹת שְׁלֹמֹה, כְּאוֹתוֹ מַרְאֵה הַשָּׁמַיִם לָטֹהַר, שֶׁכָּתוּב (תהלים קד) נוֹטֶה שָׁמַיִם כַּיְרִיעָה."],[4,"","אַל תִּרְאֻנִי שֶׁאֲנִי שְׁחַרְחֹרֶת. מָה הַטַּעַם (אני שחרחרת משום שזזפתני) אַל תִּרְאֻנִי? מִשּׁוּם שֶׁאֲנִי שְׁחַרְחֹרֶת. שֶׁשְּׁזָפַתְנִי הַשֶּׁמֶשׁ, שֶׁלֹּא הִסְתַּכֵּל עָלַי הַשֶּׁמֶשׁ לְהָאִיר לִי כָּרָאוּי. וּמַה יִּשְׂרָאֵל אוֹמְרִים? בְּנֵי אִמִּי נִחֲרוּ בִי. מִי הֵם אוֹתָם בְּנֵי אִמִּי? אֵלּוּ הַמְמֻנִּים הַגְּדוֹלִים הַמְגִנִּים עַל שְׁאָר הָעַמִּים."],[5,"","דָּבָר אַחֵר, בְּנֵי אִמִּי מַמָּשׁ, כְּמוֹ שֶׁנֶּאֱמַר (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ'. וּכְשֶׁהִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ, שָׂמֻנִי נֹטֵרָה אֶת הַכְּרָמִים. מָה הַטַּעַם? שֶׁכַּרְמִי שֶׁלִּי לֹא נָטָרְתִּי. וְשָׁנִינוּ, בְּנֵי אִמִּי וַדַּאי הִסְכִּימוּ עָלַי, כְּלוֹמַר, כְּשֶׁסָּרָה אֶרֶץ מִשָּׁמַיִם, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (שמות ב) וַתֵּתַּצַּב אֲחֹתוֹ מֵרָחֹק."],[6,"","וְכָאן נֶאֱמַר וַדַּאי, הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. וּבָהֶם בֵּאַרְנוּ (וכאן בארנו), גַּם יָחַד, כְּמוֹ שֶׁנֶּאֱמַר (ויקרא כו) וְאַף גַּם זֹּאת בִּהְיוֹתָם, שֶׁבֶת אַחִים בִּכְלָל, כֵּיוָן שֶׁכָּתוּב גַּם, לְהַכְלִיל כָּל אוֹתָם שֶׁלְּמַעְלָה, שֶׁכָל הַשִּׁלְטוֹן נִמְצָא בְּאוֹתוֹ מָקוֹם."],[7,"","דָּבָר אַחֵר הִנֵּה מַה טּוֹב וּמַה נָּעִים וְגוֹ' - אֵלּוּ אוֹתָם הַחֲבֵרִים בְּשָׁעָה שֶׁהֵם יוֹשְׁבִים כְּאֶחָד וְלֹא נִפְרָדִים זֶה מִזֶּה, בַּהַתְחָלָה הֵם נִרְאִים אֲנָשִׁים עוֹרְכֵי קְרָב שֶׁרוֹצִים לַהֲרֹג זֶה אֶת זֶה. אַחַר כָּךְ חוֹזְרִים לְאַהֲבָה וְאַחֲוָה. מָה אוֹמֵר הַקָּדוֹשׁ בָּרוּךְ הוּא? הִנֵּה מַה טּוֹב וּמַה נָּעִים שֶׁבֶת אַחִים גַּם יָחַד. גַּם - לְהַכְלִיל עִמָּהֶם שְׁכִינָה. וְלֹא עוֹד, אֶלָּא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַקְשִׁיב לְדִבְרֵיהֶם, וְיֵשׁ לוֹ נַחַת וְשָׂמֵחַ בָּהֶם. זֶהוּ שֶׁכָּתוּב (מלאכי ג) אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו וְגוֹ'."],[8,"","וְאַתֶּם הַחֲבֵרִים שֶׁל כָּאן, כְּמוֹ שֶׁהֱיִיתֶם בַּחֲבִיבוּת וְאַהֲבָה מִקֹּדֶם לָכֵן, כָּךְ גַּם מִכָּאן וָהָלְאָה לֹא תִפָּרְדוּ זֶה מִזֶּה, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יִשְׂמַח עִמָּכֶם, יִקְרָא עֲלֵיכֶם שָׁלוֹם, וְיִמָּצֵא בִגְלַלְכֶם שָׁלוֹם בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב, (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא שָׁלוֹם בָּךְ."],[9,"","הָלְכוּ, עַד שֶׁהָיוּ הוֹלְכִים, הִגִּיעוּ לְבֵית רַבִּי פִּנְחָס בֶּן יָאִיר. יָצָא רַבִּי פִּנְחָס וּנְשָׁקוֹ. אָמַר, זָכִיתִי לְנַשֵּׁק אֶת הַשְּׁכִינָה. אַשְׁרֵי חֶלְקִי. תִּקֵּן לָהֶם מַצְּעֵי מִטּוֹת בְּקִשְׁרֵי קְלִיעָה. אָמַר רַבִּי שִׁמְעוֹן, הַתּוֹרָה לֹא צְרִיכָה כָּךְ. הֶעֱבִיר אוֹתָם, וְיָשְׁבוּ. אָמַר רַבִּי פִּנְחָס, טֶרֶם שֶׁנֹּאכַל נִשְׁמַע מִבַּעַל הַתּוֹרָה דָּבָר, שֶׁהֲרֵי רַבִּי שִׁמְעוֹן, כָּל דְּבָרָיו הֵם בְּנִגְלֶה, הוּא אִישׁ שֶׁלֹּא פוֹחֵד מִמַּעְלָה וּמִמַּטָּה לוֹמַר אוֹתָם. לֹא פוֹחֵד מִמַּעְלָה, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. וְלֹא פוֹחֵד מִמַּטָּה, כְּמוֹ אַרְיֵה שֶׁלֹּא פוֹחֵד מִבְּנֵי הַצֹּאן. אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר בְּנוֹ, עֲמֹד בִּמְקוֹמְךְ וֶאֱמֹר דָּבָר חָדָשׁ אֶל רַבִּי פִּנְחָס וּשְׁאָר הַחֲבֵרִים."]]],[["קָם רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. הַאי קְרָא אִית לְאִסְתַּכְּלָא בֵּיהּ, דְּאִתְחֲזֵי דְּיַתִּירָא אִיהוּ. דְּהָא כְּתִיב בַּתְרֵיהּ, וַיֹאמֶר יְיָ' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךָ. מִכָּאן שֵׁירוּתָא דְּפַרְשְׁתָּא, הַאי קְרָא דִּלְעֵילָּא, מַאי הוּא, דִּכְתִּיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה. מַאי הוּא דְּאָמַר לֵיהּ, וּלְבָתַר וַיֹאמֶר יְיָ' אֶל מֹשֶׁה.","אֶלָּא בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב קְטֹרֶת בּוּסְמִין לְאַהֲרֹן, בָּעָא, דְּלָא יִשְׁתַּמֵשׁ בֵּיהּ בְּחַיּיוֹי בַּר נָשׁ אָחֳרָא. מַאי טַעְמָא. בְּגִין דְּאַהֲרֹן אַסְגֵּי שְׁלָמָא בְּעָלְמָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אַתְּ בָּעֵי לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא, עַל יְדָךְ יִסְגֵּי שְׁלָמָא לְעֵילָּא, הָא קְטֹרֶת בּוּסְמִין, יְהֵא מָסוּר בְּיָדְךָ מִכָּאן וּלְהָלְאָה, וּבְחַיֶּיךָ לָא יִשְׁתַּמֵשׁ בֵּיהּ בַּר נָשׁ אָחֳרָא. נָדָב וַאֲבִיהוּא אַקְדִימוּ בְּחַיֵּי דְּאָבוּהוֹן, לְאַקְרְבָא מַה דְּלָא אִתְמְסַר לְהוּ. וּמִלָּה דָּא, גָּרִים לְהוֹן דְּטָעוּ בֵּיהּ.","וְתָאנָא, מֹשֶׁה הֲוָה מְהַרְהֵר, מַאן גָּרַם לוֹן טָעוּתָא דָּא, וַהֲוָה עָצִיב. מַה כְּתִיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. וּמַה אָמַר לֵיהּ, בְּקָרְבָתָם לִפְנֵי יְיָ' וַיָמוּתוּ. בְּהַקְרִיבָם לָא כְּתִיב, אֶלָּא בְּקָרְבָתָם. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, דָּא גַּרְמָא לְהוּ, דְּדַּחֲקוּ שַׁעֲתָא בְּחַיֵּי אֲבוּהוֹן, וְטָעוּ בָּה, וְהַיְינוּ דִּכְתִּיב, (ויקרא י׳:א׳) אֲשֶׁר לֹא צִוָּה אוֹתָם, אוֹתָם לֹא צִוָּה, אֲבָל לְאַהֲרֹן צִוָּה. וּמַה תְּרֵין בְּנֵי אַהֲרֹן, עַל דְּדָחִיקוּ שַׁעֲתָא בְּחַיֵּי אֲבוּהוֹן גָּרְמוּ לְגַרְמַיְיהוּ כָּל כַּךְ, אֲנָא לְגַבֵּי אַבָּא וְרִבִּי פִּנְחָס וּשְׁאָר חַבְרַיָּיא, עַל אַחַת כַּמָה וְכַמָּה. אָתָא רִבִּי פִּנְחָס נְשָׁקֵּיהּ וּבַרְכֵיהּ.","רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שיר השירים ג׳:ז׳) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ וְגוֹ'. הִנֵה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מַאי מִטָּתוֹ. דָּא כּוּרְסֵי (נ\"א ערסא) יְקָרָא דְּמַלְכָּא, דִּכְתִּיב בֵּיהּ, (משלי ל״א:י״א) בָּטַח בָּהּ לֵב בַּעְלָהּ. שֶׁלִּשְׁלֹמֹה, מַלְכָּא דִּי שְׁלָמָא כֹּלָּא דִּילֵיהּ הוּא. שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ, דְּאִתְאַחֲדָן בְּסִטְרָהָא מִדִּינָא קַשְׁיָא, וְאִקְרוּן, שִׁתִּין פּוּלְסֵי דְּנוּרָא, (ס\"א שתין מזייני זיוני קשיין) דְּהַהוּא נַעַר, אִתְלְבַּשׁ בְּהוּ.","מִימִינֵיהּ, שִׁנָּנָא דְּחַרְבָּא תַּקִּיפָא, מִשְּׂמָאלֵיהּ גּוֹמְרֵי דְּנוּרָא תַּקִּיפָא, דְּמִתְאַחֲדָא בִּגְלִיפוֹי (ס\"א בקליפוי), בְּשִׁבְעִין אֶלֶף לַהֲטֵי נוּרָא דְּאַכְלָא, וְאִינּוּן שִׁתִּין מְזַיְינֵי זִיּוּנֵי קַשְׁיָין, מֵאִינּוּן גְּבוּרָן תַּקִּיפִן, דְּהַהִיא גְּבוּרָה עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב מִגִּבּוֹרֵי יִשְׂרָאֵל.","וְתָאנָא, בְּהַאי עַרְסָא, מַה כְּתִיב בָּהּ, וַתָּקָם בְּעוֹד לַיְלָה, כַּד יַנְקָא מִסִּטְרָא דִּימִינָא (ס\"א מסטרא דדינא). וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מַאי טֶרֶף, כְּמָה דְאַתְּ אָמֵר (מיכה ה׳:ז׳) וְטָרַף וְאֵין מַצִּיל. הֲדָא הוּא דִכְתִיב כֻּלָם אֲחוּזֵי חֶרֶב מְלוּמְּדֵי מִלְחָמָה, זְמִינִין בְּכָל אֲתַר לְמֶעְבַּד דִּינָא, וְאִקְרוּן מָארֵי דִּיבָבָא וִילָלָה.","אִישׁ חַרְבּוֹ עַל יְרֵכוֹ. כְּמָה דְאַתְּ אָמֵר, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר. מִפַּחַד בַּלֵּילוֹת. הָא אוּקְמוּהָ, מִפַּחְדָהּ דְּגֵיהִנָּם וְכוּ' אֲבָל מִפַּחַד בַּלֵּילוֹת, כְּלוֹמַר, כָּל דָּא מָאֵן אֲתַר נַטְלִין, מִפַּחַד, מֵהַהוּא אֲתַר דְּאִקְרֵי פַּחַד, כְּמָה דְאַתְּ אָמֵר (בראשית ל״א:נ״ג) וּפַחַד יִצְחָק הָיָה לִי. וַיִשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בַּלֵּילוֹת, בְּזִמְנִין דְּאִינּוּן מִתְפַּקְדִין לְמֶעְבַּד דִּינָא.","וְתָאנָא, כְּתִיב (משלי ל״א:ט״ז) זָמְמָה שָׂדֶה וַתִּקָּחֵהוּ. הֲדָא הוּא דִכְתִיב, (איוב מ׳:כ׳) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם. וְעַל דָּא כְּתִיב, (תהילים ק״ד:כ״ה) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם וְגוֹ' שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגוֹ' כְּמָה דְאַתְּ אָמֵר. (משלי ל״א:י״ד) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. מִמֶּרְחָק וַדַּאי. מֵרֵישָׁא דְּמוֹחָא, וּמֵעֵילָּא דְּרֵישָׁא, תָּבִיא לַחְמָהּ. עַל יְדָא דְּצַדִּיק, כַּד מִזְדַּוְּוגָן כְּחַד, כְּדֵין חֵידוּ בְּכֹלָּא. הֲדָא הוּא דִכְתִיב, לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ.","תָּאנָא, אֶלֶף וַחֲמֵשׁ מְאָה, מָארֵי תְּרִיסִין, מָארֵי דְּשׁוּלְטָנוּתָא, אִתְאַחֲדָן מְהַאי סִטְרָא, דְּאִינּוּן גִּיבָּרִין. בִּידוֹי דְּהַהוּא דְּאִקְרֵי נַעַר, אַרְבַּע מַפְתְּחִין רַבְרְבָן. תַּנִּינַיָיא אַזְלִין תְּחוֹת סְפִינָה, דְּהַאי יַמָּא רַבָּא, לְאַרְבַּע זָוְיָין. דָּא אָזִיל לְסִטְרָא דָּא, וְדָא אָזִיל לְסִטְרָא דָּא. וְכֵן כֻּלְּהוּ. אַרְבַּע חֵיזוּ דְּאַנְפִּין אִתְחַזְיָין בְּהוּ, וְכַד אִתְכְּלִילָן בְּחַד, כְּתִיב, (יחזקאל א׳:י׳) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, פְּנֵיהֶם דְּכֹלָּא."],[[0,"קם ר׳ אלעזר וכו׳:","קם ר״א פתח ואמר, וידבר ה׳ אל משה אחרי מות שני בני אהרן וגו'. מקרא זה יש להסתכל בו, שנראה שהוא מיותר. כי כתוב אחריו, ויאמר ה׳ אל משה דבר אל אהרן אחיך, מכאן, יש לשאול, בהתחלת הפרשה, במקרא הזה שלמעלה, מה הוא שכתוב, וידבר ה׳ אל משה. מה הוא שאמר לו, והרי לאח״כ כתוב, ויאמר ה׳ אל משה."],[1,"אלא בשעתא דקב״ה וכו׳:","ומשיב, אלא בשעה שהקב״ה נתן את קטרת הסמים לאהרן, רצה, שלא ישתמש בו אדם אחר בחייו. מהו הטעם. הוא משום שאהרן הרבה שלום בעולם. א״ל הקב״ה, אתה רוצה להרבות שלום בעולם על ידך ירבה השלום שלמעלה, כי קטרת הסמים תהיה מסורה בידך מכאן ולהלאה, שהקטרת מרבה שלום למעלה, ובחייך לא ישתמש בו אדם אחר. נדב ואביהוא הקדימו בחיי אביהם, להקריב מה שלא נמסר להם. ודבר זה גרם להם שטעו בו. להקריב אש זרה."],[2,"ותאנא משה הוה וכו׳:","ולמדנו, משה היה מהרהר, מי גרם להם טעות זו להקריב אש זרה, והיה עצב. מה כתוב, וידבר ה׳ אל משה אחרי מות שני בני אהרן. ומה אמר לו, בקרבתם לפני ה׳ וימותו. בהקריבם לא כתוב, אלא בקרבתם. אמר לו הקב״ה למשה, זה גרם להם, שדחקו את השעה להקריב קטרת בחיי אביהם, וטעו בה, שהקריבו אש זרה. והיינו שכתוב, אשר לא צוה אותם, אותם לא צוה להקריב, אבל לאהרן צוה. ויהיה טעם הכתוב, \u0003ויקריבו לפני ה׳ אש זרה,\u0004 שטעו בזה, משום \u0003אשר לא צוה אותם.\u0004 להקריב קטורת רק לאהרן לבדו צוה. ומה שני בני אהרן על שדחקו השעה בחיי אביהם גרמו לעצמם כל כך, אני כלפי אבי ור׳ פנחס ושאר החברים, על אחת כמה וכמה שאיני רשאי לדחוק השעה לומר חידושי תורה במקומם. בא ר׳ פנחס נשקו וברכו."],[3,"רבי שמעון פתח וכו׳:","רש״פ ואמר, הנה מטתו שלשלמה ששים גבורים סביב לה וגו'. \u0003הנה מטתו שלשלמה,\u0004 מהו מטתו. זו היא כסא הכבוד של המלך, דהיינו המלכות שנקראת מטה. שכתוב בה, בטח בה לב בעלה. \u0003שלשלמה,\u0004 היינו המלך שכל השלום הוא שלו. שזה ז״א. \u0003ששים גבורים סביב לה,\u0004 שהם נאחזים בצד שלה של המלכות מדין קשה ונקראים, שתין פולסא דנורא, דהיינו ששים שומרים מאש. \u0003פולסי,\u0004 פירושו שומרים, מלשון הוא ופלסונו שנער ההוא, דהיינו מטטרון, מתלבש בהם. (ב״ר ס׳)."],[4,"מימיניה שננא דחרבא וכו׳:","מימינו של מטטרון, להט החרב התקיפה, משמאלו גחלי אש חזקה, המתאחדת בחקיקותיו בע׳ אלף להבות אש אוכלת, והם ששים גבורים מזוינים זיון קשה מאלו הגבורות החזקות של גבורה עליונה ההיא של הקב״ה. שהוא ז״א. ז״ש מגבורי ישראל. דהיינו מגבורה דז״א הנקרא ישראל."],[4,"","ביאור הדברים נודע שאין החכמה מתגלה אלא עם דינים חזקים, השומרים שהרשעים לא ימשכוה מלמעלה למטה (כנ״ל פקודי אות שע״ו, ופרשת צו אות קי״ד) ואלו דינים החזקים הם נמשכים מצד שמאל דז״א, וכלולים מחג״ת נה״י שלו שכל אחד כלול מעשרה, הם ששים. וה״ס \u0003ששים גבורים.\u0004 ונודע שאין החכמה מתגלית אלא במלכות (כנ״ל ב״א דף רע״ו ד״ה ועוד כמה) וע״כ מקומם של אלו ששים גבורים הוא במלכות, לשמרה מפני החצונים, שלא ימשכו מהארת חכמה שבה מלמעלה למטה."],[4,"","וזה אמרו. \u0003הנה מטתו שלשלמה, מאי מטתו דא כורסי יקרא דמלכא.\u0004 דהיינו המלכות שנקראת מטת שלמה, כי שלמה הוא ז״א. \u0003ששים גבורים סביב לה דאתאחדן בסטרהא מדינא קשיא,\u0004 כי מצד המלכות שבה מתגלה הארת החכמה מתאחדים אלו ששים גבורים, שהם הדינים \u0003השומרים\u0004 החכמה שלא יינקו ממנה החצונים והרשעים. \u0003ואקרון שתין פולסי דנורא,\u0004 דהיינו ששים \u0003שומרים\u0004 מאש לשמרה מחצונים. וראש השומרים האלו, הוא מלאך מטטרון. כי הוא נקרא כן מלשון, אני הולך לפניהם \u0003מטטור\u0004 (ילמדינו תשא) שפירושו שומר. וז״ש, \u0003דההוא נער אתלבש בהו,\u0004 שמטטרון מתלבש בששים שומרים אלו, ושומר את המלכות, שהיא מטתו שלשלמה."],[4,"","וחוץ מאלו הדינים הנמשכים משמאל דז״א, יש ג״כ בחינות דינים הנמשכים מימין דז״א, שה״ס דינין הנמשכים ממסך דז״א, וז״ש, \u0003מימיניה שננא דחרבא תקיפא,\u0004 דהיינו הדינים הנמשכים מימין דז״א למטטרון. \u0003משמאליה גומרי דנורא תקיפא,\u0004 דהיינו הדינים הנמשכים משמאל דז״א למטטרון, בסוד ששים גבורים. אמנם כשהם נכללים עם המלכות, הם שבעים, כי חג״ת נה״י דז״א עם המלכות, הרי הם ז', וכל אחת כשנכללה במלכות היא בבחינת חכמה הנקראת אלף, והם ע׳ אלף. וז״ש, \u0003דמתאחדא בגליפוי בע׳ אלף להטי נורא דאכלא,\u0004 כי כשנכללים עם המלכות הם ע׳ אלף. וז״ש, \u0003ואינון שתין מזייני זיוני קשיין מאינון גבורן תקיפן דההיא גבורה עלאה דקב״ה,\u0004 שאלו ע׳ אלף הם בחינת אותם ששים הגבורים הנמשכים מז״א, אלא מצד המלכות הם ע׳ אלף ומצד ז״א לבד הם ששים גבורים. ז״ש \u0003מגבורי ישראל.\u0004 דהיינו שמיוחסים לז״א הנקרא ישראל, וע״כ הם ששים."],[5,"ותאנא בהאי ערסא וכו׳:","ולמדנו, במטה הזו, שהיא המלכות, מה כתוב בה, \u0003ותקם בעוד לילה,\u0004 כשיונקת מצד הדין. כלומר, בעת שהמלכות \u0003קמה\u0004 להשפיע הארת חכמה הוא \u0003לילה,\u0004 דהיינו דין, כי אין החכמה שלה מושפעת אלא עם דינים כנ״ל. וקימה פירושו הארת חכמה. \u0003ותתן טרף לביתה,\u0004 מהו טרף. הוא כש״א, וטרף ואין מציל. דהיינו הדינים שעם החכמה, שאין מציל מהם. ז״ש, \u0003כולם אחוזי חרב מלומדי מלחמה,\u0004 המוכנים לעשות דין בכל מקום ונקראים בעלי יבבה ויללה."],[6,"איש חרבו על ירכו:","הוא כמו שאתה אומר, חגור חרבך על ירך גבור. וסוד החרב כבר נתבאר (באות ע״א) \u0003מפחד בלילות,\u0004 הרי העמידוהו מפחד של גיהנם. אבל מפחד בלילות, כלומר, כל זה מאיזה מקום לוקחים, \u0003מפחד,\u0004 ממקום הזה הנקרא פחד, כש״א ופחד יצחק היה לי, שהוא גבורה דז״א, קו השמאל הנקרא יצחק. כמ״ש וישבע יעקב בפחד אביו יצחק. \u0003בלילות,\u0004 פירושו, בזמנים שהם נתמנו לעשות דין. כי בלילה, הוא זמן הדין."],[7,"ותאנא כתיב זממה וגו׳:","ולמדנו, כתוב זממה שדה ותקחהו. ז״ש, וכל חית השדה ישחקו שם דהיינו בחינת הדין של המלכות. שה״ס לילה כנ״ל ונקרא ג״כ \u0003שדה. וכל חית,\u0004 ה״ס יסוד. ישחקו ה״ס \u0003זווג,\u0004 ועל זה כתוב, זה הים גדול וגו׳ שם אניות יהלכון לויתן זה יצרת \u0003לשחק\u0004 בו. אשר לויתן ה״ס יסוד, לשחק הוא זווג. כמ״ש, והנה יצחק מצחק וגו'. כש״א, היתה כאניות סוחר \u0003ממרחק\u0004 תביא לחמה. ממרחק ודאי. כי לחמה שה\"ס הארת חכמה אינה מאירה אלא \u0003ממרחק,\u0004 דהיינו עם דינים \u0003המרחיקים\u0004 את החיצונים שלא יינקו מהארה הגדולה הזו. שז״ס מרחוק ה׳ נראה לי. וז״ס שהזווג הוא בבחינת לילה ובחינת שדה כנ״ל. כי הוא מביא את הארתה ממוח שבראש, דהיינו חכמה, ומלמעלה מראש, שהוא א״ס ב״ה. וע״כ צריכה שמירה מפני החיצונים, \u0003תביא לחמה:\u0004 היינו על ידי הצדיק, שהוא יסוד. כשמזדווגים יחד, אז היא שמחה בכל. ז״ש, לויתן זה יצרת לשחק בו. שלויתן הוא יסוד, לשחק בו הוא זווג, כנ״ל."],[8,"תאנא אלף וחמש מאה וכו׳:","למדנו, אלף וחמש מאה, בעלי המגינים בעלי השלטון נאחזים בהצד, של אלו ששים גבורים. בידיו של אותו הנקרא נער, דהיינו מטטרון, יש ארבעה מפתחות גדולים. שהם ד׳ מלאכים, מיכאל גבריאל אוריאל רפאל. ונקראים מפתחות גדולים, משום שהם ממשיכים מוחין דגדלות לתחתונים. תנינים, שהם מדרגות החכמה המבוארים (לעיל בא דף י״א ד״ה פנימיות ובדף י״ג ד״ה פירוש) הולכים תחת הספינה, שהיא המלכות דהיינו בבריאה, של ים הגדול, שהוא בינה, שממנה מקבלת המלכות הארותיה, לארבע זויות. שלה, זה הולך לצד זה, דרום. וזה הולך לצד זה, צפון. וכן כולם. דהיינו גם לצד מזרח ולצד מערב, שה״ס חו״ג תו״מ. ארבע צורות הפנים נראות בהם, בתנינים, שהם אריה שור נשר אדם. שהם נמשכים מג׳ קוין, ומלכות המקבלתם, שהיא פני אדם. וכשנכללות באחת, דהיינו בהמלכות, כתוב, ודמות פניהם פני אדם, דהיינו פניהן של כולן, שג' הצורות אריה שור נשר מקבלות צורת אדם כמו המלכות, בעת שנכללות בה."],[8,"","פירוש. הג״ר הכלולות מהארת חכמה, הם ג' קוין, חב״ד, ומכונים ג׳ אלפים, כי הארת חכמה ה״ס אלף. והאלף הג' שהוא קו האמצעי, דעת מתחלק לחסדים וגבורות ונודע שהארת חכמה אינה מקובלת מחכמה ממש שהיא בקו ימין אלא מבינה שחוזרת לחכמה, שה״ס קו שמאל. וע״כ נבחן שבחכמה וכן בחציה הימני של הדעת, שהם אלף וחצי אלף, הם חסדים והבינה וחציה השמאלי של הדעת, שהם אלף וחצי אלף, הם בהארת חכמה. וז״ש \u0003אלף וחמש מאה,\u0004 שהם בינה וחציה השמאלי של הדעת, \u0003מארי תריסין,\u0004 שהם מחציה השמאלי של הדעת, כי חציה השמאלי של הדעת, שהוא קו אמצעי, מגין על הארת החכמה שלא יתאחזו בה החצונים \u0003מארי דשולטנותא,\u0004 היינו הנמשכים מבינה, שהם שולטים בהארת החכמה, \u0003אתאחדן מהאי סטרא דאינון גיברין,\u0004 שהם מתאחדן בצד זה של השמאל, המכונים ששים גבורים. והשאר כבר נתבאר בפנים."]],[[0,"","קָם רַבִּי אֶלְעָזָר, פָּתַח וְאָמַר, וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן וְגוֹ'. בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, שֶׁנִּרְאֶה שֶׁהוּא מְיֻתָּר, שֶׁהֲרֵי כָּתוּב אַחֲרָיו, וַיֹּאמֶר ה' אֶל מֹשֶׁה דַּבֵּר אֶל אַהֲרֹן אָחִיךְ. מִכָּאן רֵאשִׁית הַפָּרָשָׁה, הַפָּסוּק הַזֶּה שֶׁלְּמַעְלָה מַה הוּא, שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה? מַה הוּא שֶׁאָמַר לוֹ, וְאַחַר כָּךְ וַיֹּאמֶר ה' אֶל מֹשֶׁה?"],[1,"","אֶלָּא בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן קְטֹרֶת בְּשָׂמִים לְאַהֲרֹן, רָצָה שֶׁלֹּא יִשְׁתַּמֵּשׁ בּוֹ בְּחַיָּיו אָדָם אַחֵר. מָה הַטַּעַם? מִשּׁוּם שֶׁאַהֲרֹן מַרְבֶּה שָׁלוֹם בָּעוֹלָם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא: אַתָּה רוֹצֶה לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם - עַל יָדְךְ יִרְבֶּה שָׁלוֹם לְמַעְלָה, הֲרֵי קְטֹרֶת הַבְּשָׂמִים תִּהְיֶה מְסוּרָה בְיָדְךְ מִכָּאן וָהָלְאָה, וּבְחַיֶּיךְ לֹא יִשְׁתַּמֵּשׁ בָּהּ אָדָם אַחֵר. נָדָב וַאֲבִיהוּא הִקְדִּימוּ בְּחַיֵּי אֲבִיהֶם לְהַקְרִיב מַה שֶּׁלֹּא נִמְסַר לָהֶם, וְדָבָר זֶה גָּרַם לָהֶם שֶׁטָּעוּ בוֹ."],[2,"","וְשָׁנִינוּ, מֹשֶׁה הָיָה מְהַרְהֵר מַה גָּרַם לָהֶם אֶת הַטָּעוּת הַזּוֹ, וְהָיָה עָצוּב. מַה כָּתוּב? וַיְדַבֵּר ה' אֶל מֹשֶׁה אַחֲרֵי מוֹת שְׁנֵי בְּנֵי אַהֲרֹן. וּמָה אָמַר לוֹ? בְּקָרְבָתָם לִפְנֵי ה' וַיָּמֻתוּ. בְּהַקְרִיבָם לֹא כָתוּב, אֶלָּא בְּקָרְבָתָם. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה: זֶה גָּרַם לָהֶם - שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם וְטָעוּ בָהּ, וְהַיְנוּ מַה שֶּׁכָּתוּב אֲשֶׁר לֹא צִוָּה אוֹתָם. אוֹתָם לֹא צִוָּה, אֲבָל לְאַהֲרֹן צִוָּה. וּמַה שְּׁנֵי בְּנֵי אַהֲרֹן, עַל שֶׁדָּחֲקוּ אֶת הַשָּׁעָה בְּחַיֵּי אֲבִיהֶם גָּרְמוּ לְעַצְמָם כָּל כָּךְ - אֲנִי כְּלַפֵּי אַבָּא וְרַבִּי פִּנְחָס וּשְׁאָר הַחֲבֵרִים עַל אַחַת כַּמָּה וְכַמָּה. בָּא רַבִּי פִּנְחָס, נְשָׁקוֹ וּבֵרְכוֹ."],[3,"","רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (שיר ג) הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ וְגוֹ'. הִנֵּה מִטָּתוֹ שֶׁלִּשְׁלֹמֹה, מִי זוֹ מִטָּתוֹ? זֶהוּ כִּסֵּא (מטת) הַכָּבוֹד שֶׁל הַמֶּלֶךְ, שֶׁכָּתוּב בּוֹ (משלי לא) בָּטַח בָּהּ לֵב בַּעְלָהּ. שֶׁלִּשְׁלֹמֹה, הַמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ הוּא. שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ, שֶׁנֶּאֱחָזִים בְּצִדֶּיהָ מִן הַדִּין הַקָּשֶׁה, וְנִקְרָאִים שִׁשִּׁים מַכּוֹת שֶׁל אֵשׁ (ששים מזינים בכלי זין קשים) שֶׁאוֹתוֹ נַעַר מִתְלַבֵּשׁ בָּהֶם."],[4,"","מִימִינוֹ שְׁנִינוּת הַחֶרֶב הַקָּשָׁה, מִשְּׂמֹאלוֹ גַּחֲלֵי אֵשׁ חֲזָקָה שֶׁאֲחוּזָה בַּחֲקִיקוֹתָיו (במקלותיו) בְּשִׁבְעִים אֶלֶף לַהֲטֵי אֵשׁ אוֹכֶלֶת, וְהֵם שִׁשִּׁים מְזֻיָּנִים בִּכְלֵי זַיִן קָשִׁים מֵאוֹתָן גְּבוּרוֹת תַּקִּיפוֹת שֶׁל אוֹתָהּ גְּבוּרָה עֶלְיוֹנָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב מִגִּבֹּרֵי יִשְׂרָאֵל."],[5,"","וְלָמַדְנוּ, בַּמִּטָּה הַזּוֹ מַה כָּתוּב בָּהּ? וַתָּקָם בְּעוֹד לַיְלָה, כַּאֲשֶׁר יוֹנֶקֶת מִצַּד הַיָּמִין (מצד הדין). וַתִּתֵּן טֶרֶף לְבֵיתָהּ. מָה הַטֶּרֶף? כְּמוֹ שֶׁנֶּאֱמַר (מיכה ה) וְטָרַף וְאֵין מַצִּיל. זֶהוּ שֶׁכָּתוּב כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי מִלְחָמָה, זְמִינִים בְּכָל מָקוֹם לַעֲשׂוֹת דִּין, וְנִקְרָאִים בַּעֲלֵי יְבָבָה וִילָלָה."],[6,"","אִישׁ חַרְבּוֹ עַל יְרֵכוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר. מִפַּחַד בַּלֵּילוֹת, הֲרֵי פֵּרְשׁוּהָ מִפַּחְדָּהּ שֶׁל גֵּיהִנֹּם וְכוּ'. אֲבָל מִפַּחַד בַּלֵּילוֹת, כְּלוֹמַר, אֶת כָּל זֶה מֵאֵיזֶה מָקוֹם לוֹקְחִים? מִפַּחַד, מֵאוֹתוֹ מָקוֹם שֶׁנִּקְרָא פַּחַד, כְּמוֹ שֶׁנֶּאֱמַר (בראשית לא) וּפַחַד יִצְחָק הָיָה לִי. וַיִּשָּׁבַע יַעֲקֹב בְּפַחַד אָבִיו יִצְחָק. בַּלֵּילוֹת, בִּזְמַנִּים שֶׁהֵם מֻנּוּ לַעֲשׂוֹת דִּין."],[7,"","וְלָמַדְנוּ, כָּתוּב (משלי לא) זָמְמָה שָׂדֶה וַתִּקָּחֵהוּ. זֶהוּ שֶׁכָּתוּב (איוב מ) וְכָל חַיַּת הַשָּׂדֶה יְשַׂחֲקוּ שָׁם. וְעַל זֶה כָּתוּב, (תהלים קד) זֶה הַיָּם גָּדוֹל וּרְחַב יָדַיִם וְגוֹ' שָׁם אֳנִיּוֹת יְהַלֵּכוּן וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר (משלי לא) הָיְתָה כָּאֳנִיּוֹת סוֹחֵר מִמֶּרְחָק תָּבִיא לַחְמָהּ. מִמֶּרְחָק וַדַּאי. מֵרֹאשׁ הַמֹּחַ, וּמִמַּעְלָה שֶׁל הָרֹאשׁ, תָּבִיא לַחְמָהּ, עַל יְדֵי הַצַּדִּיק כְּשֶׁמִּזְדַּוְּגִים כְּאֶחָד, אֲזַי שִׂמְחָה בַּכֹּל. זֶהוּ שֶׁכָּתוּב לִוְיָתָן זֶה יָצַרְתָּ לְשַׂחֶק בּוֹ."],[8,"","לָמַדְנוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת בַּעֲלֵי מָגִנִּים בַּעֲלֵי הַשִּׁלְטוֹן נֶאֱחָזִים מֵהַצַּד הַזֶּה, שֶׁהֵם גִּבּוֹרִים. בִּידֵי אוֹתוֹ שֶׁנִּקְרָא נַעַר אַרְבָּעָה מַפְתְּחוֹת גְדוֹלִים. תַּנִּינִים שֶׁהוֹלְכִים תַּחַת הַסְּפִינָה שֶׁל הַיָּם הַגָּדוֹל הַזֶּה לְאַרְבַּע זָוִיּוֹת. זֶה הוֹלֵךְ לְצַד זֶה, וְזֶה הוֹלֵךְ לְצַד זֶה, וְכָךְ כֻּלָּם. אַרְבָּעָה מַרְאוֹת שֶׁל פָּנִים נִרְאִים בָּהֶם, וּכְשֶׁנִּכְלָלִים בְּאֶחָד, כָּתוּב (יחזקאל א) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, פְּנֵיהֶם שֶׁל כֻּלָּם."]]],[["אַפֵּי רַבְרְבֵי, וְאַפֵּי זוּטְרֵי, כְּלִילָן כְּחַד לְעֵילָּא, תְּרֵי סַלְּקִין וְשָׁאטִין, וּתְרֵין מַגְרוֹפִין בִּידַיְיהוּ. אֶלֶף טוּרִין סַלְּקִין וְעָאלִין (ס\"א אלין טמירין עאלין וסלקין) בְּכָל יוֹמָא, מִשַּׁקְיוּ דְּהַהוּא יַמָּא, לְבָתַר, אִתְעֲקָרוּ מִנָּהּ, וְסַלְּקִין לְיַמָּא אָחֳרָא.","לֵית חוּשְׁבָּנָא לְאִינּוּן דְּאִתְאַחֲדָן בְּשַׂעְרָהָא, תְּרֵין בְּנִין יַנְקִין כָּל יוֹמָא, דְּאִקְרוּן מְאַלְלֵי אַרְעָא. וְדָא הוּא רָזָא דְּסִפְרָא דִּצְנִיעוּתָא, דִּכְתִּיב, (יהושע ב׳:א׳) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׂ לֵאמֹר. וְאִלֵּין, יַנְקִין מִתְּחוֹת סִטְרֵי אֶבְרָהָא, תְּרֵין בַּנוֹת בִּתְחוֹת רַגְלָהָא, (ס\"א ואלין ינקן מסטרא דאברהא, תרין בנת בתחותהא) וְעַל דָּא כְּתִיב, (בראשית ו׳:ב׳) וַיִּרְאוּ בְּנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. וְאִלֵּין מִתְאַחֲדָן בְּטַרְפֵּי (ס\"א בטופרי) דְּהַהִיא עַרְסָא, וְדָא הוּא דְּתָנֵינָן, דִּכְתִּיב, (מלכים א ג׳:ט״ז) אָז תָּבֹאנָה שְׁתַּיִם נָשִׁים זוֹנוֹת אֶל הַמֶּלֶךְ. אָז תָּבֹאנָה, וְלָא מִקַּדְמַת דְּנָא, וּבְזִמְנָא דְּיִשְׂרָאֵל לְתַתָּא, אָהֲדְרוּן קְדָל מִבָּתַר קוּדְשָׁא בְּרִיךְ הוּא, מַאי כְּתִיב, (ישעיהו ג׳:י״ב) עַמִּי נוֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. וַדַּאי.","בִּידָא שְׂמָאלָא, שִׁבְעִין עַנְפִין, דְּמְגַדְּלִין בֵּין נוּנֵי יַמָּא, כֻּלְּהוּ סוּמָקֵי כְּוַורְדָּא. וְעֵילָּא מִנְּהוֹן, עַנְפָּא חַד סוּמָקָא יַתִּיר, דָּא סָלִיק וְנָחִית. וְכֻלְּהוּ אִתְחַפְיָּין בְּשַׂעְרָהָא.","מָארֵי דְּלִישָׁנָא בִּישָׁא. כַּד נָחִית חִוְיָא. אִתְעָבִיד מְקַפֵּץ עַל טוּרִין, מְדַלְגָא עַל טִנָרֵי. עַד דְּיִשְׁכַּח טַרְפָּא, דְּאָחִיד בְּטוּפְרֵי וְיֵיכוּל. כְּדֵין שָׁכִיךְ, וְאִתְחַזָר לִישָׁנֵיהּ לְטָב. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דִּמְזַמְּנִין לֵיהּ טַרְפֵיהּ. אַהֲדָר לְאַתְרֵיהּ (ס\"א לבתריה), עַיִּיל בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא.","כַּד (ס\"א סליק סלקין) סַלְּקִין מָארֵי דְּרוֹמְחִין וְסַיְיפִין, דְּלֵית לוֹן חוּשְׁבָּנָא, סוּחֲרָנַיְיהוּ דְּאִינּוּן שִׁתִּין עִלָּאִין, דְּסוּחֲרָנֵיהּ דְּהַאי עַרְסָא, אֶלֶף אַלְפִין, וְרִבּוֹא רִבְּוָון, קַיְימִין בְּכָל סִטְרָא דְּהַאי עַרְסָא לְעֵילָּא. וּמִנֵּיהּ אַתְּזְנָן, כֻּלְּהוּ מִקָּמֵיהּ (ס\"א ומניה אתזנו, ליה פלחין כולהו קמיה) יְקוּמוּן.","מִתְּחוֹת כֻּלְּהוּ, נָפְקִין כַּמָה אֶלֶף וְרִבְּבָן, דְּלֵית לוֹן חוּשְׁבָּנָא, וְנַחְתִּין וְשָׁאטִין בְּעָלְמָא, עַד דְּתַקְעֵי מָארֵי שׁוֹפָרָא, וּמִתְכַּנְּשֵׁי. וְהָנֵי בְּזוּהֲמָא דְּטוּפְרֵי אֲחִידָן.","דָּא עַרְסָא כָּלִיל לוֹן, דָּא עַרְסָא, רַגְלוֹהִי אֲחִידָן בְּאַרְבַּע סִטְרֵי עָלְמָא, כֹּלָּא עָאלִין בִּכְלָלָא, דְּאִשְׁתְּכַח לְעֵילָּא, וְאִשְׁתְּכַח לְתַתָּא, בַּשָׁמַיִם מִמַּעַל, וְעַל הָאָרֶץ מִתָּחַת, וְעַל דָּא כְּתִיב הִנֵּה. מַאי הִנֵּה. בְּגִין דִּזְמִינָא לְכֹלָּא לְעֵילָּא וְתַתָּא. וּרְשׁוּמָא הַאי עַרְסָא מִכֹּלָּא, אֲדֹנָ\"י אִתְקְרֵי, רִבּוֹנָא דְּכֹלָּא, רְשִׁימָא בֵּין חַיָּילָהָא.","בְּגִין כַּךְ, כַּהֲנָא בָּעֵי לְכַוְּונָא מִלֵּי דִּלְעֵילָּא, לְיַחֲדָא שְׁמָא קַדִּישָׁא מֵאֲתַר דְּבָעָא לְיַחֲדָא, וְעַל דָּא תָּנֵינָן, כְּתִיב, בְּזֹאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, בְּהַאי בָּעֵי לְקָרְבָא קְדוּשָּׁה לְאַתְרֵיהּ, מֵהַאי אֲתַר, בָּעֵי בַּר נָשׁ לְדַחֲלָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא כְּתִיב, (דברים ל״ב:כ״ט) לוּ חָכְמוּ יַשְׂכִּילוּ זֹאת מִיַּד יָבִינוּ לְאַחֲרִיתָם. כְּלוֹמַר, אִי יִסְתַּכְּלוּן בְּנֵי נָשָׂא בְּעוֹנְשָׁא, הֵיךְ אֲחִידַת זֹאת בֵּין חַיָּילָהָא, וְהֵיךְ אִתְמָנוּ קַמָּהּ כָּל אִינּוּן בְּנֵי חַיָּילִין, וַאֲחִידָן בְּפוּלְחָנָא לְאִתְפָּרְעָא מִן חַיָּיבַיָּא, מִיַּד יָבִינוּ לְאַחֲרִיתָם, וְיִסְתַּמְרוּן עוֹבָדֵיהוֹן, וְלָא יְחוּבוּן קָמֵי מַלְכָּא קַדִּישָׁא.","תּוּ אָמַר רַבִּי שִׁמְעוֹן, כָּל בַּר נָשׁ דְּזָכֵי לְמֵילַף אוֹרַיְיתָא, וְנָטִיר לָהּ לְהַאי זֹאת. הַאי זֹאת נְטִירַת לֵיהּ, וְגָזַר עִמֵּיהּ קַיְּימָא עַל קַיְּימָא דִּילֵיהּ, דְּלָא יִתְעֲדֵי מִנֵּיהּ, וּמִן בְּנוֹהִי וּמִן בְּנֵי בְּנוֹהִי לְעָלְמִין. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ט:כ״א) וַאֲנִי זֹאת בְּרִיתִי אוֹתָם וְגוֹ'. יָתְבוּ לְמֵיכַל. עַד דְּאָכְלוּ, אָמַר רַבִּי שִׁמְעוֹן לְחַבְרַיָּיא, כָּל חַד וְחַד לֵימָא מִלָּה חַדְתָּא דְּאוֹרַיְיתָא. עַל פָּתוֹרָא, לְקָמֵיהּ דרִבִּי פִּנְחָס.","פָּתַח רִבִּי חִזְקִיָּה וְאָמַר, (ישעיהו נ׳:ד׳) יְיָ' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמוּדִים לָדַעַת לָעוּת אֶת יָעֵף דָּבָר וְגוֹ'. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ מִכָּל שְׁאָר עַמִין, וּקְרָאָן, קֹדֶשׁ. דִּכְתִּיב, (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַיְיָ'. וְיָהִיב לְהוּ חוּלָק, לְאִתְאַחֲדָא בִּשְׁמָא קַדִּישָׁא. וּבְמָּה אֲחִידוּ יִשְׂרָאֵל בִּשְׁמָא קַדִּישָׁא. בְּגִין דְּזָכוּ בְּאוֹרַיְיתָא, דְּכָל מַאן דְּזָכֵי בְּאוֹרַיְיתָא זָכֵי בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"אפי רברבי ואפי זוטרי וכו׳:","פנים גדולות שהם מוחין דגדלות, ופנים קטנות, שהם מוחין דקטנות, כלולים יחד למעלה, בז״א ומלכות. מלמדנו בזה, שאפילו בעת שמאירים המוחין דגדלות בזו״ן, מאירים ג״כ המוחין דקטנות (כמ״ש לעיל בהקסה״ז דף ו׳ ד״ה ואלמלא, ע״ש) שנים, שהם ב׳ קוין, הימין והאמצעי, עולים ומשוטטים וב׳ מגרופין בידיהם. שהם הכחות של המסך דחירק הנכללים בב׳ קוין אלו, שעל ידיהם מרחיקים את החצונים מלינק מהארת חכמה (כמ״ש לעיל ויחי דף ק\"ס ד״ה יתבין ע״ש כל ההמשך) שבהם כח השכר והעונש. אלף הרים עולים ובאים בכל יום לינק משיקוי של אותו הים, שהוא בינה, שהארת החכמה המכונה אלף הרים, אינה נמשכת אלא מבינה בלבד. כנ״ל בדבור הסמוך, ואח״כ נעקרים ממנה, מבינה, ועולים לים האחר, שהוא המלכות. ומשמיענו, שאע״פ שמוחין אלו כל יציאתם הוא בבינה, ולא כלום במלכות, מ״מ בסוד אמא אוזיפת לברתא מאנהא, מקבלת המלכות המוחין דבינה. (כמ\"ש לעיל בהקסה״ז דף כ׳ ד״ה וזה אמרו)."],[1,"לית חושבנא לאינון וכו׳:","אין חשבון לאלו הנאחזים בשערותיה של המלכות, דהיינו בדינים שבה המכונים שערות. שני בנים יונקים כל יום, מן המלכות, הנקראים מרגלי הארץ. וזהו סוד שבספרא דצניעותא שבסוף תרומה, שכתוב, וישלח יהושע בן נון מן השטים שנים אנשים מרגלים חרש לאמר (כמ״ש בספרא דצניעותא אות נ״ד, וכמו שנתבאר שם בהסולס ע\"ש) ואלו, שני בנים, יונקים מתחת צדדי כנפי המלכות שה״ס חו״ג. ב׳ בנות, שה״ס שתים נשים זונות (כמ״ש שם ועי׳ בהסולם) הם תחת רגלי המלכות, שה״ס נצח והוד דמלכות. \u0003תחת,\u0004 פירושו אחורים. כלומר שב׳ בנים דקליפה יונקים מאחורים דחו״ג שלה, וב' בנות דקליפה, יונקים מאחורים דנו״ה שלה. דהיינו כמו בקדושה, שהזכר הוא חג״ת והנוקבא היא נה״י. וע״כ כתוב עליהם, ויראו בני האלקים את בנות האדם. (כמ״ש שם) ואלו הבנים והבנות דקליפה, נאחזים בצפרנים של מטה ההיא, שהיא המלכות. כי צפרניה ה״ס האחורים דאצבעות שבידין ורגלין (כמ״ש לעיל באורך, ויקהל דף פ״ז ד״ה פירוש ע״ש) וזהו שלמדנו שכתוב, \u0003אז\u0004 תבאנה שתים נשים זונות, אז תבאנה, ולא מקודם לכן (כמ״ש בספרא דצניעותא דף כ״ט ד״ה וזה) ובזמן שישראל למטה מחזירים העורף מאחרי הקב״ה, מה כתוב, עמי נוגשיו מעולל ונשים משלו בו. ודאי. דהיינו ב׳ נשים הנ״ל."],[2,"בידא שמאלא שבעין וכו׳:","ביד שמאל, דהיינו מקו שמאל של המלכות, נמשכים ע׳ ענפים, שהם ע׳ שרים של אומות העולם, המגודלים בין דגת הים, שהם מדרגות הארת חכמה דשמאל, שנק׳ דגים. ים פירושו מלכות. כולם אדומים כמו ורד. מחמת הדינים שבהם, כי הדינין דשמאל הם אדומים. ולמעלה מהם, ענף אחד אדום ביותר, שהוא יותר דין קשה מכולם, שהוא סמאל, זה עולה ויורד. כלומר, שממשיך החכמה ממעלה למטה. והוא שרכב על הנחש ופיתה את האדם להמשיך החכמה ממעלה למטה שה״ס החטא דעץ הדעת. וכולם מתכסים בשערותיה של המלכות, דהיינו בדינים שלה המכונים שערות."],[3,"מארי דלישנא בישא וכו׳:","בעל הלשון הרע. שהוא הנחש. כשיורד הנחש, נעשה מקפץ על הגבעות, מדלג על ההרים. עד שימצא טרף האחוז בצפרנים ואוכל. אז הוא שקט, וחזרה לשונו לטוב. דהיינו שנתבטל הלשון הרע שלו, ונעשה לשון טוב. אשרי הם ישראל שמכינים לו הטרף. והנחש חוזר למקומו ונכנס בנקב תהום הגדול."],[3,"","פירוש. אין אחיזת הנחש רק במלכות דמדת הדין, אלא מכח המיתוק של עליית המלכות בבינה, אשר הבינה מקבלת צורת המלכות, אז עולה הנחש ונאחז בדינים שבבינה, ואחיזה זו מכונה לשון הרע, כמו שמדבר לשון הרע על מי שכולו טוב. וכבר נתבאר זה לעיל (פרשת צו אות קט״ז ע״ש) וז\"ש, \u0003מארי דלישנא בישא\u0004 שהוא הנחש, כך דרכו, \u0003כד נחית חוייא,\u0004 כשיורד, תחילה ונאחז במלכות למטה, הנה אח״כ הוא עולה \u0003ומקפץ על טורין,\u0004 שהם בחינת בינה, \u0003מדלגא על טנרי,\u0004 שהם בחינת מלכות. כלומר אע״פ שמקום אחיזתו הוא בסלעים, שהם מלכות המכונה סלע, עכ״ז הנחש מדלג עליה, שעוזב אותה, והוא קופץ להאחז בהרים, שהם חג״ת, והם בחינת בינה. שזהו לשון הרע כנ״ל. והוא משום שרוצה יותר להתאחז במקום היותר גבוה."],[3,"","אמנם ע״י העלאת מ\"ן ממצות ומע״ט שעושים ישראל, נמשכת הארת ע״ב ס״ג דא״ק, המוריד בחזרה את המלכות מן הבינה, ואז נטהרת הבינה מלשון הרע של הנחש. וגם המלכות נטהרת ע״י הארת הבינה (ועי׳ לעיל וירא אות ק״ט ק״י). וז״ש, \u0003עד דישכח טרפא דאחיד בטופרי וייכול,\u0004 דהיינו אחר שהמלכות נטהרת ע״י הארת קו שמאל דבינה, שמקום התלבשות הארה זו הוא בסוד צפרניה של המלכות, דהיינו באחורים דאצבעות שלה, כנ״ל, (ויקהל דף פ״ז ד״ה פירוש ע״ש) אז גם הנחש מקבל חלקו מהארה זו דצפרני המלכות. והוא אוכל. \u0003כדין שכיך ואתחזר לישניה לטב,\u0004 כי ע״כ ניתן לו להנות מהארה זו, כדי שיתבטל לשון הרע שלו, ויחזור ללשון טוב. \u0003זכאין אינון ישראל דמזמנין ליה טרפיה,\u0004 כי הארה זו באה ע״י העלאת מ״ן ממצות ומע״ט של ישראל כנ״ל."],[4,"כד סלקין מארי וכו׳:","כשעולים בעלי הרמחים והחרבות שאין להם חשבון, שה״ס הדינים דמסך דחירק שבקו האמצעי, המכריעים את קו השמאל שיתיחד עם הימין, מסביב אלו ששים גבורים עליונים שהם מקו שמאל, המסבבים את המטה, שהיא המלכות, והשמאל מתיחד עם הימין על ידיהם. אז אלף אלפין ורבוא רבבן עומדים בכל צד של המטה ההיא שלמעלה. כלומר שיש חכמה וחסדים בכל צד, הן בימין והן בשמאל, מחמת התכללותם זב״ז, אלף אלפין, ה״ס הארות חכמה, המכונה אלף. ורבוא רבוון, ה״ס הארות חסדים המכונה רבבות. וממנה, מן המטה שהיא המלכות, הם נזונים, כולם יקומו מפניה. כלומר, שמקבלים ג״ר המכונים קימה. בסו״ה ותקם בעוד לילה."],[5,"מתחות כלהו נפקין וכו׳:","מתחת כולם, דהיינו תחת כל מדרגות הקדושה הנ״ל, יוצאים כמה אלף ורבבות קליפות שאין להם חשבון, דהיינו בסו\"ה יפול מצדך \u0003אלף.\u0004 שה״ס הקליפות הנאחזות במפתחא, \u0003ורבבה\u0004 מימינך לא יגש, שה״ס הקליפות הנאחזות במנעולא. ויורדים ומשוטטים בעולם, עד שתוקעים בעלי השופר, שה״ס היחוד דג׳ קוין, המכונים אש מים רוח, הנכללים בקול היוצא מן השופר (כמ״ש לעיל בהקדמת ספר הזהר דף קפ״ד ד\"ה למשמע) ואז מתאספים. ואלו נאחזים בזוהמא שבתוך הצפרנים. דהיינו בפסולת של הארת אחורים, המכונים צפרנים כנ״ל."],[6,"דא ערסא כליל וכו׳:","מטה זו, שהיא המלכות, כוללת אותם, דהיינו כל אלו המדרגות הנ״ל, מטה זו, רגליה אחוזות בארבע רוחות העולם, דהיינו שיש בה ד׳ ספירות חו״ג תו״מ, שה״ס ג׳ קוין ומלכות המקבלתם. הכל נכנסים בכלל, הן מה שנמצא למעלה, דהיינו מדרגות דז״א, והן מה שנמצא למטה, דהיינו מדרגותיה עצמה. שז\"ס, בשמים ממעל, דהיינו ז״א. ועל הארץ מתחת, דהיינו המלכות הנקראת ארץ, ועל כן כתוב \u0003הנה.\u0004 דהיינו הנה מטתו שלשלמה. מהו \u0003הנה.\u0004 משום שהיא מזומנת להאיר לכל למעלה ולמטה, ומטה הזו רשומה מכל. פירוש. שאין הארת החכמה מגולה אלא במלכות, (כנ״ל בראשית א׳ דף ע\"ו ד״ה ועוד) ואפילו העליונים ממנה אין להם הארת חכמה אלא ביחודם עם המלכות. היא נקראת \u0003אדני,\u0004 שפירושו רבון כל, הרשומה בין צבאותיה."],[7,"בניני כך כהנא וכו׳:","משום זה, צריך הכהן לכוון בדברים עליונים, ליחד השם הקדוש מן המקום שצריך ליחד, כלומר, שלא להמשיך הארת החכמה, אלא במלכות. וע״כ למדנו, כתוב, ב \u0003זאת\u0004 יבא אהרן אל הקדש, היינו שב \u0003זאת,\u0004 שהיא מלכות, צריך לקרב הקדושה למקומה, ולהרחיק הסטרא אחרא שרוצה להמשיך ממנה הארת החכמה ממעלה למטה. כי ממקום הזה, מן המלכות, צריך האדם לפחד מפני הקב״ה. כלומר שעם הארת החכמה המתגלה במלכות, מתגלים דינים קשים המענישים הרשעים ומרחיקים הס״א (כנ״ל פקודי אות שע״ו) וע״כ מפחדים ממנה. ועל זה כתוב, לו חכמו ישכילו \u0003זאת,\u0004 מיד, יבינו לאחריתם. כלומר אם יסתכלו בני אדם בהעונש, ולראות איך \u0003זאת,\u0004 שהיא המלכות מתאחדת בין צבאותיה, דהיינו שמאירה להם רק מבחינת ממטה למעלה, ואיך נתמנו לפניה כל אלו בני הצבאות, האחוזים בה לשרת אותה, כדי להעניש ולהפרע מן הרשעים, הרוצים להמשיך הארתה ממעלה למטה, מיד \u0003יבינו לאחריתם,\u0004 שישמרו מעשיהם, ולא יחטאו לפני המלך הקדוש."],[8,"תו אר״ש כל וכו׳:","עוד אמר ר׳ שמעון, כל אדם הזוכה ללמוד תורה ולשמור ל \u0003זאת\u0004 ההיא, שהיא המלכות, \u0003זאת\u0004 זו שומרת אותו וכורתת עמו ברית על ברית שלו, שלא תסור ממנו ומן בניו ומן בני בניו לעולם. ז״ש, ואני \u0003זאת\u0004 בריתי אותם וגו'. ישבו לאכול. בעוד שאכלו, א״ר שמעון להחברים, כל אחד ואחד יאמר בתורה דבר חדש, על השלחן, לפני רבי פנחס."],[9,"פתח ר׳ חזקיה וכו׳:","פר״ח ואמר, ה׳ אלקים נתן לי לשון למודים לדעת לעות את יעף דבר וגו'. אשרי הם ישראל שהקב״ה בחר בהם מכל שאר העמים, וקראם, קדש. שכתוב, קדש ישראל לה'. ונתן להם חלק, להתאחז בשם הקדוש. ובמה אחוזים ישראל בהשם הקדוש. הוא משום שזכו בתורה, שכל מי שזכה בתורה, זכה בהקב״ה."]],[[0,"","פָּנִים גְּדוֹלִים וּפָנִים קְטַנִּים כְּלוּלִים כְּאֶחָד לְמַעְלָה, שְׁנַיִם עוֹלִים וּמְשׁוֹטְטִים, וּשְׁתֵּי מַגְרֵפוֹת בִּידֵיהֶם. אֶלֶף הָרִים עוֹלִים וְנִכְנָסִים (אלו מכסים נכנסים ועולים) בְּכָל יוֹם מֵהַשְׁקָאַת אוֹתוֹ הַיָּם, אַחַר כָּךְ נֶעֱקָרִים מִמֶּנָּה וְעוֹלִים לְיָם אַחֵר."],[1,"","אֵין חֶשְׁבּוֹן לְאוֹתָם הַנֶּאֱחָזִים בְּשַׂעֲרוֹתֶיהָ, שְׁנֵי בָנִים יוֹנְקִים כָּל יוֹם, שֶׁנִּקְרָאִים מְרַגְּלֵי הָאָרֶץ, וְזֶהוּ סוֹד שֶׁל סִפְרָא דִצְנִיעוּתָא, שֶׁכָּתוּב (יהושע ב) וַיִּשְׁלַח יְהוֹשֻׁעַ בִּן נוּן מִן הַשִּׁטִּים שְׁנַיִם אֲנָשִׁים מְרַגְּלִים חֶרֶשׁ לֵאמֹר. וְאֵלּוּ יוֹנְקִים מִתַּחַת צִדְדֵי אֵיבָרֶיהָ. שְׁתֵּי בָנוֹת תַּחַת רַגְלֶיהָ, (ואלו יונקים מצד אברהם, שתי בנות בתחתיה) וְעַל זֶה כָּתוּב (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם. וְאֵלּוּ נֶאֱחָזִים בַּעֲלֵי (בצפרני) אוֹתָהּ מִטָּה, וְזֶהוּ שֶׁשָּׁנִינוּ, שֶׁכָּתוּב (מלכים א ג) אָז תָּבאנָה שְׁתַּיִם נָשִׁים זֹּנוֹת אֶל הַמֶּלֶךְ. אָז תָּבאנָה, וְלֹא מִקֹּדֶם לָכֵן. וּבִזְמַן שֶׁיִּשְׂרָאֵל לְמַטָּה, מַחֲזִירִים עֹרֶף מֵאַחַר הַקָּדוֹשׁ בָּרוּךְ הוּא, מַה כָּתוּב? (ישעיה ג) עַמִּי נֹגְשָׂיו מְעוֹלֵל וְנָשִׁים מָשְׁלוּ בוֹ. וַדַּאי."],[2,"","בְּיַד שְׂמֹאל שִׁבְעִים עֲנָפִים שֶׁמְּגֻדָּלִים בֵּין דְּגֵי הַיָּם, כֻּלָּם אֲדֻמִּים כַּשּׁוֹשַׁנָּה, וּמֵעֲלֵיהֶם עָנָף אֶחָד יוֹתֵר אָדם, זֶה עוֹלֶה וְיוֹרֵד, וְכֻלָּם מִתְכַּסִּים בְּשַׂעֲרוֹתֶיהָ."],[3,"","בַּעַל הַלָּשׁוֹן הָרָע, כְּשֶׁיּוֹרֵד הַנָּחָשׁ, נַעֲשֶׂה מְקַפֵּץ עַל הֶהָרִים מְדַלֵּג עַל הַסְּלָעִים, עַד שֶׁיִּמְצָא טֶרֶף שֶׁאָחוּז בְּצִפָּרְנַיִם, וְיֹאכַל. אָז שׁוֹכֵךְ, וְחוֹזֶרֶת לְשׁוֹנוֹ לְטוֹב. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁמְּזַמְּנִים לוֹ טַרְפּוֹ. חוֹזֵר לִמְקוֹמוֹ (לאחריו), וְנִכְנָס לְנֶקֶב תְּהוֹם רַבָּה."],[4,"","כְּשֶׁעוֹלִים (עולה עולים) בַּעֲלֵי הָרְמָחִים וְהַחֲרָבוֹת, שֶׁאֵין לָהֶם חֶשְׁבּוֹן, סְבִיב אוֹתָם שִׁשִּׁים עֶלְיוֹנִים שֶׁסְּבִיב הַמִּטָּה הַזּוֹ, אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת עוֹמְדִים בְּכָל צַד שֶׁל הַמִּטָּה הַזּוֹ לְמַעְלָה, וּמִמֶּנָּה נִזּוֹנִים, כֻּלָּם מִלְּפָנֶיהָ (וממנה נזונים, כלם עובדים לה לפניה) יַעַמְדוּ."],[5,"","מִתַּחַת לְכֻלָּם יוֹצְאִים כַּמָּה אֶלֶף וּרְבָבוֹת שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְיוֹרְדִים וּמְשׁוֹטְטִים בָּעוֹלָם, עַד שֶׁתּוֹקְעִים בַּעֲלֵי הַשּׁוֹפָר וּמִתְכַּנְּסִים, וְאֵלֶּה אֲחוּזִים בְּזֻהֲמַת הַצִּפָּרְנַיִם."],[6,"","הַמִּטָה הַזּוֹ כּוֹלֶלֶת אוֹתָם. רַגְלֵי הַמִּטָּה הַזּוֹ אֲחוּזִים בְּאַרְבַּעַת צִדְדֵי הָעוֹלָם, כֻּלָּם נִכְלָלִים בַּכְּלָל שֶׁנִּמְצָא לְמַעְלָה וְנִמְצָא לְמַטָּה, בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת, וְעַל זֶה כָּתוּב הִנֵּה. מַה זֶּה הִנֵּה? מִשּׁוּם שֶׁמְּזֻמֶּנֶת לְכֻלָּם, לְמַעְלָה וּלְמַטָּה. וּרְשׁוּמָה הַמִּטָּה הַזּוֹ מֵהַכֹּל, וְנִקְרֵאת אֲדנָ\"י, הָרִבּוֹן שֶׁל הַכֹּל, רְשׁוּמָה בֵּין חֵילוֹתֶיהָ."],[7,"","מִשּׁוּם כָּךְ הַכֹּהֵן צָרִיךְ לְכַוֵּן דְּבָרִים שֶׁלְּמַעְלָה, לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ מֵהַמָּקוֹם שֶׁצָּרִיךְ לְיַחֲדוֹ, וְעַל זֶה שָׁנִינוּ, כָּתוּב בְּזֹּאת יָבֹא אַהֲרֹן אֶל הַקֹּדֶשׁ, בָּזֶה צָרִיךְ לְקָרֵב קְדֻשָּׁה לִמְקוֹמָהּ, מֵהַמָּקוֹם הַזֶּה צָרִיךְ אָדָם לִפְחֹד מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל זֶה כָּתוּב, (דברים לד) לוּ חָכְמוּ יַשְׂכִּילוּ זֹּאת מִיָּד יָבִינוּ לְאַחֲרִיתָם. כְּלוֹמַר, אִם יִסְתַּכְּלוּ בְּנֵי אָדָם בְּעֹנֶשׁ, אֵיךְ זֹּאת אֲחוּזָה בֵּין חֵילוֹתֶיהָ, וְאֵיךְ הִתְמַנּוּ לְפָנֶיהָ כָּל אוֹתָם בְּנֵי הַחֲיָלוֹת, וְאוֹחֲזִים בַּעֲבוֹדָה לְהִפָּרַע מִן הָרְשָׁעִים, מִיָּד יָבִינוּ לְאַחֲרִיתָם, וְיִשְׁמְרוּ אֶת מַעֲשֵׂיהֶם, וְלֹא יֶחֶטְאוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ."],[8,"","עוֹד אָמַר רַבִּי שִׁמְעוֹן, כָּל אָדָם שֶׁזּוֹכֶה לִלְמֹד תּוֹרָה וְשׁוֹמֵר אֶת הַזֹּאת הַזּוֹ, הַזֹּאת הַזּוֹ שׁוֹמֶרֶת אוֹתוֹ וְכוֹרֶתֶת עִמּוֹ בְּרִית עַל בְּרִיתוֹ, שֶׁלֹּא תָסוּר מִמֶּנּוּ וּמִבָּנָיו וּמִבְּנֵי בָנָיו לְעוֹלָמִים. זֶהוּ שֶׁכָּתוּב (ישעיה נט) וַאֲנִי זֹּאת בְּרִיתִי אוֹתָם וְגוֹ'. יָשְׁבוּ לֶאֱכֹל. עַד שֶׁאָכְלוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, כָּל אֶחָד וְאֶחָד יֹאמַר דָּבָר חָדָשׁ בַּתּוֹרָה עַל הַשֻּׁלְחָן לִפְנֵי רַבִּי פִּנְחָס."],[9,"","פָּתַח רַבִּי חִזְקִיָּה וְאָמַר, ה' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמּוּדִים לָדַעַת לָעוּת אֶת יָעֵף דָּבָר וְגוֹ'. אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל שְׁאָר הָעַמִּים וּקְרָאָם קֹדֶשׁ, שֶׁכָּתוּב קֹדֶשׁ יִשְׂרָאֵל לַה', וְנָתַן לָהֶם חֵלֶק לְהֵאָחֵז בַּשֵּׁם הַקָּדוֹשׁ. וּבַמָּה אָחֲזוּ יִשְׂרָאֵל בַּשֵּׁם הַקָּדוֹשׁ? מִשּׁוּם שֶׁזָּכוּ בַתּוֹרָה. שֶׁכָּל מִי שֶׁאוֹחֵז בַּתּוֹרָה, זוֹכֶה בַּקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["(נ\"א בקדש) (רצ\"ז ע\"א) וְתָנֵינָן קָמֵיהּ דְּמַר, מַאי קֹדֶשׁ. שְׁלֵימוּתָא דְּכֹלָּא דְּאִקְרֵי חָכְמָה עִלָּאָה, וּמֵהַאי אֲתַר (נגיד משח רבות קדישא בשבילין ידיען, לאתר דאקרי בינה עלאה), וּמְתַּמָן נַפְקִין מְבּוּעִין וּנְחָלִין לְכָל עֵבָר, עַד דְמַטוּ לְהַאי זֹאת. (ומהאי אתר אתער רוחא קדישא) וְהַאי זֹאת כַּד מִתְבָּרְכָא, אִקְרֵי קֹדֶשׁ, וְאִקְרֵי חָכְמָה, וּקְרָאן לֵיהּ (נ\"א והאי זאת כד אתברכא מאתר עלאה דא דאקרי קדש ואקרי חכמה קראן ליה) רוּחַ הַקֹּדֶשׁ. כְּלוֹמַר, רוּחַ, מֵהַהוּא קֹדֶשׁ דִּלְעֵילָּא. וְכַד נָפְקִין וּמִתְעָרִין מִנֵּהּ רָזֵי אוֹרַיְיתָא, כְּדֵין אִתְקְרֵי לָשׁוֹן הַקֹּדֶשׁ.","וּבְשַׁעֲתָא דְּנָגִיד הַהוּא רְבוּת קַדִּישָׁא, לְאִינּוּן תְּרֵי קַיְימִין, דְּאִקְרוּן לִמּוּדֵי ה', וְאִקְרוּן צְבָאוֹת, אִתְכְּנַשׁ תַּמָּן, וְכַד נָפִיק מִתַּמָּן, בְּהַהוּא דַּרְגָּא דְּאִקְרֵי יְסוֹד, לְהַהוּא חָכְמָה זְעֵירָא, כְּדֵין אִתְקְרֵי לְשׁוֹן לִמוּדִים. וְנָפִיק לְאִתְּעָרָא לְאִינּוּן קַדִּישֵׁי עֶלְיוֹנִים. כְּדֵין כְּתִיב, יְיָ' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמוּדִים. וְלָמָּה. לָדַעַת לָעוּת אֶת יָעֵף דָּבָר. וְקוּדְשָׁא בְּרִיךְ הוּא יָהִיב הַאי לְבוּצִינָא קַדִּישָׁא, רַבִּי שִׁמְעוֹן. וְעוֹד דְּסָלִיק לֵיהּ לְעֵילָּא לְעֵילָּא, בְּגִין כָּךְ כָּל מִלּוֹי בְּאִתְגַּלְיָיא אִתְּמָרוּ, וְלָא אִתְכַּסְיָין. עָלֵיהּ כְּתִיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת.","פָּתַח רִבִּי יֵיסָא וְאָמַר, (מלכים א ה׳:כ״ו) וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וְגוֹ'. וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה, דָּא הוּא דְּתָנֵינָן, בְּיוֹמֵי דִּשְׁלֹמֹה מַלְכָּא, קַיְּימָא סִיהֲרָא בְּאַשְׁלְמוּתָא, כַּאֲשֶׁר דִּבֶּר לוֹ, כְּמָה דְּאִתְּמַר לֵיהּ, (דברי הימים ב א׳:י״ב) הַחָכְמָה וְהַמַּדָּע נָתוּן לָךָ.","וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה. וְכִי מַה בֵּין הַאי לְהַאי. אֶלָּא הָכִי תָּנֵינָן, וַיְיָ' נָתַן חָכְמָה לִשְׁלֹמֹה. וְהַאי חָכְמָה בְּמַאי אוֹקִים לָהּ. אָמַר רִבִּי יוֹסֵי, אוֹקִים לָהּ בְּהַאי, בְּקַדְמִיתָא, דִּשְׁלֹמֹה עֲבַד דְּנָחִית לְחִירָם מֵהַהוּא דַּרְגָּא, דְּהֲוָה אָמַר, (יחזקאל כ״ח:ב׳) מוֹשָׁב אֱלֹהִים יָשַׁבְתִּי וְגוֹ', דְּתַנְיָא, חִירָם מֶלֶךְ צוֹר עָבֵד גַּרְמֵיהּ אֱלוֹהַּ. בָּתַר דִּשְׁלֹמֹה אָתָא, עֲבַד לֵיהּ בְּחָכְמָתֵיהּ, דְּנָחִית מֵהַהוּא עֵיטָא, וְאוֹדֵי לֵיהּ לִשְׁלֹמֹה. וּבְגִין כָּךְ, (מלכים א ה׳:כ״ו) וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה.","וְתָנֵינָן, אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוּדָה, דְּשָׁדַר לֵיהּ, חַד שִׁידָא, וְנָחִית לְיָד שִׁבְעָה מָדוֹרִין דְּגֵיהִנָּם וְסַלְקֵיהּ, וְשָׁדַר לֵיהּ פִּתְקִין בְּכָל יוֹמָא וְיוֹמָא בִּידֵיהּ, עַד דְּאָהֲדָר, וְאוֹדֵי לֵיהּ לִשְׁלֹמֹה. וְתָנֵינָן. (ויחי רכ\"ג, רכ\"ה) שְׁלֹמֹה יָרִית לָהּ לְסִיהֲרָא, בְּכָל סִטְרוֹי. בְּגִין כָּךְ, בְּכֹלָּא שַׁלִּיט בְּחָכְמָתֵיהּ. וְרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, שַׁלִּיט בְּחָכְמָתֵיהּ עַל כָּל בְּנֵי עָלְמָא, כָּל אִינּוּן דְּסַלְּקִין בְּדַרְגּוֹי, לָא סַלְּקִין אֶלָּא לְאַשְׁלְמָא עִמֵּיהּ. (ס\"א אי לא שלמין עמיה)","פָּתַח רִבִּי יוֹסֵי וְאָמַר, (שיר השירים ב׳:י״ד) יוֹנָתִי בְּחַגְוִי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה וְגוֹ'. יוֹנָתִי, דָּא כְּנֶסֶת יִשְׂרָאֵל, מַה יוֹנָה לָא שַׁבְקָת בֶּן זוּגָהּ לְעָלְמִין, כַּךְ כְּנֶסֶת יִשְׂרָאֵל לָא שַׁבְקָת לְּקוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין. בְּחַגְוִי הַסֶּלַע, אִלֵּין תַּלְמִידֵי חֲכָמִים, דְּלָא מִשְׁתַּכְּחֵי בְּנַיְיחָא בְּעָלְמָא דֵּין. בְּסֵתֶר הַמַּדְרֵגָה, אִלֵּין תַּלְמִידֵי חֲכָמִים, הַצְּנוּעִין, דִּבְהוֹן חֲסִידִין דַּחֲלֵי קוּדְשָׁא בְּרִיךְ הוּא, דִּשְׁכִינְתָּא לָא אַעְדֵּי מִנַיְיהוּ לְעָלְמִין. כְּדֵין, קוּדְשָׁא בְּרִיךְ הוּא מִתְּבַע בְּגִינַיְיהוּ לִכְּנֶסֶת יִשְׂרָאֵל, וְאָמַר, הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִנִי אֶת קוֹלֵךְ כִּי קוֹלֵךְ עָרֵב, דְּלֵית קָלָא מִשְׁתְּמַע לְעֵילָּא, אֶלָּא קָלָא דְּאִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא.","וְתָאנָא, כָּל אִינּוּן דְּמִתְעַסְּקֵי בְּאוֹרַיְיתָא, בְּלֵילְיָא, דִּיּוּקְנֵיהוֹן אִתְחַקָּק לְעֵילָּא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעְשַׁע בְּהוּ כּוּלֵיהּ יוֹמָא, וּמִסְתְּכַּל בְּהוּ. וְהַהוּא קָלָא, (דהכא) סָלִיק וּבָקַע כָּל אִינּוּן רְקִיעִין, עַד דְּסָלִיק קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין כְּתִיב, כִּי קוֹלֵךְ עָרֵב וּמַרְאֵךְ נָאוְה. וְהַשְׁתָּא קוּדְשָׁא בְּרִיךְ הוּא חָקַק דִּיּוּקְנָא דְּרַבִּי שִׁמְעוֹן לְעֵילָּא וְקָלֵיהּ לְעֵילָּא לְעֵילָּא סַלְּקָא, וּמִתְעַטְּרָא בְּכִתְרָא קַדִּישָׁא, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא מִתְעַטָּר בֵּיהּ בְּכֻלְּהוּ עָלְמִין. וּמִשְׁתְּבַּח בֵּיהּ. עָלֵיהּ כְּתִיב, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר.","פָּתַח רִבִּי חִיָּיא וְאָמַר, (קהלת ג׳:ט״ו) מַה שֶׁהָיָה כְּבָר הוּא (נקרא שמו ל\"ג) וַאֲשֶׁר לִהְיוֹת וְגוֹ'. מַה שֶׁהָיָה כְבָר, הַיְינוּ דְּתָנֵינָן, עַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא הַאי עָלְמָא, הֲוָה בָּארֵי עָלְמִין וְחָרִיב לוֹן, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא סָלִיק בִּרְעוּתֵיהּ, לְמִבְרֵי הַאי עָלְמָא, וְאַמְלִיךְ בְּאוֹרַיְיתָא. כְּדֵין אִתְתָּקַּן הוּא בְּתִקּוּנוֹי, וְאִתְעַטָּר בְּעִטְרוֹי, וּבָרָא הַאי עָלְמָא. וְכָל מַאי דְּאִשְׁתְּכַח בְּהַאי עָלְמָא, הָא הֲוָה קַמֵּיהּ, (והא סליק מקמיה) וְאִתְתָּקַּן קַמֵּיהּ."],[[0,"ותנינן קמיה דמר וכו׳:","ולמדנו לפני אדוני, מהו קדש. הוא שלמות הכל שנקראת חכמה עליונה, שה״ס או״א עלאין. וממקום הזה נוזל שמן משחת קדש בשבילים ידועים למקום שנקרא בינה עליונה. שה\"ס ישסו״ת, ומשם יוצאים מבועים ונחלים לכל צד. דהיינו בין לחכמה ובין לחסדים, עד שמגיעים ל \u0003זאת\u0004 הזו. שהיא מלכות. וזאת ההיא כשהיא מתברכת היא נקראת \u0003קדש,\u0004 ונקראת \u0003חכמה,\u0004 וקוראים לה \u0003רוח הקודש.\u0004 כלומר, רוח, דהיינו ו״ק, מקדש הזה שלמעלה, דהיינו ו״ק דחכמה. וכשיוצאים ומתעוררים ממנה סודות התורה, היא נקראת \u0003לשון הקדש.\u0004"],[1,"ובשעתא דנגיד וכו׳:","ובשעה שנמשכת משחת קדש ההיא, לאלו ב׳ עמודים, הנקראים למודי ה׳, ונקראים צבאות, שהם נצח והוד. היא מתקבצת שם, וכשיוצאת משם במדרגה ההיא שנקראת יסוד, ובאה לחכמה קטנה ההיא, שהיא מלכות, הנקראת חכמה קטנה, משום שאין בה רק ו״ק דחכמה, כנ״ל בדבור הסמוך, אז היא נקראת \u0003לשון למודים.\u0004 וממנה יוצאת להעיר לאלו קדושים עליונים. אז כתוב, ה׳ אלקים נתן לי \u0003לשון למודים.\u0004 ולמה. לדעת לעות את יעוף דבר. והקב״ה נתן את זה למאור הקדוש ר׳ שמעון. ועוד, שהעלה אותו למעלה למעלה. לעולמות העליונים. משום זה כל דבריו נאמרו בגלוי, ואינם מכוסים. עליו כתוב, פה אל פה אדבר בו ומראה ולא בחידות."],[2,"פתח ר׳ ייסא וכו׳:","פר״י ואמר, וה׳ נתן חכמה לשלמה כאשר דבר לו ויהי שלום בין חירם ובין שלמה וגו'. \u0003וה׳ נתן חכמה לשלמה,\u0004 זהו שלמדנו, בימיו של שלמה המלך עמדה הלבנה, שהיא המלכות, במילואה שאז נקראת המלכות חכמה, כנ״ל. ונתן אותה לשלמה. \u0003כאשר דבר לו,\u0004 היינו כמו שנאמר לו, החכמה והמדע נתון לך."],[3,"ויהי שלום בין חירם ובין שלמה:","שואל, וכי מה היה בין לזה. ומשיב, אלא כך למדנו, וה׳ נתן חכמה לשלמה. וחכמה זו במה השליט אותה. א״ר יוסי, השליט אותה תחילה בזה. ששלמה עשה לחירם שירד מאותה המדרגה, שהיה אומר, מושב אלהים ישבתי וגו', שלמדנו, חירם מלר צור עשה עצמו אלוה. דהיינו שנתדבק באלהים אחרים הממשיכים החכמה ממעלה למטה, כנ״ל ועשה את עצמו כמותם. אחר שבא שלמה, עשה לו בחכמתו, שירד מעצה זו, דאלהים אחרים. והודה בשביל זה לשלמה. ומשום כך, ויהי שלום בין חירם ובין שלמה."],[4,"ותנינן א״ר יצחק וכו׳:","ולמדנו, אר״י א״ר יהודה, ששלמה שלח לחירם, שד אחד, שהורידו לז׳ מדורי גיהגם, והעלהו. ושלח כתבים בכל יום ויום לידו, עד שחזר ממעשיו, והודה לשלמה על זה. ולמדנו. שלמה ירש את הלבנה, שהיא המלכות בכל צדדיה. הן בחכמה והן בחסדים, משום זה שלט על הכל בחכמתו. ור׳ שמעון בן יוחאי שולט בחכמתו על כל בני העולם, וכל אלו שעולים במדרגותיו, אינם עולים אלא להשלים המלכות עמו."],[5,"פתח ר׳ יוסי וכו׳:","פר״י ואמר, יונתי בחגוי הסלע בסתר המדרגה. \u0003יונתי,\u0004 זו היא כנסת ישראל, שהיא המלכות, מה יונה אינה עוזבת את בן זוגה לעולם, כך כנסת ישראל אינה עוזבת את הקב״ה לעולם. \u0003בחגוי הסלע,\u0004 אלו הם תלמידי חכמים, שאינם נמצאים במנוחה בעולם הזה, וכמו שמסתירים את עצמם בחגוי הסלע מפני אויביהם. \u0003בסתר המדרגה,\u0004 אלו הם ת״ח הצנועים, המסתירים מדרגתם מפני בני אדם, שבהם חסידים, יראי הקב״ה, שהשכינה אינה סרה מהם לעולם. אז, הקב״ה תובע מכנסת ישראל בשבילם, ואמר, הראיני את מראיך השמיעני את קולך כי קולך ערב, כי אין קול נשמע למעלה, אלא הקול של אלו העוסקים בתורה."],[6,"ותאנא כל אינון וכו׳:","ולמדנו, כל אלו העוסקים בתורה בלילה, נחקקת צורתם למעלה לפני הקב״ה, והקב״ה משתעשע בהם כל היום ומסתכל בהם. וקול ההוא עולה ובוקע כל הרקיעים, עד שעולה לפני הקב״ה. אז כתוב, כי קולר ערב ומראך נאוה. ועתה הקב״ה חקק צורת ר״ש למעלה, וקולו עולה למעלה למעלה, ומתעטר בכתר הקדוש, עד שהקב״ה מתעטר בו בכל העולמות ומשתבת בו. עליו כתוב, ויאמר לי עבדי עתה ישראל אשר בך אתפאר."],[7,"פתח ר׳ חייא וכו׳:","פר״ח ואמר, מה שהיה כבר הוא ואשר להיות וגו'. \u0003מה שהיה כבר הוא,\u0004 היינו שלמדנו, מטרם שברא הקב״ה עולם הזה, היה בורא עולמות ומחריבם שה״ס שבירת הכלים, עד שעלה ברצון של הקב״ה, לברוא עולם הזה, ונועץ עם התורה. שה״ס קו האמצעי. אז הוא נתתקן בתקוניו, ונתעטר בעטרותיו, וברא עולם זה. וכל מה שנמצא בעולם הזה, היה אז לפניו, בעת הבריאה, ונתתקן לפניו."]],[[0,"","(בקדש). וְשָׁנִינוּ לִפְנֵי מוֹרֵנוּ, מַה זֶּה קֹדֶשׁ? שְׁלֵמוּת הַכֹּל שֶׁנִּקְרֵאת הַחָכְמָה הָעֶלְיוֹנָה. וּמֵהַמָּקוֹם הַזֶּה (שופע שמן משחת קדש בשבילים ידועים למקום שנקרא בינה עליונה), וּמִשָּׁם יוֹצְאִים מַעְיָנוֹת וּנְחָלִים לְכָל עֵבֶר, עַד שֶׁמַּגִּיעִים לְזֹּאת הַזּוֹ. (וממקום זה מתעוררת רוח קדושה) וכשמתברכת הזאת הזו, נקראת קדש, ונקראת חכמה, וקוראים לה (והזאת הזו כשמתברכת ממקום עליון, זה שנקרא קדש ונקרא חכמה, קוראים לו) רוח הקדש. כלומר, רוח מאותו קדש שלמעלה. וכשיוצאים ומתעוררים ממנה סודות התורה, אז נקראת לשון הקדש."],[1,"","וּבְשָׁעָה שֶׁשּׁוֹפֵעַ אוֹתוֹ מִשְׁחַת קֹדֶשׁ לְאוֹתָם שְׁנֵי עַמּוּדִים, שֶׁנִּקְרָאִים לִמּוּדֵי ה', וְנִקְרָאִים צְבָאוֹת, מִתְכַּנֵּס לְשָׁם, וּכְשֶׁיּוֹצֵא מִשָּׁם בְּאוֹתָהּ דַּרְגָּה שֶׁנִּקְרֵאת יְסוֹד, לְאוֹתָהּ חָכְמָה קְטַנָּה, אָז נִקְרֵאת לְשׁוֹן לִמּוּדִים, וְיוֹצֵאת לְהָעִיר אוֹתָם קְדוֹשִׁים עֶלְיוֹנִים. אָז כָּתוּב, ה' אֱלֹהִים נָתַן לִי לְשׁוֹן לִמּוּדִים. וְלָמָּה? לָדַעַת לָעוּת אֶת יָעֵף דָּבָר. וְהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אֶת זֶה לַמְּנוֹרָה הַקְּדוֹשָׁה, רַבִּי שִׁמְעוֹן. וְעוֹד, שֶׁהֶעֱלָה אוֹתוֹ לְמַעְלָה לְמַעְלָה, וּמִשׁוּם כָּךְ כָּל דְּבָרָיו בַּנִּגְלֶה נֶאֱמָרִים, וְלֹא מְכֻסִּים. עָלָיו כָּתוּב, (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת."],[2,"","פָּתַח רַבִּי יֵיסָא וְאָמַר, (מלכים א ה) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה וְגוֹ'. וַה' נָתַן חָכְמָה לִשְׁלֹמֹה, זֶהוּ שֶׁשָּׁנִינוּ, בִּימֵי שְׁלֹמֹה הַמֶּלֶךְ עָמְדָה הַלְּבָנָה בִּשְׁלֵמוּתָהּ, כַּאֲשֶׁר דִּבֶּר לוֹ, כְּמוֹ שֶׁנֶּאֱמַר לוֹ, הַחָכְמָה וְהַמַּדָּע נָתוּן לָךְ."],[3,"","וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה. וְכִי מַה (בין) זֶה לָזֶה? אֶלָּא כָּךְ שָׁנִינוּ, וַה' נָתַן חָכְמָה לִשְׁלֹמֹה. וְאֶת הַחָכְמָה הַזּוֹ בַּמָּה הֶעֱמִיד אוֹתָהּ? אָמַר רַבִּי יוֹסֵי, הֶעֱמִיד אוֹתָהּ בָּזֶה בָּרִאשׁוֹנָה, שֶׁשְּׁלֹמֹה עָשָׂה שֶׁהוֹרִיד אֶת חִירָם מֵאוֹתָהּ דַּרְגָּה, שֶׁהָיָה אוֹמֵר (יחזקאל כח) מוֹשַׁב אֱלֹהִים יָשַׁבְתִּי וְגוֹ'. שֶׁלָּמַדְנוּ שֶׁחִירָם מֶלֶךְ צוֹר עָשָׂה עַצְמוֹ אֱלוֹהַּ. אַחַר שֶׁשְּׁלֹמֹה בָּא, עָשָׂה לוֹ בְּחָכְמָתוֹ שֶׁיֵּרֵד מֵאוֹתָהּ עֵצָה וְהוֹדָה לִשְׁלֹמֹה. וּמִשּׁוּם כָּךְ כָּתוּב, (מלכים א ה) וַיְהִי שָׁלוֹם בֵּין חִירָם וּבֵין שְׁלֹמֹה."],[4,"","וְשָׁנִינוּ, אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, שֶׁשָּׁלַח לוֹ שֵׁד אֶחָד, וְהוֹרִיד אוֹתוֹ לְשִׁבְעָה מְדוֹרֵי גֵיהִנֹּם, וְהֶעֱלֶה אוֹתוֹ וְשָׁלַח לוֹ פְּתָקִים בְּכָל יוֹם וָיוֹם בְּיָדוֹ, עַד שֶׁחָזַר וְהוֹדָה לִשְׁלֹמֹה. וְשָׁנִינוּ, שְׁלֹמֹה יָרַשׁ אֶת הַלְּבָנָה בְּכָל הַצְּדָדִים, וּמִשּׁוּם כָּךְ שָׁלַט בַּכֹּל בְּחָכְמָתוֹ. וְרַבִּי שִׁמְעוֹן בַּר יוֹחַאי שׁוֹלֵט בְּחָכְמָתוֹ עַל כָּל בְּנֵי הָעוֹלָם, וְכָל אוֹתָם שֶׁעוֹלִים בְּדַרְגוֹתָיו לֹא עוֹלִים אֶלָּא לְהַשְׁלִים עִמּוֹ (אם לא שלמים עמו)."],[5,"","פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר ב) יוֹנָתִי בְּחַגְוֵי הַסֶּלַע בְּסֵתֶר הַמַּדְרֵגָה וְגוֹ'. יוֹנָתִי - זוֹ כְּנֶסֶת יִשְׂרָאֵל. מַה יּוֹנָה לֹא עוֹזֶבֶת אֶת בֶּן זוּגָהּ לְעוֹלָמִים, כָּךְ כְּנֶסֶת יִשְׂרָאֵל לֹא עוֹזֶבֶת אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא לְעוֹלָמִים. בְּחַגְוֵי הַסֶּלַע - אֵלּוּ תַּלְמִידֵי חֲכָמִים, שֶׁלֹּא נִמְצָאִים בִּמְנוּחָה בָּעוֹלָם הַזֶּה. בְּסֵתֶר הַמַּדְרֵגָה - אֵלּוּ תַּלְמִידֵי חֲכָמִים שֶׁצְּנוּעִים, שֶׁבָּהֶם חֲסִידִים יִרְאֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁשְּׁכִינָה לֹא זָזָה מֵהֶם לְעוֹלָמִים. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא תּוֹבֵעַ אֶת כְּנֶסֶת יִשְׂרָאֵל בִּשְׁבִילָם וְאוֹמֵר, הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִיעִנִי אֶת קוֹלֵךְ כִּי קוֹלֵךְ עָרֵב, שֶׁאֵין קוֹל שֶׁנִּשְׁמָע לְמַעְלָה, אֶלָּא קוֹלָם שֶׁל אֵלּוּ הָעוֹסְקִים בַּתּוֹרָה."],[6,"","וְלָמַדְנוּ, כָּל אוֹתָם הָעוֹסְקִים בַּתּוֹרָה בַּלָּיְלָה, הַדְּיוֹקָן שֶׁלָּהֶם נֶחְקָק לְמַעְלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ בָּהֶם כָּל הַיּוֹם וּמִסְתַּכֵּל בָּהֶם, וְאוֹתוֹ קוֹל (של כאן) עוֹלֶה וּבוֹקֵעַ אֶת כָּל אוֹתָם רְקִיעִים עַד שֶׁעוֹלֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז כָּתוּב, כִּי קוֹלֵךְ עָרֵב וּמַרְאֵיךְ נָאוֶה. וְעַכְשָׁו הַקָּדוֹשׁ בָּרוּךְ הוּא חוֹקֵק אֶת דְּיוֹקְנוֹ שֶׁל רַבִּי שִׁמְעוֹן לְמַעְלָה, וְקוֹלוֹ לְמַעְלָה לְמַעְלָה עוֹלֶה, וּמִתְעַטֵּר בַּכֶּתֶר הַקָּדוֹשׁ, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בּוֹ בְּכָל הָעוֹלָמוֹת וּמִשְׁתַּבֵּחַ בּוֹ. עָלָיו כָּתוּב (ישעיה מט) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךְ אֶתְפָּאָר."],[7,"","פָּתַח רַבִּי חִיָּיא וְאָמַר, (קהלת ג) מַה שֶּׁהָיָה כְּבָר הוּא וַאֲשֶׁר לִהְיוֹת וְגוֹ'. מַה שֶּׁהָיָה כְּבָר, הַיְנוּ מַה שֶּׁשָּׁנִינוּ, שֶׁטֶּרֶם בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם הַזֶּה, הָיָה בּוֹרֵא עוֹלָמוֹת וּמַחֲרִיבָם, עַד שֶׁעָלָה בִרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם הַזֶּה וְנִמְלַךְ בַּתּוֹרָה. אָז הוּא הִתְתַּקֵּן בְּתִקּוּנָיו וְהִתְעַטֵּר בְּעַטְרוֹתָיו, וּבָרָא אֶת הָעוֹלָם הַזֶּה, וְכָל מַה שֶּׁנִּמְצָא בָּעוֹלָם הַזֶּה הֲרֵי הָיָה לְפָנָיו (שהרי עלהמלפניו) וְהִתְתַּקֵּן לְפָנָיו."]]],[["וְתָאנָא, כָּל אִינּוּן דַּבָּרֵי עָלְמָא, דְּאִשְׁתְּכָחוּ בְּכָל דָּרָא וְדָרָא, עַד לָא יֵיתוּן לְעָלְמָא, הָא הֲווֹ קַיְימֵי קַמֵּיהּ בְּדִיּוּקְנֵיהוֹן. (והכי תאנא) אֲפִילּוּ כָּל אִינּוּן נִשְׁמָתִין דִּבְנֵי נָשָׁא, עַד לָא יֶחתוּן לְעָלְמָא, כֻּלְּהוּ גְּלִיפִין קָמֵיהּ בִּרְקִיעָא, בְּהַהוּא דִּיּוּקְנָא מַמָּשׁ, דְּאִינּוּן בְּהַאי עָלְמָא. וְכָל מַה דְּאוֹלְפִין בְּהַאי עָלְמָא, כֹּלָּא יָדְעוּ עַד לָא יֵיתוּן לְעָלְמָא. וְתָנֵינָא, הַאי בְּאִינּוּן זַכָּאֵי קְשׁוֹט.","וְכָל אִינּוּן דְּלָא מִשְׁתַּכְּחִין זַכָּאִין בְּהַאי עָלְמָא, אֲפִילּוּ תַּמָּן, מִתְרַחֲקִין מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְעָאלִין בְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, וְדַחֲקִין שַׁעֲתָא, וְנַחְתִּין לְעָלְמָא. וְהַהִיא נִשְׁמְתָא דִּלְהוֹן, הָא אוֹלִיפְנָא, כְּמָה דְּאִינּוּן קְשֵׁי קְדָל בְּהַאי עָלְמָא, כַּךְ הֲווֹ עַד לָא יֵיתוּן לְעָלְמָא. וְהַהוּא חוּלָקָא קַדִּישָׁא דְּיָהַב לוֹן רָמָאן לֵיהּ, וְאָזְלִין וְשָׁאטִין וְאַסְתַּאָבוּן, בְּהַהוּא נוּקְבָּא דִּתְהוֹמָא רַבָּא, וְנַטְלֵי חוּלָקֵיהוֹן מִתַּמָּן, וְדַחֲקִין שַׁעֲתָא וְנַחְתֵּי לְעָלְמָא. אִי זָכֵי לְבָתַר, וְתָב בְּתִיּוּבְתָּא קָמֵי מָארֵיהּ, הוּא נָטִיל הַהוּא חוּלָקָא דִּילֵיהּ מַמָּשׁ, הֲדָא הוּא דִכְתִיב, מַה שֶׁהָיָה כְּבָר (נקרא שמו) הוּא וַאֲשֶׁר לִהְיוֹת וְגוֹ' כְּבָר הָיָה.","תָּא חֲזֵי בְּנֵי אַהֲרֹן לָא אִשְׁתְּכָחוּ בְּיִשְׂרָאֵל כְּוָותַיְיהוּ, בַּר מֹשֶׁה וְאַהֲרֹן, וְאִינּוּן אִקְרוּן (שמות כ״ד:ט׳) אֲצִילֵי בְּנֵי יִשְׂרָאֵל. וְעַל דְּטָעוּ קָמֵי מַלְכָּא קַדִּישָׁא, מִיתוּ. וְכִי קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאוֹבָדָא לוֹן, וְהָא תָּנֵינָן בְּרָזָא דְּמַתְנִיתִין, דְּקוּדְשָׁא בְּרִיךְ הוּא עָבֵד חֶסֶד בְּכֹלָּא, וַאֲפִילּוּ בְּרַשִׁיעֵי עָלְמָא לָא בָּעֵי לְאוֹבָדָא לוֹן. וְהָנֵי זַכָּאֵי קְשׁוֹט סַלְּקָא דַּעְתָּךְ דְּאִינּוּן אִתְאֲבִידוּ מֵעָלְמָא, זְכוּתָא דִּלְהוֹן אָן הוּא. זְכוּתָא דְּאָבוּהוֹן אָן הוּא. זְכוּתָא דְּמֹשֶׁה הָכִי נָמֵי. וְאִינּוּן הֵיךְ אִתְאֲבִידוּ.","אֶלָּא הָכִי אוֹלִיפְנָא מִבּוּצִינָא קַדִּישָׁא, דְּקוּדְשָׁא בְּרִיךְ הוּא חָס עַל יְקָרָא דִּלְהוֹן, וְאִתּוֹקַד גַּרְמֵיהוֹן לְגוֹ, וְנִשְׁמָתֵהוֹן לָא אִתְאֲבִידוּ, וְהָא אוֹקִימְנָא. וְתָּא חֲזֵי עַד לָא מִיתוּ בְּנֵי אַהֲרֹן כְּתִיב, (שמות ו׳:כ״ה) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ וְגוֹ', אִקְרֵי שְׁמֵיהּ פִּנְחָס, דְּהֲוָה זַמִּין לְאִתְתָּקְנָא עֲקִימָא, הֲדָא הוּא דִכְתִיב וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה.","וְתָאנָא, כֻּלְּהוּ זַכָּאֵי קְשׁוֹט, עַד לָא יֵיתוּן לְעָלְמָא, כֻּלְּהוּ אִתְתְּקָנוּ לְעֵילָּא, וְאִקְרוּן בִּשְׁמָהָן. וְרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, מִן יוֹמָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, הֲוָה אִזְדְּמַן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתְּכַח עִמֵּיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ בִּשְׁמֵיהּ, זַכָּאָה חוּלָקֵיהּ לְעֵילָּא וְתַתָּא, עָלֵיהּ כְּתִיב (משלי כ״ג:כ״ה) יִשְׂמַח אָבִיךָ וְאִמֶּךָ, אָבִיךָ: דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאִמֶּךָ: דָּא כְּנֶסֶת יִשְׂרָאֵל.","פָּתַח רִבִּי אַבָּא וְאָמַר (שיר השירים א׳:י״ב) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח וְזַמִּין בְּטוּרָא דְּסִינַי, לְמֵיהַב אוֹרַיְיתָא לְיִשְׂרָאֵל, נִרְדִּי נָתַן רֵיחוֹ, יִשְׂרָאֵל יָהֲבוּ וּסְלִיקוּ רֵיחָא טַב, דְּקָאִים וְאָגִין עָלַיְיהוּ לְדָרֵי דָּרִין. וְאָמְרוּ, (שמות כ״ד:ז׳) כָּל אֲשֶׁר דִּבֶּר יְיָ' נַעֲשֶׂה וְנִשְׁמָע. דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ, בְּעוֹד דְּסָלִיק מֹשֶׁה לְקַבְּלָא אוֹרַיְיתָא מְקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְחֲקָק בִּתְרֵי לוּחֵי אֲבָנִין, יִשְׂרָאֵל שָׁבְקוּ הַהוּא רֵיחָא טָבָא דְּהֲוָה מִתְעַטֵּר עָלַיְיהוּ, וְאָמְרוּ לָעֵגֶל, אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל.","הַשְׁתָּא הַאי קְרָא בְּרָזָא דְּחָכְמְתָא הוּא, תָּא חֲזֵי, כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, הַאי נַהֲרָא אִתְפְּשָׁט בְּסִטְרוֹי, בְּשַׁעֲתָא דְּמִזְדְּוַּוג עִמֵּיהּ בְּזִוּוּגָא שְׁלִים, כָּדֵי הַאי עֵדֶן (זווגא) בְּהַהוּא נָתִיב, דְּלָא אִתְיְידַע לְעֵילָּא וְתַתָּא, כְּמָה דְאַתְּ אָמֵר (איוב כ״ח:ז׳) נָתִיב לֹא יְדָעוֹ עָיִט. וְאִשְׁתְּכָחוּ בִּרְעוּתָא (שמות ע\"ז, נ\"ה, ס\"ד ע\"ב) דְּלָא מִתְפָּרְשָׁן תְּדִירָא חַד מֵחַד. כְּדֵין נָפְקִין מַבּוּעִין וּנְחָלִין, וּמְעַטְּרִין לְבֵן קַדִּישָׁא, בְּכָל אִינּוּן כִּתְרִין, כְּדֵין (שמות כ\"ד ע\"א) כְּתִיב (שיר השירים ג׳:י״א) בַּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. וּבְהַהִיא שַׁעֲתָא יָרִית הַהוּא בֵּן אַחֲסַנְתָּא דַּאֲבוֹי וְאִמֵּיהּ, כְּדֵין הוּא אִשְׁתַּעֲשַׁע, בְּהַהוּא עִנּוּגָא וְתַפְנוּקָא."],[[0,"ותאנא כל אינון וכו׳:","ולמדנו, כל אלו מנהיגי העולם הנמצאים בכל דור ודור, מטרם שבאו לעולם היו נמצאים לפני הקב״ה בצורותיהם. ואפילו כל אלו נשמות בני אדם, עד שלא תבואנה לעולם, כולן חקוקות לפניו ברקיע, באותה הצורה ממש, שהם בעולם הזה. וכל מה שלומדות בעולם הזה, יודעות הכל בטרם שתבואנה לעולם. ולמדנו, שכל זה הוא בצדיקי אמת."],[1,"וכל אינון דלא וכו׳:","וכל אלו שאינם נמצאים צדיקים בעולם הזה, אפילו שם, למעלה, מטרם שבאו לעולם, מתרחקים מלפני הקב״ה, ונכנסים בנקב תהום הגדול, ודוחקים את השעה, ויורדים לעולם. ונשמה ההיא שלהם, הנה למדנו, כמו שהיא קשת עורף בעולם הזה, כך היתה מטרם שבאה לעולם. ואותו החלק הקדוש שנתן להם הקב״ה מצד הקדושה זורקים אותו, והולכים ומשוטטים ונטמאים בנקב ההוא של התהום הגדול, ולוקחים חלקם משם, ודוחקים את השעה ויורדים לעולם. אם זכה אחר כך וחזר בתשובה לפני רבונו, הוא לוקח החלק ההוא שלו ממש, דהיינו חלק הקדושה שהשליך למעלה, כנ״ל, ז״ש, מה שהיה כבד הוא ואשר להיות כבר היה וגו'."],[1,"","פירוש. כי בעת בריאת הנשמות, בעודם למעלה, מטרם שבאו לעולם הזה תחת הזמן, הם נמצאים בבחינת הנצחיות שלמעלה מזמן, אשר היה הוה ויהיה משמשים שם בבת אחת כטבע הנצחיות, ונמצא שכל המעשים שיעשו הנשמות בזה אחר זה, כשיבואו בעולם הזה, כבר הם נמצאים שמה בבת אחת. וז״ש צ״ה) \u0003כל אינון נשמתין וכו׳ בההוא דיוקנא ממש דאינון בהאי עלמא.\u0004 דהיינו, כמעשיהם בעוה״ז. וז״ש (שם) \u0003וכל מה דאולפין בהאי עלמא כלא ידעו עד לא ייתון לעלמא,\u0004 כי כל התורה שעתידים ללמוד בעולם הזה במשך ימי שני חייהם, כבר היא נמצאת כולה שמה. וז״ש \u0003וכל אינון דלא משתכחין זכאין בהאי עלמא, אפילו תמן מתרחקין מקמי קב״ה\u0004 וכו', שכל מעשיהם הרעים כבר מצוירים בנשמתם. וכמו שעתידים להשליך חלק הקדושה בעולם הזה, כן גם שם, \u0003וההוא חולקא קדישא דיהב לון רמאן ליה,\u0004 וכו'. ואם עתידים בעוה״ז לחטוא ולעשות תשובה, בזה אחר זה מצויר זה למעלה בבת אחת כטבע הנצחיות. וז״ש \u0003אי זכי לבתר ותב בתיובתא קמי מאריה הוא נטיל ההוא חולקא\u0004 וכו'. שגם זה כבר מצויר שם. ויש הפרש בין הנשמה העתידה להיות בצדיק ובין העתידה להיות ברשע. כי העתידה להיות בצדיק נמצאת כבר שמה בכל קדושתה, כנ״ל, וע״כ אינה רוצה לבא לעוה״ז לחומר הגוף המזוהם. אלא בגזירת הקב״ה. אבל אותה הנשמה העתידה להיות ברשע, היא דוחקת את השעה לבא להתלבש בגוף המזוהם. כי היא חושקת לזוהמא. וז״ש \u0003ודחקין שעתא ונחתי לעלמא.\u0004"],[2,"תא חזי בני וכו׳:","בוא וראה בני אהרן לא נמצאו כמוהם בישראל חוץ ממשה ואהרן. והם נקראו אצילי בני ישראל, ומשום שטעו לפני המלך הקדוש מתו. שואל, וכי הקב״ה, רצה לאבד אותם. והרי למדנו, בסוד המשנה, שהקב״ה עושה חסד עם הכל, ואפילו רשעי עולם אינו רוצה לאבד. ואלו צדיקי אמת, נדב ואביהוא, היעלה על דעתך, שהם נאבדו מן העולם, הזכות שלהם איפה היא, זכות אבותם איפה היא, וגם כן זכותו של משה. ואיך נאבדו."],[3,"אלא הכי אוליפנא וכו׳:","ומשיב אלא כך למדנו ממאור הקדוש, שהקב״ה חס על כבודם, ונשרף גופם בפנימיותו, ונשמתם לא נאבדה. וכבר העמדנו. ובוא וראה עד שלא מתו בני אהרן, כתוב, ואלעזר בן אהרן לקח לו וגו׳ ותלד את פנחס. ונקרא שמו פנחס, משום שהיה עתיד לתקן את העקום, דהיינו לתקן הפגם של נדב ואביהוא כמ״ש לעיל וכ״ה) ואע״פ שנדב ואביהוא עוד לא מתו. ז״ש ואשר להיות כבר היה."],[4,"ותאנא כלהו זכאי וכו׳:","ולמדנו, כל צדיקי אמת, מטרם שיבואו לעולם, כולם מתתקנים למעלה ונקראים בשמות. ור' שמעון בן יוחאי מיום שברא הקב״ה העולם, היה מוכן לפני הקב״ה ונמצא עמו, והקב״ה קרא אותו בשמו, אשרי חלקו למעלה ולמטה. עליו כתוב, ישמח אביך ואמך. \u0003אביך\u0004 זה הקב״ה. \u0003ואמך\u0004 זו, כנסת ישראל."],[5,"פתח ר׳ אבא וכו׳:","פר״א, ואמר, עד שהמלך במסבו נרדי נתן ריחו. מקרא זה העמידו החברים. בשעה שהקב״ה היה מוכן ונמצא בהר סיני לתת התורה לישראל, \u0003נרדי נתן ריחו,\u0004 שישראל נתנו והעלו ריח טוב, העומד ומגן עליהם לדורי דורות, ואמרו, כל אשר דבר ה׳ נעשה ונשמע. פירוש אחר. עד שהמלך במסבו, בעוד שעלה משה לקבל התורה מהקב״ה, שנחקקה בשני לוחות אבנים, עזבו ישראל אותו ריח הטוב שהיה מתעטר עליהם, ואמרו לעגל, אלה אלהיך ישראל."],[6,"השתא האי קרא וכו׳:","עתה נבאר מקרא זה בסוד החכמה. בוא וראה, כתוב, ונהר יוצא מעדן להשקות את הגן. נהר זה, שהוא בינה, מתפשט בצדדיו, בשעה שמזדווג עמו העדן הזה שהוא חכמה בזווג שלם, בנתיב הזה שלא נודע למעלה ולמטה, שהוא יסוד דחכמה, כש״א נתיב לא ידעו עיט, ונמצאים חכמה ובינה, ברצון שאינם נפרדים מעולם זה מזה, אז יוצאים מהם, מבועים ונחלים, שהם המוחין דז\"א, ומעטרים לבן הקדוש, ז״א, שהוא בן י״ה, בכל אלו הכתרים, שהם המוחין. אז כתוב, בעטרה שעטרה לו אמו. שהם המוחין הנקראים עטרה. ובאותה שעה יורש הבן ההוא, ז״א, נחלת אביו ואמו, דהיינו המוחין היוצאים מזווג חכמה ובינה, שהם נקראים אבא ואמא, אז הוא משתעשע בעונג ובעדן ההוא."]],[[0,"","וְשָׁנִינוּ, כָּל אוֹתָם מַנְהִיגֵי הָעוֹלָם שֶׁנִּמְצָאִים בְּכָל דּוֹר וָדוֹר, טֶרֶם שֶׁיָּבאוּ לָעוֹלָם, הֲרֵי הָיוּ עוֹמְדִים לְפָנָיו בַּדְּיוֹקָן שֶׁלָּהֶם. (וכך שנינו) אֲפִלּוּ כָּל אוֹתָן נִשְׁמוֹת בְּנֵי הָאָדָם טֶרֶם שֶׁיָּרְדוּ לָעוֹלָם, כֻּלָּן חֲקוּקוֹת לְפָנָיו בָּרָקִיעַ בְּאוֹתוֹ דְיוֹקָן מַמָּשׁ שֶׁהֵם בָּעוֹלָם הַזֶּה. וְכָל מַה שֶּׁלּוֹמְדִים בָּעוֹלָם הַזֶּה, הַכֹּל יָדְעוּ טֶרֶם בּוֹאָם לָעוֹלָם. וְשָׁנִינוּ, זֶה בְּאוֹתָם צַדִּיקֵי אֱמֶת."],[1,"","וְכָל אוֹתָם שֶׁאֵין נִמְצָאִים צַדִּיקִים בָּעוֹלָם הַזֶּה, אֲפִלּוּ שָׁם מְרֻחָקִים מִלִּפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִכְנָסִים לְנֶקֶב תְּהוֹם רַבָּה, וְדוֹחֲקִים אֶת הַשָּׁעָה וְיוֹרְדִים לָעוֹלָם. וְאוֹתָהּ הַנְּשָׁמָה שֶׁלָּהֶם, הֲרֵי לָמַדְנוּ, כְּמוֹ שֶׁהֵם קְשֵׁי עֹרֶף בָּעוֹלָם הַזֶּה, כָּךְ הָיוּ טֶרֶם בּוֹאָם לָעוֹלָם. וְאֶת אוֹתוֹ חֵלֶק קָדוֹשׁ שֶׁנָּתַן לָהֶם זָרְקוּ אוֹתוֹ, וְהוֹלְכִים וּמְשׁוֹטְטִים וְנִטְמָאִים בְּאוֹתוֹ נֶקֶב תְּהוֹם רַבָּה, וְנוֹטְלִים חֶלְקָם מִשָּׁם, וְדוֹחֲקִים אֶת הַשָּׁעָה וְיוֹרְדִים לָעוֹלָם. אִם זוֹכֶה אַחַר כָּךְ וְשָׁב בִּתְשׁוּבָה לִפְנֵי רִבּוֹנוֹ - הוּא נוֹטֵל אֶת אוֹתוֹ חֵלֶק שֶׁלּוֹ מַמָּשׁ. זֶהוּ שֶׁכָּתוּב, (קהלת ו) מַה שֶּׁהָיָה כְּבָר (נקרא שמו) הוּא, (שם ג) וַאֲשֶׁר לִהְיוֹת וְגוֹ' כְּבָר הָיָה."],[2,"","בֹּא רְאֵה, לֹא נִמְצְאוּ כְמוֹ בְּנֵי אַהֲרֹן בְּיִשְׂרָאֵל, פְּרָט לְמֹשֶׁה וְאַהֲרֹן, וְהֵם נִקְרְאוּ אֲצִילֵי בְּנֵי יִשְׂרָאֵל. וְעַל שֶׁטָּעוּ לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ מֵתוּ. וְכִי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְאַבְּדָם? וַהֲרֵי שָׁנִינוּ בְּסוֹד הַמִּשְׁנָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם הַכֹּל, וַאֲפִלּוּ אֶת רִשְׁעֵי הָעוֹלָם אֵינוֹ רוֹצֶה לְאַבְּדָם, וְצַדִּיקֵי הָאֱמֶת הַלָּלוּ, הֲיַעֲלֶה עַל דַּעְתְּךְ שֶׁנֶּאֶבְדוּ מִן הָעוֹלָם?! אֵיפֹה הַזְּכוּת שֶׁלָּהֶם? אֵיפֹה הַזְּכוּת שֶׁל אֲבִיהֶם, וּזְכוּתוֹ שֶׁל מֹשֶׁה גַּם כֵּן? וְאֵיךְ הֵם נֶאֶבְדוּ?"],[3,"","אֶלָּא כָּךְ לָמַדְנוּ מֵהַמָּאוֹר הַקָּדוֹשׁ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל כְּבוֹדָם, וְנִשְׂרַף גּוּפָם בִּפְנִים, וְנִשְׁמָתָם לֹא נֶאֶבְדָה, וַהֲרֵי בֵּאַרְנוּ. וּבא רְאֵה, טֶרֶם שֶׁמֵּתוּ בְּנֵי אַהֲרֹן, כָּתוּב (שמות ו) וְאֶלְעָזָר בֶּן אַהֲרֹן לָקַח לוֹ וְגוֹ', נִקְרָא שְׁמוֹ פִּנְחָס, שֶׁהָיָה עָתִיד לְתַקֵּן אֶת הֶעָקֹם. זֶהוּ שֶׁכָּתוּב וַאֲשֶׁר לִהְיוֹת כְּבָר הָיָה. וְלָמַדְנוּ, כָּל צַדִּיקֵי הָאֱמֶת טֶרֶם"],[4,"","שֶׁיָּבאוּ לָעוֹלָם, כֻּלָּם מְתֻקָּנִים לְמַעְלָה וְנִקְרָאִים בְּשֵׁמוֹת. וְרַשְׁבִּ\"י, מִיּוֹם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הָיָה מְזֻמָּן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִמְצָא עִמּוֹ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא אוֹתוֹ בִּשְׁמוֹ, אַשְׁרֵי חֶלְקוֹ לְמַעְלָה וּלְמַטָּה, עָלָיו כָּתוּב (משליכג) יִשְׂמַח אָבִיךְ וְאִמֶּךְ. אָבִיךְ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא. וְאִמֶּךְ - זוֹ כְּנֶסֶת יִשְׂרָאֵל."],[5,"","פָּתַח רַבִּי אַבָּא וְאָמַר, (שיר א) עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. אֶת הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ הַחֲבֵרִים בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה נִמְצָא וּמְזֻמָּן בְּהַר סִינַי לָתֵת תּוֹרָה לְיִשְׂרָאֵל. נִרְדִּי נָתַן רֵיחוֹ, יִשְׂרָאֵל נָתְנוּ וְהָעֱלוּ רֵיחַ טוֹב שֶׁעָמַד וְהֵגֵן עֲלֵיהֶם לְדוֹרוֹ דוֹרוֹת, וְאָמְרוּ (בראשית א) כָּל אֲשֶׁר דִּבֶּר ה' נַעֲשֶׂה וְנִשְׁמָע. דָּבָר אַחֵר עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ - בְּעוֹד שֶׁעָלָה מֹשֶׁה לְקַבֵּל תּוֹרָה מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וְנֶחְקְקָה בִּשְׁנֵי לוּחוֹת אֲבָנִים, עָזְבוּ יִשְׂרָאֵל אֶת אוֹתוֹ רֵיחַ טוֹב שֶׁהָיָה מִתְעַטֵּר עֲלֵיהֶם, וְאָמְרוּ לָעֵגֶל, אֵלֶּה אֱלֹהֶיךְ יִשְׂרָאֵל."],[6,"","עֵכְשָׁו פָּסוּק זֶה הוּא בְּסוֹד הַחָכְמָה. בּא רְאֵה, כָּתוּב (בראשית ב) וְנָהָר יֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן. הַנָּהָר הַזֶּה הִתְפַּשֵּׁט לִצְדָדָיו, בְּשָׁעָה שֶׁמִּזְדַּוֵּג עִמּוֹ בְּזִוּוּג שָׁלֵם, כַּאֲשֶׁר הָעֵדֶן הַזֶּה (זווגו) בְּאוֹתוֹ נָתִיב שֶׁלֹּא נוֹדָע לְמַעְלָה וּלְמַטָּה, כְּמוֹ שֶׁנֶּאֱמַר (שמות טז) נָתִיב לֹא יְדָעוֹ עָיִט. וְנִמְצְאוּ בְרָצוֹן שֶׁלֹּא נִפְרָדִים תָּמִיד אֶחָד מֵאֶחָד. אָז יוֹצְאִים מַעְיָנוֹת וּנְחָלִים וּמְעַטְּרִים אֶת הַבֵּן הַקָּדוֹשׁ בְּכָל אוֹתָם הַכְּתָרִים, וְאָז כָּתוּב (שיר ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. וּבְאוֹתָהּ שָׁעָה יָרַשׁ אוֹתוֹ בֵּן יְרֻשַּׁת אָבִיו וְאִמּוֹ, וְאָז הוּא הִשְׁתַּעֲשַׁע בְּאוֹתוֹ עֹנֶג וְתַפְנוּק."]]],[["וְתָאנָא, בְּשַׁעֲתָא דְּמַלְכָּא עִלָּאָה בְּתַפְנוּקֵי מַלְכִין, יָתִיב בְּעִטְרוֹי, כְּדֵין כְּתִיב עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. דָּא יְסוֹד דְּאַפִּיק בִּרְכָאן לְאִזְדַּוְּוגָא מַלְכָּא קַדִּישָׁא בְּמַטְרוֹנִיתָא. (בהא דרגא) וּכְדֵין אִתְיַיהֲבוּן בִּרְכָאן בְּכֻלְּהוּ עָלְמִין, (ונפקין) וּמִתְבָּרְכָן עִלָּאִין וְתַתָּאִין. וְהַשְׁתָּא הָא בּוּצִינָא קַדִּישָׁא מִתְעַטָּר בְּעִטְרוֹי דְּהַאי דַּרְגָּא, וְהוּא וְחַבְרַיָּיא סְלִיקוּ תּוּשְׁבְּחָן מִתַּתָּא לְעֵילָּא, וְהִיא מִתְעַטְּרָא בְּאִינּוּן תּוּשְׁבְּחָן. הַשְׁתָּא אִית לְאַפָּקָא בִּרְכָאן לְכֻלְּהוּ חַבְרַיָּיא מֵעֵילָּא לְתַתָּא, בְּהַאי דַּרְגָּא קַדִּישָׁא, וְרִבִּי אֶלְעָזָר (ס\"א דרבי אלעזר) בְּרֵיהּ לֵימָא מֵאִינּוּן מִלִּין מְעַלְּיָין דְּאוֹלִיף מֵאֲבוֹי.","פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (בראשית כ״ט:ב׳) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ'. וְנֶאֱסָפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ'. הָנֵי קְרָאֵי אִית לְאִסְתַּכְּלָא בְּהוּ, וּבְרָזָא דְּחָכְמְתָא אִינּוּן, דְּאוֹלִיפְנָא מֵאַבָּא, וְהָכִי אוֹלִיפְנָא, וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, מַאן בְּאֵר. דָּא הוּא דִּכְתִּיב, (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. וְהִנֵה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רוֹבְצִים עָלֶיהָ, אִלֵּין אִינּוּן נֶצַח הוֹד יְסוֹד, דְּאִלֵּין אִינּוּן רְבִיעִין עָלָהּ, וְקַיְימִין עָלָהּ, וּמֵאִלֵּין אִתְמַלְּיָא בִּרְכָאן הַהִיא בְּאֵר.","כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, דְּהָא מִן הַאי בְּאֵר אִתְּזָנוּ עִלָּאִין וְתַתָּאִין (נ\"א עלמין תתאין), וּמִתְבָּרְכָאן כֻּלְּהוּ כַּחֲדָא. וְהָאֶבֶן גְּדוֹלָה עַל פִּי הַבְּאֵר, דָּא הוּא דִּינָא קַשְׁיָא, דְּקַיְּימָא עָלָהּ מִסִּטְרָא אָחֳרָא לְיָנְקָא לָהּ (נ\"א מינה). וְנֶאֱסָפוּ שָׁמָּה כָל הָעֲדָרִים, אִלֵּין אִינּוּן שִׁית כִּתְרֵי מַלְכָּא, דְּמִתְכַּנְשֵׁי כֻּלְּהוּ, וְנַגְדֵּי בִּרְכָאן מֵרֵישָׁא דְּמַלְכָּא, וּמְרִיקָן בָּהּ. וְכַד אִתְחַבְּרָאן כֻּלְּהוּ כַּחֲדָא לְאַרְקָא בָּהּ, כְּתִיב וְגָלְלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר, מְנַדְּדִין (ס\"א מגנדרין) לְהַהוּא דִּינָא קַשְׁיָא, וּמְעַבְּרָן לֵיהּ מִינָּהּ.","וְהִשְׁקוּ אֶת הַצֹּאן, מְרִיקִין בִּרְכָאן מֵהַהִיא בְּאֵר, לְעִלָּאִין וְתַתָּאִין לְבָתַר וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקוֹמָהּ. תָּב הַהוּא דִּינָא לְאַתְרֵיהּ, בְּגִין דְּאִצְטְרִיךְ לֵיהּ לְבָשְׁמָא עָלְמָא, וּלְתַקְּנָא עָלְמָא. וְהַשְׁתָּא הָא קוּדְשָׁא בְּרִיךְ הוּא אָרִיק עָלַיְיכוּ בִּרְכָאן, מִמַּבּוּעָא דְּנַחֲלָא, וּמִנַּיְיכוּ כָּל בְּנֵי דָּרָא מִתְבָּרְכִין. זַכָּאָה חוּלָקֵיכוֹן בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי עָלַיְיכוּ כְּתִיב, (ישעיהו נ״ד:י״ג) וְכָל בָּנַיִךְ לִמּוּדֵי יְיָ' וְרַב שָׁלוֹם בָּנַיִךְ.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהילים קמ״ט:ה׳) יַעְלְזוּ חֲסִידִים בְכָבוֹד יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם וְגוֹ', תָּאנָא בי\"ג מְכִילָן, אִתְקְשַׁר קִשְׁרָא דִּמְהֵימְנוּתָא, לְאִשְׁתַּכְּחָא בִּרְכָאן לְכֹלָּא. וְכָל מְהֵימְנוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא בִּתְלָתָא אַסְתִּימוּ. וְעַל הַאי, בי\"ג מְכִילָן, אוֹרַיְיתָא מִתְעַטְּרָא, כְּמָה דְּאוֹקִימְנָא מִקַל וָחוֹמֶר וּמִגְּזֵרָה שָׁוָה וְכוּ', וְכַמָּה זִמְנִין אוֹקִימְנָא הַאי. וּשְׁמָא קַדִּישָׁא בְּהַאי מִתְעַטְּרָא.","תָּא חֲזֵי, בְּהַהִיא שַׁעֲתָא דְּבָעָא יַעֲקֹב, דְּיִתְבָּרְכוּן בְּנוֹי בִּשְׁמָא (ס\"א בקשרא) דִּמְהֵימְנוּתָא. מַה כְּתִיב, (בראשית מ״ט:כ״ח) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר וְזֹאת, הָא תְּלֵיסַר, דְּאִשְׁתַּתֵּף עִמְּהוֹן שְׁכִינְתָּא, וְאִתְקְיָימוּ בִּרְכָאן. וְהַיְינוּ דִּכְתִּיב, אִישׁ אֲשֶׁר כְּבִרְכָתוֹ בֵּרַךְ אוֹתָם. מַאי כְּבִרְכָתוֹ. בְּהַהוּא דּוּגְמָא דִּלְעֵילָּא, כְּבִרְכָתוֹ דְּכָל מְכִילָא וּמְכִילָא.","וְתָאנָא, כָּל אִינּוּן מְכִילִין סַלְּקִין, וּמִתְעַטְּרִין וְנַיְיחִין בְּרֵישָׁא חֲדָא, וְתַמָּן מִתְעַטְּרָא רֵישָׁא דְּמַלְכָּא, הַהוּא דְּאִקְרֵי בְּדַרְגָּא עִלָּאָה דַחֲסִידוּת. וַחֲסִידִים, יַרְתִין כָל הַהוּא כָבוֹד דִּלְעֵילָּא, דִּכְתִּיב יַעְלְזוּ חֲסִידִים בְכָבוֹד, בְּהַאי עָלְמָא. יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם בְּעָלְמָא דְּאָתֵי. רוֹמְמוֹת אֵל בִּגְרוֹנָם, דְּיַדְעִין לְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא כְּדְקָא יֵאוֹת, וּכְדֵין חֶרֶב פִּיפִיּוֹת בְּיָדָם. מַאן חֶרֶב פִּיפִיּוֹת. דָּא הוּא חֶרֶב לָה', חַרְבָּא דְּקוּדְשָׁא בְּרִיךְ הוּא. פִּיפִיּוֹת: לְהִיטָא בִּתְרֵין דִּינִין. וְלָמָּה. לַעֲשׂוֹת נְקָמָה בַּגּוֹיִם וְגוֹ'.","וְהָא רִבִּי פִּנְחָס בֶּן יָאִיר, כִּתְרָא דְּחֶסֶד, רֵישָׁא עִלָּאָה. בְּגִין כָּךְ כָּבוֹד דִּלְעֵילָּא יָרִית, וְהוּא קָשִׁיר קִשְׁרָא עִלָּאָה, קִשְׁרָא קַדִּישָׁא, קִשְׁרָא דִּמְהֵימְנוּתָא. זַכָּאָה חוּלָקֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. עַל הַאי פָּתוֹרָא אִתְּמַר, (יחזקאל מ״א:כ״ב) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי יְיָ'. קָם רִבִּי פִּנְחָס, וְנָשִׁיק לֵיהּ, וּבָרִיךְ לֵיהּ, וְנָשִׁיק לְרִבִּי אֶלְעָזָר, וּלְכֻלְּהוּ חַבְרַיָּיא, וּבָרִיךְ לוֹן, נָטַל כַּסָּא וּבָרִיךְ."],[[0,"ותאנא בשעתא דמלכא וכו׳:","ולמדנו, בשעה שהמלך העליון שהוא ז״א, יושב במעדני מלכים, ויושב בעטרותיו, אז כתוב, \u0003עד שהמלך כמסבו נרדי נתן ריחו,\u0004 נרדי, זהו יסוד המוציא ברכות להזדווג המלך הקדוש, ז\"א, במלכה, שהיא המלכות, ואז ניתנו ברכות בכל העולמות ומתברכים עליונים ותחתונים. ועתה הרי המאור הקדוש מתעטר בעטרותיו של מדרגה ההיא, דהיינו בהמוחין דז״א מאו״א, הנקראים עטרות; והוא והחברים מעלים תשבחות ממטה למעלה דהיינו מ״ן, והיא, המלכות, מתעטרת באלו התשבחות, שמזדווגת עם ז״א, יש עתה להוציא ברכות ממעלה למטה לכל החברים ממדרגה ההיא, הנ״ל. ור׳ אלעזר בנו יאמר, מאלו דברים המשובחים ששמע מאביו."],[1,"פתח ר׳ אלעזר וכו׳:","פר״א ואמר, וירא והנה באר בשדה וגו' ונאספו שמה כל העדרים וגו'. מקראות אלו יש להסתכל בהם, שבסוד החכמה הם, שלמדתי מאבי, וכך למדתי. \u0003וירא והנה באר בשדה.\u0004 מי הוא באר. זהו שכתוב, באר חפרוה שרים כרוה נדיבי העם. דהיינו המלכות שנתקנה מאו״א הנקראים שרים. \u0003והנה שם שלשה עדרי צאן רובצים עליה.\u0004 אלו הם נצח הוד יסוד. שאלו רובצים עליה ועומדים עליה ומאלו באר ההיא נתמלאה ברכות."],[2,"כי מן הבאר וגו':","כי מן הבאר ההיא ישקו העדרים, כי מן באר הזו, נזונים עליונים ותחתונים ומתברכים כולם יחד. \u0003והאבן גדולה על פי הבאר,\u0004 זה הוא דין קשה, שנקרא אבן גדולה, שעומד עליה מהצד האחר לינק ממנה. \u0003ונאספו שמה כל העדרים.\u0004 אלו הם שש ספירות של המלך, ז״א, שהם חג״ת נה״י, שמתאספים כולן, וממשיכים ברכות מראש המלך, דהיינו מג\"ר דז״א המכונות ראש, ומריקים בה. וכשמתחברים כולם כאחד והריק בה, כתוב, \u0003וגללו את האבן מעל פי הבאר,\u0004 שגוללים אותו דין הקשה, המכונה אבן, ומעבירים אותו ממנה."],[3,"והשקו את הצאן:","היינו שמריקים ברכות מהבאר ההיא לעליונים ולתחתונים. לאח״כ, והשיבו את האבן על פי הבאר למקומה. היינו שאותו הדין חוזר למקומו. משום שצריכים אליו לבשם העולם ולתקן העולם. כי הדין הזה שומר את הבאר שלא תגלה החכמה שבה רק בעת קבוץ כל העדרים, שה״ס ג׳ קוין נה״י, שאז ה״ס הנסיעה, ולאח״כ הוא מעלים החכמה (כמ״ש זה לעיל בשלח ל״ט ד״ה וז״ש כד ע״ש) ועתה הרי הקב״ה מריק עליכם ברכות ממבוע הנחל, ומכם מתברכים כל בני הדור. אשרי חלקכם בעולם הזה ובעולם הבא. עליכם כתוב, וכל בניך למודי ה׳ ורב שלום בניך."],[4,"פתח ר״ש ואמר וכו׳:","פר״ש ואמר, יעלזו חסידים בכבוד ירננו על משכבותם וגו'. למדנו בי״ג מדות הרחמים, מתקשר קשר האמונה שהיא המלכות, שתמצאנה ברכות לכל. וכל האמונה של הקב״ה נסתמה בשלשה, דהיינו ג' קוין, שה״ס י״ג. כי הם מאירים בכל אחת מד׳ ספירות חו״ג תו״מ שבה, וג״פ ד׳ הם י\"ב, ועם כללות המלכות הם י״ג. וע״כ, בי״ג מדות, מתעטרת התורה, כמו שהעמדנו בברייתא דר׳ ישמעאל, מקל וחומר ומגזירה שוה וכו'. וכבר העמדנו זה כמה פעמים. והשם הקדוש, שהוא המלכות, מתעטר בזה."],[5,"ת״ח בההיא שעתא וכו׳:","בוא וראה בשעה ההיא שרצה יעקב שיתברכו בניו בשם האמונה, מה כתוב, כל אלה שבטי ישראל שנים עשר ו \u0003זאת,\u0004 אשר דבר להם אביהם, שנים עשר, וזאת, הם י״ג. כי נשתתפה עמהם השכינה הנקראת \u0003זאת,\u0004 ונתקיימו הברכות. והיינו שכתוב, איש אשר כברכתו ברך אותם. מהו כברכתו. היינו כדמיון של מעלה, שהם י״ג מדות הרחמים, והיינו כברכתו של כל מדה ומדה."],[6,"ותאנא כל אינון וכו׳:","ולמדנו, כל אלו המדות של המלכות עולות ומתעטרות ונחות בראש אחד, דז״א, ושם מתעטר הראש של המלך, אותו שנקרא במדרגה עליונה של חסידות, דהיינו ז״א, שהחסד שלו נעשה לחכמה, וחסידים הדבוקים בז״א, יורשים את כל הכבוד ההוא של מעלה, שהוא מלכות עם י״ג מדותיה, שכתוב, \u0003יעלזו חסידים בכבוד,\u0004 היינו בעולם הזה, שהוא מלכות. ירננו על \u0003משכבותם,\u0004 היינו בעולם הבא, שהוא בינה. \u0003רוממות אל בגרונם,\u0004 היינו שיודעים לקשר קשר האמונה כראוי. כי המלכות נקראת אל. ואז \u0003חרב פיפיות בידם.\u0004 מהו חרב פיפיות. זו היא חרב לה׳, שהיא מלכות מצד הדין, שנקראת חרב. \u0003פיפיות,\u0004 היינו שלוהטת בב׳ דינים, דהיינו בדינין דשמאל, ובדינין דמסך. ולמה. הוא, לעשות נקמה בגוים וגו'."],[7,"והא ר' פנחס וכו׳:","והרי ר׳ פנחס בן יאיר, שהוא ספירת החסד ראש העליון, דז״א, דהיינו שהחסד שלו נעשה לחכמה שהיא ראש. משום זה יורש כבוד עליון, והוא קושר קשר העליון, קשר הקדוש, קשר של האמונה. דהיינו היחוד של ז״א ומלכות. אשרי חלקו בעולם הזה ובעולם הבא. על השלחן הזה נאמר, זה השלחן אשר לפני ה׳. קם ר׳ פנחס ונשקו, וברכו. ונשק לר׳ אלעזר ולכל החברים וברך אותם. לקח את הכוס וברך."]],[[0,"","וְלָמַדְנוּ, בְּשָׁעָה שֶׁהַמֶּלֶךְ הָעֶלְיוֹן בְּתַפְנוּקֵי מְלָכִים יוֹשֵׁב בְּעַטְרוֹתָיו, אֲזַי כָּתוּב, עַד שֶׁהַמֶּלֶךְ בִּמְסִבּוֹ נִרְדִּי נָתַן רֵיחוֹ. זֶה הַיְסוֹד שֶׁמּוֹצִיא בְרָכוֹת לְזַוֵּג אֶת הַמֶּלֶךְ הַקָּדוֹשׁ עִם הַגְּבִירָה (בדרגה הזו). וְאָז נִתָּנוֹת בְּרָכוֹת בְּכָל הָעוֹלָמוֹת, (ויוצאים) וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְעַכְשָׁו הֲרֵי הַמָּאוֹר הַקָּדוֹשׁ מִתְעַטֵּר בְּעַטְרוֹת הַדַּרְגָּה הַזּוֹ, הוּא וְהַחֲבֵרִים מַעֲלִים תִּשְׁבָּחוֹת מִמַּטָּה לְמַעְלָה, וְהִיא מִתְעַטֶּרֶת בְּאוֹתָן הַתִּשְׁבָּחוֹת. עַכְשָׁו יֵשׁ לְהוֹצִיא בְרָכוֹת לְכָל הַחֲבֵרִים מִמַּעְלָה לְמַטָּה בַּדַּרְגָּה הַקְּדוֹשָׁה הַזּוֹ, וְרַבִּי אֶלְעָזָר (שרבי אלעזר) בְּנוֹ יֹאמַר מֵאוֹתָם הַדְּבָרִים הַמְעֻלִּים שֶׁלָּמַד מֵאָבִיו."],[1,"","פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (בראשית כט) וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְגוֹ', וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגוֹ'. יֵשׁ לְהִסְתַּכֵּל בַּפְּסוּקִים הַלָּלוּ, וְהֵם בְּסוֹד הַחָכְמָה שֶׁלָּמַדְתִּי מֵאַבָּא, וְכָךְ לָמַדְתִּי: וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה, אֵיזוֹ בְּאֵר? זֶהוּ שֶׁכָּתוּב (במדבר כא) בְּאֵר חֲפָרוּהָ שָׂרִים כָּרוּהָ נְדִיבֵי הָעָם. וְהִנֵּה שָׁם שְׁלֹשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ, אֵלּוּ הֵם נֵצַח סוֹד יְסוֹד, שֶׁאֵלּוּ הֵם הָרוֹבְצִים עָלֶיהָ וְעוֹמְדִים עָלֶיהָ. וּמֵאֵלֶּה מִתְמַלֵּאת הַבְּאֵר הַזּוֹ בִּבְרָכוֹת."],[2,"","כִּי מִן הַבְּאֵר הַהִיא יַשְׁקוּ הָעֲדָרִים, שֶׁהֲרֵי מֵהַבְּאֵר הַזּוֹ נִזּוֹנִים עֶלְיוֹנִים וְתַחְתּוֹנִים (עולמות תחתונים), וְכֻלָּם מִתְבָּרְכִים כְּאֶחָד. וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר, זֶהוּ הַדִּין הַקָּשֶׁה שֶׁעוֹמֵד עָלֶיהָ מֵהַצַּד הָאַחֵר לְהָנִיק לָהּ (ממנה). וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים, אֵלּוּ הֵם שֵׁשֶׁת כִּתְרֵי הַמֶּלֶךְ שֶׁכֻּלָּם מִתְכַּנְּסִים וּמַשְׁפִּיעִים בְּרָכוֹת מֵרֹאשׁ הַמֶּלֶךְ וּמְרִיקִים לְתוֹכָהּ. וּכְשֶׁכֻּלָּם מִתְחַבְּרִים כְּאֶחָד לְהָרִיק בָּהּ, אָז כָּתוּב וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר, מְנַדְּדִין (גוללים) אֶת אוֹתוֹ הַדִּין הַקָּשֶׁה וּמַעֲבִירִים אוֹתוֹ מִמֶּנָּה."],[3,"","וְהִשְׁקוּ אֶת הַצּאן, מְרִיקִים בְּרָכוֹת מֵאוֹתָהּ בְּאֵר לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים. אַחַר כָּךְ - וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקֹמָהּ. וְשָׁב אוֹתוֹ הַדִּין לִמְקוֹמוֹ, מִשּׁוּם שֶׁצָּרִיךְ לוֹ לְבַשֵּׂם אֶת הָעוֹלָם וּלְתַקֵּן הָעוֹלָם. וְעַכְשָׁו הֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵרִיק עֲלֵיכֶם בְּרָכוֹת מִמַּעְיַן הַנַּחַל, וּמִכֶּם מִתְבָּרְכִים כָּל בְּנֵי הַדּוֹר. אַשְׁרֵי חֶלְקְכֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, עֲלֵיכֶם כָּתוּב (ישעיה נד) וְכָל בָּנַיִךְ לִמּוּדֵי ה' וְרַב שְׁלוֹם בָּנָיִךְ."],[4,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים קמט) יַעְלְזוּ חֲסִידִים בְּכָבוֹד יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם וְגוֹ'. לָמַדְנוּ, בְּי\"ג מִדּוֹת נִקְשָׁר קֶשֶׁר הָאֱמוּנָה, שֶׁיִּמָּצְאוּ בְרָכוֹת לַכֹּל. וְכָל אֱמוּנָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִסְתְּרוּ בְּשָׁלֹשׁ. וְעַל זֶה בִּשְׁלֹשׁ עֶשְׂרֵה מִדּוֹת מִתְעַטֶּרֶת הַתּוֹרָה, כְּמוֹ שֶׁבֵּאַרְנוּ מִקַּל וָחֹמֶר וּמִגְּזֵרָה שָׁוָה וְכוּ', וְכַמָּה פְעָמִים בֵּאַרְנוּ אֶת זֶה, וְהַשֵּׁם הַקָּדוֹשׁ מִתְעַטֵּר בָּזֶה."],[5,"","בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁרָצָה יַעֲקֹב שֶׁיִּתְבָּרְכוּ בָנָיו בְּשֵׁם (בקשר) הָאֱמוּנָה, מַה כָּתוּב? (בראשית מט) כָּל אֵלֶּה שִׁבְטֵי יִשְׂרָאֵל שְׁנֵים עָשָׂר וְזֹּאת - הֲרֵי שְׁלֹשָׁה עָשָׂר, שֶׁהִשְׁתַּתְּפָה עִמָּהֶם שְׁכִינָה וְהִתְקַיְּמוּ הַבְּרָכוֹת. וְהַיְנוּ שֶׁכָּתוּב אִישׁ אֲשֶׁר כְּבִרְכָתוֹ בֵּרַךְ אֹתָם. מַה זֶּה כְּבִרְכָתוֹ? בְּאוֹתָהּ דֻּגְמָא שֶׁל מַעְלָה, כְּבִרְכָתָהּ שֶׁל כָּל מִדָּה וּמִדָּה."],[6,"","וְלָמַדְנוּ, כָּל אוֹתָן מִדּוֹת עוֹלוֹת וּמִתְעַטְּרוֹת וְנָחוֹת בְּרֹאשׁ אֶחָד, וְשָׁם מִתְעַטֵּר רֹאשׁ הַמֶּלֶךְ, אוֹתוֹ שֶׁנִּקְרָא בְּדַרְגָּה עֶלְיוֹנָה שֶׁל חֲסִידוּת, וְהַחֲסִידִים יוֹרְשִׁים כָּל אוֹתוֹ הַכָּבוֹד שֶׁלְּמַעְלָה, שֶׁכָּתוּב יַעְלְזוּ חֲסִידִים בְּכָבוֹד - בָּעוֹלָם הַזֶּה, יְרַנְּנוּ עַל מִשְׁכְּבוֹתָם - בָּעוֹלָם הַבָּא. רוֹמְמוֹת אֵל בִּגְרוֹנָם - שֶׁיּוֹדְעִים לִקְשֹׁר אֶת קֶשֶׁר הָאֱמוּנָה כָּרָאוּי, וְאָז חֶרֶב פִּיפִיּוֹת בְּיָדָם. אֵיזוֹ חֶרֶב פִּיפִיּוֹת? זוֹהִי חֶרֶב לַה', חַרְבּוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. פִּיפִיּוֹת - לוֹהֶטֶת בִּשְׁנֵי דִינִים. וְלָמָּה? לַעֲשׂוֹת נְקָמָה בַּגּוֹיִם וְגוֹ'."],[7,"","וַהֲרֵי רַבִּי פִּנְחָס בֶּן יָאִיר, כֶּתֶר הַחֶסֶד, הָרֹאשׁ הָעֶלְיוֹן, מִשּׁוּם כָּךְ יָרַשׁ אֶת הַכָּבוֹד שֶׁלְּמַעְלָה, וְהוּא קָשַׁר קֶשֶׁר עֶלְיוֹן, קֶשֶׁר קָדוֹשׁ, קֶשֶׁר הָאֱמוּנָה. אַשְׁרֵי חֶלְקוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עַל הַשֻּׁלְחָן הַזֶּה נֶאֱמַר, (יחזקאל מא) זֶה הַשֻּׁלְחָן אֲשֶׁר לִפְנֵי ה'. קָם רַבִּי פִּנְחָס וְנָשַׁק לוֹ וּבֵרַךְ אוֹתוֹ, וְנָשַׁק לְרַבִּי אֶלְעָזָר וּלְכָל הַחֲבֵרִים וּבֵרַךְ אוֹתָם. נָטַל כּוֹס וּבֵרַךְ."]]],[["פָּתַח וְאָמַר, (תהילים כ״ג:ה׳) תַּעֲרוֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צוֹרְרָי וְגוֹ', יָתְבוּ (ס\"א חדו) תַּמָּן, כָּל הַהוּא יוֹמָא, וַהֲווּ חַבְרַיָּא כֻּלְּהוּ חַדָּן בְּמִלֵּי דְּאוֹרַיְיתָא, וְחֶדְוָותָא דְּרַבִּי שִׁמְעוֹן הֲוָה סַגֵּי. נָטַל רִבִּי פִּנְחָס לְרִבִּי אֶלְעָזָר, וְלָא שַׁבְקֵיהּ כָּל הַהוּא יוֹמָא וְכָל לֵילְיָא, וַהֲוָה חַדֵּי עִמֵּיהּ, קָרָא עָלֵיהּ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', כָּל חֶדְוָותָא וְעִנּוּגָא יַתִּירָא דָּא דְּחוּלָקִי הוּא, (על דא דעמי הוא על דא כתיב (תהילים קמ״ד:ט״ו) אשרי העם שככה לו וגו') זְמִינִין בְּהַהוּא עָלְמָא לְאַכְרְזָא עָלַי, זַכָּאָה חוּלָקָךְ רִבִּי פִּנְחָס, דְּאַנְתְּ זָכִית לְכָל הַאי, (דברי הימים א י״ב:י״ט) שָׁלוֹם לְךָ וְשָׁלוֹם לְעוֹזְרֶךָ כִּי עֲזָרְךָ אֱלֹהֶיךָ. אַשְׁכִּימוּ לְמֵיזַל, קָם רִבִּי פִּנְחָס וְאָחִיד בֵּיהּ בְּרִבִּי אֶלְעָזָר, וְלָא שַׁבְקֵיהּ לְמֵיהַךְ. אוֹזִיף רִבִּי פִּנְחָס לְרַבִּי שִׁמְעוֹן וּבַרְכֵיהּ, וּלְכֻלְּהוּ חַבְרַיָּיא. עַד דַּהֲווּ אַזְלֵי אָמַר לְהוּ רִבִּי שִׁמְעוֹן לְחַבְרַיָּיא, (תהילים קי״ט:קכ״ו) עֵת לַעֲשׂוֹת לַיְיָ'.","אָתָא רִבִּי אַבָּא וְשָׁאִיל, כְּתִיב וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת וְגוֹ'. הָנֵי עַדְבִין לָמָּה. וְאַהֲרֹן לָמָּה לֵיהּ לְמֵיהַב עַדְבִין. וּפַרְשְׁתָּא דָּא לָמָּה. וְהָא אוֹלִיפְנָא קַמֵּי דְּמַר סִדְרָא דְּיוֹמָא, וְהַאי בְּעֵינָא לְמִנְדַּע.","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית מ״ב:כ״ד) וַיִקַּח מֵאִתָּם אֶת שִׁמְעוֹן וַיֶּאֱסוֹר אוֹתוֹ לְעֵינֵיהֶם. וְכִי מַה חָמָא יוֹסֵף לְמֵיסַב לְשִׁמְעוֹן עִמֵּיהּ יַתִּיר מֵאֲחוֹהִי. אֶלָּא, אָמַר יוֹסֵף, בְכָל אֲתַר שִׁמְעוֹן (ולוי) פְּתִיחוּתָא דְּדִינָא אִיהוּ (אינון), וְהַהִיא שַׁעֲתָא דַּאֲזִילְנָא מֵאַבָּא לְגַבַּיְיהוּ דְּאֶחָי, שִׁמְעוֹן פָּתַח בְּקַדְמִיתָא בְּדִינָא, הֲדָא הוּא דִכְתִיב, (בראשית ל״ז:י״ט-כ׳) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלוֹמוֹת הַלָּזֶה בָּא וְעַתָּה לְכוּ וְגוֹ'. לְבָתַר בִשְׁכֶם, (בראשית ל״ד:כ״ה) וַיִּקְחוּ שְׁנֵי בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי, כֻּלְּהוּ בְּדִינָא הֲווֹ. טַב לְמֵיסַב דָּא, וְלָא יִתְּעַר קְטָטוּתָא בְּכֻלְּהוּ שְׁבָטִין.","וְתָנֵינָן, מַאי קָא חָמָא שִׁמְעוֹן לְאִזְדַּוְּוגָא בְּלֵוִי יַתִּיר מִכֹּלָּא. וְהָא רְאוּבֵן הֲוָה אָחוּהָּ וְסָמִיךְ לֵיהּ, אֶלָּא שִׁמְעוֹן חָמָא וְיָדַע דְּלֵוִי מִסִּטְרָא דְּדִינָא קָא אָתֵי, וְשִׁמְעוֹן מִסִּטְרָא דְּדִינָא קַשְׁיָא יַתִּיר אִתְאֲחָד. אָמַר נִתְעֲרָב חַד בְּחַד וַאֲנָן נֶחֱרִיב עָלְמָא. מָה עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, נָטַל לֵיהּ לְחוּלָקֵיהּ לְלֵוִי, אָמַר מִכָּאן וּלְהָלְאָה שִׁמְעוֹן לֵיתִיב בְּקוּפְטִירָא בַּהֲדֵּיהּ בִּלְחוֹדוֹי.","תָּאנָא בְּסִטְרָא דְּאִימָא, תְּרֵין גַּרְדִּינֵי טְהִירִין (ס\"א תריסין) אִתְאַחֲדָן בִּידָא שְׂמָאלָא, וְהָא אוֹקִימְנָא דְּאִינּוּן מְאַלְלֵי אַרְעָא בְכָל יוֹמָא וְיוֹמָא, וְהַיְינוּ רָזָא דִּכְתִּיב, (יהושע ב׳:א׳) שְׁנַיִם אֲנָשִׁים מְרַגְּלִים.","וְתָאנָא, זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל יַתִּיר מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכְּאָה לְהוּ, וּלְרַחֲמָא עָלַיְיהוּ, דְּאִינּוּן חוּלָקֵיהּ וְעַדְבֵיהּ, הֲדָא הוּא דִכְתִיב (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ וְגוֹ', וּכְתִיב (דברים לב) יַרְכִּיבֵהוּ עַל בָּמֳתֵי אָרֶץ. עַל בָּמֳתֵי אָרֶץ דַּיְיקָא. דְּהָא אִינּוּן אִתְאַחֲדָן לְעֵילָּא לְעֵילָּא. וְעַל דָּא קוּדְשָׁא בְּרִיךְ הוּא רְחִימוּתָא דִּילֵיהּ אִתְדְּבָק בְּהוּ, הֲדָא הוּא דִכְתִיב, (מלאכי א׳:ב׳) אָהַבְתִּי אֶתְכֶם אָמַר יְיָ', וּכְתִיב (דברים ז׳:ח׳) כִּי מֵאַהֲבַת יְיָ' אֶתְכֶם וְגוֹ', וּמִגּוֹ רְחִימוּתָא יַתִּירָא דְּרָחִים לְהוּ, יָהַב לוֹן יוֹמָא חַד בְּשַׁתָּא לְדַכְאָה לְהוּ, וּלְזַכָּאָה לְהוּ מִכָּל חוֹבֵיהוֹן, דִּכְתִּיב, (ויקרא טז) כִּי בַיּוֹם הַזֶּה וְגוֹ'. בְּגִין דִּיהוֹן זַכָּאִין בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, וְלָא יִשְׁתְּכַּח בְּהוּ חוֹבָא. וְעַל דָּא בְּיוֹמָא דָּא, מִתְעַטְּרִין יִשְׂרָאֵל, וְשַׁלְטִין עַל כֻּלְּהוּ גַּרְדִּינִין, וְעַל כֻּלְּהוּ טְהִירִין.","תָּאנָא (ויקרא ט״ז:ח׳) וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גּוֹרָלוֹת. וְנָתַן אַהֲרֹן, בְּגִין דְּאָתֵי מִסִּטְרָא דְּחֶסֶד. עַל שְׁנֵי הַשְּׂעִירִים, עַל דַּיְיקָא, בְּגִין דְּתִתְבֲּסַם מַטְרוֹנִיתָא. גּוֹרָל אֶחָד לַיְיָ' וְגוֹרָל אֶחָד לַעֲזָאזֵל וְהָא תְּרֵין שְׂעִירִין אִינּוּן, אֲמַאי חַד לַיְיָ'. אֶלָּא אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יֵתִיב הַאי גַּבָּאי, וְחַד יֵזִיל וְיִשׁוֹט בְּעָלְמָא, דְּאִלְמָלֵי תַּרְוַיְיהוּ מִזְדַּוְּוגָן, לָא יָכִיל עָלְמָא לְמִסְבַּל.","נָפַק הַאי, אָזִיל וְשָׁאט בְּעָלְמָא, וְאַשְׁכַּח לְהוּ לְיִשְׂרָאֵל, בְּכַמָּה פּוּלְחָנִין, בְּכַמָּה דַּרְגִּין, בְּכַמָּה נִמוּסִין טָבָן, לָא יָכִיל לְהוּ, כֻּלְּהוּ שְׁלָמָא בֵּינַיְיהוּ, לָא יָכִיל לְמֵיעָל בְּהוּ בְּדַלְטוֹרָא. (אזל ושאט בעלמא, ואשכח לישראל כהאי גוונא) (נ\"א ישראל לתתא אוף הכי כהאי גוונא) הַאי שְׂעִירָא שַׁלְחִין לֵיהּ בְּמַטוּלָא דְּכָל חוֹבַיְיהוּ דְּיִשְׂרָאֵל."],[[0,"פתח ואמר תערוך","וגו': פתח ואמר, תערוך לפני שלחן נגד צוררי וגו'. ישבו שם כל אותו היום. והיו החברים כולם שמחים בדברי תורה, ושמחת ר\"ש היתה רבה. לקח ר' פנחס את ר' אלעזר ולא עזבו כל אותו היום וכל הלילה, והיה שמח עמו. קרא עליו אז תתענג על ה', כל השמחה והעונג הרב הזה הוא של חלקי, כי ר' אלעזר היה בן בתו, ועתידים בעולם ההוא להכריז עלי, אשרי חלקך רבי פנחס שאתה זכית לכל זה. שלום לך ושלום לעוזרך כי עזרך אלקיך. השכימו ללכת. קם ר' פנחס ואחז בו בר' אלעזר ולא הניחו ללכת. לוה ר' פנחס את ר\"ש וברכו, ולכל החברים. בעוד שהיו הולכים אמר להם ר\"ש לחברים, עת לעשות לה'."],[1,"אתא ר' אבא","וכו': בא ר' אבא ושאל. כתוב, ונתן אהרן על שני השעירים גורלות וגו'. גורלות אלו למה. ואהרן למה לו לתת הגורלות. ופרשה זו למה. והרי למדתי לפני אדוני סדר היום של יום הכפורים וגם זה אני רוצה לדעת."],[2,"פתח ר\"ש ואמר","וכו': פר\"ש ואמר, ויקח מאתם את שמעון ויאסור אותו לעיניהם. שואל וכי מה ראה יוסף לקחת את שמעון עמו יותר מאחיו האחרים. ומשיב, אלא אמר יוסף, בכל מקום, שמעון הוא פתיחת הדין, ואותה שעה שהלכתי מאבי לאחי, שמעון פתח תחילה בדין, ז\"ש, ויאמרו איש אל אחיו הנה בעל החלומות הלזה בא ועתה לכו וגו'. לאחר כך בשכם, ויקחו שני בני יעקב שמעון ולוי וגו'. כולם היו בדין. לכן, טוב לקחת את זה, ולא יעורר מריבה בכל השבטים."],[3,"ותנינן מה קא חמא","וכו': ולמדנו, מה ראה שמעון להתחבר בלוי יותר מבכולם, והרי ראובן היה אחיו, והיה סמוך לו כמו לוי, למה לא נתדבק בראובן. ומשיב, אלא שמעון ראה וידע שלוי בא מצד הדין, ושמעון היה נאחז מצד הדין הקשה יותר, אמר, נתערב אחד באחד, ואנו נחריב העולם. מה עשה הקב\"ה, לקח את לוי לחלקו, אמר מכאן ולהלאה, ישב שמעון אסור בחבלים לבדו. \u0003בקופטירא,\u0004 הוא מלשון כקפטורין יוצאה מתוך הושט, שפירושו חבל. (תנחומא מקץ)."],[4,"תאנא בסטרא דאמא","וכו': למדנו, מצד אמא, ב' רוחות חוקרי דין נאחזים ביד שמאל. והעמדנו, שהם מרגלי הארץ, שהיא המלכות, בכל יום ויום. כלומר שיונקים מן נה\"י דמלכות, הנקראים רגלין. וז\"ס שכתוב, שנים אנשים מרגלים. (עי' בספרא דצניעותא שבסוף תרומה, אות נ\"ד בהסולם)."],[5,"ותאנא זכאה חולקיהון","וכו': ולמדנו, אשרי חלקם של ישראל, יותר מכל העמים עכו\"ם, שהקב\"ה רצה לטהרם ולרחם עליהם, שהם חלקו ונחלתו. ז\"ש, כי חלק ה' עמו וגו' וכתוב, ירכיבהו על במתי ארץ. על במתי ארץ הוא בדיוק, שהם מתאחדים למעלה למעלה, בז\"א, וע\"כ הקב\"ה, האהבה שלו מתדבקת בהם, ז\"ש, אהבתי אתכם אמר ה'. וכתוב, כי מאהבת ה' אתכם וגו'. ומתוך אהבה יתירה שאוהב אותם, נתן להם יום אחד בשנה לטהרם ולזכות אותם מכל עונותיהם. שכתוב, כי ביום הזה וגו'. כדי שיהיו זכאים בעולם הזה ובעולם הבא, ולא ימצא בהם חטא. וע\"כ ביום הזה מתעטרים ישראל ושולטים על כל חוקרי הדין, ועל כל הרוחות."],[6,"תאנא ונתן אהרן","וגו': למדנו, ונתן אהרן על ב' השעירים גורלות. \u0003ונתן אהרן,\u0004 למה דוקא אהרן, הוא משום שבא מצד החסד, ויכול להשלים המלכות בחסדים. \u0003על שני השעירים,\u0004 הנה \u0003על\u0004 הוא בדיוק. הרומז על המלכות, שהוא ממעל שני השעירים, והיינו כדי שתתבשם המטרוניתא, שהיא המלכות. \u0003גורל אחד ל\"ה וגורל אחד לעזאזל,\u0004 שואל, והרי שני שעירים הם, הרומזים על דינין ולמה יהיה אחד מהם לה', ומשיב, אלא אמר הקב\"ה, ישב שעיר אחד אצלי, ואחד ילך וישוטט בעולם, כי אם יתחברו שניהם, לא יוכל העולם לסבול."],[7,"נפק האי אזיל","וכו': יוצא השעיר הזה הולך ומשוטט בעולם, ומוצא את ישראל בכמה עבודות, בכמה מדרגות, בכמה חוקים טובים, ואינו יכול להם. כולם, יש שלום ביניהם, ואינו יכול לכנוס בהם ברכילות. דהיינו שאינו יכול להשטין עליהם. שעיר הזה, שולחים אותו עם המשא של כל עונות ישראל."]],[[0,"","פָּתַח וְאָמַר, (תהלים כג) תַּעֲרֹךְ לְפָנַי שֻׁלְחָן נֶגֶד צֹרְרָי וְגוֹ'. יָשְׁבוּ (שמחו) שָׁם כָּל אוֹתוֹ הַיּוֹם, וְהָיוּ כָּל הַחֲבֵרִים שְׂמֵחִים בְּדִבְרֵי תוֹרָה, וְשִׂמְחָתוֹ שֶׁל רַבִּי שִׁמְעוֹן הָיְתָה רַבָּה. לָקַח רַבִּי פִּנְחָס אֶת רַבִּי אֶלְעָזָר, וְלֹא עָזַב אוֹתוֹ כָּל אוֹתוֹ הַיּוֹם וְכָל הַלַּיְלָה, וְהָיָה שָׂמֵחַ עִמּוֹ. קָרָא עָלָיו, (ישעיה נח) אָז תִּתְעַנַּג עַל ה'. כָּל הַשִּׂמְחָה וְהָעֹנֶג הַיָּתֵר הַזֶּה - שֶׁל חֶלְקִי הוּא, (על זה שעמי הוא, על זה כתוב (תהלים קמד) אשרי העם שככה לו וגו') עֲתִידִים בְּאוֹתוֹ עוֹלָם לְהַכְרִיז עָלַי: אַשְׁרֵי חֶלְקְךְ רַבִּי פִּנְחָס, שֶׁאַתָּה זָכִיתָ לְכָל זֶה, שָׁלוֹם לְךְ וְשָׁלוֹם לְעוֹזְרֶךְ כִּי עֲזָרְךְ אֱלֹהֶיךְ. הִשְׁכִּימוּ לָלֶכֶת. קָם רַבִי פִּנְחָס וְאָחַז בְּרַבִּי אֶלְעָזָר, וְלֹא הִשְׁאִיר אוֹתוֹ לָלֶכֶת. לִוָּה רַבִּי פִּנְחָס אֶת רַבִּי שִׁמְעוֹן וּבֵרְכוֹ, וְאֶת כָּל הַחֲבֵרִים. עַד שֶׁהָיוּ הוֹלְכִים, אָמַר לָהֶם רַבִּי שִׁמְעוֹן לַחֲבֵרִים, (תהלים קיט) עֵת לַעֲשׂוֹת לַה'."],[1,"","בָּא רַבִּי אַבָּא וְשָׁאַל, כָּתוּב וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גֹּרָלוֹת וְגוֹ'. הַגּוֹרָלוֹת הַלָּלוּ לָמָּה? וְאַהֲרֹן לָמָּה לוֹ לָתֵת גּוֹרָלוֹת? וְהַפָּרָשָׁה הַזּוֹ לָמָּה? וַהֲרֵי לָמַדְנוּ לִפְנֵי מוֹרֵנוּ אֶת סֵדֶר הַיּוֹם, וַהֲרֵי רוֹצִים לָדַעַת."],[2,"","פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (בראשית מב) וַיִּקַּח מֵאִתָּם אֶת שִׁמְעוֹן וַיֶּאֱסֹר אֹתוֹ לְעֵינֵיהֶם. וְכִי מָה רָאָה יוֹסֵף לָקַחַת אֶת שִׁמְעוֹן עִמּוֹ יוֹתֵר מֵאֶחָיו? אֶלָּא אָמַר יוֹסֵף בְּכָל מָקוֹם שִׁמְעוֹן (ולוי) הוּא (הם) פְּתִיחַת הַדִּין, וְאוֹתָהּ הַשָּׁעָה שֶׁהָלַכְתִּי מֵאָבִי אֶל אָחִי, שִׁמְעוֹן פָּתַח בָּרִאשׁוֹנָה בְּדִין, זֶהוּ שֶׁכָּתוּב (שם לז) וַיֹּאמְרוּ אִישׁ אֶל אָחִיו הִנֵּה בַּעַל הַחֲלֹמוֹת הַלָּזֶה בָּא וְעַתָּה לְכוּ וְגוֹ'. אַחַר כָּךְ בִּשְׁכֶם, (שם לד) וַיִּקְחוּ שְׁנֵי בְּנֵי יַעֲקֹב שִׁמְעוֹן וְלֵוִי, כֻּלָּם בְּדִין הָיוּ. טוֹב לָקַחַת אֶת זֶה, וְלֹא יָעִיר קְטָטָה עִם כָּל הַשְּׁבָטִים."],[3,"","וְשָׁנִינוּ, מָה רָאָה שִׁמְעוֹן לְהִזְדַּוֵּג עִם לֵוִי יוֹתֵר מֵהַכֹּל, וַהֲרֵי רְאוּבֵן הָיָה אָחִיו וְסָמוּךְ לוֹ? אֶלָּא שִׁמְעוֹן רָאָה וְיָדַע שֶׁלֵּוִי בָּא מִצַּד הַדִּין, וְשִׁמְעוֹן נֶאֱחָז יוֹתֵר בְּצַד הַדִּין הַקָּשֶׁה. אָמַר, נִתְעָרֵב אֵחָד עִם אֶחָד, וְאָנוּ נַחֲרִיב אֶת הָעוֹלָם. מֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא? נָטַל לְחֶלְקוֹ אֶת לֵוִי וְאָמַר: מִכָּאן וָהָלְאָה שֶׁיֵּשֵׁב שִׁמְעוֹן עִם שַׁלְשֶׁלֶת הַגְּבוּרָה עִמּוֹ לְבַדּוֹ."],[4,"","לָמַדְנוּ, בְּצַד הָאֵם שְׁנֵי שׁוֹמְרִים חוֹקְרֵי דִין (מגנים) אֲחוּזִים בְּיָד שְׂמֹאל, וַהֲרֵי בֵּאַרְנוּ שֶׁהֵם מְרַגְּלִים אֶת הָאָרֶץ בְּכָל יוֹם וָיוֹם, וְהַיְנוּ סוֹד הַכָּתוּב, (יהושע ב) שְׁנַיִם אֲנָשִׁים מְ רַגְּלִים."],[5,"","וְשָׁנִינוּ, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל יוֹתֵר מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם וּלְרַחֵם עֲלֵיהֶם, שֶׁהֵם חֶלְקוֹ וְגוֹרָלוֹ. זֶהוּ שֶׁכָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'. וְכָתוּב (שם) יַרְכִּבֵהוּ עַל בָּמֳתֵי אָרֶץ. עַל בָּמֳתֵי אָרֶץ דַּוְקָא, שֶׁהֲרֵי הֵם אֲחוּזִים לְמַעְלָה לְמַעְלָה, וְעַל כֵּן אַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא נִדְבֶּקֶת בָּהֶם. זֶהוּ שֶׁכָּתוּב (מלאכי א) אָהַבְתִּי אֶתְכֶם אָמַר ה', וְכָתוּב (דברים ז) כִּי מֵאַהֲבַת ה' אֶתְכֶם וְגוֹ'. וּמִתּוֹךְ הָאַהֲבָה הַיְתֵרָה שֶׁאוֹהֵב אוֹתָם, נָתַן לָהֶם יוֹם אֶחָד בַּשָּׁנָה לְטַהֵר אוֹתָם וּלְזַכּוֹת אוֹתָם מִכָּל חֲטָאֵיהֶם, שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה וְגוֹ', כְּדֵי שֶׁיִּהְיוּ צַדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, וְלֹא יִמָּצֵא בָהֶם חֵטְא. וְעַל כֵּן בַּיּוֹם הַזֶּה מִתְעַטְּרִים יִשְׂרָאֵל וְשׁוֹלְטִים עַל כָּל חוֹקְרֵי הַדִּין וְעַל כָּל הָרוּחוֹת."],[6,"","לָמַדְנוּ, וְנָתַן אַהֲרֹן עַל שְׁנֵי הַשְּׂעִירִים גֹּרָלוֹת. וְנָתַן אַהֲרֹן, מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד. עַל שְׁנֵי הַשְּׂעִירִים, בְּדִיּוּק עַל, כְּדֵי שֶׁתִּתְבַּשֵּׂם הַגְּבִירָה. גּוֹרָל אֶחָד לַה' וְגוֹרָל אֶחָד לַעֲזָאזֵל, וַהֲרֵי שְׁנֵי שְׂעִירִים הֵם. אָז לָמָּה אֶחָד לַה'? אֶלָּא אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יֵשֵׁב זֶה אֶצְלִי, וְאֶחָד יֵלֵךְ וִישׁוֹטֵט בָּעוֹלָם, שֶׁאִלְמָלֵא שְׁנֵיהֶם מִזְדַּוְּגִים, לֹא יָכוֹל הָעוֹלָם לִסְבֹּל."],[7,"","יָצָא זֶה, הוֹלֵךְ וּמְשׁוֹטֵט בָּעוֹלָם, וּמוֹצֵא אֶת יִשְׂרָאֵל בְּכַמָּה עֲבוֹדוֹת, בְּכַמָּה דְרָגוֹת, בְּכַמָּה הַנְהָגוֹת טוֹבוֹת, וְלֹא יָכוֹל לָהֶם, בֵּין כֻּלָּם שָׁלוֹם, וְלֹא יָכוֹל לְהִכָּנֵס עִמָּהֶם בְּמַלְשִׁינוּת. (הולך ומשוטט בעולם ומוצא את ישראל בצורה הזו) (אף ישראל למטה כך בצורה הזו) אֶת הַשָּׂעִיר הָאַחֵר שׁוֹלְחִים אוֹתוֹ עִם מַשָּׂא שֶׁל כָּל חֲטָאֵי יִשְׂרָאֵל."]]],[["תָּאנָא, כַּמָה חֲבִילֵי טְרִיקִין מִזְדַּוְּוגָן (נ\"א מזדמנן), דְּאִינּוּן תְּחוֹת יְדֵיהּ, וּמְמָנָן לְאַלְלָא אַרְעָא, עַל כָּל אִינּוּן דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא. וְהַהוּא יוֹמָא, לָא שְׁכִיחַ דַּלְטּוֹרָא (ס\"א פטרא) לְמַלְּלָא בְּהוּ בְּיִשְׂרָאֵל. כַּד מָטָא הַאי שְׂעִירָא לְגַבֵּי טוּרָא, כַּמָה חֵידוּ עַל חֵידוּ מִתְבַסְּמִין כֻּלְּהוּ בֵּיהּ. וְהַהוּא גַרְדִינָא דְּנָפִיק, אַהְדָּר וְאָמַר תּוּשְׁבַּחְתָּא דְּיִשְׂרָאֵל, קַטֵיגוֹרָא אִתְעָבִיד סַנֵיגוֹרָא.","וְתָּא חֲזֵי, לָאו דָּא בִּלְחוֹדוֹי הוּא, אֶלָּא בְּכָל אֲתַר דְּבַעְיָין יִשְׂרָאֵל לְאִתְדַכְּאָה מֵחוֹבַיְיהוּ, קוּדְשָׁא בְּרִיךְ הוּא יָהִיב לוֹן עֵיטָא לְקַשְּׁרָא מָארֵי דְּדִינָא, וּלְבַסְּמָא לְהוּ בְּאִינּוּן קָרְבְּנִין וְעִלָּוָון, דִּקְרֵבִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וּכְדֵין לָא יַכְלִין לְאַבְאָשָׁא. וְהַהוּא יוֹמָא יַתִּיר עַל כֹּלָּא, כְּמָה דְּמְבַסְּמִין יִשְׂרָאֵל לְתַתָּא לְכֹלָּא, הָכִי מְבַסְּמִין לְכָל אִינּוּן דְּאִית לְהוּ דַּלְטּוֹרָא (ס\"א פטרא) וְכֹלָּא קָרְבְּנָא הוּא וּפוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא.","תָּאנָא, בְּהַהִיא שַׁעֲתָא דִּכְתִּיב, וְלָקַח אַהֲרֹן אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ', מִתְעָרִין אִינּוּן בְּהַהוּא יוֹמָא לְעֵילָּא, וּבַעְיָין לְשַׁלְּטָאָה (נ\"א לשטאה) וּלְמֵיפָּק בְּעָלְמָא. כֵּיוָן דְּכַהֲנָא מְקָרֵב אִלֵּין לְתַתָּא, מִתְקָרְבִין אִינּוּן לְעֵילָּא. כְּדֵין עַדְבִין סַלְּקִין בְּכָל סִטְרִין, כַּהֲנָא יָהַב עַדְבִין לְתַתָּא, כַּהֲנָא יָהִיב עַדְבִין לְעֵילָּא. כְּמָה דְּחַד אִשְׁתְּאַר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא לְתַתָּא. וְחַד אַפְּקִין לֵיהּ לְהַהוּא מַדְבְּרָא, הָכִי נָמֵי לְעֵילָּא, חָד אִשְׁתְּאַר בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְחַד נָפִיק וְשָׁט בְּעָלְמָא, לְהַהוּא מַדְבְּרָא עִלָּאָה, וְחַד בְּחַד מִתְקַשָּׁר.","כְּתִיב (ויקרא ט״ז:כ״א) וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו עַל רֹאשׁ הַשָּׂעִיר הַחַי וְהִתְוַדָּה עָלָיו וְגוֹ'. בְּגִין כָּךְ וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָיו, דְּקוּדְשָׁא בְּרִיךְ הוּא יִסְתְּכַּם עַל יְדוֹי. עַל רֹאשׁ הַשָּׂעִיר הַחַי, הַחַי דַּיְיקָא, לְאַכְלְלָא הַהוּא דִּלְעֵילָּא.","(ויקרא ה) וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת, כְּמָה דִּכְתִּיב (ויקרא ה׳:ה׳) וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ. וְאוֹקִימְנָא עָלֶיהָ, דְּאִתְדָכֵּי בַּר נָשׁ וְאִשְׁתְּאַר עָלֶיהָ כָּל הַהוּא חוֹבָא. אוּף הָכִי וְהִתְוַדָּה עָלָיו, בָּתַר דְּאוֹדֵי כַּהֲנָא בְּגִינַיְיהוּ דְּיִשְׂרָאֵל, עָלָיו: כְּלוֹמַר, יִשְׁתַּאֲרוּן כֻּלְּהוּ עָלָיו.","אָמַר לֵיהּ רִבִּי אַבָּא, אִי הָכִי וְהָא כְּתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים, אָמַר לֵיהּ שָׁאנֵי הָכָא, דְּהָתָם לַשְּׂעִירִים הֲווֹ קְרֵבִין קָרְבְּנָא, וּבְגִין כָּךְ לָא כְּתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם שְׂעִירִים, אֶלָּא לַשְּׂעִירִים, דְּהָתָם לַשְּׂעִירִים הֲווֹ עַבְדֵּי פּוּלְחָנָא, וְשׁוּלְטָנוּתָא. וְהָכָא וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם, וְקָרְבְּנָא לָא אִתְעָבִיד אֶלָּא לְּקוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי, דִּבְגִינֵי קָרְבְּנָא מִתְבַּסְּמָן עִלָּאִין וְתַתָּאִין, וְדִינָא לָא שַׁרְיָא וְשַׁלְטָא עָלַיְיהוּ דְּיִשְׂרָאֵל."],[[0,"תאנא כמה חבילי","וכו': למדנו כמה גדודי מחבלים מזדמנים, שהם תחת ידו של השעיר הזה, וממונים לרגל הארץ על כל אלו העוברים על דברי תורה, וביום ההוא, יום הכפורים, אינו נמצא משטין לדבר על ישראל. כשמגיע שעיר הזה, שלעזאזל, אל ההר, כמה שמחה על שמחה מתבשמת בו לכולם, ואותו חוקר דין שיצא, דהיינו השעיר שלמעלה, חוזר ואומר שבחם של ישראל. הקטגור נעשה סנגור. כלומר, שהמשטין נעשה מליץ טוב."],[0,"","ביאור המאמר. הנה ג' שאלות שאל ר' אבא את ר\"ש (באות קי\"א) א) הני עדבין למה. ב) ואהרן למה לי למיהב עדבין, ולא איש אחר. ג) ופרשתא דא למה. כלומר למה נאמרה פרשה זו ליום הכפורים דוקא. וכדי לבאר לו את ג' שאלות אלו מביא ר' שמעון כאן ג' ענינים שהם, א) ענין שמעון ולוי. ב) ענין ב' אנשים מרגלים. ג) ענין ב' השעירים. אשר בשורשם הדינים שבהם שוים זה לזה."],[0,"","וכבר ידעת שב' מיני דינים הם שורשי כל הדינים והחטאים שבעולם, שהם דינים דדכורא הנמשכים מקו שמאל, ודינים דנוקבא הנמשכים מן המסך. וכשהדינים דנוקבא באים מבחינת התיקון, דהיינו מהקו האמצעי, אז הם סותרים לדינין דדכורא ומבטלים אותם, (כמ\"ש זה לעיל פרשת תזריע אות קנ\"ב בהסולם) עש\"ה. אמנם אם הדינים דנוקבא אינם באים מבחינת התקון, אלא מבחינת הדינים עצמם, אז לא די שאינם מבטלים את הדינים דדכורא, אלא עוד שנוספים עליהם ומחריבים את העולם."],[0,"","ושמעון ולוי, שניהם היו בבחינת דינים, שמעון, היה מבחינת דינים דדכורא הנמשכים מקו שמאל. ולוי, היתה בו בחינת דינין דנוקבא, הנמשכים ממסך. וז\"ש (באות קי\"ג) \u0003שמעון חמא וידע וכו' נתערב חד בחד ואנן נחריב עלמא,\u0004 כי הדינים דנוקבא שבלוי, כשיתוספו על הדינין דדכורא של שמעון, יחריבו העולם כנ\"ל. \u0003מה עביד קב\"ה, נטיל ליה לחולקיה ללוי,\u0004 דהיינו שהעלהו לבחינת התקון שלו, שהוא הקו האמצעי, אשר אז הוא סותר לדינין דדכורא, ומעלים ממנו הג\"ר דשמאל, כדרך קו האמצעי, וז\"ש, \u0003מכאן ולהלאה, ליתיב בקופטירא בהדיה בלחודוי,\u0004 דהיינו שיתמעטו הג\"ר דשמאל שלו וישאר בו\"ק דחכמה, שזה נחשב לו, כמו שהוא אסור בחבלים ע\"י הדינין דנוקבא שבלוי. ובזה מיושב ג\"כ (באות קי\"ב) הכתוב, \u0003ויקח את שמעון ויאסור אותו לעיניהם\u0004 ששאל, \u0003מה חמא יוסף\u0004 וכו'. כי יוסף הוא בחינת יסוד, שהוא קו האמצעי שמחזה ולמטה, וע\"כ בחינת דינין דנוקבא המתוקנים שבקו האמצעי, \u0003אסר את שמעון,\u0004 שמיעט הג\"ר דשמאל שבשמעון. שמהם כל הדינים והמריבות."],[0,"","וז\"ש (באות קי\"ד) \u0003בסטרא דאמא תרין גרדיני טהירין אתאחדן בידא שמאלא,\u0004 שהם דינים דנוקבא ודינין דדכורא הנ\"ל, ושניהם נמשכים מאמא אל המלכות, והדינים דנוקבא נתוספים ומתאחדים בדינין דדכורא שהם מיד שמאל, דאמא, \u0003והא אוקימנא דאינון מאללי ארעא בכל יומא ויומא,\u0004 שהם נאחזים בנה\"י המלכות הנקראים רגלין, והמלכות נקראת ארץ, וע\"כ נקראים מרגלי הארץ. והם מתעוררים בכל יום ויום, ותיקונם הוא ע\"י הארת קו האמצעי בכל יום ויום. וה\"ס שני אנשים מרגלים."],[0,"","וז\"ש (באות קט\"ז) \u0003אמאי חד לה', אלא אמר קב\"ה, יתיב האי גבאי.\u0004 דהיינו השעיר לחטאת, כי שני השעירים בשורשם למעלה הם ג\"כ ב' בחינות דינים הנ\"ל, אשר השעיר לחטאת, היא דינים דנוקבא, והשעיר לעזאזל, הוא דינים דדכודא. ואמר הקב\"ה, שה\"ס קו האמצעי, שהשעיר לחטאת ישב אצלי, כלומר שהדינים שלו יתתקנו בבחינת קו אמצעי, הממעט הג\"ר דקו שמאל, \u0003וחד יזיל וישוט בעלמא,\u0004 היינו השעיר לעזאזל, שהוא מדינים דדכורא, ישוטט בעולם בלבדו, דהיינו כמ\"ש לעיל בשמעון ולוי, ש \u0003נטל ליה לחולקיה ללוי\u0004 וכו', \u0003ושמעון ליתיב בקופטירא בהדיה בלחודוי. דאלמלי תרווייהו, מזדווגן לא יכיל עלמא למסבל,\u0004 דהיינו כנ\"ל בשמעון ולוי, שאם מתחברים היו מחריבים את העולם. כי אם הדינים דנוקבא אינם נפשכים מתקון קו האמצעי, הם נוספים על דינים דדכורא ומחריבים את העולם. וע\"כ לקח השעיר לחטאת אצלו."],[0,"","אמנם כדי להבין היטב ענין השעיר לעזאזל, צריכים להרחיב הדברים. כי אומר בזהר (וירא אות שפ\"ד) \u0003ביום ראש השנה, בעי לערבב ליה לשטן, ביום הכפורים, בעי לנייחא ולמעבד ליה נייחא דרוחא. וכדין אתהפך סנגוריא\u0004 וכו': ופירוש הדברים הוא, כי ביום ראש השנה חוזר העולם כמו שהיה ביום ד' דמעשה בראשית, דהיינו שחוזרים ונגלים ג\"ר דחכמה, ואז מתעורר הס\"א להמשיך דינים דשמאל על העולם. והתיקון לזה היא תקיעת שופר הממעטת הג\"ר מן העולמות, ונשארים בו\"ק בלי ראש והשטן מתבלבל, כי כל אחיזתו הוא בג\"ר דשמאל, ועתה נעלמו ע\"י תקיעת שופר (כמ\"ש זה וירא אות שפ\"א בהסולם ע\"ש) אמנם כיון שנעלמו הג\"ר נעשה מקום חסרון בעולמות, והס\"א עולה ונאחז במקום החסרון ג\"ר, ומחטיא את הבריות. שז\"ס בינונים תלוים ועומדים עד יוה\"כ. ולפיכך נעשה תקון שני ביום הכפורים, שחוזרים וממשיכים הארת החכמה, ועם כל זה נעשה תקון, שהס\"א לא יתאחז בשמאל להחטיא העולם בהמשכת החכמה ממעלה למטה. והיינו התקון המובא בכמה מקומות, שבעת גלוי החכמה יתגלו עמה דינים קשים המענישים הרשעים, שעי\"ז משומרת החכמה שלא ימשיכו הרשעים אותה ממעלה למטה (כנ\"ל פקודי אות שע\"ו) ותדע, שמקור התקון הזה, נעשה ביום הכפורים, על ידי השעיר לעזאזל. כי ביום הכפורים מתגלה החכמה ע\"י הלבשת המלכות לבינה, ואז \u0003ונתן אהרן על שני השעירים גורלות.\u0004 אשר שעיר אחד ה\"ס דינין דנוקבא, ושעיר הב' הוא דינין דדכורא הנמשכים מג\"ר דחכמה. \u0003גורל אחד לה',\u0004 דהיינו השעיר שבו דינין דנוקבא מכח תקיעת שופר בראש השנה, עולה לה', לקו האמצעי, ומקבל הארת החכמה בבחינת ו\"ק, כדרך הקדושה. \u0003וגורל אחד לעזאזל,\u0004 דהיינו השעיר שבו דינין דדכורא, מתגלה עליו ג\"ר דחכמה מכח שממשיך הארת החכמה, ממעלה למטה כדרך הס\"א, ואח\"כ ושלח את השעיר במדבר. דהיינו שנגלו עליו כל העונשים הנמשכים לדבוקים בו, מחמת שמוכרחים להמשך אחריו אל המדבר והחורבן. ואז ב' הדינים נתתקנו, כי דינין דנוקבא נתתקנו ע\"י שעלה עליהם הגורל לה', שהוא קו האמצעי, שתיקן אותם בהארת ו\"ק דחכמה. וכדי שלא יתאחז הס\"א במקום חסרון של ג\"ר דחכמה, ניתן לו השעיר לעזאזל הממשיך ג\"ר דחכמה, עם כל הדינים והעונשים, ואז \u0003קטגור נעשה סנגור\u0004 (כמ\"ש באות קי\"ח) כי לא ירצה להתאחז במקום חסרון דג\"ר דחכמה, כדי שלא יקלקל הג\"ר של עצמו שיונק מהשעיר לעזאזל. וגם אין פחד שיחטיא את בני העולם שימשיכו ממעלה למטה, מחמת רוב הדינים הרובצים עליו ע\"י ששולחים אותו המדברה. וז\"ש (באות קי\"ח) \u0003כד מטא\u0004 וכו' \u0003מתבסמין כלהו ביה,\u0004 דהיינו כל הדינים, הן הדינים דנוקבא, והן הדינים דדכורא, כמבואר."],[0,"","וז\"ש (באות קט\"ז) \u0003יתיב חד גבאי,\u0004 דהיינו אותו שהיא מבחינת דינים דנוקבא ישב אצלי ויקבל ו\"ק דחכמה כדרך הקדושה. \u0003וחד יזיל וישוט בעלמא,\u0004 דהיינו לפתות בני העולם שימשכו לו הג\"ר מלמעלה למטה כחפצו. ואז הולך הס\"א להחטיא בני אדם שימשיכו לו הארת החכמה ממעלה למטה, וז\"ש, \u0003נפק האי, אזל ושט בעלמא ואשכח להו לישראל בכמה פולחנין\u0004 וכו', דהיינו שע\"י הגורלות, כי נתברר מעלת השעיר אשר עלה עליו הגורל לה', דהיינו ההארות והמוחין הגדולים הנמשכים ממנו, ולעומתו רוב הדינים ועונשים הנגלים עם השעיר אשר עלה עליו הגורל לעזאזל, אז כל ישראל מתדבקים בה' בכל נפשם, והס\"א \u0003לא יכיל למיעל בהו בדלטורא.\u0004 מחמת הפחד מדינים הנגלים עמו. ונודע, שאותם ב' דינים הנזכרים, הם שורשי כל החטאים והעונות, וכיון שאותם ב' דינים השורשיים נתתקנו, כבר בטוחים שבית ישראל לא יחטאו עוד. וז\"ש, \u0003שלחין ליה במטולא דכל חובייהו דישראל\u0004 דהיינו כמ\"ש ונשא השעיר עליו את כל עונותם אל ארץ גזרה. כי ישראל נעשו בטוחים שלא יחטאו עוד, מחמת הדינים שנגלו עם השעיר שנשלח לארץ גזרה. ואז יכפר להם. ובזה נתבאר היטב, מה ששאל ר' אבא (באות קי\"א) \u0003הני עדבין למה.\u0004"],[0,"","ומה ששאל, \u0003ואהרן למה ליה למיהב עדבין.\u0004 הוא כמ\"ש (באות קט\"ז) \u0003ונתן אהרן, בגין דאתי מסטרא דחסד,\u0004 וע\"כ היה ראוי להמשיך שפע החסדים על השעיר אשר עלה עליו הגורל לה'. וליחד ימין ושמאל שבמלכות זה בזה. ומה ששאל, \u0003ופרשתא דא למה,\u0004 דהיינו למה נאמרה ביום הכפורים, הוא כמ\"ש (באות קט\"ו) \u0003ומגו רחימותא\u0004 וכו', \u0003יהב לון יומא חד בשתא לדכאה להו ולזכאה להו מכל חוביהון.\u0004"],[1,"ות\"ח לאו דא","וכו': ובוא וראה, לא זה בלבד הוא, אלא בכל מקום שצריכים ישראל להטהר מעונם, הקב\"ה נותן להם עצה לקשר בעלי הדין, שלא יקטרגו, ולבשם אותם, באלו הקרבנות והעולות, שמקריבים לפני הקב\"ה (כמ\"ש בפרשת נח דף מ\"ב ד\"ה ות\"ח ובדף מ\"ח ד\"ה ועם, ע\"ש כל ההמשך) ואז אינם יכולים להרע, וביום ההוא, דיוה\"כ, יותר מכל, וכמו שישראל למטה מבשמים הכל, ע\"י שני השעירים, כך מבשמים לכל המקטרגים. והכל הוא קרבן ועבודת הקב\"ה."],[2,"תאנא בההיא שעתא","וכו': למדנו, בשעה ההיא שכתוב, ולקח אהרן את שני וגו'. מתעוררים באותו היום אלו שני השעירים, שהם דינין דנוקבא ודינין דדכורא, למעלה, ורוצים להתחבר זה עם זה כנ\"ל, ולשלוט ולצאת לעולם. כיון שהכהן מקרב אלו ב' השעירים למטה, בבית המקדש, מתקרבים אלו שלמעלה, אז יוצאים גורלות לכל הצדדים, הכהן נותן גורלות למטה, הכהן, שהוא חסד, נותן גורלות למעלה. וכמו שאחד נשאר בהקב\"ה, דהיינו שעיר אחד לה', למטה, ואחד, שהוא השעיר לעזאזל, מוציאים אותו למדבר ההוא, כך הוא למעלה, אחד נשאר בהקב\"ה, בקו האמצעי, ואחד יוצא ומשוטט בעולם לאותו מדבר העליון, דהיינו הדינים המתגלים עם הופעת החכמה, שהם בחינת מדבר וארץ גזרה (כמ\"ש לעיל באות קי\"ח באורך) ואחד באחד מתקשר. כלומר שמאירים זה על זה, שעי\"ז מתבטלים ב' מיני הדינים הן דינין דנוקבא והן דינין דדכורא, כנ\"ל באורך."],[3,"כתיב וסמך אהרן","וגו': כתוב, וסמך אהרן את שתי ידיו על ראש השעיר החי והתודה עליו וגו'. משום זה \u0003וסמך אהרן את שתי ידיו,\u0004 שה\"ס קו ימין וקו שמאל, כדי שהקב\"ה, שהוא קו האמצעי, יסכים על ידיו. \u0003על ראש השעיר החי,\u0004 המלה \u0003החי\u0004 הוא מדויק, שבא לכלול השעיר שלמעלה. שעליו מתגלים הג\"ר דחכמה עם הדינים (כנ\"ל באות קי\"ח), וחכמה נקראת \u0003חי.\u0004"],[4,"והתודה עליו את כל עונות:","הוא כמו שכתוב, והתודה אשר חטא \u0003עליה,\u0004 שהעמדנו אשר \u0003עליה\u0004 פירושו, שהאדם נטהר ונשאר \u0003עליה\u0004 על הכשבה, כל אותו העון, אף כאן \u0003והתודה עליו,\u0004 פירושו, אחר שהתודה הכהן בשביל ישראל, \u0003עליו,\u0004 כלומר, שישארו כל עונות \u0003עליו.\u0004"],[5,"א\"ל ר' אבא","וכו': א\"ל ר\"א, אם כן, והרי כתוב, ולא יזבחו עוד את זבחיהם לשעירים, ואיך אתה אומר שהשעיר לעזאזל מכוון כנגד השעיר שלמעלה. אמר לו, כאן הוא משונה, כי שם היו מקריבים הקרבן לשעירים, כי לא כתוב, ולא יזבחו עוד את זבחיהם שעירים, אלא לשעירים, כי שם עשו עבודתם לשעירים ונתנו להם שליטה, וכאן רק, ונשא השעיר עליו את כל עונותם, והקרבן אינו נעשה אלא להקב\"ה. בוא וראה, בשביל הקרבן מתבשמים עליונים ותחתונים, והדין אינו שורה ואינו שולט על ישראל."]],[[0,"","לָמַדְנוּ, כַּמָּה קְבוּצוֹת מְחַבְּלִים מִזְדַּוְּגִים (מזדמנים), שֶׁהֵם תַּחַת יָדוֹ, וּמְמֻנִּים לְרַגֵּל אֶת הָאָרֶץ עַל כָּל אוֹתָם שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, וְאוֹתוֹ יוֹם לֹא מָצוּי הַמַּלְשִׁין (פתחון) לְדַבֵּר עַל יִשְׂרָאֵל. כְּשֶׁמַּגִּיעַ הַשָּׂעִיר הַזֶּה אֶל הָהָר, כַּמָּה שִׂמְחָה עַל שִׂמְחָה מִתְבַּשְּׂמִים כֻּלָּם בּוֹ. וְאוֹתוֹ שׁוֹמֵר שֶׁיּוֹצֵא, חוֹזֵר וְאוֹמֵר אֶת תִּשְׁבַּחְתָּם שֶׁל יִשְׂרָאֵל, הַקָּטֵגוֹר נַעֲשֶׂה סָנֵגוֹר."],[1,"","וּבֹא רְאֵה, לֹא זֶה לְבַדּוֹ הוּא, אֶלָּא בְּכָל מָקוֹם שֶׁרוֹצִים יִשְׂרָאֵל לְהִטָּהֵר מֵחֲטָאֵיהֶם, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לָהֶם עֵצָה לִקְשֹׁר אֶת בַּעֲלֵי הַדִּין וּלְבַשֵּׂם אוֹתָם בְּאוֹתָם קָרְבָּנוֹת וְעוֹלוֹת שֶׁקְּרֵבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז לֹא יְכוֹלִים לְהָרַע. וְאוֹתוֹ יוֹם יוֹתֵר עַל הַכֹּל, כְּמוֹ שֶׁיִּשְׂרָאֵל מְבַשְּׂמִים לְמַטָּה אֶת הַכֹּל, כָּךְ מְבַשְּׂמִים אֶת כָּל אֵלּוּ שֶׁלָּהֶם יֵשׁ הַלְשָׁנָה (פתחון), וְהַכֹּל הוּא קָרְבָּן וַעֲבוֹדָה שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","לָמַדְנוּ, בְּאוֹתָה שָׁעָה שֶׁכָּתוּב וְלָקַח אַהֲרֹן אֶת שְׁנֵי הַשְּׂעִירִים וְגוֹ', הֵם מִתְעוֹרְרִים בְּאוֹת יוֹם לְמַעְלָה וְרוֹצִים לִשְׁלֹט (לשטות) וְלָצֵאת לָעוֹלָם. כֵּיוָן שֶׁהַכֹּהֵן מַקְרִיב אֶת אֵלּוּ לְמַטָּה, אָז נִקְרָבִים אוֹתָם שֶׁלְּמַעְלָה, וְאָז עוֹלִים הַגּוֹרָלוֹת בְּכָל הַצְּדָדִים. הַכֹּהֵן נוֹתֵן גּוֹרָלוֹת לְמַטָּה, הַכֹּהֵן נוֹתֵן גּוֹרָלוֹת לְמַעְלָה. כְּמוֹ שֶׁאֶחָד נִשְׁאָר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַטָּה, וְאֶת הָאֶחָד מוֹצִיאִים לְאוֹתוֹ הַמִּדְבָּר, כָּךְ גַּם לְמַעְלָה אֶחָד נִשְׁאָר עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאֶחָד יוֹצֵא לְשׁוֹטֵט בָּעוֹלָם לְאוֹתוֹ הַמִּדְבָּר הָעֶלְיוֹן, וְאֶחָד נִקְשָׁר בְּאֶחָד."],[3,"","כָּתוּב וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָו עַל רֹאשׁ הַשָּׂעִיר הַחַי וְהִתְוַדָּה עָלָיו וְגוֹ'. מִשּׁוּם כָּךְ וְסָמַךְ אַהֲרֹן אֶת שְׁתֵּי יָדָו, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עַל יָדוֹ. עַל רֹאשׁ הַשָּׂעִיר הַחַי, הַחַי דַּוְקָא, לְהַכְלִיל אוֹתוֹ שֶׁלְּמַעְלָה."],[4,"","וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת, כְּמוֹ שֶׁכָּתוּב (ויקרא ה) וְהִתְוַדָּה אֲשֶׁר חָטָא עָלֶיהָ. וּבֵאַרְנוּ עָלֶיהָ, שֶׁנִּטְהָר הָאָדָם וְנִשְׁאָר עָלֶיהָ כָּל אוֹתוֹ הַחֵטְא. אַף כָּאן וְהִתְוַדָּה עָלָיו, אַחַר שֶׁהִתְוַדָּה הַכֹּהֵן בַּעֲבוּרָם שֶׁל יִשְׂרָאֵל - עָלָיו, כְּלוֹמַר, כֻּלָּם יִשָּׁאֲרוּ עָלָיו."],[5,"","אָמַר לוֹ רַבִּי אַבָּא, אִם כָּךְ, כָּתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים. אָמַר לוֹ, כָּאן שׁוֹנֶה, שֶׁשָּׁם לַשְּׂעִירִים הָיוּ מַקְרִיבִים קָרְבָּן, וּמִשּׁוּם כָּךְ לֹא כָתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם שְׂעִירִים, אֶלָּא לַשְּׂעִירִים, שֶׁשָּׁם לַשְּׂעִירִים הָיוּ עוֹשִׂים פֻּלְחָן וְשִׁלְטוֹן, וְכָאן - וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם, וְהַקָּרְבָּן אֵינוֹ נַעֲשֶׂה אֶלָּא לַקָּדוֹשׁ בָּרוּךְ הוּא. בֹּא וּרְאֵה שֶׁבִּגְלַל הַקָּרְבָּן מִתְבַּשְּׂמִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְהַדִּין לֹא שׁוֹלֵט וְשׁוֹרֶה עַל יִשְׂרָאֵל."]]],[["תָּאנָא, וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. מַהוּ אִישׁ עִתִּי. אֶלָּא רָזָא דְּמִלָּה הָכִי הוּא בְּכָל מַה דְּאִתְעָבִיד, בָּעֵי בַּר נָשׁ זַמִּין לְהַהִיא מִלָּה. אִית בַּר נָשׁ דְּבִרְכְתָא אִתְקַיָּים עַל יְדֵיהּ יַתִּיר מֵאָחֳרָא. תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ בְּכַהֲנָא, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, אַל תִּקְרֵי יְבוֹרָךְ, אֶלָּא יְבָרֵךְ, בְּגִין דְּהוּא זַמִּין דְּיִתְקַיָּים בִּרְכָתָא עַל יְדֵיהּ בְּהַאי. (ס\"א ושארי ברכתא באשגחותא דיליה).","וְאִית בַּר נָשׁ דְּהוּא זַמִּין לְאִתְקַיְּימָא לְוָוטִין עַל יְדֵיהּ, וּבְכָל מַה דְּיַשְׁגַח לֵיתֵי לְוָוטַיָיא וּמְאֵרָה וּבְעִיתָא כְּגוֹן בִּלְעָם, דְּאִקְרֵי רַע עַיִן, דְּהֲוָה זַמִּין בְּכָל בִּישׁ, וְלָא הֲוָה זַמִּין לְטָב. וְאַף עַל גַּב דִבְרָךְ, בִּרְכָתֵיהּ לָא בִּרְכָתָא, וְלָא אִתְקְיָּים. וְכַד הֲוָה לָיִיט, כָּל מַאן דְּלָיִיט אִתְקְיָּים, וְאַפִילּוּ בְּרִגְעָא חֲדָא, וְעַל דָּא כְּתִיב, (במדבר כ״ד:ג׳) שְׁתֻם הָעָיִן. בְּכָל אֲתַר דְּעֵינֵיהּ שַׁלְטָא אִתְלַטְּיָיא.","תָּא חֲזֵי מַה כְּתִיב. (במדבר כ״ד:א׳) וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו, בְּגִין דְּיִתְעַר מֵהַהוּא סִטְרָא הַהוּא דְּשַׁלְטָא תַּמָּן, וְיֵיתֵי בְּדַלְטוֹרְיָא עָלַיְיהוּ דְּיִשְׂרָאֵל. מַה כְּתִיב בְּהוּ בְּכַהֲנֵי, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, דְּהוּא הֲוָה זַמִּין בְּהַאי, וְשָׁארִי בִּרְכָתָא בְּאַשְׁגָּחוּתָא דִּילֵיהּ. וְעַל דָּא תָּנֵינָן, יִסְטֵי בַּר נָשׁ אֲפִילּוּ מִמֵּאָה אָרְחִין, וְלָא יִאְרַע בְּבַּר נָשׁ דְּאִית לֵיהּ עֵינָא בִּישָׁא.","אוּף הָכָא וְשִׁלַּח בְּיַד אִישׁ עִתִּי, דְּהוּא זַמִּין לְהַאי. וְרָשִׁים לְהַאי, וְכַהֲנָא הֲוָה אִשְׁתְּמוֹדַע בֵּיהּ, חַד עֵינָא יַתִיר מֵאָחֳרָא פּוּרְתָא. סוּרְטָא דְּעַל עֵינָא אִתְחַפְּיָא בְּשַׂעֲרִין סַגִיאִין. מְכַּחֲלָא עֵינָא, וְלָא מִסְתָּכַּל בְּמֵישָׁר. הַאי הוּא בַּר נָשׁ זַמִּין לְהַאי, וְכַדְקָא חֲזֵי לֵיהּ. וְעַל דָּא כְּתִיב בְּיַד אִישׁ עִתִּי.","בְּגוּשׁ חֲלָבָא הֲוָה בַּר נָשׁ, דִּבְכָל אֲתַר דְּמָחֵי בִּידוֹי, הֲוָה מִית, וְלָא הֲווֹ בְּנֵי נָשָׂא מְקָרְבִין בַּהֲדֵיהּ. בְּסוּרְיָּא הֲוָה בַּר נָשׁ, דִּבְכָל אֲתַר דְּאִסְתָּכַּל אֲפִילּוּ לְטָב, כֹּלָּא אִתְהַפָּךְ לְבִישׁ. יוֹמָא חַד הֲוָה חַד בַּר נָשׁ אָזִיל בְּשׁוּקָא, וַהֲווּ אַנְפּוֹי נְהִירִין. אָתָא הַהוּא בַּר נָשׁ וְאִסְתָּכַּל בֵּיהּ, וְאִתְבָּקַע עֵינֵיהּ. בְּגִין כָּךְ, בְּכֹלָּא הֲוָה בַּר נָשׁ זַמִּין, לְהַאי וּלְהַאי. וְעַל דָּא כְּתִיב טוֹב עַיִן הוּא יְבוֹרָךְ, אַל תִּקְרֵי יְבוֹרָךְ אֶלָּא יְבָרֵךְ.","וְתָאנָא, הַאי בַּר נָשׁ דְּהֲוָה אָזִיל לְמַדְבְּרָא, כַּד מָטָא בֵּיהּ בְּהַהוּא שְׂעִירָא הֲוָה סָלִיק לְטוּרָא, וְדָחֵי לֵיהּ בִּתְרֵין יְדוֹי. וְלָא הֲוָה נָחִית לְפַלְגוּת טוּרָא, עַד דְּאִתְעָבִיד שַׁיְיפִין שַׁיְיפִין. וְהַהוּא בַּר נָשׁ הֲוָה אָמַר, כַּךְ יִמָּחוּ עֲוֹנוֹת עַמְּךָ וְגוֹ'. וּבְגִין דְּסָלִיק הַהוּא קַטֵיגוֹרְיָא וְאִתְעָבִיד סַנֵיגוֹרְיָא דְּיִשְׂרָאֵל, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא, כָּל חוֹבַיְיהוּ דְּיִשְׂרָאֵל, וְכָל מַה דִּכְתִיב בְּאִינּוּן פִּתְקִין דִּלְעֵילָּא, לְאַדְכְּרָא חוֹבַיְיהוּ דִּבְנֵי נָשָׁא, נָטִיל לוֹן וּרְמֵי לוֹן כְּהַאי גַּוְונָא, לַאֲתַר דְּאִתְקְרֵי מְצוּלוֹת יָם. הֲדָא הוּא דִכְתִיב, (מיכה ז׳:י״ט) וְתַשְׁלִיךְ בִּמְצוּלוֹת יָם כָּל חַטֹּאתָם.","תָּאנָא, (ויקרא ט״ז:ה׳) וּמֵאֵת עֲדַת בְּנֵי יִשְׂרָאֵל יִקַּח שְׁנֵי שְׂעִירֵי עִזִּים לְחַטָּאת, וּמֵאֵת עֲדַת, בְּגִין דִּיְהֵא מִכֻּלְּהוּ, וְיִתְכַּפֵּר לְכֻלְּהוּ. דְּהָא כָּל חוֹבַיְיהוּ דִּבְנֵי יִשְׂרָאֵל הָכָא תַּלְיָין, וְכֻלְּהוּ מִתְכַּפְּרֵי בְּדָא. וְלָא סָגֵי מִבַּר נָשׁ חַד. וּמֵאָן אֲתַר אִתְנְסִיבוּ מֵאִינּוּן קוּפִּין דְּבַעֲזָרָה נַטְלִין אַגְרָא, וְאַיְיתֵי לְהוּ מֵאִינּוּן דָּמֵי דַּהֲווֹ מִכֻּלְּהוּ."],[[0,"תאנא ושלח ביד","וגו': למדנו. ושלח ביד איש עתי המדברה. מהו איש עתי. ומשיב, אלא סוד הדבר כך הוא. בכל מה שנעשה, צריך אדם העושה להיות מוכן לדבר ההוא. יש בן אדם שהברכה מתקיימת על ידו יותר מאחר. שהוא מטעם הכנתו לזה. בוא וראה מה כתוב בכהן, טוב עין הוא יבורך. אל תקרי יבורך אלא יברך. כי משום שהוא טוב עין הוא מוכן שתתקיים הברכה על ידו בזה."],[1,"ואית ב\"נ דהוא","וכו': ויש בן אדם שהוא מוכן שתתקיימנה קללות על ידו, ובכל מקום שיביט תבאנה קללות ומארה ובהלה. כמו בלעם שנקרא רע עין, כי היה מוכן לכל רע ולא היה מוכן לטוב. ואע\"פ שברך, ברכתו לא היה ברכה, ולא נתקיימה. וכשהיה מקלל, כל מה שקילל היה מתקיים, ואפילו ברגע אחד היה מתקיים. וע\"כ כתוב, \u0003שתום העין,\u0004 כי בכל מקום ששלטו עיניו, נתקלל."],[2,"ת\"ח מה כתיב","וכו': בוא וראה, מה כתוב, וישת אל המדבר פניו. הוא, כדי שיתעורר הצד השולט שם דהיינו הס\"א, ויבא במלשינות וקטרוגים על ישראל. מה כתוב בכהנים, טוב עין הוא יבורך. כי הוא מוכן לזה והברכה שורה בנתינת עיניו. וע\"כ למדנו שהאדם יסור אפילו ממאה דרכים, ולא יפגוש באדם שיש לו עין רעה."],[3,"אוף הכא ושלח","וכו': אף כאן, \u0003ושלח ביד איש עתי,\u0004 היינו שהוא מוכן לזה ורשום לזה, והכהן היה מכיר בו, כי עין אחת היתה גדולה קצת יותר מהשניה, העור שעל העין, דהיינו העפעפים, מכוסה בשערות גדולות, העין בצבע כחול, ואינו מביט במישור. זה הוא אדם המוכן לזה, לשלוח השעיר לעזאזל, והוא כראוי לו, וע\"כ כתוב, ביד איש עתי. \u0003סורטא,\u0004 פירושו עפעפים, לפי הענין."],[4,"בגוש חלבא הוה","וכו': בגוש חלב, היה אדם, שבכל מקום שהכה בידו היה ממית, ובני אדם לא היו קרבים אליו. בסוריא היה אדם, שבכל מקום שהביט, אפילו שהיה כונתו לטוב, היה הכל מתהפך לרע. יום אחד היה אדם אחד הולך בשוק, והיו פניו מאירים, בא אותו אדם והביט בו, ונבקעה עינו. משום זה, לכל דבר, בין לטוב בין לרע, יש איש המוכן לו, לזה ולזה. וע\"כ כתוב, טוב עין הוא יבורך. אל תקרא יבורך, אלא יברך."],[5,"ותאנא האי ב\"נ","וכו': ולמדנו, אדם זה שהיה הולך עם השעיר למדבר, כשהגיע שם עם השעיר, היה עולה להר, ודחה אותו בשתי ידים, ולא היה יורד לחצי ההר, עד שנעשה אברים אברים. והאדם ההוא היה אומר, כך ימחו עונות עמך וכו'. ומשום שעי\"ז, עלה הקטגור ונעשה סנגור של ישראל (כנ\"ל באות קי\"ח) אז לוקח הקב\"ה כל עונות ישראל, וכל מה שכתוב, באלו פסקי דין שלמעלה להזכיר עונות בני אדם, ומשליך אותם כאפן הזה, שנשלך השעיר לעזאזל מן ההר, אל המקום שנקרא מצלות ים. שה\"ס מקום החשך והדינים דשמאל שמתחת המלכות הנקראת ים. ז\"ש, ותשליך במצלות ים כל חטאתם."],[6,"תאנא ומאת עדת","וגו' \u0003לחטאת:\u0004 למדנו, הכתוב אומר \u0003ומאת עדת,\u0004 ללמד שיקחו מכסף כולם, ויתכפר לכולם. כי כל עונות ישראל תלוים כאן, וכולם מתכפרים בזה. וע\"כ לא די שיקחו מכסף אדם אחד. ומאיזה מקום נלקחים. הוא, שלוקחים כסף מן הקופות שבעזרה, ומביאים השעירים, מכסף הזה שהוא של כולם."]],[[0,"","לָמַדְנוּ, וְשִׁלַּח בְּיַד אִישׁ עִתִּי הַמִּדְבָּרָה. מַהוּ אִישׁ עִתִּי? אֶלָּא סוֹד הַדָּבָר כָּךְ הוּא - בְּכָל מַה שֶּׁנַּעֲשֶׂה, צָרִיךְ אָדָם מְזֻמָּן לְאוֹתוֹ דָבָר. יֵשׁ אָדָם שֶׁהַבְּרָכָה מִתְקַיֶּמֶת עַל יָדוֹ יוֹתֵר מֵאַחֵר. בּא וּרְאֵה מַה כָּתוּב בְּכֹהֵן, טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ אֶלָּא יְבָרֵךְ, כִּי הוּא מְזֻמָּן שֶׁתִּתְקַיֵּם בְּרָכָה עַל יָדוֹ בָּזֶה. (ושורה הברכה בהשגחתו)."],[1,"","וְיִשִׁ אָדָם שֶׁמְּזֻמָּן שֶׁיִּתְקַיְּמוּ עַל יָדוֹ קְלָלוֹת, וּבְכָל מַה שֶּׁיִּתְבּוֹנֵן יָבֹאוּ קְלָלוֹת וּמְאֵרָה וּבְעָתָה, כְּמוֹ בִּלְעָם שֶׁנִּקְרָא רַע עַיִן, שֶׁהָיָה מְזֻמָּן לְכָל רַע וְלֹא הָיָה מְזֻמָּן לְטוֹב, וְאַף עַל גַּב שֶׁבֵּרַךְ, בִּרְכָתוֹ אֵינָהּ בְּרָכָה וְלֹא הִתְקַיְּמָה. וּכְשֶׁהָיָה מְקַלֵּל, כָּל מַה שֶּׁקִּלֵּל הִתְקַיֵּם, וַאֲפִלּוּ בְּרֶגַע אֶחָד, וְעַל זֶה כָּתוּב (במדבר כד) שְׁתֻם הָעָיִן. בְּכָל מָקוֹם שֶׁעֵינוֹ שָׁלְטָה - הִתְקַלֵּל."],[2,"","בֹּא וּרְאֵה מַה כָּתוּב, (שם) וַיָּשֶׁת אֶל הַמִּדְבָּר פָּנָיו, כְּדֵי שֶׁיִּתְעוֹרֵר מֵאוֹתוֹ צַד שֶׁהוּא שׁוֹלֵט שָׁם, וְיָבֹא בְהַלְשָׁנָה עַל יִשְׂרָאֵל. מַה כָּתוּב בַּכֹּהֲנִים? (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ, שֶׁהוּא הָיָה מְזֻמָּן לָזֶה וְשׁוֹרָה בְרָכָה בַּהַשְׁגָּחָה שֶׁלּוֹ. וְעַל זֶה שָׁנִינוּ, יִסְטֶה אָדָם אֲפִלּוּ מִמֵּאָה דְרָכִים וְלֹא יִפְגֹּשׁ אָדָם שֶׁיֵּשׁ לוֹ עַיִן רָעָה."],[3,"","אַף כָּאן, וְשִׁלַּח בְּיַד אִישׁ עִתִּי - שֶׁהוּא מְזֻמָּן לָזֶה וְרָשׁוּם לָזֶה, וְהַכֹּהֵן הָיָה מַכִּיר בּוֹ עַיִן אַחַת יוֹתֵר מֵאַחֶרֶת מְעַט. הָעוֹר שֶׁעַל הָעַיִן מְכֻסֶּה בִּשְׂעָרוֹת רַבּוֹת, הָעַיִן מְכֻחֶלֶת וְלֹא מִסְתַּכֵּל יָשָׁר, זֶהוּ הָאָדָם הַמְזֻמָּן לְכָךְ וְהָרָאוּי לוֹ. וְעַל זֶה כָּתוּב בְּיַד אִישׁ עִתִּי."],[4,"","בְּגוּשׁ חָלָב הָיָה אָדָם, שֶׁבְּכָל מָקוֹם שֶׁמַּכֶּה בְּיָדוֹ, הָיָה מֵת, וְלֹא הָיוּ אֲנָשִׁים מִתְקָרְבִים אֵלָיו. בְּסוּרְיָה הָיָה אָדָם, שֶׁבְּכָל מָקוֹם שֶׁבּוֹ הִסְתַּכֵּל, אֲפִלּוּ לְטוֹב, הַכֹּל הִתְהַפֵּךְ לְרַע. יוֹם אֶחָד הָיָה אִישׁ אֶחָד הוֹלֵךְ בַּשּׁוּק, וְהָיוּ פָנָיו מְאִירוֹת. בָּא אוֹתוֹ אִישׁ וְהִסְתַּכֵּל בּוֹ, וְנִבְקְעָה עֵינוֹ. מִשּׁוּם כָּךְ לַכֹּל הָיָה אָדָם מוּכָן, לָזֶה וְלָזֶה. וְעַל זֶה כָּתוּב טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ אֶלָּא יְבָרֵךְ."],[5,"","וְלָמַדְנוּ, הָאִישׁ הַזֶּה שֶׁהָיָה הוֹלֵךְ לַמִּדְבָּר, כְּשֶׁהִגִּיעַ שָׁם אוֹתוֹ שָׂעִיר, הָיָה עוֹלֶה לָהָר, וְדוֹחֶה אוֹתוֹ בִּשְׁתֵּי יָדָיו, וְלֹא הָיָה מַגִּיעַ לַחֲצִי הָהָר עַד שֶׁנַּעֲשָׂה אֵיבָרִים אֵיבָרִים, וְאוֹתוֹ אִישׁ הָיָה אוֹמֵר: כָּךְ יִמָּחוּ עֲווֹנוֹת עַמְּךְ וְגוֹ'. וּמִשּׁוּם שֶׁעוֹלֶה אוֹתוֹ קָטֵגוֹר וְנַעֲשֶׂה סָנֵגוֹר שֶׁל יִשְׂרָאֵל, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶת כָּל חֲטָאֵי יִשְׂרָאֵל וְכָל מַה שֶּׁכָּתוּב בְּאוֹתָם פְּתָקִים שֶׁלְּמַעְלָה לְהַזְכִּיר אֶת חֲטָאֵי בְּנֵי הָאָדָם, הוּא נוֹטֵל אוֹתָם וְזוֹרֵק אוֹתָם כְּמוֹ זֶה לְמָקוֹם שֶׁנִּקְרָא מְצוּלוֹת יָם. זֶהוּ שֶׁכָּתוּב (מיכה ז) וְתַשְׁלִיךְ בִּמְצֻלוֹת יָם כָּל חַטֹּאתָם."],[6,"","לָמַדְנוּ, וּמֵאֵת עֲדַת בְּנֵי יִשְׂרָאֵל יִקַּח שְׁנֵי שְׂעִירֵי עִזִּים לְחַטָּאת. וּמֵאֵת עֲדַת, כְּדֵי שֶׁיִּהְיֶה מִכֻּלָּם וְיִתְכַּפֵּר לְכֻלָּם, שֶׁהֲרֵי כָּל חֲטָאֵי בְּנֵי יִשְׂרָאֵל כָּאן תְּלוּיִים, וְכֻלָּם מִתְכַּפְּרִים בָּזֶה, וְלֹא מַסְפִּיק מֵאִישׁ אֶחָד. וּמֵאֵיזֶה מָקוֹם נִלְקָחִים? מֵאוֹתָן קֻפּוֹת שֶׁבָּעֲזָרָה נוֹטְלִים שָׂכָר, וּמְבִיאִים אוֹתָם מֵאוֹתָם דָּמִים שֶׁהָיוּ מִכֻּלָּם."]]],[["וְהַהוּא שְׂעִירָא אָחֳרָא, דְּהֲוָה אִשְׁתְּאַר לְּקוּדְשָׁא בְּרִיךְ הוּא, עַבְדִּין לֵיהּ חַטָּאת בְּקַדְמִיתָא. וְהָא אוֹקִימְנָא בְּאָן אֲתַר הֲוָה מִתְקַשְּׁרָא. וּלְבָתַר דָּא מִתְקָרְבִין הָנֵי, וּמִתְבַּסְּמִין כֹּלָּא, וְאִשְׁתָּאָרוּ יִשְׂרָאֵל זַכָּאִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, מִכָּל חוֹבִין דְּעָבְדוּ וְחָבוּ קָמֵיהּ. הֲדָא הוּא דִכְתִיב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'.","תּוּ אָמַר רִבִּי שִׁמְעוֹן, (בראשית כ״ז:י״א) וַיֹּאמֶר יַעֲקֹב אֶל רִבְקָה אִמּוֹ הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר וְאָנֹכִי אִישׁ חָלָק. מַאי קָא רְמִיזָא, אֶלָּא וַדַּאי עֵשָׂו אִישׁ שָׂעִיר, הוּא מֵהַהוּא דְּאִקְרֵי שָׂעִיר, דְּהָא מֵהַהוּא סִטְרָא אָתֵי. וְאָנֹכִי אִישׁ חָלָק: גְּבַר מֵהַהוּא דְּפָלִיג לְכָל שְׁאָר עַמִּין רַבְרְבִין מְמָנָן. דִּכְתִּיב, (דברים ד׳:י״ט) אֲשֶׁר חָלַק יְיָ' אֱלֹהֶיךָ אוֹתָם, וּכְתִיב (דברים לב) כִּי חֵלֶק יְיָ' עַמּוֹ וְגוֹ'. תּוּ אִישׁ חָלָק, מִתְּרֵי שְׂעִירִים וְאִשְׁתְּאַר חֲדָא. דְּכַהֲנָא פָּלִיג לֵהּ, חַד לְחוּלָקֵיהּ, וְחַד לְּקוּדְשָׁא בְּרִיךְ הוּא. אֲמַאי. בְּגִין דְּיַטְעִין עַל כַּתְפּוֹי כָּל חוֹבוֹי דְּיַעֲקֹב, דִּכְתִּיב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם, עֲוֹנוֹת תָּם.","תָּאנָא, בְּהַהוּא יוֹמָא כַּמָה פִּתְחִין פְּתִיחָן לָקֳבְלֵיהוֹן דְּיִשְׂרָאֵל לְקַבְּלָא צְלוֹתֵיהוֹן. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְזַכָּאָה לוֹן, וּלְדַכְּאָה לוֹן, הֲדָא הוּא דִכְתִיב כִּי בַיּוֹם הַזֶּה יְכַפֵּר וְגוֹ'. בְּהַאי יוֹמָא אִתְעֲטָּר כַּהֲנָא בְּכַמָּה עִטְרִין. בְּהַאי יוֹמָא פּוּלְחָנָא דְּכַהֲנָא יַקִּירָא וְרַב מִכָּל פּוּלְחָנִין. לְכֹלָּא יָהַב חוּלָקָא בְּאִינּוּן קָרְבְּנִין דְּקוּדְשָׁא בְּרִיךְ הוּא. בְּהַאי יוֹמָא אִתְעֲטָּר (ס\"א אתער) חֶסֶד בְּעָלְמָא עַל יְדָא דְּכַהֲנָא, מְקָרֵב קָרְבְּנִין עַל חוֹבֵיהוֹן דְּעַמָּא. עַל חוֹבֵיהּ בְּקַדְמִיתָא, וּלְבָתַר עַל חוֹבֵיהוֹן דְּעַמָּא. מְקָרֵב עִלָּוָון עָלֵיהּ וְעַל עַמָּא וְהָא אוֹקִימְנָא מִלֵּי.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא (מ\"ד) דָּא, לְמִפְלַח רַבָּא כַּהֲנָא פּוּלְחָנָא דְּהַהוּא יוֹמָא כְּמָה דְּאִצְּטְרִיךְ, וּלְמִשְׁלַח שָׂעִיר לַעֲזָאזִל. רָזָא דָּא כְּמָה דְאַתְּ אָמֵר, בְּגִין לְאִתְפָּרְשָׁא מֵעַמָּא קַדִּישָׁא, וְלָא יִתְבַּע חוֹבֵיהוֹן קָמֵי מַלְכָּא. וְלָא יְקַטְרֵג עָלַיְיהוּ, דְּהָא לֵית לֵיהּ תְּקִיפוּ וְשׁוּלְטָנוּ, (בה) בַּר כַּד אִתָּקַף רוּגְזָא מִלְּעֵילָּא, וּבְהַהוּא דּוֹרוֹנָא אִתְהַפָּךְ לְבָתַר אַפּוֹטְרוֹפוֹסָא עָלַיְיהוּ, וְעַל דָּא אִתְדַּחְיָיא מִקַּמֵּי מַלְכָּא. וְהָא אוֹקִימְנָא, בְּגִין דְּאִיהוּ קֵץ כָּל בָּשָׂר.","וְעַמָּא קַדִּישָׁא יָהֲבִין לֵיהּ כְּמָה דְּאִצְּטְרִיךְ לֵיהּ שָׂעִיר, וְרָזָא דָּא (בראשית כ״ז:י״א) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. כְּמָה דְּאִיהוּ בִּסְטָר דִּקְדוּשָּׁה דְּכַר וְנוּקְבָּא, אוּף הָכִי בִּסְטָר מְסָאֲבוּ דְּכַר וְנוּקְבָּא. מַתְלָא אַמְרֵי, לְכַלְבָּא אַרְמֵי לֵיהּ גַּרְמָא, יְלַחֵךְ עַפְרָא דְּרַגְלָךְ.","שָׁאֲלוּ לְבֶן זוֹמָא, מַהוּ לְסָרוּסֵי כַּלְבָא. אָמַר לָהֶם, (ויקרא כ״ב:כ״ד) וּבְאַרְצְּכֶם לֹא תַּעֲשׂוּ, כָּל שֶׁבְּאַרְצְּכֶם לֹא תַּעֲשׂוּ. כְּמָה דְּאִצְּטְרִיךְ עָלְמָא לְהַאי, הָכִי אִצְּטְרִיךְ עָלְמָא לְהַאי. וְעַל דָּא אִתְּמַר, (בראשית א׳:ל״א) וְהִנֵּה טוֹב מְאֹד דָּא מַלְאָךְ הַמָּוְת. לֵית לְבַטְלָא לֵיהּ מִן עָלְמָא, עָלְמָא אִצְּטְרִיךְ לֵיהּ, אַף עַל גַּב דִּכְתִּיב בֵּיהּ, (ישעיהו נ״ו:י״א) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְגוֹ', לָא יִתְבַטְלוּן מִן עָלְמָא. כֹּלָּא אִצְּטְרִיךְ טוֹב וָרָע.","וּבְגִּינֵי כַּךְ אִית לָן בְּיוֹמָא דָּא לְמִרְמֵי לֵיהּ גַּרְמָא לְכַלְבָּא, עַד דְּאִיהוּ גָּרִיר, יֵיעוּל מַאן דְּיֵיעוּל לְגַבֵּי הֵיכָלָא דְּמַלְכָּא, וְלֵית מַאן דְּיִמְחֵי בִּידוֹי. לְבָתַר יְכָשְׁכֵּשׁ לֵיהּ בִּזְנָבֵיהּ.","מַה כְּתִיב וְהִתְוַדָּה עָלָיו אֶת כָּל עֲוֹנוֹת בְּנֵי יִשְׂרָאֵל, וּכְתִיב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲוֹנוֹתָם. כֵּיוָן דְּאִיהוּ חָמֵי הַאי שָׂעִיר. תִּיאוּבְתֵּיהּ לְגַבֵּיהּ, וּלְאִשְׁתַּכְלְּלָא בַּהֲדֵּיהּ, וְלָא יָדַע מֵאִינּוּן חוֹבִין דְּקָא נָטִיל שָׂעִיר. תָּב לְגַבַּיְיהוּ דְּיִשְׂרָאֵל, חָמֵי לוֹן בְּלָא חוֹבִין, בְּלָא פְּשָׁעִין, דְּהָא כֻּלְּהוּ שָׁרָאן בְּרֵישָׁא דְּשָעִיר, סָלִיק לְעֵילָּא, וְשַׁבַּח לוֹן קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. וְקוּדְשָׁא בְּרִיךְ הוּא חָמֵי סַהֲדוּתָא דְּהַהוּא מְקַטְרְגָא, וְהוֹאִיל וְתִיאוּבְתֵיהּ לְרַחֲמָא עַל עַמֵּיהּ, אַף עַל גַּב דְּאִיהוּ יָדַע כָּל עוֹבָדָא, חָס עֲלֵייהוֹן דְּיִשְׂרָאֵל.","וְכֹלָּא שַׁרְיָא בְּדָא, בְּגִין דְּלָא יִתְּעַר רָזָא דְּדִינָא מִלְּעֵילָּא, וְיִתְּקַף הַאי וְיִשְׁתֵּצּוּן בְּנֵי עָלְמָא, דְּהָא דָּא מִסִּטְרָא דְּדִינָא קַשְׁיָא קָא אָתֵי. וְאִי יִתְּעַר הַאי, בְּחוֹבֵי בְּנֵי אֵינָשָׁא אִתְּעַר. דְּהָא לֵית לֵיהּ אַתְּעֲרוּ לְסַלְּקָא לְעֵילָּא לְאִתְּעָרָא דִּינָא קַשְׁיָא בַּר בְּדִיל חוֹבֵי בְּנֵי נָשָׁא. דְּהָא בְּשַׁעֲתָא דְּבַּר נָשׁ עָבִיד חוֹבָא, אִתְכְּנַשׁ הַאי, וְכַמָּה אֶלֶף סַיְיעָן דִּילֵיהּ, וּמִתְכַּנְּפֵי תַּמָּן, וְנַטְלֵי לֵיהּ, וְסַלְקֵי לְעֵילָּא רַחֲמָנָא לִישֵׁזְבָן. וְעַל כֹּלָּא יָהַב קוּדְשָׁא בְּרִיךְ הוּא עֵיטָא לְיִשְׂרָאֵל לְאִשְׁתְּזָבָא מִכָּל סִטְרִין. וְעַל דָּא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לוֹ אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו. (ע\"כ רעיא מהימנא)","עַד דַּהֲווֹ אָזְלֵי, יָתְבוּ בְּחַד חֲקַל, וְצַלּוּ. נָחַת חַד עֲנָנָא דְּאֶשָּׁא, וְאַסְחַר לוֹן. אָמַר רִבִּי שִׁמְעוֹן, הָא חֲמֵינָא דְּקוּדְשָׁא בְּרִיךְ הוּא רְעוּתָא דִּילֵיהּ הָכָא. נֵיתִיב. יָתְבוּ וַהֲווּ אַמְרֵי מִלֵּי דְּאוֹרַיְיתָא. פָּתַח וְאָמַר, (משלי כ״ה:כ״ה) מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, הָא אִסְתַּכַּלְנָא בְּמִלּוֹי דִּשְׁלֹמֹה מַלְכָּא, וְכֻלְּהוּ (ס\"א בחכמתא) בְּחָכְמָה אַמָרָן.","תָּא חֲזֵי ג' סִפְרִין דְּחָכְמְתָא אַפִּיק שְׁלֹמֹה לְעָלְמָא, וְכֻלְּהוּ בְּחָכְמְתָא עִלָּאָה. שִׁיר הַשִּׁירִים חָכְמָה, קֹהֶלֶת תְּבוּנָה, וּמִשְׁלֵי דַּעַת. לָקֳבֵל ג' אִלֵּין, עֲבַד ג' סְפָרִים. שִׁיר הַשִּׁירִים כְּנֶגֶד חָכְמָה הָכֵי הוּא. קֹהֶלֶת לְקָבֵל תְּבוּנָה, הָכֵי הוּא. מִשְׁלֵי לְקָבֵל דַעַת. בְּמָאי אִתְחֲזֵי. אֶלָּא כָל אִינּוּן קְרַאֵי בִּתְרֵי גְּוָונֵי אִינּוּן, רֵישָׁא וְסֵיפָא תְּרֵי גְּוָונֵי אִתְחַזְיָיא. וְכַד מִסְתַּכְּלֵי קְרַאֵי, דָא כְּלִיל בְּדָא, וְדָא כְּלִיל בְּדָא, בְּגִין כָּךְ שָׁקִיל לָקֳבְלֵיהּ דְּדַעַת.","הַאי קְרָא לָאו רֵישֵׁיהּ סֵיפֵיהּ וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. וְכַד אִסְתַּכַּלְנָא בֵּיהּ, כֹּלָּא כָּלִיל חַד בְּחַד, בֵּין מִסֵיפֵיהּ לְרֵישֵׁיהּ, בֵּין מֵרֵישֵׁיהּ לְסֵיפֵיהּ. שְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, וְדָא וְדָא נַיְיחָא דְּרוּחָא, כְּמָה דְּהַאי נַיְיחָא דְּרוּחָא, כַּךְ הַאי נַיְיחָא דְּרוּחָא.","עַד דַּהֲווֹ יַתְבֵי, אָתָא חַד בַּר נָשׁ, אָמַר, אִנְתּוּ דְּרִבִּי שִׁמְעוֹן אַתְּסִיאַת מִמַּרְעָהָא. וְחַבְרַיָּיא שָׁמְעוּ קָלָא, דְּקוּדְשָׁא בְּרִיךְ הוּא שָׁבַק לְאִינּוּן חוֹבֵי דְּדָרָא. אָמַר רִבִּי שִׁמְעוֹן, הָא אִתְקַיָּים הָכָא קְרָא, וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, הָכִי הוּא נַיְיחָא דְּרוּחָא, כְּמוֹ מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. אָמַר לְהוּ נְקוּם וְנֵזִיל דְּקוּדְשָׁא בְּרִיךְ הוּא אַרְחִישׁ לָן בְּנִסִּין.","פָּתַח וְאָמַר, מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה, דָּא אוֹרַיְיתָא. דְּכָל מַאן דְּזָכֵי לְמִלְעֵי בְּאוֹרַיְיתָא, וּמְרַוִי נַפְשָׁא מִנָּהּ, מַה כְּתִיב וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. קוּדְשָׁא בְּרִיךְ הוּא אַכְרִיז עָלֵיהּ כַּמָה טָבָאן לְאוֹטָבָא לֵיהּ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי. הֲדָא הוּא דִכְתִיב, וּשְׁמוּעָה טוֹבָה, מַאן אֲתַר מֵאֶרֶץ מֶרְחָק, מֵאֲתַר דְּקוּדְשָׁא בְּרִיךְ הוּא הֲוָה רָחִיק מִנֵּיהּ בְּקַדְמִיתָא, מֵאֲתַר דְּהֲוָה בַּר נָשׁ בִּדְבָבוּ עִמֵּיהּ בְּקַדְמִיתָא, דִּכְתִּיב, (איוב כ׳:כ״ז) וְאֶרֶץ מִתְקוֹמָמָה לוֹ, מֵהַהוּא אֲתַר מַקְדִּימִין לֵיהּ שְׁלָם, הֲדָא הוּא דִכְתִיב, מֵאֶרֶץ מֶרְחָק. וּכְתִיב (ירמיהו ל״א:ג׳) מֵרָחוֹק יְיָ' נִרְאָה לִי וְאַהֲבַת עוֹלָם אַהֲבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד."],[[0,"וההוא שעירא אחרא","וכו': ושעיר האחר שנשאר להקב\"ה עושים אותו תחילה חטאת, וכבר העמדנו באיזה מקום הוא מתקשר (כנ\"ל בסולם אות קי\"ח) ואח\"כ מתקרבים אלו, והכל מתבשם, ונשארו ישראל זכאים לפני הקב\"ה מכל העונות שעשו וחטאו לפניו. ז\"ש, כי ביום הזה יכפר עליכם וגו'."],[1,"תו אמר רבי שמעון","וכו': עוד אר\"ש, ויאמר יעקב אל רבקה אמו הן עשו אחי איש שעיר ואנכי איש חלק. מה זה רומז. אלא ודאי, עשו \u0003איש שעיר\u0004 הוא, מאותו הנקרא \u0003שעיר,\u0004 שהוא הס\"א, כי בא מאותו הצד. \u0003ואנכי איש חלק,\u0004 היינו איש הנחלק ממה שחלק לשאר העמים, אל השרים והממונים שלהם, שכתוב, אשר חלק ה' אותם. וכתוב, כי חלק ה' עמו וגו'. עוד, \u0003איש חלק,\u0004 היינו משני שעירים שנחלקו ונשאר חלק אחד, שהכהן חלק אותם, אחד לחלקו של יעקב ואחד להקב\"ה. למה, כדי שהשעיר ישא על כתפיו, כל עונות של יעקב, שכתוב ונשא השעיר עליו את כל עונותם, שהוא אותיות עונות תם. דהיינו עונות של יעקב שנקרא איש תם."],[2,"תאנא בההוא יומא","וכו': למדנו ביום הזה, כמה פתחים פתוחים כנגד ישראל לקבל תפלתם. אשרי חלקם של ישראל שהקב\"ה רוצה לזכותם, ולטהר אותם. ז\"ש, כי ביום הזה יכפר וגו'. ביום הזה מתעטר הכהן בכמה עטרות. ביום הזה עבודת הכהן היא יקרה וגדולה מכל העבודות. לכל נתן חלק באלו הקרבנות של הקב\"ה (כנ\"ל אות קי\"ח בהסולם), ביום הזה נתעטר החסד בעולם על ידי הכהן, המקריב קרבנות על עונות העם. תחילה הקריב על עונותיו, ואח\"כ על עונות העם. ומקריב עולות עליו ועל העם. וכבר העמדנו הדברים."],[3,"פקודא דא למפלח","וכו': מצוה זו היא שיעשה הכהן הגדול עבודת יום ההוא כמו שצריך, וישלח שעיר לעזאזל. סוד זה הוא, כמו שאתה אומר, כדי שהס\"א יפרד מן העם הקדוש, ולא יתבע עונותיהם לפני המלך, ולא יקטרג עליהם, כי אין לו כח וממשלה רק כשמתחזק הכעס מלמעלה. ובמתנה הזו, של השעיר לעזאזל, מתהפך אח\"כ לשומר עליהם (כמ\"ש לעיל באות קי\"ח ע\"ש) וע\"כ נדחה מלפני המלך. והרי העמדנו, שזה הוא, משום שהוא קץ כל בשר."],[3,"","פירוש. כמו שנתבאר לעיל (פרשת נח אות ק\"ל) שע\"כ נקרא קץ כל בשר, משום, דכל רעותיה לאו איהו אלא בבשרא תדיר, ונתבאר שם בהסולם שבשר ה\"ס הארת חכמה משמאל, שהס\"א חושק מאוד לאור הזה, ע\"ש בטעמו ונימוקו. וסוד שעיר לעזאזל הוא המשכת החכמה דשמאל, (כנ\"ל אות קי\"ח) וע\"כ כשישראל ממשיכים לו אור הזה נעשה אפוטרופוס וסנגור עליהם. כמ\"ש שם באורך."],[4,"ועמא קדישא יהבין","וכו': והעם הקדוש נותן לו כמו שצריך לו, דהיינו \u0003שעיר,\u0004 וז\"ס הן עשו אחי איש \u0003שעיר.\u0004 שהוא בחינת הס\"א. ויש בו זכר ונקבה, שכמו שיש בצד הקדושה זכר ונקבה, כן יש בצד הטומאה זכר ונקבה. משל אומרים, השלך עצם לכלב, וילחך עפר רגליך. אף כאן נותנים לס\"א שעיר והוא נעשה סניגור."],[5,"שאלו לבן זומא","וכו': שאלו לבן זומא, המותר לנו לסרס כלב. אמר להם, ובארצכם לא תעשו, פירושו, כל שבארצכם לא תעשו, ואפילו כלב. כי כמו שהעולם צריך לזה, צריך העולם ג\"כ לזה. כלומר, שאין דבר בארץ שאין לו צורך. וע\"כ למדנו, והנה טוב מאד, זהו מלאך המות, שאין לבטלו מן העולם, כי העולם צריך לו. ואע\"פ שכתוב בו במלאך המות, והכלבים עזי נפש לא ידעו שבעה וגו', לא טוב שיתבטלו מן העולם. הכל צריך הן טוב והן רע."],[6,"ובגיני כך אית","וכו': ומשום זה יש לנו ביום הזה להשליך עצם לכלב, דהיינו השעיר לעזאזל, שבעוד שהוא גורר העצם, יכנוס מי שיכנוס להיכל המלך, ואין מי שימחה בידו, כי המקטרג טרוד במתנה שלו, ואח\"כ עוד ינדנד לו בזנבו. דהיינו שיעשה סניגור."],[7,"מה כתיב והתודה","וגו': מה כתוב, והתודה עליו את כל עונות בני ישראל. וכתוב, ונשא השעיר עליו את כל עונותם. כיון שהס\"א ראה שעיר הזה התעורר חשקו אליו, ולהשתכלל עמו, ואינו יודע מאלו העונות שלקח השעיר עליו. הוא חוזר לישראל, ורואה אותם בלי עונות ובלי פשעים, כי כולם שורים על ראש השעיר, הוא עולה למעלה, ומשבח אותם לפני הקב\"ה. והקב\"ה רואה העדות של המקטרג. והואיל שחשקו לרחם על עמו, אע\"פ שהוא יודע כל מעשה, הוא מרחם על ישראל."],[8,"וכלא שריא בדא","וכו': וכל התקון שורה בזה, שלא יתעורר סוד הדין מלמעלה, ויתחזק הדין הזה ויכלו בני העולם, כי זה בא מדין קשה. ואם דין הזה מתעורר, הוא מתעורר בעונות בני אדם, כי אין לו התעוררות לעלות למעלה לעורר דין קשה רק בשביל עונות בני אדם. כי בשעה שאדם עושה עון מתאסף זה וכמה אלפים עוזרים עמו, ומתקבצים שם ולוקחים אותו ומעלים למעלה, הרחמן יצילנו. ועל הכל נתן הקב\"ה עצה לישראל להנצל מכל הצדדים. וע\"כ כתוב, אשרי העם שככה לו אשרי העם שה' אלקיו."],[8,"","ביאור המאמר. כי ידעת שמצד המלכות דצמצום א', המכונה מנעולא אין המלכות, והתחתונים הנמשכים ממנה, ראוים לקבל אור העליון. כי כח הצמצום והמסך רוכב עליה, שלא תקבל שום אור. וראה הקב\"ה שאין העולם מתקיים, ע\"כ העלה המלכות למדת הרחמים שהיא בינה, ונמתקה בה, שמלכות הממותקת הזו נקראת מפתחא, ומבחינתה יכולים המלכות והתחתונים הנמשכים ממנה לקבל אורות העליונים. כמ\"ש זה לעיל (ב\"ב דף ז' ד\"ה וכבר). אמנם גם אחר שנתקנה המלכות בכלים דמפתחא, אין הנקודה דמנעולא נעדרת ממנה לגמרי, אלא שנגנזה בה. שמשום זה נקראת המלכות עצה\"ד טוב ורע, \u0003שאם זכה, הא טוב,\u0004 שהמנעולא נגנזת ונעלמת, והמפתחא שולטת בה, ואז מקבלת כל האורות ומאירה לתחתונים. \u0003ואם לא זכה,\u0004 כי הוא חוטא, \u0003הא רע,\u0004 אז חוזרת ומתגלת המנעולא בשורש החוטא, שבמלכות, והאורות מסתלקים מחמתה שעי\"ז מת החוטא (כנ\"ל ויצא דף י\"ג ד\"ה סתרא ע\"ש)."],[8,"","ואין לשאול כיון שרצה הקב\"ה בקיום העולם ותקן את המלכות בנקודה דמפתחא, א\"כ היה ראוי שיבטל לגמרי את המנעולא ולא שתחזור ותתעורר בסבת החטא. וז\"ש (באות קל\"ו) \u0003והנה טוב מאד. דא מלאך המות לית לבטלא ליה מן עלמא, עלמא אצטריך ליה\u0004 וכו'. כי אע\"פ שנקודה דמנעולא גורמת המיתה עכ\"ז העולם צריך לה ואין לבטלה קודם גמר התקון. \u0003ובגיני כך אית לן ביומא דא למרמי ליה גרמא לכלבא,\u0004 דהיינו השעיר לעזאזל, שע\"י עבודת ישראל מתגלים עליו הג\"ר דחכמה דשמאל עם הדינים הקשים שבהן, שהסטרא אחרא נהנה מהן מאד, מטעם שאומר (באות קל\"ד) \u0003בגין דאיהו קץ כל בשר,\u0004 ע\"ש. וע\"כ נבחן זה כמו שמשליכים עצם לכלב. ונעשה כל זה, כדי שהס\"א לא יקטרג על ישראל, ולא יעורר למעלה גילוי המנעולא מחמת עונותיהם של ישראל, כי עתה, \u0003עד דאיהו גריר,\u0004 בעוד שגורר העצם שזרקו לו \u0003ייעול מאן דייעול לגבי היכלא דמלכא,\u0004 דהיינו הכהן הגדול ימשיך אורות וכל טוב מהיכל המלך, \u0003ולית מאן דימחי בידוי,\u0004 כי הס\"א לא יקטרג עליו, לגלות המנעולא המסלקת האורות, כי אז יאבד גם הוא עצמו את המתנה דשעיר לעזאזל, שהשיג ע\"י עבודת ישראל. ולא עוד, אלא, \u0003לבתר יכשכש ליה בזנביה,\u0004 כי עוד ישבח לישראל בשביל זה. כמ\"ש והולך."],[8,"","ומפרש יותר (באות קל\"ח) \u0003כתיב ונשא השעיר\u0004 וגו'. ומבאר, איך נושא עליו השעיר את כל עונות בית ישראל. ואומר, \u0003כיון דאיהו חמי האי שעיר תיאובתיה לגביה ולאשתכללא בהדיה,\u0004 כי אין חשקו אלא בבשר, שהוא החכמה דשמאל הנגלית על ראש השעיר, \u0003ולא ידע מאינון חובין דקא נטיל שעיר.\u0004 כי כל אלו האורות דחכמה דשמאל, לא נגלו במלכות אלא מחמת שנגנזה בה נקודה דמנעולא, ורק נקודה דמפתחא משמשת בה בגלוי. ונמצא שבתוך השעיר הזה נכלל בו בגניזו הנקודה דמנעולא, המסלקת את אורות האלו, אלא שהס\"א לא ידע מזה משום שנגנזה, ומשום שטרוד בשעיר שלו ואינו רוצה לאבד אורותיו, \u0003תב לגבייהו דישראל חמי לון בלא חובין\u0004 וכו' \u0003ושבח לון קמי קב\"ה.\u0004 כי רוצה שישראל יהיו זכאים ולא תתגלה המנעולא, כדי שיוכל להחזיק גם הוא בהשעיר שלו. \u0003וקב\"ה חמי\u0004 וכו' \u0003אע\"ג דאיהו ידע כל עובדא, חם עליהון דישראל,\u0004 כי אע\"פ שהקב\"ה יודע שהמנעולא גנוזה, מכל מקום אין האורות מסתלקים מחמת ידיעתו, כי הקב\"ה הוא ברחמים על ישראל שע\"כ גנז המנעולא, וגילה מדת הרחמים וכל עוד שהס\"א אינו מקטרג על זה, לא יתעורר שום דין מחמת ידיעתו ית'. וז\"ש, \u0003בגין דלא יתער רזא דדינא מלעילא,\u0004 שהדין אינו מתעורר מלמעלה וכו', \u0003ואי יתער,\u0004 ואם הדין מתעורר ונגלית המנעולא, \u0003האי בחובי בני אנשא אתער,\u0004 הוא שמחמת החטא יש לו כח לס\"א לעורר דין המנעולא כנ\"ל. \u0003דהא לית ליה אתערו לסלקא לעילא לאתערא דינא קשיא,\u0004 כי אין התעוררות לסטרא אחרא לעלות למעלה לעורר הדין הקשה, שה\"ס המנעולא, \u0003בר בדיל חובי בני נשא,\u0004 רק בשביל החטאים של בני האדם. \u0003כנ\"ל אם לא זכה הא רע.\u0004 אבל אם הס\"א אינו מגלה, אע\"פ שהקב\"ה יודע, אין זה מזיק כלום. כי בכונה, גנז הקב\"ה את מדת הדין דמנעולא, וגילה בה המפתחא, שה\"ס שיתף רחמים בדין. כנ\"ל. כדי לקיים העולם במדת הרחמים."],[9,"עד דהוו אזלי, וכו׳:","בעוד שהיו הולכים, ישבו בשדה אחד והתפללו. ירד ענן אני שרצונו של הקב\"ה כאן, נשב. ישבו ואמרו דברי תורה. פתח ואמר, מים קרים על נפש עיפה ושמועה טובה מארץ מרחק. הנה אני מסתכל בדברי שלמה המלך, וכולם אמרם בחכמה."],[10,"ת״ח ג׳ ספרין דחכמתא וכו׳:","בוא וראה ג׳ ספרי חכמה הוציא שלמה לעולם, וכולם בחכמה עליונה. שיר השירים חכמה, קהלת תבונה, משלי דעת. כנגד ג׳ אלו, חב״ד, עשה ג׳ ספרים, שיר השירים, הוא כך כנגד חכמה. קהלת, הוא כך כנגד תבונה. משלי, כנגד דעת. שה״ס ג׳ קוין. במה נראה זה. ומשיב, אלא כל אלו המקראות הם בשני אפנים, שבתחילת הכתוב ובסוף הכתוב נראה שהם שני אפנים מיוחדים, דהיינו שמדבר מב׳ ענינים, שזהו בחינת ב׳ קוין, ימין ושמאל. וכשמסתכלים במקראות, זה כלול בזה, וזה כלול בזה. שב׳ ענינים שבכתוב, כלולים זב״ז, משום זה הוא שקול כנגד הדעת. שה״ס קו האמצעי הכולל ימין ושמאל יחד. מכאן אנו רואים, שכל דבריו הם בסוד ג׳ קוין וכן ספריו נחלקים לג׳ קוים, חכמה בינה דעת."],[11,"האי קרא לאו וכו׳:","ומפרש דבריו, מקרא זה, אין תחלתו סופו ואין סופו תחלתו, דהיינו שהם ב׳ ענינים נפרדים, וכשאני מסתכל בו הם כלולים אחד באחד בין מסופו לתחילתו ובין מתחילתו לסופו. כי כתוב, שמועה טובה מארץ מרחק מים קרים על נפש עיפה. אשר מים קרים על נפש עיפה, הוא ענין מיוחד, ושמועה טובה מארץ מרחק, הוא ענין מיוחד, וכלולים זה בזה, כי זה וזה הוא נחת רוח, כי כמו שזה נחת רוח כך זה נחת רוח. והוא קו האמצעי הכולל ב׳ הענינים. כנ״ל."],[12,"עד דהוו יתבי וכו׳:","בעוד שהיו יושבים, בא אדם אחד ואמר, שאשת ר׳ שמעון נתרפאה ממחלתה. והחברים שמעו קול, שהקב״ה מחל לעונות הדור. א״ר שמעון, הרי נתקיים כאן הכתוב, ושמועה טובה מארץ מרחק, הוא נחת רוח כמו מים קרים על נפש עיפה. אמר להם נקום ונלך, שהקב״ה עושה לנו נסים."],[13,"פתח ואמר מים וכו׳:","פו\"א, מים קרים על נפש עיפה, זו היא התורה, שכל מי שזכה לעסוק בתורה ומרוה נפשו ממנה, מה כתוב, ושמועה טובה מארץ מרחק. הקב״ה מכריז עליו כמה טובות להטיב לו בעולם הזה ובעולם הבא. ז״ש ושמועה טובה. מאיזה מקום היא טובה. מארץ מרחק, דהיינו, ממקום שהקב״ה היה רחוק ממנו מתחילה, דהיינו ממקום שהיה עמו בשנאה מתחילה. שכתוב וארץ מתקוממה לו. ממקום הזה מקדימים לו שלום. ז״ש מארץ מרחק. וכתוב, מרחוק ה׳ נראה לי ואהבת עולם אהבתיך ע״כ משכתיך חסד. (חסר סוף המאמר)."]],[[0,"","וְאוֹתוֹ הַשָּׂעִיר הָאַחֵר, שֶׁהָיָה נִשְׁאָר לַקָּדוֹשׁ בָּרוּךְ הוּא, עוֹשִׂים אוֹתוֹ חַטָּאת בָּרִאשׁוֹנָה. וַהֲרֵי בֵּאַרְנוּ בְּאֵיזֶה מָקוֹם הָיָה נִקְשָׁר. וְאַחַר כָּךְ מַקְרִיבִים אֶת אֵלֶּה, וְהַכֹּל מִתְבַּשְּׂמִים, וְיִשְׂרָאֵל נִשְׁאָרִים צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל הַחֲטָאִים שֶׁעָשׂוּ וְחָטְאוּ לְפָנָיו. זֶהוּ שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'."],[1,"","עוֹד אָמַר רַבִּי שִׁמְעוֹן, (בראשית כז) וַיֹּאמֶר יַעֲקֹב אֶל רִבְקָה אִמּוֹ הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר וְאָנֹכִי אִישׁ חָלָק. מַה הוּא רוֹמֵז? אֶלָּא וַדַּאי שֶׁעֵשָׂו אִישׁ שָׂעִיר, וְהוּא מֵאוֹתוֹ שֶׁנִּקְרָא שֵׂעִיר, שֶׁהֲרֵי מֵאוֹתוֹ צַד הוּא בָּא. וְאָנֹכִי אִישׁ חָלָק - אִישׁ מֵאוֹתוֹ שֶׁחִלֵּק לְכָל שְׁאָר הָעַמִּים מְמֻנִּים גְּדוֹלִים, שֶׁכָּתוּב (דברים ד) אֲשֶׁר חָלַק ה' אֱלֹהֶיךְ אֹתָם, וְכָתוּב (שם לב) כִּי חֵלֶק ה' עַמּוֹ וְגוֹ'. עוֹד אִישׁ חָלָק, מִשְּׁנֵי שְׂעִירִים, וְנִשְׁאָר אֶחָד. שֶׁהַכֹּהֵן חִלֵּק אוֹתָם - אֶחָד לְחֶלְקוֹ, וְאֶחָד לַקָּדוֹשׁ בָּרוּךְ הוּא. לָמָּה? כְּדֵי שֶׁיִּטְעַן עַל כְּתֵפוֹ אֶת כָּל חֲטָאֵי יַעֲקֹב, שֶׁכָּתוּב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם, עֲונֹת תָּם."],[2,"","לָמַדְנוּ, בְּאוֹתוֹ יוֹם כַּמָּה פְתָחִים פְּתוּחִים כְּנֶגֶד יִשְׂרָאֵל לְקַבֵּל תְּפִלּוֹתֵיהֶם. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אוֹתָם וּלְזַכּוֹת אוֹתָם, זֶהוּ שֶׁכָּתוּב כִּי בַיּוֹם הַזֶּה וְגוֹ'. בַּיּוֹם הַזֶּה מִתְעַטֵּר הַכֹּהֵן בְּכַמָּה עֲטָרוֹת. בַּיּוֹם הַזֶּה עֲבוֹדַת הַכֹּהֵן נִכְבָּדָה וּגְדוֹלָה מִכָּל הָעֲבוֹדוֹת. לְכֻלָּם נוֹתֵן חֵלֶק בְּאוֹתָם הַקָּרְבָּנוֹת שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. בַּיּוֹם הַזֶּה מִתְעַטֵּר (מתעורר) הַחֶסֶד בָּעוֹלָם עַל יְדֵי הַכֹּהֵן, מַקְרִיב אֶת הַקָּרְבָּנוֹת עַל חֲטָאֵי הָעָם, עַל חֶטְאוֹ בָּרִאשׁוֹנָה, וְאַחַר כָּךְ עַל חֲטָאֵי הָעָם. הוּא מַקְרִיב עוֹלוֹת עָלָיו וְעַל הָעָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים."],[3,"","מִצְוָה זוֹ, שֶׁיַּעֲבֹד הַכֹּהֵן הַגָּדוֹל אֶת עֲבוֹדַת אוֹתוֹ הַיּוֹם כְּמוֹ שֶׁצָּרִיךְ, וְלִשְׁלֹחַ שָׂעִיר לַעֲזָאזֵל. הַסּוֹד הַזֶּה כְּמוֹ שֶׁנֶּאֱמַר, כְּדֵי שֶׁיִּפָּרֵד מֵהָעָם הַקָּדוֹשׁ וְלֹא יִתְבַּע אֶת חֲטָאֵיהֶם לִפְנֵי הַמֶּלֶךְ וְלֹא יְקַטְרֵג עֲלֵיהֶם, שֶׁהֲרֵי אֵין לוֹ תֹּקֶף וְשִׁלְטוֹן (בה) אֶלָּא רַק כְּשֶׁמִּתְחַזֵּק הָרֹגֶז מִלְמַעְלָה, וּבְאוֹתוֹ דוֹרוֹן מִתְהַפֵּךְ אַחַר כָּךְ לְאַפּוֹטְרוֹפּוֹס עֲלֵיהֶם, וְעַל כֵּן נִדְחֶה מִלִּפְנֵי הַמֶּלֶךְ. וַהֲרֵי בֵּאַרִנוּ, מִשּׁוּם שֶׁהוּא קֵץ כָּל בָּשָׂר."],[4,"","וְהָעָֹם הַקָּדוֹשׁ נוֹתְנִים לוֹ כְּמוֹ שֶׁהוּא צָרִיךְ שָׂעִיר, וְסוֹד זֶה - (בראשיתכז) הֵן עֵשָׂו אָחִי אִישׁ שָׂעִיר. כְּמוֹ שֶׁהוּא בְּצַד הַקְּדֻשָּׁה זָכָר וּנְקֵבָה, אַף כָּךְ בְּצַד הַטֻּמְאָה זָכָר וּנְקֵבָה. מָשָׁל אוֹמְרִים, זְרֹק עֶצֶם לְכֶלֶב, וְהוּא יְלַחֵךְ אֶת עֲפַר רַגְלְךְ."],[5,"","שָׁאֲלוּ אֶת בֶּן זוֹמָא, הַאִם לְסָרֵס כֶּלֶב? אָמַר לָהֶם, (ויקרא כב) וּבְאַרְצְכֶם לֹא תַעֲשׂוּ, כֹּל שֶׁבְּאַרְצְכֶם לֹא תַעֲשׂוּ. כְּמוֹ שֶׁהָעוֹלָם צָרִיךְ אֶת זֶה, כָּךְ צָרִיךְ הָעוֹלָם אֶת זֶה. וְעַל זֶה נֶאֱמַר, (בראשית א) וְהִנֵּה טוֹב מְאֹד - זֶה מַלְאַךְ הַמָּוֶת, אֵין לְבַטְּלוֹ מִן הָעוֹלָם, שֶׁהָעוֹלָם צָרִיךְ אוֹתוֹ. אַף עַל גַּב שֶׁכָּתוּב בּוֹ (ישעיה נב) וְהַכְּלָבִים עַזֵּי נֶפֶשׁ לֹא יָדְעוּ שָׂבְעָה וְגוֹ', לֹא יִתְבַּטְּלוּ מִן הָעוֹלָם. הַכֹּל צָרִיךְ, טוֹב וָרָע."],[6,"","וּמִשּׁוּם כָּךְ יֵשׁ לָנוּ בַּיּוֹם הַזֶּה לִזְרֹק עֶצֶם לַכֶּלֶב, עַד שֶׁהוּא גּוֹרֵר, יִכָּנֵס מִי שֶׁיִּכָּנֵס לְהֵיכַל הַמֶּלֶךְ, וְאֵין מִי שֶׁיִּמְחֶה בְיָדוֹ. אַחַר כָּךְ יְכַשְׁכֵּשׁ בִּזְנָבוֹ."],[7,"","מַה כָּתוּב? וְהִתְוַדָּה עָלָיו אֶת כָּל עֲונֹת בְּנֵי יִשְׂרָאֵל, וְכָתוּב וְנָשָׂא הַשָּׂעִיר עָלָיו אֶת כָּל עֲונֹתָם. כֵּיוָן שֶׁהוּא רוֹאֶה אֶת הַשָּׂעִיר הַזֶּה, תְּשׁוּקָתוֹ אֵלָיו וּלְהִתְתַּקֵּן עִמּוֹ, וְלֹא יוֹדֵעַ מֵאוֹתָם הַחֲטָאִים שֶׁנּוֹטֵל הַשָּׂעִיר. הוּא שָׁב אֶל יִשְׂרָאֵל, רוֹאֶה אוֹתָם בְּלִי חֲטָאִים, בְּלִי פְשָׁעִים, שֶׁהֲרֵי כֻּלָּם שׁוֹרִים עַל רֹאשׁ הַשָּׂעִיר, עוֹלֶה לְמַעְלָה וּמְשַׁבֵּחַ אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹאֶה אֶת עֵדוּת אוֹתוֹ הַמְקַטְרֵג, וְהוֹאִיל וּתְשׁוּקָתוֹ לְרַחֵם עַל עַמּוֹ, אַף עַל גַּב שֶׁהוּא יוֹדֵעַ אֶת כָּל הַמַּעֲשֶׂה, הוּא חָס עַל יִשְׂרָאֵל."],[8,"","וְהַכֹּל שׁוֹרֶה עַל זֶה, כְּדֵי שֶׁלֹּא יְעוֹרֵר אֶת סוֹד הַדִּין מִלְמַעְלָה, וְזֶה יִתְחַזֵּק וְיֻשְׁמְדוּ בְּנֵי הָעוֹלָם, שֶׁהֲרֵי זֶה בָּא מִצַּד הַדִּין הַקָּשֶׁה, וְאִם זֶה יִתְעוֹרֵר, הוּא מִתְעוֹרֵר בַּחֲטָאֵי בְּנֵי הָאָדָם, שֶׁהֲרֵי אֵין לוֹ הִתְעוֹרְרוּת לַעֲלוֹת לְמַעְלָה לְעוֹרֵר דִּין קָשֶׁה רַק מִשּׁוּם חֲטָאֵי בְּנֵי אָדָם. שֶׁהֲרֵי בְּשָׁעָה שֶׁאָדָם עוֹשֶׂה חֵטְא, זֶה מִתְאַסֵּף, וְכַמָּה אֲלָפִים מְסַיְּעִים שֶׁלּוֹ, וּמִתְכַּנְּסִים שָׁם וְנוֹטְלִים אוֹתוֹ וְעוֹלִים לְמַעְלָה. הָרַחֲמָן יַצִּילֵנוּ. וְעַל הַכֹּל נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא עֵצָה לְיִשְׂרָאֵל לְהִנָּצֵל מִכָּל הַצְּדָדִים, וְעַל זֶה כָּתוּב, (תהלים קמה) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו. (עד כאן הרעיא מהימנא)."],[9,"","עֵד שֶׁהָיוּ הוֹלְכִים, יָשְׁבוּ בְשָׂדֶה אַחַת וְהִתְפַּלְלוּ. יָרַד עָנָן אֶחָד שֶׁל אֵשׁ וְהִקִּיף אוֹתָם. אָמַר רַבִּי שִׁמְעוֹן, הֲרֵינִי רוֹאֶה שֶׁרְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כָּאן. נֵשֵׁב. יָשְׁבוּ וְהָיוּ אוֹמְרִים דִּבְרֵי תוֹרָה. פָּתַח וְאָמַר, (משלי כה) מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. הֲרֵי הִסְתַּכַּלְתִּי בְּדִבְרֵי שְׁלֹמֹה הַמֶּלֶךְ, וְאֶת כֻּלָּם אָמַר בְּחָכְמָה."],[10,"","בֹּא רְאֵה, שְׁלֹשָׁה סִפְרֵי חָכְמָה הוֹצִיא שְׁלֹמֹה לָעוֹלָם, וְכֻלָּם בְּחָכְמָה עֶלְיוֹנָה. שִׁיר הַשִּׁירִים - חָכְמָה, קֹהֶלֶת - תְּבוּנָה, וּמִשְׁלֵי - דַּעַת. כְּנֶגֶד שְׁלֹשֶׁת אֵלֶּה עָשָׂה שְׁלֹשָׁה סְפָרִים. שִׁיר הַשִּׁירִים כְּנֶגֶד חָכְמָה כָּךְ הוּא. קֹהֶלֶת כְּנֶגֶד תְּבוּנָה כָּךְ הוּא. מִשְׁלֵי כְּנֶגֶד דַּעַת. בַּמֶּה זֶה נִרְאֶה? אֶלָּא כָּל אוֹתָם הַכְּתוּבִים הֵם בִּשְׁנֵי גְוָנִים, רֹאשׁ וָסוֹף, שְׁנֵי גְוָנִים נִרְאִים. וּכְשֶׁמִּסְתַּכְּלִים בַּכְּתוּבִים, זֶה כָּלוּל בָּזֶה וְזֶה כָּלוּל בָּזֶה, מִשּׁוּם כָּךְ שָׁקוּל כְּנֶגֶד הַדַּעַת."],[11,"","הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ וְאֵין סוֹפוֹ רֹאשׁוֹ, וּכְשֶׁהִסְתַּכַּלְתִּי בוֹ, הַכֹּל כָּלוּל אֶחָד עִם אֶחָד, בֵּין מִסּוֹפוֹ לְרֹאשׁוֹ, בֵּין מֵרֹאשׁוֹ לְסוֹפוֹ. שְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, וְזֶה וָזֶה נַחַת רוּחַ. כְּמוֹ שֶׁזֶּה נַחַת רוּחַ, כָּךְ זֶה נַחַת רוּחַ."],[12,"","עֵד שֶׁהָיוּ יוֹשְׁבִים, בָּא אִישׁ אֶחָד וְאָמַר, אִשְׁתּוֹ שֶׁל רַבִּי שִׁמְעוֹן נִרְפְּאָה מֵחָלְיָהּ. וְהַחֲבֵרִים שָׁמְעוּ קוֹל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מָחַל לְאוֹתָם חֲטָאֵי הַדּוֹר. אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי הִתְקַיֵּם כָּאן הַפָּסוּק, וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק, כָּךְ זֶה נַחַת רוּחַ, כְּמוֹ מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה. אָמַר לָהֶם, נָקוּם וְנֵלֵךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַרְחִישׁ לָנוּ נִסִּים."],[13,"","פָּתַח וְאָמַר, מַיִם קָרִים עַל נֶפֶשׁ עֲיֵפָה - זוֹ הַתּוֹרָה. שֶׁכָּל מִי שֶׁזּוֹכֶה לַעֲסֹק בַּתּוֹרָה וּמַרְוֶה מִמֶּנָּה אֶת הַנֶּפֶשׁ, מַה כָּתוּב? וּשְׁמוּעָה טוֹבָה מֵאֶרֶץ מֶרְחָק. הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְרִיז עָלָיו כַּמָּה טוֹבוֹת לְהֵיטִיב לוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. זֶהוּ שֶׁכָּתוּב וּשְׁמוּעָה טוֹבָה. מֵאֵיזֶה מָקוֹם? מֵאֶרֶץ מֶרְחָק, מִמָּקוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הָיָה רָחוֹק מִמֶּנּוּ בַּתְּחִלָּה, מִמָּקוֹם שֶׁהָיָה אָדָם בְּשִׂנְאָה עִמּוֹ בַּתְּחִלָּה, שֶׁכָּתוּב (איוב כ) וְאֶרֶץ מִתְקוֹמָמָה לוֹ, מֵאוֹתוֹ מָקוֹם שֶׁמַּקְדִּימִים לוֹ שָׁלוֹם, זֶהוּ שֶׁכָּתוּב מֵאֶרֶץ מֶרְחָק. וְכָתוּב, (ירמיה לא) מֵרָחוֹק ה' נִרְאָה לִי וְאַהֲבַת עוֹלָם אֲהַבְתִּיךְ עַל כֵּן מְשַׁכְתִּיךְ חָסֶד."]]],[["(כאן חסר) (ויקרא ט״ז:י״ח) וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי יְיָ' וְכִפֶּר עָלָיו. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ' דִּבֵּר וַיִּקְרָא אָרֶץ מִמִּזְרָח שֶׁמֶשׁ עַד מְבוֹאוֹ. תָּאנָא, אֶלֶף וַחֲמֵשׁ מְאָה וְחַמְשִׁין רִבּוֹא מָארֵי שִׁירָתָא, מְזַמְּרִין לְּקוּדְשָׁא בְּרִיךְ הוּא, כַּד נָהִיר יְמָמָא. וְאֶלֶף וַחֲמֵשׁ מְאָה וְאַרְבְּעִין וּתְמַנְיָא בְּטִיהֲרָא. וְאֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא בְּהַהִיא שַׁעֲתָא דְּאִקְרֵי בֵּין הָעַרְבַּיִם.","רִבִּי יוֹסֵי אָמַר, כַּד נָהִיר יְמָמָא, כָּל אִינּוּן מָארֵי דִּיבָבָא, מְשַׁבְּחָן בְּמִלֵי תּוּשְׁבְּחָן, לָקֳבְלֵיהּ דְּהַאי בֹּקֶר. (ס\"א כד אתער, דכד) דְּכַד אִתְּעַר הַאי בֹּקֶר, כֻּלְּהוּ מִתְבַסְּמִין, וְדִינָא אִשְׁתְּכִיךְ, וְאָמְרִין תּוּשְׁבְּחָן. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. וְהַהוּא זִמְנָא, (הימנותא) חֶדְוָותָא וּבִרְכָּאן מִשְׁתַּכְּחִין בְּעָלְמָא, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְּעַר לְאַבְרָהָם לְאַחֲיָיא לֵיהּ, וְאִשְׁתַּעֲשַׁע בֵּיהּ, וְאַשְׁלְטֵיהּ בְּעָלְמָא. וּמְנָא לָן דְּהַאי בֹּקֶר דְּאַבְרָהָם הוּא. דִּכְתִיב (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר.","בְּהַהוּא זִמְנָא דְּבֵין הָעַרְבָּיִם, כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא מָארֵי דִּילָלָה אִקְרוּן, וּמְזַמְּרִין בְּהַהִיא שַׁעֲתָא, וּקְטָטוּתָא שַׁרְיָא בְּעָלְמָא, וְהַהִיא שַׁעֲתָא אִתְּעָרוּתָא דְּאִתְּעַר קוּדְשָׁא בְּרִיךְ הוּא לְיִצְחָק, וְקָם וְדָאִין לְחַיָּיבַיָּא דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְשִׁבְעָה נַהֲרֵי אֶשָּׁא נַגְדִּין וְנָפְקִין וְחָלִין עַל רֵישֵׁיהוֹן דְּרַשִׁיעַיָּיא, וְשַׁלְהוֹבֵי גּוּמְרִין דְּנוּרָא מִתְעָרִין מֵעֵילָּא לְתַתָּא, וּכְדֵין תָּב אַבְרָהָם לְאַתְרֵיהּ. כְּמָה דְאַתְּ אָמֵר, (בראשית י״ח:ל״ג) וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. וְיוֹמָא אִתְפְּנֵי, וְחַיָּיבֵי גֵּיהִנָּם צַוְוחִין וְאַמְרִין (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָּנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. וְהַהִיא שַׁעֲתָא, בָּעֵי בַּר נָשׁ לְאִזְדַּהֲרָא, בִּצְלוֹתָא דְּמִנְחָה.","בְּזִמְנָא דְּמָטֵי לֵילְיָא אִינּוּן אֶלֶף וְה' מְאָה וְאַרְבְּעִין וּתְמַנְיָא, אִקְרוּן מִבָּרָא לְפָרוֹכְתָּא, וְאָמְרִין שִׁירָתָא. כְּדֵין דִּינִין דִּלְתַתָּא מִתְעָרִין, וְאָזְלִין וְשָׁאטִין בְּעָלְמָא, וְאִלֵּין אַמְרִין שִׁירָתָא. עַד דְּיִתְפְּלִיג לֵילְיָא מִשְׁמָרָה וּפַלְגָּא. בָּתַר דְּיִתְפְּלִיג לֵילְיָא מִזְדַמְנֵי כֻּלְּהוּ אַחֲרִינֵי כַּחֲדָא, וְאַמְרֵי תְּהִלּוֹת, כְּמָה דְאַתְּ אָמֵר (ישעיה ס) וּתְהִלּוֹת יְיָ' יְבַשֵּׂרוּ. רִבִּי יְהוּדָה אָמַר כַּד רַעֲוָא אִשְׁתְּכַח בְּצַפְרָא, תְּהִלּוֹת יְיָ' מְבַשְּׂרִין.","רִבִּי יוֹסֵי אָמַר, בָּתַר דְּרוּחָא דְּצָפוֹן אִתְּעַר בְּפַלְגוּת לֵילְיָא וְאָזִיל לֵיהּ, תְּהִלּוֹת מְבַשְּׂרֵי, עַד דְּיֵיתֵי צַפְרָא, וְאִתְּעַר הַאי בֹּקֶר, כְּדֵין חֶדְוָותָא וּבִרְכָּאן אִשְׁתְּכַח בְּעָלְמָא.","תָּאנָא, אָמַר רִבִּי אַבָּא, כֻּלְּהוּ הָכִי, וְעֵילָּא מִנְּהוֹן סַרְכִין תְּלָתָא. בְּהַהִיא שַׁעֲתָא דְּאִתְּעַר הַאי בֹּקֶר, וּמִתְעָרִין תּוּשְׁבְּחָן, כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְחַמְשִׁין רִבּוֹא, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא, וְהֵימָן שְׁמֵיהּ לָקֳבְלֵיה דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ סַרְכִין מְמָנָן עָלַיְיהוּ לְאַתְקְנָא שִׁירָתָא.","בְּהַהִיא שַׁעֲתָא דְּאִתְּעַר זִמְנָא דְּבֵין הָעַרְבַּיִם, וְזַמְרִין כָּל אִינּוּן אֶלֶף וַחֲמֵשׁ מְאָה וְתִשְׁעִין אֶלֶף רִבּוֹא מָארֵי דִּילָלָה, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא וִידוּתוּן שְׁמֵיהּ, לָקֳבְלֵיהּ דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ סַרְכִין מְמָנָן עָלַיְיהוּ, לְאַתְקְנָא הַהוּא זִמְרָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ה:ה׳) זְמִיר עָרִיצִים.","בְּהַהִיא שַׁעֲתָא דְּמָטֵי לֵילְיָא, מִתְעָרִין כָּל אִינּוּן דְּמִבָּרָא לְפָרוֹכְתָּא, כְּדֵין שָׁכִיךְ כֹּלָּא, וּפִטְרָא לָא אִשְׁתְּכַח, וְדִינִין דִּלְתַּתָּא מִתְעָרִין, כֻּלְּהוּ אִתְמָנָן כַּחֲדָא, אִלֵּין עַל אִלֵּין, עַד דְּאִתְפְּלִיג לֵילְיָא. בָּתַר דְּאִתְפְּלִיג לֵילְיָא, וּמִתְכַּנְּשֵׁי כֻּלְּהוּ, אִתְמָנָא עָלַיְיהוּ חַד מְמָנָא וְכָנִישׁ לְכָל מַשִּׁרְיָין, כְּמָה דְאַתְּ אָמֵר (במדבר י׳:כ״ה) מְאַסֵּף לְכָל הַמַּחֲנוֹת וְגוֹ', וְאָסָף שְׁמֵיהּ, לָקֳבְלֵיהּ דִּלְתַתָּא, וּתְחוֹת יְדֵיהּ כָּל אִינּוּן סַרְכִין מְמָנָן, וּמְבַשְּׂרֵי תְּהִלּוֹת.","עַד דְּאָתֵי צַפְרָא, כֵּיוָן דְּאָתֵי צַפְרָא, קָם הַהוּא נַעַ\"ר, יוֹנֵק מִשְּׁדֵי אִמֵּיהּ, לְדַכְּאָה לְהוּ, וְעָאל לְשַׁמְּשָׁא. כַּד אִתְּעַר בֹּקֶר, כְּדֵין הִיא שַׁעֲתָא דְּרַעֲוָא, דְּאִשְׁתָּעֵי מַטְרוֹנִיתָא בְּמַלְכָּא, וּמַלְכָּא מָשִׁיךְ מִנֵּיהּ חַד חוּטָא דְּבִרְכָּאן וּפָרִיס עַל מַטְרוֹנִיתָא, וְעַל אִינּוּן דְּמִזְדַוְּוגֵי לֵהּ. מַאן אִינּוּן דְּמִזְדַוְּוגֵי עִמֵּהּ. אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא בְּלֵילְיָא, כַּד אִתְפְּלַג."],[[0,"ויצא אל המזבח וגו׳:","ר׳ יהודה פתח ואמר מזמור לאסף אל אלקים ה׳ דבר ויקרא ארץ ממזרח שמש עד מבואו. למדנו, אלף וחמש מאות וחמשים רבוא בעלי שירה מזמרים להקב״ה כשמאיר היום. ואלף וחמש מאות וארבעים ושמונה כשמאירה הלבנה. דהיינו בלילה. ואלף וחמש מאה ותשעים אלף רבוא אומרים שירה בשעה ההיא הנקראת בין הערבים."],[0,"","פירוש, בבוקר עד חצי היום מאיר צד הימין של ז״א, שהוא חסדים, ומחצי היום עד הערב הנקרא בין הערבים מאיר צד השמאל של הז״א, שה״ס הארת החכמה שבקו שמאל דז״א. ובלילה עד חצות, מאיר משמרה וחצי משמרה, שה״ס קו ימין וחצי קו השמאל (כנ״ל ויחי דף קל״ח ד״ה וג׳ מ״ש). ונמצא שבכל ג׳ זמנים אלו אינם מאירים אלא קו וחצי קו, כי בבוקר כשמאיר קו ימין דז״א נמצא שמאירה החכמה וצד ימין דדעת דז״א, והם נבחנים לאלף וחמש מאה, כי הג״ר שהם חב״ד נבחנים לג׳ אלפים, נמצא החכמה בסוד אלף, וחצי הדעת הוא חצי אלף, דהיינו חמש מאה. ועד״ז בזמן בין הערבים מחצות היום ואלך כשמאיר צד שמאל דז״א, מאירה הבינה, וצד שמאל דדעת, דהיינו קו וחצי, שהם אלף וחמש מאה. ובלילה, כשמאירים קו ימין וחצי דשמאל כנ״ל, הוא ג״כ אלף וחמש מאה. וכל זה הוא מבחינת הג״ר דז״א המכונים ראש."],[0,"","ומבחינת הגוף דז״א, שהם ז״ת שלו, הנה עקרם רק ה׳ ספירות חג״ת נ״ה. כי בגוף יורדים חב״ד לבחינת חג״ת ות״ת ומלכות לבחינת נצח והוד, כנודע. אבל יסוד ומלכות אינם בחינות חדשות, אלא שהם ב׳ כוללים בלבד, שיסוד כולל חג״ת נ״ה מבחינת החסדים, והמלכות כוללת חג״ת נ״ה מבחינת הגבורות. הרי שאין בהארת הגוף אלא ה׳ ספירות חג״ת נ״ה בלבד. וכל אחת מהן כלולה מעשר הם חמשים."],[0,"","וז״ש, \u0003אלף וחמש מאה וחמשין רבוא מארי שירתא מזמרין לקכ״ה כד נהיר יממא,\u0004 דהיינו שהנמשכים מבחינת הג״ר, הם אלף וחצי אלף, דהיינו קו וחצי, שהם החכמה וחצי דעת מימין. כנ״ל. והנמשכים מגוף הם חמשים, ששם ה״ס חג״ת נ״ה שכל אחת כוללת עשר, והם חמשים. ולהיותם חסדים הם נבחנים במספר רבוא. כי רבוא, יורה על חסדים. וע״כ הם אלף ות״ק וחמשים רבוא."],[0,"","וז״ש \u0003ואלף וחמש מאה וארבעין ותמניא, בסיהרא,\u0004 שמבחינת הג״ר הם קו וחצי, שהם אלף וחצי אלף, ומבחינת הגוף, הם ה׳ ספירות חג״ת נ״ה, שכ״א כלולה עשר, חוץ מספירת הוד, שאינה כלולה אלא משמונה, כי מרוב הדינים שבלילה, ושבספירת הוד, אין מאירים יסוד ומלכות שבה. וע״כ אין שם אלא ארבעים ושמונה, מטעם החסרון של יסוד ומלכות דהוד, החסרים בלילה."],[0,"","אמנם בין הערבים, כשמאיר הצד שמאל דז״א, דהיינו הארת החכמה שבשמאל, אז נמצאות ג״ר גם בבחינת גוף דז״א, ויש אז בו ט׳ ספירות חב״ד חג\"ת נה״י, אפילו בגוף. אלא שהם בסוד דינים שאינם מאירים מטעם חסרון חסדים, כמ״ש היטב לעיל (בראשית ב׳ אות קמ״א, ובהסולם, עש״ה) וז״ש, \u0003ואלף וחמש מאה ותשעין אלף רבוא בההיא שעתא דאקרי בין הערבים,\u0004 כי הקו וחצי דצד שמאל דג״ר, שהם בינה וחציו השמאלי דדעת, הם אלף וחצי אלף, ותשע ספירות דגוף, שכל אחת כלולה מעשר, הם תשעים. שביחד הם אלף ות״ק וצ'. ובהיותם בהארת החכמה, מכונים, \u0003אלף רבוא,\u0004 כי החכמה מכונה אלף. ומבחינת לילה, אינו חושב כאן אלא קו וחצי המאירים עד חצות לילה, כנ״ל. והקו וחצי המאירים מחצות לילה והלאה, מבאר להלן (באות קמ״ח)."],[1,"ר׳ יוסי אמר וכו׳:","ר׳ יוסי מפרש דבריו של ר״י, ואומר כשמאיר היום, כל אלו בעלי יבבה, דהיינו אותם הנמשכים מקו שמאל שמרוב הדינים שבו הם מיבבים תמיד, משבחים בדברי תשבחות כנגד בוקר הזה, שהוא אור החסדים, כי כשנתעורר בקר הזה, כלם מתבשמים והדין נשקט, ואומרים תשבחות. ז״ש ברן יחד ככבי בקר ויריעו כל בני אלקים. ובעת ההיא נמצאות שמחה וברכות בעולם, שהקב״ה מעורר את אברהם, שה״ס החסד, להחיותו ולהשתעשע עמו, ומשליטו בעולם. שה״ס ממשלת היום. ומאין לנו שבקר הזה הוא של אברהם, דהיינו חסד, הוא משכתוב, וישכם אברהם בבקר."],[2,"בההוא זמנא דבין וכו׳:","בזמן ההוא של בין הערבים, כל אלו אלף ות״ק וצ׳ אלף רבוא הנמשכים אז, הם נקראים בעלי יללה, מחמת שנמשכים מקו וחצי דצד שמאל, שמשם נמשכים דינים, כנ״ל, וע״כ הם מיללים, כי אינם יכולים לסבול הדינים האלו. ומזמרים באותה שעה. ומריבה שורה בעולם. ושעה ההיא, היא ההתעוררות שעורר הקב״ה את יצחק, שהוא קו השמאל דז״א, והוא קם ודן את הרשעים, העוברים על דברי תורה, וז׳ נהרות אש, כנגד חג״ת נהי״מ נמשכים ויוצאים ושורים על ראשיהם של הרשעים ושלהבת גחלי אש מתעוררת מלמעלה למטה. ואז, אברהם, שה״ס החסד, שב למקומו. דהיינו שהחסד חוזר לשורשו ונעלם מן התחתונים, כש״א, ואברהם שב למקומו. והיום נפנה ורשעי גיהנם צועקים ואומרים, אוי לנו כי פנה היום כי ינטו צללי ערב. ובאותה שעה צריך אדם להזהר בתפלת המנחה."],[3,"בזמנא דמטי ליליא וכו׳:","בזמן שהגיע הלילה, אלו האלף וחמש מאות וארבעים ושמונה, הנמשכים אז, הם נקראים, מחוץ לפרוכת, ואומרים שירה. אז מתעוררים הדינים שלמטה, דהיינו הדינים של המלכות, והולכים ומשוטטים בעולם. ואלו אומרים שירה עד שנחלק הלילה, דהיינו משמרה וחצי משמרה (כנ״ל בהסולם אות קמ\"ה) אחר שנחלק הלילה מזדמנים כל האחרים יחד, דהיינו אותם של המשמרה וחצי המשמרה, שלאחר חצות לילה, ואומרים תהלות. כש״א תהלות ה׳ יבשרו. ר׳ יהודה אמר כשהרצון נמצא בבקר, אז תהלות ה׳ יספרו. ולא בלילה."],[3,"","פירוש. תהלות, פירושו אורות, מלשון \u0003בהלו\u0004 נרו עלי ראשי (איוב כ״ט) ור׳ יוסי סבר שהוא אור החכמה המתגלה אחר חצות לילה, ואז נאמר תהלות ה׳ יבשרו. ור׳ יהודה סבר, שהוא אור דחסדים המתגלה בבקר, ואז נאמר תהלות ה׳ יבשרו."],[4,"ר׳ יוסי אמר וכו׳:","רי״א, אחר שנתעורר רוח צפון בחצות הלילה והולך לו, שה״ס הארת החכמה שבצד שמאל, הנקרא רוח צפת, אז תהלות מבשרים, עד שיבא הבקר, ומתעורר בקר הזה, שהוא אור החסדים, ואז שמחה וברכות נמצאות בעולם. והן אינן נקראות תהלות. כנ״ל בדבור הסמוך."],[5,"תאנא אמר ר׳ אבא וכו׳:","למדנו, אר״א, כולם, כל מה שאמר ר׳ יהודה ור׳ יוסי כך הוא, ולמעלה מהם, יש שלשה שרים. ומפרש, באותה שעה שנתעורר בקר הזה, ומתעוררים התשבחות של כל אלו אלף וחמש מאות וחמשים רבוא, נתמנה עליהם ממונה אחד, ששמו \u0003הימן,\u0004 שהוא כנגד הימן שלמטה המובא בתהלים. ותחת ידו שרים ממונים עליהם לתקן השירה. \u0003הימן,\u0004 הוא אותיות ימין, כי הוא נמשך מימין."],[6,"בההיא שעתא דאתער וכו׳:","בשעה ההיא שנתעורר הזמן של בין הערבים, ומזמרים כל אלו אלף וחמש מאות ותשעים אלף רבוא בעלי היללה, נתמנה עליהם ממונה אחד, ושמו \u0003ידותון,\u0004 כנגד ידותון שלמטה המובא בתהלים. ותחת ידו שרים ממונים עליהם לתקן הזמר ההוא, כמש״א, זמיר עריצים. שפירושו כריתת הרשעים, אף הזמירות שלהם מכלים את הרשעים. \u0003ידותון,\u0004 הוא אותיות, יד, וידון, שזה מורה שהוא מיד שמאל, ודינים נמשכים ממנו."],[7,"בההיא שעתא דמטי וכו׳:","בשעה ההיא שבא הלילה, מתעוררים כל אלו המלאכים שהם מחוץ לפרוכת, דהיינו שנמשכים מאחורים של המלכות, ומחיצוניות שלה, אז שוקט הכל, ופתיחת פתח לא נמצא, והדינים שלמטה, דהיינו של המלכות, שהיא למטה מכל הספירות, מתעוררים, כולם, דהיינו כל הדינים, נתמנו יחד, אלו על אלו, עד שנחלק הלילה. אחר שנחלק הלילה, ומתאספים כל המלאכים הנמשכים מקו אמצעי (כנ״ל ויחי דף קל״ח ד\"ה וג') נתמנה עליהם ממונה אחד, ומאסף לכל המחנות, כש״א מאסף לכל המחנות וגו', ושמו \u0003אסף,\u0004 כנגד אסף ההוא שלמטה, המובא בתהלים, ותחת ידו כל השרים והממונים ומבשרי תהלות. פירוש. המלכות נקראת אסף, מפני שהארות כל הספירות מתאספות בה, שהיא מקבלת מכולם. ולהיות השר ההוא נמשך ממלכות ע״כ נקרא שמו אסף."],[8,"עד דאתי צפרא וכו׳:","עד שבא הבקר. כיון שבא הבוקר, קם נער ההוא, שהוא מטטרון, היונק משדי אמו, שהיא המלכות, לטהר אותם, דהיינו להמלאכים שבלילה, ונכנס לשמש, כשנתעורר הבוקר אז היא שעת רצון, שהמלכה מספרת עם המלך, שהוא ז״א. והמלך מושיט מעצמו חוט אחד של ברכות, דהיינו חסדים, ופורש על המלכה, ועל אלו המתחברים עמה. מי הם המתחברים עמה. היינו אותם שעוסקים בתורה בלילה, בעת שנחלק."]],[[0,"","וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי ה' וְכִפֶּר עָלָיו. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים נ) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבאוֹ. לָמַדְנוּ, אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשִּׁים רִבּוֹא בַּעֲלֵי שִׁירָה מְזַמְּרִים לַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁמֵּאִיר הַיּוֹם. וְאֶלֶף וַחֲמֵשׁ מֵאוֹת וְאַרְבָּעִים וּשְׁמוֹנָה בַּצָּהֳרָיִם. וְאֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בְּאוֹתָהּ שָׁעָה שֶׁנִּקְרֵאת בֵּין הָעַרְבַּיִם."],[1,"","רַבִּי יוֹסֵי אָמַר, כְּשֶׁמֵּאִיר הַיּוֹם, כָּל אוֹתָם בַּעֲלֵי יְבָבָה מְשַׁבְּחִים בְּדִבְרֵי תִשְׁבָּחוֹת כְּנֶגֶד הַבֹּקֶר הַזֶּה. (כשמתעורר) שֶׁכְּשֶׁמִּתְעוֹרֵר הַבֹּקֶר הַזֶּה, כֻּלָּם מִתְבַּשְּׂמִים, וְהַדִּין שׁוֹכֵךְ, וְאוֹמְרִים תִּשְׁבָּחוֹת. זֶהוּ שֶׁכָּתוּב (איובלט) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. וְאוֹתוֹ זְמַן (אמונה) שִׂמְחָה וּבְרָכוֹת נִמְצָאִים בָּעוֹלָם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵעִיר אֶת אַבְרָהָם לְהַחֲיוֹתוֹ, וּמִשְׁתַּעֲשֵׁעַ עִמּוֹ וּמַשְׁלִיטוֹ בָעוֹלָם. וּמִנַּיִן לָנוּ שֶׁהַבֹּקֶר הַזֶּה הוּא שֶׁל אַבְרָהָם? שֶׁכָּתוּב (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר."],[2,"","בְּאוֹתוֹ זְמַן שֶׁל בֵּין הָעַרְבַּיִם, כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בַּעֲלֵי יְלָלָה נִקְרָאִים, וּמְזַמְּרִים בְּאוֹתָהּ שָׁעָה, וְהַקְּטָטָה שׁוֹרָה בָּעוֹלָם. וְאוֹתָהּ שָׁעָה הַהִתְעוֹרְרוּת שֶׁמֵּעִיר הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִצְחָק, וְעוֹמֵד וְדָן אֶת הָרְשָׁעִים שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, וְשִׁבְעָה נַהֲרוֹת אֵשׁ זוֹרְמִים וְיוֹצְאִים וְחָלִים עַל רָאשֵׁי הָרְשָׁעִים, וְשַׁלְהָבוֹת גֶּחָלִים שֶׁל אֵשׁ מִתְעוֹרְרוֹת מִמַּעְלָה לְמַטָּה. וְאָז שָׁב אַבְרָהָם לִמְקוֹמוֹ, כְּמוֹ שֶׁנֶּאֱמַר וְאַבְרָהָם שָׁב לִמְקוֹמוֹ. וְהַיּוֹם פּוֹנֶה, וְרִשְׁעֵי הַגֵּיהִנֹּם צוֹוְחִים וְאוֹמְרִים: (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם כִּי יִנָּטוּ צִלְלֵי עָרֶב. וְאוֹתָהּ שָׁעָה צָרִיךְ אָדָם לְהִזָּהֵר בִּתְפִלַּת הַמִּנְחָה."],[3,"","בִּזְמַן שֶׁמַּגִּיעַ הַלַּיְלָה, אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְאַרְבָּעִים וּשְׁמוֹנָה נִקְרָאִים מִחוּץ לַפָּרֹכֶת וְאוֹמְרִים שִׁירָה. אָז מִתְעוֹרְרִים הַדִּינִים שֶׁלְּמַטָּה, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְאֵלֶּה אוֹמְרִים שִׁירָה עַד שֶׁנֶּחֱלָק הַלַּיְלָה מִשְׁמֶרֶת וָחֵצִי. אַחַר שֶׁנֶּחֱלָק הַלַּיְלָה, מִזְדַּמְּנִים כָּל הָאֲחֵרִים כְּאֶחָד וְאוֹמְרִים תְּהִלּוֹת, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ס) וּתְהִלּוֹת ה' יְבַשֵּׂרוּ. רַבִּי יְהוּדָה אָמַר, כְּשֶׁנִּמְצָא רָצוֹן בַּבֹּקֶר, תְּהִלּוֹת ה' מְבַשְּׂרִים."],[4,"","רַבִּי יוֹסֵי אָמַר, אַחַר שֶׁרוּחַ הַצָּפוֹן הִתְעוֹרְרָה בַּחֲצוֹת הַלַּיְלָה וְהָלְכָה לָהּ, מְבַשְּׂרִים תְּהִלּוֹת עַד שֶׁיָּבֹא הַבֹּקֶר, וּמִתְעוֹרֵר הַבֹּקֶר הַזֶּה, וְאָז שִׂמְחָה וּבְרָכוֹת נִמְצָאִים בָּעוֹלָם."],[5,"","לָמַדְנוּ, אָמַר רַבִּי אַבָּא, כֻּלָּם כָּךְ, וּמֵעַל כֻּלָּם שְׁלֹשָׁה שָׂרִים. בְּאוֹתָהּ שָׁעָה שֶׁמִּתְעוֹרֵר הַבֹּקֶר הַזֶּה וּמְעוֹרְרִים תִּשְׁבָּחוֹת עַל כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וַחֲמִשִּׁים רִבּוֹא, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד, וּשְׁמוֹ הֵימָן, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ שָׂרִים מְמֻנִּים עֲלֵיהֶם לְתַקֵּן שִׁיר."],[6,"","בְּאוֹתָהּ שָׁעָה שֶׁמִּתְעוֹרֵר זְמַן שֶׁל בֵּין הָעַרְבַּיִם וּמְזַמְּרִים כָּל אוֹתָם אֶלֶף וַחֲמֵשׁ מֵאוֹת וְתִשְׁעִים אֶלֶף רִבּוֹא בַּעֲלֵי הַיְלָלָה, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד, וּשְׁמוֹ יְדוּתוּן, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ מְמֻנִּים עֲלֵיהֶם שָׂרִים לְתַקֵּן אוֹתוֹ הַזֶּמֶר, כְּמוֹ שֶׁנֶּאֱמַר (שם כה) זְמִיר עָרִיצִים."],[7,"","בְּאוֹתָהּ שָׁעָה שֶׁמַּגִּיעַ הַלַּיְלָה, מִתְעוֹרְרִים כָּל אוֹתָם שֶׁמִּחוּץ לַפָּרֹכֶת, וְאָז הַכֹּל שׁוֹכֵךְ, וּפֶתַח לֹא נִמְצָא, וְהַדִּינִים שֶׁלְּמַטָּה מִתְעוֹרְרִים, כֻּלָּם מִתְמַנִּים כְּאֶחָד אֵלֶּה עַל אֵלֶּה, עַד שֶׁנֶּחֱלָק הַלַּיְלָה. אַחַר שֶׁנֶּחֱלָק הַלַּיְלָה וְכֻלָּם מִתְכַּנְּסִים, מִתְמַנֶּה עֲלֵיהֶם מְמֻנֶּה אֶחָד וּמְכַנֵּס אֶת כָּל הַמַּחֲנוֹת, כְּמוֹ שֶׁנֶּאֱמַר (במדבר י) מְאַסֵּף לְכָל הַמַּחֲנוֹת וְגוֹ', וּשְׁמוֹ אָסָף, כְּנֶגֶד שֶׁלְּמַטָּה, וְתַחַת יָדוֹ כָּל אוֹתָם שָׂרִים מְמֻנִּים וּמְבַשְּׂרִים תְּהִלּוֹת."],[8,"","עֵד שֶׁבָּא הַבֹּקֶר. כֵּיוָן שֶׁבָּא הַבֹּקֶר, קָם אוֹתוֹ נַעַ\"ר וְיוֹנֵק מִשְּׁדֵי אִמּוֹ לְטַהֵר אוֹתָם, וְנִכְנָס לַשֶּׁמֶשׁ. כְּשֶׁמִּתְעוֹרֵר הַבֹּקֶר, אָז הִיא עֵת רָצוֹן שֶׁמְּדַבֶּרֶת הַגְּבִירָה עִם הַמֶּלֶךְ, וְהַמֶּלֶךְ מוֹשֵׁךְ מִמֶּנּוּ חוּט אֶחָד שֶׁל בְּרָכוֹת וּפוֹרֵס עַל הַגְּבִירָה וְעַל אוֹתָם שֶׁמִּזְדַּוְּגִים עִמָּהּ. מִי הֵם שֶׁמִּזְדַּוְּגִים עִמָּהּ? אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בַּלַּיְלָה, כְּשֶׁנֶּחֱלָק."]]],[["רִבִּי שִׁמְעוֹן אָמַר, זַכָּאָה חוּלָקֵיהּ מַאן דְּאָתֵי עִם מַטְרוֹנִיתָא, בְּשַׁעֲתָא דְּאָתַת לְקַבְּלָא אַנְפֵּי מַלְכָּא, לְאִשְׁתָּעֵי בֵּיהּ. וְאִשְׁתְּכַח עִמָּהּ. בְּשַׁעֲתָא דְּאוֹשִׁיט מַלְכָּא יְמִינָא, לְקַבְּלָא לְמַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, (תהילים קל״ט:ט׳) אֶשָּׂא כַּנְפֵי שָׁחַר אֶשְׁכְּנָה בְּאַחֲרִית יָם. מַאי אַחֲרִית יָם. הַהִיא שַׁעֲתָא אַחֲרִית דְּהַהוּא יַם הוּא. דְּכַד אִתְפְּלַג, שֵׁירוּתָא הֲוָה, וְדִינָא הֲוָה, וְהַשְׁתָּא אַחֲרִית הוּא דִּילָהּ, דְּמִסְתַּלְּקִין דִּינָהָא. וְעָאלַת בְּגַדְפּוֹי דְּמַלְכָּא, הִיא וְכָל אִינּוּן דְּמִזְדַּוְּוגִין לֵהּ, הֲדָא הוּא דִכְתִיב אֶשְׁכְּנָה בְּאַחֲרִית יָם.","וְתָאנָא, כָּל אִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא בְּשַׁעֲתָא דְּאִתְפְּלִיג לֵילְיָא. אִשְׁתְּתַּף בִּשְׁכִינְתָּא. וְכַד אָתֵי צַפְרָא, וּמַטְרוֹנִיתָא אִתְחַבְּרַת עִם מַלְכָּא, הוּא אִשְׁתְּכַח עִמָּהּ עִם מַלְכָּא. וּמַלְכָּא פְּרֵיס עַל כֻּלְּהוּ גַּדְפּוֹי, הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוְּה יְיָ' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי וְגוֹ'.","תָּאנָא, בְּהַהִיא שַׁעֲתָא, אֲבָהָן מִזְדַּמְּנִין בְּמַטְרוֹנִיתָא, וְקַדְּמִין לְאִשְׁתָּעֵי בַּהֲדָהּ, וּלְאִתְחַבְּרָא עִמָּהּ. וְקוּדְשָׁא בְּרִיךְ הוּא מַלִּיל עִמָּהּ בְּהוּ. וְהוּא קָארֵי לָהּ לְפָרְסָא לָהּ גַּדְפּוֹי, הֲדָא הוּא דִכְתִיב, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִקְרָא אָרֶץ וְגוֹ'. אֵל: דָּא נְהִירוּ דְּחָכְמְתָא, וְאִקְרֵי חֶסֶד. אֱלֹהִים: דָּא גְּבוּרָה. יְדִֹוִ\"ד: דָא שְׁלִימוּ דְּכַלָּא, רַחֲמֵי. וְעַל דָא, דִּבֶּר וַיִקְרָא אָרֶץ וְגוֹ'.","רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵיהּ דְּרַבִּי שִׁמְעוֹן אֲבוֹי, אָמַר לֵיהּ, הָא תָּנֵינָן אֱלֹהִים בְּכָל אֲתַר דִּינָא הוּא. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. אִית אֲתַר דְּאִקְרֵי אֱלֹהִים, כְּגוֹן (בראשית טו) אֲדֹנָ\"י יִהוְֹ\"ה. אֲמַאי אִקְרֵי אֱלֹהִים, וְהָא אַתְוָון רַחֲמֵי אִינּוּן בְּכָל אֲתַר.","אָמַר לֵיהּ, הָכִי הוּא כְּתִיב בַּקְּרָא, דִּכְתִּיב, (דברים ד׳:ל״ט) וְיָדַעְתָּ הַיּוֹם וְהֲשֵׁבוֹתָ אֶל לְבָבֶךָ כִּי יְיָ' הוּא הָאֱלֹהִים, וּכְתִיב (מלכים א י״ח:ל״ט-מ׳) יְיָ' הוּא הָאֱלֹהִים. אָמַר לֵיהּ מִלָּה דָּא יְדַעְנָא, דְּבַאֲתַר דְּאִית דִּינָא, אִית רַחֲמֵי. וּלְזִמְנָא, בַּאֲתַר דְּאִית רַחֲמֵי, אִית דִּינָא, אָמַר לֵיהּ תָּא חַזֵי דְּהָכִי הוּא, יְדוָֹ\"ד בְּכָל אֲתַר רַחֲמֵי. וּבְשַׁעֲתָא דִּמְהַפְּכֵי חַיָּיבַיָּא רַחֲמֵי לְדִינָא, כְּדֵין כְּתִיב יִהוְֹ\"ה, וְקָרֵינָן לֵיהּ אֱלֹהִים.","אֲבָל תָּא חֲזֵי רָזָא דְּמִלָּה, ג' דַּרְגִּין אִינּוּן, וְכָל דַּרְגָּא וְדַרְגָּא בִּלְחוֹדוֹי, וְאַף עַל גַּב דְּכֹלָּא חַד, וּמִתְקַשְּׁרֵי בְּחַד, וְלָא מִתְפָּרְשֵׁי דָּא מִן דָּא. תָּא חֲזֵי, כֻּלְּהוּ נְטִיעָן, וְכָל אִינּוּן בּוּצִינִין דְּמִתְלַהֲטִין כֻּלְּהוּ נְהִירִין וּמִתְלַהֲטָן וּמִשְׁתַקְיָין וּמִתְבָּרְכָאן, מֵהַהוּא נַהֲרָא דְּנָגִיד וְנָפִיק, דְּכֹלָּא כָּלִיל בֵּיהּ, (תרי נוסחי) וּכְלָלָא דְּכֹלָּא בֵּיהּ.","וְהַאי נַהֲרָא אִתְקְרֵי אֵ\"ם לְגִנְתָּא, וְעֵילָּא מִגִּנְתָּא, בְּגִין דְּעֵדֶן מִשְׁתַּתֵּף בַּהֲדָהּ, וְלָא פָּרִישׁ (ס\"א ע\"ב) מִנָּהּ. וּבְגִין כַּךְ, כָּל מַבּוּעִין נָפְקִין וְנַגְדִּין וְאִשְׁתַקְיָין לְכָל עִיבָר. וּפַתְחִין בָּהּ פְּתִיחָן, וְעַל דָּא רַחֲמֵי מִנָּהּ מִשְׁתַּכְּחִין, וְרַחֲמִין פְּתִיחִין בָּהּ.","וּבְגִין דְּקָרֵינָן לָהּ אֵם, נוּקְבָּא גְּבוּרָה, וְדִינָא מִנָּהּ נָפִיק. אִקְרֵי רַחֲמֵי בִּלְחוֹדָהָא, הָא מִסִּטְרָהָא דִּינִין מִתְעָרִין. וּבְגִין כַּךְ כְּתִיב בְּרַחֲמֵי, וְנָקוּד בְּדִינָא. אַתְוָון בְּרַחֲמֵי, וְאִתְנְגִיד דִּינָא מִסִּטְרָהָא, כְּגַוְונָא דָּא יְהֶ\"וִֹה, הַאי דַּרְגָּא חַד.","דַּרְגָּא תִּנְיָינָא, מִסִּטְרָא דְּהַאי קַדְמָאָה, נָפִיק וְאִתְּעַר דַּרְגָּא אָחֳרָא אִקְרֵי גְּבוּרָה, וְהַאי אִקְרֵי אֱלֹהִים, בְּאִלֵּין אַתְוָון מַמָּשׁ. וְשִׁירוּתָא (חד) מִזְּעֵיר אַנְפִּין הוּא, וּבֵיהּ אִתְאֲחִיד. וּבְגִין דְּאִתְאֲחִיד (האי) בְּהַאי, כְּתִיב יְיָ' הָאֱלֹהִים, כִּי יְיָ' הוּא הָאֱלֹהִים, בְּאִלֵּין אַתְוָון, וְהוּא חַד, וְדָא הוּא דַּרְגָּא תִּנְיָינָא.","דַּרְגָּא תְּלִיתָאָה, צֶדֶק. כִּתְרָא בַּתְרָאָה, הַאי בֵּי דִּינָא דְּמַלְכָּא. וְתָאנָא אֲדֹנָ\"י הָכִי כְּתִיב, וְהָכִי אִקְרֵי, וּכְּנֶסֶת יִשְׂרָאֵל בְּהַאי שְׁמָא אִתְקְרֵי. וְהַאי שְׁמָא בַּאֲתַר דָּא אִשְׁתְּלִים. וְאִלֵּין אִינּוּן ג' דַּרְגִּין, דְּאִקְרוּן בִּשְׁמֵהוֹן דְּדִינָא. וְכֹלָּא מִתְקַשָּׁר חַד בְּחַד בְּלָא פִּרוּדָא, כְּמָה דְּאוֹקִימְנָא.","אָמַר לֵיהּ, אִי נִיחָא קַמֵּיהּ דְּאַבָּא, הָא שְׁמַעְנָא בְּהַאי, (ח\"י ע\"א) דִּכְתִּיב, (שמות ג׳:י״ד) אֶהְיֶה אֲשֶׁר אֶהְיֶה, וְלָא קַיְימָא בֵּיהּ. אָמַר לֵיהּ אֶלְעָזָר בְּרִי, הָא אוֹקְמוּהָ חַבְרַיָּיא, וְהַשְׁתָּא בְּחַד מִלָּה אִתְקְשַׁר כֹּלָּא."],[[0,"רבי שמעון אמר וכו׳:","רש״א, אשרי חלקו, מי שבא עם המלכה בשעה שבאה לקבל פני המלך, ז״א, לספר עמו, ונמצא עמה בשעה שהמלך מושיט ימינו, שהוא אור החסדים, לקבל את המלכה. ז״ש, אשא כנפי שחר אשכנה באחרית ים. מהו אחרית ים. הוא שעה ההיא, בבקר, כשמקבלת פני ז״א, היא \u0003אחרית\u0004 של \u0003ים\u0004 ההוא, שהוא מלכות. כי כשנחלק הלילה היא התחלה שלה, שאז מתחלת להאיר, והוא דין, כל עוד שהוא לילה, מטעם חסרון חסדים להלביש החכמה שלה, ועתה, שהגיע הבקר, היא \u0003אחרית\u0004 שלה, כי דיניה מסתלקים ונכנסת תחת כנפי המלך, שהוא ז״א, כלומר שמתלבשת בחסדים שלו, היא, וכל אלו הצדיקים המתחברים עמה. ז״ש, אשכנה באחרית ים."],[1,"ותאנא, כל אינון וכו׳:","ולמדנו, כל אלו שעוסקים בתורה בשעה שנחלק הלילה, הם מתחברים עם השכינה, וכשבא הבוקר, והמלכה, דהיינו השכינה, מתחברת עם המלך, שהוא ז״א, הם נמצאים עם המלך, והמלך פורש כנפיו על כולם. ז״ש, יומם יצוה ה׳ חסדו ובלילה שירה עמי וגו'."],[2,"תאנא, בהאי שעתא וכו׳:","למדנו, בשעה ההיא, שבא הבקר, האבות, שהם חג״ת דז״א, מזדמנים עם המלכה, ומקדימים לספר עמה ולהתחבר עמה. ובהם הקב״ה, ז״א, מדבר עמה, והוא קורא לה לפרוש עליה כנפיו. ז״ש, מזמור לאסף אל אלקים ה׳ דבר ויקרא ארץ וגו'. \u0003אל,\u0004 זהו אור החכמה, ונקרא חסד, והוא קו ימין. דהיינו חסד העולה להיות חכמה. \u0003אלקים,\u0004 זהו גבורה, דהיינו קו שמאל. \u0003הויה,\u0004 זהו שלמות הכל, רחמים. דהיינו קו האמצעי המשלים לימין ושמאל. ועל כן, הקו אמצעי. דבר ויקרא ארץ, שהיא מלכות. דהיינו שמשלים המלכות."],[3,"רבי אלעזר הוה וכו׳:","ר״א היה יושב לפני ר״ש אביו, אמר לו, הרי למדנו, שהשם אלקים בכל מקום הוא דין. השם הויה, יש מקום שנקרא אלקים, דהיינו שנקוד בניקוד אלקים, דהיינו אדני הוי״ה, שהשם הויה נקוד בניקוד אלקים. ושואל, למה נקרא אלקים, והרי האותיות, שהן הויה, הן רחמים בכל מקום."],[4,"אמר ליה הכי וכו׳:","א״ל כך הוא כתוב במקרא, שכתוב, וידעת היום והשבות אל לבבך כי הויה הוא האלקים. וכתוב, הויה הוא האלקים. אמר לו דבר זה ידעתי שבמקום שיש דין יש רחמים, ולפעמים במקום שיש רחמים יש דין. וע״כ אוה״כ הוי״ה הוא האלקים. אמר לו, בוא וראה שכך הוא, כי הויה בכל מקום הוא רחמים, ובשעה שהרשעים מהפכים הרחמים לדין, אז כתוב הויה, וקורים אותו אלקים."],[5,"אבל ת״ח רזא וכו׳:","אבל בוא וראה סוד הדבר. ג׳ מדרגות הן, וכל מדרגה ומדרגה היא בפני עצמה, אע״פ שהכל אחד, ומתקשרים כאחד, ואינן נפרדות זו מזו. בוא וראה, כל הנטיעות, דהיינו הספירות, וכל אלו הנרות, דהיינו ספירות המלכות, המכונה מאורי אש, כולם מאירים ולוהטים ומושקים ומתברכים מאותו הנהר הנמשך ויוצא, שהוא בינה, שהכל כלול בו, כי כל המוחין באים ממנה, וכלל הכל בו."],[6,"והאי נהרא אתקרי וכו׳:","והנהר ההוא נקרא \u0003אם\u0004 אל \u0003הגן,\u0004 שהוא מלכות, כי בינה נקראת אם, כמ״ש כי \u0003אם\u0004 לבינה תקרא, שהוא למעלה מן הגן. ונקראת אם, משום ש \u0003עדן,\u0004 שהוא חכמה מתחבר עמה, ואינו נפרד ממנה, ומשום זה כל המבועים של המוחין, יוצאים ונמשכים ממנה ומשקים לכל צד. הן לימין והן לשמאל, ופותחים בה פתחים, וע״כ הרחמים נמצאים ממנה שהוא קו האמצעי, והרחמים נפתחים בה. כי ראשית פתיחת קו האמצעי, להכריע וליחד ימין ושמאל, שהוא שלמות כולם, מתחלת בבינה."],[7,"ובגין דקרינן לה אם וכו׳:","ומשום זה שקוראים אותה, את הבינה, \u0003אם,\u0004 היא נוקבא, וגבורה, ודין יוצא ממנה. וע״כ היא נקראת רחמים בפני עצמה, דהיינו מבחינת עצמותה, אבל מצדה מתעוררים דינים. וע״כ, השם של הבינה, כתוב ברחמים, דהיינו באותיות \u0003הויה\u0004 המורה על רחמים, ומנוקד בדין, דהיינו שד׳ אותיות הויה שלה, מנוקדות כמו הניקוד שבשם אלהים. ונמצאות אותיות השם שהן ברחמים, ודינים נמשכים מצדה, המרומז בנקודות השם, כעין זה יְהֶ״וֹה, זו היא מדרגה אחת."],[7,"","ביאור המאמר. נודע, שחכמה ובינה מכונים בכל מקום אבא ואמא, וצריכים להבין טעם הדבר. והענין הוא, כי המלכות, שממנה נבראו העולמות, הנה מבחינתה עצמה אינה ראויה לקבל אור העליון, כי הצמצום א׳ והמסך רוכב עליה, שלא תקבל אור העליון. וכדי לקיים העולמות שיוכלו לקבל אור העליון, העלתה הבינה אליה את המלכות שעי״ז קבלה הבינה לתוכה את הדינים של המלכות, ונסתלקו ממנה הג\"ר, שמחמת זה קבלה המלכות שבבינה בחינת הכלים והקטנות של הבינה, ואח״כ כשירדה המלכות מן הבינה וחזרו אליה הג״ר, קיבלה המלכות המוחין דג״ר של הבינה. ומן המלכות מקבלים כל העולמות (ועי׳ לעיל ב״א דף ז׳ ד״ה וכבר). ונמצא שהבינה קבלה אליה את המלכות ודיניה. ומיעטה את עצמה, כדי שתוכל המלכות לקבל מוחין וקיום. וענין עלית המלכות לקבלת המוחין מבינה, נבחן כמו עיבור ולידה (כנ״ל ב״א מ״ב ד״ה פירוש. וכמ״ש בתרומה אות תר״ח בהסולם ע״ש) וע״כ נעשה בינה אל המלכות כמו אם, והמלכות היא בתה. ומתוך שחכמה ובינה הם בזווג, ואין בינה בלי חכמה, נבחן ג״כ החכמה לאב אל המלכות."],[7,"","וזה אמרו (באות ק״ס), \u0003והאי נהרא אתקרי אם לגנתא,\u0004 שהבינה הנקראת נהר נעשתה \u0003אם\u0004 אל המלכות. ונודע שמטעם עלית המלכות לבינה, יצאו בבינה ג׳ קוין, בסוד ג׳ נקודות חולם שורק חירק, שה״ס ג׳ זריעות, דהיינו ג׳ בחינות דינים (כמ״ש לעיל ב״א ט״ו ד״ה ההוא ע״ש) שחולם ה״ס קו ימין ושורק קו שמאל וחירק הוא קו האמצעי. וז״ש, \u0003ובגין כך כל מבועין נפקין ונגדין,\u0004 דהיינו שורשי המוחין, \u0003ואשתקיין לכל עיבר,\u0004 דהיינו לקו ימין ולקו שמאל, \u0003ועל דא רחמי מנה משמכחין,\u0004 שה״ס קו האמצעי, הרי שנעשה ג׳ בחינות דינין בבינה מג׳ קוין, שכל זה עלתה לה מטעם שהעלתה לתוכה את המלכות, כי מצדה עצמה היא בסוד, כי חפץ חסד הוא, בלי שום דין. וז״ש, \u0003ובגין דקרינן לה אם,\u0004 דהיינו שהעלתה לתוכה את המלכות, היא \u0003נוקבא, גבורה, ודינא מנה נפיק,\u0004 שמחמת שהמלכות היא נוקבא נעשתה גם הבינה נוקבא, וכן מחמת שהמלכות היא גבורה נעשתה גם הבינה לבחינת גבורה, ודינים יוצאים ממנה, דהיינו שנעשו בה ג׳ זריעות דחולם שורק חירק, שמהם יוצאים דינים, וז״ש, \u0003אקרי רחמי בלחודהא,\u0004 שלפי עצמה היא כולה רחמים בלי שום דין, כי היא בבחינת, כי חפץ חסד הוא, \u0003הא מסטרהא דינין מתערין,\u0004 מטעם שקבלה לתוכה את המלכות כנ״ל. \u0003ובג״כ כתיב ברחמי,\u0004 באותיות \u0003הויה,\u0004 שמורה על עצמותה שהיא רחמים, \u0003ונקוד בדינא,\u0004 שמורה על הדינים שבה מטעם החיבור עם המלכות, ע״כ הניקוד שלה כמו השם שבמלכות, שהוא אלקים. דהיינו בחטף סגול חולם וחירק, חטף סגול תחת ה \u0003י׳,\u0004 וחולם על \u0003ה׳,\u0004 וחירק תחת ה \u0003ו׳.\u0004"],[8,"דרגא תנינא וכו׳:","מדרגה השניה, מצד מדרגה הראשונה, שהיא בינה, יוצאת ומתעוררת מדרגה אחרת שנקראת גבורה. שהיא קו שמאל דז״א, וזה נקרא אלקים, ולא בנקודות בלבד, כמו בינה, אלא באותיות אלה ממש. והתחלתו היא מזעיר אנפין, דהיינו חסד דז״א, שמשם נמשך גבורה, ובו הוא נכלל, כי קו שמאל דז״א נכלל בקו ימין דז״א, שהוא חסד, ומשום שמתאחד בזה, בחסד, ע״כ כתוב, הויה הוא האלקים, כי \u0003הויה,\u0004 שהוא חסד, הוא האלקים, שהוא גבורה, וכאן, לא רק בנקודות של אלקים, כמ״ש בבינה, אלא כלול בהאותיות דאלקים, והם אחד. להיותם כלולים זה בזה, וזו היא מדרגה השניה."],[9,"דרגא תליתאה וכו׳:","מדרגה השלישית, הוא צדק, דהיינו מלכות, שהיא ספירה האחרונה, וזו היא בית דין של המלך, של ז״א. ולמדנו שהשם אדני כתוב כך ונקרא כך, כנסת ישראל, שהיא המלכות נקראת בשם הזה, אבל השם של ז״א כתוב הויה ונקרא אדני, ושם הזה נשלם במקום הזה, במלכות. ואלו הן ג׳ מדרגות הנקראות בשמות של דין, שמדרגת הבינה, נקראת הויה בניקוד אלקים. ומדרגת הגבורה, נקראת גם בהאותיות של אלקים, ומדרגת המלכות נקראת אדני, שהם ג׳ שמות דין, מטעם כי המדובר היא כאן בקו שמאל, שהוא דין, ששורשו היא בינה, וע״כ הוא מרומז רק \u0003בנקודות דאלקים,\u0004 וממנה נמשך לקו שמאל דז״א, ושם הוא במציאות ממש, אלא שכלול בימין. וע״כ הוא סוד \u0003אלקים גם בהאותיות.\u0004 וממנו נמשך למלכות, שהיא נבנית כולה מקו שמאל. וע״כ נקראת \u0003אדני.\u0004 שהוא אותיות דין במפורש. וכולן מתקשרות אחת באחת בלא פירוד, כמו שהעמדנו."],[10,"א״ל אי ניחא וכו׳:","אמר לו, אם הוא לרצון לפני אבי, הרי שמעתי בזה שכתוב, אהיה אשר אהיה, ואיני עומד בו, שאיני מבין פירושו. אמר לו, אלעזר בני, הרי העמידוהו החברים. ועתה בדבר אחד מתקשר הכל."]],[[0,"","רַבִּי שִׁמְעוֹן אָמַר, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁבָּא עִם הַגְּבִירָה בְּשָׁעָה שֶׁבָּאָה לְקַבֵּל אֶת פְּנֵי הַמֶּלֶךְ לְדַבֵּר עִמָּהּ, וְנִמְצָא עִמָּהּ, בְּשָׁעָה שֶׁהַמֶּלֶךְ מוֹשִׁיט אֶת יְמִינוֹ לְקַבֵּל אֶת הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב (תהלים קלט) אֶשָּׂא כַנְפֵי שָׁחַר אֶשְׁכְּנָה בְּאַחֲרִית יָם. מִי אַחֲרִית הַיָּם? אוֹתָהּ שָׁעָה אַחֲרִית שֶׁל אוֹתוֹ יָם הִיא. שֶׁכְּשֶׁנֶּחֱלָק, הָיְתָה רֵאשִׁית, וְהָיָה דִין, וְעַכְשָׁו הָאַחֲרִית הוּא שֶׁלָּהּ, שֶׁמִּסְתַּלְּקִים דִּינֶיהָ, וְנִכְנֶסֶת לְכַנְפֵי הַמֶּלֶךְ הִיא וְכָל אוֹתָם שֶׁמִּזְדַּוְּגִים עִמָּהּ. זֶהוּ שֶׁכָּתוּב אֶשְׁכְּנָה בְּאַחֲרִית יָם."],[1,"","וְלָמַדְנוּ, כָּל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה בְּשָׁעָה שֶׁנֶּחֱלָק הַלַּיְלָה, מִשְׁתַּתְּפִים עִם הַשְּׁכִינָה. וּכְשֶׁבָּא הַבֹּקֶר וְהַגְּבִירָה מִתְחַבֶּרֶת עִם הַמֶּלֶךְ, הוּא נִמְצָא עִמָּהּ עִם הַמֶּלֶךְ, וְהַמֶּלֶךְ פּוֹרֵס עַל כֻּלָּם אֶת כְּנָפָיו. זֶהוּ שֶׁכָּתוּב (שם מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי וְגוֹ'."],[2,"","לָמַדְנוּ, בְּאוֹתָהּ שָׁעָה הָאָבוֹת מִזְדַּמְּנִים עִם הַגְּבִירָה, וּמַקְדִּימִים לְדַבֵּר עִמָּהּ וּלְהִתְחַבֵּר עִמָּהּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְדַבֵּר עִמָּהּ עֲלֵיהֶם, וְהוּא קוֹרֵא לָהּ לִפְרֹס עָלֶיהָ אֶת כְּנָפָיו. זֶהוּ שֶׁכָתוּב (שם נ) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ וְגוֹ'. אֵל - זֶה אוֹר הַחָכְמָה, וְנִקְרָא חֶסֶד. אֱלֹהִים - זוֹ גְבוּרָה. יֱהִֹוִה - זוֹ שְׁלֵמוּת הַכֹּל, רַחֲמִים. וְעַל זֶה - דִּבֶּר וַיִּקְרָא אָרֶץ וְגוֹ'."],[3,"","רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, הֲרֵי שָׁנִינוּ אֱלֹהִים בְּכָל מָקוֹם הוּא דִּין. יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. יֵשׁ מָקוֹם שֶׁנִּקְרָא אֱלֹהִים, כְּמוֹ אֲדֹנָ\"י יְהֹוְ\"ה. לָמָּה נִקְרָא אֱלֹהִים, וַהֲרֵי אוֹתִיּוֹת הָרַחֲמִים הֵן בְּכָל מָקוֹם?"],[4,"","אָמַר לוֹ, כָּךְ זֶה כָּתוּב בַּמִּקְרָא, שֶׁכָּתוּב (דברים ד) וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבוֹתָ אֶל לְבָבֶךְ כִּי ה' הוּא הָאֱלֹהִים, וְכָתוּב (מלכים א יח) ה' הוּא הָאֱלֹהִים. אָמַר לוֹ, דָּבָר זֶה יָדַעְתִּי, שֶׁבְּמָקוֹם שֶׁיֵּשׁ דִּין יֵשׁ רַחֲמִים, וְלִפְעָמִים בְּמָקוֹם שֶׁיֵּשׁ רַחֲמִים יֵשׁ דִּין. אָמַר לוֹ, בֹּא וּרְאֵה שֶׁכָּכָה זֶה, יְהֹוָ\"ה בְּכָל מָקוֹם רַחֲמִים. וּבְשָׁעָה שֶׁמְּהַפְּכִים הָרְשָׁעִים רַחֲמִים לְדִין, אָז כָּתוּב יִהֹוְ\"ה, וְקוֹרְאִים אוֹתוֹ אֱלֹהִים."],[5,"","אֲבָל בֹּא רְאֵה סוֹד הַדָּבָר, שָׁלֹשׁ דְּרָגוֹת הֵן, וְכָל דַּרְגָּה וְדַרְגָּה לְבַדָּהּ, וְאַף עַל גַּב שֶׁהַכֹּל אֶחָד וּמְקֻשָּׁרִים בְּאֶחָד, וְלֹא נִפְרָדִים זֶה מִזֶּה. בֹּא רְאֵה, כָּל הַנְּטִיעוֹת וְכָל הַמְּאוֹרוֹת (שמתלהטים) כֻּלָּם מְאִירִים וּמִתְלַהֲטִים וְנִשְׁקִים וּמִתְבָּרְכִים מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא שֶׁהַכֹּל כָּלוּל בּוֹ, וּבוֹ כְּלַל הַכֹּל."],[6,"","וְהַנָּהָר הַזֶּה נִקְרָא אֵ\"ם לַגָּן וּמֵעַל לַגָּן, מִשּׁוּם שֶׁעֵדֶן מִשְׁתַּתֵּף עִמָּהּ וְלֹא נִפְרָד מִמֶּנָּה. וּמִשּׁוּם כָּךְ כָּל הַמַּעְיָנוֹת יוֹצְאִים וְשׁוֹפְעִים וְנִשְׁקִים לְכָל עֵבֶר וּפוֹתְחִים בָּהּ פְּתָחִים, וְעַל כֵּן רַחֲמִים נִמְצָאִים מִמֶּנָּה, וְרַחֲמִים פְּתוּחִים בָּהּ."],[7,"","וּמִשּׁוּם שֶׁקּוֹרְאִים לָהּ אֵם, נְקֵבָה גְּבוּרָה, וְדִין יוֹצֵא מִמֶּנָּה. נִקְרֵאת רַחֲמִים לְבַדָּהּ, הֲרֵי מִצִּדֶּיהָ מִתְעוֹרְרִים דִּינִים, וּמִשּׁוּם כָּךְ כָּתוּב בְּרַחֲמִים וְנָקוּד בְּדִין. הָאוֹתִיּוֹת בְּרַחֲמִים, וְנִשְׁפָּע דִּין מִצִּדָּהּ, כְּמוֹ כֵן יְהֶוִֹ\"ה, הִנֵּה דַּרְגָּה אַחַת."],[8,"","דַּרְגָּה שְׁנִיָּה - מִצַּד הָרִאשׁוֹנָה הַזּוֹ יוֹצֵאת וּמִתְעוֹרֶרֶת דַּרְגָּה אַחֶרֶת שֶׁנִּקְרֵאת גְּבוּרָה, וְזֶה נִקְרָא אֱלֹהִים בָּאוֹתִיּוֹת הַלָּלוּ מַמָּשׁ. וְהָרֵאשִׁית (אחת) הִיא מִזְּעֵיר אַנְפִּין, וּבוֹ נֶאֶחְזָה. וּמִשּׁוּם שֶׁנֶּאֶחְזָה (זה) בָּזֶה כָּתוּב ה' הָאֱלֹהִים, כִּי ה' הוּא הָאֱלֹהִים, בְּאֵלּוּ הָאוֹתִיּוֹת, וְהוּא אֶחָד, וְזוֹהִי דַּרְגָּה שְׁנִיָּה."],[9,"","דַּרְגָּה שְׁלִישִׁית - צֶדֶק. כֶּתֶר אַחֲרוֹן, הֲרֵי בֵּית דִּין שֶׁל הַמֶּלֶךְ. וְלָמַדְנוּ אֲדנָ\"י כָּךְ כָּתוּב וְכָךְ נִקְרָא, וּכְנֶסֶת יִשְׂרָאֵל נִקְרֵאת בַּשֵּׁם הַזֶּה, וְהַשֵּׁם הַזֶּה בַּמָּקוֹם הַזֶּה נִשְׁלָם, וְאֵלּו הֵן שָׁלֹשׁ דְּרָגוֹת שֶׁנִּקְרָאוֹת בִּשְׁמוֹת הַדִּין, וְהַכֹּל נִקְשָׁר אֶחָד עִם אֶחָד בְּלִי פֵרוּד, כְּמוֹ שֶׁבֵּאַרְנוּ."],[10,"","אָמַר לוֹ, אִם נוֹחַ לִפְנֵי אַבָּא, הֲרֵי שָׁמַעְתִּי עַל זֶה, שֶׁכָּתוּב (שמות ג) אֶהְיֶה אֲשֶׁר אֶהְיֶה, וְלֹא עוֹמֵד בּוֹ. אָמַר לוֹ, אֶלְעָזָר בְּנִי, הֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים, וְעַכְשָׁו בְּדָבָר אֶחָד הַכֹּל נִקְשָׁר."]]],[["וְרָזָא דְּמִלָּה הָכִי הוּא. אֶהְיֶה, דָּא כְּלָלָא דְּכֹלָּא. דְּכַד שְׁבִילִין סְתִימִין וְלָא מִתְפָּרְשָׁן, וּכְלִילָן בְּחַד אֲתַר. כְּדֵין אִקְרֵי אֶהְיֶה, כְּלָלָא כֹּלָּא, סָתִים וְלָא אִתְגַּלְיָיא.","בָּתַר דְּנָפַק מִנֵּיהּ שֵׁירוּתָא, וְהַהוּא נָהָר אִתְעַבָּר לְאַמְשָׁכָא כֹּלָּא, כְּדֵין אִקְרֵי אֲשֶׁר אֶהְיֶה. כְּלוֹמַר, עַל כֵּן אֶהְיֶה, אֶהְיֶה זַמִּין לְאַמְשָׁכָא וּלְאוֹלָדָא כֹּלָּא. אֶהְיֶה: כְּלוֹמַר, הַשְׁתָּא אֲנָא הוּא כְּלַל כֹּלָּא, כְּלָלָא דְּכָל פְּרָטָא. אֲשֶׁר אֶהְיֶה: דְּאִתְעַבְּרַת אִימָּא, וְזַמִינַת לְאַפָּקָא פְּרָטִין כֻּלְּהוּ, וּלְאִתְגַּלְיָיא שְּׁמָא עִלָּאָה.","לְבָתַר בָּעָא מֹשֶׁה לְמִנְדַּע פְּרָטָא דְּמִלָּה מַאן הוּא, עַד דְּפָרִישׁ וְאָמַר אֶהְיֶה (ס\"א יהוה), דָּא הוּא פְּרָטָא, וְהָכָא לָא כְּתִיב אֲשֶׁר אֶהְיֶה. (ויחי קל\"ה) וְאַשְׁכַּחְנָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, אֲשֶׁר: בְּקִיטוּרָא דְּעִדּוּנָא קַסְטִירָא בְּחַבְרוּתָא עִלָּאָה אִשְׁתְּכַח. כְּמָה דְאַתְּ אָמֵר, (בראשית ל׳:י״ג) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, אֶהְיֶה זְמִינָא לְאוֹלָדָא.","תָּא חֲזֵי הֵיךְ נָחִית מִדַּרְגָּא לְדַרְגָּא, לְאוֹדָעָא רָזָא דִּשְׁמָא קַדִּישָׁא (לאחזאה קודשא בריך הוא) לְמֹשֶׁה. בְּקַדְמִיתָא אֶהְיֶה, כְּלָלָא דְּכֹלָּא, סָתִים דְּלָא אִתְגַּלְיָיא כְּלַל, כְּמָה דַּאֲמֵינָא. וְסִימָן, (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וְגוֹ', וּכְתִיב (איוב כ״ח:י״ג) לֹא יָדַע אֱנוֹשׁ עֶרְכָּהּ וְגוֹ'. לְבָתַר אַפִּיק (רזא דשירותא עילאה, ראשיתא דכלא ו) הַהוּא נַהֲרָא, אִימָּא עִלָּאָה, אִתְעַבְּרַת, וּזְמִינָא לְאוֹלָדָא. וְאָמַר אֲשֶׁר אֶהְיֶה, זְמִינָא לְאוֹלָדָא, וּלְתַקְּנָא כֹּלָּא. לְבָתַר שָׁארֵי לְאוֹלָדָא, וְלָא כְּתִיב אֲשֶׁר, אֶלָּא אֶהְיֶה: כְּלוֹמַר, הַשְׁתָּא יָפִיק וְיִתְתָּקַן כֹּלָּא.","בָּתַר דְּנָפִיק כֹּלָּא, וְאִתְתָּקַּן כָּל חַד וְחַד בְּאַתְרֵיהּ, שָׁבַק כֹּלָּא, וְאָמַר יְהוָֹ\"ה. דָּא פְּרָטָא, וְדָא קִיוּמָא. וּבְהַהִיא שַׁעֲתָא יָדַע מֹשֶׁה, רָזָא דִּשְׁמָא קַדִּישָׁא, סָתִים וְגַלְיָא וְאִתְדַּבָּק מַה דְּלָא אִתְדָּבָקוּ שְׁאָר בְּנֵי עָלְמָא, זַכָּאָה חוּלָקֵיהּ. אָתָא רִבִּי אֶלְעָזָר וְנָשִׁיק יְדוֹי.","אָמַר לֵיהּ, אֶלְעָזָר בְּרִי, מִכָּאן וּלְהָלְאָה, אִזְדְּהַר דְּלָא לְמִכְתַּב שְׁמָא קַדִּישָׁא, אֶלָּא כְּדְקָא יֵאוֹת. דְּכָל מַאן דְּלָא יָדַע לְמִכְתַּב שְׁמָא קַדִּישָׁא כְּדְקָא יֵאוֹת, וּלְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא קִשְׁרָא דְּחַד בְּחַד, בְּגִין לְיַחֲדָא שְׁמָא קַדִּישָׁא. עָלֵיהּ כְּתִיב, (במדבר ט״ו:ל״א) כִּי דְּבַר יְיָ' בָּזָה וְאֶת מִצְוָתוֹ הֵפַר הִכָּרֵת תִּכָּרֵת וְגוֹ'. אֲפִילּוּ דְּגָרַע חַד דַּרְגָּא, אוֹ חַד קִשְׁרָא, מֵאָת חַד מִנַּיְיהוּ.","תָּא חֲזֵי, י' בְּקַדְמִיתָא, כְּלָלָא דְּכֹלָּא, סָתִים מִכָּל סִטְרִין, שְׁבִילִין לָא מִתְפַתְּחִין, כְּלָלָא דִּדְכַר וְנוּקְבָּא. קוֹצָא דְּיוֹ\"ד דִּלְעֵילָּא, רְמִיזָא לְאַיִן. לְבָתַר, י' דְּאַפִּיק הַהוּא נַהֲרָא דְּנָגִיד וְנָפִיק מִנֵיהּ, וּלְאִתְעַבְּרָא מִנֵּיהּ ה', בְּהַאי כְּתִיב (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן. (שמות פ\"ג ע\"א) יוֹצֵא וְלָא יָצָא. בְּגִין כָּךְ לָא בַּעְיָא לְאִתְפָּרְשָׁא מִנֵיהּ. וּבְגִין כָּךְ כְּתִיב רַעְיָתִי.","וְאִי תֵּימָא נָהָר כְּתִיב, מַשְׁמַע חַד, וְהָא הָכָא ג'. הָכִי הוּא ודַּאי, י' אַפִּיק תְּלָתָא, וּבִתְלָתָא אִתְכְּלַל כֹּלָּא. י' אַפִּיק לְקַמֵּיהּ הַהוּא נָהָר, וּתְרֵין בְּנִין דְּיַנְקָא לְהוּ אִימָּא, וְאִתְעַבְּרַת מִנַּיְיהוּ, וְאַפִּיק לוֹן לְבָתַר. ה': כְּגַוְונָא דָּא ה', וְאִינּוּן בְּנִין תְּחוֹת אַבָּא וְאִימָא.","בָּתַר דְּאוֹלִידַת, אַפִּיקַת בֶּן דְּכַר, וְשַׁוְיֵיהּ לְקַמָּהּ, וּבָעֵי לְמִכְתַּב ו', וְהַאי יָרִית אַחֲסַנְתָּא דְּאַבָּא וְאִימָא, וְיָרִית תְּרֵין חוּלָקִין, וּמִנֵּיהּ אִתְּזָן בְּרָתָא. וְעַל דָּא, בָּעֵי לְמִכְתַּב לְבָתַר, ו\"ה כַּחֲדָא כְּמָה דְּהֵ\"א קַדְמָאָה י\"ה כַּחֲדָא, וְלָא בָּעֵי לְאַפְרְשָׁא לוֹן, אוּף הָכָא ו\"ה כַּחֲדָא, וְלָא בָּעֵי לְאַפְרְשָׁא לוֹן. וְהָא אוֹקִימְנָא מִלֵּי. וְלַאֲתַר אָחֳרָא סַלְּקִין הָנֵי מִלֵי. זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּיַדְעִין רָזִין עִלָּאִין דְּמַלְכָּא קַדִּישָׁא, וְיִתְחֲזוּן לְאוֹדָאָה לֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ.","תָּאנָא אָמַר רִבִּי יְהוּדָה, (תהילים נ׳:א׳) אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִקְרָא אָרֶץ. שְׁלִימוּ דְּכֹלָּא, שְׁלִימוּ דַּאֲבָהָן קַדִּישֵׁי. דִּבֶּר וַיִּקְרָא אָרֶץ, לְאִשְׁתַּכְּחָא בִּכְּנֶסֶת יִשְׂרָאֵל בִּשְׁלִימוּ בְּחֶדְוָותָא. וּמֵאָן אֲתַר הוּא אִשְׁתְּכַח עִמָּהּ. הָדָר וְאָמַר, מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ.","תָּאנָא כַּד בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עָלְמָא דִּלְתַתָּא, כֹּלָּא כְּגַוְונָא דִּלְעֵילָּא עֲבַד לֵיהּ. עֲבַד יְרוּשְׁלֵים, אֶמְצָעִיתָא דְּכָל אַרְעָא. וַאֲתַר חַד דְּאִקְרֵי צִיּוֹן, עָלָה. וּמֵהַאי אֲתַר מִתְבָּרְכָא. וּבְהַאי אֲתַר דְּצִיּוֹן שָׁארֵי עָלְמָא לְאִתְבָּנָאָה, וּמִנֵּיהּ אִתְבְּנֵי. הֲדָא הוּא דִכְתִיב, אֵל אֱלֹהִים יְיָ' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרָח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאָן אֲתַר. מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ. כְּלוֹמַר, מִצִיּוֹן דְּהוּא שְׁלִימוּ דְּיוֹפִי דְּעָלְמָא, אֱלֹהִים הוֹפִיעַ. תָּא חֲזֵי, לָא אִתְבָּרְכָא יְרוּשָׁלַם, אֶלָּא מִצִּיּוֹן. וְצִיּוֹן מֵעֵילָּא, וְכֹלָּא חַד בְּחַד אִתְקְשַׁר."],[[0,"ורזא דמלה הכי וכו׳:","וסוד הדבר כך היא. השם \u0003אהיה,\u0004 זה כלל הכלל, שהוא או״א עלאין, שה״ס ג״ר דבינה, שהם תמיד בסו״ה כי חפץ חסד הוא ואינם מקבלים חכמה לעולם. כי כשהשבילים סתומים ואינם מפורשים, דהיינו שה \u0003י'\u0004 הסותמת, היא באויר שלהם, ואינה יוצאת מהם, (כנ״ל ב״א דף רנ\"א ד״ה נחית ע\"ש) וכלולים במקום אחד. דהיינו שכלולים בראש א״א. כי להיותם בבחינת ג״ר דבינה בסוד כי חפץ חסד, נחשבים כמו שלא יצאו מראש א״א, (כנ״ל בהקסה״ז דף י״ד במראות הסולם ד״ה והטעם) אז הם נקראים \u0003אהיה,\u0004 שהוא כלל הכל, והוא סתום ואינו מתגלה. (כמ״ש כל זה לעיל ב״א אות ו׳ ע״ש)."],[1,"בתר דנפק מניה וכו׳:","אחר שיוצאת ממנו ההתחלה לגילוי המוחין, ואותו הנהר, שהוא ישסו״ת נתעברה עם זו״ן, להמשיך הכל, אז היא נקראת \u0003אשר אהיה,\u0004 כלומר, על כן אהיה, \u0003אהיה,\u0004 היינו, אני עתיד להמשיך ולהוליד הכל. \u0003אהיה,\u0004 כלומר, עתה אני הוא כלל הכל, כלל של כל פרט, דהיינו של כל מדרגה ומדרגה. \u0003אשר אהיה,\u0004 היינו, שאמא, שהיא בינה, נתעברה ומוכנת להוציא כל הפרטים ולגלות שם העליון, \u0003הויה.\u0004"],[1,"","פירוש. אחר או\"א עלאין, נאצלים ויוצאים ישסו״ת, שהם בחינת ז״ת דבינה, ובהם ה \u0003י׳,\u0004 יוצאת מאויר ובינה ותו״מ שלהם שנפלו לזו״ן, חוזרים למדרגתם, לבינה, וגם לוקחים עמהם את זו״ן ומעלים אותם לבינה, כנ״ל, (בהקסה״ז דף כ׳ ד״ה אמא) שבזה נבחנים זו״ן כמו שנתעברו בבינה (כנ״ל תרומה אות תר״ח בהסולם) וז״ש, \u0003בתר דנפק מניה שירותא,\u0004 דהיינו ישסו״ת שבהם יוצאת ה \u0003י׳\u0004 מאויר, ונתגלה אור החכמה, בבחינת התחלה. \u0003וההוא נהר אתעבר,\u0004 שהבינה ותו״מ שלהם המשיכו את זו״ן לבינה, שזה נבחן שהבינה נתעברה עם זו\"ן, \u0003לאמשכא כלא,\u0004 דהיינו זו\"ן, \u0003כדין אקרי, אשר אהיה,\u0004 שפירושו, \u0003זמין לאמשכא דלאולדא כלא,\u0004 שנעשתה בזה מוכנת להוליד כל המוחין דזו\"ן. \u0003השתא אנא כלל כלא,\u0004 כי נעשתה בזה מוכשרת להוציא כל המדרגות דזו״ן ודבי״ע. וז״ש, \u0003לאפקא פרטין כלהו, ולאתגליא שמא עלאה.\u0004 דהיינו השם \u0003הויה\u0004 שהוא השם של ז״א בגדלות."],[2,"לבתר בעא משה וכו׳:","אח״כ רצה משה לדעת פרטיות הדבר מה הוא. דהיינו עצם תקון המוחין בישסו״ת בג׳ קוין שמשם יצאו ונאצלו המוחין דז״א. עד שהקב״ה פירש לו ואמר, כה תאמר לבני ישראל \u0003אהיה\u0004 וגו'. שם הזה הוא פרטיותה של ישסו״ת, וע״כ לא כתוב כאן, אשר אהיה. ומצאתי בספרו של שלמה המלך, \u0003אשר,\u0004 פירושו, שההיכל, שהוא בינה, הוא בקשר העדן, שהוא חכמה, שנמצא בחיבור העליון. כמש״א, באשרי כי אשרוני בנות. אף כאן \u0003אשר,\u0004 הוא לשון אושר. \u0003אהיה,\u0004 פירושו, שמוכנת להוליד."],[2,"","פירוש. כבר ידעת שע״י עלית המלכות במקום בינה דראש א״א, יצאה הבינה מראש דא״א לגוף, שהסו״ה, ונהר, שהוא בינה, יוצא מעדן, שהוא חכמה, שהיא הראש דא״א, וסוד העיבור של זו״ן בבינה נתבאר לעיל שהוא בזמן שהמלכות חוזרת ויורדת מבינה למקומה, ובינה ותו״מ שלה חוזרים אליה, אשר אז גם הראש דא״א מחזיר אליו הבינה ותו״מ שיצאה ממנו, והבינה, שהיא ישסו״ת חוזרת לעדן. וע״כ נקראת אז \u0003אשר,\u0004 מלשון אושר והצלחה, דהיינו מחמת שחזרה לראש א״א שה״ס עדן. וז״ש, \u0003אשר,\u0004 היינו \u0003בקיטורא דעדונא קסטירא,\u0004 שההיכל, שהוא ישסו״ת חזר ונקשר בעדן, שהוא הראש דא״א. \u0003בחברותא עלאה אשתכח,\u0004 שנמצאת אז בזווג עליון עם או״א עלאין. וע״כ נקראת \u0003אשר,\u0004 שזהו כל הצלחתה. אמנם אח״כ, לעת לידה, חוזרים ויוצאים ישסו״ת מראש דא״א ונפרדים מזווג עם או״א עלאין, ואז נקראת \u0003אהיה\u0004 סתם, בלי \u0003אשר,\u0004 משום שנפרדה מעדן. \u0003קסטירא,\u0004 פירושו היכל, כי על בחצריהם וטירותם מתרגם כפרנהון וקסטרוותהון (בראשית כ״ה ט״ז)."],[3,"ת״ח היך נחית וכו׳:","בוא וראה איך ירד ממדרגה למדרגה, להודיע הסוד של השם הקדוש למשה. מתחילה, \u0003אהיה,\u0004 שהוא כלל הכל, וסתום שלא נגלה כלל. שהם או״א עלאין, כמו שאמרתי. והסימן, ו \u0003אהיה\u0004 אצלו אמון וגו'. וכתוב, לא ידע אנוש ערכה וגו'. הרי שהחכמה, שה״ס או״א עלאין, הם סתומים וכתוב עליהם לא ידע אנוש ערכה, כי החכמה נעלמת בהם ואינה ידועה כלל. ואח״כ האצילו או״א עלאין את נהר ההוא, שהוא אמא עלאה, ונתעברה, והיא עתידה להוליד. ואמר \u0003אשר אהיה,\u0004 שפירושו, אני מוכן להוליד ולתקן הכל. לאח״כ תתחילה להוליד, ואז לא כתוב \u0003אשר,\u0004 משום שבשעת לידה נפרד הזווג העליון. כנ״ל. אלא \u0003אהיה,\u0004 כלומר, עתה יוציא ויוליד ויתתקן הכל."],[4,"בתר דנפיק כלא וכו׳:","אחר שיצא הכל ונתתקן כל אחד ואחד במקומו, כלומר, אחר שנולד ז״א ובא למטה במקומו. עזב הכל, דהיינו כל השמות הנ״ל, ואמר \u0003הויה,\u0004 זהו פרט, דהיינו פרטיות מדרגת ז״א, שלא בחיבור עם אמא, וזהו קיום, דהיינו המוחין דז״א הנקראים קיום. ובשעה ההיא ידע משה סוד השם הקדוש הסתום והגלוי, ונתדבק מה שלא נתדבקו שאר בני העולם כמוהו, אשרי חלקו. בא ר׳ אלעזר ונשק ידיו."],[5,"א״ל אלעזר ברי וכו׳:","אמר לו, אלעזר בני, מכאן ולהלאה, הזהר שלא לכתוב את השם הקדוש, אלא כראוי, כי מי שאינו יודע לכתוב את השם הקדוש כראוי ולקשר קשר האמונה, הקשר של אחד באחד, של ז״א ומלכות, בסו״ה הויה אחד ושמו אחד, כדי ליחד את השם הקדוש, עליו כתוב, כי דבר ה׳ בזה ואת מצותו הפר הכרת תכרת וגו', ואפילו אם גורע מדרגה אחת, או יחוד אחד מאות אחת מהן."],[6,"ת״ח י׳ בקדמיתא וכו׳:","בוא וראה, \u0003י׳\u0004 שבתחילת שם הויה, היא כלל הכל, סתומה מכל הצדדים, שבילים לא נפתחים בה, היא כלל זכר ונקבה, שהם אבא ואמא עלאין, שה \u0003י׳\u0004 ה״ס אבא, וב׳ אותיות מילוי היוד, שהן \u0003ו׳ ד',\u0004 הן אמא והם סתומים ובלתי נפתחים (כנ״ל אות קס״ח) הקוץ שעל ה \u0003י׳\u0004 למעלה רומז על \u0003אין,\u0004 שהוא כתר הנקרא אין, מטעם שבו אפיסת ההשגה. ואח״כ הוציאה הי', ממנה, שה״ס עדן, אותו הנהר הנמשך ויוצא, שהוא בינה, ושתתעבר ממנו, בבן ובת שהם \u0003ו׳ ד',\u0004 והיא \u0003ה׳,\u0004 שצורתה רומזת על ז״א ומלכות המעוברים בתוכה, שהם צורת \u0003ד׳ ו'.\u0004 בה׳ זו כתוב, ונהר יוצא מעדן, \u0003יוצא,\u0004 כתוב דהיינו שיוצא תמיד, ולא \u0003יצא\u0004 שהוא לשון עבר. משום זה, אין ה \u0003ה׳\u0004 צריכה להפרד מן ה \u0003י׳,\u0004 וע״כ כתוב רעיתי, על \u0003ה׳\u0004 הזו, להיותה עם ה \u0003י׳\u0004 כשני ריעים, שאינם נפרדים זה מזה לעולם."],[7,"ואי תימא נהר וכו׳:","ואם תאמר, הרי נהר כתוב, שמשמע אחד, והרי כאן יש ג', דהיינו הבינה, המעוברת עם ז״א ומלכות, כנ״ל. ומשיב, כך הוא ודאי, ה \u0003י׳\u0004 הוציאה שלשה, ובשלשה נכלל הכל, ה \u0003י׳\u0004 הוציאה לפניה נהר הזה, שהיא בינה, ושני בנים, שאמא מניקה אותם ומתעברת מהם, שהוציאה אותם לאחר כך. \u0003ה׳\u0004 היא כצורה זו \u0003ד׳,\u0004 ובתוכה \u0003ו',\u0004 שהיא הרגל הקטועה שבתוך ה \u0003ה׳,\u0004 ואלו \u0003ד׳ ו׳\u0004 הם הבנים שמתחת אבא ואמא, שאמא מעוברת בהם, כנ״ל."],[8,"בתר דאולידת אפיקת וכו׳:","אחר שהבינה הולידה, הוציאה בן זכר, ונתנה אותה לפניה, שהוא ז״א, וצריכים לכתוב \u0003ו׳,\u0004 הרומזת על הבן, שהוא ז״א, אחר שכבר נולד ויצא לחוץ, למקומו. וזה, הבן יורש נחלת אבא ואמא, דהיינו שמקבל המוחין די״ה שהם או\"א, אע״פ שאינם שייכים לו מבחינת אצילותו, אלא בסוד כיון דתלת נפקי מחד, חד בתלת קיימא בראשית א׳ דף רפ״ז ד״ה תלת) שזה נבזזן כמו שבאים לו בירושה. וז\"א יורש ב׳ חלקים, אחד לעצמו, ואחד בשביל המלכות, וממנו ניזונת הבת. וע״כ צריכים לכתוב אח״כ \u0003ו״ה\u0004 ביחד, בזו אחר זו, כמו ש \u0003ה׳\u0004 ראשונה מחוברת יחד עם ה \u0003י׳,\u0004 דהיינו \u0003י״ה,\u0004 ואין צריך להפריד ביניהם, (כנ\"ל באות קס״ט) אף כאן ו\"ה ביחד ולא צריכים להפריד ביניהם. וכבד העמדנו הדברים, ואלו הדברים שבכאן עולים למקום אחר. אשרי חלקם של הצדיקים היודעים סודות עליונים של המלך הקדוש, וראוים להודות לפניו, ז״ש אך צדיקים יודו לשמך ישבו ישרים את פניך."],[9,"תאנא א״ר יהודה וכו׳:","למדנו, אר״י, אל אלקים הוי״ה דבר ויקרא ארץ, אל אלקים הויה, הם חג״ת (כנ\"ל. אות קנ\"ו) שהם שלמות הכל, שלמות האבות הקדושים, שהם חג״ת. \u0003דבר ויקרא ארץ,\u0004 דבר, פירושו השפעה, ארץ היא המלכות, כדי להמצא בכנסת ישראל בשלמות בשמחה. ומאיזה מקום הוא נמצא עמה, חוזר ואומר, \u0003מציון מכלל יופי אלקים הופיע,\u0004 היינו מיסוד דמלכות הנקרא ציון."],[10,"תאנא כד בעא","וכו': למדנו, כשרצה הקב\"ה לברוא את העולם התחתון, כולו כעין של מעלה עשה אותו, עשה את ירושלים אמצע של כל הארץ, ומקום אחד, עליה, שנקרא ציון, שה\"ס יסוד, וממקום הזה מתברכת. וממקום הזה של ציון, התחיל העולם להבנות, וממנו נבנה, ז\"ש אל אלקים דבר ויקרא ארץ ממזרח שמש עד מבואו, ומאיזה מקום, מציון מכלל יופי אלקים הופיע, כלומר, מציון, שהיא שלמות היופי של העולם אלקים הופיע. בוא וראה, לא נתברכה ירושלים, שהיא המלכות, אלא מציון, שהיא יסוד. וציון נתברכה מלמעלה, שהוא ז\"א, והכל אחד באחד מתקשר, שז\"א ומלכות, שה\"ס אחד באחד, מתיחדים ע\"י ציון."]],[[0,"","וְסוֹד הַדָּבָר כָּךְ הוּא. אֶהְיֶה, זֶה כְּלָל שֶׁל הַכֹּל. שֶׁכְּשֶׁשְּׁבִילִים סְתוּמִים וְלֹא מִתְפָּרְשִׁים, וּכְלוּלִים בְּמָקוֹם אֶחָד, אָז נִקְרָא אֶהְיֶה, הַכְּלָל שֶׁל הַכֹּל, סָתוּם וְלֹא נִגְלֶה."],[1,"","אַחַר שֶׁיָּצְאָה מִמֶּנּוּ רֵאשִׁית וְאוֹתוֹ נָהָר עָבַר לִמְשֹׁךְ אֶת הַכֹּל, אֲזַי נִקְרָא אֲשֶׁר אֶהְיֶה. כְּלוֹמַר, עַל כֵּן אֶהְיֶה, אֶהְיֶה מְזֻמָּן לְהַמְשִׁיךְ וּלְהוֹלִיד הַכֹּל. אֶהְיֶה - כְּלוֹמַר, עַכְשָׁו אֲנִי הוּא הַכְּלָל שֶׁל הַכֹּל, הַכְּלָל שֶׁל כָּל פְּרָט. אֲשֶׁר אֶהְיֶה - שֶׁהִתְעַבְּרָה הָאֵם, וַעֲתִידָה לְהוֹצִיא אֶת כָּל הַפְּרָטִים וּלְגַלּוֹת אֶת הַשֵּׁם הָעֶלְיוֹן."],[2,"","אַחַר כָּךְ רָצָה מֹשֶׁה לָדַעַת מַהוּ פְּרַט הַדָּבָר, עַד שֶׁפֵּרַשׁ וְאָמַר אֶהְיֶה (יהוה) - זֶהוּ פְּרָט. וְכָאן לֹא כָתוּב אֲשֶׁר אֶהְיֶה. וּמָצָאתִי בְּסִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, אֲשֶׁר - בְּקֶשֶׁר שֶׁל עִדּוּן הַמֶּמְשָׁלָה נִמְצֵאת בְּחַבְרוּתָא עֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ל) בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת, אֶהְיֶה עֲתִידָה לְהוֹלִיד."],[3,"","בֹּא וּרְאֵה אֵיךְ יוֹרֵד מִדַּרְגָּה לְדַרְגָּה לְהוֹדִיעַ אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ (להראות את הקדוש ברוך הוא) לְמֹשֶׁה. בָּרִאשׁוֹנָה אֶהְיֶה, הַכְּלָל שֶׁל הַכֹּל, הַנִּסְתָּר שֶׁלֹּא הִתְגַּלָּה כְּלָל, כְּמוֹ שֶׁאָמַרְנוּ. וְסִימָן - (משלי ח) וָאֶהְיֶה אֶצְלוֹ אָמוֹן וְגוֹ', וְכָתוּב (איוב כח) לֹא יָדַע אֱנוֹשׁ עֶרְכָּהּ וְגוֹ'. אַחַר כָּךְ הוֹצִיא (סוד של הראשית העליונה, תחלת הכל ו) אוֹתוֹ הַנָּהָר, הָאֵם הָעֶלְיוֹנָה שֶׁהִתְעַבְּרָה וַעֲתִידָה לְהוֹלִיד. וְאָמַר אֲשֶׁר אֶהְיֶה, עֲתִידָה לְהוֹלִיד וּלְתַקֵּן הַכֹּל. אַחַר כָּךְ הִתְחִילָה לְהוֹלִיד, וְלֹא כָתוּב אֲשֶׁר, אֶלָּא רַק אֶהְיֶה. כְּלוֹמַר, עַכְשָׁו יוֹצִיא וְיִתְתַּקֵּן הַכֹּל."],[4,"","אַחַר שֶׁהַכֹּל יָצָא וְכָל אֶחָד וְאֶחָד הִתְתַּקֵּן בִּמְקוֹמוֹ, עָזַב אֶת הַכֹּל וְאָמַר יְהֹוָ\"ה. זֶה פְּרָט, וְזֶה הַקִּיּוּם. וּבְאוֹתָהּ שָׁעָה יָדַע מֹשֶׁה אֶת סוֹד הַשֵּׁם הַקָּדוֹשׁ הַנִּסְתָּר וְהַנִּגְלֶה, וְנִדְבָּק בְּמַה שֶּׁלֹּא נִדְבְּקוּ שְׁאָר בְּנֵי הָעוֹלָם. אַשְׁרֵי חֶלְקוֹ. בָּא רַבִּי אֶלְעָזָר וְנָשַׁק יָדוֹ."],[5,"","אָמַר לוֹ, אֶלְעָזָר בְּנִי, מִכָּאן וָהָלְאָה הִזָּהֵר שֶׁלֹּא לִכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ אֶלָּא כָּרָאוּי. שֶׁכָּל מִי שֶׁלֹּא יוֹדֵעַ לִכְתֹּב אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי וְלִקְשֹׁר אֶת קֶשֶׁר הָאֱמוּנָה קֶשֶׁר שֶׁל אֶחָד עִם אֶחָד כְּדֵי לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ, כָּתוּב עָלָיו (במדבר טו) כִּי דְבַר ה' בָּזָה וְאֶת מִצְוָתוֹ הֵפַר הִכָּרֵת תִּכָּרֵת וְגוֹ'. אֲפִלּוּ שֶׁהֶחֱסִיר דַּרְגָּה אַחַת אוֹ קֶשֶׁר אֶחָד מֵאוֹת אַחַת מֵהֶן."],[6,"","בֹּא רְאֵה, י' בָּרִאשׁוֹנָה - הַכְּלָל שֶׁל הַכֹּל, נִסְתַּר מִכָּל הַצְּדָדִים, הַשְּׁבִילִים לֹא נִפְתָּחִים, הַכְּלָל שֶׁל זָכָר וּנְקֵבָה. קוֹצוֹ שֶׁל יוֹ\"ד שֶׁלְּמַעְלָה רוֹמֵז לְאַיִן. אַחַר כָּךְ י' שֶׁמּוֹצִיאָה אֶת אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מִמֶּנּוּ, וּלְהִתְעַבֵּר מִמֶּנּוּ ה', בָּזֶה כָּתוּב (בראשיתב) וְנָהָר יֹצֵא מֵעֵדֶן. יֹצֵא וְלֹא יָצָא. מִשּׁוּם כָּךְ לֹא צָרִיךְ לְהִפָּרֵד מִמֶּנּוּ. וּמִשּׁוּם כָּךְ כָּתוּב רַעְיָתִי."],[7,"","וְאִם תֹּאמַר, כָּתוּב נָהָר, מַשְׁמָע אֶחָד, וַהֲרֵי כָּאן שְׁלֹשָׁה? זֶה כָּךְ וַדַּאי. י' מוֹצִיאָה שְׁלֹשָׁה, וּבִשְׁלֹשָׁה הַכֹּל נִכְלָל. י' מוֹצִיאָה לְפָנֶיהָ אוֹתוֹ נָהָר, וּשְׁנֵי בָנִים שֶׁמְּנִיקָה הָאֵם, וְהִתְעַבְּרָה מֵהֶם, וּמוֹצִיאָה אוֹתָם אַחַר כָּךְ. ה' - כְּמוֹ כֵן ה', וְהֵם בָּנִים תַּחַת הָאָב וְהָאֵם."],[8,"","אַחַר שֶׁהוֹלִידָה, הוֹצִיאָה בֵּן זָכָר, וְשָׂמָה אוֹתוֹ לְפָנֶיהָ, וְצָרִיךְ לִכְתֹּב ו', וְזֶה יוֹרֵשׁ אֶת נַחֲלַת הָאָב וְהָאֵם, וְיוֹרֵשׁ שְׁנֵי חֲלָקִים, וּמִמֶּנּוּ נִזּוֹנֵית הַבַּת. וְעַל כֵּן צָרִיךְ לִכְתֹּב אַחַר כָּךְ ו\"ה כְּאֶחָד, כְּמוֹ שֶׁהֵ\"א רִאשׁוֹנָה י\"ה כְּאֶחָד, וְלֹא צָרִיךְ לְהַפְרִידָם. אַף כָּאן ו\"ה כְּאֶחָד, וְלֹא צָרִיךְ לְהַפְרִידָם. וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים. וְהַדְּבָרִים הַלָּלוּ עוֹלִים לְמָקוֹם אַחֵר. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת הַסּוֹדוֹת הָעֶלְיוֹנִים שֶׁל הַמֶּלֶךְ הַקָּדוֹשׁ וּרְאוּיִים לְהוֹדוֹת לוֹ. זֶהוּ שֶׁכָּתוּב (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ."],[9,"","לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, (שם נ) אֵל אֱלֹהִים דִּבֶּר וַיִּקְרָא אָרֶץ. שְׁלֵמוּת הַכֹּל, שְׁלֵמוּתָם שֶׁל הָאָבוֹת הַקְּדוֹשִׁים. דִּבֶּר וַיִּקְרָא אָרֶץ, לְהִמָּצֵא עִם כְּנֶסֶת יִשְׂרָאֵל בִּשְׁלֵמוּת וּבְשִׂמְחָה. וּמֵאֵיזֶה מָקוֹם הוּא נִמְצָא עִמָּהּ? חָזַר וְאָמַר, מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ."],[10,"","לָמַדְנוּ, כְּשֶׁרָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא אֶת הָעוֹלָם שֶׁלְּמַטָּה, עָשָׂה הַכֹּל כְּמוֹ שֶׁלְּמַעְלָה. עָשָׂה יְרוּשָׁלַיִם מֶרְכַּז כָּל הָאָרֶץ, וּמָקוֹם אֶחָד שֶׁנִּקְרָא צִיּוֹן עָלֶיהָ, וּמֵהַמָּקוֹם הַזֶּה מִתְבָּרֶכֶת. וּבַמָּקוֹם הַזֶּה שֶׁל צִיּוֹן מַתְחִיל הָעוֹלָם לְהִבָּנוֹת, וּמִמֶּנּוּ נִבְנָה. זֶהוּ שֶׁכָּתוּב, אֵל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאֵיזֶה מָקוֹם? מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. כְּלוֹמַר, מִצִּיּוֹן, שֶׁהִיא שְׁלֵמוּת שֶׁל הַיֹּפִי שֶׁל הָעוֹלָם, אֱלֹהִים הוֹפִיעַ. בֹּא רְאֵה, לֹא הִתְבָּרְכָה יְרוּשָׁלַיִם אֶלָּא רַק מִצִּיּוֹן. וְצִיּוֹן מִלְמַעְלָה, וְהַכֹּל נִקְשָׁר אֶחָד עִם אֶחָד."]]],[["תָּאנָא, אָמַר רִבִּי יְהוּדָה, (ויקרא ט״ז:י״ח) וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי יְיָ' וְכִפֶּר עָלָיו. אֶל הַמִּזְבֵּחַ סְתָם. (כביכול) כְּמָה דְּאִתְעָבִיד לְתַתָּא, אִתְעָבִיד לְעֵילָּא, וְכֹלָּא אִתְקְשַׁר חַד בְּחַד. וְתָאנָא, כְּמָה דִּבְהַאי יוֹמָא מְכַפֵּר כַּהֲנָא לְתַתָּא, הָכִי נָמֵי לְעֵילָּא. וְכַד כַּהֲנָא דִּלְתַתָּא מְסַדֵּר פּוּלְחָנֵיהּ, כַּהֲנָא דִּלְעֵילָּא הָכִי נָמֵי, (כביכול) לָא אִשְׁתְּכַח לְעֵילָּא, עֵד דְּאִשְׁתְּכַח לְתַתָּא. וּמִתַּתָּא שָׁארֵי לְסַלְּקָא קְדוּשָּׁה דְּמַלְכָּא עִלָּאָה, וּמִשְׁתַּכְחִין כֻּלְּהוּ עָלְמִין חַד קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא.","אָמַר רִבִּי יְהוּדָה, אִלְמָלֵא הֲווֹ יַדְעִי יִשְׂרָאֵל אֲמַאי קוּדְשָׁא בְּרִיךְ הוּא פָּקִיד עָלַיְיהוּ דְּיִשְׂרָאֵל, לְאוֹכָחָא לְהוּ יַתִּיר מִכָּל שְׁאָר עַמִּין, יִנְדְּעוּן דְּהָא קוּדְשָׁא בְּרִיךְ הוּא שָׁבִיק דִּידֵיהּ, וְלָא גָּבֵי מִנְּהוֹן חַד מִמֵּאָה. תָּאנָא, קוּדְשָׁא בְּרִיךְ הוּא כַּמָה רְתִיכִין, כַּמָה חַיָּילִין אִית לֵיהּ, כַּמָה שׁוּלְטָנִין מְמָנָן מִשְׁתַּכְּחִין בְּפוּלְחָנֵיהּ, כַּד זַמִּין לְהוּ לְיִשְׂרָאֵל בְּהַאי עָלְמָא, אַכְתַּר לוֹן בְּכִתְרִין קַדִּישִׁין כְּגַוְונָא דִּלְעֵילָּא, אַשְׁרֵי לוֹן בְּאַרְעָא קַדִּישָׁא, בְּגִין דְּיִשְׁתְּכָחוּ בְּפוּלְחָנֵיהּ, קָשִׁיר לְכֻלְּהוּ עִלָּאֵי בְּהוּ בְּיִשְׂרָאֵל.","וְחֶדְוָון לָא עָאלִין קַמֵּיהּ, וּפוּלְחָנָא לָא אִתְעָבִיד קָמֵיהּ לְעֵילָּא, עַד דְּיִשְׂרָאֵל עַבְדִּין לְתַתָּא. כָּל זִמְנָא דְּיִשְׂרָאֵל מִשְׁתַּכְּחִין בְּפוּלְחָנֵיהּ דְּמָארֵיהוֹן לְתַתָּא, הָכִי נָמֵי לְעֵילָּא. (כביכול) בְּזִמְנָא דְּיִשְׂרָאֵל בְּטַלֵּי פּוּלְחָנָא לְתַתָּא. בְּטַלֵּי לְעֵילָּא, וּפוּלְחָנָא לָא אִשְׁתְּכַח לָא לְעֵילָּא וְלָא לְתַתָּא. וְעַל דְּיִשְׂרָאֵל בַּטְלוּ פּוּלְחָנָא דְּקוּדְשָׁא בְּרִיךְ הוּא כַּד שָׁארָן בְּאַרְעָא, הָכִי נָמֵי לְעֵילָּא, כָּל שֶׁכֵּן לְבָתַר.","אָמַר קוּדְשָׁא בְּרִיךְ הוּא, יִשְׂרָאֵל אִי אַתּוּן יַדְעִין, כַּמָה אוּכְלוּסִין, כַּמָה חַיָּילִין, מִתְעַכְּבִין בְּגִינַיְיכוּ, תִּנְדְּעוּן דְּלֵית אַתּוּן כְּדַאי לְמֵיקָם בְּעָלְמָא, אֲפִילּוּ שַׁעֲתָא חֲדָא. וְעִם כָּל דָּא מַה כְּתִיב, (ויקרא כ״ו:מ״ד) וְאַף גַּם זֹאת בִּהְיוֹתָם בְּאֶרֶץ אוֹיְבֵיהֶם לֹא מְאַסְתִּים וְלֹא גְעַלְתִּים וְגוֹ', (בגין כך) וְיָצָא אֶל הַמִּזְבֵּחַ, אֶל הַמִּזְבֵּחַ סְתָם, אֲשֶׁר לִפְנֵי יְיָ' סְתָם. וְכִפֶּר עָלָיו לְבָתַר, וְיָצָא וְעָשָׂה אֶת עוֹלָתוֹ וְאֶת עוֹלַת הָעָם וְגוֹ'. וְכִפֵּר עָלָיו מַאי קָא מַיְירֵי. אָמַר רִבִּי יוֹסֵי, לְאִתְּעָרָא חֶסֶד בְּעָלְמָא בְּקַדְמִיתָא.","תָּאנָא, כְּתִיב וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאוֹת בְּנֵי יִשְׂרָאֵל. מַאי וְכִפֶּר עַל הַקֹּדֶשׁ. אֶלָּא אָמַר רִבִּי אֶלְעָזָר, הָא תָּנֵינָן, חַיָּיבַיָּא עַבְדִּין פְּגִימוּתָא לְעֵילָּא, וּמִתְעָרִין דִּינִין, וְגַרְמִין לְאִסְתַּאֲבָא מַקְדְּשָׁא. וְחִוְיָא תַּקִּיפָא שָׁארֵי לְאִתְגַּלָּאָה. וּכְדֵין דִּינִין מִתְעָרִין בְּעָלְמָא, וּבְהַאי יוֹמָא, בָּעֵי כַּהֲנָא לְדַכְּאָה כֹּלָּא, וּלְאִתְעַטְּרָא (ס\"א ולאתערא) כִּתְרָא קַדִּישָׁא דִּילֵיהּ, דְּהִיא רֵישָׁא דְּמַלְכָּא. בְּגִין דְּיֵיתֵי מַלְכָּא לְאַשְׁרָאָה בְּמַטְרוֹנִיתָא, וְכַד רֵישָׁא דְּמַלְכָּא נָטִיל, כֹּלָּא נָטִיל, וְיֵיתֵי לְאִזְדַּוְּוגָא בְּמַטְרוֹנִיתָא וּלְאַתְעֲרָא חֵידוּ וּבִרְכָּאן בְּעָלְמָא. (ס\"א בגין דייתי מלכא לאזדווגא במטרוניתא ולאתערא חדו וברכאן בעלמא, וכד רישא דמלכא נטיל כלא נטיל)","אִשְׁתְּכַח דְּכָל שְׁלָמָא (נ\"א שלימו) דְּעֵילָּא וְתַתָּא, בְּכַהֲנָא תַּלְיָיא. דְּאִי אִתְּעַר כִּתְרָא דִּילֵיהּ, כֹּלָּא אִתְּעַר וְכֹלָּא בִּשְׁלִימוּ אִשְׁתְּכַח. וְעַל דָּא כְּתִיב וְכִפֶּר עַל הַקֹּדֶשׁ. בְּקַדְמִיתָא וְכִפֶּר עַל הַקֹּדֶשׁ. לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא, וּלְאַסְגָּאָה חֵידוּ בְּעָלְמָא. וְכַד חֵידוּ דְּזִוּוּגָא אִשְׁתְּכַח בְּמַלְכָּא וּבְּמַטְרוֹנִיתָא, כָּל שַׁמָּשִׁין, וְכָל בְּנֵי הֵיכָלָא, כֻּלְּהוּ אִשְׁתְּכָחוּ בְּחֵידוּ (וכד חידו דעלמא). וְכָל חוֹבִין דְּחָבוּ קָמֵי מַלְכָּא, אִתְכַּפָּר לְהוּ. הֲדָא הוּא דִכְתִיב, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ' תִּטְהָרוּ. וּבְגִין כָּךְ כְּתִיב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבֹאוֹ לְכַפֵּר בַּקֹּדֶשׁ עַד צֵאתוֹ. בְּשַׁעֲתָא דְּעָאל לְזַוְּוגָא לְהוּ, וּבְשַׁעֲתָא דְּמִזְדַּוְּוגִין מַלְכָּא וּמַטְרוֹנִיתָא, הַהִיא שַׁעֲתָא וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ.","תָּאנָא, (ויקרא ט״ז:י״ז) וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד, רִבִּי יִצְחָק פָּתַח, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְגוֹ', וְהַאי קְרָא אוּקְמוּהָ. תָּא חֲזֵי, בְּשַׁעֲתָא דְּיִשְׂרָאֵל בְּגָלוּתָא, כִּבְיָכוֹל קוּדְשָׁא בְּרִיךְ הוּא עִמְּהוֹן בְּגָלוּתָא, דְּהָא שְׁכִינְתָּא לָא אִתְעָדֵי מִנַּיְיהוּ לְעָלְמִין. תָּא חֲזֵי, בְּזִמְנָא דְּיִשְׂרָאֵל אִשְׁתְּכָחוּ בְּגָלוּתָא דְּבָבֶל, שְׁכִינְתָּא בֵּינַיְיהוּ שַׁרְיָא, וְתָאבָת עִמְּהוֹן מִן גָּלוּתָא. וּבִזְכוּת אִינּוּן צַדִּיקַיָּיא דְּאִשְׁתָּאָרוּ בְּאַרְעָא, שָׁארַת בְּאַרְעָא, וְלָא אַעְדֵּי מִנַּיְיהוּ לְעָלְמִין. אָמַר רִבִּי יְהוּדָה, דְּאִתְהַדְּרַת מַטְרוֹנִיתָא בְּמַלְכָּא, וְאִתְהַדָּר כֹּלָּא בְּהִלּוּלָא דְּמַלְכָּא, בְּגִין כָּךְ אִקְרוּן אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, כְּנֶסֶת הַגְּדוֹלָה וַדַּאי."],[[0,"תאנא א\"ר יהודה","וכו': למדנו אר\"י, ויצא אל המזבח אשר לפני ה' וכפר עליו. אל המזבח, ואמר סתם, שמרמז על המזבח של מעלה, שה\"ס יסוד דמלכות. וכמו שנעשה למטה כן נעשה למעלה, והכל נקשר אחד באחד. ע\"י המזבח, שהוא יסוד המלכות, ולמדנו, כמו שביום הזה מכפר הכהן למטה, בבית המקדש, כן הוא למעלה, וכשהכהן שלמטה מסדר עבודתו, כן הכהן שלמעלה, שהוא חסד דז\"א, משפיע אל המלכות, ולא נמצאת העבודה שלמעלה, שה\"ס ההשפעה של החסד אל המלכות, עד שנמצאת למטה עבודתו של הכהן, כי מלמטה מתחילה לעלות הקדושה של המלך העליון. ונמצאים כל העולמות אחד, לפני הקב\"ה."],[1,"א\"ר יהודה","וכו': אר\"י, אם היו יודעים ישראל למה פקד הקב\"ה עליהם לייסר אותם, יותר מכל שאר העמים, היו יודעים, שהקב\"ה ויתר, על שלו, ולא נפרע מהם אחד ממאה. למדנו, כמה מרכבות כמה צבאות יש לו להקב\"ה. כמה שליטים ממונים נמצאים בעבודתו, כשהזמין את ישראל בעולם הזה, הכתיר אותם בכתרים קדושים, כעין של מעלה, והשכין אותם בארץ הקדש, שהיא מכוונת כנגד המלכות, כדי שימצאו בעבודתו. וקשר כל העליונים בישראל."],[2,"וחדוון לא עאלין","וכו': ושמחה אינה נכנסת לפניו, ועבודה לא נעשית לפניו למעלה, עד שישראל עושים למטה. כל זמן שישראל נמצאים למטה בעבודת אדונם, כן הוא למעלה. ובזמן שישראל מבטלים העבודה למטה, מתבטלת ג\"כ למעלה, ועבודה אינה נמצאת לא למעלה ולא למטה. ומשום שישראל בטלו עבודת הקב\"ה כשהיו שורים בארץ, היה כן למעלה, ומכ\"ש אח\"כ בגלות."],[3,"אמר קב\"ה, ישראל","וכו': אמר הקב\"ה: ישראל, אם הייתם יודעים, כמה גדודים כמה צבאות מתעכבים בעבודתם בשבילכם למעלה, הייתם יודעים, שאין אתם ראוים להיות בעולם אפילו שעה אחת. ועכ\"ז, מה כתוב, ואף גם זאת בהיותם בארץ אויביהם לא מאסתים ולא געלתים וגו'. ולפיכך, ויצא אל המזבח, נאמר, על המזבח, סתם, שאינו מוכרח שהוא המזבח שלמטה במקדש. וכן, אשר לפני ה' סתם, שאינו מוכרח שהוא בבית המקדש. אלא המזבח, רומז על מזבח של מעלה, שהוא המלכות, שהוא לפני ה', שהוא ז\"א. ואח\"כ, וכפר עליו ויצא ועשה את עולתו ואת עולת העם וגו'. שואל, אם רומז על המלכות, וכפר עליו, מהו פירושו, וכי שייכת כפרה למעלה. א\"ר יוסי, וכפר עליו פירושו, לעורר החסד בעולם בתחילה."],[4,"תאנא כתיב וכפר","וגו': למדנו, כתוב, וכפר על הקדש מטומאת בני ישראל. שואל, מהו וכפר על הקדש. אלא אמר ר' אלעזר, הרי למדנו, הרשעים עושים פגם למעלה, ומעוררים דינים, וגורמים שיטמא המקדש, והנחש החזק מתחיל להתגלות. ואז דינים מתעוררים בעולם. וביום הזה, צריך הכהן לטהר הכל, ולעטר הספירה הקדושה שלו, שהיא חסד דז\"א, שהוא ראש המלך, כי חסד הוא ספירה ראשונה שלו. כדי שיבא המלך לשרות בהמלכה, שהיא המלכות, וכשראש המלך נוסע, כולם נוסעים, דהיינו כל ספירותיו, ובא להזדווג עם המלכה, ולעורר שמחה וברכות בעולם."],[5,"אשתכח דכל שלימו","וכו': נמצא שכל השלמות שלמעלה ושלמטה תלויה בכהן, שאם הספירה שלו מתעוררת, הכל מתעורר, והכל נמצא בשלימות. וע\"כ כתוב, וכפר על הקדש. בתחילה וכפר על הקדש, דהיינו להרבות שלום בעולם ולהרבות שמחה בעולם, וכשנמצאת שמחת הזווג במלך ובמלכה, כל המשמשים וכל בני ההיכל, כולם נמצאים בשמחה, וכל החטאים שעשו לפני המלך מתכפרים להם. ז\"ש, מכל חטאתיכם לפני ה' תטהרו. ומשום זה כתוב, וכל אדם לא יהיה באהל מועד, בבאו לכפר בקדש עד צאתו, שהוא בשעה שנכנס לזווג אותם, ובשעה שמזדווגים המלך והמלכה, בשעה ההיא, וכפר בעדו ובעד ביתו."],[6,"תאנא וכל אדם","וגו': למדנו, וכל אדם לא יהיה באהל מועד. רבי יצחק פתח, וזכרתי את בריתי יעקב ואף את בריתי יצחק וגו'. מקרא זה העמידוהו. בוא וראה, בשעה שישראל הם בגלות, הקב\"ה עמהם כביכול, בגלות, כי השכינה אינה סרה מהם לעולם. בוא וראה, בזמן שישראל נמצאו בגלות בבל, שרתה ביניהם השכינה, וחזרה עמהם מן הגלות. ובזכות אלו הצדיקים שנשארו בארץ, שרתה בארץ, ולא סרה מהם לעולם. א\"ר יהודה, שחזרה אז המלכה אל המלך, וחזר הכל להיות בסעודת השמחה של המלך. ומשום זה נקראו, אנשי כנסת הגדולה. כנסת הגדולה ודאי שהמלכות שנקראת כנסת, חזרה מקטנותה בגלות, והיתר לגדולה."]],[[0,"","לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, וְיָצָא אֶל הַמִּזְבֵּחַ אֲשֶׁר לִפְנֵי ה' וְכִפֶּר עָלָיו. אֶל הַמִּזְבֵּחַ סְתָם. (כביכול) כְּמוֹ שֶׁנַּעֲשֶׂה לְמַטָּה, נַעֲשֶׂה לְמַעְלָה, וְהַכֹּל נִקְשָׁר אֶחָד בְּאֶחָד. וְלָמַדְנוּ, כְּמוֹ שֶׁבַּיּוֹם הַזֶּה מְכַפֵּר הַכֹּהֵן לְמַטָּה, כָּךְ גַּם לְמַעְלָה. וּכְשֶׁהַכֹּהֵן שֶׁלְּמַטָּה מְסַדֵּר אֶת עֲבוֹדָתוֹ, כָּךְ גַּם הַכֹּהֵן שֶׁלְּמַעְלָה (כביכול) לֹא נִמְצָא לְמַעְלָה עַד שֶׁנִּמְצָא לְמַטָּה. וּמִמַּטָּה מַתְחִילָה לַעֲלוֹת קְדֻשַּׁת הַמֶּלֶךְ הָעֶלְיוֹן, וְכָל הָעוֹלָמִים נִמְצָאִים אֶחָד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."],[1,"","אָמַר רַבִּי יְהוּדָה, אִלְמָלֵא הָיוּ יוֹדְעִים יִשְׂרָאֵל לָמָּה צִוָּה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יִשְׂרָאֵל לְהוֹכִיחַ אוֹתָם יוֹתֵר מִכָּל שְׁאָר הָעַמִּים, יֵדְעוּ שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁאִיר אֶת שֶׁלּוֹ, וְלֹא גָבָה מֵהֶם אֶחָד מִמֵּאָה. לָמַדְנוּ שֶׁלַּקָּדוֹשׁ-בָּרוּךְ-הוּא יֵשׁ כַּמָּה מֶרְכָּבוֹת וְכַמָּה חֲיָלוֹת וְכַמָּה שַׁלִּיטִים מְמֻנִּים שֶׁנִּמְצָאִים בַּעֲבוֹדָתוֹ, כְּשֶׁזִּמֵּן אֶת יִשְׂרָאֵל בָּעוֹלָם הַזֶּה הִכְתִּירָם בִּכְתָרִים קְדוֹשִׁים כְּמוֹ שֶׁלְּמַעְלָה, הִשְׁרָה אוֹתָם בָּאָרֶץ הַקְּדוֹשָׁה כְּדֵי שֶׁיִּמָּצְאוּ בַעֲבוֹדָתוֹ, וְקָשַׁר אֶת כָּל הָעֶלְיוֹנִים עִם יִשְׂרָאֵל."],[2,"","וּשְׂמָחוֹת לֹא נִכְנָסוֹת לְפָנָיו, וַעֲבוֹדָה לֹא נַעֲשֵׂית לְפָנָיו לְמַעְלָה, עַד שֶׁיִּשְׂרָאֵל עוֹשִׂים לְמַטָּה. כָּל זְמַן שֶׁיִּשְׂרָאֵל נִמְצָאִים בַּעֲבוֹדַת רִבּוֹנָם לְמַטָּה, כָּךְ גַּם לְמַעְלָה. (כביכול) בִּזְמַן שֶׁיִּשְׂרָאֵל מְבַטְּלִים אֶת הָעֲבוֹדָה לְמַטָּה, הֵם מְבַטְּלִים לְמַעְלָה, וְהָעֲבוֹדָה לֹא נִמְצֵאת לֹא לְמַעְלָה וְלֹא לְמַטָּה. וְעַל שֶׁיִּשְׂרָאֵל בִּטְּלוּ אֶת עֲבוֹדָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁהָיוּ שְׁרוּיִים בָּאָרֶץ, כָּךְ גַּם לְמַעְלָה, כָּל שֶׁכֵּן אַחַר כָּךְ."],[3,"","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: יִשְׂרָאֵל, אִם אַתֶּם יוֹדְעִים כַּמָּה אוּכְלוּסִים וְכַמָּה חֲיָלוֹת מִתְעַכְּבִים בִּשְׁבִילְכֶם, תֵּדְעוּ שֶׁאֵינְכֶם כְּדָאִים לַעֲמֹד בָּעוֹלָם אֲפִלּוּ שָׁעָה אַחַת, וְעַל כָּל זֶה מַה כָּתוּב? (ויקרא כו) וְאַף גַּם זֹּאת בִּהְיוֹתָם בְּאֶרֶץ אֹיְבֵיהֶם לֹא מְאַסְתִּים וְגוֹ'. (משום כך) וְיָצָא אֶל הַמִּזְבֵּחַ, אֶל הַמִּזְבֵּחַ סְתָם, אֲשֶׁר לִפְנֵי ה' סְתָם. וְכִפֶּר עָלָיו אַחַר כָּךְ, וְיָצָא וְעָשָׂה אֶת עֹלָתוֹ וְאֶת עֹלַת הָעָם וְגוֹ'. וְכִפֶּר עָלָיו, מַה זֶּה אוֹמֵר? אָמַר רַבִּי יוֹסֵי, לְהָעִיר חֶסֶד בָּעוֹלָם בַּתְּחִלָּה."],[4,"","לָמַדְנוּ, וְכִפֶּר עַל הַקֹּדֶשׁ מִטֻּמְאֹת בְּנֵי יִשְׂרָאֵל. מַה זֶּה וְכִפֶּר עַל הַקֹּדֶשׁ? אֶלָּא אָמַר רַבִּי אֶלְעָזָר, הֲרֵי שָׁנִינוּ שֶׁהָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה, וּמְעוֹרְרִים דִּינִים, וְגוֹרְמִים לְטַמֵּא הַמִּקְדָּשׁ. וְהַנָּחָשׁ הַקָּשֶׁה מַתְחִיל לְהִגָּלוֹת, וְאָז מִתְעוֹרְרִים דִּינִים בָּעוֹלָם, וּבַיּוֹם הַזֶּה צָרִיךְ הַכֹּהֵן לְטַהֵר אֶת הַכֹּל וּלְהִתְעַטֵּר (ולעורר) הַכֶּתֶר הַקָּדוֹשׁ שֶׁלּוֹ, שֶׁהוּא רֹאשׁ הַמֶּלֶךְ, כְּדֵי שֶׁיָּבֹא הַמֶּלֶךְ לִשְׁרוֹת עִם הַגְּבִירָה. וּכְשֶׁרֹאשׁ הַמֶּלֶךְ נוֹסֵעַ, הַכֹּל נוֹסֵעַ, וְיָבא לְהִזְדַּוֵּג עִם הַגְּבִירָה וּלְעוֹרֵר שִׂמְחָה וּבְרָכוֹת בָּעוֹלָם. (כדי שיבא המלך להזדוג עם הגבירה ולעורר שמחה וברכות בעולם. וכשראש המלך נוסע, הכל נוסע)."],[5,"","נִמְצָא שֶׁכָּל הַשָּׁלוֹם (השלמות) שֶׁלְּמַעְלָה וּלְמַטָּה תְּלוּיָה בַּכֹּהֵן. שֶׁאִם הוּא מְעוֹרֵר אֶת הַכֶּתֶר שֶׁלּוֹ, הַכֹּל מִתְעוֹרֵר וְהַכֹּל נִמְצָא בִּשְׁלֵמוּת, וְעַל זֶה כָּתוּב וְכִפֶּר עַל הַקֹּדֶשׁ. בָּרִאשׁוֹנָה וְכִפֶּר עַל הַקֹּדֶשׁ, לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם וּלְהַרְבּוֹת שִׂמְחָה בָּעוֹלָם. וּכְשֶׁשִּׂמְחַת הַזִּוּוּג נִמְצֵאת עִם הַמֶּלֶךְ וְהַגְּבִירָה, כָּל הַשַּׁמָּשִׁים וְכָל בְּנֵי הַהֵיכָל, כֻּלָּם נִמְצָאִים בְּשִׂמְחָה (וכל שמחת העולם). וְכָל הַחֲטָאִים שֶׁחָטְאוּ לִפְנֵי הַמֶּלֶךְ, מִתְכַּפְּרִים לָהֶם. זֶהוּ שֶׁכָּתוּב מִכֹּל חַטֹאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ. וּמִשּׁוּם כָּךְ כָּתוּב, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבאוֹ לְכַפֵּר בַּקֹּדֶשׁ עַד צֵאתוֹ. בְּשָׁעָה שֶׁנִּכְנָס לְזַוֵּג אוֹתָם, וּבְשָׁעָה שֶׁמִּזְדַּוְּגִים הַמֶּלֶךְ עִם הַגְּבִירָה, אוֹתָהּ שָׁעָה - וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ."],[6,"","לָמַדְנוּ, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד. רַבִּי יִצְחָק פָּתַח, (שם) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְאַף אֶת בְּרִיתִי יִצְחָק וְגוֹ', וְהַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ. בּא וּרְאֵה, בְּשָׁעָה שֶׁיִּשְׂרָאֵל בַּגָּלוּת, כִּבְיָכוֹל הַקָּדוֹשׁ בָּרוּךְ הוּא עִמָּהֶם בַּגָּלוּת, שֶׁהֲרֵי הַשְּׁכִינָה לֹא זָזָה מֵהֶם לְעוֹלָמִים. בּא רְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל נִמְצְאוּ בְּגָלוּת בָּבֶל, הַשְּׁכִינָה שָׁרְתָה בֵינֵיהֶם וְשָׁבָה עִמָּהֶם מִן הַגָּלוּת, וּבִזְכוּת אוֹתָם הַצַּדִּיקִים שֶׁנִּשְׁאֲרוּ בָאָרֶץ, שָׁרְתָה בָאָרֶץ וְלֹא זָזָה מֵהֶם לְעוֹלָמִים. אָמַר רַבִּי יְהוּדָה, שֶׁחָזְרָה הַגְּבִירָה עִם הַמֶּלֶךְ, וְחָזַר הַכֹּל בִּסְעוּדַת הַשִּׂמְחָה שֶׁל הַמֶּלֶךְ, מִשּׁוּם כָּךְ נִקְרְאוּ אַנְשֵׁי כְּנֶסֶת הַגְּדוֹלָה, כְּנֶסֶת הַגְּדוֹלָה וַדַּאי."]]],[["תָּאנָא, בְּכָל זִמְנָא דְּיִשְׂרָאֵל בְּגָלוּתָא, אִי אִינּוּן זַכָּאִין, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים לְרַחֲמָא עָלַיְיהוּ, וּלְאַפָּקָא לוֹן מִגָּלוּתָא. וְאִי אִינּוּן לָא זַכָּאִין, מְעַכֵּב לוֹן בְּגָלוּתָא, עַד הַהוּא זִמְנָא דְּאִתְגְּזַר. וְכַד מָטָא זִמְנָא, וְאִינּוּן לָא אִתְחַזְיָין, קוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח לִיקָרָא דִּשְׁמֵיה, וְלָא אַנְשֵׁי לְהוּ בְּגָלוּתָא, הֲדָא הוּא דִכְתִיב וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְגוֹ'. אִלֵּין אֲבָהָן דְּכֹלָּא, רָזָא דִּשְׁמָא קַדִּישָׁא.","רִבִּי חִיָּיא אָמַר, מַאי טַעֲמָא יַעֲקֹב קַדְמָאָה הָכָא. אֶלָּא, בְּגִין דְּיַעֲקֹב כְּלָלָא דַּאֲבָהָן, וְהוּא אִילָנָא קַדִּישָׁא. בְּגִין כָּךְ, ו' דִּשְׁמָא קַדִּישָׁא בֵּיהּ אֲחִידָא, וְהָכִי קָרֵינָן יַעֲקוֹב בְּו'. רִבִּי יִצְחָק, אָמַר וָא\"ו בְּאַתְווֹי י\"ג מְכִילָן, דְּיָרִית יְרוּתָא דְּי\"ג מַבּוּעִין דְּמַבּוּעָא סְתִימָא קַדִּישָׁא.","רִבִּי אַבָּא אָמַר, וָא\"ו אֲמַאי כָּלִיל ו' א' ו'. אֶלָּא, ו' דְּיָתִיב עַל כּוּרְסְיָיא, כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. א' סָתִים בְּגַוִּיהּ וְלָא אִתְגַּלְיָיא, וְדָא הוּא דִּכְתִּיב, (בראשית כ״ב:ט״ז) בִּי נִשְׁבַּעְתִּי (ק\"ל ע\"א) נְאֻם יְיָ', בְּגִין כָּךְ כְּתִיב, וְלָא אִקְרֵי, בַּתְרָאָה, כְּלָלָא דְּקַדְמָאָה. בַּתְרָאָה, הָא אוֹקִימְנָא (נ\"א בתראה כללא דו' קדמאה ו' בתראה) דָּא יְסוֹד, דְּאִיהוּ סִיּוּמָא דְּגוּפָא, וּכְלָלָא דִּילֵיהּ. וְעַל דָּא כְּלִילָן אַתְוָון דָּא בְּדָא, וָא\"ו, רֵישָׁא וְסִיּוּמָא, כְּמָה דְּאוֹקִימְנָא.","וְתָאנָא, תְּרֵין אַתְוָון אִינּוּן, כְּהַאי גַּוְונָא וָא\"ו דַּאֲמֵינָא, נוּ\"ן אוּף הָכִי. וְאַף עַל גַּב דְּאוּקְמוּהָ מִלָּה, נוּ\"ן הָכִי מִתְפָּרְשָׁא: נ' כְּפוּפָה, דָּא מַטְרוֹנִיתָא. וּסְמִיכָא לָהּ ו', דְּאִיהוּ יְסוֹד, בְּגִין לְאִתְבָּרְכָא מִנֵּיהּ. ן' פְּשׁוּטָה, אִתְפַּשְּׁטוּתָא דְּתִפְאֶרֶת. וְעַל דָּא כְּלִילָן אַתְוָון, וּמִתְאַחֲדָן דָּא בְּדָא. וְאִי תֵּימָא, אֲמַאי אַהְדָּר ו' אַנְפּוֹי מִנּוּ\"ן כְּפוּפָה, וְאַהְדָּר אַנְפּוֹי לְגַבֵּי ן' פְּשׁוּטָה. אֶלָּא בְּגִין יְקָרָא דְּמַלְכָּא, אַהְדָּר אַנְפּוֹי לָקֳבְלֵיהּ דְּמַלְכָּא.","וְתָאנָא, מֵ\"ם לָא כָּלִיל בְּגַוָּיהּ אָת אָחֳרָא, (בגין) אֶלָּא מ' פְּתוּחָה, ם' סְתוּמָה. מ' פְּתוּחָה: דְּהוּא כַּד דְּכַר אִתְחַבָּר עִמָּהּ. ם' סְתוּמָה: יוֹבְלָא. דְּהָא סְתִימִין אֲרְחָהָא וְאַף עַל גַּב דְמִתְפַשְׁטִין לְזִמְנִין, וְאִית דְמַתְנֵי בְהַאי כְּמָה דְאַתְּ אָמֵר (שיר השירים ד׳:י״ב) גַּן נָעוּל אֲחוֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם.","אָמַר רִבִּי יִצְחָק, בְּשַׁעֲתָא דְּמַלְכָּא קַדִּישָׁא אַדְכַּר לְהוּ לְיִשְׂרָאֵל בְּגִין שְׁמֵיהּ, וְאָהַדְרַת מַטְרוֹנִיתָא לְאַתְרָהָא, (כדין) כְּתִיב, וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבֹאוֹ לְכַפֵּר בַּקֹּדֶשׁ. כַּךְ כַּהֲנָא, בְּשַׁעֲתָא דְּעָאל לְיַחֲדָא שְׁמָא קַדִּישָׁא, וּלְכַפְּרָא בְּקוּדְשָׁא, לְזַוְּוגָא לְמַלְכָּא בְּמַטְרוֹנִיתָא. כְּתִיב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד וְגוֹ'.","תָּאנָא, רִבִּי יְהוּדָה אָמַר, כַּהֲנָא אִתְּעַר שְׁלָמָא בְּעָלְמָא, לְעֵילָּא וְתַתָּא. וְתַנְיָא עָאל בְּדַרְגָּא חַד, אַסְחֵי גּוּפֵיהּ. נָפִיק מֵהַאי דַּרְגָּא, לְדַרְגָּא אָחֳרָא אַסְחֵי גּוּפֵיהּ. אָחִיד שְׁלָמָא בְּהַאי וּבְהַאי, קִדֵּשׁ יְדוֹי, וּמִתְבָּרְכָאן כַּחֲדָא. וּבְכֹלָּא בָּעֵי לְאַחֲזָאָה עוֹבָדָא, וּבָעֵי לְאַחֲזָאָה לְבוּשׁוֹי, דְּיִתְלַבָּשׁ כְּגַוְונָא דְּעוֹבָדָא דְּיִתְכַּוָּון, עַד דִּיסַדֵּר כֹּלָּא כְּמָה דְּאִצְטְרִיךְ, וְיִתְבָּרְכוּן עִלָּאֵי וְתַתָּאֵי.","תָּאנָא רִבִּי שִׁמְעוֹן, פָּתַח (ד') יוֹ\"ד בִּגְלִיפוֹי, אַתְוָון בְּסִטְרִין, אִתְקַשְּׁרָן בְּיוֹ\"ד. יוֹ\"ד אָזִיל לְיוֹ\"ד. (לוי\"ו) יוֹ\"ד סָלִיק בְּיוֹ\"ד. יוֹ\"ד אָזִיל לְוָי\"ו, מִתְכַּנְּשֵׁי בה'. וּמְכַוִּון דַּעְתָּא, אִתְחַבָּר ה' בְּוָא\"ו.","ה' עִלָּאָה אָחִיד תַּרְעוֹי (ס\"א בתרעוי) בְּגִלּוּפֵי תַּכְסִיסִין, אַחֲדָא בִּנְהִירוּ אֶלֶף וַחֲמֵשׁ מְאָה וְשִׁבְעִין אַכְסַדְרִין סְתִימִין. סָלִיק ה', וְאִתְעַטָּר חַמְשִׁין זִמְנִין, לָן' תַּרְעִין קַיְימִין דְּקַיְימִין, כַּד אִתְגְּלָף בְּעִטְרוֹי, נַהֲרִין אַנְפִּין דְּמַלְכָּא, וָא\"ו אִתְפְּשָׁט לְע\"ב גְּלִיפִין.","מְעַטֵּר ה' לְו', (נ\"א מתעטר ביו\"ד, ה' לו') בְּע' אֶלֶף וְה' מְאָה כִּתְרִין, דְּמִתְעַטְּרָן בְּחַד כִּתְרָא, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:י״א) בַּעֲטָרָה, שֶׁעִטְּרָה לּוֹ אִמּוֹ. ו' בִּתְרֵין רֵישִׁין, רֵישָׁא דְּגּוּלְגְלָתָא גְּלִיפָא רֵישָׁא, קוֹצָא חַד לְעֵילָּא, וְקוֹצָא חַד לְתַתָּא, וְי' נָחִית לְו', (ס\"א וא\"ו נחית לוא\"ו) גְּלִיפָא דְּגִלּוּפִין בְּגַּוַּיְיהוּ, שִׁבְעִין אַנְפִּין דְּעִטְרִין מֵעֵילָּא לְתַתָּא. בֵּיהּ טָאסִין גְּבִיעִין וּפַרְחִין, דָּא סָלִיק, וְדָא נָחִית מִתְגַּלְּפִין חַד בְּחַד.","אִתְקְשַּׁר י' בְּה', ה' בְּו', ו' בְּה'. (ס\"א ו' בה', ה' בו', ו' בו', ו' בה') דָּא אָחִיד בְּדָא, כְּמָה דְּאַתְּ אָמֵר, (בראשית מ״ט:כ״ד) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפֹזּוּ זְרוֹעֵי יָדָיו מִידֵי אֲבִיר יַעֲקֹב. וּכְתִיב, (במדבר כ״ד:כ״א) אֵיתָן מוֹשָׁבֶךָ וְשִׂים בַּסֶּלַע קִנֶּךָ. כְּדֵין אִתְקְשַּׁר כֹּלָּא חַד בְּחַד, דָא בְּדָא, נַהֲרִין מַפְתְּחָן, וְנַהֲרִין אַנְפִּין כֻּלְּהוּ, כְּדֵין כֻּלְּהוּ נַפְלִין עַל אַנְפַּיְיהוּ, וּמִזְדַּעְזְעָן, וְאַמְרֵי בְּרִיךְ שְׁמָא יְקָרָא מַלְכוּתֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין."],[[0,"תאנא בכל זמנא וכו׳:","למדנו, בכל זמן, שישראל הם בגלות, אם הם זכאים, הקב״ה מקדים לרחם עליהם ולהוציאם מן הגלות. ואם אינם זכאים מעכב אותם בגלות עד הזמן ההוא שנגזר, וכשהגיע הזמן, והם אינם ראוים להגאל, הקב״ה משגיח לכבוד שמו, ואינו שוכח אותם בגלות. ז״ש וזכרתי את בריתי יעקב וגו׳ שהם אבות הכל, דהיינו חג״ת, שה״ס השם הקדוש, הוי״ה. כי משגיח לכבוד שמו."],[1,"רבי חייא אמר וכו׳:","רח״א, מהו הטעם שיעקב נאמר כאן הראשון, שאומר וזכרתי את בריתי יעקב ואח״כ יצחק ואח״כ אברהם. ומשיב הוא משום שיעקב שהוא ת״ת, הוא כלל האבות, כי ת״ת כולל בתוכו את החסד והגבורה, הנקראים אברהם ויצחק. והוא אילן הקדוש, דהיינו ז״א, הכולל כל הו״ק, ע״כ ה \u0003ו׳\u0004 של השם הקדוש הויה, נאחזת בו, ואנו קורים כך \u0003יעקוב\u0004 עם \u0003ו׳.\u0004 ר׳ יצחק אמר ואו במילוי אותיותיו, הוא בגימטריא י״ג, והיינו י״ג מדות הרחמים, שיעקב שהוא ז״א, יורש ירושת י״ג מבועים של המבוע הסתום הקדוש, שהוא א״א. שמדיקנא שלו נמשכים י״ג תיקונים לז\"א שנקרא יעקב. וע״כ כתוב יעקב עם \u0003ו'.\u0004"],[2,"ר׳ אבא אמר וכו׳:","רא״א \u0003ו׳\u0004 למה כלולה \u0003ו׳ א' ו׳\u0004 במבטא ומשיב, אלא \u0003ו',\u0004 שהוא ז״א, הוא היושב על הכסא, על המלכות שנקראת כסא, כש״א, ועל דמות הכסא דמות כמראה אדם עליו מלמעלה, שהוא ז״א. \u0003א׳\u0004 סתומה בתוך הואו, ואינה מתגלה, כי \u0003א׳ היא א״א\u0004 המלובש מטבורו ולמטה בז״א, ואינו מתגלה לחוץ מז״א, וז״ש \u0003בי\u0004 נשבעתי נאם ה'. כי ז״א נשבע, בא״א המלובש בתוכו, ומשום זה ה \u0003א׳\u0004 היא כתובה ולא נקראת, כלומר כשאנו קורים \u0003ואו\u0004 ה \u0003א'\u0004 נחה ואינה נשמעת במבטא, משום שרומזת על א״א שהוא סתום ובלתי מושג. \u0003ו׳\u0004 האחרונה, היא כלל הראשונה, והעמדנו ש \u0003ו׳\u0004 האחרונה, היא יסוד, שהוא סיום הגוף, שהוא ת״ת, וכלל שלו. שהוא כלול בגוף. וע״כ כלולות האותיות זו בזו \u0003ואו\u0004 שהוא ראש וסוף, דהיינו ת״ת ויסוד שהם אחד, וה \u0003א׳\u0004 היא א״א המלובש בת״ת, כמו שהעמדנו."],[3,"ותאנא תרין אתוון וכו׳:","ולמדנו, אלו ב׳ אותיות, באותו האפן שאמרתי ב \u0003ואו,\u0004 הוא גם כן ב \u0003נון.\u0004 ואע״פ שהעמידו הדבר בדרך אחר, הרי הנון מתבארת כך, ה \u0003נ׳\u0004 כפופה זו היא המלכה. ונסמכת לה \u0003ו׳\u0004 שהוא יסוד, כדי שהמלכות תתברך ממנו. ה \u0003ן׳\u0004 פשוטה, היא התפשטות ת״ת. וע״כ כלולות האותיות ומתאחדות זו בזו. כי ת״ת שהוא \u0003ן׳\u0004 פשוטה משפיע ליסוד שהוא \u0003ו',\u0004 והיסוד משפיע למלכות, שהיא \u0003נ׳\u0004 כפופה. ואם תאמר, למה ה \u0003ו',\u0004 מחזרת פניה מן ה \u0003נ׳\u0004 הכפופה, ונותנת פניה אל ה \u0003ן׳\u0004 הפשוטה. אלא הוא משום כבוד המלך, שהוא \u0003ן׳\u0004 פשוטה דהיינו ת״ת כנ״ל, ע״כ היסוד מחזיר פניו כנגד המלך. כלומר, שהיסוד ות״ת הם תמיד כאחד כנ״ל בדבור הסמוך."],[4,"ותאנא מם לא וכו׳:","ולמדנו, ה \u0003מם\u0004 אינה כוללת בתוכה אות אחרת, כי אות המילוי היא ג״כ \u0003ם׳,\u0004 אלא שהיא \u0003מ׳\u0004 פתוחה ו \u0003ם׳\u0004 סתומה. \u0003מ׳\u0004 פתוחה מורה, שהמלכות היא בזמן כשהדכר מתחבר עמה, והיא פתוחה לקבל ממנו השפע. \u0003ם׳\u0004 סתומה מורה על יובל, שהיא בינה, שדרכיה סתומים, וע״כ גם ה \u0003ם'\u0004 סתומה מכל צדדיה. ואע״פ שהבינה מתפשטת לפעמים, מ״מ נחשבת שהיא סתומה. ויש שלומד בזה, כמו שאתה אומר, גן נעול אחותי כלה גן נעול מעין חתום. דהיינו שגם ה \u0003ם׳\u0004 הסתומה רומזת על מלכות, בהיותה נקראת, מעין חתום."],[5,"א״ר יצחק בשעתא וכו׳:","אר״י, בשעה שהמלך הקדוש זוכר את ישראל למען שמו, ומחזיר את המלכה למקומה, אז כתוב, וכל אדם לא יהיה באהל מועד בבאו לכפר בקדש. כך הכהן בשעה שנכנס ליחד השם הקדוש, ולכפר בקדש, לזווג המלך והמלכה, כתוב וכל אדם לא יהיה באהל מועד וגו'."],[6,"תאנא ר׳ יהודה וכו׳:","למדנו, רי״א, הכהן מעורר שלום בעולם למעלה ולמטה. ולמדנו נכנס במדרגה אחת, של המלכות, רוחץ גופו. יצא ממדרגה זו למדרגה אחרת, של ז״א, רוחץ גופו. ומאחז השלום בזה ובזה, בז\"א ובמלכות, מקדש ידיו, ומתברכים יחד. ובכל דבר צריך להראות מעשה למטה כדי לעורר כנגדו למעלה, וצריך להראות הלבושים שמתלבש שיהיו כעין המעשה, שיכוון עד שמסדר הכל כמו שצריך, ויתברכו עליונים ותחתונים."],[7,"תאנא ר״ש, פתח וכו׳:","ר׳ שמעון למד. ה \u0003י׳\u0004 פותחת בחקיקותיה, ומתפשטות האותיות בצדדים, דהיינו כל אות משם הויה מתפשטת בג׳ קוים, ומתקשרות ב \u0003י׳.\u0004 שכל קו מהן, נקשר ב \u0003י׳,\u0004 שהיא חכמה וקו ימין. ומפרש. ה \u0003י׳\u0004 הולכת ל \u0003י׳.\u0004 דהיינו החכמה, שה\"ס \u0003י׳\u0004 ראשונה של השם יאהדונה״י, הולכת ומתפשטת עד ה \u0003י׳\u0004 האחרונה, שהיא המלכות. כי מתפשטת באור ישר עד המלכות. ה \u0003י׳,\u0004 שהיא מלכות, עולה ל \u0003י׳,\u0004 שהיא חכמה. שהמלכות מעלה אור חוזר עד החכמה, ונכללת החכמה בעשר ספירות שז״ס ה \u0003י׳\u0004 פותחת בחקיקותיה. ואח״כ ה \u0003י׳,\u0004 שהיא חכמה, הולכת ל \u0003ו׳.\u0004 שהיא ז״א, דהיינו שמתפשטת לז״א, ונעשית ראש ה \u0003ו׳.\u0004 אמנם תחילה מתקבצים, האורות של החכמה, ב \u0003ה׳,\u0004 שהיא בינה, ומכוונת את הדעת, שהדעת מכוונת באמצע בין חכמה לבינה, ואח״כ נתחברה \u0003ה׳\u0004 ב \u0003ו׳.\u0004 שהאורות דבינה, שהיא ה׳ ראשונה דהויה, מתחברות ובאות ב \u0003ו׳\u0004 דהויה, שהוא ז״א."],[8,"ה׳ עלאה אחיד וכו׳:","עתה מפרש ג׳ הקוין שבבינה ואיך כל אחת נקשרת ב \u0003י׳\u0004 שהיא חכמה. ואומר, \u0003ה׳\u0004 עליונה שבשם הויה, שהיא בינה, אוחזת שעריה, דהיינו נ׳ שערי בינה שלה, בחקיקות תכסיסים, דהיינו חקיקות מסודרות, שה״ס העלאת המלכות לבינה, והורדתה בחזרה למקומה, שמזה יוצאים ג׳ קוין בבינה (כנ״ל באות קס״א) ואז, אוחזת בהארת אלף וחמש מאות ושבעים אכסדרות סתומות. אלף ה״ס חכמה, וקו ימין. וחמש מאות ה״ס בינה וקו שמאל, ושבעים ה״ס הדעת, קו האמצעי. ומצד שהמוחין אלו הם שורשים להארת החכמה, הם נקראים אכסדרות, שהן פתוחות לכל עבר. ומצד שאין כאן מקום הארתם כי בבינה שולט החסד ולא החכמה, הן נבחנות לסתומות, כי לא יפתחו אלא במלכות, ששם מקום שליטתם. וכל ג׳ קוין האלו הם החכמה שבבינה, וקו ימין שלה, הוכלל מג׳ קוין. ואח\"כ עולה ה \u0003ה׳.\u0004 שהיא בינה, ומתעטרת חמשים פעמים, לחמשים שערי בינה שלה, שהם קיום של כל קיום. שה״ס הבינה של הבינה, ובחינת קו שמאל שלה, שהוא שורש כל המוחין הנקראים קיום. וכאשר נחקקה, הבינה, בעטרותיה, דהיינו ב׳ עטרין שלה שה״ס הדעת שלה, מאירים מכאן פני המלך, שהוא ז״א. כי כל האורות דז״א נמשכים מב׳ עטרין אלו, בסוד תלת נפקי מחד, חד בתלת קיימא (כנ״ל ב״א דף רפ״ז ד״ה תלת) וה \u0003ו׳\u0004 מתפשטת באלו האורות, לע״ב חקיקות, דהיינו השם ע״ב. כי ה \u0003ו׳\u0004 כוללת \u0003ו׳\u0004 קצוות חג״ת נה״י, ובכל קצה מאירות י״ב בחינות, שה״ס חו״ב תו״מ שבכל אחת ג׳ קוין, וששה פעמים י״ב הם ע״ב. ונתבאר איך ג׳ קוין חב״ד דבינה נקשרים בחכמה."],[8,"","המוחין דחכמה מכונים אלף, בסו״ה ואאלפך חכמה. המוחין דבינה מכונים חמש מאות ע״ש ה׳ ספירות שלה חג״ת נ״ה, שספירותיה בסוד מאות. ומוח הדעת מכונה שבעים, ע״ש חג״ת נהי״ם שלו, כי ספירות דז״א בסוד עשרות. ומה שאנו חושבים בבינה רק חג״ת נ״ה, ולא יסוד ומלכות, הוא מטעם כי בינה עד הוד התפשטותה, ולא יותר. הדעת נבחנת לשתי עטרין, כי חג״ת נה״י שבדעת הם \u0003עיטרא\u0004 דחסד, והמלכות שבדעת היא \u0003עיטרא\u0004 דגבורה."],[9,"מעטר ה׳ לו׳ וכו׳:","אחר שנתפשטו ג׳ קוי חב״ד בבינה שה״ס \u0003ה'\u0004 היא מעטרת ה \u0003ו׳,\u0004 ב \u0003ע׳\u0004 אלף וחמש מאות כתרים. ז״ס דחכמה חג״ת נה״י ה״ס ע׳ אלף, שהוא קו ימין. וחג״ת נ״ה דבינה ה״ס חמש מאות, שהם קו שמאל, שהם מתעטרים בעטרה אחת, שה״ס הדעת, המאחדת וכוללת אותם. ז״ש, בעטרה שעטרה לו אמו, כי הבינה היא אמו של ה \u0003ו׳\u0004 שהוא ז״א. ונמצא אשר ה \u0003ו׳,\u0004 בב׳ ראשים חקוק הראש שלו, דהיינו חכמה ובינה, וע״כ נכתבים ב׳ קוצין בראש ה \u0003ו',\u0004 קוץ אחד למעלה, רומז על חכמה, קוץ אחד למטה, רומז על בינה. וה \u0003י׳,\u0004 שהוא חכמה, יורד אז לה \u0003ו'\u0004 דהיינו שה \u0003ו׳\u0004 נקשרה ביוד כמו ה \u0003ה'.\u0004 החקיקה דכל החקיקות, שהוא קו האמצעי, ביניהם דב׳ ראשים, שהוא ע׳ פנים המעטרים מלמעלה למטה, דהיינו דעת המתפשטת ממעלה למטה. שהוא חג״ת נהי״מ, שכל אחת כלולה מעשר, והם ע'. בו מעופפים גביעים ופרחים, שהדעת נחלקת לב׳ חלקים, אורות הימין שבו נקראים גביעים, ואורות השמאל שלו נקראים פרחים, זה עולה, דהיינו הפרחים, להיותם בהארת חכמה,שאינה מאירה אלא ממטה למעלה. וזה יורד, דהיינו האורות דימין שמשפיעים ממעלה למטה. ונחקקים זה בזה, שאורות דימין נכללים באורות דשמאל."],[10,"אתקשר י׳ בה׳ וכו׳:","ה \u0003י׳\u0004 נקשרה ב \u0003ה',\u0004 וה \u0003ה׳\u0004 ב \u0003ו',\u0004 וה \u0003ו׳\u0004 ב \u0003ה׳.\u0004 זה אחוז בזה. דהיינו ה \u0003ו׳,\u0004 שהוא ז״א, אחוז ב \u0003ה׳\u0004 שהיא המלכות. כמו שאתה אומר, ותשב \u0003באיתן קשתו\u0004 ויפזו זרועי ידיו מידי אביר יעקב. אשר איתן, הוא יסוד, קשתו, היא המלכות. הרי שהיסוד דז״א אחוז במלכות. וכתוב, \u0003איתן\u0004 מושבך ושים \u0003בסלע\u0004 קנך. אשר איתן הוא יסוד, וסלע הוא מלכות. אז נקשרו הכל אחד באחד זה בזה, מאירים המפתחות בהארת החכמה, שהם כל בחינות קו האמצעי, שנקרא מפתח, להיותו הפותח את הארת החכמה, ע״י הכרעתו את הימין ואת השמאל, ומאירים כל הפנים כולם, שה״ס ע׳ פנים הנ״ל. אז כולם נופלים על פניהם, דהיינו שמסתירים את פניהם שלא להמשיך ממעלה למטה שהיא בחינת ג״ר דחכמה, שנתמעטו ע״י קו האמצעי (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) ומזדעזעים, מחמת הדינים המתגלים עם הארת החכמה, ואומרים, ברוך שם כבוד מלכותו לעולם ולעולמי עולמים."]],[[0,"","לָמַדְנוּ, בְּכָל זְמַן שֶׁיִּשְׂרָאֵל בַּגָּלוּת, אִם הֵם צַדִּיקִים - הַקָּדוֹשׁ בָּרוּךְ הוּא מַקְדִּים לְרַחֵם עֲלֵיהֶם וּלְהוֹצִיאָם מֵהַגָּלוּת, וְאִם הֵם אֵינָם צַדִּיקִים - הוּא מְעַכֵּב אוֹתָם בַּגָּלוּת עַד אוֹתוֹ זְמַן שֶׁנִּגְזַר. וּכְשֶׁמַּגִּיעַ הַזְּמַן וְהֵם אֵינָם רְאוּיִים - הַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ עַל כְּבוֹד שְׁמוֹ, וְאֵינוֹ שׁוֹכֵחַ אוֹתָם בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב וְגוֹ'. אֵלּוּ הָאָבוֹת שֶׁל הַכֹּל, סוֹד הַשֵּׁם הַקָּדוֹשׁ."],[1,"","רַבִּי חִיָּיא אָמַר, מָה הַטַּעַם יַעֲקֹב רִאשׁוֹן כָּאן? אֶלָּא מִשּׁוּם שֶׁיַּעֲקֹב הוּא כְּלַל הָאָבוֹת, וְהוּא הָעֵץ הַקָּדוֹשׁ. מִשּׁוּם כָּךְ ו' שֶׁל הַשֵּׁם הַקָּדוֹשׁ אֲחוּזָה בּוֹ, וְכָךְ קוֹרְאִים יַעֲקוֹב בְּו'. רַבִּי יִצְחָק אָמַר, וָא\"ו בְּאוֹתִיּוֹתָיו שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת, שֶׁיָּרַשׁ יְרֻשָּׁה שֶׁל שְׁלֹשָׁה עָשָׂר מַעְיָנוֹת שֶׁל הַמַּעְיָן הַנִּסְתָּר הַקָּדוֹשׁ."],[2,"","רַבִּי אַבָּא אָמַר, וָא\"ו לָמָּה כּוֹלֶלֶת ו' א' ו'? אֶלָּא, ו' שֶׁיּוֹשֵׁב עַל הַכִּסֵּא, כְּמוֹ שֶׁנֶּאֱמַר (יחזקאל א) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. א' נִסְתֶּרֶת בְּתוֹכוֹ וְלֹא מְגֻלֶּה, וְזֶהוּ שֶׁכָּתוּב (בראשית כב) בִּי נִשְׁבַּעְתִּי נְאֻם ה', מִשּׁוּם כָּךְ כָּתוּב, וְלֹא נִקְרָא אַחֲרוֹן כְּלָל שֶׁל הָרִאשׁוֹן. הָאַחֲרוֹן, הֲרֵי בֵּאַרְנוּ (ו' אחרונה כלל של ו' ראשונה, ו' אחרונה) זֶה יה\"ו יְסוֹד, שֶׁהוּא סִיּוּם הַגּוּף וְהַכְּלָל שֶׁלּוֹ. וְעַל כֵּן כְּלוּלוֹת הָאוֹתִיּוֹת זוֹ עִם זוֹ - וָא\"ו, רֹאשׁ וְסִיּוּם, כְּמוֹ שֶׁבֵּאַרְנוּ."],[3,"","וְלָמַדְנוּ, שְׁתֵּי אוֹתִיּוֹת הֵן, כְּמוֹ זֶה וָא\"ו שֶׁאָמַרְנוּ, נוּ\"ן אַף כָּךְ. וְאַף עַל גַּב שֶׁבֵּאֲרוּ אֶת הַדָּבָר, נוּ\"ן כָּךְ מִתְפָּרֶשֶׁת: נ' כְּפוּפָה זוֹ הַגְּבִירָה. וּסְמוּכָה לָהּ ו', שֶׁהוּא יְסוֹד, כְּדֵי שֶׁתִּתְבָּרֵךְ מִמֶּנּוּ. ן' פְּשׁוּטָה, זוֹ הִתְפַּשְּׁטוּת הַתִּפְאֶרֶת. וְלָכֵן כְּלוּלוֹת הָאוֹתִיּוֹת וְנֶאֱחָזוֹת זוֹ בָּזוֹ. וְאִם תֹּאמַר, לָמָּה מַחֲזִיר ו' פָּנָיו מִנּוּ\"ן כְּפוּפָה, וּמַחֲזִיר פָּנָיו אֶל הַן' הַפְּשׁוּטָה. אֶלָּא בִּשְׁבִיל כְּבוֹד הַמֶּלֶךְ הוּא מַחֲזִיר פָּנָיו כְּנֶגֶד הַמֶּלֶךְ."],[4,"","וְלָמַדְנוּ, מֵ\"ם לֹא כוֹלֶלֶת בְּתוֹכָהּ אוֹת אַחֶרֶת, (משום) אֶלָּא מ' פְּתוּחָה, ם' סְתוּמָה. מ' פְּתוּחָה - שֶׁהוּא כְּשֶׁהַזָּכָר מִתְחַבֵּר עִמָּהּ. ם' סְתוּמָה - יוֹבֵל. שֶׁהֲרֵי נִסְתָּרִים דְּרָכֶיהָ וְאַף עַל גַּב שֶׁלִּפְעָמִים מִתְפַּשְּׁטִים, וְיֵשׁ שֶׁשּׁוֹנִים בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (שיר ד) גַּן נָעוּל אֲחֹתִי כַלָּה גַּל נָעוּל מַעְיָן חָתוּם."],[5,"","אָמַר רַבִּי יִצְחָק, בְּשָׁעָה שֶׁהַמֶּלֶךְ הַקָּדוֹשׁ זוֹכֵר אֶת יִשְׂרָאֵל בַּעֲבוּר שְׁמוֹ וְחוֹזֶרֶת הַגְּבִירָה לִמְקוֹמָהּ, (אז) כָּתוּב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד בְּבאוֹ לְכַפֵּר בַּקֹּדֶשׁ. כָּךְ הַכֹּהֵן, בְּשָׁעָה שֶׁנִּכְנָס לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ וּלְכַפֵּר בַּקֹּדֶשׁ, לְזַוֵּג אֶת הַמֶּלֶךְ עִם הַגְּבִירָה, כָּתוּב וְכָל אָדָם לֹא יִהְיֶה בְּאֹהֶל מוֹעֵד וְגוֹ'."],[6,"","לָמַדְנוּ, רַבִּי יְהוּדָה אָמַר, הַכֹּהֵן מְעוֹרֵר שָׁלוֹם בָּעוֹלָם, לְמַעְלָה וּלְמַטָּה. וְלָמַדְנוּ, נִכְנָס בְּדַרְגָּה אַחַת, רוֹחֵץ גּוּפוֹ. יוֹצֵא מִדַּרְגָּה זוֹ לְדַרְגָּה אַחֶרֶת, רוֹחֵץ גּוּפוֹ. אוֹחֵז שָׁלוֹם בָּזֶה וּבָזֶה. קִדֵּשׁ יָדָיו, וּמִתְבָּרְכִים כְּאֶחָד. וּבַכֹּל צָרִיךְ לְהַרְאוֹת מַעֲשֶׂה, וְצָרִיךְ לְהַרְאוֹת לְבוּשׁוֹ שֶׁיִּתְלַבֵּשׁ כְּגוֹן שֶׁהַמַּעֲשֶׂה יִתְכַּוֵּן, עַד שֶׁיְּסַדֵּר הַכֹּל כְּמוֹ שֶׁצָּרִיךְ, וְיִתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים."],[7,"","לָמַדְנוּ, רַבִּי שִׁמְעוֹן פָּתַח, (ד') יוֹ\"ד בַּחֲקִיקוֹתָיו, אוֹתִיּוֹת בַּצְּדָדִים הִתְקַשְּׁרוּ בְיוֹ\"ד. יוֹ\"ד הוֹלֵךְ לְיוֹ\"ד (לוי\"ו). יוֹ\"ד עוֹלֶה בְיוֹ\"ד. יוֹ\"ד הוֹלֵךְ לְוָי\"ו, מִתְכַּנְּסִים בְּה'. וּמְכַוֵּן אֶת הַדַּעַת, וּמִתְחַבְּרִים ה' עִם וָא\"ו."],[8,"","ה' עֶלְיוֹנָה אוֹחֶזֶת שְׁעָרֶיהָ (בשעריה) בְּחִקּוּקֵי תַכְסִיסִים, אוֹחֶזֶת בְּהֶאָרַת אֶלֶף וַחֲמֵשׁ מֵאוֹת וְשִׁבְעִים אַכְסַדְרוֹת נִסְתָּרוֹת. עוֹלָה ה', וּמִתְעַטֶּרֶת חֲמִשִּׁים פְּעָמִים לַחֲמִשִּׁים שְׁעָרִים עַמּוּדִים שֶׁעוֹמְדִים. כְּשֶׁמִּתְגַּלֵּף בְּעַטְרוֹתָיו, מְאִירִים פְּנֵי הַמֶּלֶךְ, וָא\"ו מִתְפַּשֶּׁטֶת לְשִׁבְעִים וּשְׁתַּיִם חֲקִיקוֹת."],[9,"","מְעַטֶרֶת ה' אֶת ו' (נ\"א מתעטר ביו\"ד, ה' לו') בְּשִׁבְעִים אֶלֶף וַחֲמֵשׁ מֵאוֹת כְּתָרִים שֶׁמִּתְעַטְּרִים בְּכֶתֶר אֶחָד. זֶהוּ שֶׁכָּתוּב (שם ג) בָּעֲטָרָה שֶׁעִטְּרָה לּוֹ אִמּוֹ. ו' בִּשְׁנֵי רָאשִׁים, רֹאשׁ הַגֻּלְגֹּלֶת חָקוּק הָרֹאשׁ שֶׁלּוֹ, קוֹץ אֶחָד לְמַעְלָה וְקוֹץ אֶחָד לְמַטָּה, וְי' יוֹרֶדֶת לְו', חֲקִיקַת הַחֲקִיקוֹת בְּתוֹכָם, שִׁבְעִים פָּנִים שֶׁל עֲטָרוֹת מִמַּעְלָה לְמַטָּה. בּוֹ טָסִים גְּבִיעִים וּפְרָחִים, זֶה עוֹלֶה וְזֶה יוֹרֵד, וְנֶחְקָקִים אֶחָד עִם אֶחָד."],[10,"","נִקְשֶׁרֶת י' עִם ה', ה' עִם ו', ו' עִם ה' (ו' בה', ה' בו', ו' בו', ו' בה'). זֶה אָחוּז בָּזֶה, כְּמוֹ שֶׁנֶּאֱמַר (בראשית מט) וַתֵּשֶׁב בְּאֵיתָן קַשְׁתּוֹ וַיָּפֹזּוּ זְרוֹעֵי יָדָיו מִידֵי אֲבִיר יַעֲקֹב. וְכָתוּב, (במדבר כד) אֵיתָן מוֹשָׁבֶךְ וְשִׂים בַּסֶּלַע קִנֶּךְ. אָז הַכֹּל מִתְקַשֵּׁר אֶחָד עִם אֶחָד, זֶה עִם זֶה, מְאִירִים הַמַּפְתְּחוֹת וּמְאִירִים כָּל הַפָּנִים. אָז כֻּלָּם נוֹפְלִים עַל פְּנֵיהֶם וּמִזְדַּעְזְעִים וְאוֹמְרִים: בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."]]],[["קָלָא מִתְקַשָּׁר עִמֵּיהּ דְּכַהֲנָא, וְהוּא אָתִיב לְגַבַּיְיהוּ. וְאָמַר תִּטְהָרוּ. תִּטְהָרוּ לָא אַמְרִין שְׁאַר כַּהֲנֵי וְעַמָּא, בַּר כַּהֲנָא רַבָּא, כַּד אִתְקְשַּׁר בֵּיהּ הַהוּא קָלָא.","תָּאנָא, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ', כֵּיוָן דִּכְתִּיב מִכֹּל חַטֹּאתֵיכֶם, אֲמַאי לִפְנֵי יְיָ'. אֶלָּא אָמַר רִבִּי יִצְחָק, (שמות ק\"ע ע\"ב) לִפְנֵי יְיָ' מַמָּשׁ.","דְּתַנְיָא, מֵרֵישָׁא דְּיַרְחָא סִפְרִין פְּתִיחִין, וְדַיְינֵי דַּיָּינִין. בְּכָל יוֹמָא וְיוֹמָא בָּתֵּי דִּינִין אִתְמַסְרָן, לְאִתְּפַתְחָא בְּדִינָא, עַד הַהוּא יוֹמָא דְּאִקְרֵי תִּשְׁעָה לְיַרְחָא. בְּהַהוּא יוֹמָא, סַלְּקִין דִּינִין כֻּלְּהוּ לְמָארֵי דְּדִינָא, וּמְתַקְּנֵי כּוּרְסְיָיא עִלָּאָה דְּרַחֲמֵי, לְמַלְכָּא קַדִּישָׁא. בְּהַהוּא יוֹמָא בָּעָאן יִשְׂרָאֵל לְתַתָּא, לְמֶחְדֵּי בְּחֶדְוָותָא לְקַדְמוּת מָארֵיהוֹן, דְּזַמִּין לְיוֹמָא אָחֳרָא, לְמֵיתַב עָלַיְיהוּ בְּכוּרְסְיָיא קַדִּישָׁא דְּרַחֲמֵי, בְּכוּרְסְיָיא דְּוַותְּרָנוּתָא.","וְכָל אִינּוּן סִפְרִין דִּפְתִּיחִין קָמֵיהּ, וּכְתִיבִין קָמֵיהּ כָּל אִינּוּן חוֹבִין, הוּא מְזַכֵּי לוֹן, וּמַדְכֵּי לוֹן מְכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי יְיָ' תִּטְהָרוּ. לִפְנֵי יְיָ' מַמָּשׁ, אִינּוּן דְּאַמְרֵי קְרָא, עַד הָכָא אַמְרִין, וְלָא יַתִּיר. וְלֵית רְשׁוּ לְאָחֳרָא דְּלִימָא תִּטְהָרוּ, אֶלָּא כַּהֲנָא רַבָּא, דְּפָלַח פּוּלְחָנָא, וְקָשַׁר שְׁמָא קַדִּישָׁא בְּפוּמֵיהּ, וְכַד הֲוָה אִתְקְשַׁר וּמִתְבָּרֵךְ בְּפוּמֵיהּ, הַהוּא קָלָא נָחִית וּבָטַשׁ בֵּיהּ, וְאִתְנְהִיר מִלָּה בְּפוּמֵיהּ דְּכַהֲנָא, וְאוֹמֵר תִּטְהָרוּ. פָּלַח פּוּלְחָנָא, וּמִתְבָּרְכִין כָּל אִינּוּן עִלָּאִין דְּאִשְׁתָּאָרוּ.","וּלְבָתַר אַסְחֵי גּוּפֵיהּ, וְקִדֵּשׁ יְדוֹי, לְאַעֲלָא בְּפוּלְחָנָא אָחֳרָא קַדִּישָׁא. עַד דְּיִתְכַּוָּון לְמֵיעַל לַאֲתַר אָחֳרָא עִלָּאָה, קַדִּישָׁא מִכֹּלָּא. ג' שׁוּרִין סָחֲרִין לֵיהּ, כַּהֲנֵי אָחוֹי, וְלֵיוָאֵי, וּמִכָּל שְׁאָר עַמָּא כֻּלְּהוּ. (ברכאן קמיה) זַקְפִין יְדִין עָלֵיהּ בִּצְלוֹתָא וְקִטְרָא דְּדַהֲבָא זַקְפָא בְּרַגְלֵיהּ. נָטִיל ג' פְּסִיעָן, וְכֻלְּהוּ קַיְימִין בְּקִיּוּמַיְיהוּ, וְלָא נַטְלִין בַּתְרֵיהּ (הוה אקטיר קטורת).","נָטִיל ג' פְּסִיעָן אָחֳרָן, (רשימא בלבא) אַסְחַר לְדוּכְתֵּיהּ. נָטִיל ג' פְּסִיעָן, אַסְתִּים עַיְינִין, וְאִתְקְשַׁר לְעֵילָּא. עָאל לַאֲתַר דְּעָאל, שָׁמַע קוֹל גַּדְפֵּי דִּכְרוּבַיָּיא מְזַמְּרִין, וְאָקִישָׁן גַּדְפִּין פְּרִישָׂאן לְעֵילָּא. הֲוָה אַקְטִיר קְטוֹרֶת, מִשְׁתַּכְּכָא קוֹל גַּדְפַּיְיהוּ וּבִלְחִישׁוּ אִתְדַּבְּקָן.","אִי כַּהֲנָא זָכֵי, דְּהָא לְעֵילָּא בְּחֵידוּ אִשְׁתְּכַח, אוּף הָכָא בְּהַהִיא שַׁעֲתָא נָפִיק רַעֲוָא דִּנְהוֹרָא, מִתְבַּסְּמָא מֵרֵיחִין דְּטוּרֵי אֲפַרְסְמוֹנָא דַּכְיָא דִּלְעֵילָּא, וְאַזְלָא בְּכָל הַהוּא אֲתַר, אָעִיל רֵיחָא בִּתְרֵי נוּקְבֵי דְּחוּטָמֵיהּ, וְאִתְיָישְׁבָא לִבָּא. כְּדֵין כֹּלָּא הוּא בִּלְחִישׁוּ, וּפִטְרָא לָא אִשְׁתְּכַח תַּמָּן. פָּתַח כַּהֲנָא פּוּמֵיהּ בִּצְלוֹתָא בִּרְעוּתָא בְּחֶדְוָותָא, וְצַלֵּי צְלוֹתֵיהּ.","בָּתַר דְּסִיֵּים, זַקְפִין כְּרוּבְיָיא כְּמִלְּקַדְּמִין גַּדְפַּיְיהוּ, וּמְזַמְּרִין. כְּדֵין יָדַע כַּהֲנָא דִּרְעוּתָא הֲווֹ, וְעִידָּן חֶדְוָותָא לְכֹלָּא, וְעַמָּא יַדְעִין דְּאִתְקַבֵּל צְלוֹתֵיהּ, כְּמָה דִּכְתִּיב, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהוּא תָּב לַאֲחוֹרֵיהּ, וְצַלֵּי צְלוֹתֵיהּ. זַכָּאָה חוּלָקֵיהּ דְּכַהֲנָא, דְּהָא עַל יְדוֹי חֵידוּ עַל חֵידוּ אִשְׁתְּכַח הַהוּא יוֹמָא לְעֵילָּא וְתַתָּא, עַל הַהִיא שַׁעֲתָא כְּתִיב, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ, אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו.","(ויקרא ט״ז:כ״ט) וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם וְגוֹ'. רִבִּי חִיָּיא פָּתַח, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ וְגוֹ'. נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה. נַפְשִׁי בַּלַּיְלָה מִבָּעֵי לֵיהּ, מַאי נַפְשִׁי אִוִּיתִיךָ. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָ מִבָּעֵי לֵיהּ. אֶלָּא הָכִי תָּאנָא, קוּדְשָׁא בְּרִיךְ הוּא רוּחָא וְנַפְשָׁא דְּכֹלָּא, וְיִשְׂרָאֵל אַמְרֵי נַפְשִׁי וְרוּחִי אַנְּתְּ. בְּגִין כַּךְ אִוִּיתִיךָ לְאַדְבְּקָא בָּךְ, וַאֲשַׁחֲרֶךָ לְאַשְׁכְּחָא רְעוּתָךְ.","רִבִּי יוֹסֵי אָמַר, בְּשַׁעֲתָא דְּבַּר נָשׁ נָאִים בְּעַרְסֵיהּ. נָפְקָא נַפְשֵׁיהּ, סַלְקָא וְאַסְהִידַת בֵּיהּ בְּבַּר נָשׁ, עַל כָּל מַה דַּעֲבַד בְּכָל יוֹמָא. גּוּפָא אָמַר לְנַפְשָׁא, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ."],[[0,"קלא מתקשר עמיה וכו׳:","קול, שהוא ז״א, קו האמצעי, מתקשר עם הכהן, כלומר, שהכהן נעשה מרכבת לז\"א, והוא משיב להם ואמר \u0003תטהרו.\u0004 שלהיותו מרכבה לקו האמצעי משפיע להם הארת החכמה המביאה לכפרת עונות וטהרה. \u0003תטהרו,\u0004 אינם אומרים שאר הכהנים והעם. חוץ מכהן גדול בעת שנקשר בו הקול, שהוא ז\"א. אז הוא יכול להשפיע להם הטהרה ואומר, \u0003תטהרו.\u0004"],[1,"תאנא מכל חטאתיכם","וגו': למדנו, מכל חטאתיכם לפני ה'. שואל, כיון שכתוב לטהר אתכם מכל חטאתיכם, למה כתוב, לפני ה' תטהרו. אלא אמר ר' יצחק, לפני ה' ממש. כלומר, שפירושו, להארת הפנים של ה'. כי הארת הפנים של ה' שה\"ס הארת החכמה, בסו\"ה חכמת אדם תאיר פניו, היא מכפרת העונות מביאה הטהרה."],[2,"דתניא מרישא דירחא","וכו': כי למדנו, מראש החדש, דהיינו בראש השנה, הספרים פתוחים והדיינים דנים. בכל יום ויום נמסרים בתי הדינים להפתח בדין, עד היום ההוא שנקרא תשיעי לחדש. ביום ההוא עולים כל הדינים לבעל הדין, והם מתקנים כסא עליון של רחמים למלך הקדש. ביום הזה צריכים ישראל למטה לשמוח בשמחה לפני אדונם, העתיד ביום השני לשבת עליהם בכסא רחמים, בכסא של ויתור, דהיינו כפרת עונות."],[2,"","פירוש. המלכות נקראת כסא. ובכל ראש השנה חוזר העולם, שהיא המלכות, לקדמותו, דהיינו כמו שהיתה ביום ד' דמעשה בראשית, שאז נאצלה המלכות בסוד ב' המאורות הגדולים, שז\"א היה מלביש קו ימין דבינה שהוא חסדים, והמלכות קו שמאל דבינה, שהיא חכמה בלי חסדים, שאז נמשכים ממנה דינים. ונקראת כסא דין. וז\"ס שהקב\"ה שהוא ז\"א, יושב על כסא דין, דהיינו שהמלכות משפעת דינים, והיא דן את העולם. וע\"י תקיעת שופר ועל ידי כל הדינים הנמשכים מג\"ר דשמאל, עד יום הכפורים, נכנע השמאל ומתיחד עם הימין ע\"י קו אמצעי, ואז עולה המלכות אל הבינה אחר שקו שמאל כבר מיוחד עם הימין ע\"י קו האמצעי, שה\"ס רחמים המיחד חסד ודין, וכיון שהמלכות מקבלת מן קו שמאל, שכבר נמתק ע\"י קו האמצעי, היא נקראת כסא רחמים. ונמצא שהקב\"ה יושב על כסא רחמים והעולמות מקבלים מכסא רחמים. ונמצא שכל אלו הדינים שיצאו מקו שמאל מראש השנה עד ט' לחודש בערב הם הכריחו את קו השמאל שיכלול בימין, ושיתוקן כסא הרחמים ביום הכפורים."],[2,"","וזה אמרו, \u0003ההוא יומא סלקין דינין כלהו למארי דדינא,\u0004 דהיינו לקו שמאל דבינה, שהוא שורש כל הדינים, ועי\"ז נמצא השמאל מתיחד עם הימין ע\"י קו האמצעי, ביום הכפורים, וז\"ש, \u0003ומתקני כרסייא עלאה, דרחמי,\u0004 שהדינים מכריחים את קו השמאל להכלל בימין על ידי הקו האמצעי שהוא רחמים, ונמצאת המלכות המקבלת משמאל המיוחד בימין, שהיא כסא רחמים כנ\"ל. אמנם תקון המלכות עצמה שתקבל משמאל הזה המתוקן, הוא ביום הכפורים וז\"ש, \u0003דזמין ליומא אחרא למיתב עלייהו בכורסייא קדישא דרחמי,\u0004 שביום הכפורים נעשית המלכות לכסא רחמים. \u0003בכורסייא דוותרנותא,\u0004 שאז מתגלה במלכות הארת החכמה המתוקנת, שהיא מכפרת העוונות. (עי' לעיל פרשת וירא אות שפ\"א והלאה. ועי' לעיל אות קט\"ז)."],[3,"וכל אינון ספרין","וכו': וכל אלו הספרים הפתוחים לפניו וכתובים לפניו כל אלו העונות הוא מזכה אותם ומטהר אותם מכולם. ז\"ש, מכל חטאתיכם לפני ה' תטהרו. לפני ה' ממש. דהיינו הארת הפנים של ה', שה\"ס הארת החכמה המכפרת כל העונות. אלו האומרים הכתוב הזה, עד כאן אומרים, דהיינו עד \u0003לפני ה'\u0004 ולא יותר, כי אין רשות לאחר שיאמר \u0003תטהרו,\u0004 אלא לכהן הגדול בלבד, שעובד העבודה ומיחד השם הקדוש בפיו, וכאשר מיחד השם הקדוש, ומתברך בפיו, אז הקול ההוא, שהוא ז\"א, יורד ובוטש בו, והאיר המלה בפה הכהן, ואומר, \u0003תטהרו.\u0004 עובד עבודתו ומתברכים כל העליונים שנשארו."],[4,"ולבתר אסחי גופיה","וכו': ואח\"כ רוחץ גופו ומקדש ידיו, לכנוס בעבודה אחרת קדושה. עד שיתכוון לכנוס למקום אחר עליון הקדוש מכל. שהוא קדש הקדשים. ג' שורות מסבבים את הכהן הגדול, אחיו הכהנים, והלוים, ומכל שאר העם כולם. שהם כנגד ג' קוין, כהן ולוי הם ימין ושמאל. וישראל ה\"ס קו האמצעי. והם נושאים ידיהם עליו בתפלה. וקשר של חבל זהב תלוי ברגלו, מחשש אולי ימות בקה\"ק, יוציאוהו משם בחבל הזה. \u0003זקפא,\u0004 פירושו תלוי, מלשון וזקיף יתמחא עלוהי (עזרא ו' י\"א)."],[5,"נטיל ג' פסיען","וכו': הלך ג' פסיעות, וכולם עומדים על מקומם ואינם הולכים אחריו. הלך ג' פסיעות אחרות ומסבב למקומו, הולך ג' פסיעות, וסותם עיניו, ומתקשר למעלה. נכנס למקום שנכנס, דהיינו בקה\"ק, שמע קול כנפי הכרובים, שמזמרים ודופקים בכנפיהם הפרושים למעלה, היה מקטיר קטרת, נשתתק קול כנפיהם, ומתדבקים בלחש."],[6,"אי כהנא זכי","וכו': אם הכהן זוכה, כיון שלמעלה נמצא בשמחה, אף כאן למטה יוצא בשעה ההיא רצון של אור, המתבשם מריחות של הרי אפרסמון הטהור שלמעלה, והולך בכל אותו המקום. נכנס הריח בב' נקבי החוטם שלו ומתישב הלב. אז הכל הוא בלחש ופתחון פה לא נמצא שם. פתח הכהן פיו בתפלה ברצון ובשמחה, ומתפלל תפלתו."],[7,"בחד דסיים זקפן","וכו': אחר שגמר תפלתו, נושאים הכרובים כנפיהם כבתחילה, ומזמרים. אז יודע הכהן שהיה רצון, ושעת שמחה לכל, והעם ידעו שנתקבלה תפלתו. כמ\"ש אם יהיו חטאיכם כשנים כשלג ילבינו. והכהן שב לאחוריו, ומתפלל תפלתו. אשרי חלקו של הכהן כי על ידיו נמצאת שמחה על שמחה, ביום ההוא למעלה ולמטה. על השעה ההיא כתוב, אשרי העם שככה לו אשרי העם שה' אלקיו."],[8,"והיתה וגו' תענו את נפשותיכם:","ר' חייא פתח, נפשי אויתיך בלילה אף רוחי בקרבי אשחרך וגו'. שואל, נפשי אויתיך בלילה, נפשי בלילה, צריך לומר, מהו נפשי אויתיך. וכן, אף רוחי בקרבי אשחרך, ישחרך היה צריך לומר. ומשיב, אלא כך למדנו. הקב\"ה הוא רוח ונפש של כל, וישראל אומרים, נפשי ורוחי אתה, משום זה, \u0003אויתיך\u0004 להתדבק בך. \u0003ואשחרך,\u0004 למצוא רצונך."],[9,"ר' יוסי אמר","וכו': רי\"א בשעה שאדם ישן במטתו, נפשו יוצאת ועולה ומעידה על האדם, מה שעשה בכל היום. ע\"כ הגוף אומר לנפש, נפשי אויתיך בלילה, דהיינו בשעה שאת יוצאת ממני, אף רוחי בקרבי אשחרך."]],[[0,"","הַקּוֹל נִקְשָׁר עִם הַכֹּהֵן, וְהוּא מֵשִׁיב אֲלֵיהֶם וְאוֹמֵר תִּטְהָרוּ. תִּטְהָרוּ אֵין אוֹמְרִים שְׁאָר הַכֹּהֲנִים וְהָעָם, פְּרָט לַכֹּהֵן הַגָּדוֹל, כְּשֶׁנִּקְשָׁר בּוֹ אוֹתוֹ הַקּוֹל."],[1,"","לָמַדְנוּ, מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי ה'. כֵּיוָן שֶׁכָּתוּב מִכֹּל חַטֹּאתֵיכֶם, לָמָּה לִפְנֵי ה'? אֶלָּא אָמַר רַבִּי יִצְחָק, לִפְנֵי ה' מַמָּשׁ."],[2,"","שֶׁשָּׁנִינוּ, מֵרֹאשׁ חֹדֶשׁ הַסְּפָרִים פְּתוּחִים וְהַדַּיָּנִים דָּנִים. בְּכָל יוֹם וָיוֹם בָּתֵּי הַדִּין נִמְסָרִים לְהִפָּתֵחַ לְדִין, עַד אוֹתוֹ יוֹם שֶׁנִּקְרָא תִּשְׁעָה לַחֹדֶשׁ. בְּאוֹתוֹ יוֹם כָּל הַדִּינִים עוֹלִים לְבַעַל הַדִּין וּמְתַקְּנִים כִּסֵּא עֶלְיוֹן שֶׁל רַחֲמִים לַמֶּלֶךְ הַקָּדוֹשׁ. בְּאוֹתוֹ יוֹם צְרִיכִים יִשְׂרָאֵל לְמַטָּה לִשְׂמֹחַ בְּשִׂמְחָה לִפְנֵי אֲדוֹנָם שֶׁעָתִיד לְיוֹם אַחֵר לָשֶׁבֶת עֲלֵיהֶם בַּכִּסֵּא הַקָּדוֹשׁ שֶׁל רַחֲמִים, בְּכִסֵּא שֶׁל וַתְּרָנוּת."],[3,"","וְכָל אוֹתָם הַסְּפָרִים הַפְּתוּחִים לְפָנָיו וּכְתוּבִים לְפָנָיו אֶת כָּל אוֹתָם הַחֲטָאִים, הוּא מְזַכֶּה אוֹתָם וּמְטַהֵר אוֹתָם מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב מִכֹּל חַטֹּאתֵיכֶם לִפְנֵי ה' תִּטְהָרוּ. לִפְנֵי ה' מַמָּשׁ. אוֹתָם שֶׁאוֹמְרִים אֶת הַפָּסוּק, אוֹמְרִים עַד כָּאן וְלֹא יוֹתֵר. וְאֵין רְשׁוּת לְאַחֵר לוֹמַר תִּטְהָרוּ, אֶלָּא הַכֹּהֵן הַגָּדוֹל שֶׁעוֹבֵד אֶת הָעֲבוֹדָה, וְקוֹשֵׁר אֶת הַשֵּׁם הַקָּדוֹשׁ בְּפִיו. וּכְשֶׁהָיָה נִקְשָׁר וּמִתְבָּרֵךְ בְּפִיו, אוֹתוֹ קוֹל יוֹרֵד וּמַכֶּה בּוֹ, וּמְאִירָה הַמִּלָּה בְּפִי הַכֹּהֵן, וְאוֹמֵר תִּטְהָרוּ. עָבַד עֲבוֹדָה, וּמִתְבָּרְכִים כָּל אוֹתָם הָעֶלְיוֹנִים שֶׁנִּשְׁאֲרוּ."],[4,"","אַחַר כָּךְ רוֹחֵץ גּוּפוֹ וּמְקַדֵּשׁ יָדָיו לְהִכָּנֵס לַעֲבוֹדָה קְדוֹשָׁה אַחֶרֶת. עַד שֶׁיִּתְכַּוֵּן לְהִכָּנֵס לְמָקוֹם אַחֵר עֶלְיוֹן קָדוֹשׁ מֵהַכֹּל. שָׁלֹשׁ שׁוּרוֹת מַקִּיפוֹת אוֹתוֹ; שֶׁל אֶחָיו הַכֹּהֲנִים, וּלְוִיִּם, וּמִכָּל שְׁאָר הָעָם. (ברכות לפניו) זוֹקְפִים יָדַיִם עָלָיו בִּתְפִלָּה, וְקֶשֶׁר שֶׁל זָהָב תָּלוּי בְּרַגְלוֹ. נוֹטֵל שָׁלֹשׁ פְּסִיעוֹת, וְכֻלָּם עוֹמְדִים בִּמְקוֹמָם וְלֹא הוֹלְכִים אַחֲרָיו. (היה מקטיר קטרת)."],[5,"","הוֹלֵךָ שָׁלֹשׁ פְּסִיעוֹת אֲחֵרוֹת, (רשומהבלב) מַקִּיף אֶת מְקוֹמוֹ. הוֹלֵךְ שָׁלֹשׁ פְּסִיעוֹת, וְסוֹתֵם אֶת עֵינָיו וְנִקְשָׁר לְמַעְלָה. נִכְנָס לְמָקוֹם שֶׁנִּכְנָס, שׁוֹמֵעַ קוֹל כַּנְפֵי הַכְּרוּבִים שֶׁמְּזַמְּרִים וּמַקִּישִׁים בַּכְּנָפִים הַפְּרוּשׂוֹת לְמַעְלָה. הָיָה מַקְטִיר אֶת הַקְּטֹרֶת, וְשׁוֹכֵךְ קוֹל כַּנְפֵיהֶם וְנִדְבָּקִים בְּלַחַשׁ."],[6,"","אִם הַכֹּהֵן זוֹכֶה, שֶׁהֲרֵי לְמַעְלָה נִמְצָא בְשִׂמְחָה - אַף כָּאן בְּאוֹתָהּ שָׁעָה יוֹצֵא רְצוֹן הָאוֹר הַמִּתְבַּשֵּׂם מֵרֵיחוֹת שֶׁל הָרֵי אֲפַרְסְמוֹן טָהוֹר שֶׁלְּמַעְלָה, וְהוֹלֵךְ בְּכָל אוֹתוֹ הַמָּקוֹם. נִכְנָס הָרֵיחַ לִשְׁנֵי נִקְבֵי חָטְמוֹ, וְלִבּוֹ מִתְיַשֵּׁב. אָז הַכֹּל הוּא בְּלַחַשׁ, וְלֹא נִמְצָא שָׁם פִּתְחוֹן פֶּה. פּוֹתֵחַ הַכֹּהֵן אֶת פִּיו בִּתְפִלָּה בְּרָצוֹן, בְּשִׂמְחָה, וּמִתְפַּלֵּל אֶת תְּפִלָּתוֹ."],[7,"","אַחַר שֶׁסִּיֵּם, זוֹקְפִים הַכְּרוּבִים כְּמוֹ מִקֹּדֶם אֶת כַּנְפֵיהֶם וּמְזַמְּרִים. אָז יוֹדֵעַ הַכֹּהֵן שֶׁהָיָה רָצוֹן, וְעֵת שִׂמְחָה לַכֹּל, וְהָעָם יוֹדְעִים שֶׁתְּפִלָּתוֹ הִתְקַבְּלָה, כְּמוֹ שֶׁכָּתוּב (ישעיה א) אִם יִהְיֶה חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ. וְהוּא שָׁב לַאֲחוֹרָיו וּמִתְפַּלֵּל תְּפִלָּתוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל הַכֹּהֵן, שֶׁהֲרֵי עַל יָדוֹ שִׂמְחָה עַל שִׂמְחָה נִמְצֵאת בְּאוֹתוֹ יוֹם לְמַעְלָה וּלְמַטָּה. עַל אוֹתָהּ שָׁעָה כָּתוּב, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו."],[8,"","וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ תְּעַנּוּ אֶת נַפְשּתֶיכֶם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ וְגוֹ'. נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, נַפְשִׁי אִוְּתָךְ בַּלַּיְלָה הָיָה צָרִיךְ לִהְיוֹת! מַהוּ נַפְשִׁי אִוִּיתִךְ? אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָּ הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כָּךְ לָמַדְנוּ, הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא רוּחַ וְהַנֶּפֶשׁ שֶׁל הַכֹּל, וְיִשְׂרָאֵל אוֹמְרִים: נַפְשִׁי וְרוּחִי אָתָּה. מִשּׁוּם כָּךְ אִוִּיתִךְ לִדְבֹּק בְּךְ, וַאֲשַׁחֲרֶךָּ לִמְצֹא אֶת רְצוֹנְךְ."],[9,"","רַבִּי יוֹסֵי אָמַר, בְּשָׁעָה שֶׁאָדָם יָשֵׁן בְּמִטָּתוֹ, יוֹצֵאת נַפְשׁוֹ, עוֹלָה וּמְעִידָה בָּאָדָם עַל כָּל מַה שֶּׁעָשָׂה בְּכָל הַיּוֹם. הַגּוּף אוֹמֵר לַנֶּפֶשׁ: נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ."]]],[["דָּבָר אַחֵר נַפְשִׁי אִוִּיתִיךָ, אָמְרָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, בְּעוֹד דַּאֲנָא בְּגָלוּתָא בֵּינֵי עֲמַמְיָא, וּמְנִיעָא נַפְשִׁי מִכָּל בִּישָׁתָא (נ\"א ורוינא נפשי מכל פיסתא) דְּקוּטְרָא בְּנֵי עֲמַמְיָא, נַפְשִׁי אִוִּיתִיךָ, בְּגִין לְאָתָבָא לְאַתְרִי. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, כְּלוֹמַר, אַף עַל גַּב דְּאִינּוּן מְשַׁעְבְּדִין לְבָנַי, בְּכָל שִׁעְבּוּדָא, רוּחָא קַדִּישָׁא לָא אִתְעָדֵי מִנַּאי, בְּגִין לְמִשְׁחַר לָךְ, וּלְמֶעְבַּד פִּקּוּדֶיךָ.","רִבִּי יִצְחָק אָמַר, אָמְרוּ יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, בְּעוֹד דְּנַפְשִׁי בִּי, אִוִּיתִיךָ בַּלַּיְלָה. מַאי טַעֲמָא בַּלַּיְלָה, אֶלָּא בְּגִין דְּהַאי נֶפֶשׁ בְּהַאי שַׁעֲתָא, אִצְטְרִיךְ לְחַמְדָּא לָךְ. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, כַּד אִתְּעַר בִּי רוּחָא קַדִּישָׁא, אֲשַׁחֲרֶךָּ בְּאִתְעָרוּתָא לְמֶעְבַּד רְעוּתָךְ. כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ בְּזִמְנָא דְּמִשְׁפָּט נָחִית בְּאַרְעָא, לְבַשְׂמָא עָלְמָא, כְּדֵין צֶדֶק לָמְדוּ יוֹשְבֵי תֵבֵל. כְּלוֹמַר יַכְלִין לְמִסְבַּל דִּינָא דְּצֶדֶק, וְלָא יִשְׁתְּצֵי עָלְמָא מִנֵּיהּ. אֵימָתַי צֶדֶק לָמְדוּ יוֹשְבֵי תֵבֵל, כַּאֲשֶׁר מִשְׁפָּטֶיךָ לָאָרֶץ. רַבִּי חִזְקִיָּה אָמַר, נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה, דָּא כְּנֶסֶת יִשְׂרָאֵל. אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, דָּא קוּדְשָׁא בְּרִיךְ הוּא.","רִבִּי אַבָּא הֲוָה יָתִיב קָמֵיהּ דְּרִבִּי שִׁמְעוֹן, קָם רִבִּי שִׁמְעוֹן בְּפַלְגּוּ לֵילְיָא, לְמִלְעֵי בְּאוֹרַיְיתָא. קָמוּ רִבִּי אֶלְעָזָר וְרִבִּי אַבָּא עִמֵּיהּ. פָּתַח רִבִּי שִׁמְעוֹן וְאָמַר, (תהילים מ״ב:ב׳) כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרוֹג אֵלֶיךָ אֱלֹהִים. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, זַכָּאִין אִינּוּן יִשְׂרָאֵל מִכָּל עַמִּין, דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן אוֹרַיְיתָא קַדִּישָׁא, וְאוֹרִית לוֹן נִשְׁמָתִין קַדִּישִׁין מֵאֲתַר קַדִּישָׁא, בְּגִין לְמֶעְבַּד פִּקּוּדוֹי, וּלְאִשְׁתַּעֲשְׁעָא בְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתַּעֲשָׁע בְּאוֹרַיְיתָא, לָא דָּחִיל מִכֹּלָּא. דִּכְתִּיב, (תהילים קי״ט:צ״ב) לוּלֵי תּוֹרָתְךָ שַׁעֲשׁוּעָי אָז אָבַדְתִּי בְעָנְיִי.","מַאן אִינּוּן שַׁעֲשׁוּעָי. אוֹרַיְיתָא. דְּאוֹרַיְיתָא שַׁעֲשׁוּעִים אִקְרֵי, דִּכְתִּיב, (משלי ח׳:ל׳) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְדָא הוּא דְּתָנֵינָן, קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא בְּגִנְתָא דְּעֵדֶן. מַאי לְאִשְׁתַּעְשְׁעָא. בְּגִין לְמֶחְדֵּי בְּהוּ. דְּתָנֵינָן, זַכָּאִין אִינּוּן צַדִּיקַיָּא, דִּכְתִיב בְּהוּ, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ', בְּגִין לְאִתְעַנְּגָא מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ח:י״א) וְהִשְׁבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךָ. כִּבְיָכוֹל, קוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשָׁע בְּהוּ, מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא, דְּמִתְעַנְּגֵי בְּהוּ צַדִּיקַיָּיא. וְעַל דָּא אָתֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא. וְכָל מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, זָכֵי לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, מֵהַהוּא שַׁקְיוּ דְּנַחֲלָא."],[[0,"ד״א נפשי וכו׳:","פירוש אחר. נפשי אויתיך. אמרה כנסת ישראל לפני הקב״ה, נפשי אויתיך בלילה. היינו בעוד שאני בגלות בין שאר העמים, ומנעתי נפשי מכל הרע הקשור בבני העמים, נפשי אויתיך, כדי לחזור למקומי. אף רוחי בקרבי אשחרך, כלומר, אע״פ שמשעבדים את בני בכל שעבוד, הרוח הקדוש אינו סר ממנו, כדי לבקר אותך ולעשות מצותיך."],[1,"ר׳ יצחק אמר וכו׳:","רי״א, אמרו ישראל לפני הקב״ה, בעוד שנפשי בי \u0003אויתיך בלילה.\u0004 מהו הטעם, בלילה. אלא משום שהנפש בשעה ההיא צריכה לחמוד אותך, \u0003אף רוחי בקרבי אשחרך,\u0004 היינו, כשנתעורר בי הרוח הקדוש אשחרך בהתעוררות לעשות רצונך. \u0003כי כאשר משפטיך לארץ.\u0004 היינו, בזמן שמשפט, שהוא ז״א, יורד בארץ, שהיא המלכות, לבשם העולם, אז \u0003צדק למדו יושבי תבל,\u0004 כלומר שיכולים לסבול הדינים דצדק, ולא יכלו בני העולם ממנו. מתי, \u0003צדק למדו יושבי תבל,\u0004 כאשר משפטיך לארץ. ר׳ חזקיה אמר, נפשי אויתיך בלילה. זו היא כנסת ישראל, שהיא המלכות, אף רוחי בקרבי אשחרך. זה הקב״ה. כי המלכות ה״ס נפש והקב״ה ה״ס רוח."],[2,"ר׳ אבא הוה וכו׳:","ר״א היה יושב לפני ר׳ שמעון, קם ר׳ שמעון בחצות לילה לעסוק בתורה. קמו ר׳ אלעזר ור׳ אבא עמו. פתח ר״ש ואמר, כאיל תערוג על אפיקי מים כן נפשי תערוג אליך אלקים. מקרא זה העמידו החברים. אשרי הם ישראל מכל העמים, שהקב\"ה נתן להם התורה הקדושה, והוריש להם נשמות קדושות ממקום קדוש, כדי לעשות מצותיו ולהשתעשע בתורה. שכל מי שמשתעשע בתורה, אינו ירא מכל. שכתוב, לולי תורתך שעשועי אז אבדתי בעניי."],[3,"מאן אינון שעשועי וכו׳:","מה הם שעשועי. זה התורה, שהתורה נקראת שעשועים, שכתוב, ואהיה שעשועים יום יום. וזהו שלמדנו. שהקב״ה בא להשתעשע בגן עדן. מהו להשתעשע. היינו כדי שישמח בהם. שלמדנו. אשרי הם הצדיקים שכתוב בהם, אז תתענג על ה'. כדי להתענג מאותו שיקוי הנחל, שהוא בינה, כש\"א, והשביע בצחצחות נפשך. כביכול, הקב״ה משתעשע בהם, מאותו שיקוי של הנחל, שהצדיקים מתענגים בו. וע״כ בא להשתעשע עם הצדיקים. וכל מי שעוסק בתורה, זוכה להשתעשע עם הצדיקים מאותו שיקוי הנחל, שהוא בינה."]],[[0,"","דָּבָר אַחֵר נַפְשִׁי אִוִּיתִךְ - אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, בְּעוֹד שֶׁאָנוּ בַּגָּלוּת בֵּין הָעַמִּים, וּמְנוּעָה נַפְשִׁי מִכָּל רַע (ושבעה נפשי מכל הבזיונות) שֶׁקְּשׁוּרָה בֵּין הָעַמִּים, נַפְשִׁי אִוִּיתִךְ, כְּדֵי לָשׁוּב לִמְקוֹמִי. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, כְּלוֹמַר, אַף עַל גַּב שֶׁהֵם מְשַׁעְבְּדִים אֶת בָּנַי בְּכָל שִׁעְבּוּד, רוּחַ הַקֹּדֶשׁ לֹא זָזָה מִמֶּנִּי כְּדֵי לְשַׁחֵר אוֹתְךְ וְלַעֲשׂוֹת מִצְווֹתֶיךְ."],[1,"","רַבִּי יִצְחָק אָמַר, אָמְרוּ יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: בְּעוֹד שֶׁנַּפְשִׁי בִּי, אִוִּיתִךְ בַּלַּיְלָה. מָה הַטַּעַם בַּלַּיְלָה? אֶלָּא מִשּׁוּם שֶׁהַנֶּפֶשׁ הַזּוֹ בַּשָּׁעָה הַזּוֹ צְרִיכָה לַחְמֹד אוֹתְךְ. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, כַּאֲשֶׁר מִתְעוֹרֶרֶת בִּי רוּחַ הַקֹּדֶשׁ, אֲשַׁחֲרֶךָּ בְּהִתְעוֹרְרוּת לַעֲשׂוֹת רְצוֹנְךְ. כִּי כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ, בִּזְמַן שֶׁהַמִּשְׁפָּט יוֹרֵד לָאָרֶץ לְבַשֵּׂם אֶת הָעוֹלָם, אָז צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל. כְּלוֹמַר, יְכוֹלִים לִסְבֹּל אֶת הַדִּין שֶׁל צֶדֶק, וְלֹא יֻשְׁמַד הָעוֹלָם מִמֶּנּוּ. מָתַי צֶדֶק לָמְדוּ יֹשְׁבֵי תֵבֵל? כַּאֲשֶׁר מִשְׁפָּטֶיךְ לָאָרֶץ. רַבִּי חִזְקִיָּה אָמַר, נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל. אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא."],[2,"","רַבִּי אַבָּא הָיָה יוֹשֵׁב לִפְנֵי רַבִּי שִׁמְעוֹן. קָם רַבִּי שִׁמְעוֹן בַּחֲצוֹת הַלַּיְלָה לַעֲסֹק בַּתּוֹרָה. קָמוּ רַבִּי אֶלְעָזָר וְרַבִּי אַבָּא עִמּוֹ. פָּתַח רַבִּי שִׁמְעוֹן וְאָמַר, (תהלים מב) כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם כֵּן נַפְשִׁי תַעֲרֹג אֵלֶיךְ אֱלֹהִים. הַפָּסוּק הַזֶּה פֵּרְשׁוּהוּ הַחֲבֵרִים, אַשְׁרֵיהֶם יִשְׂרָאֵל מִכָּל הָעַמִּים, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לָהֶם תּוֹרָה קְדוֹשָׁה וְהוֹרִישׁ לָהֶם נְשָׁמוֹת קְדוֹשׁוֹת מִמָּקוֹם קָדוֹשׁ כְּדֵי לַעֲשׂוֹת מִצְווֹתָיו וּלְהִשְׁתַּעֲשֵׁעַ בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמִּשְׁתַּעֲשֵׁעַ בַּתּוֹרָה, לֹא פוֹחֵד מִכֹּל, שֶׁכָּתוּב (תהלים קיט) לוּלֵי תוֹרָתְךְ שַׁעֲשֻׁעָי אָז אָבַדְתִּי בְעָנְיִי."],[3,"","מִי הֵם שַׁעֲשֻׁעָי? תּוֹרָה. שֶׁהַתּוֹרָה נִקְרֵאת שַׁעֲשׁוּעִים, שֶׁכָּתוּב (משלי ח) וָאֶהְיֶה שַׁעֲשׁוּעִים יוֹם יוֹם. וְזֶהוּ שֶׁשָּׁנִינוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים בְּגַן עֵדֶן. מַה זֶּה לְהִשְׁתַּעֲשֵׁעַ? כְּדֵי לִשְׂמֹחַ עִמָּהֶם, שֶׁשָּׁנִינוּ, אַשְׁרֵי הַצַּדִּיקִים, שֶׁכָּתוּב בָּהֶם (ישעיה נח) אָז תִּתְעַנַּג עַל ה', כְּדֵי לְהִתְעַנֵּג מֵאוֹתָהּ הַשְׁקָאָה שֶׁל הַנַּחַל, כְּמוֹ שֶׁנֶּאֱמַר וְהִשְׂבִּיעַ בְּצַחְצָחוֹת נַפְשֶׁךְ. כִּבְיָכוֹל מִשְׁתַּעֲשֵׁעַ הַקָּדוֹשׁ בָּרוּךְ הוּא בָּהֶם מֵאוֹתָהּ הַשְׁקָאַת הַנַּחַל שֶׁבָּהּ מִתְעַנְּגִים הַצַּדִּיקִים, וְעַל כֵּן בָּא לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים. וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, זוֹכֶה לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים מֵאוֹתָהּ הַשְׁקָיַת הַנַּחַל."]]],[["תָּאנָא, כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, דָּא כְּנֶסֶת יִשְׂרָאֵל. כְּמָה דְאַתְּ אָמֵר, (תהילים כ״ב:כ׳) אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, וַדַאי לְאִשְׁתַּקְּיָא מִשַּׁקְיוּ דְּמַבּוּעֵי דְּנַחֲלָא, עַל יְדֵי דְּצַדִיק. תַּעֲרוֹג: כְּמָה דְאַתְּ אָמֵר, (שיר השירים ו) לַעֲרוּגֹת הַבּוֹשֶׂם, כֵּן נַפְשִׁי תַעֲרוֹג אֵלֶיךָ אֱלֹהִים. לְאִשְׁתַּקְּיָיא מִנָךְ, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי.","מַבּוּעֵי נַחֲלָא מַאן אִינּוּן. מַבּוּעָא חַד לְעֵילָּא, דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ'. וּמִתַּמָּן נָגִיד וְנָפִיק, וּמַשְׁקֵי גִּנְתָּא, וְכָל אִינּוּן נַחֲלִין, נַגְדִּין וְנָפְקִין וּמִתְכַּנְּשִׁין בִּתְרֵי מַבּוּעִין, דְּאִקְרוּן נֶצַח וְהוֹד, וְאִלֵּין אִקְרוּן אֲפִיקֵי מַיִם, בְּהַהוּא דַּרְגָא דְּצַדִיק, דְּמִנֵיהּ נָגִיד וְנָפִיק וּמִשְׁתַּקְיָא גִּנְתָּא. בְּגִין כַּךְ אַיָּל וּצְבִי כַּחֲדָא מִשְׁתַּכְחֵי, (נ\"א איל וצבי אקרון עטרת ויסוד) צֶדֶק וְצַדִּיק.","תָּאנָא, כְּתִיב (תהילים כ״ט:ט׳) קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת, אַיָּלוֹת, אַיֶּלַת כְּתִיב חָסֵר, דָּא אַיְלוֹת הַשָּׂדֶה (נ\"א דא אילת דשחר). (דבר אחר אילות השדה), דְּתַנְיָא, בְּפַלְגוּת לֵילְיָא, בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָאל לְגִנְתָּא דְּעֵדֶן לְאִשְׁתַּעְשְׁעָא עִם צַדִּיקַיָּיא, הַאי קוֹל נָפִיק, וְכָאִיב כָּל אִינּוּן אַיַּלְתָּא דְּסַחֲרָנֵי כּוּרְסְיָיא יַקִּירָא קַדִּישָׁא, הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:ז׳) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ. דָּבָר אַחֵר יְחוֹלֵל אַיָּלוֹת, כְּמָה דְאַתְּ אָמֵר (איוב כ״ו:י״ג) חוֹלְלָה יָדוֹ נָחָשׁ בָּרִיחַ. וַיֶּחשׂוֹף יְעָרוֹת כְּמָה דְאַתְּ אָמֵר. (שמואל א יב) בְּיַעְרַת הַדְּבָשׁ, וּכְתִיב (שיר השירים ה׳:א׳) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי, וְיַנְקָא לְהוּ כְּאִמָּא דְּיָנְקָא לִבְנִין.","\u0003רעיא מהימנא\u0004 אָמַר רַעְיָא מְהֵימָנָא, בְּהַהוּא זִמְנָא, אִלֵּין מָארֵי מַתְנִיתִין מָארֵי חָכְמְתָא עִלָּאָה, מָארֵי קַבָּלָה, מָארֵי רָזֵי תּוֹרָה, שַׁעֲתָא דְּחִיקַת לוֹן. וְהַאי אִיהוּ דְּאָמַר כְּאַיָּל תַּעֲרוֹג עַל אֲפִיקֵי מָיִם, דְּאִינּוּן אֲפִיקֵי מַיִם דְּאוֹרַיְיתָא לְגַבֵּי שְׁכִינְתָּא. וְלֵית תּוֹרָה, אֶלָּא עַמּוּדָא דְּאֶמְצָּעִיתָא. דִּיהוֹן אִלֵּין אֲפִיקֵי מַיִם, בְּצַּעֲרָא בִּיגוֹנָא בְּעַנְיוּתָא, וְאִלֵּין אִינּוּן חֲבָלִים צִּירִין דְּיוֹלֵדָה, דְּאִיהִי שְׁכִינְתָּא, דְּאִתְּמַר בָּהּ, (משלי כ״ג:כ״ה-כ״ו) וְתָגֵל יוֹלַדְתֶּךָ. וּבְאִינּוּן חֲבָלִים, תְּהֵא בְּצַּעֲרָא דִּלְהוֹן.","וּבְאִינּוּן חֲבָלִים דְּצַּוְוחַת בְּהוֹן, אִתְּעָרַת שִׁבְעִין סַנְהֶדְרִין דִּלְעֵילָּא, עַד דְּיִתְּעַר קוֹל דִּילָהּ עַד יְהוָֹ\"ה, וּמִיַּד (תהילים כ״ט:ט׳) קוֹל יְיָ' יְחוֹלֵל אַיָּלוֹת, דְּאִינּוּן מָארֵי מַתְנִיתִין, (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, כֻּלְּהוֹן יִהוֹן לוֹן חִיל כַּיּוֹלֵדָה מַמָּשׁ, בְּדַחֲקִין, דְּדַחֲקָא לוֹן שַׁעֲתָא, בְּכַמָּה נְשִׁיכִין דְּיִצֶּר הָרָע, דְּחִוְיָא דְּנָשִׁיךְ לוֹן בְּכַמָּה דַּחֲקִין.","בְּהַהוּא זִמְנָא אִתְפַּתְּחַת לְאוֹלָדָא מְשִׁיחָא, בְּגִין חֲבָלִים וְדוֹחֲקִים דְּצַּדִּיקִים, וּמָארֵי מִדּוֹת, וּמָארֵי רָזִין דְּאוֹרַיְיתָא, מָארֵי בּוֹשֶת וַעֲנָוָה, מָארֵי יִרְאָה וְאַהֲבָה, מָארֵי חֶסֶד, אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים, אַנְשֵׁי אֱמֶת, שׂוֹנְאֵי בָצַּע, דְּדַחֲקָא לוֹן שַׁעֲתָא. וְהַאי הוּא דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, דּוֹר שֶׁבֶּן דָּוִד בָּא, אַנְשֵׁי חַיִל יְסוֹבְבוּ מֵעִיר לָעִיר וְלָא יְחוֹנָנוּ, וְיִרְאֵי חֵטְא יִמָּאֲסוּ, וְחָכְמַת סוֹפְרִים תִּסְרַח, וּתְּהִי הָאֱמֶת נֶעְדֶּרֶת, וְהַגֶּפֶן תִּתֵּן פִּרְיָה, וְהַיַּיִן בְּיוֹקֶר.","וּמֵאִינּוּן קָלִין דְּיָהִיבַת, דְּאִינּוּן שִׁבְעִין, לָקֳבֵל שִׁבְעִין תֵּיבִין דְּיַעַנְךָ יְיָ' בְּיוֹם צָּרָה, אִתְפַּתְּחַת רַחְמָהּ, דְּאִיהִי ב', כְּלִילָא מִתְּרֵין בֵּיתִין, לְאוֹלָדָא ב' מְשִׁיחִין, וְאָעִילַת רֵישָׁהּ בֵּין בִּרְכָּהָא, דְּאִיהוּ רֵישָׁא דִּילָהּ, עַמּוּדָא דְּאֶמְצָּעִיתָא. תְּרֵין שׁוֹקָהָא, נֶצַּח וְהוֹד, תְּרֵין נְבִיאִים. מִתַּמָּן אוֹלִידַת תְּרֵין מְשִׁיחִין. בְּהַהִיא זִמְנָא וַיֶּחֱשׂוֹף יְעָרוֹת, יִתְעַבָּר נָחָשׁ מֵעָלְמָא (ע\"כ רעיא מהימנא)","אָמַר לֵיהּ רִבִּי אַבָּא, (ישעיהו כ״ו:ט׳) נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, נַפְשִׁי בַּלַּיְלָה מִבָּעֵי לֵיהּ. אֲשַׁחֲרֶךָּ, יְשַׁחֲרֶךָ מִבָּעֵי לֵיהּ. אָמַר לֵיהּ הָא אוּקְמוּהָ, (בראשית כ\"ג) כְּמָה דְאַתְּ אָמֵר (איוב י״ב:י׳) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְרוּחַ כָּל בְּשַׂר אִישׁ.","תָּא חֲזֵי נַפְשָׁא וְרוּחָא אִשְׁתְּמוֹדָע (ס\"א אשתעי) (ס\"א אשתתפי) כַּחֲדָא לְעָלְמִין. תָּנָא פּוּלְחָנָא שְׁלֵימָתָא דְּבָעֵי בַּר נָשׁ לְמִפְלַח לְּקוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּתַנִּינָן (דברים ו׳:ה׳) וְאָהַבְתָּ אֶת יְיָ' אֱלֹהֶיךָ וְגוֹ'. דְּיַרְחִים לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא רְחִימוּתָא דְּנֶפֶשׁ מַמָּשׁ, וְדָא הוּא רְחִימוּתָא שְׁלֵימָתָא, רְחִימוּתָא דְּנַפְשֵׁיהּ וְרוּחֵיהּ. כְּמָה דְּאִתְדְּבָּקוּ אִלֵּין בְּגוּפָא, וְגוּפָא רָחִים לוֹן. (ס\"א כדין) כַּךְ יִתְדָּבָק בַּר נָשׁ לְרַחֲמָא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, רְחִימוּתָא דְּנַפְשֵׁיהּ וְרוּחֵיהּ, לְאַדְבְּקָא בֵּיהּ. הֲדָא הוּא דִכְתִיב נַפְשִׁי אִוִּיתִיךָ בַּלַּיְלָה (כלומר) נַפְשִׁי מַמָּשׁ.","אַף רוּחִי בְּקִרְבִּי אֲשַׁחֲרֶךָּ, אִתְדַּבְּקָא בָּךְ בִּרְחִימוּתָא סַגִיאָה, בַּלַּיְלָה. דְּבָעֵי בַּר נָשׁ מֵרְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, לְמֵיקָם בְּכָל לֵילְיָא, לְאִשְׁתַּדְלָא בְּפוּלְחָנֵיהּ, עַד דְּיִתְעַר צַפְרָא, וְיִתְמְשַׁךְ עָלֵיהּ חוּטָא דְּחֶסֶד. דְּתַנְיָא, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא בַּר נָשׁ דִּרְחִימוּתָא דָּא רָחִים לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְהָנֵי זַכָּאֵי קְשׁוֹט דִּמְרַחֲמִין לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא הָכִי, עָלְמָא מִתְקַיְימָא בְּגִינֵיהוֹן, וְשַׁלְטִין עַל כָּל גְּזִירִין קָשִׁין דִּלְעֵילָּא וְתַתָּא. (נ\"א היא) (בגין דיתקיים עלמא בגיניהון)","תָּאנָא, הַהוּא זַכָּאָה דְּאִתְדַּבָק בְּרוּחֵיהּ וְנַפְשֵׁיהּ לְעֵילָּא, בְּמַלְכָּא קַדִישָׁא, בִּרְחִימוּתָא כְּדְקָא יֵאוֹת. שַׁלִּיט בְּאַרְעָא דִּלְתַתָּא, וְכָל מַה דְּגָזַר עַל עָלְמָא אִתְקַיָּים. מְנָא לָן, מֵאֵלִיָּהוּ. דִּכְתִּיב, (מלכים א י״ז:א׳) חַי יְיָ' אֲשֶׁר עָמַדְתִּי לְפָנָיו אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְּבָרִי.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּאַתְיָין נִשְׁמָתִין קַדִישִׁין מֵעֵילָּא לְתַתָּא, וְאִינּוּן זַכָּאֵי עָלְמָא מְשַׁלְּפֵי לְהוּ מִמַּלְכָּא וּמַטְרוֹנִיתָא, זְעִירִין אִינּוּן, דִּבְהַהוּא שַׁעֲתָא דְּנָחִית, קַיְּימָא קָמֵי מַלְכָּא, וּרְעוּתָא דְּמַלְכָּא לְאִסְתַּכְּלָא בָּהּ, כְּמָה דְּאוֹקִימְנָא, בְּשַׁעֲתָא דְּנָשַׁב קוּדְשָׁא בְּרִיךְ הוּא רוּחָא בְּכָל חֵילָא וְחֵילָא דִּשְׁמַיָּא, כֻּלְּהוּ חַיָּילִין אִתְעָבִידוּ, וְקַיְימֵי בְּקִיּוּמַיְיהוּ, הֲדָא הוּא דִכְתִיב (תהילים ל״ג:ו׳) וּבְרוּחַ פִּיו כָּל צְבָאָם. וּמִנַּיְיהוּ אִתְעַכְּבוּ עַד דְּקוּדְשָׁא בְּרִיךְ הוּא אָחִית לְהוּ לְתַתָּא."],[[0,"תאנא כאיל תערוג וגו׳:","למדנו כאיל תערוג על אפיקי מים זו היא כנסת ישראל, שהיא המלכות. כש״א אילותי לעזרתי חושה, אשר אילותי היא המלכות. \u0003תערוג על אפיקי מים,\u0004 היינו ודאי, להיות מושקים משיקוי של מבוע הנחל, שהוא בינה, ע״י הצדיק, שהוא יסוד, \u0003תערוג,\u0004 הוא כש״א לערוגת הבושם. כן נפשי תערוג אליך אלקים, היינו להשקות ממך בעולם הזה ובעולם הבא."],[1,"מבועי נחלא מאן וכו׳:","שואל, מבועי הנחל, מי הם. ומשיב, יש מבוע אחד למעלה שהוא בינה, שכתוב, ונהר יוצא מעדן להשקות את הגן, וגו'. ומשם נמשך ויוצא ומשקה את הגן, שהוא המלכות. וכל אלו הנחלים, שהם ספירות דז״א המקבלות מן הנהר, נמשכים ויוצאים ומתקבצים בשני מבועים הנקראים נצח והוד, דז״א, ואלו נקראים אפיקי מים. ומשפיעים במדרגה ההיא שנקראת צדיק, דהיינו יסוד דז״א, שממנו נמשך ויוצא ומושקה הגן. שהוא המלכות. ומשום כך, איל וצבי נמצאים יחד, שהם צדק וצדיק, דהיינו יסוד ומלכות, שהם ביחד. כי איל הוא מלכות, וצבי הוא יסוד."],[2,"תאנא כתיב וכו׳:","למדנו, כתוב, קול ה׳ יחולל אילות. קוראים אילות וכתוב אילת חסר \u0003ו'.\u0004 זו היא אילת השחר, שהיא המלכות. פירוש אחר אילות השדה. שלמדנו, בחצות לילה, בשעה שהקב\"ה נכנס בגן עדן להשתעשע עם הצדיקים, הקול הזה, שהוא ז״א, יוצא ומכאיב לכל אלו האילות המסבכות את כסא הכבוד הקדוש, שהוא המלכות. ז״ש ששים גבורים סביב לה. פירוש אחר. יחולל אילות, הוא כמו שאתה אומר, חוללה ידו נחש בריח. שחוללה, פירושו שברא וחיזק, אף מחולל אילות פירושו שמחזק את האילות, שהם ששים הגבורים. \u0003ויחשוף יערות,\u0004 הוא כמו שאתה אומר ב \u0003יערת\u0004 הדבש. וכתוב אכלתי \u0003יערי\u0004 עם דבשי, והוא, ז״א, שה״פ קול \u0003ה',\u0004 מיניק אותם ששים גבורים, הנקראים אילות, כמו אם המיניקה את הבנים. וע״כ כתוב, \u0003קול ה׳\u0004 יחולל אילות. דהיינו שמניק ומקיים אותם."],[2,"","פירוש. כי בחצות לילה נתעורר קו האמצעי עם כח המסך דחירק שבו, למעט הג״ר דשמאל, וליחדו עם הימין, כדי שיוכל להשפיע החכמה שבו. שז״ס שהקב״ה, שה״ס קו האמצעי בא אז בג״ע שהוא המלכות וכו'. וע״כ עד חצות לילה, דהיינו מטרם שבא קו האמצעי למעט הג״ר דשמאל, כל הפתחים של המלכות סתומים, כי אע״פ שיש בהם הארת החכמה, הם סתומים ואינם יכולים להאיר, מטעם שהקו האמצעי עוד לא כלל אותו עם הימין, וע״כ אינו מאיר אלא מחצות לילה ואילך. כמ״ש כל זה באורך (וישלח אות קל״ד קל״ה בהסולם ע״ש)."],[2,"","וזה אמרו, \u0003בפלגות ליליא\u0004 וכו' \u0003האי קול נפיק וכאיב כל אינון אילתא.\u0004 כי ששים הגיבורים שהם בחינת קו שמאל דז״א שבלילה, שה״ס המלכות, ואין הארת החכמה שבהם יכולה להאיר, הנה בחצות לילה, יוצא הקול הזה, שהוא הקו האמצעי, \u0003וכאיב כל אינון אילתא,\u0004 דהיינו שממעט הג״ר דשמאל, שזה כואב להם, אבל בשביל זה נפתחת הארת החכמה שבהם, כי יכולים להתיחד עם הימין, וז״ס \u0003קול ה׳,\u0004 שהוא קו האמצעי, \u0003יחולל אילות,\u0004 שמכאיב אותם שממעט הג״ר שבהם, כדי לפתוח הארת החכמה שבהם. וז״ש, \u0003דבר אחר, יחולל אילות, כד״א חוללה ידו נחש בריח.\u0004 ונמצא שיחולל, פירושו שבורא את האילות, שהם קו שמאל שבמלכות. שהרי הוא מכשיר ופותח את קו השמאל שתאיר בו החכמה, שזה נבחן כמו שבורא את השמאל. וז״ש, \u0003ויחשוף יערות, כד״א ביערת הדבש.\u0004 כי הכלים דאחורים, הנמשכים מקו השמאל שבמלכות, מכונים, \u0003יערות,\u0004 להיותם אילני סרק, שאינם מוציאים פירות, והדינים שורים בהם. אבל עי״ז שז״א מיחד הימין והשמאל זב״ז, הוא פותח הארת החכמה שבשמאל, כנ״ל, הנה נמצא שמגלה את החכמה שביערות. שז״ס \u0003ויחשוף יערות\u0004 והארת החכמה המתגלה מן היערות הללו. מכונה דבש, שז״ס ב \u0003יערת\u0004 הדבש, וכן אכלתי \u0003יערי\u0004 עם דבשי. וז״ש \u0003וינקא להו,\u0004 שז״א שנק׳ קול ה׳ מיניק אותם האילות, \u0003כאמא דינקא לבנין.\u0004 דהיינו שממשיך להם חסדים שע״י התלבשות בחסדים האלו, הם יכולים להאיר. וע״כ כתוב קול ה׳ יחולל אילות שיניקה זו נבחנת כמו שבוראת אותם, שהרי עד עתה לא היתה בהם מציאת הארת החכמה. כי היו סתומים, כנ״ל."],[3,"אמר רעיא מהימנא וכו׳:","אמר רעיא מהימנא, שהוא נשמת משה רבנו, בזמן ההוא, קודם ביאת המשיח, אלו בעלי המשנה, בעלי החכמה העליונה, בעלי קבלה, בעלי סודות התורה, השעה דחוקה והם, שאין להם ממה להתפרנס, וזהו שאמר, כאיל תערג על אפיקי מים. שהם דהיינו בעלי החכמה הנ״ל אפיקי מים של התורה אל השכינה, כי התורה נקראת מים, ואין תורה אלא העמוד האמצעי, דהיינו ז״א, קו האמצעי. כי אלו אפיקי מים, שהם בעלי החכמה הנ״ל שמהם תצא תורה, שהיא מים, הם בצעד ביגון בעניות. ואלו הם חבלים וצירים של היולדת, שהיא השכינה, שנאמר בה ותגל יולדתך. ובאלו חבלים תהיה, דהיינו בצער שלהם, של בעלי התורה והחכמה הנ״ל. שצערם נבחן לחבלי לידה של השכינה."],[4,"ובאינון חבלים דצווחת וכו׳:","ובאלו חבלי לידה שצועקת בהם מתעוררים ע׳ סנהדרין למעלה. עד שיתעורר הקול שלה עד הוי״ה. ומיד קול ה׳ יחולל אילות, שהם בעלי המשנה הנ״ל שה״ס, בתולות אחריה רעיתיה, לכולם יהיה חיל כיולדה ממש, בדחק שהשעה דוחקת להם בכמה נשיכות של יצר הרע, שהוא הנחש הנושך אותם בכמה מיני דחקות."],[5,"בההוא זמנא וכו׳:","בזמן ההוא, היא נפתחת להוליד את המשיח, בשביל החבלים והדחק של הצדיקים, בעלי מדות, בעלי סודות התורה, בעלי בושת וענוה, בעלי יראה ואהבה, בעלי חסד, אנשי חיל, יראי אלקים, אנשי אמת, ושונאי בצע, שהשעה דוחקת אותם. וזהו שהעמידו בעלי המשנה, דור שבן דוד בא אנשי חיל יסובבו מעיר לעיר ולא יחוננו. ויראי חטא ימאסו, וחכמת סופרים תסרח, ותהא האמת נעדרת, והגפן תתן פריה והיין ביוקר."],[6,"ומאינון קלין וכו׳:","ומאלו הקולות שנותנת, שהם שבעים קולות, כנגד שבעים תיבות שיש במזמור, יענך ה׳ ביום צרה, נפתחה רחמה, שהיא \u0003ב׳,\u0004 דהיינו \u0003בית\u0004 הרחם, הכלול מב' בתים, להוליד מהם ב׳ משיחים, משיח בן דוד ומשיח בן יוסף. ומביאה ראשה בין ברכיה. הראש שלה, הוא העמוד האמצעי, דהיינו ז״א. ברכיה הם ב׳ שוקים נצח והוד, שהם ב׳ נביאים. משם נולדים ב׳ משיחים כנ״ל. בעת ההוא, \u0003ויחשוף יערות,\u0004 דהיינו שתתגלה החכמה (כנ״ל באות ר״י) והנחש יהיה נעבר מן העולם. כי אור החכמה מכלה כל הקליפות. (ע״כ רעיא מהימנא)."],[7,"אמר ליה ר׳ אבא וכו׳:","א״ל ר״א, נפשי אויתיך בלילה אף רוחי בקרבי אשחרך, שואל נפשי בלילה היה צריך לומר. דהיינו נפשי בלילה אף רוחי בקרבי אשחרך. וכן אשחרך, ישחרך היה צריך לומר, שהרי הוא סובב על הרוח שלו. אמר לו הרי העמידוהו, שהוא כש״א, אשר בידו נפש כל חי ורוח כל.בשר איש. כלומר שנפשי ורוחי שאומר אינם כינויי עצמו, אלא שהם ב׳ האורות רוח ונפש המלובשים בגוף, כמו שמפרש והולך."],[8,"ת״ח נפשא ורוחא וכו׳:","בוא וראה נפש ורוח משתתפים יחד לעולם. למדנו, עבודה שלמה שצריך האדם לעבוד להקב״ה, הוא כמו שלמדנו, ואהבת את ה׳ אלקיך וגו'. שיאהב את הקב״ה אהבת נפש ממש. וזו היא אהבה שלמה, אהבת נפשו ורוחו. כמו שאלו, הנפש והרוח, נתדבקו בגוף, והגוף אוהב אותם, כך יתדבק האדם לאהוב את הקב״ה להתדבק בו, כאהבת נפשו ורוחו. ז״ש, נפשי אויתיך בלילה. דהיינו נפשי ממש, המלובשת בגוף."],[9,"אף רוחי בקרבי אשחרך:","היינו שאתדבק בך באהבה רבה בלילה. כי האדם צריך לקום בכל לילה, מאהבת הקב״ה, לעסוק בעבודתו עד שיתעורר הבוקר, וימשוך עליו חוט של חסד. ולמדנו, אשרי חלקו של אדם שאוהב את הקב״ה באהבה זו. ואלו צדיקי אמת שאוהבים כך את הקב״ה, העולם מתקיים בשבילם, ושולטים על כל גזירות קשות שלמעלה ושלמטה."],[10,"תאנא ההוא זכאה וכו׳:","למדנו אותו הצדיק שמתדבק ברוחו ונפשו למעלה, בהמלך הקדוש, באהבה כראוי. הוא שולט בארץ שלמטה, וכל מה שגוזר על העולם מתקיים. מאין לנו זה מאליהו, שכתוב, חי ה׳ אשר עמדתי לפניו אם יהיה השנים האלה טל ומטר כי אם לפי דברי."],[11,"ת״ח בשעתא דאתיין וכו׳:","בוא וראה, בשעה שנשמות קדושות באות מלמעלה למטה, וצדיקי העולם ממשיכים אותם מן המלך והמלכה, דהיינו מזווג זו״ן, ומועטות הנה, שזוכות, שבאותה שעה שיורדת לעולם, נמצאת עומדת ומשמשת לפני המלך, ורצון המלך הוא להסתכל בה. ואח\"כ יורדת לעולם. כמו שהעמדנו, בשעה שהקב״ה נשב רות בכל נשמה ונשמה, ובכל מלאך ומלאך שבשמים, כל הצבאות נעשו ונגמרו בקיומם. ז\"ש וברוח פיו כל צבאם. ומהן, מן הנשמות, יש, שמתעכבות ועומדות לפני הקב״ה כנ״ל, עד שהקב״ה מורידן למטה."]],[[0,"","לָמַדְנוּ, כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם - זוֹ כְּנֶסֶת יִשְׂרָאֵל, כְּמוֹ שֶׁנֶּאֱמַר אֱיָלוּתִי לְעֶזְרָתִי חוּשָׁה. תַּעֲרֹג עַל אֲפִיקֵי מָיִם, וַדַּאי כְּדֵי לְהִשָּׁקוֹת מֵהַשְׁקָיָה שֶׁל מַעַיְנוֹת הַנַּחַל עַל יְדֵי הַצַּדִּיק. תַּעֲרֹג, כְּמוֹ שֶׁנֶּאֱמַר (שיר ו) לַעֲרֻגוֹת הַבֹּשֶׂם. כֵּן נַפְשִׁי תַעֲרֹג אֵלֶיךְ אֱלֹהִים, לְקַבֵּל מִמְּךְ הַשְׁקָאָה בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא."],[1,"","מַעַיְנוֹת הַנַּחַל מִי הֵם? מַעְיָן אֶחָד לְמַעְלָה, שֶׁכָּתוּב (בראשית ב) וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן וְגוֹ', וּמִשָּׁם שׁוֹפֵעַ וְיוֹצֵא וּמַשְׁקֶה אֶת הַגָּן. כָּל אוֹתָם הַנְּחָלִים שׁוֹפְעִים וְיוֹצְאִים וּמִתְכַּנְּסִים לִשְׁנֵי מַעְיָנוֹת שֶׁנִּקְרָאִים נֵצַח וְהוֹד, וְאֵלּוּ נִקְרָאִים אֲפִיקֵי מַיִם, בְּאוֹתָהּ דַּרְגָּה שֶׁל צַדִּיק, שֶׁמִּמֶּנּוּ שׁוֹפֵעַ וְיוֹצֵא וְנִשְׁקָה הַגָּן. מִשּׁוּם כָּךְ אַיָּל וּצְבִי נִמְצָאִים כְּאֶחָד, (איל וצבי נקראים עטרת ויסוד) צֶדֶק וְצַדִּיק."],[2,"","לָמַדְנוּ, כָּתוּב קוֹל ה' יְחוֹלֵל אַיָּלוֹת. אַיָּלוֹת, אַיֶּלֶת כָּתוּב חָסֵר, זוֹ אַיְלוֹת הַשָּׂדֶה (נ\"א זו אילת השחר) (ד\"א אילות השדה). אַיְלוֹת הַשָּׂדֶה, שֶׁשָּׁנִינוּ, בַּחֲצוֹת הַלַּיְלָה, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִכְנָס לְגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, הַקּוֹל הַזֶּה יוֹצֵא וּמַכְאִיב לְכָל אוֹתָן הָאַיָּלוֹת שֶׁסְּבִיב הַכִּסֵּא הַנִּכְבָּד הַקָּדוֹשׁ, זֶהוּ שֶׁכָּתוּב (שיר ג) שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ. דָּבָר אַחֵר יְחוֹלֵל אַיָּלוֹת - כְּמוֹ שֶׁנֶּאֱמַר (איובכו) חֹלְלָה יָדוֹ נָחָשׁ בָּרִחַ. וַיֶּחֱשּׁף יְעָרוֹת, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א יד) בְּיַעְרַת הַדְּבָשׁ, וְכָתוּב (שיר ה) אָכַלְתִּי יַעְרִי עִם דִּבְשִׁי, וּמֵינִיקָה אוֹתָם כְּמוֹ אֵם שֶׁמֵּינִיקָה אֶת הַבָּנִים."],[3,"","אָמַר הָרוֹעֶה הַנֶּאֱמָן, בְּאוֹתוֹ זְמַן בַּעֲלֵי הַמִּשְׁנָה הַלָּלוּ, בַּעֲלֵי הַחָכְמָה הָעֶלְיוֹנָה, בַּעֲלֵי קַבָּלָה, בַּעֲלֵי רָזֵי תוֹרָה, הַשָּׁעָה דְּחוּקָה לָהֶם. וְזֶהוּ שֶׁאָמַר כְּאַיָּל תַּעֲרֹג עַל אֲפִיקֵי מָיִם, שֶׁאוֹתָם אֲפִיקֵי מַיִם שֶׁל הַתּוֹרָה אֶל הַשְּׁכִינָה. וְאֵין תּוֹרָה אֶלָּא עַמּוּד הָאֶמְצָעִי, שֶׁיִּהְיוּ אֲפִיקֵי הַמַּיִם הַלָּלוּ בְּצַעַר, בְּיָגוֹן וּבְעֹנִי, וְאֵלּו הֵם חֲבָלִים, צִירִים שֶׁל יוֹלֵדָה, שֶׁהִיא הַשְּׁכִינָה, שֶׁבָּהּ נֶאֱמַר (משלי כג) וְתָגֵל יוֹלַדְתֶּךְ. וּבְאוֹתָם הַחֲבָלִים תִּהְיֶה בַּצַּעַר שֶׁלָּהֶם."],[4,"","וּבְאוֹתָם חֲבָלִים שֶׁצּוֹעֶקֶת בָּהֶם, מִתְעוֹרְרִים שִׁבְעִים סַנְהֶדְרִין שֶׁלְּמַעְלָה, עַד שֶׁיִּתְעוֹרֵר קוֹלָהּ עַד יְהֹוָ\"ה, וּמִיָּד - (תהלים כט) קוֹל ה' יְחוֹלֵל אַיָּלוֹת, שֶׁהֵם בַּעֲלֵי הַמִּשְׁנָה, בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, לְכֻלָּם יִהְיֶה חִיל כַּיּוֹלֵדָה מַמָּשׁ בַּדְּחָקִים שֶׁהַשָּׁעָה דּוֹחֶקֶת אוֹתָם בְּכַמָּה נְשִׁיכוֹת שֶׁל יֵצֶר הָרָע, שֶׁל נָחָשׁ שֶׁנּוֹשֵׁךְ אוֹתָם בְּכַמָּה דְחָקִים."],[5,"","בְּאוֹתוֹ זְמַן נִפְתַּחַת לְהוֹלִיד אֶת הַמָּשִׁיחַ, מִשּׁוּם הַחֲבָלִים וְהַדְּחָקִים שֶׁל הַצַּדִּיקִים, וּבַעֲלֵי מִדּוֹת וּבַעֲלֵי רָזִים שֶׁל הַתּוֹרָה, בַּעֲלֵי בֹּשֶׁת וַעֲנָוָה, בַּעֲלֵי יִרְאָה וְאַהֲבָה, בַּעֲלֵי חֶסֶד, אַנְשֵׁי חַיִל יִרְאֵי אֱלֹהִים, אַנְשֵׁי אֱמֶת, שׂוֹנְאֵי בָצַע, שֶׁדָּחֲקָה אוֹתָם הַשָּׁעָה. וְזֶהוּ שֶׁבֵּאֲרוּהָ בַּעֲלֵי הַמִּשְׁנָה, דּוֹר שֶׁבֶּן דָּוִד בָּא, אַנְשֵׁי חַיִל יְסוֹבְבוּ מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ, וְיִרְאֵי חֵטְא יִמָּאֲסוּ, וְחָכְמַת סוֹפְרִים תִּסְרַח, וּתְהִי הָאֱמֶת נֶעְדֶּרֶת, וְהַגֶּפֶן תִּתֵּן פִּרְיָהּ, וְהַיַּיִן בְּיֹקֶר."],[6,"","וּמֵאוֹתָם קוֹלוֹת שֶׁהִיא נוֹתֶנֶת, שֶׁהֵם שִׁבְעִים, כְּנֶגֶד שִׁבְעִים תֵּבוֹת שֶׁל יַעַנְךְ ה' בְּיוֹם צָרָה, נִפְתַּחַת רַחְמָהּ, שֶׁהִיא שְׁתַּיִם, כְּלוּלָה מִשְּׁתֵּי בֵּיתִי\"ם, לְהוֹלִיד שְׁנֵי מְשִׁיחִים, וּמַכְנִיסָה אֶת רֹאשָׁהּ בֵּין בִּרְכֶּיהָ, שֶׁהוּא הָרֹאשׁ שֶׁלָּהּ, הָעַמּוּד הָאֶמְצָעִי. שְׁתֵּי שׁוֹקֶיהָ, נֵצַח וְהוֹד, שְׁנֵי נְבִיאִים. מִשָּׁם מוֹלִידָה שְׁנֵי מְשִׁיחִים. בְּאוֹתוֹ זְמַן וַיֶּחֱשׂף יְעָרוֹת, יָעֳבַר הַנָּחָשׁ מֵהָעוֹלָם. (עד כאן רעיא מהימנא)."],[7,"","אָמַר לוֹ רַבִּי אַבָּא, (ישעיה כו) נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ. הָיָה צָרִיךְ לִהְיוֹת נַפְשִׁי אִוְּתָךְ בַּלַּיְלָה! אֲשַׁחֲרֶךָּ?! יְשַׁחֲרֶךָּ הָיָה צָרִיךְ לִהְיוֹת! אָמַר לוֹ, הֲרֵי פֵּרְשׁוּהָ, כְּמוֹ שֶׁנֶּאֱמַר (איוב יב) אֲשֶׁר בְּיָדוֹ נֶפֶשׁ כָּל חָי וְרוּחַ כָּל בְּשַׂר אִישׁ."],[8,"","בֹּא רְאֵה, הַנֶּפֶשׁ וְהָרוּחַ נוֹדָעוֹת (נפגשות) (משתתפות) כְּאֶחָד לְעוֹלָמִים. לָמַדְנוּ, עֲבוֹדָה שְׁלֵמָה שֶׁצָּרִיךְ אָדָם לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁלָּמַדְנוּ וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךְ, שֶׁיֹּאהַב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבַת נֶפֶשׁ מַמָּשׁ, וְזוֹהִי אַהֲבָה שְׁלֵמָה, אַהֲבַת נַפְשׁוֹ וְרוּחוֹ. כְּמוֹ שֶׁאֵלֶּה נִדְבָּקִים בְּגוּף, וְהַגּוּף אוֹהֵב אוֹתָם, (אז) כָּךְ יִדְבַּק אָדָם לֶאֱהֹב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבַת נַפְשׁוֹ וְרוּחוֹ לִדְבּק בּוֹ. זֶהוּ שֶׁכָּתוּב נַפְשִׁי אִוִּיתִךְ בַּלַּיְלָה, (כלומר) נַפְשִׁי מַמָּשׁ."],[9,"","אַף רוּחִי בְקִרְבִּי אֲשַׁחֲרֶךָּ, אֶתְדַּבֵּק בְּךְ אַהֲבָה רַבָּה בַּלַּיְלָה, שֶׁצָּרִיךְ אָדָם מֵאַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲמֹד בְּכָל לַיְלָה לְהִשְׁתַּדֵּל בַּעֲבוֹדָתוֹ עַד שֶׁיִּתְעוֹרֵר הַבֹּקֶר, וְיִמָּשֵׁךְ עָלָיו חוּט שֶׁל חֶסֶד. שֶׁשָּׁנִינוּ, אַשְׁרֵי חֶלְקוֹ שֶׁל אוֹתוֹ אָדָם שֶׁאוֹהֵב אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא אַהֲבָה כָּזוֹ, וְצַדִּיקֵי הָאֱמֶת הַלָּלוּ שֶׁאוֹהֲבִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא כָּךְ, הָעוֹלָם מִתְקַיֵּם בַּעֲבוּרָם, וְשׁוֹלְטִים עַל כָּל הַגְּזֵרוֹת הַקָּשׁוֹת שֶׁלְּמַעְלָה וּלְמַטָּה. (היא) (כדי שיתקים העולם בעבורם)."],[10,"","לָמַדְנוּ, אוֹתוֹ צַדִּיק שֶׁנִּדְבָּק בְּרוּחוֹ וְנַפְשׁוֹ לְמַעְלָה בַּמֶּלֶךְ הַקָּדוֹשׁ בְּאַהֲבָה כָּרָאוּי, שׁוֹלֵט בָּאָרֶץ שֶׁלְּמַטָּה, וְכָל מַה שֶּׁגּוֹזֵר עַל הָעוֹלָם מִתְקַיֵּם. מִנַּיִן לָנוּ? מֵאֵלִיָּהוּ, שֶׁכָּתוּב (מלכים א יז) חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו אִם יִהְיֶה הַשָּׁנִים הָאֵלֶּה טַל וּמָטָר כִּי אִם לְפִי דְבָרִי."],[11,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁבָּאוֹת הַנְּשָׁמוֹת הַקְּדוֹשׁוֹת מִמַּעְלָה לְמַטָּה, וְאוֹתָם צַדִּיקֵי הָעוֹלָם שׁוֹלְפִים אוֹתָם מֵהַמֶּלֶךְ וּמֵהַגְּבִירָה, מְעַטִּים הֵם. שֶׁבְּאוֹתָהּ שָׁעָה שֶׁיּוֹרֶדֶת, עוֹמֶדֶת לִפְנֵי הַמֶּלֶךְ, וּרְצוֹנוֹ שֶׁל הַמֶּלֶךְ לְהִתְבּוֹנֵן בָּהּ, כְּמוֹ שֶׁבֵּאַרְנוּ, בְּשָׁעָה שֶׁנּוֹשֵׁב הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ בְּכָל חַיִל וְחַיִל שֶׁל הַשָּׁמַיִם, כָּל הַחֲיָלוֹת נַעֲשִׂים, וְעוֹמְדִים בִּמְקוֹמָם. זֶהוּ שֶׁכָּתוּב וּבְרוּחַ פִּיו כָּל צְבָאָם. וּמֵהֶן מִתְעַכְּבוֹת עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיד אוֹתָן לְמַטָּה."]]],[["וְתָאנָא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, קַיְימֵי קַמֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעַכָּבוּ עַד דְּמָטָא זִמְנָא לְאַחֲתָא לוֹן בְּאַרְעָא, וְאִלֵּין שְׁלִיטוּ לְעֵילָּא וְתַתָּא, הֲדָא הוּא דִכְתִיב חַי יְיָ' אֲשֶׁר עָמַדְתִּי לְפָנָיו, אֲשֶׁר אֲנִי עוֹמֵד לָא כְּתִיב, אֶלָּא אֲשֶׁר עָמַדְתִּי. לְבָתַר אַהְדָר לְאַתְרֵיהּ, וְסָלִיק לְאִדָּרֵיהּ, וְאִינּוּן אָחֳרָנִין לָא סַלְּקִין עַד דִּימוּתוּן. בְּגִין דְּלָא קַיְימוּ קוֹדֶם לָכֵן כְּאִינּוּן אָחֳרָנִין. וּבְגִין כַּךְ אֵלִיָּהוּ אִתְעָבִיד שְׁלִיחָא, מַלְאָכָא לְעֵילָּא, וְאִלֵּין דְּמִתְדַּבְּקָן יַתִיר לְמַלְכָּא.","אַשְׁכַּחְנָא בְּסִפְרָא דְּאָדָם קַדְמָאָה דְּכָל רוּחִין קַדִישִׁין דִּלְעֵילָּא, עָבְדִין שְׁלִיחוּתָא, וְכֻלְּהוּ אַתְיָין מֵאֲתַר חַד. דְּנִשְׁמָתְהוֹן דְּצַדִיקַיָּיא מִתְּרֵי דַּרְגִּין דִּכְלִילָן בְּחַד, וּבְגִין כַּךְ סַלְּקִין יַתִיר, וְדַרְגֵּיהוֹן יַתִיר, וְהָכִי הוּא. וְכָל אִינּוּן דַּהֲווֹ טְמִירִין תַּמָּן, נַחְתּוּ וּסְלִיקוּ בְּחַיֵּיהוֹן, כְּגוֹן חֲנוֹךְ דְּלָא אִשְׁתְּכַח בֵּיהּ מִיתָה. וְהָא אוֹקִימְנָא מִלָּה דָּא, בַּחֲנוֹךְ וְאֵלִיָּהוּ.","וְתָאנָא מְאָה וְעֶשְׂרִין וַחֲמֵשׁ אֶלֶף דַּרְגִּין (לצדיקייא) לְנִשְׁמָתְהוֹן דְּצַדִּיקַיָּיא, סְלִיקוּ בִּרְעוּתָא, עַד לָא אִתְבְּרֵי עָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא מְזַמְּנָא לְהוּ בְּעָלְמָא דֵּין, בְּכָל דָּרָא וְדָרָא, וְסַלְּקִין וְטָאסִין עָלְמָא, וּמִתְקַשְּׁרֵי בִּצְרוֹרָא דְּחַיֵּי, וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְחַדְּתָּא עָלְמָא בְּהוּ, עָלַיְיהוּ כְּתִיב, (ישעיהו ס״ו:כ״ב) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה וְגוֹ'.","(ויקרא ט״ז:כ״ט) תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם, נַפְשׁוֹתֵיכֶם קָאָמַר, בְּגִין דְּיִשְׂרָאֵל מִשְׁתַּכְחִין קָמֵי מַלְכָּא קַדִישָׁא זַכָּאִין, וִיהֵא רְעוּתָא דִּלְהוֹן לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּלְאִתְדַּבְקָא בֵּיהּ, בְּגִין דְּיִתְכַּפֵּר לְהוּ חוֹבַיְיהוּ. וְעַל דָּא, מַאן דְּאָכַל וְשָׁתֵי בִּתְשִׁיעָאָה, וּמְעַנְּגָא נַפְשֵׁיהּ בְּמֵיכְלָא וּמִשְׁתְּיָיא, אִשְׁתְּכַח בַּעֲשִׂירָאָה עִנּוּיָא דְּנַפְשָׁא בִּתְרֵין חוּלָקִין, וְאִשְׁתְּכַח כְּאִלּוּ אִתְעַנֵּי תְּשִׁיעָאָה וַעֲשִׂירָאָה. אֶת נַפְשׁוֹתֵיכֶם: לְאַכְלְלָא כֹּלָּא, גּוּפָא וְנַפְשָׁא, וּלְאִתְכַּנְּעָא בְּהַאי יוֹמָא, לְאִתְכַּפְּרָא עַל חוֹבֵיהוֹן.","תָּאנָא כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. בַּיוֹם הַזֶּה. הַיּוֹם הַזֶּה מִבָּעֵי לֵיהּ. אֶלָּא בַּיוֹם הַזֶּה דַּיְיקָא, דְּבֵיהּ אִתְגְלֵי עַתִּיקָא קַדִּישָׁא, לְכַפָּרָא עַל חוֹבֵיהוֹן דְּכֹלָּא.","דָּבָר אַחֵר תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם. רִבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ט׳:י״ד) עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעָט וְגוֹ', עִיר קְטַנָּה, הָא אוּקְמוּהָ. אֲבָל עִיר קְטַנָּה, כְּמָה דְאַתְּ אָמֵר, (ישעיהו כ״ו:א׳) עִיר עָז לָנוּ יְשׁוּעָה יָשִׁית חוֹמוֹת וַחֵיל וְגוֹ'. וּכְתִּיב (הושע י״א:ט׳) וְלֹא אָבֹא בְּעִיר. עִיר קְטַנָּה, זְעֵירָא הִיא, דְּהִיא בַּתְרָאָה מִכֹּלָּא, תַּתָּאָה מִכֹלָּא, שׁוּרוֹי רַבְרְבִין, תַּקִּיפִין, קַדִּישִׁין, עִיר הַקֹּדֶשׁ אִקְרֵי. וַאֲנָשִׁים בָּהּ מְעָט, זְעִירִין אִינּוּן דְּזַכָּאן לְסַלְּקָא לְגַוָּוהּ, וּלְמִשְׁרֵי בָּהּ, כְּמָה דְאַתְּ אָמֵר (תהילים כ״ד:ג׳) מִי יַעֲלֶה בְהַר יְיָ' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ וְגוֹ'. וְעַל דָּא אֲנָשִׁים בָּהּ מְעָט.","וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל, דָּא קוּדְשָׁא בְּרִיךְ הוּא. לְאִזְדַוְּוגָא בָּהּ, וּלְמִשְׁרֵי בָּהּ, וְסָבַב אוֹתָהּ, כְּמָה דְאַתְּ אָמֵר (זכריה ב׳:ט׳) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יְיָ' חוֹמַת אֵשׁ סָבִיב וְגוֹ'. וּבָנָה עָלֶיהָ מְצוֹדִים גְּדוֹלִים, דְּבָנָה שׁוּרוֹי, רַבְרְבִין תַּקִּיפִין יֶאֱיָאן וְשַׁפִּירִין (ס\"א מכל אבנין יקירין) קַדִּישִׁין. עִיר הַקֹּדֶשׁ אִקְרֵי, וְכָל יְקָרָא דְּמַלְכָּא עַיִּיל בְּגַוָּוהּ. וּבְגִין כָּךְ, הִיא בִּלְחוֹדָהָא כְּלִילָא מִכָּל עִטְרֵי דְּמַלְכָּא, וְכָל עִטְרֵי מַלְכָּא בָּהּ מִתְעַטְּרִין. בְּגִין כָּךְ, וַאֲנָשִׁים בָּהּ מְעָט כְּתִיב.","וּמָצָא בָהּ אִישׁ מִסְכֵּן וְחָכָם, הֲדָא הוּא דִכְתִיב, (תהלים טו) נְקִי כַפַּיִם וּבַר לֵבָב. מִסְכֵּן: כְּמָה דְאַתְּ אָמֵר (שמות א׳:י״א) וַיִּבֶן עָרֵי מִסְכְּנוֹת לְפַרְעֹה, מִתְעַטָּר בְּעִטְרִין תַּקִּיפִין, בְּעִטְרֵי אוֹרַיְיתָא, בְּעִטְרֵי פִּקּוּדֵי אוֹרַיְיתָא דְּמַלְכָּא. וְחָכָם, דְּזָכֵי בָּהּ בְּהַאי חָכְמָה. וְחָכָם, דְּהוּא חַכִּים יַתִיר מִכֹּלָּא לְעַיְּינָא בְּפוּלְחָנָא דְּמָארֵיהּ, בְּגִין לְמִזְכֵּי בָּהּ, וּלְאַעֲלָא בָּהּ. הֲדָא הוּא דִּכְתִיב, וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ. וּמִלַּט: כְּמוֹ (שמואל א כ׳:כ״ט) אִמָּלְטָה נָּא וְאֶרְאֶה אֶת אֶחָי, (בראשית י״ט:כ׳) אִמָּלְטָה נָא שָׁמָּה. אוּף הָכָא וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ.","וְאָדָם לֹא זָכַר אֶת הָאִישׁ הַמִּסְכֵּן הַהוּא, וְאָדָם לָא זָכַר, לְמֶעְבַּד פִּקּוּדֵי אוֹרַיְיתָא, לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, כְּהַהוּא גְּבַר מִסְכְּנָא דְּאִתְחַבָּר בְּכֹלָּא, בְּגִין לְמִזְכֵּי בָּהּ. (קהלת ט׳:ט״ז) וְאָמַרְתִּי אָנִי טוֹבָה חָכְמָה מִגְּבוּרָה. דְּהָא בְּהַהוּא עָלְמָא, לָא יָהֲבִין רְשׁוּ לְמֵיעַל, בַּר הָנֵי זַכָּאֵי קְשׁוֹט, הָנֵי דְּמִשְׁתַּדְּלֵי בָּהּ בְּאוֹרַיְיתָא יוֹמָא וְלֵילֵי, וּמִתְעַטְּרֵי בְּפִקּוּדֵי אוֹרַיְיתָא בְּהַאי עָלְמָא, לְמֵיעַל בְּהוּ לְעָלְמָא דְּאָתֵי."],[[0,"ותאנא מיומא דאתברי וכו׳:","ולמדנו, מיום שנברא העולם, עומדות נשמות הצדיקים הגדולים, לפני הקב״ה, ומתעכבות לפניו, והקב״ה מסתכל בהן כנ״ל, עד שמגיע הזמן להורידן בארץ, דהיינו שיתלבשו בגוף. והן שולטות למעלה ולמטה. ז״ש חי ה׳ אשר \u0003עמדתי\u0004 לפניו, אשר אני עומד לא כתוב, אלא אשר עמדתי. והיינו מטרם שירד לעולם הזה. אח״כ חזר למקומו לשמים, ועלה לחדרו. ונשמות אחרות אינן עולות למקומן עד שימותו. משום שלא עמדו מקודם לכן, לפני הקב״ה באותה המעלה כמו האחרים, דהיינו חנוך ואליהו, שזכו לעלות למקומם בעודם בחיים. ומשום זה נעשה אליהו שליח ומלאך למעלה. וכן חנוך. ואלו הם שנתדבקו ביותר בהמלך. דהיינו יותר ממלאך."],[1,"אשכחנא בספרא דאדם וכו׳:","מצאתי בספרו של אדם הראשון, שכל הרוחות הקדושים שלמעלה, דהיינו המלאכים, עושים שליחות של הקב״ה, וכולם באים ממקום אחד. ונשמות הצדיקים באות משתי מדרגות הכלולות באחד, ועל כן עולות יותר ממלאכים ומדרגותיהן יותר ממלאכים. וכך הוא. וכל אלו שהיו חבוים שמה, ירדו ועלו בחייהם, כמו חנוך שלא נמצא בו מיתה. וכבר העמדנו דבר זה בחנוך ואליהו."],[1,"","פירוש. כבר ידעת שב׳ נקודות כלולות במלכות שהן מנעולא ומפתחא, וכל האורות נמשכים רק בסוד המפתחא. ונקודת המנעולא גנוזה בה. וע״כ נקראת עץ הדעת טוב ורע, כי האנשים, שהם נמשכים ממלכות, אם זכה, ואינו חוטא, הא טוב. שנקודת המנעולא אינה מתגלית, וזוכה לכל האורות. ואם לא זכה, הא רע, שמתגלית עליו נקודת המנעולא, ואז מסתלקים תיכף כל האורות. ומטעם זה, בא המיתה על כל אדם, כי השטן שהוא מלאך המות מעורר על האדם את נקודת המנעולא, ואור החיים מסתלק בסבתה. כמ״ש כל זה לעיל (ויצא דף י״ג ד״ה סתרא עש״ה)."],[1,"","אמנם המלאכים נמשכים רק מבחינת נקודה דמפתחא לבד, ואין בהם שום חלק ממנעולא. וע״כ המלאכים אינם מתים. וז״ש, \u0003דכל רוחין קדישין דלעילא,\u0004 דהיינו כל המלאכים, \u0003אתיין מאתר חד.\u0004 דהיינו מנקודה אחת בלבד, שהיא המפתחא. \u0003דנשמתהון דצדיקייא מתרי דרגין דכלילן בחד,\u0004 דהיינו מב׳ נקודות מנעולא ומפתחא שכלולים באחד, במפתחא, ונקודת המנעולא נגוזה בה ואינה ניכרת. כנ״ל."],[1,"","ויש מעלה במלאכים שאין בבני אדם, שהרי מלאכים אינם מתים, משא״כ בני אדם כיון שכלולים ג״כ מנקודה דמנעולא, הם מתים בשביל זה. ויש מעלה בבני אדם שאין במלאכים, כי המלאכים, עליהם לא מוטל התקון, כי המפתחא אינו צריך שום תקון, להיותו מבחינת בינה, וכל עיקרו לא בא אלא לתקן המנעולא. וע״כ הם עומדים תמיד במדרגת אחת כמו שנבראו, ואין עליות ומדרגות נוהגות בהם. משא״כ בני אדם, הכלולים ממנעולא עליהם מוטל כל התקון, וע״כ כשזוכים עולים בעליות ומשיגים מדרגות. וז״ש, \u0003ובג״כ סלקין יתיר,\u0004 כי בני אדם עולים בעליות \u0003ודרגיהון יתיר,\u0004 שהולכים ממדרגה למדרגה שאין זה במלאכים."],[1,"","ויש נשמות גדולות אשר בחינת המנעולא גנוזה בהן ביותר עד שאינה ראויה להגלות לעולם, והם אינם מתים. וז״ש \u0003וכל אינון דהוו טמירין תמן,\u0004 כלומר שבחינת המנעולא שבהם גנוזה וחבויה בשורשם, \u0003נחתו וסליקו בחייהון, כגון חנוך, דלא אשתכח ביה מיתה.\u0004 כמבואר."],[2,"ותאנא מאה וכו׳:","ולמדנו מאה ועשרים וחמשה אלף מדרגות לנשמות הצדיקים עלו ברצון הקב״ה, מטרם שנברא העולם, שהקב״ה מזמן אותן בעולם הזה, בכל דור ודור, ועולות ומעופפות בעולם ומתקשרות בצרור החיים, שהוא המלכות, ועתיד הקב״ה לחדש בהן את העולם. עליהם כתוב, כי כאשר השמים החדשים והארץ החדשה וגו'."],[2,"","פירוש, המדרגה אינה נבחנת לשלמה, אלא עד שתהיינה בה ה׳ מדרגות נפש רוח נשמה חיה יחידה, שכל אחת מאלו יש לה ה׳ מדרגות נרנח״י פרטיות, וכל אחת מהפרטיות יש לה ה׳ מדרגות נרנח״י פרטי פרטיות. שהם ביחד קכ״ה מדרגות. וז\"ש \u0003מאה ועשרין וחמש\u0004 וכו׳:"],[3,"תענו את נפשותיכם:","אומר נפשותיכם, כדי שישראל ימצאו זכאים לפני המלך הקדוש, ויהיה רצונם אל הקב״ה, ולהתדבק בו, כדי שיתכפרו להם עונותיהם. וע״כ מי שאוכל ושותה בתשיעי ומענג נפשו במאכל ומשתה, נמצא לו עינוי נפש בעשירי, כפלים, והוא נמצא כאלו התענה תשיעי ועשירי. \u0003את נפשותיכם,\u0004 כולל הכל, גוף ונפש, ולהכנע ביום הזה, כדי לכפר על עונותיהם."],[4,"תאנא כי ביום וגו׳:","למדנו, כי ביום הזה יכפר עליכם. שואל, אומר ביום הזה, היום הזה, היה צריך לומר. ומשיב, אלא ביום הזה הוא מדויק, כי בו מתגלה עתיקא קדישא, שהוא הכתר, לכפר על עונות הכל."],[5,"ד״א, תענו את נפשותיכם:","ר׳ אבא פתח ואמר, עיר קטנה ואנשים בה מעט וגו'. \u0003עיר קטנה,\u0004 הרי העמידוהו. אבל, עיר קטנה היא כמו שאתה אומר, עיר עז לנו ישועה ישית חומות וחיל וגו'. וכתוב, ולא אבא בעיר. אשר עיר פירושו מלכות. \u0003עיר קטנה,\u0004 שהיא קטנה משום שהיא האחרונה מכל הספירות, ותחתונה. מכולן. חומותיה הן גדולות, חזקות, וקדושות, היא נקראת עיר הקדש. \u0003ואנשים בה מעט,\u0004 מועטים המה הזוכים לעלות לתוכה ולשכון בה. כש״א מי יעלה בהר ה׳ ומי יקום במקום קדשו וגו'. וע״כ אנשים בה מעט."],[6,"ובא אליה מלך גדול:","זהו הקב״ה, שבא להתחבר עמה ולשכון בה. \u0003וסבב אותה,\u0004 הוא כש״א, ואני אהיה לה חומת אש סביב וגו'. \u0003ובנה עליה מצודים גדולים\u0004 שבנה חומותיה, דהיינו השמירה שלא יינקו ממנה החיצונים, גדולים וחזקים ונאים ויפים וקדושים. נקראת עיר הקדש, וכל יקר של המלך הכניס בתוכה. וע״כ היא לבדה כלולה מכל עטרות המלך, שהם המוחין דז״א, וכל עטרות המלך מתעטרים בה. בסו״ה אשת חיל עטרת בעלה. כי אין מתעטר בהארת חכמה, אלא בשעה שנזזדווג עם המלכות, משום שאין חכמה נגלית אלא במלכות. (כנ״ל בראשית א׳ דף רע״ו ד״ה ועוד כמה) משום זה, ואנשים בה מעט, כתוב. שאין כל אדם זוכה בה."],[7,"ומצא בה איש מסכן וחכם:","זהו שכתוב, נקי כפים ובר לבב. נקרא \u0003מסכן,\u0004 כש״א ויבן ערי מסכנות לפרעה. דהיינו שמתעטר בעטרות תקיפות, בעטרות התורה בעטרות מצות התורה של המלך. ונקרא \u0003חכם,\u0004 משום שזכה בחכמה הזו, כי המלכות נקראת חכמה תתאה, משום שבה מקום גילוי החכמה. כנ\"ל. ועוד נקרא \u0003וחכם,\u0004 משום שהוא חכם יותר מכל אדם להתבונן בעבודת אדונו, כדי לזכות בה ולכנוס בה. ז״ש, ומלט הוא את העיר בחכמתו. ומלט, הוא כמו אמלטה נא ואראה את אחי. וכן אמלטה נא שמה. שהוא לשון הצלה. אף כאן ומלט הוא את העיר בחכמתו. שע״י ההתבוננות שלו, הוא מציל אותה, שלא יינקו ממנה החיצונים."],[8,"ואדם לא זכר את האיש המסכן ההוא:","היינו ששום אדם לא זכר לעשות מצות התורה ולעסוק בתורה כמו האיש המסכן ההוא, שנתחבר בכל, כדי לזכות בה. \u0003ואמרתי אני טובה חכמה מגבורה,\u0004 היינו שבעולם ההוא, אינם נותנים רשות לכנוס חוץ לאלו צדיקי אמת, לאלו שעוסקים בתורה יומם ולילה, ומתעטרים במצות התורה בעולם הזה כדי לבוא עמהם לעולם הבא."]],[[0,"","וְלָמַדְנוּ, מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם הֵן עוֹמְדוֹת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְעַכְּבוֹת עַד שֶׁמַּגִּיעַ הַזְּמַן לְהוֹרִיד אוֹתָן לָאָרֶץ, וְאֵלּוּ שׁוֹלְטוֹת לְמַעְלָה וּלְמַטָּה. זֶהוּ שֶׁכָּתוּב חַי ה' אֲשֶׁר עָמַדְתִּי לְפָנָיו. אֲשֶׁר אֲנִי עוֹמֵד לֹא כָתוּב, אֶלָּא אֲשֶׁר עָמַדְתִּי. אַחַר כָּךְ חוֹזֶרֶת לִמְקוֹמָהּ וְנִכְנֶסֶת לְחַדְרָהּ, וְאוֹתָן אֲחֵרוֹת לֹא עוֹלוֹת עַד שֶׁיָּמוּתוּ, כִּי לֹא עָמְדוּ קֹדֶם כְּאוֹתָן הָאֲחֵרוֹת. וּמִשּׁוּם כָּךְ אֵלִיָּהוּ נַעֲשָׂה שָׁלִיחַ, מַלְאָךְ לְמַעְלָה, וְאֵלּו שֶׁמִּתְדַּבְּקִים יוֹתֵר לַמֶּלֶךְ."],[1,"","מָצָאנוּ בְּסִפְרוֹ שֶׁל אָדָם הָרִאשׁוֹן, שֶׁכָּל הָרוּחוֹת הַקְּדוֹשׁוֹת שֶׁלְּמַעְלָה עוֹשׂוֹת שְׁלִיחוּת, וְכֻלָּן בָּאוֹת מִמָּקוֹם אֶחָד. שֶׁנִּשְׁמוֹתֵיהֶם שֶׁל הַצַּדִּיקִים הֵן מִשְּׁתֵּי דְרָגוֹת שֶׁכְּלוּלוֹת בְּאַחַת, וּמִשּׁוּם כָּךְ עוֹלוֹת יוֹתֵר, וְדַרְגָּתָן יְתֵרָה, וְכָךְ זֶה. וְכָל אוֹתָן שֶׁהָיוּ טְמוּנוֹת שָׁם, יָרְדוּ וְעָלוּ בְחַיֵּיהֶן, כְּמוֹ חֲנוֹךְ שֶׁלֹּא נִמְצְאָה בּוֹ מִיתָה. וַהֲרֵי בֵּאַרְנוּ הַדָּבָר הַזֶּה בַּחֲנוֹךְ וְאֵלִיָּהוּ."],[2,"","וְלָמַדְנוּ, מֵאָה וְעֶשְׂרִים וַחֲמִשָּׁה אֶלֶף דְּרָגוֹת (לצדיקים) הֵן לְנִשְׁמוֹת הַצַּדִּיקִים שֶׁעָלוּ בְרָצוֹן בְּטֶרֶם שֶׁנִּבְרָא הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזַמֵּן אוֹתָן לָעוֹלָם הַזֶּה בְּכָל דּוֹר וָדוֹר, וְעוֹלוֹת וְטָסוֹת בָּעוֹלָם, וְנִקְשָׁרוֹת לִצְרוֹר הַחַיִּים. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְחַדֵּשׁ בָּהֶן אֶת הָעוֹלָם. עֲלֵיהֶם כָּתוּב (ישעיה סו) כִּי כַאֲשֶׁר הַשָּׁמַיִם הַחֲדָשִׁים וְהָאָרֶץ הַחֲדָשָׁה וְגוֹ'."],[3,"","תְּעַנּוּ אֶת נַפְשּתֵיכֶם, נַפְשֹׁתֵיכֶם הוּא אָמַר, כִּי יִשְׂרָאֵל נִמְצָאִים צַדִּיקִים לִפְנֵי הַמֶּלֶךְ הַקָּדוֹשׁ, וְיִהֶיה הָרָצוֹן שֶׁלָּהֶם אֶל הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִדָּבֵק בּוֹ כְּדֵי שֶׁיִּתְכַּפֵּר לָהֶם חֶטְאָם. וְלָכֵן, מִי שֶׁאוֹכֵל וְשׁוֹתֶה בַּתְּשִׁיעִי וּמְעַנֵּג אֶת נַפְשׁוֹ בְּמַאֲכָל וּבְמִשְׁתֶּה, נִמְצָא בַּעֲשִׂירִי עִנּוּי נֶפֶשׁ בִּשְׁנֵי חֲלָקִים, וְנִמְצָא כְּאִלּוּ הִתְעַנָּה תְשִׁיעִי וַעֲשִׂירִי. אֶת נַפְשֹׁתֵיכֶם - לְהַכְלִיל אֶת הַכֹּל, גּוּף וָנֶפֶשׁ, וּלְהִכָּנַע בַּיּוֹם הַזֶּה, כְּדֵי לְכַפֵּר עַל חֶטְאָם."],[4,"","לָמַדְנוּ, כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם. בַּיּוֹם הַזֶּה?! הַיּוֹם הַזֶּה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא בַּיּוֹם הַזֶּה דַּוְקָא, שֶׁבּוֹ מִתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ לְכַפֵּר עַל חֲטָאֵי כֻּלָּם."],[5,"","דָּבָר אַחֵר תְּעַנּוּ אֶת נַפְשּתֵיכֶם - רַבִּי אַבָּא פָּתַח וְאָמַר, (קהלת ט) עִיר קְטַנָּה וַאֲנָשִׁים בָּהּ מְעָט וְגוֹ'. עִיר קְטַנָּה, הֲרֵי פֵּרְשׁוּהָ. אֲבָל עִיר קְטַנָּה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) עִיר עָז לָנוּ יְשׁוּעָה יָשִׁית חוֹמוֹת וָחֵל וְגוֹ'. וְכָתוּב (הושע יא) וְלֹא אָבוֹא בְּעִיר. עִיר קְטַנָּה, קְטַנָּה הִיא, שֶׁהִיא אַחֲרוֹנָה מֵהַכֹּל וְתַחְתּוֹנָה מֵהַכֹּל. חוֹמוֹתֶיהָ גְּדוֹלוֹת, חֲזָקוֹת, קְדוֹשׁוֹת, נִקְרֵאת עִיר הַקֹּדֶשׁ. וַאֲנָשִׁים בָּהּ מְעָט, מְעַטִּים אוֹתָם שֶׁזּוֹכִים לִכָּנֵס לְתוֹכָהּ וְלִשְׁרוֹת בָּהּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים כד) מִי יַעֲלֶה בְהַר ה' וּמִי יָקוּם בִּמְקוֹם קָדְשׁוֹ וְגוֹ'. וְעַל זֶה אֲנָשִׁים בָּהּ מְעָט."],[6,"","וּבָא אֵלֶיהָ מֶלֶךְ גָּדוֹל - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהִזְדַּוֵּג עִמָּהּ וְלִשְׁרוֹת בָּהּ. וְסָבַב אֹתָהּ, כְּמוֹ שֶׁנֶּאֱמַר (זכריה ב) וַאֲנִי אֶהְיֶה לָּהּ נְאֻם ה' חוֹמַת אֵשׁ סָבִיב וְגוֹ'. וּבָנָה עָלֶיהָ מְצוֹדִים גְּדלִים, שֶׁבָּנָה חוֹמוֹתֶיהָ גְּדוֹלִים וַחֲזָקִים, נָאִים וְיָפִים (מכל אבנים יקרות) וּקְדוֹשִׁים. וְנִקְרֵאת עִיר הַקֹּדֶשׁ, וְאֶת כָּל כְּבוֹד הַמֶּלֶךְ הִכְנִיס לְתוֹכָהּ. וּמִשּׁוּם כָּךְ הִיא לְבַדָּהּ כְּלוּלָה מִכָּל עַטְרוֹת הַמֶּלֶךְ, וְכָל עַטְרוֹת הַמֶּלֶךְ מִתְעַטְּרִים בָּהּ. מִשּׁוּם כָּךְ כָּתוּב, וַאֲנָשִׁים בָּהּ מְעָט."],[7,"","וּמָצָא בָהּ אִישׁ מִסְכֵּן (ו) חָכָם, זֶהוּ שֶׁכָּתוּב נְקִי כַפַּיִם וּבַר לֵבָב. מִסְכֵּן, כְּמוֹ שֶׁנֶּאֱמַר (שמות א) וַיִּבֶן עָרֵי מִסְכְּנוֹת לְפַרְעֹה. מִתְעַטֵּר בַּעֲטָרוֹת חֲזָקוֹת, בְּעַטְרוֹת הַתּוֹרָה, בַּעֲטָרוֹת שֶׁל מִצְווֹת תּוֹרַת הַמֶּלֶךְ. וְחָכָם, שֶׁזּוֹכֶה בָּהּ בַּחָכְמָה הַזֹּאת. וְחָכָם, שֶׁהוּא יוֹתֵר חָכָם מִכֻּלָּם לְעַיֵּן בַּעֲבוֹדַת רִבּוֹנוֹ כְּדֵי לִזְכּוֹת בָּהּ וּלְהִכָּנֵס אֵלֶיהָ. זֶהוּ שֶׁכָּתוּב וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ. וּמִלַּט, כְּמוֹ (שמואל א כ) אִמָּלְטָה נָּא וְאֶרְאֶה אֶת אֶחָי, אִמָּלְטָה נָּא שָׁמָּה. אַף כָּאן, וּמִלַּט הוּא אֶת הָעִיר בְּחָכְמָתוֹ."],[8,"","וְאָדָם לֹא זָכַר אֶת הָאִישׁ הַמִּסְכֵּן הַהוּא. וְאָדָם לֹא זָכַר, לַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, לְהִשְׁתַּדֵּל בַּתּוֹרָה כְּאוֹתוֹ אִישׁ עָנִי שֶׁהִתְחַבֵּר בַּכֹּל כְּדֵי לִזְכּוֹת בָּהּ. (קהלת ט) וְאָמַרְתִּי אָנִי טוֹבָה חָכְמָה מִגְּבוּרָה. שֶׁהֲרֵי בְּאוֹתוֹ עוֹלָם לֹא נוֹתְנִים רְשׁוּת לְהִכָּנֵס, פְּרָט לְאוֹתָם צַדִּיקֵי אֱמֶת, אֵלּוּ שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת, וּמִתְעַטְּרִים בְּמִצְווֹת הַתּוֹרָה בָּעוֹלָם הַזֶּה לְהִכָּנֵס בָּהֶם לָעוֹלָם הַבָּא."]]],[["וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים. דְּהָא בְּנֵי נָשָׁא לָא מִסְתַּכְּלִין בֵּיהּ, וְלָא בָּעָאן לְאִתְחַבְּרָא בֵּיהּ, וּלְאָצִית לְמִלּוֹי. דְּתָנָא, כָּל מַאן דְּאָצִית לְמִלּוֹי דְּאוֹרַיְיתָא, זַכָּאָה הוּא בְּהַאי עָלְמָא, וּכְאִלּוּ קַבִּיל תּוֹרָה מִסִּינַי. וַאֲפִילּוּ מִכָּל בַּר נָשׁ נָמֵי בָּעֵי לְמִשְׁמַע מִלּוֹי דְּאוֹרַיְיתָא. וּמַאן דְּאַרְכִין אוּדְנֵיהּ לָקֳבְלֵיהּ, יָהִיב יְקָרָא לְמַלְכָּא קַדִּישָׁא, וְיָהִיב יְקָרָא לְאוֹרַיְיתָא. עָלֵיהּ כְּתִיב, (דברים כ״ז:ט׳) הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם לַיְיָ' אֱלֹהֶיךָ.","תָּאנָא, יוֹמָא חַד הֲווֹ אַזְלֵי חַבְרַיָּיא עִמֵּיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר רַבִּי שִׁמְעוֹן, חֲמֵינָא אִלֵּין עַמִּין כֻּלְּהוּ עִלָּאֵי, וְיִשְׂרָאֵל תַּתָּאֵי מִכֻּלְּהוּ, מַאי טַעֲמָא. בְּגִין דְּמַלְכָּא אַשְׁדַר מַטְרוֹנִיתָא מִינֵּהּ, וְאָעִיל אַמָּהוּ בְּאַתְרָהָא (כלומר שפחה). כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:כ״ג) תַּחַת שָׁלֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ'. וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. מַאן שִׁפְחָה. הִיא כִּתְרָא נוּכְרָאָה, דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בּוּכְרָא דִּלְהוֹן בְּמִצְרַיִם. דִּכְתִיב (שמות י״א:ה׳) עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם. אַחַר הָרֵחָיִם הֲוַת יָתְבָא בְּקַדְמִיתָא, וְהַשְׁתָּא, הַאי שִׁפְחָה תִּירַשׁ גְּבִירְתָּהּ.","בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, מַלְכָּא בְּלָא מַטְרוֹנִיתָא, לָא אִקְרֵי מַלְכָּא. מַלְכָּא דְּאִתְדַּבָק בְּשִׁפְחָה בְּאֲמָּהוּ דְּמַטְרוֹנִיתָא, אָן הוּא יְקָרָא דִּילֵיהּ. וּזְמִינָא קָלָא לְבַשְּׂרָא לְמַטְרוֹנִיתָא, וְלֵימָא (זכריה ט׳:ט׳) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלַ ם הִנֵּה מַלְכֵּךְ יָבֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. כְּלוֹמַר, צַדִּיק הוּא נוֹשָׁע, בְּגִין דְּהֲוָה רָכִיב עַד הַשְׁתָּא בַּאֲתַר דְּלָאו דִּילֵיהּ, בַּאֲתַר נוּכְרָאָה, וְיָנִיק לֵיהּ.","וְעַל דָּא כְּתִיב עָנִי וְרוֹכֵב עַל חֲמוֹר, עָנִי (דלא) הֲוָה בְּקַדְמִיתָא, וְרוֹכֵב עַל חֲמוֹר, כְּמָה דְּאוֹקִימְנָא, אִינּוּן כִּתְרִין תַּתָּאִין דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּקָטִיל קוּדְשָׁא בְּרִיךְ הוּא בּוּכְרָא דִּלְהוֹן בְּמִצְרַיִם, הֲדָא הוּא דִכְתִיב, (שמות י״א:ה׳) וְכָּל בְּכוֹר בְּהֵמָה, וְהָא אוֹקִימְנָא מִלֵּי. כִּבְיָכוֹל צַדִיק וְנוֹשָׁע הוּא, הוּא וַדַּאי יַתִּיר מִכֹּלָּא. בְּגִין דְּעַד הַשְׁתָּא שָׁארֵי צַדִּיק בְּלָא צֶדֶק. וְהַשְׁתָּא דְּיִזְדַּוְּוגוּן כַּחֲדָא, צַדִיק וְנוֹשָׁע הוּא, דְּהָא לָא יָתִיב בְּסִטְרָא אָחֳרָא. תָּאנָא, (ישעיהו נ״ז:א׳) הַצַּדִיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְגוֹ', הַאי קְרָא קַשְׁיָא, הַצַּדִיק אָבָד, נֶאֱבַד מִבָּעֵי לֵיהּ, מַהוּ אָבָד. אֶלָּא אָבָד מַמָּשׁ, וּמַאי אָבָד. אָבַד לְמַטְרוֹנִיתָא, וְאִתְדַּבָק בַּאֲתַר אָחֳרָא, דְּאִקְרֵי שִׁפְחָה.","אָמַר רִבִּי יִצְחָק לְרִבִּי שִׁמְעוֹן, אִי נִיחָא קָמֵי דְּמֹר, הָא דְּתָנֵינָן, דִּכְתִיב (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם, מַאן דְּאָמַר, דְּעַל שִׁבְעָה קַיְימִין קַיְּימָא עָלְמָא. וּמַאן דְּאָמַר, עַל חַד קַיְּימָא עָלְמָא, הֵיךְ מִתְיַישְּׁבָן מִלֵּי. אָמַר לֵיהּ, כֹּלָּא מִלָּה חַד הוּא, דְּהָא ז' אִינּוּן וּבְהוּ אִית חַד קַיְּימָא, דְּאִקְרֵי צַדִּיק, וְקַיְימֵי עָלֵיהּ, וְעָלְמָא בְּהַאי אִתְקַיְּימָא. וְכַד אִתְקַיְּימָא עָלְמָא עָלֵיהּ, כְּאִלּוּ אִתְקַיָּים עַל כֻּלְּהוּ שִׁבְעָה. וְעַל דָּא כְּתִיב, וְצַדִּיק יְסוֹד עוֹלָם. וְהָא אוֹקִימְנָא מִלֵּי בְּכַמָּה אֲתַר.","וְתָאנָא, הַאי שִׁפְחָה זְמִינָא לְשַׁלְּטָאָה בְּאַרְעָא קַדִּישָׁא דִּלְתַּתָּא, כְּמָה דַּהֲוַת מַטְרוֹנִיתָא שַׁלְטָא בְּקַדְמִיתָא, דִּכְתִיב (ישעיהו א׳:כ״א) צֶדֶק יָלִין בָּהּ, וְהַשְׁתָּא שִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ בְּכֹלָּא. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְאָתָבָא לְמַטְרוֹנִיתָא לְאַתְרָהָא כְּקַדְמֵיתָא, וּכְדֵין מִמַּאן הוּא חֶדְוָותָא, הֲוִי אֵימָא חֶדְוָותָא דְּמַלְכָּא, וְחֶדְוָותָא דְּמַטְרוֹנִיתָא. חֶדְוָותָא דְּמַלְכָּא, בְּגִין דְּיֵתוּב לָהּ וְיִתְפְּרַשׁ מִשִּׁפְחָה, כַּדְקָא אֲמֵינָא. וְחֶדְוָותָא דְּמַטְרוֹנִיתָא, בְּגִין דְּתֵיתוּב לְאִזְדַּוְּוגָא בְּמַלְכָּא, הֲדָא הוּא דִכְתִיב גִּילִי מְאֹד בַּת צִיּוֹן וְגוֹ'.","תָּא חֲזֵי, כְּתִיב וְהָיְתָה זֹּאת לָכֶם לְחֻקַּת עוֹלָם. וְהָיְתָה לָכֶם מִבָּעֵי לֵיהּ, מַאי זֹאת. הָא דְּאַמָרָן, לְחֻקַּת עוֹלָם. בְּכָל אֲתַר וַאֲתַר חֻקַּת עוֹלָם אִתְקְרֵי, גְּזֵרַה דְּמַלְכָּא, דְּעַיִּיל כָּל נִמוּסוֹי בַּאֲתַר דָּא, וְאַסְתִּים לוֹן, כְּמָאן דְּסָתִים כֹּלָּא, בְּאַסְקוּפָא חֲדָא. (ק\"פ) חֻקַּת עוֹלָם וַדַאי. בְּהַאי זֹאת רָשִׁים וְחָקַק כָּל גְּנִיזִין דִּילֵיהּ, וְכָל טְמִירִין דִּילֵיהּ."],[[0,"וחכמת המסכן בזויה ודבריו אינם נשמעים:","כי בני אדם אינם רוצים להסתכל בו, ואינם רוצים להתחבר עמו ולהקשיב לדבריו. כי למדנו, כל מי שמקשיב לדברי תורה, אשרי הוא בעולם הזה, ודומה כאלו קבל התורה מסיני. ואפילו מכל אדם צריכים לשמוע דברי תורה. ומי שמטה אזנו אליו, נותן כבוד למלך הקדוש, ונותן כבוד לתורה. עליו כתוב, היום הזה נהיית לעם לה׳ אלקיך."],[1,"תאנא יומא חד וכו׳:","למדנו, יום אחד, היו הולכים החברים עם ר׳ שמעון. א״ר שמעון, אני רואה כל העמים שהם עליונים, וישראל תחתונים מכולם, מהו הטעם. הוא משום שהמלך שלח את המלכה ממנו, והכניס שפחה במקומה. כש״א, תחת שלש רגזה ארץ וגו׳ תחת עבד כי ימלוך וגו', ושפחה כי תירש גבירתה. מי היא השפחה, היא המלכות הנכריה של הס\"א, שהקב״ה הרג את הבכור שלהם במצרים. שכתוב, עד בכור \u0003השפחה\u0004 אשר אחר הריחים. אחר הריחים היתה יושבת מתחילה, ועתה שפחה זו תירש גבירתה. שבמקום להשפיע אל המלכות הקדושה, לוקחת שפחה זו דס״א כל השפע ומשפעת להעמים שהם מן הצד שלה."],[2,"בכה ר״ש ואמר וכו׳:","בכה ר׳ שמעון ואמר, מלך בלא מלכה אינו נקרא מלך. מלך שנתדבק בשפחה, באמה של המלכה, איפה הכבוד שלו. וקול עתיד לבשר אל המלכה ולומר, גילי מאד בת ציון הריעי בת ירושלים הנה מלכך יבא לך צדיק ונושע הוא. כלומר, הצדיק, שהוא יסוד, הוא שנושע, משום שהיה רוכב עד עתה, במקום שאינו שלו, במקום זר, דהיינו השפחה, והניק אותו. ועתה חזרה אליו המלכה."],[3,"ועל דא כתיב וכו׳:","ועל זה כתוב, \u0003עני ורוכב על חמור,\u0004 כי עני היה מתחילה, ורוכב על חמור, כמו שהעמדנו, שהוא כתרים התחתונים של העמים עכו״ם, שהקב״ה הרג הבכור שלהם במצרים, שהם נקראים חמור, ז״ש וכל בכור בהמה. וכבר העמדנו הדברים. כביכול, \u0003צדיק ונושע הוא,\u0004 שהוא נושע ודאי יותר מכל. משום שעד עתה היה שורה הצדיק, שהוא יסוד, בלא צדק, שהיא מלכות, ועתה שיזדווגו יחד, צדיק וצדק, \u0003צדיק ונושע הוא,\u0004 כי אינו יושב עוד בסטרא אחרא. למדנו, הצדיק אבד ואין איש שם על לב וגו'. מקרא זה קשה, אומר הצדיק אבד, נאבד היה צריך לומר, מהו אבד. ומשיב, אלא אבד ממש. ומה אבד. אבדה המלכה, ונתדבק במקום אחר שנקרא שפחה."],[4,"אמר ר׳ יצחק וכו׳:","אר״י לר׳ שמעון, אם לפני אדוני טוב, זה שלמדנו, שכתוב, וצדיק יסוד עולם, יש מי שאומר, שעל שבעה עמודים העולם עומד, ויש מי שאומר, שעל עמוד אחד העולם, שהוא יסוד, שעליו נאתר וצדיק יסוד עולם, איך מתישבים הדברים שלא יהיו סותרים זא״ז. אמר לו הכל דבר אחד הוא. כי שבעה הם, דהיינו ז״ס חג״ת נהי״מ, ובהם יש עמוד אחד שנקרא צדיק, שהוא יסוד, והשבעה עומדים עליו, והעולם מתקיים על ידו. וכשנתקיים העולם על ידו, הוא כאלו מתקיים על כל השבעה. כי היסוד כולל בעצמו כל ז״ס חג״ת נהי״מ. וע״כ כתוב, וצדיק יסוד עולם. וכבר העמדנו הדברים בכמה מקומות."],[5,"ותאנא האי שפחה וכו׳:","ולמדנו, שפחה זו עתידה לשלוט בארץ הקדושה שלמטה, כמו שמתחילה היתה שולטת המלכה. שכתוב, צדק ילין בה, שהיא המלכות הנקראת צדק. ועתה, ושפתה כי תירש גברתה, בכל, הן למעלה והן למטה. ועתיד הקב״ה להשיב את המלכה למקומה כבתחילה, ואז, שמחת מי היא. הוי אומר, שמחת המלך ושמחת המלכה. שמחת המלך היא, משום שהשיב אותה ונפרד מן השפחה, כמו שאמרנו. ושמחת המלכה היא, משום שחזרה להתחבר במלך. ז״ש גילי מאד בת ציון וגו'."],[6,"ת״ח כתיב וכו׳:","בוא וראה, כתוב, והיתה זאת לכם לחוקת עולם. שואל, והיתה לכם היה צריך לומר, מהו, זאת. ומשיב, שפירוש הכתוב הוא, זה שאמרנו, הוא לחקת עולם, שהיא המלכות, בכל מקום ומקום היא נקראת חקת עולם, שפירושו, גזירת המלך. כי הכניס כל חוקותיו במקום הזה, במלכות, וסתם אותם, כמי שסותם הכל באוצר אחד, והיא חקת עולם ודאי. ב \u0003זאת\u0004 זו, שהיא המלכות, רשם וחקק כל האוצרות שלו וכל הנסתרות שלו. \u0003אסקופה\u0004 (עי׳ פירושו לעיל ב״ב דף ק״ה ד\"ה א״ל)."]],[[0,"","וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים. שֶׁהֲרֵי בְּנֵי אָדָם אֵינָם מִסְתַּכְּלִים עָלָיו, וְלֹא רוֹצִים לְהִתְחַבֵּר עִמּוֹ וּלְהַקְשִׁיב לִדְבָרָיו. שֶׁלָּמַדְנוּ, כָּל מִי שֶׁמַּקְשִׁיב לְדִבְרֵי הַתּוֹרָה, אַשְׁרָיו בָּעוֹלָם הַזֶּה, וּכְאִלּוּ קִבֵּל תּוֹרָה מִסִּינַי. וַאֲפִלּוּ מִכָּל אָדָם גַּם כֵּן צָרִיךְ לִשְׁמֹעַ דִּבְרֵי תוֹרָה. וּמִי שֶׁמַּרְכִּין אָזְנָיו כְּנֶגְדּוֹ, נוֹתֵן כָּבוֹד לַמֶּלֶךְ הַקָּדוֹשׁ וְנוֹתֵן כָּבוֹד לַתּוֹרָה. עָלָיו כָּתוּב, הַיּוֹם הַזֶּה נִהְיֵיתָ לְעָם לַה' אֱלֹהֶיךְ."],[1,"","לָמַדְנוּ, יוֹם אֶחָד הָיוּ הוֹלְכִים הַחֲבֵרִים עִם רַבִּי שִׁמְעוֹן. אָמַר רַבִּי שִׁמְעוֹן, רָאִיתִי שֶׁהָעַמִּים הַלָּלוּ כֻּלָּם עֶלְיוֹנִים, וְיִשְׂרָאֵל תַּחְתּוֹנִים מִכֻּלָּם. מָה הַטַּעַם? מִשּׁוּם שֶׁהַמֶּלֶךְ שָׁלַח מִמֶּנּוּ אֶת הַגְּבִירָה, וְהִכְנִיס אָמָה בִּמְקוֹמָהּ (כלומר שפחה), כְּמוֹ שֶׁנֶּאֱמַר, (משלי ל) תַּחַת שָׁלוֹשׁ רָגְזָה אֶרֶץ וְגוֹ'. תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְגוֹ'. וְשִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ. מִי הַשִּׁפְחָה? זוֹהִי כֶּתֶר הַנָּכְרִי, שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא הַבְּכוֹר שֶׁלָּהֶם בְּמִצְרַיִם, שֶׁכָּתוּב (שמות יא) עַד בְּכוֹר הַשִּׁפְחָה אֲשֶׁר אַחַר הָרֵחָיִם. אַחַר הָרֵחָיִם הִיא הָיְתָה יוֹשֶׁבֶת בָּרִאשׁוֹנָה, וְעַכְשָׁו הַשִּׁפְחָה הַזּוֹ תִּירַשׁ גְּבִרְתָּהּ."],[2,"","בָּכָה רַבִּי שִׁמְעוֹן וְאָמַר, מֶלֶךְ בְּלִי גְבִירָה לֹא נִקְרָא מֶלֶךְ. מֶלֶךְ שֶׁנִּדְבָּק בַּשִּׁפְחָה, בָּאָמָה (שלה) שֶׁל הַגְּבִירָה, אֵיפֹה כְבוֹדוֹ? וְעָתִיד קוֹל לְבַשֵּׂר לַגְּבִירָה וְלוֹמַר: (זכריה ט) גִּילִי מְאֹד בַּת צִיּוֹן הָרִיעִי בַּת יְרוּשָׁלם הִנֵּה מַלְכֵּךְ יָבוֹא לָךְ צַדִּיק וְנוֹשָׁע הוּא. כְּלוֹמַר, צַדִּיק הוּא נוֹשָׁע, כִּי הָיָה רוֹכֵב עַד עַכְשָׁו בְּמָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ, בִּמְקוֹם נָכְרִי, וּמֵינִיק אוֹתוֹ."],[3,"","וְעַל זֶה כָּתוּב עָנִי וְרֹכֵב עַל חֲמוֹר. עָנִי (שלא) הָיָה בָּרִאשׁוֹנָה, וְרֹכֵב עַל חֲמוֹר, כְּמוֹ שֶׁבֵּאַרְנוּ, אוֹתָם כְּתָרִים תַּחְתוֹנִים שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁהָרַג הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַבְּכוֹר שֶׁלָּהֶם בְּמִצְרַיִם. זֶהוּ שֶׁכָּתוּב (שמות יא) וְכָל בְּכוֹר בְּהֵמָה, וַהֲרֵי בֵּאַרְנוּ הַדְּבָרִים. כִּבְיָכוֹל צַדִּיק וְנוֹשָׁע הוּא, הוּא וַדַּאי יוֹתֵר מֵהַכֹּל. כִּי עַד עַכְשָׁו שָׁרוּי צַדִּיק בְּלִי צֶדֶק. וְעַכְשָׁו שֶׁיִּזְדַּוְּגוּ כְאֶחָד, צַדִּיק וְנוֹשָׁע הוּא, שֶׁהֲרֵי אֵינוֹ יוֹשֵׁב בַּצַּד הָאַחֵר. לָמַדְנוּ, (ישעיה נז) הַצַּדִּיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְגוֹ'. פָּסוּק זֶה קָשֶׁה. הַצַּדִּיק אָבָד?! נֶאֱבַד הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אָבָד? אֶלָּא אָבַד מַמָּשׁ. וּמָה אָבַד? אָבַד לַגְּבִירָה, וְנִדְבַּק בְּמָקוֹם אַחֵר, שֶׁנִּקְרָא שִׁפְחָה."],[4,"","אָמַר רַבִּי יִצְחָק לְרַבִּי שִׁמְעוֹן, אִם נוֹחַ לִפְנֵי מוֹרִי, זֶה שֶׁשָּׁנִינוּ שֶׁכָּתוּב (משלי י) וְצַדִּיק יְסוֹד עוֹלָם, יֵשׁ מִי שֶׁאוֹמֵר שֶׁעַל שִׁבְעָה עַמּוּדִים עוֹמֵד הָעוֹלָם, וְיֵשׁ מִי שֶׁאוֹמֵר עַל עַמּוּד אֶחָד עוֹמֵד הָעוֹלָם, אֵיךְ הַדְּבָרִים מִתְיַשְּׁבִים? אָמַר לוֹ, הַכֹּל הוּא דָּבָר אֶחָד, שֶׁהֲרֵי שִׁבְעָה הֵם, וּבָהֶם יֵשׁ עַמּוּד אֶחָד שֶׁנִּקְרָא צַדִּיק, וְעוֹמְדִים עָלָיו, וְהָעוֹלָם מִתְקַיֵּם עַל זֶה. וּכְשֶׁהָעוֹלָם מִתְקַיֵּם עָלָיו, כְּאִלּוּ שֶׁהִתְקַיֵּם עַל כָּל הַשִּׁבְעָה, וְעַל כֵּן כָּתוּב וְצַדִּיק יְסוֹד עוֹלָם, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים בְּכַמָּה מְקוֹמוֹת."],[5,"","וְלָמַדְנוּ, הַשִּׁפְחָה הַזּוֹ עֲתִידָה לִשְׁלֹט בָּאָרֶץ הַקְּדוֹשָׁה שֶׁלְּמַטָּה, כְּמוֹ שֶׁהָיְתָה הַגְּבִירָה שׁוֹלֶטֶת בָּרִאשׁוֹנָה, שֶׁכָּתוּב צֶדֶק יָלִין בָּהּ, וְעַכְשָׁו שִׁפְחָה כִּי תִירַשׁ גְּבִרְתָּהּ, בַּכֹּל. וְעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב אֶת הַגְּבִירָה לִמְקוֹמָהּ כְּבָרִאשׁוֹנָה, וְאָז שֶׁל מִי הִיא הַשִּׂמְחָה? הֱוֵי אוֹמֵר, שִׂמְחַת הַמֶּלֶךְ וְשִׂמְחַת הַגְּבִירָה. שִׂמְחַת הַמֶּלֶךְ, מִשּׁוּם שֶׁיָּשִׁיב אוֹתָהּ וְיִפָּרֵד מִן הַשִּׁפְחָה כְּפִי שֶׁאָמַרְנוּ. וְשִׂמְחַת הַגְּבִירָה, כִּי תָשׁוּב לְהִזְדַּוֵּג עִם הַמֶּלֶךְ. זֶהוּ שֶׁכָּתוּב גִּילִי מְאֹד בַּת צִיּוֹן וְגוֹ'."],[6,"","בֹּא רְאֵה, כָּתוּב וְהָיְתָה זֹּאת לָכֶם לְחֻקַּת עוֹלָם. וְהָיְתָה לָכֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה זֹּאת? זֶה שֶׁאָמַרְנוּ, לְחֻקַּת עוֹלָם. בְּכָל מָקוֹם וּמָקוֹם חֻקַּת עוֹלָם נִקְרֵאת, גְּזֵרַת הַמֶּלֶךְ, שֶׁמַּכְנִיס אֶת כָּל הַנְהָגוֹתָיו בַּמָּקוֹם הַזֶּה וּמַסְתִּיר אוֹתָם, כְּמוֹ שֶׁמַּסְתִּיר הַכֹּל בְּאוֹצָר אֶחָד. חֻקַּת עוֹלָם וַדַּאי. בָּזֹּאת הַזּוֹ רָשַׁם וְחָקַק אֶת כָּל הַגְּנָזִים שֶׁלּוֹ וְאֶת כָּל הַמַּטְמוֹנִים שֶׁלּוֹ."]]],[["(ויקרא ט״ז:כ״ט) בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר דַּיְיקָא, כְּמָה דְּאוֹקִימְנָא. תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם, וַדַּאי הָכִי הוּא, וְהָא אִתְּמַר נַפְשׁוֹתֵיכֶם וַדַּאי. דְּהָא בְּנַפְשָׁא תַּלְיָא מִלְּתָא, וּבְגִין כַּךְ, אֲכִילָה וּשְׁתִיָּה מִתְּשִׁיעָאָה, יַתִיר מִיּוֹמָא אָחֳרָא. וְאַף עַל גַּב דְּהַאי מִלָּה אִתְּמַר בְּגַוְונָא אָחֳרָא, וְכֹלָּא שַׁפִּיר, וְהַאי וְהַאי מִלָּה חֲדָא, וְכָל חַד בְּאַתְרֵיהּ, וְהָכִי הוּא.","וְתָאנָא, בְּהַאי יוֹמָא, כָּל חֵידוּ, וְכָל נְהִירוּ, וְכָל וַותְּרָנוּתָא דְּעָלְמִין, כֻּלְּהוּ תַּלְיָין בְּאִימָּא עִלָּאָה, דְּכָל מַבּוּעִין נַגְדִּין וְנָפְקִין מִנָּהּ. וּכְדֵין נְהִירִין כָּל אִינּוּן בּוּצִינִין, וְנַהֲרִין בִנְהִירוּ בְּחֶדְוָותָא, עַד דְּמִתְבְּסַם כֹּלָּא. וּכְדֵין כָּל אִינּוּן דִּינִין אִשְׁתְּכָחוּ בִּנְהִירוּ, וְדִינָא לָא אִתְעָבִיד, וְעַל דָּא תְּעַנּוּ אֶת נַפְשׁוֹתֵיכֶם.","אָמַר רִבִּי אַבָּא, הָא אוֹקִים לָהּ מֹר, מִן גּוּפָא דְּמַתְנִיתָא, לָא גָּלוּ יִשְׂרָאֵל מֵאַרְצָם, עַד שֶׁכָּפְרוּ בְּקוּדְשָׁא בְּרִיךְ הוּא. דִּכְתִּיב, (שמואל ב כ׳:א׳) אֵין לָנוּ חֵלֶק בְּדָוִד וְלֹא נַחֲלָה בְּבֶן יִשַׁי, וְהָא אִתְּמַר. קְרָא אַחֲרִינָא אַשְׁכַּחְנָא בְּהַאי, דִּכְתִּיב, (מלכים א י״ב:ט״ז) רְאֵה בֵיתְךָ דָּוִד. אָמַר לֵיהּ, הָכִי הוּא וַדַּאי, בֵּית דָּוִד אִקְרֵי, כְּמָה דִּכְתִּיב, (ישעיהו ב׳:ה׳) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר יְיָ'. בֵּית יַעֲקֹב, כְּמָה דְאַתְּ אָמֵר (ישעיהו ס׳:ז׳) וּבֵית תִּפְאַרְתִּי אֲפָאֵר. לְכוּ וְנֵלְכָה בְּאוֹר יְיָ', דִּכְתִּיב, (בראשית ב׳:י׳) וְנָהָר יוֹצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וְנָטַע הַאי גַּן לְאִשְׁתַּעְשְׁעָא בֵּיהּ עִם צַדִּיקַיָּיא, דְּבֵיהּ שַׁרְיָין.","תָּאנָא, כְּתִיב אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפּוּרִים הוּא וְגוֹ' וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם. וּכְתִיב וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. אַךְ דִּכְתִּיב, מַאי קָא בָּעֵי הָכָא. אָמַר לֵיהּ, לְמִעוּטָא קָא אַתְיָא. דְּכֵיוָן דְּאָמַר וְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ, אָמַר לְבָתַר אַךְ בֶּעָשׂוֹר. אַךְ עָשׂוֹר מִבָּעֵי לֵיהּ, דְּבֶעָשׂוֹר תַּלְיָא מִלְּתָא.","אָמַר לֵיהּ אִי הָכִי, (שמות י״ב:ט״ו) אַךְ בַּיוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאוֹר מִבָּתֵּיכֶם, וְתָנֵינָן אַךְ חִלֵּק, חֶצְיוֹ אָסוּר בַּאֲכִילַת חָמֵץ, וְחֶצְיוֹ מוּתָּר. אוּף הָכָא אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ, אֵימָא דְּחֶצְיוֹ אָסוּר בַּמְּלָאכָה (נ\"א באכילה), וְחֶצְיוֹ מוּתָּר. אָמַר לֵיהּ אוּף הָכָא בִּוְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם תַּלְיָא, דְּהָא עִנּוּי לָא אִשְׁתְּכַח אֶלָּא מִפַּלְגּוּת יוֹמָא וּלְהָלְאָה, וְשַׁפִּיר הוּא אַךְ חִלֵּק בִּוְעִנִּיתֶם אֶת נַפְשׁוֹתֵיכֶם.","אָמַר רִבִּי אֶלְעָזָר, כְּתִיב, (ויקרא ט״ז:ל׳) כִּי בַּיוֹם הַזֶה יְכַפֵּר עֲלֵיכֶם וְגוֹ'. אֲכַפֵּר עַלֵיכֶם מִבָּעֵי לֵיהּ. אֶלָּא יְכַפֵּר עֲלֵיכֶם, לְאַכְלְלָא יוֹבְלָא, דְּנָגִיד מַבּוּעֵי לְאַשְׁקָאָה בְּהַאי יוֹמָא לְכָל עִיבָר, לְאַרְוָאָה כֹּלָּא, וּלְאַשְׁקָאָה כֹּלָּא. וְדָא עֲלֵיכֶם, כְּלוֹמַר, בְּגִינֵיכוֹן לְדַכְּאָה לְכוֹן בְּהַאי יוֹמָא, דִּכְתִּיב לִפְנֵי יְיָ' תִּטְהָרוּ. וְלָא יִשְׁלוֹט עָלַיְיכוּ דִּינָא.","רִבִּי יְהוּדָה, אָמַר זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וּבָעֵי לְדַכְּאָה לְהוּ, דְּלָא יִשְׁתְּכַּח בְּהוּ חוֹבָה, בְּגִין דִּיהוֹן בְּנֵי הֵיכָלֵיהּ, וִידוּרוּן בְּהֵיכָלֵיהּ. וּלְזִמְנָא דְּאָתֵי כְּתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וְגוֹ'.","רִבִּי יְהוּדָה פָּתַח, (תהילים ק״ל:א׳) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'. תָּנֵינָן, בְּשַׁעֲתָא דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּעָא לְמִבְרֵי בַּר נָשׁ, אַמְלִיךְ בְּאוֹרַיְיתָא, אָמְרָה קַמֵּיהּ, תִּבְעֵי לְמִבְרֵי הַאי בַּר נָשׁ, זַמִּין הוּא לְמֶחֱטֵי קַמָּךְ, זַמִּין הוּא לְאַרְגָּזָא קַמָּךְ. אִי תַּעֲבִיד לֵיהּ כְּעוֹבָדוֹי, הָא עָלְמָא לָא יָכִיל לְמֵיקָם קַמָּךְ, כָּל שֶׁכֵּן הַהוּא בַּר נָשׁ. אָמַר לֵיהּ, וְכִי לְמַגָּנָא אִתְקָרִינָא, (שמות ל״ד:ו׳) אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם.","וְעַד לָא בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא, בָּרָא תְּשׁוּבָה, אָמַר לָהּ לִתְשׁוּבָה, אֲנָא בָּעֵינָא לְמִבְרֵי בַּר נָשׁ בְּעָלְמָא, עַל מְנָת דְּכַד יְתוּבוּן לָךְ מֵחוֹבֵיהוֹן, דְּתֶהֱוִי זְמִינָא לְמִשְׁבַּק חוֹבֵיהוֹן, וּלְכַפְּרָא עָלַיְיהוּ. וּבְכָל שַׁעֲתָא וְשַׁעֲתָא תְּשׁוּבָה זְמִינָא לְגַבֵּי בְּנֵי נָשָׁא, וְכַד בְּנֵי נָשָׁא תַּיְיבִין מֵחוֹבַיְיהוּ, הַאי תְּשׁוּבָה תָּבַת לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְכִפֵּר עַל כֹּלָּא, וְדִינִין אִתְכַּפְיָין, וּמִתְבַּסְּמָן כֻּלְּהוּ, וּבַר נָשׁ אִתְדָּכֵי מֵחוֹבֵיהּ.","אֵימָתַי אִתְדָּכֵי בַּר נָשׁ מֵחוֹבֵיהּ בְּשַׁעֲתָא דְּעָאל בְּהַאי תְּשׁוּבָה כַּדְקָא חֲזֵי. רִבִּי יִצְחָק אָמַר, דְּתָב קָמֵי מַלְכָּא עִלָּאָה, וְצַלֵּי צְלוֹתָא מֵעוּמְקָא דְּלִבָּא, הֲדָא הוּא דִכְתִיב מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'."],[[0,"בחדש השביעי בעשור לחודש:","בעשור הוא בדיוק, כמו שהעמדנו שבעשור הוא מלכות. \u0003תענו את נפשותיכם.\u0004 ודאי כך הוא, והרי למדנו, נפשותיכם ודאי. כי בנפש תלוי הדבר, כי אור המלכות נקרא נפש, ונפש היא תמיד מלכות. ומשום זה אכילה ושתיה מתשעה לחדש, שהוא יסוד, הוא אז יותר מיום אחר. ואע\"פ שדבר זה למדנו באפן אחר (לעיל אות רכ\"ג) והכל יפה, וזה וזה דבר אחד הוא, וכל אחד במקומו, וכך הוא."],[0,"","פירוש, כבר ידעת שאי אפשר שתתגלה החכמה אם לא יופיעו דינים קשים עמה להמטיר על ראשי הרשעים, שלא ימשיכו החכמה ממעלה למטה, (כנ\"ל פקודי אות שע\"ו, וצו אות קי\"ד) וז\"ס ה' עינוים שביום הכפורים, שמהם נמשכים הדינים על ראשי הרשעים. שאז אפשר שתתגלה החכמה. וז\"ס כי כל הנפש אשר לא תעונה בעצם היום הזה, ונכרתה מעמיה. כי אם לא קבל ה' עינוים אלו להרחיק הרשעים, לא תוכל החכמה להופיע בנפש, ואור החכמה הוא אור החיים, וע\"כ ונכרתה מעמיה."],[0,"","וזה אמרו \u0003בעשור לחדש, בעשור דייקא,\u0004 שהוא המלכות ששם מקום גילוי החכמה, כי אין גילוי חכמה בשום ספירה אלא בספירת המלכות לבד. (כנ\"ל ב\"א דף רע\"ו ד\"ה ועוד) וע\"כ צריכים לקבוע שמה התקון הזה, שימשכו דינים ממנה על ראשי הרשעים בעת שתתגלה בה החכמה. וע\"כ \u0003תענו את נפשותיכם ודאי\u0004 וכו', שצריכים לעורר במלכות את ה' עינוים שמשם נמשכים הדינים האלה, \u0003דהא בנפשא תליא מלתא,\u0004 כי הדבר תלוי רק בנפש, שהיא בחינת מלכות, שרק שם מקום גילוי החכמה ולא במקום אחר. וע\"כ בעת שמתגלים בה הדינים תוכל לקבל החכמה מן היסוד דז\"א כי אין עוד פחד מפני הרשעים שיינקו ממנה. וז\"ש, \u0003ובגין כך אכילה ושתיה מתשיעאה יתיר מיומא אחרא.\u0004 שע\"כ תוכל המלכות לקבל המוחין דהארת חכמה המכונים אכילה ושתיה מן היסוד, יותר מביום אחר, כי אין המלכות מקבלת אלא מן \u0003היסוד.\u0004 וז\"ס שצריכים להרבות באכילה ושתיה בערב יוה\"כ שהוא תשיעי לחדש, דהיינו \u0003יסוד.\u0004 כי מתוך שמקבל ה' עינויים ביום הכפורים, היא ראויה לקבל אכילה ושתיה מן היסוד. באפן, שתקון עינוי הנפש שביוה\"כ, מאיר בתקון אכילה ושתיה שבתשיעי לחדש, להיותה נשמרת מהרשעים. וז\"ס שאמרו, כל האוכל ושותה בתשיעי מעלה עליו הכתוב, כאלו התענה תשיעי ועשירי. כי עינוי הנפש דעשירי מאיר על המוחין המושפעים בתשיעי. ושומר אותם."],[1,"ותאנא בהאי יומא וכו':","ולמדנו, ביום ההוא, כל שמחה וכל אור, וכל ויתור שבעולמות, דהיינו כפרת עונות, כולם תלוים באמא עלאה, שכל המבועים נמשכים ויוצאים ממנו. דהיינו הו הארת החכמה והן הארת החסדים, ואז מאירים כל אלו הנרות, שה\"ס מאורי האש שבמלכות, ומאירים באור ובשמחה עד שהכל מתבשם, ואז כל אלו הדינים נמצאים בהארה, כי אותם הדינים הנמשכים מה' עינוים, הם הגורמים שתאיר החכמה, ולולא הם, לא היתה החכמה מתגלה כנ\"ל, והדין אינו נעשה, אלא שהוא מאיים בלבד, ועל זה, תענו את נפשותיכם. כדי לאפשר הארת החכמה."],[2,"אמר ר' אבא וכו':","אר\"א, הרי אמר לנו אדני מן גוף המשנה, שלא גלו ישראל מארצם עד שכפרו בהקב\"ה, שכתוב, אין לנו חלק בדוד ולא נחלה בבן ישי. כי דוד הוא המלכות, ואמרו אין לנו חלק במלכות. ומקרא אחר מצאתי בזה, שכתוב, ראה ביתך דוד. ושואל, אם בית דוד, רומז ג\"כ על המלכות. אמר לו כך הוא, ודאי שהמלכות נקראת, בית דוד, כמ\"ש בית יעקב לכו ונלכה באור ה'. בית יעקב, הוא כמו שאתה אומר, ובית תפארתי אפאר, כי יעקב הוא תפארת, ובית תפארת הוא המלכות, אף בית דוד הוא מלכות. וביאור הכתוב, \u0003בית יעקב\u0004 לכו ונלכה באור ה'. פירושו, שכתוב, ונהר יוצא מעדן להשקות את הגן, אשר נהר הוא ז\"א המשקה את הגן שהוא המלכות. שנטע את הגן, להשתעשע בו עם הצדיקים השורים בו. ועל זה נאמר, בית יעקב, שהוא המלכות, לכו ונלכה באור ה', שהוא ז\"א, המשקה את המלכות."],[3,"תאנא כתיב אך וגו':","למדנו כתוב, אך בעשור לחדש השביעי וגו' ועניתם את נפשותיכם. וכתוב, והיתה לכם לחקת עולם בחדש השביעי בעשור לחדש תענו את נפשותיכם, ולא כתוב שם אך בעשור. \u0003אך\u0004 בעשור שכתוב כאן, מה הוא רוצה בזה. אמר לו הוא בא למיעוט. שבכל מקום שכתוב, \u0003אך,\u0004 הוא בא למעט. כי כיון שאמר ועניתם את נפשותיכם בתשעה לחדש, אמר אח\"כ \u0003אך\u0004 בעשור, והיה צריך לומר אך עשור, אלא להשמיענו, שבעשור תלוי הדבר של ועניתם את נפשותיכם, ולמעט התשיעי בחדש."],[4,"אמר ליה אי וכו':","א\"ל, אי הכי, אך ביום הראשון תשביתו שאור מבתיכם ולמדנו, \u0003אך\u0004 חלק, חציו אסור באכילת חמץ וחציו מותר. אף כאן שכתוב, \u0003אך\u0004 בעשור לחדש, נאמר, שחציו אסור באכילה וחציו מותר. אמר לו אף כאן בועניתם את נפשותיכם, מחולק, כי ענוי אינו נמצא אלא מחצי היום והלאה, דהיינו אחר זמן אכילה, ונמצא ש \u0003אך\u0004 חלק, יפה הוא גם בועניתם את נפשותיכם, \u0003תליא\u0004, פירושו מחולק, בלשון ויפשחני \u0003תלהי,\u0004 (אי\"ר דוב אורב)."],[5,"א\"ר אלעזר כתיב וכו':","אר\"א כתוב, כי ביום הזה יכפר עליכם וגו'. היה צריך לומר אכפר עליכם, כמדבר בעדו. ומשיב, אלא יכפר עליכם שאומר בלשון נסתר, כולל היובל, שהוא בינה, שנמשך ממנו מבועים, דהיינו הארת חכמה, להשקות ביום הזה לכל צד, לרוות הכל ולהשקות הכל, וזהו \u0003עליכם,\u0004 כלומר, בשבילכם, כדי לטהר אתכם ביום ההוא, שכתוב לפני ה' תטהרו. ולא ישלוט עליכם הדין."],[6,"ר' יהודה אמר וכו':","רי\"א, אשריהם ישראל, שהקב\"ה רצה בהם, ורצה לטהר אותם, שלא ימצא בהם עון, כדי שיהיו בני היכלו וידורו בהיכלו. ולעתיד לבא, כתוב, וזרקתי עליכם מים טהורים וגו'."],[7,"רבי יהודה פתח וכו':","רי\"פ, שיר המעלות ממעמקים קראתיך ה'. למדנו, בשעה שברא הקב\"ה את העולם, רצה לברוא את האדם, נתיעץ בתורה, אמרה לפניו, אתה רוצה לברוא אדם הזה, הוא עתיד לחטוא לפניך, הוא עתיד להרגיז לפניך, אם תתנהג עמו כמעשיו, הרי העולם לא יוכל לעמוד לפניך, כל שכן האדם ההוא. אמר לה הקב\"ה, וכי לחנם אני נקרא, אל רחום וחנון ארך אפים."],[8,"ועד לא ברא וכו':","ומטרם שברא הקב\"ה את העולם, ברא תשובה. אמר הקב\"ה לתשובה, שה\"ס בינה הנקראת תשובה, אני רוצה לברוא אדם בעולם, בתנאי, אם ישובו אליך מעונותיהם, תהיה מוכנת לסלוח עונותיהם ולכפר עליהם. ובכל שעה ושעה התשובה מוכנת לבני אדם, וכשבני אדם שבים מעונותיהם, תשובה זו, שהיא בינה, חוזרת אל הקב\"ה, דהיינו שמשפטת תוחין לז״א, ומכפרת על הכל. והדינים נכנעים ומתבשמים כולם, ואדם נטהר מעונותיו."],[9,"אימתי אתדכי וכו׳:","שואל. מתי נטהר האדם מעונו. ומשיב, בשעה שנכנס בתשובה ההיא כראוי. ר׳ יצחק אמר, בשעה ששב לפני המלך העליון, ומתפלל תפלה מעומק הלב. ז״ש ממעמקים קראתיך ה'."]],[[0,"","בַּחֹדֶשׁ הַשְּׁבִיעִי בֶּעָשׂוֹר לַחֹדֶשׁ. בֶּעָשׂוֹר בְּדִיִּוּק, כְּמוֹ שֶׁבֵּאַרְנוּ. תְּעַנּוּ אֶת נַפְשתֵיכֶם, וַדַּאי כָּךְ זֶה, וַהֲרֵי נֶאֱמַר נַפְשּתֵיכֶם וַדַּאי. שֶׁהֲרֵי בַּנֶּפֶשׁ תָּלוּי הַדָּבָר, וּמִשּׁוּם כָּךְ אֲכִילָה וּשְׁתִיָּה מֵהַתְּשִׁיעִי יוֹתֵר מִיּוֹם אַחֵר. וְאַף עַל גַּב שֶׁהַדָּבָר הַזֶּה נֶאֱמַר בְּגָוֶן אַחֵר, וְהַכֹּל יָפֶה, וְזֶה וָזֶה דָּבָר אֶחָד, וְכָל אֶחָד בִּמְקוֹמוֹ, וְכָךְ זֶה."],[1,"","וְלָמַדְנוּ, בַּיּוֹם הַזֶּה כָּל הַשִּׂמְחָה וְכָל הָאוֹר וְכָל הַסְּלִיחָה שֶׁל הָעוֹלָמוֹת, כֻּלָּם תְּלוּיִים בָּאֵם הָעֶלְיוֹנָה, שֶׁכָּל הַמַּעְיָנוֹת שׁוֹפְעִים וְיוֹצְאִים מִמֶּנָּה, וְאָז מְאִירִים כָּל אוֹתָם מְאוֹרוֹת, וּמְאִירִים בְּאוֹר וּבְשִׂמְחָה, עַד שֶׁהַכֹּל מִתְבַּשֵּׂם. וְאָז כָּל אוֹתָם הַדִּינִים נִמְצָאִים בְּאוֹר, וְהַדִּין לֹא נַעֲשֶׂה, וְעַל כֵּן תְּעַנּוּ אֶת נַפְשֹׁתֵיכֶם."],[2,"","אָמַר רַבִּי אַבָּא, הֲרֵי מוֹרֵנוּ בֵּאֵר אוֹתָהּ מִגּוּף הַמִּשְׁנָה - לֹא גָלוּ יִשְׂרָאֵל מֵאַרְצָם עַד שֶׁכָּפְרוּ בַּקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (שמואל ב כ) אֵין לָנוּ חֵלֶק בְּדָוִד וְלֹא נַחֲלָה (לנו) בְּבֶן יִשַׁי, וַהֲרֵי נֶאֱמַר. פָּסוּק אַחֵר מָצָאנוּ עַל זֶה, שֶׁכָּתוּב (מלכים א יא) רְאֵה בֵיתְךְ דָּוִד. אָמַר לוֹ, כָּךְ זֶה וַדַּאי, בֵּית דָּוִד נִקְרָא, כְּמוֹ שֶׁכָּתוּב (ישעיה ה) בֵּית יַעֲקֹב לְכוּ וְנֵלְכָה בְּאוֹר ה'. בֵּית יַעֲקֹב, כְּמוֹ שֶׁנֶּאֱמַר (שם ס) וּבֵית תִּפְאַרְתִּי אֲפָאֵר. לְכוּ וְנֵלְכָה בְּאוֹר ה', שֶׁכָּתוּב וְנָהָר יצֵא מֵעֵדֶן לְהַשְׁקוֹת אֶת הַגָּן, וְנָטַע אֶת הַגָּן הַזֶּה לְהִשְׁתַּעֲשֵׁעַ בּוֹ עִם הַצַּדִּיקִים, שֶׁבּוֹ הֵם שְׁרוּיִים."],[3,"","לָמַדְנוּ, כָּתוּב אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ הַשְּׁבִיעִי הַזֶּה יוֹם הַכִּפֻּרִים הוּא וְגוֹ' וְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם. וְכָתוּב וְהָיְתָה לָכֶם לְחֻקַּת עוֹלָם בַּחֹדֶשׁ הַשְּׁבִיעִי וְגוֹ'. מַה שֶּׁכָּתוּב אַךְ, מַה הוּא רוֹצֶה כָּאן? אָמַר לוֹ, זֶה בָּא לְמַעֵט, שֶׁכֵּיוָן שֶׁאָמַר וְעִנִּיתֶם אֶת נַפְשּתֵיכֶם בְּתִשְׁעָה לַחֹדֶשׁ, אָמַר (אחר כך) אַךְ בֶּעָשׂוֹר, וְהָיָה צָרִיךְ לִהְיוֹת אַךְ עָשׂוֹר! שֶׁבֶּעָשׂוֹר הַדָּבָר תָּלוּי."],[4,"","אָמַר לוֹ, אִם כָּךְ, (שמות יב) אַךְ בַּיּוֹם הָרִאשׁוֹן תַּשְׁבִּיתוּ שְּׂאֹר מִבָּתֵיכֶם, וְשָׁנִינוּ אַךְ - חִלֵּק, חֶצְיוֹ אָסוּר בַּאֲכִילַת חָמֵץ וְחֶצְיוֹ מֻתָּר. אַף כָּאן אַךְ בֶּעָשׂוֹר לַחֹדֶשׁ, אֱמֹר שֶׁחֶצְיוֹ אָסוּר בִּמְלָאכָה (באכילה) וְחֶצְיוֹ מֻתָּר. אָמַר לוֹ, אַף כָּאן בִּוְעִנִּיתֶם אֶת נַפְשֹׁתֵיכֶם זֶה תָּלוּי, שֶׁהֲרֵי עִנּוּי לֹא נִמְצָא אֶלָּא מֵחֲצוֹת הַיּוֹם וְאֵילָךְ, וְיָפֶה הוּא אַךְ חִלֵּק בִּוְעִנִּיתֶם אֶת נַפְשּתֵיכֶם."],[5,"","אָמַר רַבִּי אֶלְעָזָר, כָּתוּב כִּי בַיּוֹם הַזֶּה יְכַפֵּר עֲלֵיכֶם וְגוֹ'. אֲכַפֵּר עֲלֵיכֶם הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא יְכַפֵּר עֲלֵיכֶם - לְהַכְלִיל אֶת הַיּוֹבֵל שֶׁשּׁוֹפֵעַ מַעְיָנוֹת לְהַשְׁקוֹת בַּיּוֹם הַזֶּה לְכָל עֵבֶר לְרַוּוֹת אֶת הַכֹּל וּלְהַשְׁקוֹת אֶת הַכֹּל. וְזֶה עֲלֵיכֶם, כְּלוֹמַר עֲבוּרְכֶם, לְטַהֶרְכֶם בַּיּוֹם הַזֶּה, שֶׁכָּתוּב לִפְנֵי ה' תִּטְהָרוּ, וְלֹא יִשְׁלֹט עֲלֵיכֶם הַדִּין."],[6,"","רַבִּי יְהוּדָה אָמַר, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָּהֶם וְרוֹצֶה לְטַהֵר אוֹתָם שֶׁלֹּא יִמָּצֵא בָהֶם חֵטְא, כְּדֵי שֶׁיִּהְיוּ בְּנֵי הֵיכָלוֹ וְיָדוּרוּ בְהֵיכָלוֹ. וְלֶעָתִיד לָבא כָּתוּב, (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וְגוֹ'."],[7,"","רַבִּי יְהוּדָה פָּתַח, (תהלים קל) שִׁיר הַמַּעֲלוֹת מִמַּעֲמַקִּים קְרָאתִיךְ ה'. שָׁנִינוּ, בְּשָׁעָה שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, רָצָה לִבְרֹא אָדָם. נִמְלַךְ בַּתּוֹרָה. אָמְרָה לְפָנָיו: תִּרְצֶה לִבְרֹא הָאָדָם הַזֶּה?! עָתִיד הוּא לַחֲטֹא לְפָנֶיךְ וְעָתִיד הוּא לְהַרְגִּיז לְפָנֶיךְ. אִם תַּעֲשֶׂה לוֹ כְמַעֲשָׂיו, הֲרֵי הָעוֹלָם לֹא יוּכַל לַעֲמֹד לְפָנֶיךְ, כָּל שֶׁכֵּן אוֹתוֹ הָאִישׁ. אָמַר לָהּ: וְכִי לְחִנָּם נִקְרֵאתִי (שמות לד) אֵל רַחוּם וְחַנּוּן אֶרֶךְ אַפַּיִם?"],[8,"","וְטֶרֶם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, בָּרָא תְשׁוּבָה. אָמַר לָהּ לַתְּשׁוּבָה: אֲנִי רוֹצֶה לִבְרֹא אָדָם בָּעוֹלָם, עַל מְנָת שֶׁכְּשֶׁיָּשׁוּבוּ לָךְ מֵחֲטָאֵיהֶם, שֶׁתִּהְיִי עֲתִידָה לַעֲזֹּב אֶת חֲטָאֵיהֶם וּלְכַפֵּר עֲלֵיהֶם. וּבְכָל שָׁעָה וְשָׁעָה הַתְּשׁוּבָה זְמִינָה לָאֲנָשִׁים, וּכְשֶׁאֲנָשִׁים שָׁבִים מֵחֲטָאֵיהֶם, הַתְּשׁוּבָה הַזּוֹ שָׁבָה לַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא מְכַפֵּר עַל הַכֹּל, וְהַדִּינִים נִכְנָעִים, וְכֻלָּם מִתְבַּשְּׂמִים, וְאָדָם נִטְהָר מֵחֶטְאוֹ."],[9,"","מָתַי נִטְהָר אָדָם מֵחֶטְאוֹ? בְּשָׁעָה שֶׁנִּכְנָס לַתְּשׁוּבָה הַזּוֹ כָּרָאוּי. רַבִּי יִצְחָק אָמַר, שֶׁשָּׁב לִפְנֵי הַמֶּלֶךְ הָעֶלְיוֹן וּמִתְפַּלֵּל תְּפִלָּה מֵעֹמֶק הַלֵּב. זֶהוּ שֶׁכָּתוּב מִמַּעֲמַקִּים קְרָאתִיךְ ה'."]]],[["רִבִּי אַבָּא אָמַר, מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ', אֲתַר גָּנִיז הוּא לְעֵילָּא, וְהוּא עַמִיקָא (שמות ס\"ג ע\"ב) דְּבֵירָא, וּמֵהַאי נָפְקִין נַחֲלִין וּמַבּוּעִין לְכָל עִיבָר, וְהַהוּא עֲמִיקָא דַּעֲמִיקְתָא אִקְרֵי תְּשׁוּבָה. וּמַאן דְּבָעֵי לְאָתָבָא וּלְאִתְדַכְּאָה מֵחוֹבוֹי, בְּהַאי עוּמְקָא אִצְטְרִיךְ לְמִקְרֵי לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב מִמַּעֲמַקִּים קְרָאתִיךָ יְיָ'.","תָּאנָא, בְּשַׁעֲתָא דְּהֲוָה בַּר נָשׁ חָב קָמֵי מָארֵיהּ, וְקָרִיב קָרְבָּנֵיהּ עַל מַדְבְּחָא, וְכַהֲנָא מְכַפֵּר עָלֵיהּ, וּבָעֵי בָּעוּתֵיהּ עָלֵיהּ, מִתְעָרִין רַחֲמֵי, וְדִינִין מִתְבַּסְּמָן, וּתְשׁוּבָה אָרִיק בִּרְכָאן, בְּמַבּוּעִין דְּנַגְדִּין וְנָפְקִין, וּמִתְבָּרְכִין כֻּלְּהוּ בּוּצִינִין כַּחֲדָא, וּבַר נָשׁ אִתְדָּכֵי מֵחוֹבֵיהּ.","תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא, אַפִּיק עֶשֶׂר כִּתְרִין, עִטְרִין קַדִּישִׁין לְעֵילָּא, דְּאִתְעַטָּר בְּהוּ, וּמִתְלַבָּשׁ בְּהוּ, וְהוּא אִינּוּן, וְאִינּוּן הוּא, כְּשַׁלְהוֹבָא דַּאֲחִידָא בְּגוּמְרָא, וְלֵית תַּמָּן פִּרוּדָא. לָקֳבֵיל דְּנָא, אִית עֶשֶׂר כִּתְרִין דְּלָא קַדִּישִׁין לְתַתָּא, וְאִינּוּן אֲחִידָן בְּזוּהֲמָא דְּטוּפְרָא דְּחַד עִטְרָא קַדִּישָׁא, דְּאִקְרֵי חָכְמָה. וְעַל דָּא אִקְרוּן חָכְמוֹת.","וְתָאנָא, עֲשְׂרָה זִינֵי חָכְמוֹת אִלֵּין נַחְתּוּ לְעָלְמָא. וְכֻלְּהוּ אִסְתְּאָבוּ (ס\"א אשתאבו) בְּמִצְרַיִם, בַּר מֵחַד דְּאִתְפְּשַׁט בְּעָלְמָא, וְכֻלְּהוּ זִינֵי חַרְשֵׁי אִינּוּן, וּמִנַּיְיהוּ יַדְעֵי מִצְרַיִם חַרְשִׁין, עַל כָּל בְּנֵי עָלְמָא. וְכַד מִצְרָאֵי בָּעָאן לְמֶעְבַּד כְּנוּפְיָיא בְּחַרְשַׁיְיהוּ לְעוֹבָדֵיהוֹן, הֲווֹ נַפְקֵי לְחַקְלָא לְטוּרֵי רָמַאֵי, וְדַבְחִין דְּבָחִין, וְעַבְדִין גּוּמִּין בְּאַרְעָא, וְסַחֲרִין הַהוּא דָּמָא סוֹחֲרָנֵיהּ דְּהָנֵי גּוּמִּין, וּשְׁאָר דָּמָא מִתְכַּנְּפֵי בְּהַנְהוּ גּוּמִּין, וּבִשְׂרָא שָׁוִין עָלַיְיהוּ. וּקַרְבִין קָרְבְּנֵיהוֹן, לְאִינּוּן זִינִין בִּישִׁין, וְאִינּוּן זִינִין בִּישִׁין מִתְכַּנְּשִׁין וּמִתְקָרְבִין כַּחֲדָא, וּמִתְפַּיְּיסִין בַּהֲדַיְיהוּ בְּהַהוּא טוּרָא.","יִשְׂרָאֵל דַּהֲווֹ בְּשִׁעְבּוּדֵיהוֹן, הָווֹ מִתְקָרְבִין לְהוֹן, וְאוֹלְפוּ מִנַּיְיהוּ, וַהֲווּ טָעָאן בַּתְרַיְיהוּ, וְהַיְינוּ דִּכְתִּיב כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ וּכְמַעֲשֵׂה אֶרֶץ כְּנַעַן וְגוֹ', וּכְתִיב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים וְגוֹ'. תָּאנָא, בְּשַׁעֲתָא דַּהֲווֹ מְקָרְבִין לְהוֹן עַל גַּבֵּי חַקְלָא, וַהֲווּ מְזַמְּנֵי הַהוּא דָּמָא, וּמְקָרְבֵי קָרְבְּנַיְיהוּ, הֲווֹ מִתְכַּנְּפֵי כָּל אִינּוּן זִינִין בִּישִׁין, וְחָמָאן לְהוֹן כְּגַוְונָא דִשְׂעִירִים, כֻּלְּהוּ מַלְיָין שַׂעֲרָא, וּמוֹדָעֵי לְהוּ מַה דְּאִינּוּן בַּעְיָין.","תָּא חֲזֵי, יִצְחָק מַה כְּתִיב בֵּיהּ, (בראשית כ״ז:כ״ב) וַיִּגַּשׁ יַעֲקֹב אֶל יִצְחָק אָבִיו וַיְמֻשֵּׁהוּ, אָמַר, דָּא לָא אִתְעָדֵי (ס\"א הכא לא אתער), אֶלָּא מִטַּלָּא דִּשְׁמַיָּא דְּנָגִיד עַל אַרְעָא. אָמַר רִבִּי יוֹסֵי, וּמִשְׁמַנֵּי הָאָרֶץ, בְּכֹלָּא בְּרָכֵיהּ. מַאי טַעְמָא. בְּגִין דְּחָמָא לֵיהּ בְּשַׂעְרָא, אָמַר לְמֶעְבַּר דָּא, וּמִשְׁמַנֵּי הָאָרֶץ אִצְטְרִיךְ, וְלָא זוּהֲמָא דְּאַרְעָא, דְּהַאי זוּהֲמָא הוּא דְּאַרְעָא, וְכַד טַלָּא דִּשְׁמַיָּא וּמִגְדָּא דְּאַרְעָא מִתְחַבְּרָאן אִתְעַבָּר הַאי זוּהֲמָא.","אָמַר רִבִּי חִיָּיא, בַּתְרַיְיתָא דְּאִינּוּן כִּתְרִין תַּתָּאִין דְּלָא קַדִּישִׁין הַאי הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ח:י״א) וְדוֹרֵשׁ אֶל הַמֵּתִים, וְדָּא הוּא עֲשִׁירָאָה דְּכֹלָּא. דְּתַנְיָא אָמַר רִבִּי יִצְחָק אָמַר רִבִּי יְהוּדָה, נַפְשָׁתָא דְּרַשִׁיעַיָּיא אִלֵּין אִינּוּן מַזִּיקִין דְּעָלְמָא.","אָמַר רִבִּי יוֹסֵי, אִי הָכִי טַב לְהוּ לְחַיָּיבַיָּא דְּאִתְעַבְּדִין מַזִּיקִין בְּעָלְמָא, אָן הוּא עוֹנְשָׁא דְּגֵיהִנָּם. אָן הוּא בִּישָׁא דִּזְמִינָא לְהוּ בְּהַהוּא עָלְמָא. אָמַר רִבִּי חִיָּיא, הָכִי תָּנֵינָן, וְהָא אוֹקִימְנָא מִלֵּי, נַפְשָׁתָא דְּרַשִׁיעַיָּיא בְּשַׁעֲתָא דְּנָפְקִין מֵעָלְמָא, כַּמָה גַּרְדִּינֵי נִמוּסִין מִזְדַּמְּנֵי לְקַבְּלָא לְהוּ, וּלְאַעְלָאָה לְהוּ לְגֵּיהִנָם, וְעָאלִין לְהוּ בִּתְלַת דִּינִין בְּכָל יוֹמָא, בַּגֵיהִנָּם. לְבָתַר מִזְדַּוְּוגֵי בְּהוּ, וְאַזְלִין וְשָׁאטִין בְּעָלְמָא, וּמַטְעָן לְהוּ לְרַשִׁיעַיָּיא, לְאִינּוּן דְּקָא אַסְתִּים תְּשׁוּבָה מִקַּמַּיְיהוּ. לְבָתַר תַּיְיבִין לְהוּ לְגֵּיהִנָם, וְאִתְסָאבִין (נ\"א ואתדנון) תַּמָּן, וְכַךְ בְּכָל יוֹמָא.","לְבָתַר דְּאַזְלִין בְּהוּ, וְשָׁאטִין בְּהוּ בְּעָלְמָא, מְהַדְּרִין לְקִבְרַיְיהוּ, וְחַמָּן תּוֹלַעְתָּא דְּגוּפָא מְנַקְּרֵי בִּשְׂרָא וּמִתְאַבְּלָן עָלַיְיהוּ, וְאִינּוּן חַרְשִׁין הֲווֹ אַזְלֵי לְבֵי קִבְרֵי, וְחַרְשֵׁי בְּחַרְשַׁיְיהוּ, וְעַבְדִין חַד צַלְמָא דְּבַר נָשׁ, וְדַבְחִין קַמֵּיהּ חַד צְפִירָא. לְבָתַר עָאלִין לְהַהוּא צְפִירָא, בְּהַהוּא קִבְרָא, וְהַהוּא צַלְמָא מְתַּבְּרִין (ס\"א מדברין) לֵיהּ לְאַרְבַּע סִטְרִין, וּמַעֲלִין לֵיהּ לְאַרְבַּע זִיוְויָין דְּקִבְרָא. כְּדֵין מְחָרְשֵׁי בְּחַרְשַׁיְיהוּ, וּמִתְכַּנְּפֵי אִינּוּן כִּנּוּפֵי, וְאִינּוּן זִינִין בִּישִׁין, וּמַיְיתִין הַהִיא נַפְשָׁתָא, וְעָאל בְּקִבְרָא וּמִשְׁתָּעֵי בַּהֲדַיְיהוּ."],[[0,"ר׳ אבא אמר וכו׳:","רא״א, ממעמקים קראתיך ה׳, פירושו, מקום גנוז יש למעלה, והוא עומק הבאר דהיינו בינה, ומכאן יוצאים נחלים ומבועים לכל צד, ועמוק שבעמוק הזה, נקרא תשובה. ומי שרוצה לשוב ולהטהר מעונותיו, בעומק הזה צריך לקרוא להקב״ה. ז״ש ממעמקים קראתיך ה'."],[1,"תאנא בשעתא דהוה וכו׳:","למדנו, בשעה שאדם היה חוטא לפני אדונו, והקריב קרבנו על המזבח, והכהן מכפר עליו ומתפלל תפלתו עליו, מתעוררים הרחמים, והדינים מתבשמים, והתשובה, שהיא בינה, מריקה ברכות, במבועים הנמשכים ויוצאים, ומתברכים כל הנרות יחד, דהיינו הספירות דמלכות, והאדם נטהר מעונו."],[2,"ת״ח קב״ה אפיק וכו׳:","בוא וראה, הקב״ה, שה״ס א״ס, הוציא, עשר ספירות, עטרות קדושות למעלה, שהוא מתעטר בהן, ומתלבש בהן, והוא הן, והן הוא, כשלהבת הנאחזת בגחלת, ואין שם פרוד בין א״ס ב״ה לספירות המלבישות אותו. כנגד זה, יש עשר ספירות שאינן קדושות, שהן למטה, והן אחוזות בזוהם הצפרנים של ספירה קדושה אחת הנקראת חכמה, דהיינו המלכות שנקראת חכמה תתאה. והארות אחורים שלה נקראות צפרנים, ובפסולת שבהן, הנקראת זוהמת הצפרנים נאחזות הקליפות (כנ״ל אות פ״ב) ועל כן נקראות חכמות."],[3,"ותאנא עשרה זייני וכו׳:","ולמדנו עשרה מיני חכמות אלו, דקליפות, ירדו לעולם, וכולם ניתנו ונטמאו, במצרים, חוץ מאחד שנתפשט בעולם, דהיינו בכל העולם חוץ ממצרים. והם כל מיני כשפים, ומהם ידעו מצרים כשפים יותר מכל בני העולם. וכשהמצרים רצו לעשות אסיפת כשפים למעשיהם, היו יוצאים לשדה, להרים הרמים, וזובחים זבחים, ועושים חפירות בארץ, ומסבבים הדם מסביב אותם החפירות, ושאר הדם מתקבץ בתוך החפירות, ונותנים עליו הבשר. ומקריבים הקרבנות לאלו המינים הרעים, ואלו המינים הרעים מתאספים ומתקרבים יחד. ומתרצים עמהם בהר ההוא."],[4,"ישראל דהוו בשעבודיהון וכו׳:","ישראל שהיו תחת שעבודם של המצרים, היו מתקרבים להם ולומדים מהם והיו טועים אחריהם וז״ש, כמעשה ארץ מצרים אשר ישבתם בה לא תעשו וכמעשה ארץ כנען וגו'. וכתוב, ולא יזבחו עוד את זבחיהם לשעירים וגו'. למדנו, בשעה שהיו מקריבים להם על פני השדה, והיו מכינים את הדם ומקריבים קרבנותיהם, היו מתאספים כל אלו המינים הרעים, והיו רואים אותם כמו שעירים, שכולם היו מלאים שערות, ומודיעים אותם מה שרוצים."],[5,"ת״ח יצחק מה וכו׳:","בוא וראה, יצחק, מה כתוב בו. ויגש יעקב אל יצחק אביו וימשהו. אמר, זה אינו חסר אלא \u0003מטל השמים\u0004 הנוזל על הארץ. כלומר, שאינו חסר אלא משפע ז״א בלבד שנקרא שמים, שהוא אור החסדים. להיותו מרכבה לז״א, אבל אינו צריך להארת החכמה, ובכל ברכו, בין בחסדים ובין בחכמה, ר׳ יוסי, גם \u0003ומשמני הארץ\u0004 כתוב, דהיינו הארת החכמה, ובכל ברכו, בין בחסדים ובין בחכמה, מהו הטעם שברכו בהארת החכמה, משום שראה אותו בשערות, דהיינו דינים, אמר, כדי להעביר ממנו זה, אל \u0003משמני הארץ\u0004 הוא צריך, שהוא הארת החכמה. אבל לא זוהמא של הארץ, כמו הסטרא אחרא שיונקת מזוהמא של הצפרנים (כנ\"ל אות רמ״ח) כי זוהמא זו היא מן הארץ, שהיא המלכות, וכשטל השמים ומגד הארץ, שהם ז״א ומלכות, מתחברים, נעברת הזוהמא ההיא."],[6,"אמר ר׳ חייא וכו׳:","אר״ח האחרונה של אלה ספירות תחתונות שאינן קדושות, היא זה שכתוב, ודורש אל המתים. וזו היא העשירית של כל הספירות, דהיינו המלכות של הס״א. כי עשרה מיני כשוף יש בכתוב, שהם כנגד עשר ספירות דס״א (כנ\"ל וישלח אות ל״ה) שלמדנו, א״ר יצחק א״ר יהודה, נפשות הרשעים שמתו, אלו הן מזיקי העולם. שעליהן סובב הכתוב, ודורש אל המתים."],[7,"אמר ר׳ יוסי וכו׳:","אר״י, אם כן, טוב להם לרשעים, שהם נעשים מזיקים בעולם. איפה הוא העונש של גיהנם, איפה היא הרעה, המוכנה להם בעולם ההוא. אמר ר׳ חייא, כך למדנו והעמדנו הדברים, נפשות הרשעים, בשעה שיוצאות מן העולם, כמה חוקרי דין מזומנים לקבלן ולהביאן בגיהנם, ומכניסים אותן בג׳ דינים בכל יום בגיהנם. אח״כ מתחברים בהן מלאכי החבלה, והולכות ומשוטטות בעולם, ומטעות את הרשעים, לאותם שכבר נסתמה מהם התשובה. ואח״כ מחזירים אותן לגיהנם ונדונים שם. וכך בכל יום."],[8,"לבתר דאזלין בהו וכו׳:","לאחר שמלאכי חבלה, הלכו עמהן ושוטטו עמהן בעולם הם מחזירים אותן לקברן, ורואות תולעת הגוף מנקרת הבשר שלהן, והנפשות מתאבלות עליהם. על הגופות. ואלו המכשפים, הם הולכים לבית הקברות ומכשפים בכשפיהם, ועושים צלם אחד של אדם, וזובחים לפניו שעיר אחד. לאחר כך מביאים את השעיר בקבר ההוא, ואותו הצלם משברים לד׳ צדדים, ומעלים אותו לארבע זויות הקבר. אז מכשפים בכשפיהם. ומתקבצות אלו הקבוצות, ואלו המינים הרעים, ומביאים הנפש ההיא, ונכנסת בקבר, ומספרת עמהם."]],[[0,"","רַבִּי אַבָּא אָמַר, מִמַּעֲמַקִּים קְרָאתִיךְ ה', מָקוֹם גָּנוּז הוּא לְמַעְלָה, וְהוּא עֹמֶק הַבְּאֵר, וּמִזֶּה יוֹצְאִים נְחָלִים וּמַעְיָנוֹת לְכָל עֵבֶר, וְאוֹתוֹ עֹמֶק הָעֳמָקִים נִקְרָא תְשׁוּבָה. וּמִי שֶׁרוֹצֶה לָשׁוּב וּלְהִטָּהֵר מֵחֲטָאָיו, מֵהָעֹמֶק הַזֶּה הוּא צָרִיךְ לִקְרֹא לַקָּדוֹשׁ בָּרוּךְ הוּא. זֶהוּ שֶׁכָּתוּב מִמַּעֲמַקִּים קְרָאתִיךְ ה'."],[1,"","לָמַדְנוּ, בְּשָׁעָה שֶׁהָיָה אָדָם חוֹטֵא לִפְנֵי רִבּוֹנוֹ וּמַקְרִיב קָרְבָּנוֹ עַל הַמִּזְבֵּחַ, וְהַכֹּהֵן מְכַפֵּר עָלָיו וּמְבַקֵּשׁ בַּקָּשָׁתוֹ עָלָיו, מִתְעוֹרְרִים רַחֲמִים, וְהַדִּינִים מִתְבַּשְּׂמִים, וְהַתְּשׁוּבָה מְרִיקָה בְרָכוֹת בְּמַעְיָנוֹת שֶׁשּׁוֹפְעִים וְיוֹצְאִים, וְכָל הַמְּאוֹרוֹת מִתְבָּרְכִים כְּאֶחָד, וְהָאָדָם נִטְהָר מֵחֶטְאוֹ."],[2,"","בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא עֲשָׂרָה כְתָרִים, עֲטָרוֹת קְדוֹשׁוֹת לְמַעְלָה, שֶׁהִתְעַטֵּר בָּהֶם וּמִתְלַבֵּשׁ בָּהֶם, וְהוּא זֶה הֵם, וְהֵם זֶה הוּא, כְּשַׁלְהֶבֶת הָאֲחוּזָה בְּגַחֶלֶת, וְאֵין שָׁם פֵּרוּד. כְּנֶגֶד זֶה יֵשׁ עֲשָׂרָה כְתָרִים שֶׁאֵינָם קְדוֹשִׁים לְמַטָּה, וְהֵם אֲחוּזִים בְּזֻהֲמַת הַצִּפֹּרֶן שֶׁל עֲטָרָה קְדוֹשָׁה שֶׁנִּקְרֵאת חָכְמָה, וְעַל כֵּן נִקְרְאוּ חָכְמוֹת."],[3,"","וְלָמַדְנוּ, עֲשֶׂרֶת מִינֵי הַחָכְמוֹת הַלָּלוּ יָרְדוּ לָעוֹלָם, וְכֻלָּם נִטְמְאוּ (נשאבו) בְמִצְרַיִם, פְּרָט לְאֶחָד שֶׁהִתְפַּשֵּׁט בָּעוֹלָם, וְכֻלָּם הֵם מִינֵי כְשָׁפִים, וּמֵהֶם יָדְעוּ הַמִּצְרִים כְּשָׁפִים עַל כָּל בְּנֵי הָעוֹלָם. וּכְשֶׁהַמִּצְרִים רָצוּ לַעֲשׂוֹת כִּנּוּס בְּכִשְׁפֵיהֶם לְמַעֲשֵׂיהֶם, הָיוּ יוֹצְאִים לַשָּׂדֶה לֶהָרִים הַגְּבוֹהִים, וְזוֹבְחִים זְבָחִים, וְעוֹשִׂים גֻּמּוֹת בָּאָרֶץ, וּמְסוֹבְבִים אוֹתוֹ הַדָּם סְבִיב הַגֻּמּוֹת הַלָּלוּ, וּשְׁאָר הַדָּם מְכַנְּסִים בַּגֻּמּוֹת הַלָּלוּ, וְשָׂמִים עֲלֵיהֶם בָּשָׂר, וּמַקְרִיבִים אֶת קָרְבְּנוֹתֵיהֶם לְאוֹתָם הַמִּינִים הָרָעִים, וְאוֹתָם הַמִּינִים הָרָעִים מִתְכַּנְּסִים וּמִתְקָרְבִים כְּאֶחָד, וּמִתְפַּיְּסִים עִמָּם בְּאוֹתוֹ הָהָר."],[4,"","יִשְׂרָאֵל שֶׁהָיוּ מְשֻׁעְבָּדִים לָהֶם, הָיוּ מִתְקָרְבִים לָהֶם, וְלָמְדוּ מֵהֶם, וְהָיוּ טוֹעִים אַחֲרֵיהֶם. וְהַיְנוּ מַה שֶּׁכָּתוּב, כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ וּכְמַעֲשֵׂה אֶרֶץ כְּנַעַן וְגוֹ'. וְכָתוּב וְלֹא יִזְבְּחוּ עוֹד אֶת זִבְחֵיהֶם לַשְּׂעִירִים וְגוֹ'. לָמַדְנוּ, בְּשָׁעָה שֶׁהָיוּ מַקְרִיבִים לָהֶם עַל גַּבֵּי הַשָּׂדֶה וְהָיוּ מְזַמְּנִים אוֹתוֹ הַדָּם וּמַקְרִיבִים קָרְבְּנוֹתֵיהֶם, הָיוּ מִתְכַּנְּסִים כָּל אוֹתָם מִינִים רָעִים, וְרוֹאִים אוֹתָם כְּמוֹ הַשְּׂעִירִים, כֻּלָּם מְלֵאִים בְּשֵׂעָר, וּמוֹדִיעִים לָהֶם מַה שֶּׁהֵם רוֹצִים."],[5,"","בֹּא רְאֵה, מַה כָּתוּב בְּיִצְחָק? (בראשית כז) וַיִּגַּשׁ יַעֲקֹב אֶל יִצְחָק אָבִיו וַיְמֻשֵּׁהוּ. אָמַר, זֶה לֹא חָסֵר (כאן לא מתעורר), אֶלָּא מִטַּל הַשָּׁמַיִם שֶׁנּוֹזֵל עַל הָאָרֶץ. אָמַר רַבִּי יוֹסֵי, וּמִשְׁמַנֵּי הָאָרֶץ, בַּכֹּל הוּא בֵּרַךְ אוֹתוֹ. מָה הַטַּעַם? כִּי רָאָה אוֹתוֹ עִם שֵׂעָר. אָמַר, שֶׁכְּדֵי לְהַעֲבִיר אֶת זֶה, צָרִיךְ וּמִשְׁמַנֵּי הָאָרֶץ, וְלֹא זֻהֲמַת הָאָרֶץ, שֶׁהֲרֵי זֻהֲמָה הִיא שֶׁל הָאָרֶץ, וּכְשֶׁטַּל הַשָּׁמַיִם וּמֶגֶד הָאָרֶץ מִתְחַבְּרִים, עוֹבֶרֶת הַזֻּהֲמָה הַזּוֹ."],[6,"","אָמַר רַבִּי חִיָּיא, הָאַחֲרוֹן שֶׁל אוֹתָם הַכְּתָרִים הַתַּחְתּוֹנִים שֶׁאֵינָם קְדוֹשִׁים, זֶהוּ הוּא מַה שֶּׁכָּתוּב (דברים י) וְדוֹרֵשׁ אֶל הַמֵּתִים, וְזֶהוּ הָעֲשִׂירִי שֶׁל הַכֹּל. שֶׁלָּמַדְנוּ, אָמַר רַבִּי יִצְחָק אָמַר רַבִּי יְהוּדָה, נַפְשׁוֹת הָרְשָׁעִים אֵלּוּ הֵם מַזִּיקֵי הָעוֹלָם."],[7,"","אָמַר רַבִּי יוֹסֵי, אִם כָּךְ טוֹב לָרְשָׁעִים שֶׁנַּעֲשִׂים מַזִּיקִים בָּעוֹלָם, אֵיפֹה הוּא עֹנֶשׁ הַגֵּיהִנֹּם? אֵיפֹה הָרָע שֶׁעָתִיד לָהֶם בָּעוֹלָם הַהוּא? אָמַר רַבִּי חִיָּיא, כָּךְ שָׁנִינוּ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים. נַפְשׁוֹת הָרְשָׁעִים בְּשָׁעָה שֶׁיּוֹצְאִים מִן הָעוֹלָם, כַּמָּה שׁוֹמְרֵי הֲחֻקִּים מִזְדַּמְּנִים כְּנֶגְדָּם וּלְהַכְנִיסָם בַּגֵּיהִנֹּם, וּמַכְנִיסִים אוֹתָם בִּשְׁלֹשָׁה דִינִים בְּכָל יוֹם בַּגֵּיהִנֹּם. אַחַר כָּךְ מִזְדַּוְּגִים עִמָּם, וְהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם, וּמַטְעִים אֶת הָרְשָׁעִים לְאוֹתָם שֶׁנִּסְתְּמָה מִלִּפְנֵיהֶם הַתְּשׁוּבָה. אַחַר כָּךְ מְשִׁיבִים אוֹתָם לַגֵּיהִנֹּם, וְנִטְמָאִים (ונדונים) שָׁם, וְכָךְ בְּכָל יוֹם."],[8,"","אַחַר שֶׁהוֹלְכִים עִמָּם וּמְשׁוֹטְטִים עִמָּם בָּעוֹלָם, מַחֲזִירִים לְקִבְרֵיהֶם, וְרוֹאִים אֶת הַתּוֹלַעַת שֶׁל הַגּוּף מְנַקֶּרֶת אֶת הַבָּשָׂר וּמִתְאַבְּלִים עֲלֵיהֶם, וְאוֹתָם מְכַשְּׁפִים הָיוּ הוֹלְכִים לְבֵית הַקְּבָרוֹת וּמְכַשְּׁפִים בְּכִשְׁפֵיהֶם, וְעוֹשִׂים צֶלֶם אֶחָד שֶׁל הָאָדָם, וְזוֹבְחִים לְפָנָיו שָׂעִיר אֶחָד. אַחַר כָּךְ מַכְנִיסִים אוֹתוֹ הַשָּׂעִיר לְאוֹתוֹ קֶבֶר, וְאֶת אוֹתוֹ צֶלֶם מְשַׁבְּרִים (מנהיגים) אוֹתוֹ לְאַרְבָּעָה צְדָדִים, וּמַכְנִיסִים אוֹתוֹ לְאַרְבַּע זָוִיּוֹת הַקֶּבֶר, וְאָז מְכַשְּׁפִים בְּכִשְׁפֵיהֶם, וּמְכַנְּסִים אוֹתָם כִּנּוּסִים וְאוֹתָם מִינִים רָעִים, וּמְבִיאִים אוֹתָהּ הַנֶּפֶשׁ, וּמַכְנִיסִים לַקֶּבֶר וּמְדַבְּרִים עִמָּם."]]],[["אָמַר רִבִּי יִצְחָק, זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, דְּהָא כֻּלְּהוּ קַדִּישִׁין. גּוּפָא דִּלְהוֹן קַדִּישָׁא. נַפְשָׁא דִּלְהוֹן קַדִּישָׁא. רוּחָא דִּלְהוֹן קַדִּישָׁא. נִשְׁמְתָא דִּלְהוֹן קֹדֶשׁ קֳדָשִׁים. תְּלַת דַּרְגִּין אִינּוּן, כְּגַוְונָא דִּלְעֵילָּא. דְּתַנְיָא אָמַר רִבִּי יְהוּדָה, כְּתִיב (בראשית א׳:כ״ד) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, דָּא הִיא נִשְׁמְתָא (עלאה) דְּאָדָם קַדְמָאָה (עלאה). תָּא חֲזֵי, תְּלַת דַּרְגִּין אִינּוּן, וְאִתְדְּבָקוּ כְּחַד, נֶפֶשׁ, רוּחַ, נְשָׁמָה. וְעִלָּאָה מִנַּיְיהוּ, נְשָׁמָה.","דְּאָמַר רִבִּי יוֹסֵי, בְּכֻלְּהוּ בְּנֵי נָשָׁא אִית נֶפֶשׁ, וְאִית נֶפֶשׁ עִלָּאָה מִנֶּפֶשׁ. זָכָה בַּר נָשׁ בְּהַאי נֶפֶשׁ, מְרִיקִין עָלֵיהּ עִטְרָא חַד, דְּאִקְרֵי רוּחַ. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ב:ט״ו) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. כְּדֵין אִתְּעַר בַּר נָשׁ בְּאִתְעָרוּתָא אָחֳרָא עִלָּאָה, לְאִסְתַּכְּלָא בְּנִמוּסֵי מַלְכָּא קַדִּישָׁא. זָכָה בַּר נָשׁ בֵּיהּ בְּהַהוּא רוּחָא, מְעַטְּרִין לֵיהּ בְּכִתְרָא קַדִּישָׁא עִלָּאָה, דְּכָלִיל כֹּלָּא, דְּאִקְרֵי נְשָׁמָה. דְּאִתְקְרֵי נִשְׁמַת אֱלוֹהַּ.","וְתָאנָא בְּרָזָא דְּרָזִין, בְּגוֹ רָזִין דְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא. הַאי קְרָא, דִּכְתִּיב, (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, כֵּיוָן דִּכְתִּיב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, אֲמַאי שְׁכְּבָר מֵתוּ. אֶלָּא שְׁכְּבָר מֵתוּ בְּהַאי עָלְמָא, בְּפוּלְחָנָא דְּמָארֵיהוֹן. (בראשית רכ\"ד ע\"ב)","וְתַמָּן כְּתִיב, תְּלָת מָדוֹרִין עֲבַד קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָּיא, חַד (ס\"א דזכו אינון צדיקייא דלא אישתציאו מהאי עלמא וכד אצטריך) לְנַפְשָׁאן דְּאִינּוּן צַדִּיקַיָּיא, דְּלָא אִסְתְּלָקוּ מֵהַאי עָלְמָא, וּשְׁכִיחִין בְּהַאי עָלְמָא. וְכַד אִצְטְרִיךְ עָלְמָא רַחֲמִין, וְאִינּוּן חַיִּין יַתְבִין בְּצַעֲרָא, אִינּוּן מְצָלוּ צְלוֹתָא עָלַיְיהוּ, וְאַזְלִין וּמוֹדְעִין מִלָּה לְאִינּוּן דְּמִיכִין דְּחֶבְרוֹן, וּמִתְעָרִין, וְעַאלִין לְגַּן עֵדֶן דְּאַרְעָא, דְּתַמָּן רוּחֵיהוֹן דְּצַדִּיקַיָּיא, מִתְלַבְּשָׁן בְּעִטְרִין דִּנְהוֹרָא, וְאִתְיַיעֲטוּ בְּהוּ, וְגַזְרִין גְּזֵרָה, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד רְעוּתָא דִּלְהוֹן, וְחָס עַל עָלְמָא.","וְאִינּוּן נַפְשָׁן דְּצַדִּיקַיָּיא, מִשְׁתַּכְּחִין בְּהַאי עָלְמָא, לְאַגָּנָא עַל חַיַּיָא, וְהַאי אִקְרֵי נֶפֶשׁ, וְדָא לָא אִסְתָּלְקָא (ס\"א אשתצי) מֵהַאי עָלְמָא, וּשְׁכִיחָא בְּהַאי עָלְמָא, לְאִסְתַּכְּלָא וּלְמִנְדַּע וּלְאַגָּנָא עַל דָּרָא. וְהַאי הוּא דְּאָמְרוּ חַבְרַיָּיא, דְּמֵתֵי יַדְעֵי בְּצַעֲרָא דְּעָלְמָא. וְעוֹנְשָׁא דְּחַיָּיבִין דִּי בְּאַרְעָא, בְּהַאי הוּא, דִּכְתִּיב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ.","וּמָדוֹרָא תִּנְיָינָא הוּא גַּן עֵדֶן דִּי בְּאַרְעָא. בֵּיהּ עָבֵד קוּדְשָׁא בְּרִיךְ הוּא מָדוֹרִין עִלָּאִין יַקִּירִין, כְּגַוְונָא דְּהַאי עָלְמָא, וּכְגַוְונָא דְּעָלְמָא עִלָּאָה. וְהֵיכָלִין בִּתְרֵין גַּוְונִין, דְּלֵית לְהוֹן חוּשְׁבָּנָא, וְאִילָנִין וַעֲשָׂבִין וְרֵיחִין דְּסַלְּקִין בְּכָל יוֹמָא. וּבְהַאי אֲתַר שָׁארֵי הַהוּא דְּאִקְרֵי רוּחַ דְּאִינּוּן צַדִּיקַיָּיא, וּמָדוֹרָא דְּהַהוּא רוּחָא בֵּיהּ שָׁארֵי. וְכָל רוּחַ וְרוּחַ מִתְלַבְּשָׁא בִּלְבוּשׁ יַקִּירָא, כְּגַוְונָא דְּהַאי עָלְמָא, וּכְגַוְונָא דְּהַהוּא עָלְמָא עִלָּאָה.","מָדוֹרָא תְּלִיתָאָה, הַהוּא מָדוֹרָא עִלָּאָה קַדִּישָׁא דְּאִיתְקְרֵי צְרוֹרָא דְּחַיֵּי. דְּתַמָּן מִתְעַדְּנָא הַהוּא דַּרְגָּא עִלָּאָה קַדִּישָׁא, דְּאִקְרֵי נְשָׁמָה. וְהַאי אִתְדְּבַק לְאִתְעַנְּגָא בְּעִדּוּנָא עִלָּאָה. עָלֵיהּ כְּתִיב, (ישעיהו נ״ח:י״ד) אָז תִּתְעַנַּג עַל יְיָ' וְהִרְכַּבְתִּיךָ וְגוֹ'.","וְתָאנָא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא רַחֲמֵי, וְאִינּוּן צַדִּיקַיָּיא זַכָּאִין. הַהוּא נֶפֶשׁ דְּאִשְׁתַּכְּחָא בְּעָלְמָא, לְאַגָּנָא עַל עָלְמָא. נֶפֶשׁ סָלִיק וְאָזִיל וְשָׁאט בְּעָלְמָא, וּמוֹדַע לְרוּחַ. וְרוּחַ סָלִיק וְאִתְעַטָּר, וּמוֹדַע לַנְשָׁמָה. וּנְשָׁמָה לְּקוּדְשָׁא בְּרִיךְ הוּא. וּכְדֵין חָס קוּדְשָׁא בְּרִיךְ הוּא עַל עָלְמָא. כְּדֵין נַחְתָּא מֵעֵילָּא לְתַתָּא, נְשָׁמָה אוֹדַע לְרוּחַ, וְרוּחַ אוֹדַע לְנַפְשָׁא.","וּבְכָל שַׁבְּתָא וְשַׁבְּתָא, וְרֵישׁ יַרְחָא, כֻּלְּהוּ, מִתְחַבְּרָן וּמִתְעַטְּרָן כְּחַד, עַד דְּאִזְדְּוָּוגוּ לְמֵיתֵי לְסַגְּדָא לְמַלְכָּא עִלָּאָה. וּלְבָתַר תַּיְיבִין לְאַתְרַיְיהוּ. הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ יָבֹא כָל בָּשָׂר וְגוֹ'.","וּבְשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא רַחֲמֵי, וְחַיַיָא אַזְלֵי וּמוֹדָעֵי לְהוּ לְנַפְשַׁיְיהוּ דְּצַדִּיקַיָּיא, וּבָכָאן עַל קִבְרַיְיהוּ, אִינּוּן דְּאִתְחָזוֹ לְאוֹדָעָא לְהוּ. מַאי טַעְמָא. דְּשַׁוְיָין רְעוּתָא דִּלְהוֹן לְאִתְדַּבְּקָא נַפְשָׁא בְּנַפְשָׁא, כְּדֵין אִתְּעָרִין נַפְשַׁיְיהוּ דְּצַדִּיקַיָּיא, וּמִתְכַּנְּפֵי וְאַזְלִין וְשָׁאטִין לִדְמִיכֵי חֶבְרוֹן, וּמוֹדִיעֵי לְהוּ צַעֲרָא דְּעָלְמָא. וְכֻלְּהוּ עָאלִין בְּהַהוּא פִּתְחָא דְגַּן עֵדֶן, וּמוֹדִיעֵי לְרוּחַ. וְאִינּוּן רוּחִין דְּמִתְעַטְּרָן בְּגַּן עֵדֶן, מַלְאֲכֵי עִלָּאִין אַזְלֵי בֵּינַיְיהוּ. וְכֻלְּהוּ מוֹדִיעִין לַנְשָׁמָה. וּנְשָׁמָה אוֹדָעַת לְּקוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ בָּעָאן רַחֲמֵי עַל חַיִּין, וְחָס קוּדְשָׁא בְּרִיךְ הוּא עַל עָלְמָא בְּגִינֵיהוֹן. וְעַל דָּא אָמַר שְׁלֹמֹה, וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'."],[[0,"אמר ר׳ יצחק וכו׳:","אר״י, אשריהם הצדיקים בעולם הזה ובעולם הבא, אשר כולם קדושים, הגוף שלהם קדוש, הנפש שלהם קדושה הרוח שלהם קדוש, הנשמה שלהם קדש קדשים. ג׳ מדרגות הן, נפש רוח ונשמה, כעין של מעלה, דהיינו כנגד מלכות, ת״ת, ובינה של מעלה. שלמדנו א״ר יהודה, כתוב, תוצא הארץ נפש חיה, זו היא הנשמה של אדם הראשון. בוא וראה, ג׳ מדרגות הן ומתדבקות יחד, נפש, רוח, ונשמה. והעליונה מהם היא נשמה."],[1,"דא״ר יוסי בכלהו וכו׳:","שאמר ר׳ יוסי, בכל אדם יש נפש. דהיינו נפש בהמית. ויש נפש עליונה מנפש, דהיינו \u0003נפש\u0004 הרוחנית, זכה אדם בנפש ההיא, מריקים עליו עטרה אחת שנקראת \u0003רוח.\u0004 ז״ש עד יערה עלינו רוח ממרום. אז מתעורר האדם בהתעורתת אחרת עליונה, להסתכל בדרכי המלך הקדוש. זכה אדם ברוח ההוא, מעטרים אותו בספירה קדושה עליונה הכוללת הכל, שנקראת \u0003נשמה.\u0004 שנקראת נשמת אלוה."],[2,"ותאנא ברזא דרזין וכו׳:","ולמדנו, בסודי סודות, בסוד שבספרו של שלמה המלך, מקרא זה שכתוב, ושבח אני את המתים שכבר מתו. כיון שכתוב ושבח אני את המתים, למה אומר עוד, שכבר מתו. ומשיב. אלא הפירוש הוא, שכבר מתו בעולם הזה, בעבודת אדונם. כלומר, שהמיתו את עצמם בעבודת רבונם. שאין התורה מתקיימת אלא במי שממית עצמו עליה."],[3,"ותמן כתיב ג׳ וכו׳:","ושם, בספרו של שלמה המלך, כתוב, ג׳ מדורים עשה הקב\"ה לצדיקים, לנר״ן שלהם אחר פטירתם. אחד, לנפשות הצדיקים, שלא הסתלקו מעולם הזה, ונמצאות בעולם הזה. כי נפש הנפטר אינה מסתלקת מעוה״ז, וכשהעולם צריך רחמים, ואלו בני האדם החיים יושבים בצער, הן מתפללות תפלה עליהם, והולכות ומודיעות הדבר לישני חברון, דהיינו האבות, והן מתעוררות ועולות לגן עדן הארץ, ששם רוחות הצדיקים מתלבשים בעטרות של אור, ומתיעצות בהם, וגוזרות גזרה, והקב״ה עושה רצונן, ומרחם על העולם."],[4,"ואינון נפשן דצדיקייא וכו׳:","ואלו נפשות הצדיקים נמצאות בעולם הזה, להגן על בני האדם החיים. וזו נקראת נפש. וזו אינה מסתלקת מעולם הזה, ונמצאת בעולם הזה להסתכל ולדעת ולהגן על הדור, וזהו שאמרו החברים, שהמתים יודעים בצער העולם ועונשם של הרשעים בארץ הוא בנפש הזאת, שכתוב, ונכרתה הנפש ההיא מעמיה."],[5,"ומדורא תניינא הוא וכו׳:","מדור השני הוא, גן עדן שבארץ, בו עשה הקב״ה מדורים עליונים יקרים, שהם כעין עולם הזה וכעין עולם העליון. כלומר, שכלולים מבחינת מלכות ומבחינת בינה. כי גן, ה״ס מלכות, ועדן ה״ס בינה. וההיכלות הם ג״כ בב' אפנים, כמו המדורים, שאין להם חשבון, ואילנות ועשבים וריחות עולים בכל יום. ובמקום ההוא שורה, אותו הנקרא רוח של אלו הצדיקים, והוא המדור שרוח ההוא שורה בו. וכל רוח ורוח, מתלבש בלבוש יקר כעין עולם הזה וכעין עולם העליון."],[6,"מדורא תליתאה וכו׳:","מדור השלישי, הוא מדור העליון הקדוש הנקרא צרור החיים, שהוא גן עדן העליון, ששם מתעדנת אותה המדרגה עליונה הקדושה שנקראת נשמה, שזו מתדבקת להתענג בעדן העליון, עליה כתוב, אז תתענג על ה׳ והרכבתיך על במתי ארץ. שג״ע העליון נקרא במתי ארץ."],[7,"ותאנא בשעתא וכו׳:","ולמדנו, בשעה שהעולם צריך לרחמים, ואז אלו הצדיקים הזכאים, נפש ההיא שלהם שנמצאת בעולם להגן על העולם, עולה והולכת ומשוטטת בעולם ומודיעה לרוח, והרוח עולה ומתעטר ומודיע לנשמה, והנשמה להקב״ה, ואז מרחם הקב״ה על העולם. ואז יורד ממעלה למטה, הנשמה מודיעה לרוח, והרוח מודיע לנפש."],[8,"ובכל שבתא ושבתא וכו׳:","ובכל שבת ושבת, וראש חדש, כולם הנפש והרוח והנשמה, מתחברים ומתעטרים יחד, עד שמתחברים לבא להשתחות למלך העליון, ואח״כ חוזרים למקומם. ז״ש, והיה מדי חדש בחדשו ומדי שבת בשבתו יבא כל בשר וגו'."],[9,"ובשעתא דאצטרך וכו׳:","ובשעה שהעולם צריך רחמים, והחיים הולכים ומודיעים לנפשות הצדיקים, ובוכים על קבריהם, והם ראוים להודיע להם, מה הטעם שראוים, הוא משום ששמים הרצון שלהם להתדבק נפש בנפש, אז מתעוררות נפשות הצדיקים ומתאספות והולכות ומשושטות לישני חברון, ומודיעות להם צער העולם. וכולן עולות לפתח גן העדן ומודיעות לרוח, ואלו הרוחות המתעטרים בגן עדן, מלאכים עליונים הולכים ביניהם, וכולם מודיעים לנשמה, והנשמה מודיעה להקב״ה. וכולם מבקשים רחמים על החיים. והקב״ה מרחם בשבילם על העולם. ועל זה אמר שלמה, ושבח אני את המתים שכבר מתו."]],[[0,"","אָמַר רַבִּי יִצְחָק, אַשְׁרֵי הַצַּדִּיקִים בָּעולָם הַזֶּה וּבָעולָם הַבָּא, שֶׁהֲרֵי כֻּלָּם קְדוֹשִׁים. גּוּפָם קָדוֹשׁ. נַפְשָׁם קְדוֹשָׁה. רוּחָם קְדוֹשָׁה. נִשְׁמָתָם קֹדֶשׁ קָדָשִׁים. שָׁלֹשׁ דְּרָגוֹת הֵן כְּמוֹ שֶׁלְּמַעְלָה. שֶׁשָּׁנִינוּ, אָמַר רַבִּי יְהוּדָה, כָּתוּב (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה, זוֹהִי נְשָׁמָה (עליונה) שֶׁל אָדָם הָרִאשׁוֹן (עליון). בֹּא רְאֵה, שָׁלֹשׁ דְּרָגוֹת הֵן, וְנִדְבְּקוּ כְאַחַת - נֶפֶשׁ, רוּחַ, נְשָׁמָה. וְהָעֶלְיוֹנָה מֵהֶן - נְשָׁמָה."],[1,"","שֶׁאָמַר רַבִּי יוֹסֵי, בְּכָל הָאֲנָשִׁים יֵשׁ נֶפֶשׁ, וְיֵשׁ נֶפֶשׁ עֶלְיוֹנָה מֵהַנֶּפֶשׁ. זָכָה אָדָם בַּנֶּפֶשׁ הַזּוֹ - מְרִיקִים עָלָיו עֲטָרָה אַחַת שֶׁנִּקְרֵאת רוּחַ. זֶהוּ שֶׁכָּתוּב (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. אָז מִתְעוֹרֵר אָדָם בְּהִתְעוֹרְרוּת אַחֶרֶת עֶלְיוֹנָה, לְהִסְתַּכֵּל בְּנִימוּסֵי הַמֶּלֶךְ הַקָּדוֹשׁ. זָכָה אָדָם בְּאוֹתָהּ הָרוּחַ - מְעַטְּרִים אוֹתוֹ בְּכֶתֶר קָדוֹשׁ עֶלְיוֹן שֶׁכּוֹלֵל הַכֹּל, שֶׁנִּקְרָא נְשָׁמָה, שֶׁנִּקְרֵאת נִשְׁמַת אֱלוֹהַּ."],[2,"","וְלָמַדְנוּ בְּסוֹד הַסּוֹדוֹת, בְּתוֹךְ הַסּוֹדוֹת שֶׁל סִפְרוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ, הַפָּסוּק הַזֶּה שֶׁכָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, כֵּיוָן שֶׁכָּתוּב וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים, לָמָּה שֶׁכְּבָר מֵתוּ? אֶלָּא שֶׁכְּבָר מֵתוּ בָּעוֹלָם הַזֶּה בַּעֲבוֹדַת רִבּוֹנָם."],[3,"","וְשָׁם כָּתוּב, שְׁלֹשָׁה מְדוֹרִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיקִים, אֶחָד (שזכו אותם צדיקים שלא נאבדו מהעולם הזה, וכך צריך) לְנַפְשׁוֹת אוֹתָם הַצַּדִּיקִים שֶׁלֹּא הִסְתַּלְּקוּ מֵהָעוֹלָם הַזֶּה וּמְצוּיִים בָּעוֹלָם הַזֶּה. וּכְשֶׁהָעוֹלָם צָרִיךְ רַחֲמִים, וְאוֹתָם הַחַיִּים יוֹשְׁבִים בְּצַעַר, הֵם מִתְפַּלְלִים עֲלֵיהֶם תְּפִלָּה, וְהוֹלְכִים וּמוֹדִיעִים אֶת הַדָּבָר לְאוֹתָם יְשֵׁנֵי חֶבְרוֹן, וּמִתְעוֹרְרִים וְנִכְנָסִים לְגַן הָעֵדֶן שֶׁל הָאָרֶץ, שֶׁשָּׁם רוּחוֹת הַצַּדִּיקִים מְלֻבָּשׁוֹת בְּעַטְרוֹת אוֹר, וּמִתְיָעֲצִים עִמָּם, וְגוֹזְרִים גְּזֵרָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה אֶת רְצוֹנָם וְחָס עַל הָעוֹלָם."],[4,"","וְאוֹתָן נַפְשׁוֹת הַצַּדִּיקִים נִמְצָאוֹת בָּעוֹלָם הַזֶּה לְהָגֵן עַל הַחַיִּים, וְזוֹ נִקְרֵאת נֶפֶשׁ, וְזוֹ לֹא מִסְתַּלֶּקֶת (נאבדת) מִן הָעוֹלָם הַזֶּה, וּמְצוּיָה בָּעוֹלָם הַזֶּה כְּדֵי לְהִסְתַּכֵּל וְלָדַעַת וּלְהָגֵן עַל הַדּוֹר. וְזֶהוּ שֶׁאָמְרוּ הַחֲבֵרִים, שֶׁהַמֵּתִים יוֹדְעִים בְּצַעֲרוֹ שֶׁל הָעוֹלָם. וְעֹנֶשׁ הָרְשָׁעִים שֶׁבָּאָרֶץ הוּא בָּזֶה, שֶׁכָּתוּב וְנִכְרְתָה הַנֶּפֶשׁ הַהִיא מֵעַמֶּיהָ."],[5,"","וְהַמָּדוֹר הַשֵּׁנִי הוּא גַּן הָעֵדֶן שֶׁבָּאָרֶץ, בּוֹ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא מְדוֹרִים עֶלְיוֹנִים נִכְבָּדִים, כְּמוֹ שֶׁהָעוֹלָם הַזֶּה וּכְמוֹ שֶׁהָעוֹלָם הָעֶלְיוֹן, וְהֵיכָלוֹת בִּשְׁנֵי גְוָנִים שֶׁאֵין לָהֶם חֶשְׁבּוֹן, וְאִילָנוֹת וַעֲשָׂבִים וְרֵיחוֹת שֶׁעוֹלִים בְּכָל יוֹם. וּבַמָּקוֹם הַזֶּה שׁוֹרֶה אוֹתוֹ שֶׁנִּקְרֵאת הָרוּחַ שֶׁל אוֹתָם הַצַּדִּיקִים, וְהַמָּדוֹר שֶׁל אוֹתָהּ רוּחַ שֶׁבּוֹ שׁוֹרָה, וְכָל רוּחַ וְרוּחַ מִתְלַבֶּשֶׁת בִּלְבוּשׁ נִכְבָּד כְּמוֹ שֶׁל הָעוֹלָם הַזֶּה, וּכְמוֹ שֶׁל אוֹתוֹ עוֹלָם עֶלְיוֹן."],[6,"","הַמָּדוֹר הַשְּׁלִישִׁי, אוֹתוֹ מָדוֹר קָדוֹשׁ עֶלְיוֹן שֶׁנִּקְרָא צְרוֹר הַחַיִּים, שֶׁשָּׁם מִתְעַדֶּנֶת אוֹתָהּ דַּרְגָּה עֶלְיוֹנָה קְדוֹשָׁה שֶׁנִּקְרֵאת נְשָׁמָה, וְזוֹ דְּבֵקָה לְהִתְעַנֵּג בָּעֹנֶג הָעֶלְיוֹן. עָלֶיהָ כָּתוּב, (ישעיה נח) אָז תִּתְעַנַּג עַל ה' וְהִרְכַּבְתִּיךְ וְגוֹ'."],[7,"","וְלָמַדְנוּ, בְּשָׁעָה שֶׁצָּרִיךְ הָעוֹלָם רַחֲמִים וְאוֹתָם צַדִּיקִים זַכָּאִים, אוֹתָהּ הַנֶּפֶשׁ שֶׁנִּמְצֵאת בָּעוֹלָם לְהָגֵן עַל הָעוֹלָם, הַנֶּפֶשׁ עוֹלֶה וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וּמוֹדִיעָה לָרוּחַ, וְהָרוּחַ עוֹלָה וּמִתְעַטֶּרֶת וּמוֹדִיעָה לַנְּשָׁמָה, וְהַנְּשָׁמָה לַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָז חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל הָעוֹלָם. אָז יוֹרֶדֶת מִמַּעְלָה לְמַטָּה, וְהַנְּשָׁמָה מוֹדִיעָה לָרוּחַ, וְהָרוּחַ מוֹדִיעָה לַנֶּפֶשׁ."],[8,"","וּבְכָל שַׁבָּת וְשַׁבָּת וְרֹאשׁ חֹדֶשׁ, כֻּלָּם מִתְחַבְּרוֹת וּמִתְעַטְּרוֹת כְּאֶחָד, עַד שֶׁמִּזְדַּוְּגוֹת לָבֹא לְהִשְׁתַּחֲווֹת לַמֶּלֶךְ הָעֶלְיוֹן. וְאַחַר כָּךְ חוֹזְרוֹת לִמְקוֹמָן. זֶהוּ שֶׁכָּתוּב (שם סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבא כָל בָּשָׂר וְגוֹ'."],[9,"","וּבְשָׁעָה שֶׁהָעוֹלָם צָרִיךְ רַחֲמִים, וְהַחַיִּים הוֹלְכִים וּמוֹדִיעִים לְנַפְשׁוֹת הַצַּדִּיקִים וּבוֹכִים עַל קִבְרֵיהֶם, אוֹתָם שֶׁרְאוּיִים לְהוֹדִיעַ לָהֶם. מָה הַטַּעַם? כִּי שָׂמִים רְצוֹנָם לְהִדָּבֵק נֶפֶשׁ בְּנֶפֶשׁ, אָז מְעוֹרְרִים אֶת נַפְשׁוֹת הַצַּדִּיקִים, וּמִתְכַּנְּסִים וְהוֹלְכִים וּמְשׁוֹטְטִים לִישֵׁנֵי חֶבְרוֹן, וּמוֹדִיעִים לָהֶם אֶת צַעַר הָעוֹלָם. וְכֻלָּם נִכְנָסִים לְאוֹתוֹ פֶּתַח גַּן הָעֵדֶן וּמוֹדִיעִים לָרוּחַ. וְאוֹתָן רוּחוֹת שֶׁמִּתְעַטְּרוֹת בְּגַן עֵדֶן, הוֹלְכִים בֵּינֵיהֶן מַלְאָכִים עֶלְיוֹנִים, וְכֻלָּם מוֹדִיעִים לַנְּשָׁמָה. וְהַנְּשָׁמָה מוֹדִיעָה לַקָבָּ\"ה, וְכֻלָּם מְבַקְשִׁים רַחֲמִים עַל הַחַיִּים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם בַּעֲבוּרָם. וְעַל זֶה אָמַר שְׁלֹמֹה, וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ וְגוֹ'."]]],[["אָמַר רִבִּי חִיָּיא, תַּוַּוהְנָא אִי אִית מַאן דְּיָדַע לְאוֹדָעָא לְהוּ לְמֵתַיָּיא, בַּר אֲנָן. אָמַר רִבִּי אַבָּא, צַעֲרָא מוֹדְעָא לְהוּ. אוֹרַיְיתָא מוֹדְעָא לְהוּ. דְּהָא בְּשַׁעֲתָא דְּלֵית מַאן דְּיָדַע בְּהַאי, (בראשית רכ\"א ע\"א) אַפְקֵי אוֹרַיְיתָא סָמוּךְ לְקִבְרִי, וְאִינּוּן מִתְעָרֵי, עַל אוֹרַיְיתָא עַל מַה אִתְגַּלְיָיא לְהַהוּא אֲתַר, כְּדֵין דּוּמָה אוֹדַע לְהוֹן.","אָמַר רִבִּי יוֹסֵי, וְאִינּוּן יַדְעֵי דְּהָא עָלְמָא בְּצַעֲרָא, וְחַיַיָא לָא אִתְחָזוּן, וְלָא יַדְעֵי לְאוֹדָעָא לְהוּ. בֵּיהּ שַׁעֲתָא כֻּלְּהוּ צַוְוחִין עַל אוֹרַיְיתָא דְּאִתְקְלָנָא וְאִתְגַּלְיָיא לְהַהוּא אֲתַר. אִי בְּנֵי נָשָׁא תַּיְיבִין וּבָכָאן בְּלִבָּא שְׁלִים, וְתַיְיבִין קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כֻּלְּהוּ מִתְכַּנְּשֵׁי, וּבָעָאן רַחֲמֵי, וּמוֹדִיעִין לְאִינּוּן דְּמִיכֵי חֶבְרוֹן, וְעָאלִין וּמוֹדְעִין לְרוּחַ דבְּגַּן עֵדֶן, כְּמָה דְּאַמָרָן.","וְאִי אִינּוּן לָא תַּיְיבִין בְּלִבָּא שְׁלִים לְמִבָּעֵי וּלְמִבְכֵּי עַל צַעֲרָא דְּעָלְמָא. וַוי לְהוֹן, דְּכֻלְּהוּ מִתְכַּנְּפֵי לְרֵיקָא אַמְרֵי מַאן גָּרַם לְאוֹרַיְיתָא קַדִּישָׁא דְּאִתְגַּלְיָיא עַל יְדַיְיהוּ בְּלָא תְּשׁוּבָה. וְכֻלְּהוּ אָתָאן לְאִתְחַדְתָּא (ס\"א לאדכרא) חוֹבַיְיהוּ בְּגִינֵי כַּךְ לָא יַהֲכוּן תַּמָּן בְּלָא תְּשׁוּבָה וּבְלָא תַּעֲנִיתָא לְמִבָּעֵי בָּעוּתָא קַמַּיְיהוּ. רִבִּי אַבָּא אָמַר, (ס\"א כלא אתלת) בְּלָא תְּלַת תַּעֲנִיתָא. רִבִּי יוֹסֵי אָמַר, אֲפִילּוּ חַד, וּבְהַהוּא יוֹמָא, וּבִלְבַד דְּעָלְמָא יָתִיב בְּצַעֲרָא טְפֵי, כְּדֵין כֻּלְּהוּ מִזְדַּוְּוגֵי לְמִבָּעֵי רַחֲמִין עַל עָלְמָא.","תָּאנָא, אָמַר רִבִּי יְהוּדָה, יוֹמָא חַד הֲווֹ אַזְלֵי (קמ\"ד ע\"א, צ\"א) רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא בְּאוֹרְחָא, עָרְעוּ בְּגוּשׁ חָלָב, וַהֲוָה חָרִיב, יָתְבוּ סָמִיךְ לְבֵי קִבְרֵי, וְרִבִּי יֵיסָא הֲוָה בִּידֵיהּ חַד חוּטְרָא (ס\"א קיטרא) דְסֵפֶר תּוֹרָה דְּאִקְרַע, עַד דְּיָתְבוּ אִתְרְגִישׁ חַד קִבְרָא קָמַיְיהוּ, וְצָוַוח וַוי וַוי, דְּהָא עָלְמָא בְּצַעֲרָא שְׁכִיחַ, הָא אוֹרַיְיתָא הָכָא דְּאִתְגַּלְיָיא, אוֹ חַיָּיָא אָתוּ לְחַיְּיכָא עֲלָן, וּלְכַסְּפָא בְּכִסּוּפָא עֲלָן בְּאוֹרָיְיתַיְיהוּ. אִזְדַּעֲזָעוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא.","אָמַר רִבִּי חִזְקִיָּה מַאן אַתְּ. אָמַר לֵיהּ מֵיתָא אֲנָא, וְהָא אִתְּעַרְנָא לְגַבֵּי סֵפֶר תּוֹרָה. דְּזִמְנָא חֲדָא הֲוָה יָתִיב עָלְמָא בְּצַעֲרָא, וְאָתוּ חַיָּיָא הָכָא, לְאִתְּעָרָא לָן בְּסֵפֶר תּוֹרָה, וַאֲנָא וְחַבְרָאי אַקְדִּימְנָא לְגַבֵּי דְּמִיכֵי חֶבְרוֹן, וְכַד אִתְחַבָּרוּ בְּגַן עֵדֶן בְּרוּחֵיהוֹן דְּצַדִּיקַיָּיא, אִשְׁתְּכַח קָמַיְיהוּ, דְּהַהוּא סֵפֶר תּוֹרָה דְּאַיְיתוּ לְקַמָּן אִינּוּן חַיַיָא, הֲוָה פָּסוּל וּמְשַׁקֵּר בִּשְׁמָא דְּמַלְכָּא, עַל דְּאִשְׁתְּכַח וָא\"ו יַתִּיר בְּהַהוּא קְרָא (ויקרא יא) דִּוְשֹׁסַעַת שֶׁסַע שְׁתֵּי פְרָסוֹת, וְאָמְרוּ דְּהוֹאִיל וְשַׁקְּרוּ בִּשְׁמָא דְּמַלְכָּא דְּלָא יְתוּבוּן לְגַבֵּיהוֹן, וְדָחוּ לִי וּלְחַבְרָאי בְּהַהִיא שַׁעֲתָא מִבֵּי מְתִיבְתָּא.","עַד דְּחַד סָבָא דְּהֲוָה בֵּינַיְיהוּ, אָזַל וְאַיְיתֵי סַפְרָא דְּרַב הַמְנוּנָא סָבָא, וּכְדֵין אִתְּעַר (קהלת רבה פסוק שלח לחמך) רִבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן, דְּהֲוָה קָבִיר עִמָּנָא, וְאָזַל וּבָעָא בְּגַּן עֵדֶן עָלַיְיהוּ, וְאִתְסֵי עָלְמָא, כְּדֵין שָׁארוּ לָן, וּמִן הַהוּא יוֹמָא דִּסְלִיקוּ לֵיהּ לְרִבִּי אֶלְעָזָר מִבֵּי קִבְרָא דָּא, וְאִתְיְיהִיב לְגַבֵּי אֲבוּהָ, לֵית מַאן דְּאִתְּעַר לְמֵיקָם קַמַּיְיהוּ דִּדְמִיכֵי חֶבְרוֹן, דְּמִסְתַּפֵּינָא מִן הַהוּא יוֹמָא דְּדָחוּ לִי וְלַחֲבֵרַי. וְהַשְׁתָּא אֲתִיתּוּן לְגַבָּן, וְסֵפֶר תּוֹרָה גַּבֵּיכוֹן, אֲמֵינָא דְּהָא עָלְמָא בְּצַעֲרָא אִשְׁתְּכַח. וְעַל דָּא אִזְדַּעֲזַעַנָא, דַּאֲמֵינָא מַאן יַקְדִּים לְאוֹדָעָא לְאִינּוּן זַכָּאֵי קְשׁוֹט דְּמִיכֵי חֶבְרוֹן, אִשְׁתְּמִיט רִבִּי יֵיסָא בְּהַהוּא קִיטְרָא דְּסֵפֶר תּוֹרָה. אָמַר רִבִּי חִזְקִיָּה, חַס וְשָׁלוֹם לֵית עָלְמָא בְּצַעֲרָא, וַאֲנָן לָא אֲתֵינָן לְהַאי.","קָמוּ רִבִּי חִזְקִיָּה וְרִבִּי יֵיסָא וְאַזְלוּ. אַמְרֵי, וַדַּאי בְּשַׁעֲתָא דְּזַכָּאִין לָא אִשְׁתְּכָחוּ בְּעָלְמָא, עָלְמָא לָא מִתְקַיְּימָא אֶלָּא בְּגִינֵיהוֹן דְּמֵתַיָּיא. אָמַר רִבִּי יֵיסָא, בְּשַׁעֲתָא דְּאִצְטְרִיךְ עָלְמָא לְמִטְרָא, אֲמַאי אַזְלֵינָן לְגַבֵּיהוֹן דְּמֵתַיָּיא, וְהָא כְּתִיב (דברים י״ח:י״א) וְדוֹרֵשׁ אֶל הַמֵּתִים וְאָסִיר. אָמַר לֵיהּ עַד כָּאן לָא חֲמֵיתָא גַּדְפָּא דְּצִפָּרָא דְּעֵדֶן. וְדוֹרֵשׁ אֶל הַמֵּתִים, אֶל הַמֵּתִים דַּיְיקָא. דְּאִינּוּן חַיָּיבֵי עָלְמָא, דְּאִינּוּן מֵעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּאִשְׁתְּכָחוּ תָּדִיר מֵתִים. אֲבָל יִשְׂרָאֵל דְּאִינּוּן זַכָּאֵי קְשׁוֹט, שְׁלֹמֹה קְרָא עָלַיְיהוּ (קהלת ד׳:ב׳) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, בְּזִמְנָא אָחֳרָא וְלָא הַשְׁתָּא. שֶׁכְּבָר מֵתוּ, וְהַשְׁתָּא אִינּוּן חַיִּין."],[[0,"אמר ר׳ חייא וכו׳:","אמר ר׳ חייא, תמה אני, אם יש מי שיודע להודיע אל המתים חוץ ממנו. אמר ר׳ אבא הצער, שהאנשים מצטערים, מודיע להם, התורה מודיעה להם. שבשעה שאין מי שיודע בזה, איך להודיע לנפשות הצדיקים, מוציאים ספר תורה סמוך לקברים, והן מתעוררות על מה שהתורה נגלתה למקום הזה, אז המלאך דומה מודיע להן."],[1,"א״ר יוסי ואינון וכו׳:","אר״י, והם יודעים שהעולם הוא בצער, והחיים, אינם ראוים ואינם יודעים להודיע להם, בה בשעה כולם צווחים על התורה, שנכשלנו והיא גלתה למקום הזה. אם בני אדם שבים בתשובה, ובוכים בלב שלם ושבים לפני הקב״ה, כולן מתאספות ומבקשות רחמים, ומודיעות לאלו ישני חברון, ונכנסות ומודיעות לרוח שבגן עדן, כמו שאמרנו."],[2,"ואי אינון לא וכו׳:","ואם הם אינם שבים בלב שלם, לבקש ולבכות על צער העולם, אוי להם, שכולן מתאספות לריק. אומרים, מי גרם לתורה הקדושה שגלתה על ידיהם בלא תשובה, וכולם באים להזכיר עונותיהם, ומשום זה לא ילכו שמה בלא תשובה, ובלא תענית, לבקש בקשות לפניהם. ר׳ אבא אמר, בלא ג׳ תעניתים. ר׳ יוסי אמר אפילו תענית אחת דיה, ויהיה באותו יום, ובלבד שהעולם יושב בצער ביותר, אז כולם מתחברים, דהיינו כל נר״נ, לבקש רחמים על העולם."],[3,"תאנא א״ר יהודה וכו׳:","למדנו אר״י, יום אחד היו הולכים ר׳ חזקיה ור׳ ייסא בדרך, פגשו במקום שנקרא, גוש חלב והיה חרוב. ישבו סמוך לבית הקברות, ור׳ ייסא היה בידו חלק אחד של ספר תורה שנקרע. כלומר, שהיה בידו חלק הנקרע מספר תורה עם העמוד שבתוכו. בעוד שישבו התנענע לפניהם קבר אחד, וצעק, אוי אוי, הרי העולם נמצא בצער, כי התורה גלתה לכאן, או אפשר, שהחיים באו לצחוק עלינו ולבזות אותנו בחרפה, עם תורתם. נזדעזעו ר׳ חזקיה ור׳ ייסא. \u0003אתרגיש,\u0004 פירושו התנענע. כי על ויתגעש ותרעש ארץ, מתרגם ואתרגשת. (שמואל ב׳ כ״ח ח׳), דהיינו רעש ונענוע."],[4,"אמר ר׳ חזקיה וכו׳:","אמר ר׳ חזקיה, אל הקבר, מי אתה. אמר לו מת אני והרי נתעוררתי בשביל ספר התורה. כי פעם אחת היה העולם יושב בצער. ובאו החיים כאן לעורר אותנו בספר תורה. ואני וחברי הקדמנו לישני חברון. וכשנתחברו בגן עדן ברוחות הצדיקים, נמצא לפניהם, שספר התורה ההוא שהביאו לפנינו החיים, היה פסול, ומשקר בשם המלך, על שנמצא ו' יתירה במקרא ההוא דושסעת שסע שתי פרסות שהיה כתוב שם ושוסעת. ואמרו, כיון ששקרו בשם המלך. כי התורה היא שם המלך, לא ישובו אליהם, להודיעם אם נתקבלה תפלתם. ודחו אותי וחברי, בשעה ההיא, מבית הישיבה."],[5,"עד דחד סבא וכו׳:","עד שזקן אחד שהיה ביניהם הלך והביא הספר של ר׳ המנונא סבא. ואז נתעורר רבי אלעזר. בר׳ שמעון שהיה קבור עמנו, והלך והתפלל בגן עדן עליהם. ונרפא העולם. אז התירו לנו, לחזור לבית הישיבה. ומיום ההוא שהעלו את ר׳ אלעזר מהקבר הזה שבגוש חלב, וניתן אצל אביו, במירון, אין מי שיעורר לקום לפני ישני חברון. כי אנו מפחדים מאותו היום שדחו אותי ואת חבירי מבית הישיבה. ועתה באתם לנו, וספר תורה אצלכם, אמרתי, שהעולם נמצא בצער. וע״כ נזדעזעתי, שאמרתי, מי יקדים להודיע לאלו צדיקי אמת ישני חברון. נשמט ר׳ ייסא והלך לו עם אותו חלק של ספר התורה. א״ר חזקיה, חס ושלום, אין העולם בצער, ואנו לא באנו לזה."],[5,"","ואין להקשות הרי ר׳ חזקיה ור' ייסא מתו באדרא רבא, ועוד היה ר״א בר״ש חי. כמ״ש בסוף אדרת נשא. כי אלו ר׳ חזקיה ור' ייסא שבכאן אינם אותם שבאדרא רבא."],[6,"קמו ר׳ חזקיה וכו׳:","קמו ר״ח ור׳ ייסא והלכו. אמרו ודאי בשעה שצדיקים אינם נמצאים בעולם, אין העולם מתקיים אלא בזכותם של המתים. אמר ר׳ ייסא, בשעה שהעולם צריך לגשמים, למה הולכים אל המתים להתפלל, והרי כתוב, ודורש אל המתים. ואסור. אמר לו, עד עתה עוד לא ראית הכנף של הצפור שבעדן, שה\"ס בינה, כלומר שעוד לא השיג הבינה. כי הכתוב, ודורש אל המתים, אל המתים הוא בדיוק, שהם רשעי עולם, שהם מעמי עכו״ם, הנמצאים תמיד מתים, כי הרשעים בחייהם נקראים מתים. אבל ישראל, שהם צדיקי אמת קרא עליהם שלמה, ושבח אני את המתים שכבר מתו. \u0003שכבר מתו\u0004 בפעם אחרת, שהמיתו עצמם על התורה (כנ״ל אות רנ״ז) ולא עתה. \u0003שכבר מתו,\u0004 ועתה הם חיים."]],[[0,"","אָמַר רַבִּי חִיָּיא, תְּמֵהַנִי אִם יֵשׁ מִי שֶׁיּוֹדֵעַ לְהוֹדִיעַ לַמֵּתִים פְּרָט לָנוּ. אָמַר רַבִּי אַבָּא, הַצַּעַר מוֹדִיעַ לָהֶם, הַתּוֹרָה מוֹדִיעָה לָהֶם. שֶׁהֲרֵי בְּשָׁעָה שֶׁאֵין מִי שֶׁמַּכִּיר אֶת זֶה, מוֹצִיאִים אֶת הַתּוֹרָה סָמוּךְ לַקְּבָרִים, וְהֵם מִתְעוֹרְרִים עַל הַתּוֹרָה עַל מָה גָּלְתָה לְאוֹתוֹ מָקוֹם, וְאָז דּוּמָה מוֹדִיעַ לָהֶם."],[1,"","אָמַר רַבִּי יוֹסֵי, וְהֵם יוֹדְעִים שֶׁהֲרֵי הָעוֹלָם בְּצַעַר, וְהַחַיִּים לֹא רְאוּיִים וְלֹא יוֹדְעִים לְהוֹדִיעַ לָהֶם. בְּאוֹתָהּ שָׁעָה כֻּלָּם צוֹוְחִים עַל שֶׁהַתּוֹרָה נִקְלְתָה וְגָלְתָה לְאוֹתוֹ מָקוֹם. אִם בְּנֵי אָדָם שָׁבִים וּבוֹכִים בְּלֵב שָׁלֵם וְשָׁבִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אָז כֻּלָּם מִתְכַּנְּסִים וּמְבַקְשִׁים רַחֲמִים וּמוֹדִיעִים לְאוֹתָם יְשֵׁנֵי חֶבְרוֹן, וְנִכְנָסִים וּמוֹדִיעִים לָרוּחַ שֶׁבְּגַן עֵדֶן, כְּמוֹ שֶׁאָמַרְנוּ."],[2,"","וְאִם הֵם לֹא שָׁבִים בְּלֵב שָׁלֵם לְבַקֵּשׁ וְלִבְכּוֹת עַל צַעַר הָעוֹלָם - אוֹי לָהֶם! שֶׁכֻּלָּם מִתְכַּנְּסִים לָרִיק וְאוֹמְרִים: מִי גָרַם לַתּוֹרָה הַקְּדוֹשָׁה לִגְלוֹת עַל יְדֵיהֶם בְּלִי תְשׁוּבָה? וְכֻלָּם בָּאִים לְחַדֵּשׁ (להזכיר) חֲטָאֵיהֶם. מִשּׁוּם כָּךְ אַל יֵלְכוּ לְשָׁם בְּלִי תְשׁוּבָה וּבְלִי תַעֲנִית לְבַקֵּשׁ בַּקָּשָׁה לִפְנֵיהֶם. רַבִּי אַבָּא אָמַר, (הכל על שלש) בְּלִי שָׁלֹשׁ תַּעֲנִיּוֹת. רַבִּי יוֹסֵי אָמַר, אֲפִלּוּ אַחַת וּבְאוֹתוֹ יוֹם, וּבִלְבַד שֶׁהָעוֹלָם יֵשֵׁב בְּצַעַר יָתֵר, אָז כֻּלָּם מִזְדַּוְּגִים לְבַקֵּשׁ רַחֲמִים עַל הָעוֹלָם."],[3,"","לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, יוֹם אֶחָד הָיוּ הוֹלְכִים רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא בַּדֶּרֶךְ. פָּגְעוּ בְּגוּשׁ חָלָב, וְהָיָה חָרֵב. יָשְׁבוּ סָמוּךְ לְבֵית הַקְּבָרוֹת, וּבִידֵי רַבִּי יֵיסָא הָיָה מַקֵּל (קשר) שֶׁל סֵפֶר תּוֹרָה שֶׁנִּקְרַע. בְּעוֹד שֶׁיָּשְׁבוּ, רָעַשׁ קֶבֶר אֶחָד לִפְנֵיהֶם וְצָוַח: אוֹי אוֹי! שֶׁהֲרֵי הָעוֹלָם מָצוּי בְּצַעַר. הֲרֵי הַתּוֹרָה גָּלְתָה לְכָאן, אוֹ שֶׁהַחַיִּים בָּאוּ לִצְחֹק עָלֵינוּ וּלְבַיֵּשׁ אוֹתָנוּ בְּבוּשָׁה בְּתוֹרָתָם! הִזְדַּעְזְעוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא."],[4,"","אָמַר רַבִּי חִזְקִיָּה, מִי אַתָּה? אָמַר לוֹ: אֲנִי מֵת, וַהֲרֵי הִתְעוֹרַרְתִּי לְסֵפֶר הַתּוֹרָה. שֶׁפַּעַם אַחַת הָיָה הָעוֹלָם יוֹשֵׁב בְּצַעַר, וּבָאוּ לְכָאן הַחַיִּים לְעוֹרֵר אוֹתָנוּ עִם סֵפֶר תּוֹרָה, וַאֲנִי וַחֲבֵרַי הִקְדַּמְנוּ אֶל יְשֵׁנֵי חֶבְרוֹן, וּכְשֶׁהִתְחַבְּרוּ בְּגַן עֵדֶן עִם רוּחוֹת הַצַּדִּיקִים, נִמְצָא לִפְנֵיהֶם, שֶׁאוֹתוֹ סֵפֶר תּוֹרָה שֶׁהֵבִיאוּ לְפָנֵינוּ אוֹתָם הַחַיִּים הָיָה פָּסוּל וּמְשַׁקֵּר בְּשֵׁם הַמֶּלֶךְ, עַל שֶׁנִּמְצְאָה וָא\"ו יְתֵרָה בְּאוֹתוֹ פָּסוּק שֶׁל (ויקרא יא) וְֹשסַעַת שֶׁסַע שְׁתֵּי פְרָסוֹת. וְאָמְרוּ, שֶׁהוֹאִיל וְשִׁקְּרוּ בְשֵׁם הַמֶּלֶךְ, שֶׁלֹּא יָשׁוּבוּ אֲלֵיהֶם, וְדָחוּ אוֹתִי וְאֶת הַחֲבֵרִים שֶׁלִּי מִבֵּית הַיְשִׁיבָה."],[5,"","עֵד שֶׁזָּקֵן אֶחָד שֶׁהָיָה בֵינֵיהֶם הָלַךְ וְהֵבִיא אֶת סִפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְאָז הִתְעוֹרֵר רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן, שֶׁהָיָה קָבוּר עִמָּנוּ, וְהָלַךְ וּבִקֵּשׁ בְּגַן עֵדֶן עֲלֵיהֶם, וְנִרְפָּא הָעוֹלָם. וְאָז הִתִּירוּ לָנוּ, וּמֵאוֹתוֹ יוֹם שֶׁהֶעֱלוּ אֶת רַבִּי אֶלְעָזָר מִבֵּית הַקְּבָרוֹת הַזֶּה וְנִתַּן לְאָבִיו, אֵין מִי שֶׁיִּתְעוֹרֵר לַעֲמֹד לִפְנֵי יְשֵׁנֵי חֶבְרוֹן, שֶׁאָנוּ פוֹחֲדִים מֵאוֹתוֹ הַיּוֹם שֶׁדָּחוּ אוֹתִי וְאֶת חֲבֵרַי. וְעַכְשָׁו בָּאתֶם אֵלֵינוּ עִם סֵפֶר תּוֹרָה עִמָּכֶם, אָמַרְנוּ שֶׁהֲרֵי הָעוֹלָם מָצוּי בְּצַעַר. וְעַל כֵּן הִזְדַּעְזַעְנוּ, שֶׁאָמַרְנוּ: מִי יַקְדִּים לְהוֹדִיעַ לְאוֹתָם צַדִּיקֵי אֱמֶת יְשֵׁנֵי חֶבְרוֹן? נִשְׁמַט רַבִּי יֵיסַא עִם אוֹתוֹ חֵלֶק שֶׁל סֵפֶר תּוֹרָה. אָמַר רַבִּי חִזְקִיָּה, חַס וְשָׁלוֹם אֵין הָעוֹלָם בְּצַעַר, וְאָנוּ לֹא בָאנוּ לְכָךְ."],[6,"","קָמוּ רַבִּי חִזְקִיָּה וְרַבִּי יֵיסָא וְהָלְכוּ. אָמְרוּ, וַדַּאי בְּשָׁעָה שֶׁצַּדִּיקִים לֹא נִמְצָאִים בָּעוֹלָם, הָעוֹלָם אֵינוֹ מִתְקַיֵּם אֶלָּא בִּשְׁבִיל הַמֵּתִים. אָמַר רַבִּי יֵיסָא, בְּשָׁעָה שֶׁהָעוֹלָם צָרִיךְ אֶת הַמָּטָר, לָמָּה הוֹלְכִים אֵצֶל הַמֵּתִים, וַהֲרֵי כָּתוּב (דברים יח) וְדֹרֵשׁ אֶל הַמֵּתִים, וְאָסוּר? אָמַר לוֹ, עַד כָּאן לֹא רָאִיתָ כְּנַף צִפּוֹר הָעֵדֶן. וְדֹרֵשׁ אֶל הַמֵּתִים, דַּוְקָא אֶל הַמֵּתִים. שֶׁהֵם רִשְׁעֵי הָעוֹלָם שֶׁהֵם מֵעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁנִּמְצָאִים תָּמִיד עִם הַמֵּתִים. אֲבָל יִשְׂרָאֵל, שֶׁהֵם צַדִּיקֵי אֱמֶת, עֲלֵיהֶם קָרָא שְׁלֹמֹה, (קהלתד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, בִּזְמַן אַחֵר וְלֹא עַכְשָׁו. שֶׁכְּבָר מֵתוּ, וְעַכְשָׁו הֵם חַיִּים."]]],[["וְעוֹד, דִּשְׁאָר עַמִּין כַּד אָתָאן לִמְתֵיהוֹן, אַתְיָין בְּחַרְשִׁין, לְאִתְּעָרָא עָלַיְיהוּ זִינִין בִּישִׁין. וְכַד יִשְׂרָאֵל אָתָאן לִמְתֵיהוֹן, אַתְיָין בְּכַמָּה תְּשׁוּבָה לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. בִּתְבִירוּ דְּלִבָּא, בְּתַעֲנִיתָא לָקֳבְלֵיהּ, וְכֹלָּא בְּגִין דְּנִשְׁמָתִין קַדִּישִׁין יִבְעוּן רַחֲמֵי לְקַמֵּי קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא חָיִיס עַל עָלְמָא בְּגִינֵיהוֹן.","וְעַל דָּא תָּנֵינָן, צַדִּיקָא אַף עַל גַּב דְּאִתְפְּטָר מֵהַאי עָלְמָא, לָא אִסְתַּלָּק וְלָא אִתְאֲבִיד מְכֻּלְּהוּ עָלְמִין, דְּהָא בְּכֻלְּהוּ עָלְמִין אִשְׁתְּכַח יַתִּיר מֵחַיּיוֹי. דִּבְחַיּיוֹי אִשְׁתְּכַח בְּהַאי עָלְמָא בִּלְחוֹדוֹי, וּלְבָתַר אִשְׁתְּכַח בִּתְלַת עָלְמִין, וְזַמִּין לְגַבַּיְיהוּ, דִּכְתִּיב, (שיר השירים א׳:ג׳) עֲלָמוֹת אֲהֵבוּךָ, אַל תִּקְרֵי עֲלָמוֹת, אֶלָּא עוֹלָמוֹת. זַכָּאָה חוּלָקֵיהוֹן.","תָּאנָא, כְּתִיב (שמואל א כ״ה:כ״ט) וְהָיְתָה נֶפֶשׁ אֲדוֹנִי צְרוּרָה בִּצְרוֹר הַחַיִּים, וְהָיְתָה נֶפֶשׁ אֲדוֹנִי, נִשְׁמַת אֲדוֹנִי מִבָּעֵי לֵיהּ. אֶלָּא כְּמָה דְּאַמָרָן, דְּזַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא דְּכֹלָּא אִתְקְשַׁר דָּא בְּדָא, נֶפֶשׁ בְּרוּחַ, וְרוּחַ בִּנְּשָׁמָה, וּנְשָׁמָה בְּקוּדְשָׁא בְּרִיךְ הוּא. אִשְׁתְּכַח דְּנֶפֶשׁ צְרוּרָה בִּצְרוֹר הַחַיִּים.","אָמַר רִבִּי אֶלְעָזָר, הַאי דְּאָמְרוּ חַבְרַיָּיא, גָּלוּתָא דְסֵפֶר תּוֹרָה אֲפִילּוּ מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא אָחֳרָא אָסִיר. וְכָּל שֶׁכֵּן לְבֵי רְחוֹב, אֲמַאי לְבֵי רְחוֹב. אָמַר רִבִּי יְהוּדָה, כְּמָה דְּאַמָרָן, בְּגִין דְּיִתְעָרוּן עָלֵיהּ וְיִתְבְּעוּן רַחֲמֵי עַל עָלְמָא. אָמַר רִבִּי אַבָּא, שְׁכִינְתָּא כַּד אִתְגַּלְיָיא הָכִי נָמֵי מֵאֲתַר לַאֲתַר, עַד דְּאָמְרָה (ירמיהו ט׳:א׳) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים וְגוֹ' אוּף הָכָא בְּקַדְמִיתָא מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא, לְבָתַר לְבֵי רְחוֹב, לְבָתַר בַּמִּדְבָּר מְלוֹן אוֹרְחִים. אָמַר רִבִּי יְהוּדָה, בְּנֵי בָּבֶל מִסְתָּפוּ וְלָא קָא עַבְרֵי אֲפִילּוּ מִבֵּי כְּנִישְׁתָּא לְבֵי כְּנִישְׁתָּא, כָּל שֶׁכֵּן הַאי.","תַּנְיָא, אָמַר לְהוּ רַבִּי שִׁמְעוֹן לְחַבְרַיָּא, בְּיוֹמַאי לָא יִצְטָרְכוּן בְּנֵי עָלְמָא לְהַאי. אָמַר לֵיהּ רִבִּי יוֹסֵי, צַדִּיקַיָּיא מְגִינִּין עַל עָלְמָא בְּחַיֵּיהוֹן, וּבְמִיתָתְהוֹן יוֹתֵר מֵחַיֵּיהוֹן. הֲדָא הוּא דִכְתִיב, (ישעיהו ל״ז:ל״ה) וְגַנּוֹתִי עַל הָעִיר הַזֹאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, וְאִילּוּ בְּחַיּיוֹהִי לָא כְּתִיב. אָמַר רִבִּי יְהוּדָה מַאי שְׁנָא הָכָא דִּכְתִּיב לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, דְּשָׁקִיל הַאי לְגַבֵּי הַאי. אֶלָּא, בְּגִין דְּדָוִד זָכָה לְאִתְקַשְּׁרָא בִּרְתִּיכָא קַדִּישָׁא דַּאֲבָהָתָא, וּבְגִין כָּךְ כֹּלָּא חַד, בְּרִיךְ הוּא לְעָלַם וּלְעָלְמֵי עָלְמַיָּא.","(ויקרא י״ח:ג׳) כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ, רִבִּי יִצְחָק פָּתַח, (תהילים ק״ב:כ״ב) לְסַפֵּר בְּצִיּוֹן שֵׁם יְיָ' וּתְהִלָּתוֹ בִּיְרוּשָׁלַ ם. תַּמָּן תָּנֵינָן, שְׁמָא קַדִּישָׁא סָתִים וְגַלְיָא. וְאוֹרַיְיתָא דְּהִיא שְׁמָא קַדִּישָׁא עִלָּאָה, סָתִים וְגַלְיָא. וְכָל קְרָא דִּבְאוֹרַיְיתָא, וְכָל פַּרְשְׁתָא דְּאוֹרַיְיתָא, סָתִים וְגַלְיָא.","דְּתַנְיָא אָמַר רִבִּי יְהוּדָה, מֵחֲצִיפוּתָא דְּצַדֶּקֶת חֲדָא, נַפְקָן כְּמָה טָבָאן לְעָלְמָא. וּמַאן הִיא. תָּמָר. דִּכְתִּיב, (בראשית ל״ח:י״ד) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. אָמַר רִבִּי אַבָּא, פַּרְשְׁתָּא דָּא מוֹכַח, דְּאוֹרַיְיתָא סָתִים וְגַלְיָא. וְהָא אִסְתַּכַּלְנָא בְּאוֹרַיְיתָא כֻּלָּא, וְלָא אַשְׁכַּחְנָא אֲתַר דְּאִקְרֵי פֶּתַח עֵינַיִם, אֶלָּא כֹּלָּא סָתִים, וְרָזָא דְּרָזִין הוּא.","וְתַנְיָא, מַאי חָמָאת צַדֶּקֶת זוֹ לְעוֹבָדָא דָּא. אֶלָּא יַדְעַת בְּבֵיתָא דַּחֲמוֹהִי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, הֵיךְ מַדְבֵּר הַאי עָלְמָא עִם בְּנֵי נָשָׁא. וּבְגִין דְּהִיא יַדְעַת, קוּדְשָׁא בְּרִיךְ הוּא אוֹקִים מִלָּה עַל יְדָהָא. וְאַזְלָא הָא כְּמָה דְּתָנֵינָן, אִזְדַּמְּנַת הֲוַת בַּת שֶׁבַע מו' יְמֵי בְּרֵאשִׁית לְמֶהֱוִי אִמֵּיהּ דִּשְׁלָמָא מַלְכָּא. אוּף הָכָא אִזְדַּמְּנַת הֲוַת תָּמָר לְדָא, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא.","וַתֵּשֶׁב בְּפֶתַח עֵינַיִם, מַאן פֶּתַח עֵינַיִם כְּמָה דְּאַתְּ אָמֵר, (בראשית י״ח:א׳) וְהוּא יוֹשֵׁב פֶּתַח הָאֹהֶל. וּכְתִיב, (שמות י״ב:כ״ג) וּפָסַח יְיָ' עַל הַפֶּתַח. וּכְתִיב (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק וְגוֹ'. עֵינַיִם: דְּכָל עַיְינִין דְּעָלְמָא לְהַאי פִּתְחָא מְצַפָּאן. אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה, מַאי תִּמְנָתָה. כְּמָה דְאַתְּ אָמֵר (במדבר יב) וּתְמוּנַת יְיָ' יַבִּיט. וְהָכִי אוֹקִימְנָא, תָּמָר אוֹקִימַת מִלָּה לְתַתָּא, וּפַרְחַת פַּרְחִין, וַאֲנִיצַת עַנְפִין בְּרָזָא דִּמְהֵימְנוּתָא."],[[0,"ועוד דשאר עמין וכו׳:","ועוד, כי שאר העמים, כשבאים למתים שלהם, באים בכשפים לעורר עליהם המינים הרעים. וכשישראל באים למתים, באים בהרבה תשובה לפני הקב״ה, בשבירת הלב ובתענית הם לפניו. והכל כדי שהנשמות הקדושות תבקשנה רחמים עליהם לפני הקב״ה, והקב״ה מרחם על העולם בשבילם."],[1,"וע״ד תנינן צדיקייא וכו׳:","וע״כ למדנו, הצדיק, אע״פ שנפטר מן העולם הזה, אינו מסתלק ואינו נאבד מכל העולמות, כי הוא נמצא בכל העולמות עוד יותר מבחייו, כי בחייו היה נמצא בעולם הזה בלבד, ואח״כ הוא נמצא בג׳ עולמות, שהם בריאה יצירה עשיה, והוא מצוי אצלם, שכתוב, עלמות אהבוך. אל תקרי עלמות, אלא עולמות. אשרי חלקם."],[2,"תאנא כתיב והיתה וגו׳:","למדנו, כתוב, והיתה נפש אדוני צרורה בצרור החיים. שואל, אומר, והיתה נפש אדוני, נשמת אדוני היה צריך לומר, שהרי הנפש נשארת בעולם הזה, ורק הנשמה עולה לצרור החיים (כנ״ל אות רס״ב). ומשיב, אלא כמו שאמרנו, שאשרי חלקם של הצדיקים, שהכל נקשר זה בזה, הנפש ברוח והרוח בנשמה, והנשמה בהקב״ה. (כנ״ל אות רנ״ז) נמצא שהנפש צרורה בצרור החיים. כי נקשרת בנשמה שהיא בצרור החיים."],[3,"אמר ר׳ אלעזר וכו׳:","אר״א, זה שאמרו החברים, שגלות ספר תורה, אפילו מבית כנסת לבית כנסת אחר אסור, וכל שכן לרחוב, ולמה מוציאים אותו לרחוב. אמר ר׳ יהודה, כמו שאמרנו, כדי שיתעוררו עליה, ויבקשו רחמים על העולם. אמר ר׳ אבא כשגלתה השכינה גלתה ג״כ ממקום למקום, עד שאמרה. מי יתנני במדבר מלון אורחים וגו'. אף כאן, מתחילה גלתה מבית כנסת לבית כנסת, ואח״כ לרחוב, ואח\"כ במדבר מלון אורחים. אר״י, בני בבל יראים ואינם עוברים עם ספר התורה, אפילו מבית כנסת לבית כנסת כ״ש זה, לרחוב."],[4,"תניא אמר להו וכו׳:","למדנו אמר להם ר׳ שמעון לחברים, בימי לא יצטרכו בני עולם לזה. להוציא ספר התורה לרחוב. א״ל ר׳ יוסי, צדיקים מגינים על העולם בחייהם, ובמיתתם יותר מבחייהם. ז״ש, וגנותי על העיר הזאת להושיעה למעני ולמען דוד עבדי. ואלו בחייו של דוד זה אינו כתוב. אמר ר׳ יהודה מהו השינוי כאן שכתוב, \u0003למעני ולמען דוד עבדי,\u0004 שהשוה זה לזה ומשיב, אלא בשביל שדוד זכה להתקשר במרכבה הקדושה של האבות, שהוא רביעי להם, שה״ס המלכות, ומשום זה הכל אחד. ברוך הוא לעולם ולעולמי עולמים."],[5,"כמעשה ארץ מצרים וגו׳ לא תעשו:","ר׳ יצחק פתח, לספר בציון שם ה׳ ותהלתו בירושלים. שם למדנו, השם הקדוש סתום ונגלה, שהנסתר הוא הויה והנגלה הוא אדני. והתורה, שהיא שם הקדוש העליון, דז״א, היא סתומה ומגולה. וכל מקרא שבתורה, וכל פרשה שבתורה סתומה ומגולה. כלומר, שיש בה פשט ויש בה סוד."],[6,"דתניא א״ר יהודה וכו׳:","שלמדנו אר״י, מעזות של צדקת אחת, יצאו כמה טובות לעולם, ומי היא. היא תמר. שכתוב, ותשב בפתח עינים. אמר רבי אבא, פרשה זו מוכיחה לנו שהתורה היא סתומה וגלויה, שיש בה נגלה ונסתר, והרי הסתכלתי בכל התורה כולה, ולא מצאתי מקום שיהיה נקרא פתח עינים. אלא הכל סתים הוא, וסוד הסודות הוא."],[7,"ותניא מה חמאת וכו׳:","ולמדנו, מה ראתה צדקת זו למעשה זה. ומשיב, אלא ידעה בבית חמיה, דרכיו של הקב״ה, איך מנהיג את העולם הזה עם בני אדם, ומשום שהיא ידעה, העמיד הקב״ה הדבר על ידיה. וזה הולך כמו שלמדנו, מוכנת היתה, בת שבע לדוד מששת ימי בראשית, להיות אמו של שלמה המלך. אף כאן, מוכנת היתה תמר לזה מיום שנברא העולם."],[8,"ותשב בפתח עינים:","שואל מה הוא פתח עינים. ומשיב הוא כש״א, והוא יושב פתח האהל. וכתוב ופסח ה׳ על הפתח. וכתוב, פתתו לי שערי צדק. \u0003עינים,\u0004 שכל עינים של העולם מצפים לפתח ההוא. אשר על דרך תמנתה. מהו תמנתה, הוא כמו שאתה אומר, ותמונת ה׳ יביט. וכך העמדנו תמר העמידה הדבר למטה ויצאו פרחים והניצו ענפים בסוד האמונה."]],[[0,"","וְעוֹד, שֶׁשְּׁאָר הָעַמִּים, כְּשֶׁהֵם בָּאִים לְמֵתֵיהֶם, הֵם בָּאִים עִם כְּשָׁפִים לְעוֹרֵר עֲלֵיהֶם מִינִים רָעִים. וּכְשֶׁיִּשְׂרָאֵל בָּאִים לְמֵתֵיהֶם, בָּאִים בְּכַמָּה תְשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, בְּשִׁבְרוֹן לֵב וּבְתַעֲנִית כְּנֶגְדּוֹ, וְהַכֹּל כְּדֵי שֶׁנִּשְׁמוֹת הַקְּדוֹשִׁים יְבַקְשׁוּ רַחֲמִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עֲלֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם בַּעֲבוּרָם."],[1,"","וְעַל זֶה שָׁנִינוּ, צַדִּיק, אַף עַל גַּב שֶׁנִּפְטָר מֵהָעוֹלָם הַזֶּה, לֹא מִסְתַּלֵּק וְלֹא נֶאֱבָד מִכָּל הָעוֹלָמוֹת, שֶׁהֲרֵי בְּכָל הָעוֹלָמוֹת הוּא נִמְצָא יוֹתֵר מִבְּחַיָּיו, שֶׁבְּחַיָּיו נִמְצָא בָּעוֹלָם הַזֶּה בִּלְבַדּוֹ, וְאַחַר כָּךְ נִמְצָא בִּשְׁלֹשָׁה עוֹלָמוֹת וּמְזֻמָּן אֲלֵיהֶם, שֶׁכָּתוּב (שיר א) עֲלָמוֹת אֲהֵבוּךְ, אַל תִּקְרֵי עֲלָמוֹת אֶלָּא עוֹלָמוֹת. אַשְׁרֵי חֶלְקָם."],[2,"","לָמַדְנוּ, כָּתוּב (שמואל א כה) וְהָיְתָה נֶפֶשׁ אֲדנִי צְרוּרָה בִּצְרוֹר הַחַיִּים. וְהָיְתָה נֶפֶשׁ אֲדנִי?! נִשְׁמַת אֲדנִי הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא כְּמוֹ שֶׁאָמַרְנוּ, שֶׁאַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַכֹּל נִקְשָׁר זֶה עִם זֶה, נֶפֶשׁ בְּרוּחַ, וְרוּחַ בִּנְשָׁמָה, וּנְשָׁמָה בַּקָּדוֹשׁ בָּרוּךְ הוּא. נִמְצָא שֶׁהַנֶּפֶשׁ צְרוּרָה בִּצְרוֹר הַחַיִּים."],[3,"","אָמַר רַבִּי אֶלְעָזָר, זֶה שֶׁאָמְרוּ הַחֲבֵרִים, גָּלוּתוֹ שֶׁל סֵפֶר תּוֹרָה אֲפִלּוּ מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת אַחֵר אָסוּר, וְכָל שֶׁכֵּן לָרְחוֹב. לָמָּה לָרְחוֹב? אָמַר רַבִּי יְהוּדָה, כְּמוֹ שֶׁאָמַרְנוּ, כְּדֵי שֶׁיִּתְעוֹרְרוּ עָלֵינוּ וִיבַקְשׁוּ רַחֲמִים עַל הָעוֹלָם. אָמַר רַבִּי אַבָּא, כְּשֶׁשְּׁכִינָה גָּלְתָה כָּךְ גַּם מִמָּקוֹם לְמָקוֹם, עַד שֶׁאָמְרָה (ירמיה ט) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים וְגוֹ', אַף כָּאן בָּרִאשׁוֹנָה מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת, אַחַר כָּךְ לָרְחוֹב, אַחַר כָּךְ בַּמִּדְבָּר מְלוֹן אוֹרְחִים. אָמַר רַבִּי יְהוּדָה, בְּנֵי בָּבֶל פּוֹחֲדִים וְלֹא מַעֲבִירִים אֲפִלּוּ מִבֵּית כְּנֶסֶת לְבֵית כְּנֶסֶת, כָּל שֶׁכֵּן זֶה."],[4,"","לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן לַחֲבֵרִים, בְּיָמַי לֹא יִצְטָרְכוּ בְּנֵי הָעוֹלָם אֶת זֶה. אָמַר לוֹ רַבִּי יוֹסֵי הַצַּדִּיקִים מְגִנִּים עַל הָעוֹלָם בְּחַיֵּיהֶם, וּבְמִיתָתָם יוֹתֵר מִבְּחַיֵּיהֶם. זֶהוּ שֶׁכָּתוּב (ישעיה לז) וְגַנּוֹתִי עַל הָעִיר הַזֹּאת לְהוֹשִׁיעָהּ לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי. וְאִלּוּ בְּחַיָּיו לֹא כָתוּב. אָמַר רַבִּי יְהוּדָה, מַה שּׁוֹנֶה כָּאן שֶׁכָּתוּב לְמַעֲנִי וּלְמַעַן דָּוִד עַבְדִּי, שֶׁשָּׁקוּל זֶה לָזֶה? אֶלָּא מִשּׁוּם שֶׁדָּוִד זָכָה לְהִקָּשֵׁר לַמֶּרְכָּבָה הַקְּדוֹשָׁה שֶׁל הָאָבוֹת, וּמִשּׁוּם כָּךְ הַכֹּל אֶחָד. בָּרוּךְ הוּא לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים."],[5,"","כְּמַעָשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ לֹא תַעֲשׂוּ. רַבִּי יִצְחָק פָּתַח, (תהלים קב) לְסַפֵּר בְּצִיּוֹן שֵׁם ה' וּתְהִלָּתוֹ בִּיְרוּשָׁלם. שָׁם שָׁנִינוּ, הַשֵּׁם הַקָּדוֹשׁ נִסְתָּר וְנִגְלֶה. וְהַתּוֹרָה, שֶׁהִיא הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן, נִסְתֶּרֶת וְנִגְלֵית. וְכָל פָּסוּק שֶׁבַּתּוֹרָה, וְכָל פָּרָשָׁה שֶׁל הַתּוֹרָה, נִסְתָּר וְנִגְלֶה."],[6,"","שֶׁלָּמַדְנוּ, אָמַר רַבִּי יְהוּדָה, מֵחֻצְפָּתָהּ שֶׁל צַדִּיקָה אַחַת יָצְאוּ כַּמָּה טוֹבוֹת לָעוֹלָם, וּמִי הִיא? תָּמָר, שֶׁכָּתוּב (בראשית לח) וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. אָמַר רַבִּי אַבָּא, פָּרָשָׁה זוֹ מוֹכִיחָה שֶׁהַתּוֹרָה נִסְתֶּרֶת וְנִגְלֵית. וַהֲרֵי הִסְתַּכַּלְתִּי בְּכָל הַתּוֹרָה וְלֹא מָצָאתִי מָקוֹם שֶׁנִּקְרָא פֶּתַח עֵינַיִם, אֶלָּא הַכֹּל נִסְתָּר, וְסוֹד הַסּוֹדוֹת הוּא."],[7,"","וְלָמַדְנוּ, מָה רָאֲתָה הַצַּדֶּקֶת הַזּוֹ לַמַּעֲשֶׂה הַזֶּה? אֶלָּא הִכִּירָה בְּבֵית חָמִיהָ אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵיךְ מַנְהִיג אֶת הָעוֹלָם עִם בְּנֵי הָאָדָם. וּמִשּׁוּם שֶׁהִיא הִכִּירָה, הַקָּדוֹשׁ בָּרוּךְ הוּא הֵקִים אֶת הַדָּבָר עַל יָדָהּ. וְזֶה הוֹלֵךְ כְּמוֹ שֶׁשָּׁנִינוּ, מְזֻמֶּנֶת הָיְתָה בַּת שֶׁבַע מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית לִהְיוֹת אִמּוֹ שֶׁל שְׁלֹמֹה הַמֶּלֶךְ. אַף כָּאן מְזֻמֶּנֶת הָיְתָה תָּמָר לְכָךְ מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם."],[8,"","וַתֵּשֶׁב בְּפֶתַח עֵינַיִם. מִי זֶה פֶּתַח עֵינַיִם? כְּמוֹ שֶׁנֶּאֱמַר, וְהוּא יֹשֵׁב פֶּתַח הָאֹהֶל. וְכָתוּב (שמות יב) וּפָסַח ה' עַל הַפֶּתַח. וְכָתוּב (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק וְגוֹ'. עֵינַיִם - שֶׁכָּל עֵינֵי הָעוֹלָם מְצַפִּים לַפֶּתַח הַזֶּה. אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה, מַה זֶּה תִּמְנָתָה? כְּמוֹ שֶׁנֶּאֱמַר (במדבר יב) וּתְמוּנַת ה' יַבִּיט. וְכָךְ בֵּאַרְנוּ, תָּמָר הֵקִימָה הַדָּבָר לְמַטָּה, וְהִפְרִיחָה פְרָחִים וְנִצְנְצָה עֲנָפִים בְּסוֹד הָאֱמוּנָה."]]],[["(הושע י״ב:א׳) וִיהוּדָה עוֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן. וַיִרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה וְגוֹ'. כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:כ׳) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. כִּי כִסְּתָה פָּנֶיהָ, וְאוֹקִימְנָא כִּי כִסְּתָה פָּנֶיהָ, כְּמָה דְאַתְּ אָמֵר, אָכְלָה וּמָחֲתָה פִיהָ, אוֹקִידַת עָלְמָא בְּשַׁלְהוֹבוֹי, וְאָמְרָה לֹא פָעַלְתִּי אָוְן. מַאי טַעְמָא. בְּגִין כִּי כִסְּתָה פָּנֶיהָ, וְלֵית מַאן דְּיֵדַע אוֹרְחָהָא, לְאִשְׁתְּזָבָא מִנָּהּ. וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ, אֶל הַדֶּרֶךְ מַמָּשׁ, לְאִתְחַבְּרָא חִוָּורָא בְּסוּמָקָא. וַיֹאמֶר הָבָה נָא אָבֹא אֵלַיִךְ וְגוֹ', הָא אוֹקִימְנָא הָבָה בְּכָל אֲתַר.","כִּי לֹא יָדַע כִּי כַלָּתוֹ הִיא. כִּי כַלָּתוֹ הִיא דְּעָלְמָא, מְתַרְגְּמִינָן אֲרִי שֵצַיְיתָא דְּעָלְמָא הִיא. מַאי טַעֲמָא לָא יָדַע. בְּגִין דְּהָא מְנַהֲרָן אַנְפָּהָא, לְקַבְּלָא מִנֵּיהּ, וְאִזְדַּמְּנָא לְאִתְבַּסְּמָא וּלְרַחֲמָא עָלְמָא (דבר אחר) כִּי כַלָּתוֹ הִיא, דָּא כַּלָּה מַמָּשׁ, דִּכְתִּיב, (שיר השירים ד׳:ח׳) אִתִּי מִלְּבָנוֹן כַּלָּה.","וַתֹּאמֶר מַה תִּתֵּן לִי כִּי תָּבֹא אֵלָי. הַשְׁתָּא כַּלָּה בַּעְיָא תַּכְשִׁיטָהָא. וַיֹאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. לְמַלְכָּא דְהַוָה לֵיהּ בְּרָא מֵאָמַהוּ חֲדָא, וְאָזִיל בְּהֵיכָלָא, בָּעָא מַלְכָּא לְאִתְנַסְּבָא בְּמַטְרוֹנִיתָא עִלָּאָה, וּלְאַעְלָאָה בְּהֵיכָלֵיהּ. אָמְרָה מַאן יָהִיב לֵיהּ בְּהֵיכָלֵיהּ דְּמַלְכָּא (נ\"א מאן יהיב ליה לדין בהיכליה דמלכא. אמר מלכא), אָמַר מִכָּאן וּלְהָלְאָה אַשְׁדַר וְאַתָּרִיךְ לִבְרָא דְּאָמַהוּ מֵהֵיכָלָא דִּילִי.","כַּךְ נָמֵי הָכָא, אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. וְהָא אוֹקִימְנָא, בְּלֹא תְבַשֵּׁל גְּדִי. וְכָל אִינּוּן בְּסִטְרָא דִּבְכוֹר בְּהֵמָה קָא אָתוּ. וְעַל דָּא לָא כְּתִיב אָנֹכִי אֶתֵּן, אֶלָּא אָנֹכִי אֲשַׁלַּח, אַתָּרִיךְ וְאַשְׁדָּר לֵיהּ, דְּלָא יִשְׁתְּכַּח בְּהֵיכָלִי.","וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךָ. אִלֵּין אִינּוּן סִימָנִין דְּמַטְרוֹנִיתָא, דְּאִתְבָּרְכָא מִן מַלְכָּא בְּזִוּוּגָהָא. וַיֹּאמֶר מַה הָעֵרָבוֹן אֲשֶׁר אֶתֵּן לָךְ, וַתֹּאמֶר חוֹתָמְךָ וּפְתִילֶךָ וּמַטְּךָ. אִלֵּין אִינּוּן (נ\"א סטרי) קִטְרֵי עִלָּאֵי, תַּכְשִׁיטָהָא דְּכַלָּה אִתְבָּרְכָא מִתְּלָתָא אִלֵּין, נֶצַח הוֹד יְסוֹד, וְכֹלָּא אִשְׁתְּכַח בִּתְלָתָא אִלֵּין וְכַלָה (ס\"א מנצח הוד יסוד) מֵהָכָא מִתְבָּרְכָא. מִיַּד וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ. וַיְּהִי כְּמִשְׁלֹשׁ חֳדָשִׁים. מַאן מִשְׁלֹשׁ חֳדָשִׁים. בָּתַר דִּיתַלְּתוּן יַרְחַיָּא, וְהָא ג' יַרְחִין אוֹקִימְנָא. וְהָכָא כְּמִשְׁלֹשׁ חֳדָשִׁים, דְּשָׁארִי יַרְחָא רְבִיעָאָה לְאִתְּעָרָא דִּינִין בְּעָלְמָא בְּחוֹבֵי בְּנֵי נָשָׁא, וְהִיא יַנְקָא מִסִּטְרָא אָחֳרָא. כְּדֵין, וַיּוּגַּד לִיהוּדָה לֵאמֹר זָנְתָה תָּמָר כַּלָּתֶךָ, הָא כַּלָּה בְּסִטְרָא אָחֳרָא אִשְׁתְּכַחַת. מַה כְּתִיב, הוֹצִיאוּהָ. כְּמָה דִּכְתִּיב, (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. וְתִשָּׂרֵף, בְּשַׁלְהוֹבֵי טִיהֲרָא בְּגָלוּתָא. מַה כְּתִיב, הִיא מוּצֵאת, לְאִתְמַשְּׁכָא בְּגָלוּתָא. וְהִיא שָׁלְחָה אֶל חָמִיהָ לֵאמֹר לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. לְאִישׁ אֲשֶׁר אֵלֶּה מִמֶּנוּ לָא כְּתִיב, אֶלָּא לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. דִּילֵיהּ סִימָנִין אִלֵּין מִשְׁתַּכְּחִין, אָנֹכִי הָרָה. מִיַּד וַיַּכֵּר יְהוּדָה וַיֹּאמֶר צָדְקָה מִמֶּנִּי. צָדְקָה וַדַּאי, וּשְׁמָא גָּרִים. מַאן גָּרִים לָהּ, שְׁמָא דָּא. הָדָר וְאָמַר מִמֶּנִּי, דִּכְתִּיב, (תהילים י״א:ז׳) כִּי צַדִּיק יְיָ' צְדָקוֹת אָהֵב יָשָׁר יֶחזוּ פָנֵימוֹ. צָדְקָה: צָדַק ה', דְּמִמֶּנִּי נַטְלַת שְׁמָא דָּא. מִמֶּנִּי יָרְתָא. מִמֶּנִּי אִשְׁתְּכַחַת.","אָמַר רִבִּי יוֹסֵי, מַאי טַעְמָא חָמִיהָ כְּתִיב בַּאֲתַר חַד, יְהוּדָה בַּאֲתַר אָחֳרָא. אָמַר לֵיהּ, כֹּלָּא אִתְקְטַר דָּא בְּדָא. חָמִיהָ, בַּאֲתַר עִלָּאָה תָּלֵי.","אָמַר רִבִּי אֶלְעָזָר, פַּרְשְׁתָּא דָּא אוֹקִימְנָא בְּרָזָא עִלָּאָה, בְּכַמָּה גַּוְונִין. כַּד יִסְתַּכְּלוּן מִלֵּי, מִינָּהּ יִשְׁתְּמַע רָזִין דְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְדִינוֹי בְּכָל אֲתַר. וְהִיא יַדְעַת וְאַקְדִּימַת גַּרְמָאָה לְמִלָּה דָּא, לְאַשְׁלְמָא אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּיִנְפְּקוּ מִינָּהּ מַלְכִין שַׁלִּיטִין, וּזְמִינִין לְשַׁלְּטָאָה עַל עָלְמָא. וְרוּת כְּהַאי גַּוְונָא עַבְדַת.","אָמַר רִבִּי אַבָּא, פַּרְשְׁתָּא דָּא בְּרָזָא דְּחָכְמְתָא דְּאוֹרַיְיתָא אִתְקַשְּׁרָא, וְכֹלָּא סָתִים וְגַלְיָא. וְאוֹרַיְיתָא כֹּלָּא כְּהַאי גַּוְונָא אִשְׁתְּכַחַת. וְלֵית לָךָ מִלָּה בְּאוֹרַיְיתָא, דְּלָא רָשִׁים בָּהּ שְׁמָא קַדִּישָׁא עִלָּאָה, דְּסָתִים וְגַלְיָא. בְּגִינֵי כַּךְ, סְתִימֵי דְּאוֹרַיְיתָא, קַדִּישֵׁי עֶלְיוֹנִין יָרְתִין לָהּ, וְאִתְגַּלְיָא בִּשְׁאָר בְּנֵי עָלְמָא. כְּגַוְונָא דָּא כְּתִיב, (תהילים ק״ב:כ״ב) לְסַפֵּר בְּצִיּוֹן שֵׁם יְיָ' וּתְהִלָּתוֹ בִּיְרוּשָׁלַ ם, דְּהָא בְּצִיּוֹן בְּמַקְדְּשָׁא, שָׁרֵי לְאַדְכְּרָא שְׁמָא קַדִּישָׁא כַּדְקָא חֲזֵי. וּלְבַר בְּכִינּוּיוֹ. וְעַל דָּא כֹּלָּא סָתִים וְגַלְיָא. תָּאנָא, כָּל מַאן דְּגָרַע אָת חַד מֵאוֹרַיְיתָא. אוֹ יוֹסִיף אָת חַד בְּאוֹרַיְיתָא, כְּמַאן דִּמְשַׁקֵּר בִּשְׁמָא קַדִּישָׁא עִלָּאָה דְּמַלְכָּא."],[[0,"ויהודה עוד רד עם אל וגו׳:","ויראה יהודה ויחשבה לזונה וגו'. היינו כש״א כן דרך אשה מנאפת. כי כסתה פניה. והעמדנו, כי כסתה פניה פירושו כמו שאתה אומר, אכלה ומחתה פיה. היא שורפת העולם בשלהבותיה, ואמרה לא פעלתי און. מהו הטעם. הוא משום שכסתה פניה, ואין מי שיודע דרכיה להנצל ממנה. \u0003ויט אליה אל הדרך,\u0004 אל הדרך ממש, לחבר לבן באדום. \u0003ויאמר הבה נא אבא אליך\u0004 וגו'. הרי העמדנו פירושו של \u0003הבה,\u0004 בכל מקום. שפירושו הזמנה (כנ״ל נח אות שמ״ב). הביאור של המאמר הוא בסוף המאמר."],[1,"כי לא ידע כי כלתו היא:","היינו כי כלתו היא של העולם, כמו שמתרגמינן, ארי שצייתא דעלמא היא, שפירושו שלא ידע שהיא מכלה את העולם, כי כלה, היא מלשון כליה. מהו הטעם שלא ידע. הוא משום שהיו מאירים פניה לקבל ממנו, ונזדמנה להתבשם ולרחם העולם. פירוש אחר, \u0003כי כלתו היא,\u0004 זו כלה ממש, שכתוב, אתי מלבנין כלה."],[2,"ותאמר מה תתן לי כי תבא אלי:","עתה צריכה הכלה תכשיטים. ויאמר אנכי אשלח גדי עזים מן הצאן. בדומה למלך שהיה לו בן משפחה אחת, והיה הולך בהיכל. רצה המלך להנשא במטרוניתא עליונה, ולהביאה בהיכלו. אמרה מי נתן לזה בהיכלו של המלך. אמר המלך מכאן ולהלאה אשלח ואגרש את בן האמה מן ההיכל שלי."],[3,"כך נמי הכא וכו׳:","אף כאן כך, אנכי אשלח גדי עזים מן הצאן. והרי העמדנו, מהו גדי, בלא תבשל גדי, שהוא הס״א היונקת ממלכות (כמ״ש לעיל משפטים אות תקס״ד) מטרם טהרתה. וכל אלו הם באים מצד בכור בהמה. וע״כ לא כתוב, אנכי אתן, אלא אנכי אשלח. דהיינו, אגרש ואשלח אותו שלא ימצא בהיכלי."],[4,"","[א] \u0003ותאמר אם תתן וגו׳:\u0004 ותאמר אם תתן ערבון עד שלחך. אלו הם הסימנים של המלכה שנתברכה מן המלך בזווגה. ויאמר מה הערבון אשר אתן לך ותאמר חותמך ופתילך ומטך. אלו הם קשרים העליונים תכשיטי הכלה המתברכת מן ג׳ אלו, שהם נצח, הוד, ויסוד. והכל נמצא בג' אלו, והכלה מתברכת מכאן. מיד ויתן לה ויבא אליה ותהר לו."],[4,"","[ב] \u0003ויהי כמשלש חדשים:\u0004 שואל, מהו משלש חדשים. ומשיב, אחר שישלשו החדשים. וג׳ חדשים, העמדנו, שהם חג״ת, וכאן כתוב כמשלש חדשים, פירושו, כשהתחיל חדש הרביעי, שהוא מלכות, לעורר דינים בעולם, מחמת עונות בני אדם, והיא יונקת מצד האחר. אז ויוגד ליהודה לאמר זנתה תמר כלתך, הרי הכלה בצד האחד נמצאת. מה כתוב, \u0003הוציאוה.\u0004 הוא כמ״ש השליך משמים ארץ תפארת ישראל. \u0003ותשרף,\u0004 בשלהבת אש בגלות."],[4,"","[ג] \u0003מה כתיב היא וגו':\u0004 מה כתוב, \u0003היא\u0004 מוצאת, להמשך בגלות. \u0003והיא שלחה אל חמיה לאמר לאיש אשר אלה לו אנכי הרה,\u0004 לאיש אשר אלה ממנו, לא כתוב, אלא לאיש אשר אלה לו, שפירושו, שסמנים אלו היו שלו אנכי הרה. שאלו היו תכשיטי כלה, וכבר נעשו שלה כנ״ל, אלא שהוא נתן אותם. מיד, ויכר יהודה ויאמר \u0003צדקה ממני.\u0004 צדקה ודאי, והשם גרם. שכך נקראת המלכות. מי גרם לה שם זה. חזר ואמר, \u0003ממני\u0004, שכתוב, כי צדיק ה׳ צדקות אהב ישר יחזו פנימו. כי צדקה היא צדק \u0003ה',\u0004 וממני קבלה שם הזה, וממני ירשה אותו וממני הוא נמצא."],[4,"","ביאור המאמר. כי ע״י מעשה זה של תמר ויהודה יצא שורש נשמת המשיח לעולם. והטעם הוא. כי תמר היתה מבחינת מלכות דמלכות שנק׳ מנעולא, ונודע שיש ערך הפכי בין כלים לאורות (כמ״ש לעיל בפתיחה לחכמת הקבלה אות כ״ד) וע״כ כשיושלם כלי מלכות דמלכות יושלם האור של יחידה דיחידה, שה״ס נשמת המשיח, המשלים את כל העולם. כי אין אור גדול ממנו בעולמות. אמנם מלכות דמלכות זו אינה ראויה לקבל שום אור, כי צמצום הא׳ רוכב עליה, וע״כ כל התקונים הנעשים במלכות דאצילות, מתחלתם ועד סופם באים לתקן המלכות דמלכות הזו, שתהיה ראויה לקבל בתוכה אורות התקון, אשר בסופם יביאו לגמר התקון, שיהיה נשלם האור של יחידה דיחידה. שה״ס המשיח. ולפיכך נתכוונה תמר במעשיה, להמשיך עקרי תקוני המלכות דאצילות: שתחלה צריכה לעלות המלכות לבינה, ששם נתקנה במדת הרחמים מהתכללותה בבינה, ונעשה לה בזה, ב׳ נקודות, א׳ משורשה עצמה הנשאר בה, שה״ס מנעולא. ב׳ מבחינת התכללותה בבינה, שה״ס מפתחא (כנ״ל בהקסה״ז דף מ״ה ד״ה ההיא) וז״ס ותשב בפתח עינים (שבאות ר״פ) ואח״כ צריכה לגניזת נקודה דמנעולא, ולתת שליטה לנקודה דמפתחא (כנ״ל בהקסה״ז דף קכ\"ד אות קכ״ג) וה״ס, כי כסתה פניה (שבאות רפ״א). ואח״כ צריכה לכלים דנה״י דז״א, שבתוכם מקבלת המוחין, שה״ס הערבון, חותמך פתילך ומטך (שבאות רפ״ה) ואחר כל אלו התקונים נעשית ראויה להולדת ראש נשמת המשיח, שה״ס פרץ."],[4,"","אמנם יש לשאול, מאין ידעה תמר כל דרכי התקונים האלו של המלכות, עד שיכלה לסדר מעשיה כדי להמשיכם בשורש נשמתה. וזה אמרו, (באות רע״ט) \u0003מאי חמאת\u0004 וכו' \u0003אלא ידעת בביתא דחמיה ארחו דקב״ה היך מדבר האי עלמא\u0004 וכו׳ כי אלו התקונים, איך הקב״ה מנהיג עולם הזה, שה״ס המלכות דאצילות, כדי להאיר לבני אדם, היתה תמר יודעת כל זה מבית חמיה, וע״כ ידעה לכוון מעשיה על פיהם. והנה תקון ראשון הוא עלית המלכות לבינה, כנ״ל. וז״ש, ותשב בפתח עינים, \u0003מאן פתח עינים, כד״א והוא יושב פתח האהל\u0004 וגו', אשר \u0003פתח\u0004 הוא מלכות. \u0003עינים, דכל עיינין דעלמא להאי פתחא מצפאן,\u0004 דהיינו עלית המלכות בבינה השב להיות חכמה, שאז נקראת הבינה \u0003עינים אשר על דרך תמנתה וכו׳ כד״א ותמונת ה׳ יביט.\u0004 המלכות כשמקבלת חכמה נקראת תמונת ה'. שזסו״ה פתח עינים, שהמלכות שנקראת פתח עלתה לבינה שנקראת, \u0003עינים אשר על דרך תמנתה\u0004 שמשפעת חכמה למלכות כשהיא נקראת תמונת ה'. וזהו להוציא חכמה ממש שנקראת עינים, שאינה בכלל זה, מפני שהיא אינה משפעת לתמונת ה׳, כי נגנזה, ורק הבינה שחזרה לחכמה, היא המשפעת לתמונת ה׳, וע״כ מגדירה הכתוב, עינים אשר על דרך תמנתה."],[4,"","אמנם אין מקרא יוצא מידי פשוטו, וכל אלו המעשים שעשתה תמר היו בגשמיות בענפים התחתונים, הרומזים על שרשיהם העליונים באצילות, ופתח עינים היה מקום שנקרא כך, ותמר ישבה שמה לעורר שורשו העליון המכוון כנגד המקום אשר נקרא, פתח עינים אשר על דרך תמנתה, כמו שבארנו כי ע״י אתערותא דלתתא מעוררים אתערותא דלעילא, וז״ש, \u0003והכי אוקימנא, תמר אוקימת מלה לתתא\u0004 שהיא עשתה הדברים למטה בעולם הגשמי, וכוונתה היתה לעורר שורש כל מעשה, למעלה במלכות דאצילות, \u0003ופרחת פרחין ואניצת ענפין ברזא דמהימנותא,\u0004 שיצאו התקונים למעלה במלכות הנקראת אמונה. וגם יהודה, היו נמשכות מחשבותיו, מז״א המתקן את המלכות. וז\"ש, ויהודה עוד רד עם אל ועם קדושים נאמן. שאע״פ שכתוב בפרשה, \u0003וירד יהודה,\u0004 שמשמע ש \u0003ירד\u0004 ממדרגותיו, עם כל זה, \u0003ועם קדושים נאמן,\u0004 שכל מחשבותיו היו נאמנות עם קדושים עליונים, דהיינו ז״א ומלכות. ושואל, הרי כתוב, \u0003ויראה יהודה ויחשבה לזונה.\u0004 איך נוהג זה בז״א למעלה. ומשיב, הוא, \u0003כמה דאת אמר, כן דרך אשה מנאפת.\u0004 כי בשעה שהמלכות עולה לבינה, והבינה קבלה הדינים דמלכות בתוכה, אז הקליפה, שנקראת זונה, שהיתה מקודם לכן נאחזת במלכות לבד, והט״ר היו נקיים לגמרי מאחיזת הקליפות, עתה אחר שבינה קבלה דיני המלכות, עלתה הקליפה ונאחזה במקום החסרון הנמשך מדיני הבינה. וז״ש כן דרך אשה מנאפת אכלה ומחתה פיה, שאותה הזונה שכל נאפופיה היו באחיזה ממלכות מבחינת המנעולא לבד ולא כלום בט״ר, שלא עליהם היה הצמצום, היא נבחנת כמו ש \u0003אכלה,\u0004 מבחינת המלכות בלבד, ואח״כ \u0003מחתה פיה ואמרה לא פעלתי און.\u0004 שהעלימה שאחיזתה היא במלכות ואמרה שלא פעלה שם און, ועלתה ונאחזה בחסרון הבינה. ואע״פ שבעת שנאחזה במלכות, \u0003אוקידת עלמא בשלהובוי,\u0004 ששרפה כל העולם בקטרוגה, ועם כל זה מחתה פיה, כמו שלא היתה נאחזת במלכות לעולם, ועלתה ונאחזה בחסרון הבינה, שנעשה מחמת עלית המלכות למקום בינה. וז״ש ויראה יהודה ויחשבה לזונה, שחשב כי מעשיה של תמר לשבת בפתח עינים, הוא, כמו אותה הזונה הנ״ל, אמנם ז״א למעלה לא אכפת לו בעליית הזונה להאחז במקום בינה, ואדרבה כל התקון נצמח מזה, שה״ס המוקש שמשימים לנחש (כנ\"ל וארא אות ק״ט ק״י ע״ש בסולם) הרי שהמחשבה של הזונה נמצאת ג״כ למעלה. וז״ש \u0003ואמרה לא פעלתי און, מ״ט, בגין כי כסתה פניה,\u0004 כי הזונה כסתה פניה האמיתים שהם ממנעולא, ואמרה לא פעלתי און. וענין כיסוי פניה זה, נמשך ג״כ מתקון שבמלכות, שנתתקנה, שהמנעולא תהיה גנוזה, ורק המפתחא הנמשכת מבינה, תהיה גלויה (כנ״ל בהקסה״ז דף קכ\"ד אות קכ״ג) אמנם תקון הגניזה שבקדושה היא קבועה. משא״כ הגניזה וכסוי פניה של הזונה, אינה בקביעות, אלא רק כדי לרמות בני אדם שיתדבקו בה, ואחר כך חוזרת ומגלה עליהם המנעולא וממיתם (כנ״ל ויצא דף י״ד ד״ה ביאור ע״ש) וז״ש, \u0003ולית מאן דידע אורחהא לאשתזבא מינה.\u0004 וע״כ כחה יפח לפתות בני אדם אחריה."],[4,"","וז״ש, \u0003כי לא ידע כי כלתו היא,\u0004 וכו', \u0003ארי שצייתא דעלמא היא,\u0004 כי מאחר שתמר כסתה פניה, שה״ס גניזת המנעולא, שממנה המיתה והכליה של העולם, לא ידע יהודה, כי יש בה בחינת המנעולא המכלה את העולם. וז״ש, \u0003מ״ט לא ידע, בגין דהא מנהרן אנפהא לקבלא מניה,\u0004 כי נמתקה בבינה אשר על ידיה, מאיר פניה לקבל ממנו. \u0003ואזדמנא לאתבסמא ולרחמא עלמא,\u0004 כי אחרי שנתבשמה בבינה היא במדת הרחמים לרחם העולם כמו הבינה. עוד כולל הכתוב, \u0003כי כלתו היא,\u0004 דא כלה ממש, כי תמר היתה אז מרכבה למלכות, שהיא כלתו של ז״א ממש. \u0003ותאמר מה תתן לי\u0004 וכו'. \u0003השתא כלה בעיא תכשיטהא,\u0004 דהיינו כלים, לקבל בהם ג״ר, הנקראים תכשיטין. \u0003ויאמר אנכי אשלח גדי עזים מן הצאן.\u0004 דהיינו השפעת החסדים והארת החכמה, מקו האמצעי המרחקת את הקליפות הנקראות בכור בהמה, והמכונה ג״כ גדי עזים."],[4,"","והנה גם אחר שנתמתקה המלכות בבינה, עוד אינה ראויה לקבל האורות בכלים שלה עצמה, אלא בכלים דנה״י דבינה, שהיא מקבלתם מז״א, שבתוכם מתלבשים אורותיה שמקבלת מבינה ומז״א. וז״ש, ותאמר אם תתן ערבון עד שלחך, \u0003אלין אינון סימנין דמטרוניתא דאתברכא מן מלכא בזווגהא,\u0004 כלומר, ששאלה ערבון ממנו, דהיינו סימנין, שתוכל לקבל ממלכא, שהוא ז״א, ברכת הזווג, דהיינו המאורות. כי ידעה שהכלים שלה עצמה אינם ראוים לקבל מן האורות של הזווג. וז״ש, \u0003ותאמר חותמך ופתילך ומטך, אלין אינון קטרי עלאי תכשיטהא דכלה,\u0004 דהיינו כנ״ל (בהקסה״ז דף כ') שאומר \u0003ואמא אוזיפת לברתא מאנהא,\u0004 דהיינו הכלים דנה״י שלה, שה״ס אתוון \u0003אל״ה, וקשיט לה בקישוטהא,\u0004 שעי״ז מקבלת אורות דג״ר דאמא הנקראים קישוטי כלה. (ע״ש בהסולם) כי נה״י אלו ה״ס בינה ותו״מ דבינה שנפלו לז״א ולמלכות, בעת קטנות, ואח\"כ לעת גדלות מחזרת הבינה, את ג׳ הכלים בינה ותו״מ שלה, שעמהם עולים גם ז״א ומלכות, והם מקבלים שם אורות דבינה. וע״כ נקראים בינה ותו״מ שבנה״י אלו, בשם, \u0003קטרי עלאי,\u0004 שהם מתקשרים בז״א ומלכות בעת קטנות ומעלים אותם לבינה בעת גדלות. ובעת שז״א ומלכות חוזרים ויורדים עם האורות דבינה למקומם, לוקחים עמהם בינה ותו״מ אלו שהעלו אותם לבינה, והם נעשו להם כלים להלבשת האורות. (כמ״ש שם באורך ע״ש כל ההמשך) ובינה ותו״מ אלו, מכונים נה״י, (כמ\"ש לעיל ויקהל אות ק״י ד\"ה וצריך ע״ש ובאות שכ״ד) וז״ש, \u0003אתברכא מתלתא אלין, נצח, הוד יסוד,\u0004 כי ג׳ כלים נה״י דבינה, הם שהעלו את המלכות לבינה והמלכות נתברכה מאורות דבינה, ע״י נה״י אלו. וכן מציאות האורות שקבלה המלכות, היא בשלשה אלו, שהם נה״י דבינה. וז״ש, \u0003וכלא אשתכח בתלתא אלין,\u0004 שכל האורות נמצאים מלובשים בג' כלים נה״י אלו. מיד, ויתן לה, ויבא אליה ותהר לו."],[4,"","וכבר ידעת שהאורות הם חג״ת ומלכות, שה״ס ג׳ קוין, ומלכות המקבלת ג׳ הקוין, שהם מכונים ארבעה חדשים. וע״כ כיון שתמר היתה משורשה מבחינת מלכות דמלכות, קשה היה המיתוק שלה בבינה, ולפיכך כל עוד שקבלה בחינות ג׳ חדשים שהם חג״ת, לא נתעוררו בה הדינים דמנעולא, אלא כיון שהגיעה לחדש הרביעי, שהוא בחינת המלכות עצמה, אז חזרה ונתעוררה בה המלכות דמדת הדין, שהיא מנעולא, שכל האורות מסתלקים בעת הגילוי שלה (כנ\"ל ויצא דף י״ג ד\"ה סתרא) וז״ש, \u0003והא ג׳ ירחין אוקימנא,\u0004 דהיינו שהם ג׳ קוין חג״ת, \u0003והכא כמשלש חדשים,\u0004 שפירושו אחר שלשה חדשים, \u0003דשארי ירחא רביעאה לאתערא דינין בעלמא בחובי בני נשא,\u0004 שחדש הרביעי, שהוא המלכות דאצילות למעלה, מעוררת הדינים דמנעולא שבתוכה, אם בני אדם חוטאים למטה, ואז \u0003והיא יונקת מסטרא אחרא,\u0004 דהיינו שהאורות מסתלקים בסבת הגילוי, והסטרא אחרא נאחזת ויונקת ממנו, כדין ויוגד ליהודה לאמור זנתה תמר כלתך, שפירושו, \u0003הא כלה בסטרא אחרא אשתכחת,\u0004 דהיינו שנתגלה בה המנעולא, והס״א נאחז בה. \u0003מה כתיב הוציאוה,\u0004 דהיינו בדומה למלכות שנאמר בה השליך משמים ארץ תפארת ישראל. \u0003ותשרף בשלהובי טיהרא בגלותא,\u0004 שדיני הגלות ישרפוה, \u0003מה כתיב, היא מוצאת והיא שלחה\u0004 וגו' \u0003לאיש אשר אלה ממנו, לא כתיב, אלא, לאיש אשר אלה לו. דיליה סמנין אלין משתכחין.\u0004 כלומר שטענה, כי האורות אינם מקובלים בכלים שלה, אלא בכלים שלו של ז״א שה״ס נה״י דבינה שז״א ומלכות קבלו ממנה, אשר דינים דמנעולא לא יוכלו לשלוט בהם כנ״ל. וז\"ש, \u0003מיד ויכר יהודה ויאמר צדקה ממני\u0004 וגו' \u0003צדק ה׳,\u0004 שבעת שמקבלת האורות הגדולים מלובשים בנה״י דז״א ודבינה, היא נקראת צדקה, שהוא אותיות צדק ה׳, שאז הן האורות והן הכלים היא מקבלת \u0003מז״א\u0004, וז\"ש \u0003דממני נטלת שמא דא.\u0004 וע״ז בא הרמז, \u0003צדקה ממני\u0004."],[5,"א״ר יוסי וכו׳:","מה הטעם שחמיה, כתוב במקום אחד, ויהודה, במקום אחר. אמר לו הכל נקשר זה בזה. \u0003חמיה,\u0004 תלוי במקום עליון."],[5,"","פירוש. \u0003חמיה,\u0004 רומז על אבי בעלה של המלכות, שהוא חכמה, כי חכמה הוא אבא דז״א. ויהודה רומז כאן על ז״א, כי השם הויה שהוא ז״א, נמצא בשם יהודה. ומקשה, למה כתוב פעם חמיה ופעם יהודה, הלא ב׳ מדרגות הן. ומשיב, שהמה קשורים זה בזה, כלומר שרומז על ז״א בעת שהוא מקושר ומלביש את החכמה. וז״ש, \u0003חמיה, תלוי במקום עליון,\u0004 שהוא חכמה."],[6,"א״ר אלעזר וכו׳:","אר״א פרשה זו העמדנו בסוד עליון בכמה אופנים. כשמסתכלים בדברים נשמעים ממנה הסודות של דרכי ה', ודיניו שבכל מקום, דהיינו כמו שבארנו לעיל, והיא, תמר ידעה כל זה, והקדימה עצמה לדבר זה, להשלים דרכי הקב״ה, כדי שיצאו ממנו מלכים ושליטים העתידים לשלוט על העולם. וגם רות עשתה באפן זה. כי גם רות היתה מעוררת את בועז ליבום, כמו תמר."],[7,"א״ר אבא וכו׳:","אר״א פרשה זו בסוד חכמת התורה נקשרה, והכל סתום וגלוי, דהיינו שיש בה סוד ויש בה פשט. וכל התורה נמצאת כעין זה, בסוד ובפשט. ואין לך דבר בתורה שלא רשום בו השם הקדוש העליון שהוא סתום ומגולה. משום, שהנסתרות שבתורה, יורשים אותם קדושים העליונים, והנגלות שבה, מתגלים לשאר בני העולם. כעין זה כתוב, לספר בציון שם הוי״ה ותהלתו בירושלים. שפירושו, בציון, בבית המקדש, מותר להזכיר את השם הקדוש הוי״ה כראוי, ולחוץ מבית המקדש, רק בכינוי שלו, דהיינו אדני, ולא בכתיבתו. וע״כ הכל הוא סתום וגלוי. כי שם הויה, שאסור להזכירו הוא סתום, והשם אדני, שאנו מזכירים, הוא גלוי. ועד״ז כל הדברים. למדנו, כל מי שגורע אות אחת מן התורה, או מוסיף אות אחת בתורה הוא כמו שמשקר בשם הקדוש העליון של המלך."]],[[0,"","וִיהוֹדָה עֹד רָד עִם אֵל וְעִם קְדוֹשִׁים נֶאֱמָן (הושע יב). וַיִּרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה וְגוֹ'. כְּמוֹ שֶׁנֶּאֱמַר (משלי ל) כֵּן דֶּרֶךְ אִשָּׁה מְנָאָפֶת. כִּי כִסְּתָה פָּנֶיהָ, וּבֵאַרְנוּ כִּי כִסְּתָה פָּנֶיהָ, כְּמוֹ שֶׁנֶּאֱמַר אָכְלָה וּמָחֲתָה פִיהָ, שָׂרְפָה אֶת הָעוֹלָם בְּשַׁלְהֲבוֹתֶיהָ, וְאָמְרָה לֹא פָעַלְתִּי אָוֶן. מָה הַטַּעַם? מִשּׁוּם כִּי כִסְּתָה פָּנֶיהָ, וְאֵין מִי שֶׁיּוֹדֵעַ דְּרָכֶיהָ לְהִנָּצֵל מִמֶּנָּה. וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ, אֶל הַדֶּרֶךְ מַמָּשׁ, לְחַבֵּר לָבָן בְּאָדם. וַיֹּאמֶר הָבָה נָּא אָבוֹא אֵלַיִךְ וְגוֹ', הֲרֵי בֵּאַרְנוּ הָבָה בְּכָל מָקוֹם."],[1,"","כִּי לֹא יָדַע כִּי כַלָּתוֹ הִיא. כִּי כַלָּתוֹ הִיא שֶׁל הָעוֹלָם, מְתַרְגְּמִים: אֲשֶׁר הַשְׁמָדַת הָעוֹלָם הִיא. מָה הַטַּעַם לֹא יָדַע? מִשּׁוּם שֶׁהֵאִירוּ פָנֶיהָ לְקַבֵּל מִמֶּנּוּ, וְהִזְדַּמְּנָה לְבַשֵּׂם וּלְרַחֵם עַל הָעוֹלָם. כִּי כַלָּתוֹ הִיא - זוֹ כַּלָּה מַמָּשׁ, שֶׁכָּתוּב (שיר ד) אִתִּי מִלְּבָנוֹן כַּלָּה."],[2,"","וַתֹּאמֶר מַה תִּתֶּן לִי כִּי תָבוֹא אֵלָי. עַכְשָׁו הַכַּלָּה צְרִיכָה תַכְשִׁיטֶיהָ. וַיּאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצּאן. לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן מִשִּׁפְחָה אַחַת שֶׁהָלַךְ בַּהֵיכָל, רָצָה הַמֶּלֶךְ לָשֵׂאת גְּבִירָה עֶלְיוֹנָה וּלְהַכְנִיסָהּ לְהֵיכָלוֹ. אָמְרָה: מִי נָתַן אֶת זֶה בְּתוֹךְ הֵיכַל הַמֶּלֶךְ? (מי נתן את זה בהיכל המלך אמר המלך:) אָמַר: מִכָּאן וָהָלְאָה אֲשַׁלַּח וַאֲגָרֵשׁ אֶת בֶּן הַשִּׁפְחָה מֵהֵיכָלִי."],[3,"","כָּךָ גַּם כָּאן, אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן. וַהֲרֵי בֵּאַרְנוּ בְּלֹא תְבַשֵּׁל גְּדִי. וְכָל אוֹתָם שֶׁמִּצַּד בְּכוֹר הַבְּהֵמָה הֵם בָּאוּ. וְעַל כֵּן לֹא כָתוּב אָנֹכִי אֶתֵּן, אֶלָּא אָנֹכִי אֲשַׁלַּח, אֲגָרֵשׁ וַאֲשַׁלַּח אוֹתוֹ שֶׁלֹּא יִמָּצֵא בְהֵיכָלִי."],[4,"","וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךְ. אֵלּוּ הֵם סִימָנֵי הַגְּבִירָה שֶׁהִתְבָּרְכָה מֵהַמֶּלֶךְ בְּזִוּוּגָהּ. וַיֹּאמֶר מָה הָעֵרָבוֹן אֲשֶׁר אֶתֶּן לָךְ, וַתֹּאמֶר חֹתָמְךְ וּפְתִילֶךְ וּמַטְּךְ. אֵלּוּ הֵם (צדדי) הַקְּשָׁרִים הָעֶלְיוֹנִים, תַּכְשִׁיטֶיהָ שֶׁל הַכַּלָּה מִתְבָּרְכִים מִשְּׁלֹשֶׁת אֵלֶּה, נֵצַח הוֹד יְסוֹד, וְהַכֹּל נִמְצָא בִּשְׁלֹשֶׁת אֵלֶּה, וְהַכַּלָּה (מנצח הוד יסוד) מִתְבָּרֶכֶת מִכָּאן. מִיָּד - וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ. וַיְהִי כְּמִשְׁלֹשׁ חֳדָשִׁים. מַה זֶּה מִשְׁלֹשׁ חֳדָשִׁים? אַחַר שֶׁיְּשַׁלְּשׁוּ הֶחֳדָשִׁים, וַהֲרֵי שְׁלֹשָׁה חֳדָשִׁים בֵּאַרְנוּ. וְכָאן כְּמִשְׁלֹשׁ חֳדָשִׁים, שֶׁהִתְחִיל הַחֹדֶשׁ הָרְבִיעִי לְעוֹרֵר דִּינִים בָּעוֹלָם מֵחֲטָאֵי בְּנֵי אָדָם, וְהִיא יוֹנֶקֶת מִצַּד הָאַחֵר. אָז - וַיֵּגּד לִיהוּדָה לֵאמֹר זָנְתָה תָּמָר כַּלָּתֶךְ. הֲרֵי כַּלָּה בַּצַּד הָאַחֵר נִמְצֵאת. מַה כָּתוּב? הוֹצִיאוּהָ, כְּמוֹ שֶׁכָּתוּב, (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ תִּפְאֶרֶת יִשְׂרָאֵל. וְתִשָּׂרֵף, בְּשַׁלְהֶבֶת הַצָּהֳרַיִם בַּגָּלוּת. מַה כָּתוּב? הִיא מוּצֵאת, לְהִמָּשֵׁךְ, לַגָּלוּת. וְהִיא שָׁלְחָה אֶל חָמִיהָ לֵאמֹר לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. לֹא כָתוּב לְאִישׁ אֲשֶׁר אֵלֶּה מִמֶּנּוּ, אֶלָּא לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ. שֶׁלּוֹ הַסִּימָנִים הַלָּלוּ הַמְּצוּיִים, אָנֹכִי הָרָה. מִיָּד - וַיַּכֵּר יְהוּדָה וַיּאמֶר צָדְקָה מִמֶּנִּי. צָדְקָה וַדַּאי, וְהַשֵּׁם גּוֹרֵם. מַה גָּרַם לָהּ? הַשֵּׁם הַזֶּה. חָזַר וְאָמַר, מִמֶּנִּי, שֶׁכָּתוּבּ כִּי צַדִּיק ה' צְדָקוֹת אָהֵב יָשָׁר יֶחֱזוּ פָנֵימוֹ. צָדְקָה - צָדַק ה', שֶׁמִּמֶּנִּי נָטְלָה אֶת הַשֵּׁם הַזֶּה. מִמֶּנִּי יָרְשָׁה, מִמֶּנִּי נִמְצֵאת."],[5,"","אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם כָּתוּב חָמִיהָ בְּמָקוֹם אֶחָד, וִיהוּדָה בְּמָקוֹם אַחֵר? אָמַר לוֹ, הַכֹּל נִקְשָׁר זֶה עִם זֶה. חָמִיהָ תָּלוּי בְּמָקוֹם עֶלְיוֹן."],[6,"","אָמַר רַבִּי אֶלְעָזָר, הַפָּרָשָׁה הַזּוֹ בֵּאַרְנוּ בְּסוֹד עֶלְיוֹן בְּכַמָּה גְוָנִים. כְּשֶׁיִּתְבּוֹנְנוּ בַדְּבָרִים, מִמֶּנָּה יִשָּׁמְעוּ הַסּוֹדוֹת שֶׁל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְדִינָיו בְּכָל מָקוֹם. וְהִיא יָדְעָה וְהִקְדִּימָה עַצְמָהּ לַדָּבָר הַזֶּה, לְהַשְׁלִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁיֵּצְאוּ מִמֶּנָּה מְלָכִים שַׁלִּיטִים, שֶׁעֲתִידִים לִשְׁלֹט עַל הָעוֹלָם. וְרוּת עָשְׂתָה כְּגוֹן זֶה."],[7,"","אָמַר רַבִּי אַבָּא, פָּרָשָׁה זוֹ נִקְשְׁרָה בְּסוֹד חָכְמַת הָתּוֹרָה, וְהַכֹּל נִסְתָּר וְנִגְלֶה. וְכָל הַתּוֹרָה מְצוּיָה כְּגוֹן זֶה, וְאֵין לְךְ דָּבָר בַּתּוֹרָה שֶׁלֹּא רָשׁוּם בּוֹ הַשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁנִּסְתָּר וְנִגְלֶה. מִשּׁוּם כָּךְ הַנִּסְתָּרוֹת שֶׁבַּתּוֹרָה, קְדוֹשִׁים עֶלְיוֹנִים יוֹרְשִׁים אוֹתָם, וְנִגְלֵית לִשְׁאָר בְּנֵי הָעוֹלָם. כְּמוֹ כֵן כָּתוּב, (תהלים קב) לְסַפֵּר בְּצִיּוֹן שֵׁם ה' וּתְהִלָּתוֹ בִּירוּשָׁלם. שֶׁהֲרֵי בְּצִיּוֹן בַּמִּקְדָּשׁ מֻתָּר לְהַזְכִּיר אֶת הַשֵּׁם הַקָּדוֹשׁ כָּרָאוּי, וּבַחוּץ בְּכִנּוּיוֹ. וְלָכֵן הַכֹּל נִסְתָּר וְנִגְלֶה. לָמַדְנוּ, כָּל מִי שֶׁגּוֹרֵעַ אוֹת אַחַת מֵהַתּוֹרָה אוֹ מוֹסִיף אוֹת אַחַת לַתּוֹרָה, כְּמִי שֶׁמְּשַׁקֵּר בַּשֵּׁם הַקָּדוֹשׁ הָעֶלְיוֹן שֶׁל הַמֶּלֶךְ."]]],[["אָמַר רִבִּי יִצְחָק, עוֹבָדָא דְּמִצְרַיִם פַּלְחִין לְשִׁפְחָה, כְּמָה דְּאוֹקִימְנָא. עוֹבָדָא דִּכְנַעַן, פַּלְחִין לְהַהוּא דְּאִקְרֵי (שמות י״ב:כ״ט) שְׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. וְעַל דָּא כְּתִיב, (בראשית ט׳:כ״ה) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. בְּגִין כָּךְ כֻּלְּהוּ מַכְתִיבִין (ס\"א מברכין) (ס\"א מכדבין) בְּמִלִּין קַדִּישִׁין, וְעַבְדִין עוֹבָדִין (ס\"א עריין) בְּכֹלָּא. בְּגִינֵי כַּךְ כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ וְגוֹ'. רִבִּי יְהוּדָה אָמַר, דְּעַבְדִּין דִּינִין (ס\"א זינין) בִּישִׁין לְשַׁלְטָא עַל (נ\"א לסאבא) אַרְעָא, כְּמָה דְאַתְּ אָמֵר וְלֹא תְּטַמֵּא אֶת אַדְמָתְךָ. וּכְתִיב וַתִּטְמָא הָאָרֶץ.","(ויקרא י״ח:ג׳) כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם וְגוֹ', רִבִּי חִיָּיא פָּתַח, (איוב ל״ח:י״ג) לֶאֱחוֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ', תָּאנָא, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְדַכְּאָה לְאַרְעֵיהּ, מִכָּל מְסַאֲבוּתָא דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, דְּסָאִיבוּ לָהּ. כְּהַאי מַאן דְּאָחִיד בְּטָלִיתֵיהּ, וְאַנְעַר טִנּוּפָא מִנֵּיהּ. וְכָל אִינּוּן דְּאִתְקְבָרוּ בְּאַרְעָא קַדִּישָׁא, לְמִשְׁדֵּי לוֹן לְבַר, וּלְדַכְּאָה אַרְעָא קַדִּישָׁא מִסִּטְרָא אָחֳרָא (ס\"א קדישא אחרא), כִּבְיָכוֹל דְּהֲוָה מַתְּזָנָא לִשְׁאָר רַבְרְבֵי עַמִּין, וּלְקַבְּלָא מְסַאֲבוּתָא דִּלְהוֹן, וּלְדַבְּרָא לוֹן. וְזַמִּין לְדַכְּאָה לָהּ וּלְאַעְבְּרָא לוֹן לְבַר.","רִבִּי שִׁמְעוֹן הֲוָה מַדְכֵּי טוּרֵי (ס\"א שוקי) דִּטְבֶרְיָא, וְכָל דְּהֲוָה תַּמָּן מִית, הֲוָה סָלִיק לֵיהּ, וּמְדַכֵּי אַרְעָא. תָּאנָא, כְּתִיב (ירמיהו ב׳:ז׳) וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְגוֹ', אָמַר רִבִּי יְהוּדָה, זַכָּאָה חוּלָקֵיהּ מַאן דְּזָכֵי בְּחַיּיוֹי לְמִשְׁרֵי מָדוֹרָא בְּאַרְעָא קַדִּישָׁא. דְּכָל מַאן דְּזָכֵי לָהּ, זָכֵי לְאַנְגְּדָא מִטַּלָּא דִּשְׁמַיָּא דִּלְעֵילָּא, דְּנָחִית עַל אַרְעָא. וְכָל מַאן דְּזָכֵי לְאִתְקַשְּׁרָא בְּחַיּיוֹי בְּהַאי אַרְעָא קַדִּישָׁא, זָכֵי לְאִתְקַשְּׁרָא לְבָתַר בְּאַרְעָא קַדִּישָׁא עִלָּאָה.","וְכָל מַאן דְּלָא זָכֵי בְּחַיּוֹי, וּמַיְיתִין לֵיהּ לְאִתְקַבְּרָא תַּמָּן, עָלֵיהּ כְּתִיב, (ירמיהו ב׳:ז׳) וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. רוּחֵיהּ נָפִיק בִּרְשׁוּתָא נוּכְרָאָה אָחֳרָא, וְגוּפֵיהּ אָתֵי תְּחוֹת רְשׁוּתָא דְּאַרְעָא קַדִּישָׁא, כִּבְיָכוֹל עָבִיד קֹדֶשׁ חוֹל, וְחוֹל קֹדֶשׁ. וְכָל מַאן דְּזָכֵי לְמֵיפַּק נִשְׁמָתֵיהּ בְּאַרְעָא קַדִּישָׁא, אִתְכְּפָּרוּ חוֹבוֹי, וְזָכֵי לְאִתְקַשְּׁרָא תְּחוֹת גַּדְפּוֹי דִּשְׁכִינְתָּא, דִּכְתִּיב, (דברים ל״ב:מ״ג) וְכִפֶּר אַדְמָתוֹ עַמּוֹ. וְלֹא עוֹד אֶלָּא אִי זָכֵי בְּחַיּיוֹי, זָכֵי לְאִתְמַשְּׁכָא עָלֵיהּ רוּחָא קַדִּישָׁא תָּדִיר, וְכָל מַאן דְּיָתִיב בִּרְשׁוּתָא אָחֳרָא, אִתְמְשַׁךְ עָלֵיהּ רוּחָא אָחֳרָא נוּכְרָאָה.","תָּאנָא, כַּד סָלִיק רַב הַמְנוּנָא סָבָא לְהָתָם, הֲווֹ עִמֵּיהּ תְּרֵיסָר בְּנֵי מְתִיבְתָּא דִּילֵיהּ, אָמַר לוֹן, אִי אֲנָא אָזִיל לְאָרְחָא דָּא, לָאו עַל דִּידִי קָא עֲבִידְנָא, אֶלָּא לְאָתָבָא פִּקְדוֹנָא לְמָארֵיהּ. תָּנֵינָן כָּל אִינּוּן דְּלָא זָכוּ לְהַאי בְּחַיּיוֹי, אָתִיבִין פִּקְדוֹנָא דְּמָארֵיהוֹן לְאָחֳרָא.","אָמַר רִבִּי יִצְחָק, בְּגִינֵי כַּךְ, כָּל מַאן דְּאַעְבָּר מֵאִינּוּן זִינִין בִּישִׁין, אוֹ רְשׁוּתָא אָחֳרָא בְּאַרְעָא, אַרְעָא אִסְתְּאָבַת, וַוי לֵיהּ לְהַהוּא גְּבַר, וַוי לְנַפְשֵׁיהּ, דְּהָא אַרְעָא קַדִּישָׁא לָא מְקַבְּלָא לֵיהּ לְבָתַר. עָלֵיהּ כְּתִיב, (תהילים ק״ד:ל״ה) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ, בָּעוֹלָם הַזֶּה, וּבָעוֹלָם הַבָּא, וּרְשָׁעִים עוֹד אֵינָם, בִּתְחִיַּית הַמֵּתִים, כְּדֵין בָּרַכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ.","(ויקרא י״ח:ד׳) אֶת מִשְׁפָּטַי תַּעֲשׂוּ וְאֶת חֻקֹּתַי תִּשְׁמְרוּ לָלֶכֶת בָּהֶם וְגוֹ', רִבִּי אַבָּא אָמַר, זַכָּאָה חוּלָקָא דְּיִשְׂרָאֵל, דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ מִכָּל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה, וּבְגִין רְחִימוּתָא דִּילֵיהּ עָלַיְיהוּ, יָהִיב לוֹן נִימוּסִין דִּקְשׁוֹט, נָטַע בְּהוּ אִילָנָא דְּחַיֵּי, אַשְׁרֵי שְׁכִינְתָּא בֵּינַיְיהוּ. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל רְשִׁימִין בִּרְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵיהוֹן. וְאִשְׁתְּמוֹדְעָן דְּאִינְהוּ דִּילֵיהּ, (אשתמודען) מִבְּנֵי הֵיכָלֵיהּ."],[[0,"א״ר יצחק וכו׳:","אר״י, מעשה מצרים הוא, שהיו עובדים לשפחה. דהיינו הקליפה שנקראת שפחה, כמו שהעמדנו. מעשה כנען הוא, שהיו עובדים למקום ההוא שנקרא, שבי אשר בבית הבור. וע״כ כתוב, ארור כנען עבד עבדים יהיה לאחיו. משום זה היו כולם משקרים בדברים קדושים, ועשו מעשים של עבודה זרה, בכל. משום זה כתוב, כמעשה ארץ מצרים אשר ישבתם בה וגו'. ר׳ יהודה אמר שעשו דינים רעים לשלוט על הארץ, שהיא המלכות. כש״א ולא תטמא את אדמתך. וכתוב, ותטמא הארץ."],[1,"כמעשה ארץ מצרים וגו׳:","ר׳ חייא פתח, לאחוז בכנפי הארץ וינערו רשעים ממנה. למדנו, עתיד הקב״ה לטהר את ארצו, שהיא המלכות, מכל טומאות העמים עכו״ם שטמאו אותה, כמי שאוחז בבגדו ומנער את הטנופת ממנו, שהם כל הרשעים שנקברו בארץ הקדושה כך הוא מנער הארץ כדי להשליך אותם לחוץ, וכדי לטהר הארץ הקדושה, שהיא המלכות, מסטרא אחרא. שכביכול, שהיתה מזינה שאר שרי העמים, שקבלה טומאה מהם להנהיגם ועתיד לטהר אותה ולהעביר שרי העמים לחוץ."],[2,"ר״ש הוה מדכי שוקי וכו׳:","ר״ש היה מטהר שוקר טבריא, וכל מת שהיה שם היה מעלה אותו ומטהר הארץ. למדנו, כתוב, ותבאו ותטמאו את ארצי וגו'. א\"ר יהודה, אשרי חלקו, מי שזכה בחייו לעשות משכנו בארץ הקדושה, שכל מי שזכה לה זוכה להמשיך מטל השמים שלמעלה היורד על הארץ. וכל מי שזכה להתקשר בחייו בארץ הקדושה הזו, זוכה להתקשר אח״כ בארץ הקדושה העליונה, שהיא המלכות."],[3,"וכל מאן דלא וכו׳:","וכל מי שלא זכה בחייו, בארץ הקדושה, ומביאים אותו להקבר שמה, עליו כתוב, ונחלתי שמתם לתועבה. רוחו יצא ברשות אחר זר, וגופו בא תחת רשות ארץ הקדושה, כביכול, עשה קדש חול וחול קודש. וכל מי שזכה שתצא נשמתו בארץ הקדושה מתכפרים עונותיו, וזוכה, להתקשר תחת כנפי השכינה. שכתוב, וכפר אדמתו עמו. ולא עוד, אלא אם זכה בחייו, בארץ הקדושה, זוכה שיהיה נמשך עליו תמיד רוח הקודש. וכל מי שיושב ברשות אחרת, דהיינו בחוץ לארץ, נמשך עליו רוח אחר זר."],[4,"תאנא כד סליק וכו׳:","למדנו, כשעלה רב המנונא סבא שמה, לארץ הקדושה, היו עמו שנים עשר בני ישיבה שלו. אמר להם אם אני הולך לדרך הזה, לא בשבילי אני עושה, אלא כדי להשיב הפקדת לבעליו. למדנו, כל אלו שלא זכו לזה, לארץ הקדושה, בחייהם, משיבים הפקדון של אדונם, דהיינו הנשמה שנתנה בהם, לאחר, לסטרא אחרא."],[5,"אמר ר׳ יצחק וכו׳:","אר״י, בשביל זה, כל מי שמכניס מאלו מינים הרעים, או רשות אחרת, בארץ. נטמאת הארץ. או לו לאותו איש, או לנפשו, כי הארץ הקדושה אינה מקבלתו אח״כ, עליו כתוב, \u0003יתמו חטאים מן הארץ,\u0004 בעולם הזה ובעולם הבא, \u0003ורשעים עוד אינם.\u0004 בתחיית המתים, אז, ברכי נפשי את ה׳ הללויה."],[6,"את משפטי תעשו וגו׳:","ר׳ אבא אמר, אשרי חלקם של ישראל, שהקב״ה רצה בהם מכל העמים עכו\"ם, ומתוך אהבתו עליהם נתן להם חוקי אמת, נטע בהם עץ החיים, שהוא ז״א, והשרה השכינה ביניהם. מהו הטעם. הוא משום שישראל רשומים ברושם קדוש בבשר שלהם, וניכרים שהם שלו, מבני היכלו."]],[[0,"","אָמַר רַבִּי יִצְחָק, מַעֲשֶׂה שֶׁל מִצְרַיִם שֶׁעוֹבְדִים לְשִׁפְחָה, כְּמוֹ שֶׁבֵּאַרְנוּ. מַעֲשֶׂה שֶׁל כְּנַעַן שֶׁעוֹבְדִים לְאוֹתוֹ שֶׁנִּקְרָא (שמות יב) שְׁבִי אֲשֶׁר בְּבֵית הַבּוֹר. וְעַל זֶה כָּתוּב, (בראשית ט) אָרוּר כְּנָעַן עֶבֶד עֲבָדִים יִהְיֶה לְאֶחָיו. מִשּׁוּם כָּךְ כֻּלָּם מַכְתִּיבִים (מברכים) (מכזבים) בִּדְבָרִים קְדוֹשִׁים, וְעוֹשִׂים מַעֲשִׂים (עריות) בַּכֹּל. מִשּׁוּם כָּךְ, כְּמַעֲשֵׂה אֶרֶץ מִצְרַיִם אֲשֶׁר יְשַׁבְתֶּם בָּהּ וְגוֹ'. רַבִּי יְהוּדָה אָמַר, שֶׁעוֹשִׂים דִּינִים (מינים) רָעִים לִשְׁלֹט (לטמא) עַל הָאָרֶץ, כְּמוֹ שֶׁנֶּאֱמַר וְלֹא תְטַמֵּא אֶת אַדְמָתְךְ. וְכָתוּב וַתִּטְמָא הָאָרֶץ."],[1,"","כְּמַעָשֵׂה אֶרֶץ מִצְרַיִם וְגוֹ'. רַבִּי חִיָּיא פָּתַח, (איוב לח) לֶאֱחֹז בְּכַנְפוֹת הָאָרֶץ וְגוֹ'. לָמַדְנוּ, עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְטַהֵר אֶת אַרְצוֹ מִכָּל טֻמְאַת הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁטִּמְּאוּ אוֹתָהּ, כְּמִי שֶׁאוֹחֵז בְּטַלִּיתוֹ וּמְנַעֵר אֶת הַטִּנֹּפֶת מִמֶּנָּה. וְכָל אוֹתָם שֶׁנִּקְבְּרוּ בָּאָרֶץ הַקְדוֹשָׁה, לִזְרֹק אוֹתָם הַחוּצָה, וּלְטַהֵר אֶת הָאָרֶץ מֵהַצַּד הָאַחֵר (קדוש אחר), כִּבְיָכוֹל שֶׁהָיְתָה מְזִינָה אֶת שְׁאָר גְּדוֹלֵי הָעַמִּים וּלְקַבֵּל אֶת טֻמְאָתָם וּלְהַנְהִיגָם, וְעָתִיד לְטַהֵר אוֹתָהּ וּלְהַעֲבִירָם הַחוּצָה."],[2,"","רַבִּי שִׁמְעוֹן הָיָה מְטַהֵר אֶת (הרי) שׁוּקֵי טְבֶרְיָה, וְכָל שֶׁהָיָה שָׁם מֵת, הָיָה מַעֲלֶה אוֹתוֹ וּמְטַהֵר אֶת הָאָרֶץ. לָמַדְנוּ, כָּתוּב וַתָּבֹאוּ וַתְּטַמְּאוּ אֶת אַרְצִי וְגוֹ'. אָמַר רַבִּי יְהוּדָה, אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁזּוֹכֶה בְחַיָּיו לְהַשְׁרוֹת מְדוֹרוֹ בָּאָרֶץ הַקְּדוֹשָׁה. שֶׁכָּל מִי שֶׁזּוֹכֶה לָהּ, זוֹכֶה לְהַשְׁפִּיעַ מִטַּל הַשָּׁמַיִם שֶׁלְּמַעְלָה שֶׁיּוֹרֵד עַל הָאָרֶץ. וְכָל מִי שֶׁזּוֹכֶה לְהִקָּשֵׁר בְּחַיָּיו בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, זוֹכֶה לְהִקָּשֵׁר אַחַר כָּךְ לָאָרֶץ הַקְּדוֹשָׁה הָעֶלְיוֹנָה."],[3,"","וְכָל מִי שֶׁלֹּא זוֹכֶה בְחַיָּיו, וּמְבִיאִים אוֹתוֹ לְהִקָּבֵר שָׁם, עָלָיו כָּתוּבּ וְנַחֲלָתִי שַׂמְתֶּם לְתוֹעֵבָה. רוּחוֹ יָצְאָה בִרְשׁוּת נָכְרִיָּה אַחֶרֶת, וְגוּפוֹ בָּא תַּחַת רְשׁוּת הָאָרֶץ הַקְּדוֹשָׁה כִּבְיָכוֹל, עָשָׂה קֹדֶשׁ חֹל, וְחֹל קֹדֶשׁ. וְכָל מִי שֶׁזּוֹכֶה לְהוֹצִיא נִשְׁמָתוֹ בָּאָרֶץ הַקְּדוֹשָׁה, מִתְכַּפְּרִים חֲטָאָיו, וְזוֹכֶה לְהִקָּשֵׁר תַּחַת כַּנְפֵי הַשְּׁכִינָה, שֶׁכָּתוּב (דברים לב) וְכִפֶּר אַדְמָתוֹ עַמּוֹ. וְלֹא עוֹד, אֶלָּא אִם זוֹכֶה בְחַיָּיו, זוֹכֶה לִמְשֹׁךְ עָלָיו רוּחַ קְדֻשָּׁה תָּמִיד, וְכָל מִי שֶׁיּוֹשֵׁב בְּרָשׁוּת אַחֶרֶת, נִמְשֶׁכֶת עָלָיו רוּחַ אַחֶרֶת נָכְרִיָּה."],[4,"","לָמַדְנוּ, כְּשֶׁעָלָה רַב הַמְנוּנָא סָבָא לְשָׁם, הָיוּ עִמּוֹ שְׁנֵים עָשָׂר בְּנֵי הַיְשִׁיבָה שֶׁלּוֹ. אָמַר לָהֶם, אִם אֲנִי הוֹלֵךְ לַדֶּרֶךְ הַזּוֹ, לֹא עַל שֶׁלִּי אֲנִי עוֹשֶׂה, אֶלָּא כְּדֵי לְהָשִׁיב הַפִּקָּדוֹן לִבְעָלָיו. שָׁנִינוּ, כָּל אוֹתָם שֶׁלֹּא זָכוּ לָזֶה בְחַיֵּיהֶם, הֵם מְשִׁיבִים אֶת פִּקְדוֹן רִבּוֹנָם לְאַחֵר."],[5,"","אָמַר רַבִּי יִצְחָק, מִשּׁוּם כָּךְ, כָּל מִי שֶׁמַּעֲבִיר מֵאוֹתָם מִינִים רָעִים אוֹ רָשׁוּת אַחֶרֶת לָאָרֶץ, הָאָרֶץ נִטְמֵאת. אוֹי לְאוֹתוֹ הָאִישׁ! אוֹי לְנַפְשׁוֹ! שֶׁהֲרֵי הָאָרֶץ הַקְּדוֹשָׁה לֹא תְקַבֵּל אוֹתוֹ אַחַר כָּךְ, עָלָיו כָּתוּב (תהלים קד) יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ - בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. וּרְשָׁעִים עוֹד אֵינָם - בִּתְחִיַּת הַמֵּתִים. אָז - בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ."],[6,"","אֶת מִשְׁפָּטַי תַּעֲשׂוּ וְאֶת חֻקֹּתַי תִּשְׁמְרוּ לָלֶכֶת בָּהֶם וְגוֹ'. רַבִּי אַבָּא אָמַר, אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה, וּבִשְׁבִיל אַהֲבָתוֹ עֲלֵיהֶם נָתַן לָהֶם הַנְהָגוֹת אֱמֶת, נָטַע בָּהֶם אֶת עֵץ הַחַיִּים וְהִשְׁרָה שְׁכִינָתוֹ בֵינֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁיִּשְׂרָאֵל רְשׁוּמִים בְּרֹשֶׁם קָדוֹשׁ בִּבְשָׂרָם, וְנוֹדָעִים שֶׁהֵם שֶׁלּוֹ, (נודעים) מִבְּנֵי הֵיכָלוֹ."]]],[["וּבְגִּינֵי כַּךְ, כָּל אִינּוּן דְּלָא רְשִׁימִין בִּרְשִׁימוּ קַדִּישָׁא בִּבְשָׂרֵיהוֹן לָאו אִינּוּן דִּילֵיהּ, וְאִשְׁתְּמוֹדְעָן דְּכֻלְּהוּ מִסִּטְרָא דִּמְסָאֲבוּתָא אַתְיָין, וְאָסִיר לְאִתְחַבְּרָא בְּהוּ, וּלְאִשְׁתָּעֵי בַּהֲדַיְיהוּ, בְּמִלּוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וְאָסִיר לְאוֹדָעָא לְהוּ מִלֵּי דְּאוֹרַיְיתָא, בְּגִין דְּאוֹרַיְיתָא כֻּלָּא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכָל אָת דְּאוֹרַיְיתָא, מִתְקַשְּׁרָא בִּשְׁמָא קַדִּישָׁא. וְכָל מַאן דְּלָא אִתְרְשִׁים בִּרְשִׁימָא קַדִּישָׁא בִּבְשָׂרֵיהּ, אָסִיר לְאוֹדָעָא לֵיהּ מִלָּה דְּאוֹרַיְיתָא. וְכָּל שֶׁכֵּן לְאִשְׁתַּדְּלָא (נ\"א לאסתכלא) בֵּיהּ.","רַבִּי שִׁמְעוֹן פָּתַח, (שמות י״ב:מ״ג-מ״ד) זֹאת חֻקַּת הַפָּסַח כָּל בֶּן נֵכָר לֹא יֹאכַל בּוֹ, וּכְתִיב וְכָל עֶבֶד אִישׁ וְגוֹ'. וּכְתִיב תּוֹשָׁב וְשָׂכִיר לֹא יֹאכַל בּוֹ. וּמַה פִּסְחָא דְּאִיהוּ בִּשְׂרָא לְמֵיכְלָא, עַל דְּאִתְרְמִיז בְּמִלָּה קַדִּישָׁא, אָסִיר לְכָל הָנֵי לְמֵיכַל בֵּיהּ, וּלְמֵיהַב לְהוּ לְמֵיכַל, עַד דְּאִתְגְּזָרוּ. אוֹרַיְיתָא דְּהִיא קֹדֶשׁ קֳדָשִׁים (דקדישא) שְׁמָא עִלָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה.","רִבִּי אֶלְעָזָר שָׁאִיל לְרִבִּי שִׁמְעוֹן אֲבוּהִי, אָמַר לֵיהּ, הָא תָּנֵינָן אָסוּר לְלַמֵּד תּוֹרָה לְעוֹבֵד כּוֹכָבִים וּמַזָּלוֹת, וְשַׁפִּיר אַתְּעֲרוּ חַבְרַיָּיא דְּבָבֶל, דִּכְתִּיב, (תהילים קמ״ז:כ׳) לֹא עָשָׂה כֵן לְכָל גּוֹי, אֲבָל כֵּיוָן דְּאָמַר מַגִּיד דְּבָרָיו לְיַעֲקֹב, אֲמַאי חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. אָמַר לֵיהּ, אֶלְעָזָר תָּא חֲזֵי, זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּחוּלָקָא עִלָּאָה קַדִּישָׁא דָּא נָטַע בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (משלי ד׳:ב׳) כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, לָכֶם, וְלָא לְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה.","וּבְגִין דְּאִיהִי גְּנִיזָא עִלָּאָה יַקִּירָא, שְׁמֵיהּ מַמָּשׁ, אוֹרַיְיתָא כֹּלָּא סָתִים וְגַלְיָא, בְּרָזָא דִּשְׁמֵיהּ. וְעַל דָּא, יִשְׂרָאֵל בִּתְרֵין דַּרְגִּין אִינּוּן, סָתִים וְגַלְיָא, דְּתָנֵינָן תְּלַת דַּרְגִּין אִינּוּן מִתְקַשְּׁרָן דָּא בְּדָא, קוּדְשָׁא בְּרִיךְ הוּא, אוֹרַיְיתָא, וְיִשְׂרָאֵל. וְכָל חַד, דַּרְגָּא עַל דַּרְגָּא, סָתִים וְגַלְיָא. קוּדְשָׁא בְּרִיךְ הוּא דַּרְגָּא עַל דַּרְגָּא, סָתִים וְגַלְיָא. אוֹרַיְיתָא הָכִי נָמֵי סָתִים וְגַלְיָא. יִשְׂרָאֵל הָכִי נָמֵי דַּרְגָּא עַל דַּרְגָּא, הֲדָא הוּא דִּכְתִּיב, (תהילים קמ״ז:י״ט) מַגִּיד דְּבָרָיו לְיַעֲקֹב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. תְּרֵי דַּרְגִּין אִינּוּן, יַעֲקֹב וְיִשְׂרָאֵל, חַד גַּלְיָא, וְחַד סָתִים.","מַאי קָא מַיְירֵי. אֶלָא כָּל מָאן דְּאִתְגְּזַר וְאִתְרְשִׁים בִּשְׁמָא (נ\"א ברשומא) קַדִּישָׁא, יָהֲבִין לֵיהּ בְּאִינּוּן מִלִּין דְּאִתְגַּלְּיָין בְּאוֹרַיְיתָא, כְּלוֹמַר, מוֹדִיעִין לֵיהּ בְּרֵישֵׁי אַתְוָון, בְּרֵישֵׁי פִּרְקִין, יָהֲבִין עָלֵיהּ חוּמְרָא דְּפִקוּדֵי אוֹרַיְיתָא, וְלָא יַתִּיר, עַד דְּיִסְתָּלַק בְּדַרְגָּא אָחֳרָא, הֲדָא הוּא דִכְתִיב מַגִּיד דְּבָרָיו לְיַעֲקֹב (ליעקב שפיר). אֲבָל חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, דְּאִיהוּ בְּדַרְגָּא עִלָּאָה יַתִּיר. וּכְתִיב (בראשית ל״ה:י׳) לֹא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב וְגוֹ'. חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, אִלֵּין רָזֵי אוֹרַיְיתָא וְנִמּוּסֵי אוֹרַיְיתָא, וְסִתְרֵי אוֹרַיְיתָא, דְּלָא יִצְטָרְכוּן לְגַלָּאָה אֶלָּא לְמַאן דְּאִיהוּ בְּדַרְגָּא עִלָּאָה יַתִּיר כַּדְקָא חֲזֵי.","וּמַה לְיִשְׂרָאֵל הַאי, לְעַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה עַל אַחַת כַּמָּה וְכַמָּה, וְכָל מַאן דְּלָא אִתְגְּזַר וְיָהֲבִין לֵיהּ אֲפִילּוּ אָת זְעֵירָא דְּאוֹרַיְיתָא, כְּאִלּוּ חָרִיב עָלְמָא, וּמְשַׁקֵּר בִּשְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּכֹלָּא בְּהַאי תַּלְיָא, וְדָא אִתְקְשַׁר, דִּכְתִּיב, (ירמיהו ל״ג:כ״ה) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.","תָּא חֲזֵי, כְּתִיב (דברים ד׳:מ״ד) וְזֹאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. לִפְנֵי בְּנֵי יִשְׂרָאֵל שָׂם, אַבָל לִשְׁאָר עַמִּין לָא שָׂם. בְּגִין כָּךְ דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל. (ויקרא כ) וְאֶל בְּנֵי יִשְׂרָאֵל תֹּאמַר. וְכֵן כֻּלְּהוּ. יְנוּחוּן אֲבָהָן דְּעָלְמָא, אִינּוּן הִלֵל וְשַׁמָּאי, דְּהָכִי אָמְרוּ לְאוּנְקְלוּס, וְלָא אוֹדְעוּ לֵיהּ מִלָּה דְּאוֹרַיְיתָא עַד דְּאִתְגְּזַר.","וְתָא חֲזֵי, מִלָּה קַדְמָאָה דְּאוֹרַיְיתָא, דְּיָהֲבִין לִינוֹקֵי, אָלֶ\"ף בֵּי\"ת, דָּא מִלָּה דְּלָא יַכְלִין בְּנֵי עָלְמָא לְאַדְבְּקָא בְּסוּכְלְתָנוּ, וּלְסַלְּקָא לֵיהּ בִּרְעוּתָא, וְכָּל שֶׁכֵּן לְמַלְּלָא בְּפוּמֵיהוֹן. וַאֲפִילּוּ מַלְאֲכֵי עִלָּאֵי, וְעִלָאֵי דְּעִלָאֵי, לָא יַכְלִין לְאַדְבְּקָא, בְּגִין דְּאִינּוּן סְתִימִין דִּשְׁמָא קַדִּישָׁא. וַאֶלַף וְאַרְבַּע מְאָה וַחֲמֵשׁ רִבְּבָן דְּעָלְמִין, כֻּלְּהוּ תַלְיָין בְּקוּצָא דְּאַלֶ\"ף, וְשִׁבְעִין וּתְרֵין שְׁמָהָן קַדִישִׁין גְלִיפִין בְּאַתְווֹי רְשִׁימִין, דְּקַיְימוּ בְּהוּ עִלָּאֵי וְתַתָּאֵי, שְׁמַיָא וְאַרְעָא, וְכוּרְסְיָיא יְקָרָא דְּמַלְכָּא, תַּלְיָין מִסִּטְרָא חֲדָא לְסִטְרָא חֲדָא, דִּפְשִׁיטוּתָא דְּאָלֶף, קִיוּמָא דְּעָלְמִין כֻּלְּהוּ, וְסַמְכִין דְּעִלָּאִין וְתַתָּאִין בְּרָזָא דְּחָכְמְתָא.","וּשְׁבִילִין סְתִימִין, וְנַהֲרִין עֲמִיקִין, וְעֶשֶׂר אֲמִירָן, כֻּלְּהוּ נָפְקִין מֵהַהוּא קוֹצָא תַּתָּאָה דִּתְחוֹת אָלֶף. מִכָּאן וּלְהָלְאָה שָׁארֵי לְאִתְפַּשְׁטָא אָלֶף בְּבֵית. וְלֵית חוּשְׁבָּן לְחָכְמְתָא דְּהָכָא אִתְגְּלִיף."],[[0,"ובגיני כך כל וכו׳:","ומשום זה, כל אלו שאינם רשומים ברושם קדוש בבשר שלהם, דהיינו שאינם נמולים, אינם שלו, של הקב״ה, וניכרים שכולם באים מצד הטומאה, ואסור להתחבר בהם, ולספר עמהם בדברי הקב״ה, ואסור להודיעם דברי תורה, משום שהתורה כולה היא שמו של הקב״ה, וכל אות שבתורה, מתקשרת בשם הקדוש, וע״כ כל מי שאינו נרשם בשם הקדוש בבשרו, אסור להודיעו דברי תורה. וכל שכן לעסוק עמו."],[1,"ר\"ש פתח וכו׳:","רבי שמעון פתח, זאת חקת הפסח כל בן נכר לא יאכל בו. וכתוב וכל עבד איש וגו'. וכתוב, תושב ושכיר לא יאכל בו. ומה הפסח, שהוא רק בשר לאכול, ומשום שנרמז בדבר קדוש, דהיינו על שפסח ה׳ על הפתח וגו', אסור לכל אלו לאכול בו, ולתת להם לאכול, עד שימולו, התורה, שהיא קדש הקדשים, שהיא שם העליון של הקב״ה, על אחת כמה וכמה, שאסור ללמדם."],[2,"ר״א שאיל לר״ש וכו׳:","ר׳ אלעזר שאל לר׳ שמעון אביו, אמר לו, הרי למדנו, אסור ללמוד תורה לעכו״ם, ויפה העירו החברים מבבל, שכתוב לא עשה כן לכל גוי. אבל יש לשאול, כיון שכתוב מגיד דבריו ליעקב, למה כתוב, חוקיו ומשפטיו לישראל. הרי הוא כפל לשון. אמר לו: אלעזר, בוא וראה, אשרי הם ישראל, שחלק העליון הקדוש הזה נטע בהם הקב״ה, שכתוב, כי לקח טוב נתתי \u0003לכם\u0004, לכם, ולא לעמים עכו״ם."],[3,"ובגין דאיהי גניזא וכו׳:","ומשום שהיא טמונה עליונה היקרה, שמו ממש, ע״כ התורה כולה סתומה וגלויה, שיש בה סוד ופשט, בסוד שמו. וע״כ ישראל הם בשתי מדרגות, דהיינו סתומה וגלויה, שלמדנו ג׳ מדרגות הן, המתקשרות זו בזו, שהן הקב״ה, התורה, וישראל. וכל אחת מהן היא מדרגה על מדרגה, דהיינו סתומה וגלויה. כי הקב״ה הוא מדרגה על מדרגה סתומה וגלויה. התורה ג״כ סתומה וגלויה. וישראל ג״כ מדרגה על מדרגה. ז״ש, מגיד דבריו ליעקב חקיו ומשפטיו לישראל. שתי מדרגות הן, יעקב, וישראל. אחת גלויה, שהיא מדרגת יעקב, ואחת סתומה, שהיא מדרגת ישראל."],[4,"מאי קא מיירי וכו׳:","שואל. ומה רוצה הכתוב, בזה שאמר חוקיו ומשפטיו לישראל. ומשיב, אלא כל מי שנמול, ונרשם בשם הקדוש, נותנים אותו בדברים הגלוים שבתורה, כלומר, שמודיעים לו בראשי אותיות בראשי פרקים, ונותנים עליו הזהירות החמורה של מצות התורה, ולא יותר, עד שמתעלה במדרגה אחרת. ז״ש מגיד דבריו ליעקב. אבל חוקיו ומשפטיו לישראל, שהוא במדרגה עליונה יותר. שכתוב, לא יקרא שמך עוד יעקב וגו' הרי שישראל חשוב יותר מיעקב, וע״כ, חוקיו ומשפטיו לישראל, שהם סודות התורה, וחוקי התורה ונסתרות התורה, שלא צריכים לגלות זה, אלא למי שהוא במדרגה עליונה יותר כראוי."],[5,"ומה לישראל האי וכו׳:","ומה לישראל כך, שאין מגלים התורה, אלא למי שהוא במדרגה עליונה, לעמים עכו״ם על אחת כמה וכמה. וכל מי שלא נימול ונותנים לו אפילו אות קטנה שבתורה, הוא כאלו החריב העולם, ומשקר בשמו של הקב״ה. כי הכל תלוי בזה, במילה, וזה בזה נקשר, התורה נקשרת במילה, שכתוב, אם לא בריתי יומם ולילה חקות שמים וארץ לא שמתי."],[6,"ת״ח כתיב וכו׳:","בוא וראה, כתוב, וזאת התורה אשר \u0003שם\u0004 משה לפני בני ישראל. לפני בני ישראל שם, אבל לשאר העמים לא שם. משום זה, דבר אל בני ישראל, ואל בני ישראל תאמר. וכן כולם רק לישראל. ינוחו, אבות העולם, שהם הלל ושמאי, שאמרו כך לאונקלוס, ולא הודיעו לו דבר תורה עד שנמול."],[7,"ות״ח מלה קדמאה וכו׳:","ובוא וראה, דבר ראשון שבתורה, שנותנים לתנוקות, הוא אלף בית. זהו דבר שאין בני העולם יכולים להשיג בבינתם ולהעלות על רצונם, וכל שכן לדבר בפיהם. ואפילו מלאכים עליונים ועליוני העליונים אינם יכולים להשיג, משום שהם נסתרות של השם הקדוש. ואלף וארבע מאות וחמשה רבבות עולמות, כולם תלוים בקוץ של האלף. דהיינו הקוץ שב \u0003י׳\u0004 העליונה שב \u0003א׳.\u0004 וע״ב שמות קדושים חקוקים באותיות רשומות שמתקיימים בהם. ועליונים ותחתונים, שמים וארץ, וכסא הכבוד של המלך תלוים מצד אחד לצד אחד, דהיינו מקוץ העליון עד קוץ התחתון, של התפשטות ה \u0003א'.\u0004 הם הקיום של כל העולמות, והסומכים של העליונים והתחתונים בסוד החכמה."],[7,"","פירוש. ה \u0003א׳\u0004 כוללת בתוכה כל פרצופי אצילות. כי קוצה של \u0003י׳\u0004 העליונה של ה \u0003א׳\u0004 הוא א״א. וה \u0003י׳\u0004 עצמה היא או״א עלאין, שה״ס ג״ר דבינה, וה \u0003ו׳\u0004 שבאמצע ה \u0003א׳\u0004 בין ב׳ היודין, היא ישסו״ת. ו \u0003י׳\u0004 התחתונה, היא ז״א ומלכות (כמ״ש לעיל ב״א אות קל״ח בהסולם באורך עש״ה)."],[7,"","וז״ש, \u0003ואלף וארבע מאה וחמש רבבן דעלמין, כלהו תליין בקוצא דאלף,\u0004 כי הקוצא דאלף הוא א״א, שבו תלוים אבא ואמא, אשר אבא ה״ס \u0003אלף\u0004 ואמא ה״ס \u0003ד׳ מאות,\u0004 שהם חו״ב תו\"מ. והנתיב המיחד אותם כולל חג״ת נ״ה, שה״ס \u0003חמש.\u0004 וה \u0003ו׳\u0004 שבאמצע האלף ה״ס ישסו״ת, שהם ו״ק דבינה, ובהם מתגלה שורשי ע״ב שמות המרומזים באותיות הכתובים של ויסע ויבא ויט, (כמ״ש לעיל בשלח אות קע״ג) שה״ס ג׳ קוין. וז״ש \u0003ושבעין ותרין שמהן גליפין באתווי רשימין דקיימו בהו,\u0004 שע״ב שמות החקוקים באותיות רשומות של ויסע ויבא ויט, קיימים בהם באו״א עלאין, כי ישסו״ת שבהם שורשי ג׳ קוין שה״ס ע״ב שמות נמשכים מאו״א, שהם אלף ות״ה עולמות כנ״ל. וז\"ש, \u0003עלאי ותתאי,\u0004 שהם או\"א וישסו״ת, \u0003שמיא וארעא,\u0004 שהם זו״ן \u0003וכורסייא יקרא דמלכא,\u0004 שהוא נוקבא הנפרדת מז״א, \u0003תליין מסטרא חדא לסטרא חדא דפשיטותא דאלף,\u0004 שכל אלו נכללים ב \u0003א׳\u0004 מצד אחד למשנהו, כי קוצה של יוד, היא א״א ויוד עליונה ד \u0003א'\u0004 היא או״א, וה \u0003ו׳\u0004 שבאמצעה, היא ישסו״ת, ו \u0003י׳\u0004 תחתונה היא זו״ן, ונוקבא הנפרדת שלו. והם, \u0003קיומא דעלמין כלהו,\u0004 שהמוחין של כל העולמות הנקראים קיום נמשכים מהם, \u0003וסמכין דעלאין ותתאין, ברזא דחכמתא.\u0004 שסוד ג׳ סמכין שהם ג׳ קוין הממשיכים הארת החכמה, בעליונים ותחתונים נמשכים מהם."],[8,"ושבילין סתימין ונהרין וכו׳:","ושבילים סתומים, שה״ס ל״ב נתיבות החכמה, ונהרות עמוקים, שה״ס ספירות הבינה, ועשרה מאמרות, שה״ס עשר ספירות של הדעת המיחד חו״ב, שה״ס חכמה בינה דעת דו״א, כולם יוצאים ונמשכים לעולמות מקוץ ההוא התחתון שמתחת האלף. כי \u0003י׳\u0004 תחתונה ד \u0003א׳\u0004 ה״ס זו״ן כנ״ל, שאורותיהם נמשכים דרך הקוץ התחתון ד \u0003י׳.\u0004 וע״כ הוא כלל, שכולם כלולים באלף. ומכאן ולהלאה מתחילים האורות שב \u0003א׳\u0004 להתפשט ב \u0003ב'\u0004 וכו'. ואין חשבון לחכמה שנחקקה כאן. (ועי׳ לעיל ב״א אות ק״מ בהסולם)."]],[[0,"","וּמִשּׁוּם כָּךְ, כָּל אוֹתָם שֶׁלֹּא רְשׁוּמִים בָּרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרָם, הֵם אֵינָם שֶׁלּוֹ, וְנוֹדָעִים שֶׁכֻּלָּם מִצַּד הַטֻּמְאָה הֵם בָּאִים, וְאָסוּר לְהִתְחַבֵּר עִמָּהֶם וּלְדַבֵּר עִמָּם בְּדִבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאָסוּר לְהוֹדִיעָם דִּבְרֵי תוֹרָה, כִּי הַתּוֹרָה כֻּלָּהּ שְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, וְכָל אוֹת שֶׁל הַתּוֹרָה נִקְשֶׁרֶת לַשֵּׁם הַקָּדוֹשׁ. וְכָל מִי שֶׁלֹּא רָשׁוּם בָּרֹשֶׁם הַקָּדוֹשׁ בִּבְשָׂרוֹ, אָסוּר לְהוֹדִיעוֹ דְּבַר תּוֹרָה, וְכָל שֶׁכֵּן לְהִתְעַסֵּק (להסתכל) עִמּוֹ."],[1,"","רַבִּי שִׁמְעוֹן פָּתַח, (שמות יב) זֹּאת חֻקַּת הַפָּסַח כָּל בֶּן נֵכָר לֹא יֹאכַל בּוֹ, וְכָתוּב וְכָל עֶבֶד אִישׁ וְגוֹ', וְכָתוּב תּוֹשָׁב וְשָׂכִיר לֹא יֹאכַל בּוֹ. וּמַה פֶּסַח שֶׁהוּא בָּשָׂר לְמַאֲכָל, עַל שֶׁנִּרְמָז בְּדָבָר קָדוֹשׁ אָסוּר לְכָל אֵלֶּה לֶאֱכֹל בּוֹ וְלָתֵת לָהֶם לֶאֱכֹל עַד שֶׁיִּמּוֹלוּ - הַתּוֹרָה שֶׁהִיא קֹדֶשׁ קָדָשִׁים (של קדשים), הַשֵּׁם הָעֶלְיוֹן שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, עַל אַחַת כַּמָּה וְכַמָּה."],[2,"","רַבִּי אֶלְעָזָר שָׁאַל אֶת רַבִּי שִׁמְעוֹן אָבִיו. אָמַר לוֹ, הֲרֵי שָׁנִינוּ שֶׁאָסוּר לְלַמֵּד תּוֹרָה לְעוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְיָפֶה הֵעִירוּ הַחֲבֵרִים מִבָּבֶל, שֶׁכָּתוּב לֹא עָשָׂה כֵן לְכָל גּוֹי. אֲבָל כֵּיוָן שֶׁאָמַר מַגִּיד דְּבָרָיו לְיַעֲקֹב, לָמָּה חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל? אָמַר לוֹ, אֶלְעָזָר, בֹּא רְאֵה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַחֵלֶק הָעֶלְיוֹן הַקָּדוֹשׁ הַזֶּה נָטַע בָּהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב כִּי לֶקַח טוֹב נָתַתִּי לָכֶם, לָכֶם וְלֹא לְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה."],[3,"","וּמִשּׁוּם שֶׁהִיא גְּנוּזָה עֶלְיוֹנָה נִכְבָּדָה, שְׁמוֹ מַמָּשׁ, הַתּוֹרָה כֻּלָּהּ נִסְתָּר וְנִגְלֶה בַּסּוֹד שֶׁל שְׁמוֹ, וְעַל כֵּן יִשְׂרָאֵל הֵם בִּשְׁתֵּי דְרָגוֹת, נִסְתָּר וְנִגְלֶה. שֶׁשָּׁנִינוּ, שָׁלֹשׁ דְּרָגוֹת הֵן שֶׁנִּקְשָׁרוֹת זוֹ בָּזוֹ: הַקָּדוֹשׁ בָּרוּךְ הוּא, תּוֹרָה וְיִשְׂרָאֵל. וְכָל אַחַת דַּרְגָּה עַל דַּרְגָּה, נִסְתָּר וְנִגְלֶה. הַקָּדוֹשׁ בָּרוּךְ הוּא דַּרְגָּה עַל דַּרְגָּה, נִסְתָּר וְנִגְלֶה. הַתּוֹרָה גַּם כֵּן נִסְתָּר וְנִגְלֶה. יִשְׂרָאֵל גַּם כֵּן דַּרְגָּה עַל דַּרְגָּה. זֶהוּ שֶׁכָּתוּב (תהלים קמז) מַגִּיד דְּבָרָיו לְיַעֲקֹב חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. שְׁתֵּי דְרָגוֹת הֵן - יַעֲקֹב וְיִשְׂרָאֵל, אֶחָד גָּלוּי וְאֶחָד נִסְתָּר."],[4,"","מַה זֶּה אוֹמֵר? אֶלָּא כָּל מִי שֶׁנִּמּוֹל וְנִרְשָׁם בַּשֵּׁם (ברשם) הַקָּדוֹשׁ, נוֹתְנִים לוֹ בְּאוֹתָם דְּבָרִים שֶׁהִתְגַּלּוּ בַתּוֹרָה, כְּלוֹמַר, מוֹדִיעִים לוֹ בְּרָאשֵׁי אוֹתִיּוֹת וּבְרָאשֵׁי פְרָקִים, נוֹתְנִים עָלָיו חֻמְרָה שֶׁל מִצְווֹת הַתּוֹרָה, וְלֹא יוֹתֵר, עַד שֶׁיִּתְעַלֶּה לְדַרְגָּה אַחֶרֶת. זֶהוּ שֶׁכָּתוּב מַגִּיד דְּבָרָיו לְיַעֲקֹב (ליעקב יפה). אֲבָל חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, שֶׁהוּא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה, וְכָתוּב (בראשית לב) לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב וְגוֹ'. חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל, אֵלּוּ סוֹדוֹת הַתּוֹרָה וְהַנְהָגוֹת הַתּוֹרָה וְסִתְרֵי תוֹרָה, שֶׁלֹּא יִצְטָרְכוּ לְגַלּוֹת אֶלָּא לְמִי שֶׁהוּא בְּדַרְגָּה יוֹתֵר עֶלְיוֹנָה כָּרָאוּי."],[5,"","וּמַה לְּיִשְׂרָאֵל כָּזֶה, לְעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה עַל אַחַת כַּמָּה וְכַמָּה. וְכָל מִי שֶׁלֹּא נִמּוֹל וְנוֹתְנִים לוֹ אֲפִלּוּ אוֹת קְטַנָּה שֶׁל הַתּוֹרָה, כְּאִלּוּ הֶחֱרִיב עוֹלָם וּמְשַׁקֵּר בִּשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהַכֹּל תָּלוּי בָּזֶה, וְזֶה בָּזֶה נִקְשָׁר, שֶׁכָּתוּב (ירמיהלג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי."],[6,"","בֹּא רְאֵה, כָּתוּב וְזֹּאת הַתּוֹרָה אֲשֶׁר שָׂם מֹשֶׁה לִפְנֵי בְּנֵי יִשְׂרָאֵל. לִפְנֵי בְּנֵי יִשְׂרָאֵל שָׂם, אֲבָל לִשְׁאָר הָעַמִּים לֹא שָׂם. מִשּׁוּם כָּךְ דַּבֵּר אֶל בְּנֵי יִשְׂרָאֵל. (ויקרא ב) וְאֶל בְּנֵי יִשְׂרָאֵל תֹּאמַר. וְכֵן כֻּלָּם. יָנוּחוּ אֲבוֹת הָעוֹלָם, הֵם הִלֵּל וְשַׁמַּאי, שֶׁכָּךְ אָמְרוּ לְאוּנְקְלוּס, וְלֹא הוֹדִיעוּ לוֹ דְּבַר תּוֹרָה עַד שֶׁנִּמּוֹל."],[7,"","וּבֹא רְאֵה, הַדָּבָר הָרִאשׁוֹן שֶׁל הַתּוֹרָה שֶׁנּוֹתְנִים לַתִּינוֹקוֹת אָלֶ\"ף בֵּי\"ת, זֶה דָּבָר שֶׁאֵין בְּנֵי הָעוֹלָם יְכוֹלִים לְהַשִּׂיג בְּשִׂכְלָם וּלְהַעֲלוֹתוֹ בְרָצוֹן, וְכָל שֶׁכֵּן לְדַבֵּר אוֹתוֹ בְּפִיהֶם, וַאֲפִלּוּ מַלְאָכִים עֶלְיוֹנִים וְעֶלְיוֹנֵי הָעֶלְיוֹנִים אֵין יְכוֹלִים לְהַשִּׂיג, כִּי הֵם נִסְתְּרוֹת הַשֵּׁם הַקָּדוֹשׁ. וְאֶלֶף וְאַרְבַּע מֵאוֹת וְחָמֵשׁ רְבָבוֹת שֶׁל עוֹלָמוֹת, כֻּלָּם תְּלוּיִים בְּקוֹצוֹ שֶׁל אָלֶ\"ף, וְשִׁבְעִים וּשְׁנַיִם שֵׁמוֹת קְדוֹשִׁים חֲקוּקִים בְּאוֹתִיּוֹתָיו רְשׁוּמִים, שֶׁעָמְדוּ בָהֶם עֶלְיוֹנִים וְתַחְתּוֹנִים, שָׁמַיִם וָאָרֶץ, וְכִסֵּא הַכָּבוֹד שֶׁל הַמֶּלֶךְ, תְּלוּיִים מִצַּד אֶחָד לְצַד אֶחָד, שֶׁפְּשִׁיטוּת הָאָלֶף קִיּוּמָם שֶׁל כָּל הָעוֹלָמוֹת, וְתוֹמְכִים שֶׁל עֶלְיוֹנִים וְתַחְתּוֹנִים בְּסוֹד הַחָכְמָה."],[8,"","וּשְׁבִילִים נִסְתָּרִים וּנְהָרוֹת עֲמֻקִּים וְעֶשֶׂר אֲמִירוֹת, כֻּלָּם יוֹצְאִים מֵאוֹתוֹ קוֹץ תַּחְתּוֹן שֶׁתַּחַת הָאָלֶף. מִכָּאן וָהָלְאָה מַתְחִיל לְהִתְפַּשֵּׁט אָלֶף בְּבֵי\"ת, וְאֵין חֶשְׁבּוֹן לַחָכְמָה שֶׁנֶּחְקְקָה כָּאן."]]],[["בְּגִינֵי כַּךְ, אוֹרַיְיתָא קִיוּמָא דְּכֹלָּא, וּמְהֵימְנוּתָא דְּכֹלָּא, לְקַשְּׁרָא קִשְׁרָא דִּמְהֵימְנוּתָא דָּא בְּדָא כַּדְקָא חֲזֵי. וּמַאן דְּאִתְגְּזַר, אִתְקָשַׁר בְּהַהוּא קִשְׁרָא דִּמְהֵימְנוּתָא. וּמַאן דְּלָא אִתְגְּזַר, וְלָא אִתְקְשַׁר בֵּיהּ, כְּתִיב בֵּיהּ, (ויקרא כ״ב:י׳) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שמות י״ב:מ״ח) וְכָל עָרֵל לֹא יֹאכַל בּוֹ. דְּהָא אִתְּעַר רוּחַ מִסְאֲבָא דְּמִסִּטְרֵיהּ, וְאָתֵי לְאִתְעָרְבָא בִּקְדוּשָּׁה. בְּרִיךְ רַחֲמָנָא, דְּפָרִישׁ לְיִשְׂרָאֵל בְּנוֹי, רְשִׁימִין בִּרְשִׁימָא קַדִּישָׁא, מִנַּיְיהוּ וּמִזוּהֲמָא דִּלְהוֹן. עָלַיְיהוּ כְּתִיב, (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. וּבְגִּינֵי כַּךְ, (מיכה ז׳:כ׳) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְלָא לְאָחֳרָא. תּוֹרַת אֱמֶת, לְזֶרַע אֱמֶת. אָתָא רִבִּי אֶלְעָזָר וּנְשָׁקֵיהּ עַל יְדוֹי.","רִבִּי חִזְקִיָּה אָמַר, כְּתִיב (שמואל א י״ב:כ״ב) כִּי לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ וְגוֹ', כִּי לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ, מַאי טַעְמָא בַּעֲבוּר שְׁמוֹ הַגָּדוֹל. בְּגִין דְּכֹלָּא אִתְקְשַׁר דָּא בְּדָא, וּבְמָּה אִתְקָשָּׁרוּ יִשְׂרָאֵל בְּקוּדְשָׁא בְּרִיךְ הוּא. בְּהַהוּא רְשִׁימָא קַדִּישָׁא דְּאִתְרְשִׁים בִּבְשָׂרֵיהוֹן. וּבְגִּינֵי כַּךְ, לֹא יִטּוֹשׁ יְיָ' אֶת עַמּוֹ. וְלָמָּה. בַּעֲבוּר שְׁמוֹ הַגָּדוֹל דְּאִתְרְשִׁים בְּהוּ.","תָּאנָא, אוֹרַיְיתָא אִקְרֵי בְּרִית, וְקוּדְשָׁא בְּרִיךְ הוּא אִקְרֵי בְּרִית. וְהַאי רְשִׁימָא קַדִּישָׁא אִקְרֵי בְּרִית. וְעַל דָּא כֹּלָּא אִתְקְשַׁר דָּא בְּדָא, וְלָא אִתְפְּרַשׁ דָּא מִן דָּא. אָמַר לֵיהּ רִבִּי יֵיסָא, אוֹרַיְיתָא וְיִשְׂרָאֵל שַׁפִּיר. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא מְנָלָן דְּאִקְרֵי בְּרִית. אָמַר לֵיהּ דִּכְתִּיב, (תהילים ק״ו:מ״ה) וַיִּזְכּוֹר לָהֶם בְּרִיתוֹ, וְהָא אִתְיְידַע, וְהָא אִתְּמַר.","(ויקרא י״ח:ד׳) וְאֶת חֻקֹּתַי תִּשְׁמְרוּ, חֻקּוֹתַי: אִלֵּין אִינּוּן נִמוּסֵי מַלְכָּא. מִשְׁפָּטַי: אִלֵּין אִינּוּן גִּזְרֵי אוֹרַיְיתָא, רִבִּי יְהוּדָה אָמַר, כָּל אִינּוּן נִמוּסִין מֵאֲתַר דְּאִקְרֵי צֶדֶק, אִקְרוּן חֻקּוֹתַי, וְאִינּוּן גְּזֵרַת מַלְכָּא. וּבְכָל אֲתַר דְּאִקְרֵי מִשְׁפָּט אִקְרוּן דִּינָא דְּמַלְכָּא, דְּאִיהוּ מַלְכָּא קַדִּישָׁא, קוּדְשָׁא בְּרִיךְ הוּא, מַלְכָּא דִּשְׁלָמָא כֹּלָּא דִּילֵיהּ הוּא. דְּהוּא מַלְכָּא קַדִּישָׁא, בַּאֲתַר דִּתְרֵין חוּלָקִין אֲחִידָן דָּא בְּדָא. וְעַל דָּא כְּתִיב, (תהילים פ״ט:ט״ו) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךָ, וְאִינּוּן דִּינָא וְרַחֲמֵי. וּבְגִּינֵי כַּךְ חֹק וּמִשְׁפָּט. וְעַל דָּא כְּתִיב (תהילים קמ״ז:י״ט-כ׳) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. לְיִשְׂרָאֵל וְלָא לִשְׁאָר עַמִּין.","בַּתְרֵיהּ מַה כְּתִיב, לֹא עָשָׂה כֵן לְכָל גּוֹי. וְתָנֵינָן, אַף עַל גַּב דְּאִתְגְּזַר וְלָא עָבִיד פִּקּוּדֵי אוֹרַיְיתָא, הֲרֵי הוּא כְּגוֹי בְּכֹלָּא, וְאָסִיר לְמֵילַף לֵיהּ פִּתְגָּמֵי אוֹרַיְיתָא. וְעַל דָּא תָּנֵינָן (שמות כ׳:כ״ב) מִזְבַּח אֲבָנִים, דָּא מִזְבֵּחַ אֲבָנִים מַמָּשׁ. וְהָא קַשְׁיוּ דְּלִבֵּיהּ בְּאַתְרֵיהּ קַיְּימָא, וְזוּהֲמָא לָא אִתְפְּסָק מִנֵיהּ. בְּגִינֵי כַּךְ, לָא סָלִיק בִּידֵיהּ הַהוּא גְּזִירוּ, וְלָא מְהַנְיָא לֵיהּ. וְעַל דָּא כְּתִיב, (שמות כ׳:כ״ב) כִּי חַרְבְּךָ הֵנַפְתָּ עָלֶיהָ וַתְּחַלְלֶהָ.","בְּגִינֵי כַּךְ, לֹא עָשָׂה כֵן לְכָל גּוֹי סְתָם. וּמִשְׁפָּטִים בַּל יְדָעוּם לְעָלַם וּלְעָלְמֵי עָלְמִין. מִלָּה אָחֳרָא (נ\"א זעירא), לָא יַהֲבֵינָן לְהוּ, כָּל שֶׁכֵּן רָזֵי אוֹרַיְיתָא, וְנִמוּסִין דְּאוֹרַיְיתָא. וּכְתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁיְיָ' אֱלֹהָיו.","מַתְנִיתִין, בְּנִמוּסֵי טְהִירִין. אַרְבַּע מַפְתְּחִין שָׁוִיין, לְאַרְבַּע סִטְרֵי עָלְמָא. בְּזִוְיַיתְהוֹן אִשְׁתְּכָחוּ. חַד לִסְטַר אַרְבַּע, וְאַרְבַּע לִסְטַר חַד. אִתְגַלְּפָן (ס\"א אתפלגן) בְּחַד גַּוְונָא. בְּהַהוּא גַּוְונָא, תְּכֵלָא, וְאַרְגְּוָונָא וְצֶבַע זְהוֹרִי, וְחִוָּורָא, וְסוּמָקָא. דָּא עָיֵיל בְּגַוְונָא דְּחַבְרֵיהּ, וְדִידֵיהּ בֵּיהּ רָשִׁים.","אַרְבַּע רֵישִׁין כַּחֲדָא אִסְתְּלִיקוּ, וּבְחַד דִּיּוּקְנָא מִתְדַּבְּקָן. חַד רֵישָׁא אִסְתְּלִיק, מִגּוֹ סַחְיוּ דְּאִסְתְּחֵי. תְּרֵי אַיַּילְתָּא קְצִיבִין בְּשִׁיעוּרָא חַד, סַלְקָן מֵהַהוּא סַחְיוּתָא, דִּכְתִּיב, (שיר השירים ד׳:ב׳) כְּעֵדֶר הַקְּצוּבוֹת שֶׁעָלוּ מִן הָרַחְצָה. בְּשַׂעֲרָא דִּלְהוֹן, חֵיזוֹ דְּאֶבֶן טָבָא דְּאַרְבַּע גַּוְונִין.","אַרְבַּע גַּדְפִּין דְּכַסְיָין עַל גּוּפָא, וִידִין זְעִירִין תְּחוֹת גַּדְפַּיְיהוּ. וְחָמֵשׁ בְּחָמֵשׁ גְּלִיפָן. טָאסִין (ס\"א שאפין) לְעֵילָּא לְעֵילָּא מֵהֵיכָלָא, דְּשַׁפִּירָא בְּרֵיוָא וְיָאֶה לְמֵחזֵי.","חַד עוּלֵים רַבְיָא, נָפִּיק שִׁנָּן חַרְבָּא, דְּמִתְהַפְּכָא לְגוּבְרִין לְנוּקְבִין. נַטְלִין לִמְשִׁיחָא דְּאֵיפָה בֵּין שְׁמַיָּא וּבֵין אַרְעָא. לְזִמְנִין נַטְלִין (ס\"א עולין) לָהּ בְּכָל עָלְמָא, וְכָל מְשִׁיחִין בָּהּ מָשִׁיחִין, דִּכְתִּיב, (ויקרא י״ט:ל״ו) אֵיפַת צֶדֶק וְגוֹ'."],[[0,"בגיני כך אורייתא וכו׳:","ומשום זה, התורה, שה״ס ז״א, היא קיום הכל ואמונת הכל, לקשר קשר האמונה, שהיא מלכות, זה בזה כראוי. ומי שנמול, נתקשר בקשר ההוא של האמונה, ומי שלא נמול ולא נקשר בו, כתוב בו, וכל זר לא יאכל קדש. וכל ערל לא יאכל בו. כי נתעורר רוח הטומאה שמצדו, ובא להתערב בקדושה. ברוך הרחמן שהפריש ישראל בניו, הרשומים ברושם הקדוש, מהם ומזוהמתם. עליהם כתוב, ואנכי נטעתיך שורק כלה זרע אמת. ומשום זה כתוב, תתן אמת ליעקב, ולא לאחר, תורת אמת לזרע אמת. בא ר׳ אלעזר ונשקו על ידיו."],[1,"ר׳ חזקיה אמר וכו׳:","רח״א, כתוב, כי לא יטוש ה׳ את עמו בעבור שמו וגו'. \u0003כי לא יטוש ה׳ את עמו,\u0004 מהו הטעם. הוא, \u0003בעבור שמו הגדול,\u0004 משום שהכל נקשר זה בזה. ובמה נקשרו ישראל בהקב״ה. הוא, ברושם ההוא הקדוש שנרשם בבשרם, ומשום זה, לא יטוש ה׳ את עמו, ולמה. הוא, בעבור שמו הגדול שנרשם בהם."],[2,"תאנא אורייתא אקרי וכו׳:","למדנו, התורה נקראת ברית, והקב״ה נקרא ברית, ורושם הזה הקדוש דהיינו המילה נקרא ברית וע״כ הכל נקשר זה בזה ולא נפרד זה מזה. א״ל ר׳ ייסא, התורה וישראל, שנקראים ברית, יפה הוא, אבל הקב״ה מאין לנו שנקרא ברית. אמר לו, שכתוב, ויזכור להם בריתו. והרי נודע, שה״ס יסוד. וכבר למדנו."],[3,"ואת חקתי תשמרו:","חקותי, הם מנהגי המלך, שהוא ז״א. \u0003משפטי,\u0004 אלו הם הגזרות שבתורה. ר׳ יהודה אמר, כל אלו המנהגים ממקום שנקרא \u0003צדק,\u0004 שהוא המלכות. נקראים חוקותי. והם גזרות המלך. ובכל מקום שנקרא משפט, נקראים דיני המלך, שהוא מלך הקדוש, הקדוש ברוך הוא, המלך שהשלום כולו שלו הוא, שהוא מלך הקדוש במקום ששני חלקים אחוזים זה בזה, דהיינו דין ורחמים, וע״כ כתוב, צדק ומשפט מכון כסאך, והם דין ורחמים. ומשום זה הם חק ומשפט. וע״ז כתוב, חוקיו ומשפטיו לישראל. לישראל, ולא לשאר העמים."],[4,"בתריה מה כתיב וכו׳:","אחריו, מה כתוב, לא עשה כן לכל גוי. ולמדנו אע״פ שנמול, ואינו עושה מצות התורה, הרי הוא כעכו״ם לגמרי, ואסור ללמדו דברי תורה. וע״כ תנינן מזבח אבנים תעשה לי. זה, המילה, היא מזבח אבנים ממש, דהיינו שמרכך את לבו האבן, וזה שנמול ואינו עושה מצות התורה, קשיות הלב שלו עומדת במקומה, והזוהמא לא נפסקת ממנו. משום זה, לא עולה בידו המילה, ואינה מועילה לו. וע״כ כתוב, כי חרבך הנפת עליה ותחללה. כלומר אע״פ שחרבך הנפת עליה, דהיינו שנמול, עכ״ז, כיון שאינו מקיים המצוות, \u0003ותחללה.\u0004 נתחללה המילה ואינה מועילה. ואסור ללמדו תורה."],[5,"בגיני כך, לא וגו׳:","משום זה, לא עשה כן לכל גוי, גוי סתם, שכולל גם אותו שנמול ואינו עושה מצות. ומשפטים בל ידעום לעולם ולעולמי עולמים, דבר אחר, דהיינו פשטי התורה והמצות, אין אנו נותנים להם, כ״ש סודות התורה וחוקות התורה. וכתוב, כי חלק ה׳ עמו יעקב חבל נחלתו. אשר העם שככה לו אשרי העם שה׳ אלקיו."],[6,"מתניתין, בנמוסי טהירין וכו׳:","משנה, בדרכי האורות. ארבעה מפתחות נעשו לארבע רוחות העולם. ובזויותיהם נמצאים, מפתח אחד לארבע רוחות, וארבע רוחות לרוח אחד. ונחקקים בצבע אחד. בצבע ההוא נמצא מעורב, תכלת, וארגמן, ותולעת שני, ולבן ואדום, זה נכנס בצבע חבירו, וצבע שלו, דהיינו של חבירו, רשום בו."],[6,"","פירוש. נודע שקו ימין וקו שמאל, שהם חסד וגבורה הם במחלוקת ואינם יכולים להאיר, עד שבא הקו האמצעי עם כח המסך שבו ומכריע אותם ומיחדם זב״ז, ואז נפתחת הארתם ומאירים (כנ״ל ב״א נ״ז ד״ה וזה) וע״כ מכונה הקו האמצעי, שהוא ת״ת, בשם \u0003מפתח.\u0004 להיותו פותח האורות. וז״ש \u0003ד׳ מפתחן שויין לארבע סטרי עלמא,\u0004 כי ד׳ סטרי עלמא, הם חסד וגבורה ת״ת ומלכות, וכל רוח כלול מכולם, כמ״ש להלן, נמצא שיש בכל רוח מפתח אחד, שהוא ת״ת, דהיינו הקו האמצעי."],[6,"","ונודע שהקו האמצעי מחבר ד׳ רוחות חו״ג תו״מ לאחד, כלומר שעושה אותם, שאחד מהם לא יוכל להאיר אלא בשיתוף כולם. כי מחמת הכרעתו צריך השמאל לחסדים שבימין, והימין להארת חכמה שבשמאל, שזולתו הוא מחוסר ג\"ר, ושניהם הימין והשמאל צריכים לקו האמצעי שייחדם, ושלשתם צריכים למלכות, משום שקו האמצעי מתקן החכמה שלא תאיר רק ממטה למעלה, (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) שלא יצויר זה אלא במלכות, שהיא אור נקבה, המאירה ממטה למעלה. הרי איך כולם נתקשרו ונתחברו זה בזה על ידי הת״ת שהוא קו האמצעי, והוא נקרא מפתח. וז״ש, \u0003בזוייתהון אשתכחו.\u0004 שהזוית נבחנת לנקודת החיבור של ב׳ רוחות. וכיון שהמפתחות שהם ת״ת, וקו אמצעי, מחברים הרוחות, שהם חו״ג תו״מ, זה בזה. ע״כ נבחן שהמפתחות נמצאים בזויות של הרוחות, דהיינו בבחינת החיבור שבהם."],[6,"","ואין לשאול, הלא ארבע רוחות הם חו\"ג תו״מ, וא״כ אין בכולם אלא ת״ת אחד, שהוא מפתח אחד, ולא ארבע. לזה אומר, \u0003חד לסטר ארבע,\u0004 שבאמת אין יותר ממפתח אחד לארבע רוחות, אבל, \u0003וארבע לסטר חד,\u0004 כי ד׳ הרוחות, חו״ג תו״מ, נכללים זה מזה, ויש ארבע רוחות חו״ג תו״מ בכל רוח מהם, וע״כ יש ד׳ מפתחות."],[6,"","ואותם ד׳ רוחות חו״ג תו״מ, מכונים ד׳ גוונים, שהם לבן אדום ירוק שחור, ולפעמים נקרא הת״ת תולעת שני, והמלכות תכלת. ובעת שת״ת מיחד כל האורות ונכלל מהם נקרא ארגמן, משום שצבע ארגמן כולל בתוכו כל הצבעים וז״ש, \u0003אתגלפן בחד גוונא,\u0004 שכל ד׳ מפתחות נתגלפו בצבע אחד, שהוא ארגמן הכולל כל הצבעים. אבל, \u0003בההוא גוונא, תכלא וארגוונא וצבע זהורי וחוורא וסומקא.\u0004 כלומר שכל אלו האורות נכללים בו. \u0003תכלא,\u0004 הוא מלכות. \u0003ארגוונא,\u0004 הוא ת״ת בשעה שכוללם. \u0003וצבע זהורי,\u0004 הוא ת״ת בפרטיותו. \u0003וחוורא\u0004 הוא חסד \u0003וסומקא,\u0004 היא גבורה. אמנם כלולים זה בזה, וז״ש, \u0003דא עייל בגוונא דחבריה ודידיה ביה רשום,\u0004 דהיינו שמעורבים וכלולים זה בזה."],[7,"ד׳ רישין כחדא וכו׳:","ארבעה ראשים עלו יחד, ובצורה אחת מתדבקים. ראש אחד עלה מתוך הרחיצה שנתרחץ, שתי אילות קצובות בשיעור אחד, עלו מהרחיצה ההיא, שכתוב כעדר הקצובות שעלו מן הרחצה. בשערות שלהם, מראה אבן טוב בד' צבעים."],[7,"","פירוש אחר שהקו האמצעי, שהוא ת״ת הכריע ואיחד ב׳ הקוין זה בזה ונעשו ארבע מפתחות (כנ״ל בדבור הסמוך,) אז מתעלים חג״ת והמלכות למעלה, ונעשו חב״ד שהם ד׳ ראשים, חכמה, בינה, והימין של הדעת דהיינו ת״ת שעלה, שהוא חסדים, והשמאל של הדעת שהוא גבורות, דהיינו המלכות שעלתה. וז״ש, \u0003ד׳ רישין כחדא אסתליקו.\u0004 דהיינו ע״י היחוד של ארבעה מפתחות, שחגת״מ נעשו לחב״ד. אמנם כל אלו ד׳ ראשים הם רק ראש אחד, וז״ש \u0003ובחד דיוקנא מתדבקן,\u0004 שאינם אלא צורה אחת, של ראש אחד. אלא שנבחנים לד׳ ראשים על פי ד׳ המוחין חב״ד שבו, שהם בחינות ג׳ קוין ומלכות המקבלתם."],[7,"","וכבר ידעת שבסבת הדינים שבמסך דחירק שבקו האמצעי מתרצה השמאל להתיחד עם הימין (כנ״ל פרשת לך דף י״ג ד״ה ונתבאר). אמנם לא על ידי המסך בלבד הוא מתרצה להתיחד, אלא בעיקר מפני החסדים המרובים המתגלים ע״י זווג אור עליון על המסך, אשר החסדים הללו \u0003רוחצים\u0004 הקו שמאל מרוב הדינים שנשתקע בהם. גם ידעת שבעת הארת החכמה מתגלים שוב אותם הדינים שבקו שמאל שמלפני יחודו עם הימין, כדי להרחיק החיצונים שלא יינקו מהארת החכמה, (כנ״ל פקודי אות שע״ו) ולפיכך מתגלים ג״כ כנגדם, אותם החסדים המרובים שנתגלו בעת יחודו עם הימין, \u0003שרחצו\u0004 את קו השמאל מן הדינים ההם. וז״ש, \u0003חד רישא אסתליק,\u0004 שהוא ראש הבינה, שהוא שמאל, \u0003מגו סחיא דאסתחי,\u0004 מתוך הרחיצה שהתרחץ, כלומר שבעת שמתגלה הארת החכמה שבבינה, מתגלה באותו הזמן דבר הרחיצה שלו, דהיינו שמתגלים הדינים דשמאל שמטרם יחודו בימין, ומתגלים ג״כ כנגדם החסדים, המכונים מים, שלאחר יחודו עם הימין, שהם רוחצים אותו מן הדינים ההם. באפן, שהראש הזה אינו מאיר זולת דרך רחיצתו."],[7,"","והנה על ידי עלית המלכות לבינה, נכללו זו בזו, וצורותיהן נעשות שוות זו לזו, ויצאו בינה ומלכות בבינה, ובינה ומלכות במלכות, ואלו בינה ומלכות שבמלכות, מכונות ב׳ אילות. וז״ש \u0003תרי איילתא,\u0004 שהן בינה ומלכות שבמלכות, \u0003קציבין בשיעורא חד,\u0004 שהן שוות זו לזו בשיעור אחד, דהיינו כשיעור הבינה, \u0003סלקן מההוא סחיותא,\u0004 שהן עולות, ומקבלות הארת החכמה, מתוך אותה הרחיצה, הנזכרת בראש הבינה. כי מאחר שהמלכות קבלה צורתה של הבינה, היא ראויה לקבל חכמה. ובעת שהמלכות מקבלת הארת החכמה, היא נקראת, אבן טובה בארבעה צבעים, שה״ס ג׳ קוין ומלכות המקבלתם, שבדרך נסיעתם מתגלה החכמה (כנ״ל בשלח דף ל״ט ד״ה וג') וז״ש \u0003בשערא דלהון,\u0004 דהיינו בדינים שלהם, מתגלה, \u0003חיזו דאבן טבא דארבע גוונין,\u0004 שה״ס גילוי הארת החכמה הנקרא \u0003חיזו.\u0004 וכיון שהחכמה אינה מתגלה זולת עם דינין כנ״ל, ע״כ אומר \u0003בשערא דלהון.\u0004"],[8,"ארבע גדפין דכסיין וכו׳:","ארבע כנפים מכסות על הגוף, וידים קטנות תחת כנפיהם. וחמש בחמש חקוקות. מעופפות למעלה למעלה מן ההיכל, שהוא יפה תאר ויפה מראה."],[8,"","כנפים, פירושם כיסוים. והן ארבע. כי ידעת, שמפאת עלית המלכות לבינה, נעשו ימין ושמאל בבינה, שהם בינה ומלכות שבבינה, וימין ושמאל במלכות, שהם בינה ומלכות שבמלכות, ומן הדינים שבאלו ארבע בחינות, יצאו ארבע כנפים לכסות את הגוף, להעלים שם הארת החכמה. וז״ש, \u0003ארבע גדפין דכסיין על גופא.\u0004 המעלימים הארת החכמה במקום הגוף שלהן. אבל תחת הכיסוים יש ידים קטנות. ידים, היינו חסד וגבורה. המכונים ידים, שבכל אחת ה׳ אצבעות, כנגד חג״ת נ״ה, שבסוד שאו ידיכם קדש הן ממשיכות חכמה. וז״ש, \u0003וידין זעירין תחות גדפייהו, וחמש בחמש גליפן,\u0004 שכל אחת מן הידים חקוקה בחמש אצבעות, \u0003טאסין לעילא לעילא מהיכלא דשפירא בריוא ויאה למחזי,\u0004 דהיינו, בסו״ה שאו ידיכם קדש, הן מעופפות ועולות לבינה, שהיא למעלה למעלה מן המלכות הנקראת היכל יפה תאר ויפה מראה, ושם נעשות הידים לחכמה ובינה. ונקראים \u0003ידין זעירין,\u0004 משום שאינם מאירים רק בו\"ק דחכמה."],[9,"חד עולים רביא וכו׳:","נער אמיץ אחד, יוצא בחרב שנונה, המתהפכת לזכרים ולנקבות. נושאים מדידת האיפה בין שמים ובין הארץ. ולפעמים נושאים אותה בכל העולם, וכל המדידות מודדים בה. שכתוב איפת צדק וגו'. \u0003עולים,\u0004 פירושו אמיץ, כי על חזק ואמץ מתרגם תקף ועלם (יהושע א׳ ז')."],[9,"","נער, פירושו מטטרון, שהוא מכונה נער. והוא שומר את השכינה, דהיינו שמרחיק החצונים שלא יינקו ממנה (כנ״ל אות ע״א ע\"ש בהסולם) וע״כ הוא נושא את להט החרב המתהפכת להרחיק החצונים. וז\"ש, \u0003חד עולים רביא נפיק שנן חרבא.\u0004 וכבר ידעת שמעלית המלכות בבינה, נמשכות ד׳ בחינות, ימין ושמאל שבבינה, וימין ושמאל שבמלכות, (כנ״ל בדבור הסמוך,) ולהט החרב הזו מתהפכת על ד׳ בחינות ההם שב' בחינות ימין נקראות זכרים, וב׳ בחינות שמאל נקראות נקבות, וז״ש \u0003דמתהפכא לגוברין לנוקבין,\u0004 שלפעמים שולטים בה הדכורים ולפעמים שולטים בה הנוקבין, (כמ״ש באורך לעיל בראשית ב׳ דף ע״ח ד״ה ביאור, ע\"ש בהמשך) אמנם עיקרם של ד׳ בחינות אלה אינם אלא שתים, דהיינו בינה ומלכות, שהן כלולות במסך שבמלכות, שעליו נעשה הזווג עם ז״א, והמסך נקרא \u0003איפה,\u0004 משום שהוא מודד שיעור האור שיתקבל ע״י הזווג. וז״ש, \u0003נטלין למשיחא דאיפה בין שמיא ובין ארעא,\u0004 שבינה ומלכות האלה המעורבות זו בזו, הפועלות בלהט החרב המתהפכת, הן נושאות את האיפה, דהיינו שמתקנות את מדידת האיפה, שהיא המסך, בין שמים, שהם ז״א, ובין הארץ שהיא המלכות, שהן מתקנות המסך במדת הרחמים לעשותו ראוי לזווג, ולקבל אור העליון. אמנם למטה מן המלכות דאצילות אין האיפה מתוקנת כל כך, ולפעמים מתגלה שם מלכות דמדת הדין, הדוחה את אור העליון מלהתקבל. אמנם לפעמים, דהיינו בשבתות וימים טובים בזמן תפלה, נמצאת נושאים ומתקנים האיפה בכל העולמות, וז\"ש, \u0003לזמנין נטלין לה בכל עלמא, וכל משיחין בה משיחין, דכתיב איפת צדק\u0004 וגו'. איפת הצדק המתוקנת בבינה שולטת בכל מקום וכל המדידות נמדדות בה."],[9,"","ובזה מיושבים ב׳ המקראות, שבזכריה ה׳ ו' אומר, זאת האיפה וגו׳ עינם בכל הארץ. ובפסוק ט׳ אומר, ותשנה את האפה בין הארץ ובין השמים. והיינו כנ״ל, שלפעמים כך ולפעמים כך."]],[[0,"","מִשּׁוּם כָּךְ הַתּוֹרָה הִיא הַקִּיּוּם שֶׁל הַכֹּל וֶאֱמוּנַת הַכֹּל, לִקְשֹׁר קֶשֶׁר שֶׁל הָאֱמוּנָה זֶה עִם זֶה כָּרָאוּי. וּמִי שֶׁנִּמּוֹל, נִקְשָׁר בְּאוֹתוֹ קֶשֶׁר הָאֱמוּנָה. וּמִי שֶׁלֹּא נִמּוֹל וְלֹא נִקְשָׁר בּוֹ, כָּתוּב בּוֹ (ויקרא כב) וְכָל זָר לֹא יֹאכַל קֹדֶשׁ. (שמות יג) וְעָל עָרֵל לֹא יֹאכַל בּוֹ. שֶׁהֲרֵי הִתְעוֹרְרָה רוּחַ הַטֻּמְאָה שֶׁמִּצִּדּוֹ, וּבָא לְהִתְעָרֵב בַּקְּדֻשָּׁה. בָּרוּךְ הָרַחֲמָן שֶׁהִפְרִיד אֶת יִשְׂרָאֵל בָּנָיו, רְשׁוּמִים בְּרֹשֶׁם קָדוֹשׁ, מֵהֶם וּמִזֻּהַמְתָּם. עֲלֵיהֶם כָּתוּב, (ירמיה כ) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. וּמִשּׁוּם כָּךְ, (מיכהז) תִּתֵּן אֱמֶת לְיַעֲקֹב, וְלֹא לְאַחֵר. תּוֹרַת אֱמֶת, לְזֶרַע אֱמֶת. בָּא רַבִּי אֶלְעָזָר וּנְשָׁקוֹ עַל יָדוֹ."],[1,"","רַבִּי חִזְקִיָּה אָמַר, כָּתוּב (שמואל א יב) כִּי לֹא יִטֹּשׁ ה' אֶת עַמּוֹ בַּעֲבוּר שְׁמוֹ וְגוֹ'. כִּי לֹא יִטֹּשׁ ה' אֶת עַמּוֹ, מָה הַטַּעַם בַּעֲבוּר שְׁמוֹ הַגָּדוֹל? כִּי הַכֹּל נִקְשָׁר זֶה עִם זֶה. וּבַמֶּה נִקְשְׁרוּ יִשְׂרָאֵל בַּקָּדוֹשׁ בָּרוּךְ הוּא? בְּאוֹתוֹ רֹשֶׁם קָדוֹשׁ שֶׁנִּרְשָׁם בִּבְשָׂרָם, וּמִשּׁוּם כָּךְ לֹא יִטֹּשׁ ה' אֶת עַמּוֹ. וְלָמָּה? בַּעֲבוּר שְׁמוֹ הַגָּדוֹל שֶׁנִּרְשָׁם בָּהֶם."],[2,"","לָמַדְנוּ, הַתּוֹרָה נִקְרֵאת בְּרִית, וְהַקָּדוֹשׁ בָּרוּךְ הוּא נִקְרָא בְּרִית, וְהָרֹשֶׁם הַקָּדוֹשׁ הַזֶּה נִקְרָא בְּרִית. וְלָכֵן הַכֹּל נִקְשָׁר זֶה עִם זֶה וְלֹא נִפְרָד זֶה מִזֶּה. אָמַר לוֹ רַבִּי יֵיסָא, תּוֹרָה וְיִשְׂרָאֵל - יָפֶה, אֲבָל הַקָּדוֹשׁ בָּרוּךְ הוּא מִנַּיִן לָנוּ שֶׁנִּקְרָא בְּרִית? אָמַר לוֹ, שֶׁכָּתוּב (תהלים קו) וַיִּזְכֹּר לָהֶם בְּרִיתוֹ, וַהֲרֵי נוֹדָע, וַהֲרֵי נִתְבָּאֵר."],[3,"","וְאֶת חֻקֹּתַי תִּשְׁמְרוּ (ויקרא יח). חֻקֹּתַי - אֵלּוּ הֵן הַנְהָגוֹת הַמֶּלֶךְ. מִשְׁפָּטַי - אֵלּוּ הֵן גְּזֵרוֹת הַתּוֹרָה. רַבִּי יְהוּדָה אָמַר, כָּל אוֹתָן הַנְהָגוֹת שֶׁנִּקְרָאוֹת צֶדֶק, נִקְרְאוּ חֻקֹּתַי, וְהֵן גְּזֵרַת הַמֶּלֶךְ. וּבְכָל מָקוֹם שֶׁנִּקְרָא מִשְׁפָּט, הֵן נִקְרָאוֹת דִּינוֹ שֶׁל הַמֶּלֶךְ, שֶׁהוּא הַמֶּלֶךְ הַקָּדוֹשׁ, הַקָּדוֹשׁ בָּרוּךְ הוּא הַמֶּלֶךְ שֶׁכָּל הַשָּׁלוֹם שֶׁלּוֹ, שֶׁהוּא הַמֶּלֶךְ הַקָּדוֹשׁ בְּמָקוֹם שֶׁשְּׁנֵי חֲלָקִים אֲחוּזִים זֶה עִם זֶה. וְעַל זֶה כָּתוּב, (תהלים פט) צֶדֶק וּמִשְׁפָּט מְכוֹן כִּסְאֶךְ, וְהֵם דִּין וְרַחֲמִים. וּמִשּׁוּם כָּךְ חֹק וּמִשְׁפָּט. וְעַל זֶה כָּתוּב, (שם קמז) חֻקָּיו וּמִשְׁפָּטָיו לְיִשְׂרָאֵל. לְיִשְׂרָאֵל וְלֹא לִשְׁאָר הָעַמִּים."],[4,"","מַה כָּתוּב אַחֲרָיו? לֹא עָשָׂה כֵן לְכָל גּוֹי. וְשָׁנִינוּ, אַף עַל גַּב שֶׁנִּמּוֹל וְלֹא עָשָׂה אֶת מִצְווֹת הַתּוֹרָה, הֲרֵי הוּא כְּמוֹ גּוֹי בַּכֹּל, וְאָסוּר לְלַמְּדוֹ דִּבְרֵי תוֹרָה. וְעַל זֶה שָׁנִינוּ, (שמות כ) מִזְבַּח אֲבָנִים, זֶה מִזְבַּח אֲבָנִים מַמָּשׁ. וַהֲרֵי קְשִׁי הַלֵּב עוֹמֵד בִּמְקוֹמוֹ, וְהַזֻּהֲמָה לֹא פָסְקָה מִמֶּנּוּ. מִשּׁוּם כָּךְ לֹא עוֹלָה בְיָדוֹ אוֹתָהּ מִילָה וְלֹא מוֹעִילָה לוֹ. וְעַל זֶה כָּתוּב, כִּי חַרְבְּךְ הֵנַפְתָּ עָלֶיהָ וַתְּחַלְלֶהָ."],[5,"","מִשּׁוּם כָּךְ, לֹא עָשָׂה כֵן לְכָל גּוֹי סְתָם. וּמִשְׁפָּטִים בַּל יְדָעוּם, לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים. דָּבָר אַחֵר (קטן), לֹא נוֹתְנִים לָהֶם כָּל שֶׁכֵּן סוֹדוֹת תּוֹרָה וְהַנְהָגוֹת הַתּוֹרָה. וְכָתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ, (תהלים קמד) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ אַשְׁרֵי הָעָם שֶׁה' אֱלֹהָיו."],[6,"","מִשְׁנָה, בְּדַרְכֵי הָאוֹרוֹת הָעֶלְיוֹנִים. אַרְבָּעָה מַפְתְּחוֹת נַעֲשׂוּ לְאַרְבַּעַת צִדְדֵי הָעוֹלָם, וּבְזָוִיּוֹתֵיהֶם נִמְצָאִים אֶחָד לְצַד אַרְבָּעָה, וְאַרְבָּעָה לְצַד אֶחָד. נֶחְקָקִים (נחלקו) בְּגָוֶן אֶחָד. בְּאוֹתוֹ גָּוֶן, תְּכֵלֶת וְאַרְגָּמָן וְצֶבַע זוֹהֵר וְלָבָן וְאָדם. זֶה נִכְנָס לַגָּוֶן שֶׁל חֲבֵרוֹ, וְשֶׁלּוֹ רָשׁוּם בּוֹ."],[7,"","אַרְבָּעָה רָאשִׁים עָלוּ כְאֶחָד, וּבִדְיוֹקָן אֶחָד נִדְבָּקִים. רֹאשׁ אֶחָד עוֹלֶה מִתּוֹךְ הָרַחְצָה שֶׁרוֹחֵץ. שְׁתֵּי אַיָּלוֹת קְצוּבוֹת בְּשִׁעוּר אֶחָד עוֹלוֹת מֵאוֹתָהּ רַחְצָה, שֶׁכָּתוּב (שיר ד) כְּעֵדֶר הַקְּצוּבוֹת שֶׁעָלוּ מִן הָרַחְצָה. בַּשֵּׂעָר שֶׁלָּהֶם מַרְאֶה שֶׁל אֶבֶן טוֹבָה שֶׁל אַרְבָּעָה גְוָנִים."],[8,"","אַרְבַּע כְּנָפַיִם שֶׁמְּכַסּוֹת עַל הַגּוּף, וְיָדַיִם קְטַנּוֹת תַּחַת כַּנְפֵיהֶם. וְחָמֵשׁ בְּחָמֵשׁ חֲקוּקִים. טָסִים (שואפים) לְמַעְלָה לְמַעְלָה מִן הַהֵיכָל, שֶׁהוּא יְפֵה תֹאַר וְנָאֶה לְמַרְאֶה."],[9,"","עָלֶם אֶחָד יֶלֶד יוֹצֵא שְׁנוּן חֶרֶב, שֶׁמִּתְהַפֶּכֶת לִגְבָרִים וְלִנְקֵבוֹת. לוֹקְחִים מְדִידַת הָאֵיפָה בֵּין שָׁמַיִם וּבֵין אָרֶץ. לִפְעָמִים לוֹקְחִים (עולים) לָהּ בְּכָל הָעוֹלָם, וְכָל הַמְּדִידוֹת מוֹדְדִים בָּהּ, שֶׁכָּתוּב אֵיפַת צֶדֶק וְגוֹ'."]]],[["חַד חֵיזוֹ דִּבְדוֹלְחָא, קַיְּימָא עַל חַרְבָּא חַד, בְּרֵישָׁא דְּהַהוּא רַבְיָא (נ\"א חרבא) מְלָהֲטָא סוּמָקָא מִגּוֹ בְּדוֹלְחָא. תְּרֵין סִטְרִין מֵהַאי גִּיסָא וּמֵהַאי גִּיסָא, אִתְחֲזֵי הַהוּא חַרְבָּא, בִּרְשִׁימִין עֲמִיקִין, חַד גְּבָר תַּקִּיף, עוֹלְמָא דְּקַיְּימָא בי\"ג עָלְמִין. חַגִיר הַהוּא חַרְבָּא, לְמֶעְבַּד נוּקְמִין. עִמֵּיהּ חַגִּירִין שִׁתִּין אָחֳרָנִין, כֻּלְּהוּ מִשְׁתַלְחֶפֵי (נ\"א מתיילפי) (ס\"א משלפי) נַצְחִין קְרָבָא, הֲדָא הוּא דִכְתִיב, (תהילים מ״ה:ד׳) חֲגוֹר חַרְבְּךָ עַל יָרֵךְ גִּבּוֹר הוֹדְךָ וַהֲדָרֶךָ. וּכְתִיב (שיר השירים ג׳:ח׳) כֻּלָּם אֲחוּזֵי חֶרֶב מְלוּמְּדֵי מִלְחָמָה וְגוֹ'. בְּכַמָּה גַּוְונִין מִתְהַפְּכִין אַנְפַּיְיהוּ, לֵית דְּיֵדַע לוֹן, בַּר חַד תּוֹלַעְתָּא דְּשָׁאט (ס\"א דשארי) בֵּין נוּנֵי יַמָּא, כָּל אֲבָנִין דְּאַעְבָּר עָלַיְיהוּ מִתְבַּקְּעִין.","בְּהַהוּא זִמְנָא, קָלָא דְּנָפִיק מֵאִינּוּן דַּחֲגִירֵי חַרְבָּא, מְבָקַע תִּמְנֵיסָר טוּרִין רַבְרְבִין, וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ. כֻּלְּהוּ עָלְמָא סְתִימִין עַיְינִין, אֲטִימִין לִבָּא, לֵית מַאן דְּיַשְׁגַּח דְּהָא בִּנְיָינָא לִסְתּוֹר כַּד עַבְדִּין עוֹבָדָן דְּלָא מִתְכַּשְּׁרָן, סָאטִין מֵאָרְחָא דְּתַקְּנָא, יְמִינָא אַעְדֵּי, וּשְׂמָאלָא שַׁלְטָא, כְּדֵין עֶרְיָין אִשְׁתְּכָחוּ. וַוי לְחַיָּיבַיָּא דְּגַרְמִין דָּא בְּעָלְמָא, דְּהָא לָא מִתְבָּרְכִין לְעֵילָּא, עַד דְּיִשְׁתְּצוּן אִינּוּן לְתַתָּא. הֲדָא הוּא דִכְתִיב, (תהילים ק״ד:ל״ה) וּרְשָׁעִים עוֹד אֵינָם בָּרַכִי נַפְשִׁי אֶת יְיָ' הַלְלוּיָהּ. (ע\"כ).","(ויקרא ח\"י) עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה רִבִּי חִיָּיא פָּתַח. (שיר השירים ב׳:ג׳) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים וְגוֹ'. הַאי קְרָא אוּקְמוּהָ חַבְרַיָּיא, אֲבָל כַּמָה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל קָמֵי קוּדְשָׁא בְּרִיךְ הוּא. דְּהִיא מְשַׁבַּחַת לֵיהּ בְּהַאי. הָכָא אִית לְאִסְתַּכְּלָא, אֲמַאי מְשַׁבַּחַת לֵיהּ בְּתַפּוּחַ, וְלָא בְּמִלָּה אָחֳרָא, אוֹ בִּגְוָונִין אוֹ בְּרֵיחָא אוֹ בְּטַעְמָא.","אֲבָל הוֹאִיל וּכְתִיב תַּפּוּחַ, בְּכֹלָּא הִיא מְשַׁבַּחַת לֵיהּ, בִּגְוָונִין, בְּרֵיחָא, וּבְטַעְמָא. מַה תַּפּוּחַ הוּא אַסוּותָא לְכֹלָּא, אוּף קוּדְשָׁא בְּרִיךְ הוּא אַסוּותָא לְכֹלָּא. מַה תַּפּוּחַ אִשְׁתְּכַח בִּגְוָונֵי, כְּמָה דְּאוֹקִימְנָא, אוּף קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בִּגְוָונִין עִלָּאִין. מַה תַּפּוּחַ אִית בֵּיהּ רוּחָא דָּקִיק מִכָּל שְׁאָר אִילָנֵי, אוּף קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בֵּיהּ (הושע י״ד:ז׳) וְרֵיחַ לוֹ כַּלְּבָנוֹן. מַה תַּפּוּחַ טַעְמֵיהּ מְתִיקָא, אוּף קוּדְשָׁא בְּרִיךְ הוּא כְּתִיב בֵּיהּ (שיר השירים ה׳:ט״ז) חִכּוֹ מַמְתַּקִּים.","וְקוּדְשָׁא בְּרִיךְ הוּא מְשַׁבַּח לָהּ לִכְּנֶסֶת יִשְׂרָאֵל כְּשׁוֹשַׁנָּה, וְהָא אוֹקִימְנָא מִלֵי, אֲמַאי כְּשׁוֹשַׁנָּה, וְהָא אִתְּמַר. רִבִּי יְהוּדָה אָמַר, בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאֵי בְּעָלְמָא, כְּנֶסֶת יִשְׂרָאֵל סַלְּקָא רֵיחִין טָבִין, וּמִתְבָּרְכָא מִמַּלְכָּא קַדִּישָׁא, וְאַנְפָּהָא נְהִירִין. וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כִּבְיָכוֹל כְּנֶסֶת יִשְׂרָאֵל לָא סַלְּקָא רֵיחִין טָבִין, וְאַטְעָמַת מִסִּטְרָא אָחֳרָא מְרִירָא. כְּדֵין, כְּתִיב (איכה ב׳:א׳) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ', וְאַנְפָּהָא חֲשׁוֹכָן.","רִבִּי יוֹסֵי אָמַר, בְּשַׁעֲתָא דְּאַסְגִּיאוּ זַכָּאִין בְּעָלְמָא, כְּתִיב (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וּבְזִמְנָא דְּאַסְגִּיאוּ חַיָּיבִין בְּעָלְמָא, כְּתִיב (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ. רִבִּי חִזְקִיָּה אָמַר מֵהָכָא, (משלי ט״ז:כ״ח) וְנִרְגָּן מַפְרִיד אַלּוּף, כְּלוֹמַר פָּרִישׁ מַלְכָּא מִן מַטְרוֹנִיתָא, הֲדָא הוּא דִכְתִיב עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה.","רִבִּי אֶלְעָזָר הֲוָה יָתִיב קָמֵי אֲבוֹי, אָמַר לֵיהּ, אִי פְּרַקְלִיטָא בְּעָלְמָא בְּמַטְרוֹנִיתָא אִשְׁתְּכַח, וְאִי קַטֵיגוֹרְיָא בְּעָלְמָא, בְּמַטְרוֹנִיתָא אִשְׁתְּכַח, אֲמַאי. אָמַר לֵיהּ, לְמַלְכָּא דְּהֲוָה לֵיהּ בַּר מִמַטְרוֹנִיתָא, כָּל זִמְנָא דְּהַהוּא בְּרָא עָבִיד רְעוּתָא דְּמַלְכָּא, מַלְכָּא עָבִיד מָדוֹרֵיהּ בְּמַטְרוֹנִיתָא. וְכָל זִמְנָא דְּלָא הֲוָה הַהוּא בַּר עָבִיד רְעוּתָא דְּמַלְכָּא, מַלְכָּא פָּרִישׁ מָדוֹרֵיהּ מִמַּטְרוֹנִיתָא.","כַּךְ קוּדְשָׁא בְּרִיךְ הוּא וּכְּנֶסֶת יִשְׂרָאֵל, כָּל זִמְנָא דְּיִשְׂרָאֵל עַבְדִּין רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא שַׁוִּי מָדוֹרֵיהּ בִּכְנֶסֶת יִשְׂרָאֵל. וְכָל זִמְנָא דְּיִשְׂרָאֵל לָא עַבְדִין רְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, קוּדְשָׁא בְּרִיךְ הוּא לָא שַׁוִּי מָדוֹרֵיהּ בִּכְּנֶסֶת יִשְׂרָאֵל. מַאי טַעְמָא. בְּגִין דְּיִשְׂרָאֵל הוּא בְּרָא בּוּכְרָא דְּקוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִּיב, (שמות ד) בְּנִי בְכוֹרִי יִשְׂרָאֵל. אִמָּא, דָּא הִיא כְּנֶסֶת יִשְׂרָאֵל דִּכְתִּיב, (משלי יא) וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ.","תָּא חֲזֵי, כָּל זִמְנָא דְּיִשְׂרָאֵל רָחֲקִין מֵהֵיכָלָא דְּמַלְכָּא, כִּבְיָכוֹל מַטְרוֹנִיתָא אִתְרַחֲקַת עִמְּהוֹן. מַאי טַעְמָא. בְּגִין דְּמַטְרוֹנִיתָא לָא אַקְדִּימַת קִיסְטָא לְהַאי בַּר, לְאַלְקָאָה לֵיהּ, לְמֵיהַךְ בְּאוֹרַח מֵישָׁר. בְּגִין דְּמַלְכָּא לָא אַלְקֵי לִבְרֵיהּ לְעָלְמִין. אֶלָּא שָׁבִיק כֹּלָּא בִּידָא דְּמַטְרוֹנִיתָא, לְאַנְהָגָא הֵיכָלָא, וּלְאַלְקָאָה בְּרָהּ, וּלְדַבְּרָא לֵיהּ בְּאוֹרַח קְשׁוֹט, לָקֳבְלֵיהּ דְּמַלְכָּא."],[[0,"חד חיזו דבדולהא וכו׳:","מראה אחת של בדולח נמצאת על חרב אחת. בראש החרב ההיא לוהט צבע אדום מתוך הבדולח. מב׳ צדדים מצד זה ומצד זה, נראות בחרב ההיא, רשימות עמוקות. גבור אחד אמיץ, נער העומד בי״ג עולמות, חגור חרב ההיא לעשות נקמות. עמו חגורים חרב, ששים גבורים אחרים, כולם מלומדים לנצח מלחמה. ז״ש חגור חרבך על ירך גבור. וכתוב, כלם אחוזי חרב מלומדי מלחמה וגו'. בכמה אפנים מתהפכים פניהם, אין מי שיודע אותם, חוץ מתולעת אחת השטה בין דגי הים. כל האבנים העוברות עליהם מתבקעות."],[0,"","פירוש. מראה הבדלח, הוא לבן מעורב באדמימות, ורומזת על ב׳ קוין ימין ושמאל, שהם לבן ואדום, שה״ס הארות החסדים שהם לבן, והארת החכמה הנמשכת משמאל שהיא אדום, המעורבות זו בזו, וכלולות זו בזו ע״י קו האמצעי. ואומר, שמראה הבדלח, דהיינו החכמה והחסדים הכלולים זה בזה, שורים על החרב. ומלבד זה שורות בה ג׳ בחינות דינים שהן שורשים לכל מיני דינים שבעולם. א׳ הוא דינים דדכורא. דהיינו דינים הנמשכים משמאל בלי ימין. ב׳ הוא דינים דנוקבא הנמשכים ממסך דבינה. ג׳ הוא דינים דנוקבא הנמשכים ממסך דמלכות. באפן, שגוף החרב נמשך מהקו האמצעי, וע״כ שורה עליה מראה הבדולח, כנ״ל. ובראש החרב מתגלים דינים דדכורא שמצד שמאל. ובב' פיות החרב מתגלים ב׳ בחינות דינים דנוקבא הנ״ל. ואת החרב הזו נושא מטטרון, אשר במראה הבדלח שעל החרב עושה נקמות. להכרית הקליפות, כי אינם נכרתים אלא ע״י הארת החכמה שבמראה הבדלח. ובג׳ מיני דינים שבחרב הוא מכריח החיצונים שלא יינקו מהארת חכמה."],[0,"","וזה אמרו, \u0003חיזו דבדולחא קיימא על חרבא חד,\u0004 דהיינו התכללות החכמה והחסדים זה בזה, ע״י בחינת קו האמצעי הנמצא בגוף החרב. \u0003ברישא דההוא חרבא מלהטא סומקא מגו בדולחא,\u0004 דהיינו ששורים שם דינים דשמאל שהם אדומים. שהם בראש החרב כנ״ל. \u0003תרין סטרין מהאי גיסא ומהאי גיסא אתחזי ההוא חרבא ברשימין עמיקין,\u0004 שהם ב׳ בחינות דינים דנוקבא, מצד אחד הדינים דמסך דבינה, ומצד אחד הדינים דמסך דמלכות. \u0003חד גבר תקיף,\u0004 היינו מטטרון, \u0003עולמא דקיימא בי״ג עלמין,\u0004 דהיינו המרכבה של המלכות המתפשטת בי״ג עולמות, שהם חו״ב תו״מ שבכל אחת ג׳ קוין, שהם י״ב עולמות, ועם הארת המלכות שעליהם הם י״ג עולמות, ומטטרון עומד ותוקף במקום י״ג עולמות אלו. \u0003הגיר ההוא חרבא למעבד נוקמין,\u0004 כי ההארת חכמה שבה, מכלה את הקליפות ועושה נקמות בהן."],[0,"","ותחת ידו של מטטרון נמצאים ששים גבורים (כמ״ש באורך לעיל אות ע״א ע״ש) וז״ש \u0003עמיה חגירין שתין אחרנין\u0004 וכו'. ונתבאר שם שהם נמשכים מחג״ת נה״י דז״א, והיינו מעת שז״א היה במצב מוחין דו״ק, שקו השמאל הוא במחלוקת שם עם קו הימין, וע״כ המוחין ההם מטולטלים, פעם הם דין ופעם הם רחמים. וז״ש, \u0003בכמה גוונין מתהפכין אנפייהו,\u0004 דהיינו פעם לדין ופעם לרחמים. וע״כ \u0003לית דידע לון,\u0004 שאי אפשר להשיגם, מחמת התהפכותם. עד שהקו האמצעי מעורר, את המסך דחירק שבו, ואז מתרצה קו השמאל להתיחד בימין, ונעשה בסוד הרחמים (כנ״ל לך י״ג ד\"ה ונתבאר) והמסך דחירק מכונה, \u0003תולעת,\u0004 וז״ש \u0003בר חד תולעתא\u0004 (דפו״י דף ע״ד ע״א) שהיא מיחדת אותם עם הימין, ומעמידה אותם בסוד הרחמים ואינם מתהפכים עוד לדין. אמנם מחמת המסך הזה, מתבקע קו השמאל, שחצי מדרגתו העליונה, שהיא הג״ר דחכמה, נעלמת, ונשאר רק בו״ק דחכמה, דהיינו בחצי המדרגה התחתונה. וז״ש, \u0003דשאט בין נוני ימא,\u0004 דהיינו בין מדרגות החכמה שבשמאל הנקראות דגת הים, \u0003כל אבנין דאעבר עלייהו מתבקעין,\u0004 שכל המדרגות המכוונות אבנים, העוברות שמה מוכרחות להתבקע לב' חצאים, שחצים העליון נעלם, וחצים התחתון נשאר. שזה נעשה מכח המסך דחירק המיחד ימין ושמאל, (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) שהקו האמצעי מתקן את השמאל שלא יאיר ממעלה למטה שה״ס ג״ר אלא ממטה למעלה שה״ס ו״ק דחכמה. ע״ש."],[1,"בההוא זמנא קלא וכו׳:","בזמן ההוא, שהמדרגות דשמאל מתבקעות מחמת התולעת, הקול שיוצא מאלו חגורי חרב, דהיינו מששים גבורים, מבקע שמונה עשר הרים גדולים שהם חג״ת נה״י שבכל אחד ג׳ קוים, שבחינת ג״ר דחכמה מסתלקת מהם ואין מי שיטה אזנו. להשמר מלהמשיך הג״ר דחכמה. וע״כ כל העולם הם סתומי עינים ואטומי הלב. אין מי שיסתכל שבנין הזה, של ג״ר דשמאל, עומד לסתור. כשעושים מעשים שאינם כשרים, וסרים מדרך המתוקן, הוסר הימין, שהוא הארת החסדים, והשמאל שולט בלי ימין, אז נמצאות עריות. דהיינו הדינים המתגלים בבינה ומלכות, שה״ס גילוי ערוה, אוי לרשעים שגורמים זאת בעולם, כי לא יתברכו למעלה מטרם שיכלו אלו הרשעים למטה. ז״ש ורשעים עוד אינם ברכי נפשי את ה׳ הללויה."],[2,"ערות אביך וערות אמך לא תגלה:","ר׳ חייא פתח, כתפוח בעצי היער כן דודי בין הבנים וגו'. מקרא זה העמידוהו החברים. אבל כמה חביבה כנסת ישראל לפני הקב״ה שהיא משבחת לו בכתוב הזה. כאן יש להסתכל. למה משבחת אותו בתפוח, ולא בדבר אחר, או בדבר שיש לו צבע, או ריח, או טעם."],[3,"אבל הואיל וכתיב וכו׳:","ומשיב. אבל כיון שכתוב \u0003תפוח,\u0004 נמצאת משבחת אותו בכל, בצבעים בריח ובטעם, כי מה תפוח הוא רפואה לכל, אף הקב״ה הוא רפואה לכל. מה התפוח נמצא בצבעים, כמו שהעמדנו, שיש בו לבן אדום ירוק, אף הקב״ה נמצא בגוונים עליונים, שהם חסד גבורה ת״ת, שה״ס לבן אדום ירוק. מה תפוח יש בו ריח דק, יותר מכל שאר אילנות, אף הקב״ה, כתוב בו, וריח לו כלבנון. מה תפוח, טעמו מתוק, אף הקב״ה כתוב בו, חכו ממתקים."],[4,"וקב״ה משבח לה וכו׳:","והקב״ה משבח לכנסת ישראל, \u0003כשושנה.\u0004 וכבר העמדנו הדברים, למה שיבח אותה כשושנה וכבר למדנו. ר׳ יהודה אמר, בשעה שצדיקים נתרבו בעולם, כנסת ישראל, שהיא המלכות, מעלה ריחות טובים, שה״ס הארת חכמה המאירה ממטה למעלה, כמו ריח, ומתברכת, בחסדים, ממלך הקדוש, ופניה מאירים. ובשעה שהרשעים נתרבו בעולם, כביכול, כנסת ישראל אינה מעלה ריחות טובים, וטעמת מיניקת הס״א המרה, אז כתוב, השליך משמים ארץ וגו'. דהיינו שנתבטל הזווג, דז״א שנקרא שמים, והמלכות הנקראת ארץ, ופניה חשכים."],[5,"ר׳ יוסי אמר וכו׳:","רי״א, בשעה שהצדיקים נתרבו בעולם, כתוב, שמאלו תחת לראשי וימינו תחבקני. דהיינו שהימין ושמאל מתיחדים זה בזה. ובשעה שמתרבים רשעים בעולם כתוב, השיב אחור ימינו. והשמאל שולט בלי ימין. שאז כל הדינים נשפעים ממנו. ר׳ חזקיה אמר מכאן, שכתוב, ונרגן מפריד אלוף, כלומר שהמלך נפרד מן המלכה, מחמת הרשע שנקרא נרגן. ז״ש ערות אביך וערות אמך לא תגלה. דהיינו שלא תגרום גילוי דינים למעלה ליניקת הס״א, שעי״ז נפרד הזווג הקדוש."],[6,"ר׳ אלעזר הוה וכו׳:","ר״א היה יושב לפני אביו, אמר לו, אם יש מליץ טוב בעולם, הוא מגיע להמלכה, ואם יש מלמד חוב בעולם, הוא מגיע אל המלכה. ולא למעלה מהמלכות. ושאל למה הוא כך. אמר לו. בדומה למלך שהיה לו בן מהמלכה, כל זמן שהבן עשה רצונו של המלך, המלך שם משכנו בהמלכה. וכל זמן שהבן לא עשה רצונו של המלך, המלך מפריד משכנו מן המלכה."],[7,"כך קב״ה וכ״י וכו׳:","כך הקב״ה וכנסת ישראל. כל זמן שישראל עושים רצונו של הקב״ה, הקב״ה משים משכנו בכנסת ישראל. וכל זמן שישראל אינם עושים רצונו של הקב״ה, אין הקב״ה משים משכנו בכנסת ישראל. מהו הטעם, הוא משום שישראל הם בנו בכורו של הקב״ה, שכתוב, בני בכורי ישראל. וכנסת ישראל היא אמם של ישראל, שכתוב, ואל תטוש תורת אמך."],[8,"ת״ח כל זמנא וכו׳:","בוא וראה, כל זמן שישראל רחוקים מהיכל המלך, כביכול המטרוניתא מתרחקת עמהם מן המלך. מהו הטעם. הוא, משום שהמלכה לא הקדימה שבט לאותו הבן להכותו שילך בדרך הישר. כי המלך אינו מכה בנו לעולם, אלא עוזב הכל בידי המלכה, שתנהיג היכלו, ושתכה את בנה, ושהנהיגו בדרך אמת כנגד המלך. \u0003קיסטא,\u0004 פירושו שבט, לפי הענין."]],[[0,"","מַרְאֶה אֶחָד שֶׁל בְּדוֹלַח עוֹמֵד עַל חֶרֶב אַחַת, בְּרֹאשׁ אוֹתוֹ יֶלֶד (חרב) מְלַהֵט אָדם מִתּוֹךְ הַבְּדוֹלַח. שְׁנֵי צְדָדִים מִצַּד זֶה וּמִצַּד זֶה, נִרְאֵית אוֹתָהּ הַחֶרֶב בִּרְשָׁמִים עֲמֻקִּים, גֶּבֶר אֶחָד תַּקִּיף, סֻלָּם שֶׁעוֹמֵד בִּשְׁלֹשָׁה עָשָׂר עוֹלָמוֹת חָגוּר אוֹתָהּ הַחֶרֶב לַעֲשׂוֹת נְקָמוֹת, וְעִמּוֹ חֲגוּרִים שִׁשִּׁים אֲחֵרִים, כֻּלָּם מֻחְלָפִים (מלמדי) (שולפי) מְנַצְּחֵי קְרָב. זֶהוּ שֶׁכָּתוּב (תהלים מה) חֲגוֹר חַרְבְּךְ עַל יָרֵךְ גִּבּוֹר הוֹדְךְ וַהֲדָרֶךְ. וְכָתוּב (שיר ג) כֻּלָּם אֲחֻזֵי חֶרֶב מְלֻמְּדֵי מִלְחָמָה וְגוֹ'. בְּכַמָּה גְוָנִים מִתְהַפְּכִים פְּנֵיהֶם, שֶׁאֵין מַכִּיר אוֹתָם פְּרָט לְתוֹלַעַת אַחַת שֶׁשָּׁטָה (ששורה) בֵּין דְּגֵי הַיָּם, כָּל הָאֲבָנִים שֶׁעוֹבְרוֹת עֲלֵיהֶם נִבְקָעוֹת."],[1,"","בְּאוֹתוֹ זְמַן הַקּוֹל שֶׁיּוֹצֵא מֵאוֹתָם חֲגוּרֵי הַחֶרֶב, מְבַקֵּעַ שְׁמוֹנָה עָשָׂר הָרִים גְּדוֹלִים, וְאֵין מִי שֶׁיַּרְכִּין אָזְנָיו. כָּל הָעוֹלָם סְתוּמֵי עֵינַיִם, אֲטוּמֵי לֵב, אֵין מִי שֶׁיַּשְׁגִּיחַ, שֶׁהֲרֵי הַבִּנְיָן סָתוּר כְּשֶׁעוֹשִׂים מַעֲשִׂים שֶׁאֵינָם כְּשֵׁרִים, סוֹטִים מִדֶּרֶךְ תְּקִינָה, הַיָּמִין סָרָה וְהַשְּׂמֹאל שׁוֹלֶטֶת, וְאָז מְצוּיוֹת עֲרָיוֹת. אוֹי לָרְשָׁעִים שֶׁגּוֹרְמִים אֶת זֶה בָּעוֹלָם, שֶׁהֲרֵי אֵין מִתְבָּרְכִים לְמַעְלָה עַד שֶׁיִּכְלוּ אוֹתָם לְמַטָּה. זֶהוּ שֶׁכָּתוּב (תהלים קד) וּרְשָׁעִים עוֹד אֵינָם בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ. (עד כאן)"],[2,"","עָרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. רַבִּי חִיָּיא פָּתַח, (שיר ב) כְּתַפּוּחַ בַּעֲצֵי הַיַּעַר כֵּן דּוֹדִי בֵּין הַבָּנִים וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים, אֲבָל כַּמָּה חֲבִיבָה כְּנֶסֶת יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהִיא מְשַׁבַּחַת אוֹתוֹ בָּזֶה. כָּאן יֵשׁ לְהִתְבּוֹנֵן, לָמָּה הִיא מְשַׁבַּחַת אוֹתוֹ בְּתַפּוּחַ וְלֹא בְּדָבָר אַחֵר, אוֹ בִּגְוָנִים אוֹ בְּרֵיחַ אוֹ בְּטַעַם?"],[3,"","אֲבָל הוֹאִיל וְכָתוּב תַּפּוּחַ, בַּכֹּל הִיא מְשַׁבַּחַת אוֹתוֹ - בַּגְּוָנִים, בָּרֵיחַ, וּבַטַּעַם. מַה תַּפּוּחַ הוּא רְפוּאָה לַכֹּל - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא רְפוּאָה לַכֹּל. מַה תַּפּוּחַ נִמְצָא בִּגְוָנִים, כְּמוֹ שֶׁבֵּאַרְנוּ - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בִּגְוָנִים עֶלְיוֹנִים. מַה תַּפּוּחַ יֵשׁ בּוֹ רֵיחַ דַּק מִכָּל שְׁאָר הָעֵצִים - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתוּב בּוֹ וְרֵיחַ לוֹ כַּלְּבָנוֹן. מַה תַּפּוּחַ טַעֲמוֹ מָתוֹק - אַף הַקָּדוֹשׁ בָּרוּךְ הוּא כָּתוּב בּוֹ חִכּוֹ מַמְתַּקִּים."],[4,"","וְהַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁבֵּחַ אֶת כְּנֶסֶת יִשְׂרָאֵל כְּמוֹ שׁוֹשַׁנָּה, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים לָמָּה כְּמוֹ שׁוֹשַׁנָּה, וַהֲרֵי נִתְבָּאֵר. רַבִּי יְהוּדָה אָמַר, בְּשָׁעָה שֶׁמִּתְרַבִּים צַדִּיקִים בָּעוֹלָם, כְּנֶסֶת יִשְׂרָאֵל מַעֲלָה רֵיחוֹת טוֹבִים, וּמִתְבָּרֶכֶת מִן הַמֶּלֶךְ הַקָּדוֹשׁ, וּפָנֶיהָ מְאִירִים. וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, כִּבְיָכוֹל אֵין כְּנֶסֶת יִשְׂרָאֵל מַעֲלָה רֵיחוֹת טוֹבִים, וְטוֹעֶמֶת מֵהַצַּד הָאַחֵר הַמַּר, אָז כָּתוּב (איכה ב) הִשְׁלִיךְ מִשָּׁמַיִם אֶרֶץ וְגוֹ', וּפָנֶיהָ חֲשׁוּכִים."],[5,"","רַבִּי יוֹסֵי אָמַר, בְּשָׁעָה שֶׁמִּתְרַבִּים צַדִּיקִים בָּעוֹלָם, כָּתוּב (שם ב) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וִימִינוֹ תְּחַבְּקֵנִי. וּבִזְמַן שֶׁמִּתְרַבִּים רְשָׁעִים בָּעוֹלָם, כָּתוּב הֵשִׁיב אָחוֹר יְמִינוֹ. רַבִּי חִזְקִיָּה אָמַר מִכָּאן, (משלי יז) וְנִרְגָּן מַפְרִיד אַלּוּף, כְּלוֹמַר, מַפְרִיד אֶת הַמֶּלֶךְ מֵהַגְּבִירָה. זֶהוּ שֶׁכָּתוּב עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה."],[6,"","רַבִּי אֶלְעָזָר הָיָה יוֹשֵׁב לִפְנֵי אָבִיו. אָמַר לוֹ, אִם פְּרַקְלִיט יֵשׁ בָּעוֹלָם, הוּא נִמְצָא עִם הַגְּבִירָה. וְאִם יֵשׁ בָּעוֹלָם קָטֵגוֹר, הוּא נִמְצָא עִם הַגְּבִירָה. לָמָּה? אָמַר לוֹ, לְמֶלֶךְ שֶׁהָיָה לוֹ בֵּן מִן הַגְּבִירָה - כָּל זְמַן שֶׁאוֹתוֹ הַבֵּן עוֹשֶׂה אֶת רְצוֹן הַמֶּלֶךְ, הַמֶּלֶךְ שָׂם מְדוֹרוֹ עִם הגבירה. וכל זמן שאותו בן לא עוֹשֶׂה אֶת רְצוֹן הַמֶּלךְ, מַפְרִיד אֶת מְדוֹרוֹ מִן הַגְּבִירָה."],[7,"","כָּךָ הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל - כָּל זְמַן שֶׁיִּשְׂרָאֵל עוֹשִׂים אֶת רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם מְדוֹרוֹ עִם כְּנֶסֶת יִשְׂרָאֵל. וְכָל זְמַן שֶׁאֵין יִשְׂרָאֵל עוֹשִׂים אֶת רְצוֹנוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֵין הַקָּדוֹשׁ בָּרוּךְ הוּא שָׂם מְדוֹרוֹ עִם כְּנֶסֶת יִשְׂרָאֵל. מָה הַטַּעַם? כִּי יִשְׂרָאֵל הוּא בְּנוֹ הַבְּכוֹר שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב בְּנִי בְכֹרִי יִשְׂרָאֵל. הָאֵם זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁכָּתוּב (משלי א) וְאַל תִּטֹּשׁ תּוֹרַת אִמֶּךְ."],[8,"","בֹּא רְאֵה, כָּל זְמַן שֶׁיִּשְׂרָאֵל רְחוֹקִים מֵהֵיכַל הַמֶּלֶךְ, כִּבְיָכוֹל הַגְּבִירָה הִתְרַחֲקָה עִמָּהֶם. מָה הַטַּעַם? כִּי הַגְּבִירָה לֹא הִקְדִּימָה שִׁבְטָהּ לַבֵּן הַזֶּה לְהַלְקוֹתוֹ כְּדֵי לָלֶכֶת בְּדֶרֶךְ יְשָׁרָה, כִּי הַמֶּלֶךְ לֹא מַלְקֶה אֶת בְּנוֹ לְעוֹלָמִים, אֶלָּא מַשְׁאִיר הַכֹּל בְּיַד הַגְּבִירָה לְהַנְהִיג אֶת הַהֵיכָל וּלְהַלְקוֹת אֶת בְּנָהּ וּלְהַנְהִיגוֹ בְּדֶרֶךְ הָאֱמֶת כְּנֶגֶד הַמֶּלֶךְ."]]],[["וְרָזָא דְּמִלָּה דִּכְתִּיב, (משלי ל״א:א׳) דִּבְרֵי לְמוֹאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ (אמו ודאי), דָּא בַּת שֶׁבַע, וְהָא אִתְּמַר כְּתִיב, (משלי י׳:א׳) מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי. חָמֵי מַה כְּתִיב, בֵּן חָכָם יְשַׂמַּח אָב, בְּעוֹד דְּהַאי בַּר אָזִיל בְּאוֹרַח מֵישָׁר, וְהוּא חַכִּימָא, יְשַׂמַּח אָב (כלל), דָּא מַלְכָּא קַדִּישָׁא לְעֵילָּא. יְשַׂמַּח אָב סְתָם. אִשְׁתְּכַח הַאי בַּר בְּאוֹרְחָא תְּקָלָא, מַה כְּתִיב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי, דָּא כְּנֶסֶת יִשְׂרָאֵל. וְרָזָא דְּמִלָּה כְּתִיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֲכֶם שֻׁלְּחָה אִמְּכֶם.","תָּא חֲזֵי, לָא אִשְׁתְּכַח חֶדְוָותָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, כְּיוֹמָא דְּסָלִיק שְׁלֹמֹה לְחָכְמְתָא, וְאָמַר שִׁיר הַשִּׁירִים. כְּדֵין נְהִירוּ אַנְפּוֹי דְּמַטְרוֹנִיתָא, וְאָתֵי מַלְכָּא לְמִשְׁרֵי מָדוֹרֵיהּ עִמָּהּ. הֲדָא הוּא דִכְתִיב, (מלכים א ה׳:י׳) וַתֵּרֶב חָכְמַת שְׁלֹמֹה וְגוֹ'. מַאי וַתֵּרֶב. דְּסַלְּקָא שְׁפִּירוּ דְּמַטְרוֹנִיתָא, וְאִתְרַבִּיאַת בְּדַרְגָּהָא עַל כָּל שְׁאָר דַּרְגִּין, בְּגִין דְּמַלְכָּא שַׁוִּי מָדוֹרֵיהּ בָּהּ. וְכָל כַּךְ לָמָּה. בְּגִין דְּאַפִּיקַת בְּרָא חַכִּימָא דָּא לְעָלְמָא. (נ\"א למלכא)","וְכַד אַפִּיקַת לֵיהּ לִשְׁלֹמֹה, לְכָל יִשְׂרָאֵל אַפִּיקַת, וְכֻלְּהוּ הֲווֹ בְּדַרְגִּין עִלָּאִין זַכָּאִין כִּשְׁלֹמֹה (ס\"א בשלמא). דְּקוּדְשָׁא בְּרִיךְ הוּא חַדֵּי בְּהוּ, וְאִינּוּן בֵּיהּ. וּבְיוֹמָא דְּשַׁכְלַל שְׁלֹמֹה בֵּיתָא לְתַתָּא, אַתְקִינַת מַטְרוֹנִיתָא בֵּיתָא לְמַלְכָּא. וְשַׁוּוּ מָדוֹרֵיהוֹן כַּחֲדָא, וּנְהִירוּ אַנְפָּהָא בְּחֶדְוָה שְׁלִימוּ. כְּדֵין אִשְׁתְּכַח חֶדְוָותָא לְכֹלָּא, לְעֵילָּא וְתַתָּא. וְכָל כַּךְ לָמָּה. בְּגִין דִּכְתִּיב, מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, דְּדַּבְּרַת לֵיהּ לִרְעוּתָא דְּמַלְכָּא.","וְכַד הַאי בַּר כְּמָה דַּאֲמֵינָא, (ס\"א דאצטריך) לָא אִתְדְּבַר לִרְעוּתֵיהּ דְּמַלְכָּא. כְּדֵין הִיא עֶרְיָיתָא דְּכֹלָּא, עֶרְיָיתָא דְּכָל סִטְרִין דְּהָא מַלְכָּא פָּרִישׁ מִמַּטְרוֹנִיתָא, וּמַטְרוֹנִיתָא אִתְרַחֲקַת מְהֵיכָלֵיהּ, וּבְגִין כָּךְ עֶרְיָיתָא הִיא דְּכֹלָּא. וְכִי לָא עֶרְיָיתָא הוּא, מַלְכָּא בְּלָא מַטְרוֹנִיתָא, וּמַטְרוֹנִיתָא בְּלָא מַלְכָּא. וְעַל דָּא כְּתִיב, עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה אִמְּךָ הִיא. אִמְּךָ הִיא וַדַּאי, וְשַׁרְיָא עִמָּךְ, בְּגִינֵי כַּךְ לֹא תְגַלֵּה עֶרְוָתָהּ.","רַבִּי שִׁמְעוֹן אָקִישׁ יְדוֹי וּבָכָה, וְאָמַר וַוי אִי אֵימָא וְגַלֵינָא רָזָא, וַוי אִי לָא אֵימָא, דְּיֵיבְדוּן חַבְרַיָּיא מִלָּה. (יחזקאל י״א:י״ג) אֲהָהּ יְיָ' אֱלֹהִים כָּלָה אַתָּה עוֹשֶׂה אֵת שְׁאֵרִית יִשְׂרָאֵל. מַאי אֲהָהּ. וּמַאי כָּלָה אַתָּה עוֹשֶׂה. אֶלָּא רָזָא דְּמִלָּה, בְּזִמְנָא דְּה' תַּתָּאָה אִתְתְּרָכַת מֵהֵיכָלָא דְּמַלְכָּא, ה' אָחֳרָא עִלָּאָה בְּגִינָהּ מַנְעַת בִּרְכָתָא. וּכְדֵין כְּתִיב, אֲהָהּ כָּלָה אַתָּה עוֹשֶׂה. בְּגִין דְּכַד אִיהִי (נ\"א האי ה') אִתְמְנָעַת מִבִּרְכָאן, ה' אָחֳרָא מַנְעַת לוֹן מִכֹּלָּא. מַאי טַעֲמָא. בְּגִין דְּבִרְכָּאן לָא מִשְׁתַּכְּחֵי, אֶלָּא בַּאֲתַר דְּשַׁרְיָין דְּכַר וְנוּקְבָּא.","וְעַל דָּא כְּתִיב, (ירמיהו כ״ה:ל׳) יְיָ' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוִהוּ. עַל נָוִהוּ מַמָּשׁ. דָּא מַטְרוֹנִיתָא, וְדָא הוּא וַדַּאי. וּמַאי אוֹמֵר. אוֹי שֶׁהֱחֶרַבְתִּי אֶת בֵּיתִי וְכוּ'. בֵּיתִי זִוּוּגָא דְּמַטְרוֹנִיתָא. וְדָא הוּא וַדַּאי, עֶרְוַת אָבִיךָ וְעֶרְוַת אִמְּךָ לֹא תְגַלֵּה. דְּהָא מִכָּל סִטְרִין עֶרְיָיתָא הוּא. וּכְדֵין, (ישעיהו נ׳:ג׳) לָבְשׁוּ שָׁמַיִם קַדְרוּת וְשַׂק הוּשַׂם כְּסוּתָם דְּהָא אֲתַר אַחֲסָנַת בִּרְכָאן דְּמַבּוּעִין דְּנַחֲלִין דַּהֲווֹ נְגִּידִין וְשַׁקְיָין כַּדְקָא חֲזוּ, אִתְמְנָעוּ.","תָּנֵינָן, כַּד אִתְפְּרַשׁ מַלְכָּא מִמַּטְרוֹנִיתָא, וּבִרְכָּאן לָא מִשְׁתַּכְּחָן, כְּדֵין אִקְרֵי ו\"י. מַאי טַעְמָא ו\"י. דְּתַנְיָא, רֵישָׁא דִּיְּסוֹד י', דְּהָא יְסוֹד ו' זְעֵירָא הוּא, וְקוּדְשָׁא בְּרִיךְ הוּא ו' רַבְרְבָא עִלָּאָה. וְעַל דָּא כְּתִיב וָ\"ו תְּרֵין וָוִין כַּחֲדָא, וְרֵישָׁא דְּהַאי יְסוֹד י' הוּא. וְכַד אִתְרַחֲקַת מַטְרוֹנִיתָא מִמַּלְכָּא, וּבִרְכָּאן אִתְמְנָעוּ מִמַּלְכָּא, וְזִוּוּגָא לָא אִשְׁתְּכַח בְּרֵישָׁא דִּיְּסוֹד, נָטִיל ו' עִלָּאָה לְהַאי רֵישָׁא דִּיְּסוֹד דְּהוּא י', וְנָגִיד לֵיהּ לְגַבֵּיהּ, כְּדֵין הוּא ו\"י, ו\"י לְכֹלָּא, לְעִלָּאִין וְתַתָּאִין.","וְעַל דָּא תָּנֵינָן, מִיּוֹמָא דְּאִתְחֲרִיב יְרוּשָׁלַם, בִּרְכָאן לָא אִשְׁתְּכָחוּ בְּעָלְמָא, וְלֵית לָךְ יוֹם דְּלָא אִשְׁתְּכַח בֵּיהּ לְוָוטִין, דְּהָא בִּרְכָאן אִתְמְנָעוּ בְּכָל יוֹם. אָמַר לֵיהּ, אוֹ הָכִי, אוֹ\"י אוֹ הוֹ\"י, (נ\"א או וה') מַהוּ."],[[0,"ורזא דמלה דכתיב וכו׳:","וסוד הדבר, שכתוב, דברי למואל מלך משא אשר יסרתו אמו. אמו, זו היא בת שבע. שה\"ס המלכות הנקראת בת שבע. ולמדנו, כתוב, משלי שלמה בן חכם ישמח אב ובן כסיל תוגת אמו. תוגת אמו ודאי. ראה מה כתוב, \u0003בן חכם ישמח אב,\u0004 היינו בעוד שהבן הזה הולך בדרך הישר, והוא חכם, \u0003ישמח אב,\u0004 זהו המלך הקדוש למעלה, דהיינו ז״א, כי כתוב, ישמח אב, סתם. ויורה על האב שלמעלה. ואם בן הזה נמצא בדרך כשלון, מה כתוב, ובן כסיל תוגת אמו, \u0003תוגת אמו\u0004 ודאי, שזו היא כנסת ישראל, דהיינו המלכות. וסוד הדבר, שכתוב, ובפשעכם שלחה אמכם. שהיא המלכות."],[1,"ת״ח לא אשתכח וכו׳:","בוא וראה, לא היתה נמצאת שמחה לפני הקב\"ה כאותו יום שעלה שלמה לחכמה, ואמר שיר השירים, אז האירו פניה של המלכה, והמלך בא להשרות משכנו עמה. ז״ש, ותרב חכמת שלמה וגו'. מהו ותרב. היינו שעלה היופי של המלכה, ונתגדלה במדרגותיה על כל שאר המדרגות שהיו לה באיזה זמן, משום שהמלך שם משכנו בה. וכל כך למה, משום שהוציאה בן חכם הזה לעולם."],[2,"וכד אפיקת ליה וכו׳:","וכשהוציאה, את שלמה, דהיינו שהשפיעה לו חכמתה, הוציאה לכל ישראל, וכולם היו זוכים במדרגות עליונות כמו שלמה, שהקב״ה היה שמח בהם, והם בו. וביום ששכלל שלמה הבית המקדש למטה. התקינה המלכה בית אל המלך, ושמו משכנם יחד, והאירו פניה בשמחה שלמה. אז נמצאת שמחה לכל, למעלה ולמטה. וכל כך למה. הוא, משום שכתוב, משא אשר יסרתו אמו. שהנהיגה אותו לרצון המלך."],[3,"וכד האי כד וכו׳:","וכשבן הזה, כמו שאמרתי, איני מתנהג לרצון המלך, אז היא ערוה לכל, שגורם שיתגלו דינים במלכות שה״ס גילוי ערוה, ערוה לכל הצדדים, הן לימין והן לשמאל, כי המלך נפרד מן המלכה, והמלכה נתרחקה מהיכלו, וע״כ היא ערות כל. וכי אין זה ערוה אם המלך הוא בלי המלכה, והמלכה בלי המלך. וע״כ כתוב, ערות אביך וערות אמך לא תגלה אמך היא. \u0003אמך היא\u0004 ודאי, דהיינו המלכות, ושוכנת עמך, משום זה, לא תגלה ערותה."],[4,"ר״ש אקיש ידוי וכו׳:","ר״ש הכה ידיו זו אל זו, ובכה. ואמר, אוי אם אומר ואגלה סוד, אוי אם לא אומר, ויאבדו החברים דבר זה. אהה ה׳ אלקים כלה אתה עושה את שארית ישראל. מהו אהה. ומהו כלה אתה עושה. ומשיב, אלא סוד הדבר, בזמן ש \u0003ה׳\u0004 תחתונה, דהויה, שהיא המלכות, נגרשת מהיכל המלך, \u0003ה׳\u0004 אחרת עליונה, דהויה, שהיא בינה, מונעת הברכות בשבילה, ואז כתוב א \u0003הה\u0004 כלה אתה עושה, כי הפגם מגיע ב \u0003ב'\u0004 ההין דהוי״ה בבינה ומלכות, כי כש \u0003ה׳\u0004 תחתונה נמנעת מלקבל ברכות \u0003ה׳\u0004 האחרת העליונה מונעת הברכות מכל, שאינה משפעת גם לז״א. מהו הטעם. הוא משום שהברכות אינן נמצאות אלא במקום ששורים דכר ונוקבא. וכיון שהמלכות נגרשת מז״א, אין ברכות גם בז״א, להיותו בלי נוקבא."],[5,"ועל דא כתיב וכו׳:","וע״כ כתוב, ה׳ ממרום ישאג וממעון קדשו יתן קולו שאג ישאג על נוהו. על נוהו ממש, שהיא המלכה, שאיננה, וזהו ששואג ודאי. ומהו אומר. היינו, אוי שהחרבתי את ביתי וכו׳ (כמ״ש ברכות ג.) \u0003ביתי,\u0004 פירושו זווג המלכה. וזה הוא ודאי ערות אביך וערות אמך לא תגלה. כי מכל הצדדים היא ערוה. דהיינו פגם. כי כשנפרדה המלכות שהיא אמך בעון התחתונים, מסתלקים האורות גם מז״א, ונמצא גם ז״א, שהוא אביך, נפגם. ואז לבשו \u0003שמים\u0004 קדרות ושק הושם כסותם דהיינו ז״א שנקרא שמים. כי מקום נחלת הברכות של מבועי הנחלים, שהם בבינה, שהיו נוזלים ומשקים ז״א כראוי, נמנעו ונסתלקו."],[6,"תנינן כד אתפרש וכו׳:","למדנו, כשנפרד המלך מן המלכה, וברכות אינן נמצאות. אז נקרא ז״א, \u0003וי.\u0004 שפירושו אוי לי. מהו הטעם שנקרא \u0003וי.\u0004 הוא, כי למדנו הראש של היסוד הוא \u0003י׳\u0004 כי היסוד עצמו הוא \u0003ו׳\u0004 קטנה, והקב״ה, דהיינו ז״א, הוא \u0003ו׳\u0004 גדולה עליונה. וע״כ כתוב \u0003וו\u0004 ב׳ ווין יחד, שמורים על ז״א ויסוד. וראש של יסוד הזה הוא \u0003י'.\u0004 וכשהמלכה מתרחקת מן המלך, והברכות נמנעות מן המלך, שהוא ז״א, וזווג אינו נמצא בראש היסוד, אז לוקח \u0003ו'\u0004 העליונה, שהיא ז״א, לראש הזה של היסוד, שהוא \u0003י',\u0004 ומושכו אצלו, אז נעשה הצירוף \u0003וי,\u0004 דהיינו \u0003וי\u0004 לכל, לעליונים ותחתונים. שכיון שהתחתונים אינם מקבלים אין נותנים לעליונים להשפיע להם, כנ״ל."],[7,"וע״ד תנינן וכו׳:","וע״כ למדנו, מיום שנחרב בית המקדש ברכות אינן נמצאות בעולם, ואין לך יום שלא נמצאות בו קללות, כי הברכות הצריכות לבא בכל יום נמנעות, ונעשות קללות. אמר לו, אם כן, אם כתוב, \u0003או״י\u0004 או \u0003הו״י,\u0004 ולא \u0003ו״י\u0004 מהו פירושם."]],[[0,"","וְסוֹד הַדָּבָר - שֶׁכָּתוּב (משלי לא) דִּבְרֵי לְמוּאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, (אמו ודאי) זוֹ בַּת שֶׁבַע, וַהֲרֵי נֶאֱמַר הַכָּתוּב (שם י) מִשְׁלֵי שְׁלֹמֹה בֵּן חָכָם יְשַׂמַּח אָב וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי. רְאֵה מַה כָּתוּב, בֵּן חָכָם יְשַׂמַּח אָב. בְּעוֹד שֶׁהַבֵּן הַזֶּה הוֹלֵךְ בְּדֶרֶךְ יְשָׁרָה וְהוּא חָכָם - יְשַׂמַּח אָב (כלל), זֶה הַמֶּלֶךְ הַקָּדוֹשׁ לְמַעְלָה. יְשַׂמַּח אָב סְתָם. נִמְצָא הַבֵּן הַזֶּה בְּדֶרֶךְ כּוֹשֶׁלֶת - מַה כָּתוּב? וּבֵן כְּסִיל תּוּגַת אִמּוֹ. תּוּגַת אִמּוֹ וַדַּאי, זוֹ כְּנֶסֶת יִשְׂרָאֵל. וְסוֹד הַדָּבָר כָּתוּב, (ישעיה נ) וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם."],[1,"","בֹּא רְאֵה, לֹא נִמְצֵאת שִׂמְחָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּמוֹ הַיּוֹם שֶׁעָלָה שְׁלֹמֹה לַחָכְמָה וְאָמַר שִׁיר הַשִּׁירִים. אָז הֵאִירוּ פְּנֵי הַגְּבִירָה, וּבָא הַמֶּלֶךְ לְהַשְׁרוֹת אֶת מְדוֹרוֹ עִמָּהּ. זֶהוּ שֶׁכָּתוּב (מלכים א ד) וַתֵּרֶב חָכְמַת שְׁלֹמֹה וְגוֹ'. מַה זֶּה וַתֵּרֶב? שֶׁעָלָה הַיֹּפִי שֶׁל הַגְּבִירָה וְהִתְגַּדְּלָה בְדַרְגוֹתֶיהָ עַל כָּל שְׁאָר הַדְּרָגוֹת, כִּי הַמֶּלֶךְ שָׂם אֶת מְדוֹרוֹ עִמָּהּ. וְכָל כָּךְ לָמָּה? כִּי הוֹצִיאָה אֶת הַבֵּן הֶחָכָם הַזֶּה לָעוֹלָם (למלך)."],[2,"","וּכְשֶׁהוֹצִיאָה אֶת שְׁלֹמֹה, הִיא הוֹצִיאָה לְכָל יִשְׂרָאֵל, וְכֻלָּם הָיוּ בִּדְרָגוֹת עֶלְיוֹנוֹת צַדִּיקִים כִּשְׁלֹמֹה (בשלום), שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שָׂמֵחַ בָּהֶם, וְהֵם בּוֹ. וּבַיּוֹם שֶׁתִּקֵּן שְׁלֹמֹה אֶת הַבַּיִת לְמַטָּה, תִּקְּנָה הַגְּבִירָה בַּיִת לַמֶּלֶךְ, וְשָׂמוּ מְדוֹרָם יַחַד, וְהֵאִירוּ פָּנֶיהָ בְּשִׂמְחָה וּשְׁלֵמוּת. אָז נִמְצְאָה שִׂמְחָה לַכֹּל, לְמַעְלָה וּלְמַטָּה. וְכָל כָּךְ לָמָּה? כִּי כָתוּב מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ, שֶׁהִנְהִיגָה אוֹתוֹ לִרְצוֹן הַמֶּלֶךְ."],[3,"","וּכְשֶׁהַבֵּן הַזֶּה, כְּמוֹ שֶׁאָמַרְנוּ (שצריך), אֵינוֹ מִתְנַהֵג לִרְצוֹן הַמֶּלֶךְ, אָז זוֹ עֶרְוַת הַכֹּל, עֶרְוַת כָּל הַצְּדָדִים, שֶׁהֲרֵי הַמֶּלֶךְ פּוֹרֵשׁ מֵהַגְּבִירָה, וְהַגְּבִירָה הִתְרַחֲקָה מֵהֵיכָלוֹ, וּמִשּׁוּם כָּךְ זוֹהִי עֶרְוַת הַכֹּל. וְכִי אֵין זוֹ עֶרְוָה, מֶלֶךְ בְּלִי גְבִירָה, וּגְבִירָה בְּלִי מֶלֶךְ?! וְעַל זֶה כָּתוּב, עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה אִמְּךְ הִיא. אִמְּךְ הִיא וַדַּאי, וְשׁוֹרָה עִמְּךְ. מִשּׁוּם כָּךְ לֹא תְגַלֶּה עֶרְוָתָהּ."],[4,"","רַבִּי שִׁמְעוֹן הִקִּישׁ יָדָיו וּבָכָה וְאָמַר: אוֹי אִם אֹמַר וַאֲגַלֶּה סוֹד, אוֹי אִם לֹא אֹמַר, שֶׁיֹּאבְדוּ הַחֲבֵרִים דָּבָר. (יחזקאל יא) אֲהָהּ ה' אֱלֹהִים כָּלָה אַתָּה עֹשֶׂה אֵת שְׁאֵרִית יִשְׂרָאֵל. מַה זֶּה אֲהָהּ? וּמַה זֶּה כָּלָה אַתָּה עֹשֶׂה? אֶלָּא סוֹד הַדָּבָר - בִּזְמַן שֶׁה' תַּחְתּוֹנָה הִתְגָּרְשָׁה מֵהֵיכַל הַמֶּלֶךְ, ה' אַחֶרֶת עֶלְיוֹנָה מוֹנַעַת בִּרְכָתָהּ, וְאָז כָּתוּב, אֲהָהּ כָּלָה אַתָּה עֹשֶׂה. מִשּׁוּם שֶׁכְּשֶׁהִיא (הה' הזאת) נִמְנַעַת מִבְּרָכוֹת, ה' אַחֶרֶת מוֹנַעַת אוֹתָם מֵהַכֹּל. מָה הַטַּעַם? כִּי בְרָכוֹת אֵינָן מְצוּיוֹת, אֶלָּא בְּמָקוֹם שֶׁשּׁוֹרִים זָכָר וּנְקֵבָה."],[5,"","וְעַל זֶה כָּתוּב, (ירמיה כה) ה' מִמָּרוֹם יִשְׁאָג וּמִמְּעוֹן קָדְשׁוֹ יִתֵּן קוֹלוֹ שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. עַל נָוֵהוּ מַמָּשׁ. זוֹ הַגְּבִירָה, וְזֶהוּ וַדַּאי. וּמַהוּ אוֹמֵר? אוֹי שֶׁהֶחֱרַבְתִּי אֶת בֵּיתִי וְכוּ'. בֵּיתִי זֶהוּ זִוּוּג הַגְּבִירָה. וְזֶהוּ וַדַּאי עֶרְוַת אָבִיךְ וְעֶרְוַת אִמְּךְ לֹא תְגַלֵּה. שֶׁהֲרֵי מִכָּל הַצְּדָדִים זוֹ עֶרְוָה. וְאָז, לָבְשׁוּ שָׁמַיִם קַדְרוּת וְשַׂק הוּשַׂם כְּסוּתָם, שֶׁהֲרֵי מְקוֹם יְרֻשַּׁת הַבְּרָכוֹת שֶׁל מַעַיְנוֹת הַנְּחָלִים שֶׁהָיוּ שׁוֹפְעִים וּמַשְׁקִים כָּרָאוּי, נִמְנְעוּ."],[6,"","שָׁנִינוּ, כְּשֶׁנִּפְרָד הַמֶּלֶךְ מִן הַגְּבִירָה וְאֵין בְּרָכוֹת מְצוּיוֹת, אָז נִקְרָא ו\"י. מָה הַטַּעַם ו\"י? שֶׁלָּמַדְנוּ, רֹאשׁ הַיְסוֹד י', שֶׁהֲרֵי יְסוֹד הוּא ו' קְטַנָּה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא ו' גְּדוֹלָה עֶלְיוֹנָה. וְלָכֵן כָּתוּב ו\"ו, שְׁתֵּי וָוִי\"ם כְּאֶחָד. וְהָרֹאשׁ שֶׁל הַיְסוֹד הַזֶה הוּא י'. וּכְשֶׁמִּתְרַחֶקֶת הַגְּבִירָה מִן הַמֶּלֶךְ וְהַבְּרָכוֹת נִמְנָעוֹת מִן הַמֶּלֶךְ, וְהַזִּוּוּג לֹא נִמְצָא בְּרֹאשׁ הַיְסוֹד, נוֹטֵל ו' הָעֶלְיוֹן אֶת הָרֹאשׁ הַזֶּה שֶׁל הַיְסוֹד, שֶׁהוּא י', וּמַשְׁפִּיעוֹ אֵלָיו, וְאָז הוּא ו\"י, ו\"י לַכֹּל, לָעֶלְיוֹנִים וְלַתַּחְתּוֹנִים."],[7,"","וְעַל זֶה שָׁנִינוּ, מִיּוֹם שֶׁחָרְבָה יְרוּשָׁלַיִם לֹא נִמְצְאוּ בְרָכוֹת בָּעוֹלָם, וְאֵין לְךְ יוֹם שֶׁלֹּא מְצוּיִים בּוֹ קְלָלוֹת, שֶׁהֲרֵי הַבְּרָכוֹת מְנוּעוֹת בְּכָל יוֹם. אָמַר לוֹ, אוֹ כָּךְ: אוֹ\"י, אוֹ: הוֹ\"י. (או וה') מַה הוּא?"]]],[["אָמַר לֵיהּ, כַּד מִלָּה תַּלְיָא בִּתְשׁוּבָה, וְלָא תַּיְיבִין, כְּדֵין ה' עִלָּאָה נָטִיל לוֹן, וְאַנְגִיד לְוָאו וְי', לְגַבָּהּ, בְּגִין דְּלָא תַּיְיבִין, כְּדֵין אִקְרֵי הוֹי. הוֹי כַּד אִסְתַּלָּק מַלְכָּא לְעֵילָּא לְעֵילָּא, וְצַוְוחִין בְּנֵי נָשָׁא וְלָא אַשְׁגַּח בְּהוּ. וְהַהוּא עִלָּאָה אֶהְיֶה טְמִירָא, סָלִיק לְו', וְי' לְגַבֵּיהּ, בְּגִין דְּלָא אִתְקְבִּיל צְלוֹתֵיהּ, כְּדֵין אִקְרֵי אוֹי, דְּהָא א' סָלִיק לְגַבֵּיהּ דְּו' וְי'. (ס\"א דהוא א' סליק גביה לה' ו' לי') וּכְדֵין תְּשׁוּבָה לָא אִשְׁתְּכַח. וְעַל דָּא אִסְתַּלָּק מֵאִלֵּין אַתְוָון ה', דְּהָא בִּתְשׁוּבָה לָא תַּלְיָיא.","וַדַּאי כַּד אַסְגִּיאוּ חוֹבֵי עָלְמָא טְפֵי, וּתְשׁוּבָה הֲוָה תַּלְיָא בְּקַדְמִיתָא, וְלָא בָּעוּ, כְּדֵין אִסְתַּלָּק ה', וא' סָלִיק לְו' יוֹ\"ד לְגַבֵּיהּ, וְאִקְרֵי אוֹי. וְכַד חָרִיב בֵּי מַקְדְּשָׁא, וּתְשׁוּבָה אִסְתָּלָקַת (ולא מעליא), כְּדֵין צָוְוחוּ וְאָמְרוּ, (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָנָה הַיּוֹם. מַאי כִּי פָנָה הַיּוֹם. דָּא הוּא יוֹמָא עִלָּאָה, דְּאִקְרֵי תְּשׁוּבָה, דְּאִסְתַּלָּק וְאִתְעֲבָר, וְלָא שְׁכִיחַ. הַהוּא יוֹמָא דְּאִשְׁתְּמוֹדַע, לְפַשְׁטָא יְמִינָא לְקַבְּלָא חַיָּיבִין, וְהָא אִתְפְּנֵי מִכֹּלָּא, וְלָא אִשְׁתְּכַח, וְעַל דָּא אָמְרוּ אוֹי, וְלָא הוֹי. כִּי יִנָּטוּ צִלְלֵי עָרֶב, דְּהָא אִתְיְיהִיב רְשׁוּ לְרַבְרְבֵי מְמָנָן דִּשְׁאָר עַמִּין, לְמִשְׁלַט עָלַיְיהוּ.","תָּאנָא, סָלִיק ו' לְעֵילָּא לְעֵילָּא, וְהֵיכָלָא אִתּוֹקַד, וְעַמָּא אִתְגְּלֵי, וּמַטְרוֹנִיתָא אִתְתְּרָכַת, וּבֵיתָא אִתְחֲרָבַת. לְבָתַר כַּד נָחִית ו\"ו לְאַתְרֵיהּ, אַשְׁגַּח בְּבֵיתֵיהּ וְהָא אִתְחֲרִיב, בָּעֵי לְמַטְרוֹנִיתָא, וְהָא אִתְרַחֲקַת וְאַזְלַת. חָמָא לְהֵיכָלֵיהּ, וְהָא אִתּוֹקַד. בָּעָא לְעַמָּא, וְהָא אִתְגְּלֵי. חָמָא לְבִרְכָּאן דְּנַחֲלִין עֲמִיקִין דַּהֲווֹ נַגְדִּין, וְהָא אִתְמְנָעוּ. כְּדֵין כְּתִיב, (ישעיהו כ״ב:י״ב) וַיִּקְרָא יְיָ' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגוֹר שָׂק. וּכְדֵין לָבְשׁוּ שָׁמַיִם קַדְרוּת.","כְּדֵין ו' ה' (ס\"א ו' י') אִתְנְגִיד חַד לָקֳבֵיל חַד. וְה' עִלָּאָה, נָגִיד מַבּוּעֵי לְסִטְרָא אָחֳרָא, וּבִרְכָּאן לָא מִשְׁתַּכְּחָן. דְּהָא דְּכַר וְנוּקְבָּא לָא אִשְׁתְּכָחוּ, וְלָא שַׁרְיָין כַּחֲדָא. כְּדֵין (ירמיהו כ״ה:ל׳) שָׁאֹג יִשְׁאַג עַל נָוִהוּ. בָּכָה רַבִּי שִׁמְעוֹן, וּבָכָה רִבִּי אֶלְעָזָר, אָמַר רִבִּי אֶלְעָזָר, בְּכִיָיה תְּקִיעָא בְּלִבָּאִי מִסִּטְרָא חֲדָא, וְחֶדְוָותָא בְּלִבָּאִי מִסִּטְרָא אָחֳרָא. דְּהָא שְׁמַעְנָא מִלִּין, דְּלָא שְׁמַעְנָא עַד הַשְׁתָּא, זַכָּאָה חוּלָקִי.","(ויקרא ח\"י) עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה, מַאן אֵשֶׁת אָבִיךָ. אָמַר רַבִּי שִׁמְעוֹן, הָא תָּנֵינָן, כָּל מִלּוֹי דְּאוֹרַיְיתָא סָתִים וְגַלְיָא, כְּמָה דִּשְׁמָא קַדִּישָׁא סָתִים וְגַלְיָא, אוֹרַיְיתָא דְּהִיא שְׁמָא קַדִּישָׁא, הָכִי נָמֵי סָתִים וְגַלְיָא. הָכָא כֹּלָּא בְּאִתְגַּלְיָיא, יְדִיעָא סָתִים כְּמָה דְּאוֹקִימְנָא.","וְהַאי קְרָא הָכִי הוּא, אֵשֶׁת אָבִיךָ: תָּאנָא, כָּל זִמְנָא דְּמַטְרוֹנִיתָא אִשְׁתְּכַחַת בְּמַלְכָּא, וְיַנְקָא לָךְ, אִקְרֵי אִמֶּךָ. הַשְׁתָּא דְּאִתְגַּלְיָא עִמָּךְ וְאִתְרָחֲקַת מִן מַלְכָּא, אֵשֶׁת אָבִיךָ אִתְקְרֵי. אִנְתּוּ הִיא דְּמַלְכָּא קַדִּישָׁא לָא אִתְפְּטָרַת בְּתִרוּכִין מִנֵּיהּ, אִנְתְּתֵיהּ הִיא וַדַּאי. כְּמָה דִּכְתִּיב, (ישעיהו נ׳:א׳) כֹּה אָמַר יְיָ' אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. אֶלָּא וַדַּאי אִנְתּוּ הִיא דְּמַלְכָּא, אַף עַל גַּב דְּאִתְגַּלְיָיא.","וְעַל דָּא פָּקִיד עָלָה תְּרֵי זִמְנֵי, כַּד יָתְבָא בְּמַלְכָּא בְּזִוּוּגָא חַד, וְאִתְקְרֵי אִמְּךָ, דִּכְתִּיב עֶרְוַת אִמְּךָ לֹא תְגַלֵּה, לָא תַּעֲבִיד דְּיִתְרַחֲקוּן דָּא מִן דָּא, וְתִשְׁתְּלַח עַל חוֹבָךְ, כְּמָה דִּכְתִּיב, (ישעיהו נ׳:א׳) וּבְפִשְׁעֵכֶם שֻׁלְחָה אִמְּכֶם. וְחַד, כַּד הִיא בְּגָלוּתָא עִמָּךְ, וְאִתְגַּלְיָיא מֵהֵיכָלָא דְּמַלְכָּא, וְאִתְקְרֵי אִנְתּוּ דְּמַלְכָּא. אַף עַל גַּב דְּאִתְרַחֲקָת מִנֵּיהּ לָא תַּעֲבִיד בְּגִין דְּתַעְדֵי מִבֵּינָךְ, וְיִשְׁלְטוּן בָּךְ שַׂנְאָךְ, וְלָא תִּסְתַּמָר עֲלָךְ בְּגָלוּתָא. הֲדָא הוּא דִכְתִיב עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה. מַאי טַעֲמָא. בְּגִין כִּי עֶרְוַת אָבִיךָ הוּא. אַף עַל גַּב דְּאִתְרַחֲקָת מִן מַלְכָּא, אַשְׁגָּחוּתָא דְּמַלְכָּא בָּהּ תְּדִירָא, וּבַעְיָא לְאִסְתַּמְּרָא לָקֳבְלָה יַתִּיר, וְלָא תֵּיחוּב לְגַבָּהּ.","רִבִּי שִׁמְעוֹן פָּתַח, (דברים כ״ג:ט״ו) כִּי יְיָ' אֱלֹהֶיךָ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךָ לְהַצִּילְךָ וְגוֹ'. כִּי יְיָ' אֱלֹהֶיךָ: דָּא שְׁכִינְתָּא, דְּאִשְׁתְּכָחַת בְּהוּ בְּיִשְׂרָאֵל, וְכָּל שֶׁכֵּן בְּגָלוּתָא, לְאַגָּנָא עָלַיְהוּ תְּדִירָא מִכָּל סִטְרִין, וּמִכָּל שְׁאָר עַמִּין, דְּלָא יְשֵׁיצוּן לְהוּ לְיִשְׂרָאֵל."],[[0,"אמר ליה כד וכו׳:","א״ל, כשהדבר תלוי בתשובה, ואינם שבים אז לוקח אותם \u0003ה׳\u0004 עלאה דהויה, שהיא בינה, ומושך את ה \u0003ו׳\u0004 וה \u0003י'\u0004 אליה, משום שאינם שבים, ונעשה הצירוף \u0003הו״י,\u0004 אז נקרא \u0003הוי.\u0004 דהיינו \u0003הוי\u0004 כשנסתלק המלך, שהוא ז״א, למעלה למעלה, לבינה. ובני אדם צועקים ואינו משגיח בהם. ולפעמים עליונה ההיא השם \u0003אהיה\u0004 הנסתר, שהוא כתר, מעלה את ה \u0003ו׳\u0004 שהוא ז״א, ואת ה \u0003י׳\u0004 שהוא ראש היסוד, אליו, כי לא נתקבלה תפלתו, ונעשה הצירוף, אוי, אז נקרא \u0003אוי,\u0004 כי \u0003א׳,\u0004 שהוא אהיה, העלה אליה \u0003ו' י׳.\u0004 ואז לא נמצא תשובה וע״כ נסתלקה \u0003ה׳\u0004 מאלו האותיות. כי כבר אינו תלוי בתשובה. שה״ס בינה הנקראת \u0003ה'.\u0004"],[1,"ודאי כד אסגיאו וכו׳:","ודאי כשנתרבו ביותר עונות העולם, ובתחילה היתה התשובה תלויה, ולא רצו לשוב, אז נסתלקה \u0003ה׳,\u0004 שהיא בינה שה״ס תשובה, וה \u0003א׳,\u0004 שהיא כתר, מעלה את ה \u0003ו' י׳\u0004 אליו, ונקרא \u0003אוי.\u0004 וכשנחרב בית המקדש ונסתלקה התשובה אז זעקו ואמרו, \u0003אוי\u0004 לנו כי פנה היום. מהו, כי פנה היום. זהו יום העליון, דהיינו בינה הנקראת תשובה, שנסתלק ונעבר ואינו נמצא. הוא היום ההוא, שנודע, שפושט ימינו לקבל רשעים. והוא פנה לו מכל ואינו נמצא. וע״כ אמרו \u0003אוי,\u0004 ולא \u0003הוי.\u0004 כי ינטו צללי ערב. היינו שניתנה רשות לשרים הממונים של שאר העמים לשלוט על ישראל."],[2,"תאנא סליק ו׳ וכו׳:","למדנו, ה \u0003ו׳,\u0004 שהיא ז״א, עלתה למעלה למעלה, לכתר, שה״ס א׳ כנ״ל, וההיכל נשרף והעם הוגלה, והמלכה גורשה, והבית נחרב. אח״כ כשחזרה ה \u0003ו׳\u0004 למקומה, השגיח בבית והוא נחרב. בקש את המלכה, והיא נתרחקה והלכה. ראה את היכלו, והנה נשרף. בקש העם, והרי הגלו. ראה את הברכות של הנחלים העמוקים, מבינה, שהיו נמשכים, והנה נמנעו. אז כתוב, ויקרא ה׳ צבאות ביום ההוא לבכי ולמספד ולקרחה ולחגור שק. ואז, לבשו שמים, שהוא ז״א, קדרות."],[3,"כדין ו׳ י׳ אתנגיד וכו׳:","אז \u0003ו׳ י׳\u0004 נמשכו אחד כנגד אחד. שה \u0003י׳\u0004 שהיא ראש היסוד נמשכה אל ה \u0003ו׳,\u0004 שהיא ז״א, ונפרדה מהמלכות. ו \u0003ה׳\u0004 העליונה דהויה, שהיא בינה, נוזלת מבועים לסטרא אחרא, וברכות אינן נמצאות, משום שלא נמצאו דכר ונוקבא, שהם ז״א ומלכות, ואינם שורים יחד. אז שאג ישאג על נוהו, שהוא מלכות. בכה ר״ש ובכה ר׳ אלעזר. אמר ר׳ אלעזר, בכיה תקועה בלבי מצד זה, ושמחה בלבי מצד אחר, כי שמעתי דברים שלא שמעתי עד עתה. אשרי חלקי."],[4,"ערות אשת אביך לא תגלה:","שואל, מי היא אשת אביך. אמר ר׳ שמעון, הרי למדנו, כל דברי התורה סתומים וגלוים, כמו השם הקדוש שהוא סתום וגלוי, שכתוב הויה, ונקרא אדני, והתורה שהיא השם הקדוש, היא ג״כ סתומה ומגולה. וכאן, במקרא הזה, הכל בגלוי, דהיינו לפי פשוטו, שהכתוב מדבר באשת אביו. ויש בו ידיעה סתומה, כמו שהעמדנו."],[5,"והאי קרא הכי וכו׳:","ומקרא זה כך הוא. \u0003אשת אביך.\u0004 למדנו, כל זמן שהמלכה נמצאת עם המלך, ומניקה אותך, משפע שלה, היא נקראת אמך. עתה, בגלות, שהגלתה עמך ונתרחקה מן המלך, היא נקראת \u0003אשת אביך,\u0004 כי היא אשת המלך הקדוש, שהוא ז״א, שלא נפטרה ממני בספר כריתות, אשתו היא ודאי. כמו שכתוב, כה אמר ה׳ אי זה ספר כריתות אמכם אשר שלחתיה. אלא ודאי, שהיא אשת המלך אע״פ שהגלתה."],[6,"ועל דא פקיד וכו׳:","ועל כן צוה עליה ב׳ פעמים, אחד, כשיושבת עם המלך בזווג אחד ונקראת \u0003אמך,\u0004 שכתוב, ערות אמך לא תגלה, שפירושו, לא תעשה שיתרחקו זה מזה ותהיה משולחת בסבת עונך. כמו שכתוב, ובפשעכם שלחה אמכם. ואחד, כשהיא בגלות עמך, והגלתה מהיכל המלך, שנקראת אז אשת המלך, ואע״פ שנתרחקה מן המלך, לא תעשה שתהיה סרה ממך, וישלטו עליך אויביך, ולא תשמור אותך בגלות. ז\"ש, ערות אשת אביך לא תגלה. מהו הטעם. הוא משום, כי ערות אביך הוא. כי אע״פ שנתרחקה מן המלך, השגחת המלך נמצאת בה תמיד, וצריך לשמור עצמו כנגדה ביותר, ולא לחטא לה."],[7,"רבי שמעון פתח וכו׳:","ר״ש פתח, כי ה׳ אלקיך מתהלך בקרב מחנך להצילך וגו'. כי ה׳ אלקיך, זו היא השכינה הנמצאת בישראל, וכל שכן בגלות, להגן עליהם תמיד מכל הצדדים, ומכל שאר העמים שלא יכלו את ישראל."]],[[0,"","אָמַר לוֹ, כְּשֶׁהַדָּבָר תָּלוּי בִּתְשׁוּבָה וְלֹא שָׁבִים, אָז ה' הָעֶלְיוֹנָה נוֹטֶלֶת אוֹתָם וּמַשְׁפִּיעָה לְוָא\"ו וְי' אֵלֶיהָ, כִּי לֹא שָׁבִים, וְאָז נִקְרָא הוֹי. הוֹי כְּשֶׁהִסְתַּלֵּק הַמֶּלֶךְ לְמַעְלָה לְמַעְלָה, וְצוֹוְחִים בְּנֵי אָדָם וְאֵין מַשְׁגִּיחַ בָּהֶם. וְאוֹתוֹ הָעֶלְיוֹן אֶהְיֶה הוּא הַטָּמִיר, מַעֲלֶה לְו', וְי' אֵלָיו, כִּי לֹא הִתְקַבְּלָה תְפִלָּתוֹ, אָז נִקְרָא אוֹי, שֶׁהֲרֵי א' עוֹלֶה לְו' וְי', (שהיאא'עולהלה'לו'לי') וְאָז אֵין מְצוּיָה תְשׁוּבָה, וְלָכֵן הִסְתַּלְּקָה מֵהָאוֹתִיּוֹת הַלָּלוּ ה', שֶׁהֲרֵי לֹא תָלוּי בִּתְשׁוּבָה."],[1,"","וַדַּאי כְּשֶׁהִתְרַבּוּ יוֹתֵר חֲטָאֵי הָעוֹלָם, וּתְשׁוּבָה הָיְתָה תְלוּיָה בָּרִאשׁוֹנָה וְלֹא רָצוּ, אֲזַי הִסְתַּלְּקָה ה', וְא' הֶעֶלְתָה אֶת ו' וְיוֹ\"ד אֵלָיו, וְנִקְרָא אוֹי. וּכְשֶׁחָרַב בֵּית הַמִּקְדָּשׁ וְהַתְּשׁוּבָה הִסְתַּלְּקָה (ולאמעלה), אֲזַי צָוְחוּ וְאָמְרוּ, (ירמיה ו) אוֹי לָנוּ כִּי פָנָה הַיּוֹם. מַה זֶּה כִּי פָנָה הַיּוֹם? זֶהוּ הַיּוֹם הָעֶלְיוֹן, שֶׁנִּקְרָא תְשׁוּבָה, שֶׁהִסְתַּלֵּק וְעָבַר וְלֹא מָצוּי. אוֹתוֹ הַיּוֹם שֶׁנּוֹדָע, לִפְשֹׁט הַיָּמִין כְּנֶגֶד הָרְשָׁעִים, וַהֲרֵי הִתְפַּנָּה מֵהַכֹּל וְלֹא נִמְצָא, וְלָכֵן אָמְרוּ אוֹי וְלֹא הוֹי. כִּי יִנָּטוּ צִלְלֵי עָרֶב, שֶׁהֲרֵי נִתְּנָה רְשׁוּת לִגְדוֹלֵי הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים לִשְׁלֹט עֲלֵיהֶם."],[2,"","לָמַדְנוּ, עָלְתָה ו' לְמַעְלָה לְמַעְלָה, וְהַהֵיכָל נִשְׂרַף, וְהָעָם גָּלָה, וְהַגְּבִירָה גֹּרְשָׁה, וְהַבַּיִת נֶחֱרַב. אַחַר כָּךְ שֶׁיָּרַד וָ\"ו לִמְקוֹמוֹ, הִשְׁגִּיחַ עַל בֵּיתוֹ וְהִנֵּה חָרַב, בִּקֵּשׁ אֶת הַגְּבִירָה, וְהִנֵּה הִתְרַחֲקָה וְהָלְכָה. רָאָה אֶת הֵיכָלוֹ, וְהִנֵּה נִשְׂרַף. בִּקֵּשׁ אֶת הָעָם, וְהִנֵּה גָּלָה. רָאָה אֶת בִּרְכוֹת הַנְּחָלִים הָעֲמֻקִּים שֶׁהָיוּ שׁוֹפְעִים, וְהִנֵּה נִמְנְעוּ. וְאָז כָּתוּב, (ישעיה כב) וַיִּקְרָא ה' אֱלֹהִים צְבָאוֹת בַּיּוֹם הַהוּא לִבְכִי וּלְמִסְפֵּד וּלְקָרְחָה וְלַחֲגֹר שָׂק. וְאָז לָבְשׁוּ שָׁמַיִם קַדְרוּת."],[3,"","אֲזַי ו' ה' (ו' י') נִמְשְׁכוּ אֶחָד כְּנֶגֶד הָאֶחָד, וְה' הָעֶלְיוֹנָה הִשְׁפִּיעָה אֶת הַמַּעְיָנוֹת לַצַּד הָאַחֵר, וְהַבְּרָכוֹת לֹא נִמְצְאוּ, שֶׁהֲרֵי לֹא נִמְצְאוּ הַזָּכָר וְהַנְּקֵבָה וְלֹא שְׁרוּיִים כְּאֶחָד. אֲזַי שָׁאֹג יִשְׁאַג עַל נָוֵהוּ. בָּכָה רַבִּי שִׁמְעוֹן, וּבָכָה רַבִּי אֶלְעָזָר. אָמַר רַבִּי אֶלְעָזָר, בְּכִיָּה תְקוּעָה בְּלִבִּי מִצַּד אֶחָד, וְשִׂמְחָה בְּלִבִּי מִצַּד אַחֵר, שֶׁהֲרֵי שָׁמַעְתִּי דְבָרִים שֶׁלֹּא שָׁמַעְתִּי עַד עַתָּה. אַשְׁרֵי חֶלְקִי!"],[4,"","עָרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מִי זוֹ אֵשֶׁת אָבִיךְ? אָמַר רַבִּי שִׁמְעוֹן, הֲרֵי שָׁנִינוּ, כָּל דִּבְרֵי הַתּוֹרָה נִסְתָּר וְנִגְלֶה, כְּמוֹ שֶׁהַשֵּׁם הַקָּדוֹשׁ נִסְתָּר וְנִגְלֶה, הַתּוֹרָה שֶׁהִיא שֵׁם קָדוֹשׁ, כָּךְ גַּם נִסְתָּר וְנִגְלֶה. כָּאן הַכֹּל בְּנִגְלֶה, יְדִיעָה נִסְתֶּרֶת כְּמוֹ שֶׁבֵּאַרְנוּ."],[5,"","וְהַפָּסוּק הַזֶּה הוּא כָּךְ: אֵשֶׁת אָבִיךְ - לָמַדְנוּ, כָּל זְמַן שֶׁהַגְּבִירָה נִמְצֵאת עִם הַמֶּלֶךְ וְהִיא מֵינִיקָה אוֹתְךְ, נִקְרֵאת אִמְּךְ. בְּעֵת שֶׁגָּלְתָה עִמְּךְ וְהִתְרַחֲקָה מִן הַמֶּלֶךְ, הִיא נִקְרֵאת אֵשֶׁת אָבִיךְ. אֵשֶׁת הַמֶּלֶךְ הַקָּדוֹשׁ לֹא נִפְטֶרֶת בְּגֵרוּשִׁין מִמֶּנּוּ, הִיא וַדַּאי אִשְׁתּוֹ, כְּמוֹ שֶׁכָּתוּב (שם נ) כֹּה אָמַר ה' אֵי זֶה סֵפֶר כְּרִיתוּת אִמְּכֶם אֲשֶׁר שִׁלַּחְתִּיהָ. אֶלָּא וַדַּאי שֶׁהִיא אֵשֶׁת הַמֶּלֶךְ, אַף עַל גַּב שֶׁגָּלְתָה."],[6,"","וְלָכֵן צִוָּה עָלֶיהָ פַּעֲמַיִם - כְּשֶׁיָּשְׁבָה עִם הַמֶּלֶךְ בְּזִוּוּג אֶחָד, וְנִקְרֵאת אִמְּךְ, שֶׁכָּתוּב עֶרְוַת אִמְּךְ לֹא תְגַלֵּה, אַל תַּעֲשֶׂה שֶׁיִּתְרַחֲקוּ זֶה מִזּוֹ וְתִשָּׁלַח עַל חֶטְאֲךְ, כְּמוֹ שֶׁכָּתוּב וּבְפִשְׁעֵיכֶם שֻׁלְּחָה אִמְּכֶם. וְאֶחָד כְּשֶׁהִיא בַּגָּלוּת עִמְּךְ וְגָלְתָה מֵהֵיכַל הַמֶּלֶךְ, וְנִקְרֵאת אֵשֶׁת הַמֶּלֶךְ. אַף עַל גַּב שֶׁהִתְרַחֲקָה מִמֶּנּוּ, אַל תַּעֲשֶׂה כְּדֵי שֶׁתָּזוּז מִבֵּינְךְ וְיִשְׁלְטוּ בְךְ שׂוֹנְאֶיךְ, וְלֹא תִשְׁמֹר עָלֶיךְ בַּגָּלוּת. זֶהוּ שֶׁכָּתוּב עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מָה הַטַּעַם? מִשּׁוּם כִּי עֶרְוַת אָבִיךְ הוּא. אַף עַל גַּב שֶׁהִתְרַחֲקָה מִן הַמֶּלֶךְ, בָּהּ הַשְׁגָּחַת הַמֶּלֶךְ תָּמִיד, וְצָרִיךְ לְהִשָּׁמֵר כְּנֶגְדָּהּ יוֹתֵר וְלֹא תֶחֱטָא אֵלֶיהָ."],[7,"","רַבִּי שִׁמְעוֹן פָּתַח, (דברים כג) כִּי ה' אֱלֹהֶיךְ מִתְהַלֵּךְ בְּקֶרֶב מַחֲנֶךְ לְהַצִּילְךְ וְגוֹ'. כִּי ה' אֱלֹהֶיךְ - זוֹ הַשְּׁכִינָה שֶׁנִּמְצֵאת עִם יִשְׂרָאֵל, וְכָל שֶׁכֵּן בַּגָּלוּת, לְהָגֵן עֲלֵיהֶם תָּמִיד מִכָּל הַצְּדָדִים וּמִכָּל שְׁאָר הָעַמִּים כְּדֵי שֶׁלֹּא יַשְׁמִידוּ אֶת יִשְׂרָאֵל."]]],[["דְּתַנְיָא, לָא יַכְלִין שַׂנְאֵיהוֹן דְּיִשְׂרָאֵל לְאַבְאָשָׁא לְהוּ, עַד דְּיִשְׂרָאֵל מַחֲלִישִׁין חֵילָא דִּשְׁכִינְתָּא מִקַּמֵּי רַבְרְבֵי מְמָנָן דִּשְׁאָר עַמִּין. כְּדֵין יַכְלִין לְהוֹן שַׂנְאֵיהוֹן דְּיִשְׂרָאֵל, וְשַׁלְטִין עָלַיְיהוּ, וְגַזְרִין עָלַיְיהוּ כַּמָה גְּזֵירִין בִּישִׁין. וְכַד אִינּוּן תַּיְיבִין לָקֳבְלָה, הִיא מְתָבָּרַת חֵילָא וְתּוּקְפָּא דְּכָל אִינּוּן מְמָנָן רַבְרְבִין, וְתַבְרַת חֵילָא וְתּוּקְפָּא דְּשַׂנְאֵיהוֹן דְּיִשְׂרָאֵל, וְאִתְפָּרְעָא לְהוּ מִכֹּלָּא.","וְעַל דָּא וְהָיָה מַחֲנֶיךָ קָדוֹשׁ, דְּבָעֵי בַּר נָשׁ דְּלָא יִסְתְּאָב בְּחוֹבוֹי, וַיַּעֲבָר עַל פִּתְגָּמֵי אוֹרַיְיתָא. דְּאִי עָבִיד הָכֵי, מְסָאֲבִין לֵיהּ, כְּמָה דִּכְתִּיב וְנִטְמֵתֶם בָּם, בְּלֹא א'. וְתָאנָא, מָאתָן וּתְמַנְיָא וְאַרְבְּעִין שַׁיְיפִין בְּגוּפָא, וְכֻלְּהוּ אִסְתַּאֲבָן, כַּד אִיהוּ אִסְתְּאַב. כְּלוֹמַר, כַּד בָּעֵי לְאִסְתַּאֲבָא. וְעַל דָּא, וְהָיָה מַחֲנֶיךָ קָדוֹשׁ. מַאי מַחֲנֶיךָ, אִלֵּין אִינּוּן שַׁיְיפֵי גּוּפָא. וְלֹא יִרְאֶה בְךָ עֶרְוַת דָּבָר, מַאי עֶרְוַת דָּבָר. עֶרְיָיתָא נוּכְרָאָה לְהַאי (ס\"א דהוי) דָּבָר רָמָז, כְּמָה דְּאוֹקִימְנָא. דְּאִי הָכִי, וְשָׁב מֵאַחֲרֶיךָ וַדַּאי. וְעַל דָּא עֶרְוַת אֵשֶׁת אָבִיךָ לֹא תְגַלֵּה. מַאי טַעְמָא. בְּגִין דִּכְתִּיב עֶרְוַת אָבִיךָ הוּא, כְּמָה דְּאוֹקִימְנָא.","תָּאנָא, עַל ג' מִלִּין מִתְעַכְּבִין יִשְׂרָאֵל בְּגָלוּתָא. עַל דְּעַבְדִין קְלָנָא בִּשְׁכִינְתָּא בְּגָלוּתָא. וּמְהַדְּרֵי אַנְפַּיְיהוּ מִן שְׁכִינְתָּא, וְעַל דִּמְסָאֲבֵי גַּרְמַיְיהוּ קָמֵי שְׁכִינְתָּא. וְכֻלְּהוּ אוֹקִימְנָא בְּמַתְנִיתָא דִּילָן.","רִבִּי אַבָּא, הֲוָה אָזִיל לְקַפּוּטְקִיָּא, וַהֲוָה עִמֵּיהּ רִבִּי יוֹסֵי. עַד דַּהֲווֹ אַזְלֵי, חָמוּ חַד בַּר נָשׁ, דְּהֲוָה אָתֵי, וּרְשִׁימָא חַד בְּאַנְפּוֹי. אָמַר רִבִּי אַבָּא, נִסְטֵי מֵהַאי אוֹרְחָא, דְּהָא אַנְפּוֹי דְּדֵין אַסְהִידוּ עָלֵיהּ, דְּעָבַר בְּעֶרְיָיתָא דְּאוֹרַיְיתָא, בְּגִינֵי כַּךְ אִתְרְשִׁים בְּאַנְפּוֹי. אָמַר לֵיהּ רִבִּי יוֹסֵי, אִי הַאי רְשִׁימָא הֲוָה לֵיהּ כַּד הֲוָה יַנוּקָא, מַאי עֶרְיָיתָא אִשְׁתְּכַח בֵּיהּ. אָמַר לֵיהּ, אֲנָא חֲמֵינָא בְּאַנְפּוֹי, דְּאַסְהִידוּ בְּעֶרְיָיתָא דְּאוֹרַיְיתָא.","קָרָא לֵיהּ רִבִּי אַבָּא, אָמַר לֵיהּ אֵימָא מִלָּה, הַאי רְשִׁימָא דְּאַנְפָּךְ, מַה הוּא. אָמַר לוֹן, בְּמָטוֹתָא מִנַּיְיכוּ, לָא תַּעֲנְשׁוּ יַתִּיר לְהַהוּא בַּר נָשׁ, דְּהָא חוֹבוֹי קָא גָּרְמוּ לֵיהּ. אָמַר רִבִּי אַבָּא מַהוּ. אָמַר לֵיהּ, יוֹמָא חַד הֲוִינָא אָזִיל בְּאָרְחָא אֲנִי וַאֲחֹתִי, שָׁרֵינָא בְּחַד אוֹשְׁפִּיזָא, וְרָוִינָא חַמְרָא, וְכָל הַהוּא לֵילְיָא אֲחִידְנָא בַּאֲחֹתִי. בְּצַפְרָא קַמְנָא, וְאוּשְׁפִּיזָאִי קָטַט בְּחַד גַּבְרָא, עָיֵילְנָא בֵּינַיְיהוּ, וְקַטְרוּ לִי דָּא מֵהַאי גִּיסָא, וְדָא מֵהַאי גִּיסָא, וּרְשִׁימָא דָּא הֲוָה עָיֵיל לְבֵי מוֹחָא, וְאִשְׁתְּזַבְנָא עַל יְדָא דְּחַד אַסְיָיא דְּאִית בְּגַוָון.","אָמַר לֵיהּ, מַאן הוּא אַסְיָיא. אָמַר לֵיהּ, רִבִּי שַׂמְלָאי הוּא. אָמַר לֵיהּ מַאי אַסוּותָא יָהַב לְךָ. אָמַר לֵיהּ אַסוּותָא דְּנַפְשָׁא. וּמֵהַהוּא יוֹמָא אַהֲדַרְנָא בִּתְשׁוּבָה. וּבְכָל יוֹמָא חֲזֵינָא אַנְפָּאִי בְּחַד חֵיזוּ, וּבָכֵינָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּהוּא רִבּוֹן עָלְמִין עַל הַהוּא חוֹבָה. וּמֵאִינּוּן דִּמְעִין אַסְחֵינָא אַנְפָּאִי. אָמַר רִבִּי אַבָּא, אִי לָאו דְּאִתְמְנַע מִנָךְ תְּשׁוּבָה, אַעְבַרְנָא מֵאַנְפָּךְ הַהוּא רְשִׁימָא. אֲבָל קָרֵינָא עָלָיךְ, (ישעיהו ו׳:ז׳) וְסָר עֲוֹנֶךָ וְחַטָּאתְך תְּכוּפָּר. אָמַר לֵיהּ, ג' זִמְנִין אֵימָא. אָמַר לֵיהּ ג' זִמְנִין, וְאִתְעֲבָר רְשִׁימָא.","אָמַר רִבִּי אַבָּא, וַדַּאי מָארָךְ הָא בָּעָא לְאַעְבְּרָא מִנָךְ, דְּוַדַּאי בִּתְשׁוּבָה אִשְׁתְּכַחַת. אָמַר לֵיהּ, נָדַרְנָא מֵהַאי יוֹמָא לְאִתְעַסְּקָא בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא. אָמַר לֵיהּ, מַה שְׁמָךְ. אָמַר לֵיהּ אֶלְעָזָר. אָמַר לֵיהּ אֵל עָזַר, וַדַּאי שְׁמָא גָּרִים, דֶּאֱלָהָךְ סִיְּיעָךְ, וַהֲוָה בְּסָעֲדָךְ, שַׁדְרֵיהּ רִבִי אַבָּא וּבַרְכֵיהּ.","לְזִמְנָא אָחֳרָא, הֲוָה רִבִּי אַבָּא אָזִיל לְגַבֵּי רַבִּי שִׁמְעוֹן, עָאל בְּמָאתֵיהּ, אַשְׁכָּחֵיהּ דְּהֲוָה יָתִיב וְדָרִישׁ, (תהילים צ״ב:ז׳) אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹאת. אִישׁ בַּעַר לֹא יֵדָע וְגוֹ', כַּמָה טִפְּשִׁין אִינּוּן בְּנֵי עָלְמָא, דְּלָא מַשְׁגִּיחִין וְלָא יַדְעִין וְלָא מִסְתַּכְּלִין לְמִנְדַּע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, עַל מַה קַיְימִין בְּעָלְמָא. מַאן מְעַכֵּב לְהוּ לְמִנְדַּע, טִפְּשׁוּתָא דִּלְהוֹן. בְּגִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, דְּאִילּוּ הֲווֹ מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא יִנְדְּעוּן אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא."],[[0,"דתניא לא יכלין וכו׳:","שלמדנו, לא יכלו שונאיהם של ישראל להרע להם, עד שישראל החלישו כח השכינה לפני השרים הממונים של שאר העמים, אז יכלו להם שונאיהם של ישראל ושולטים עליהם, וגוזרים עליהם כמה גזרות רעות. וכשישראל שבים כנגדה בתשובה, השכינה משברת הכח והאומץ של אלו השרים הממונים, ומשברת הכח והאומץ של שונאי ישראל, ונפרעת מהם הכל."],[1,"וע״ד, והיה מחניך וגו׳:","וע״כ, והיה מחניך קדוש. שהאדם צריך לראות שלא יטמא בעונותיו, ויעבור על דברי תורה. שאם עושה כך, מטמאים אותו. כמו שכתוב, ונטמתם בם. בלי \u0003א'.\u0004 שיורה על טומאה יתירה. ולמדנו, רמ״ח אברים יש בגוף וכולם נטמאים כשהוא נטמא. כלומר כשהוא רוצה להטמא, תיכף נטמא, וע״כ והיה מחניך קדוש. מהו מחניך. אלו הם אברי הגוף. ולא יראה בך ערות דבר. מהו ערות דבר. היינו רמז, שלא תגרום, ערוה זרה לדבר הזה, שהיא זרה למלכות הנקראת דבר. כמו שהעמדנו. שאם אתה עושה כן, \u0003ושב מאחריך,\u0004 ודאי. וע״כ אשת אביך לא תגלה. מהו הטעם. משום שכתוב, ערות אביך הוא. כמו שהעמדנו."],[2,"תאנא על ג׳ וכו׳:","למדנו על ג׳ דברים מתעכבים ישראל בגלות, על שנוהגים בזיון בשכינה בגלות. ועל שמחזירים פניהם מן השכינה. דהיינו כמ״ש כי פנו אלי עורף ולא פנים. ועל שמטמאים עצמם לפני השכינה. ואינם חוששים שהשכינה עמהם בגלות. וכולם העמדנו במשנה שלנו."],[3,"רבי אבא הוה וכו׳:","ר״א היה הולד לקפוטקיא, והיה עמו ר׳ יוסי. בעוד שהיו הולכים, ראו אדם אחד שהיה בא ורושם אחד בפניו. אמר ר׳ אבא, נטה מדרך הזה, כי הפנים שלזה מעידים עליו שעבר על עריות שבתורה, וע״כ נרשם זה בפניו. א״ל ר׳ יוסי אם היה בו רושם ההוא מעת שהיה ילד, איזה ערוה היתה נמצא אז עמו. אמר לו, אני רואה בפניו שמעידים שעבר על עריות שבתורה."],[4,"קרא ליה ר׳ אבא וכו׳:","קרא אותו ר׳ אבא, אמר לו אמור הדבר, רושם הזה שבפניך מה הוא. אמר להם בבקשה מכם שלא תענשו יותר לאדם ההוא, כי עונותיו גרמו לו רושם הזה. א״ר אבא מה הוא. א״ל יום אחד הייתי הולך בדרך אני ואחותי, והיינו שורים במלון אחד, והשתכרנו מיין, וכל אותו הלילה אחזתי באחותי, בבוקר קמתי, ובעל המלון היה לו מריבה עם אדם אחד, נכנסתי ביניהם, להפרידם זה מזה, וסדרו אותי דהיינו שהכו אותי, זה מצד זה, וזה מצד זה, ורושם הזה נכנס במוחי. ונצלתי ע״י רופא אחד שיש ביננו. \u0003קטרו,\u0004 פירושו תקנו סדרו. כמו, קטרין ליה גננא (ברכות טז.) ומובא כאן, בלשון סגי נהור, כלומר, שהכו אותו קרוב למיתה."],[5,"אמר ליה מאן וכו׳:","א״ל מי הוא הרופא. אמר ליה, ר׳ שמלאי הוא. א״ל איזו רפואה נתן לך. א״ל רפואת הנפש. ומיום ההוא חזרתי בתשובה. ובכל יום ראיתי פני במראה אחד בלי שינוי, ובכיתי לפני הקב״ה, שהוא רבון העולמים, על עון ההוא, ומדמעות האלו רחצתי פני. אמר ר׳ אבא, אם לא היתה נמנעת ממך תשובה, הייתי מעביר מפניך רושם ההוא, אבל קורא אני עליך, וסר עונך וחטאתך תכופר. א״ל, אמור זה ג׳ פעמים. א״ל ג׳ פעמים והרושם נעבר."],[6,"א״ר אבא ודאי וכו׳:","אר״א, ודאי רבונך רצה להעביר ממך הרושם, כי ודאי נמצאת בתשובה. אמר לו, אני נודר מיום זה ולהלאה, לעסוק בתורה יום ולילה. א״ל מה שמך. א״ל אלעזר. א״ל אל עזר, ודאי שהשם גורם, שאלקיך עזר אותך והיה עמך, שלחו ר׳ אבא וברכו."],[7,"לזמנא אחרא הוה וכו׳:","פעם אחרת היה הולך ר׳ אבא לר״ש, נכנס בעירו, מצאו לאותו האיש שהיה בו הרושם, שהיה יושב ודורש, איש בער לא ידע וכסיל לא יבין את זאת. \u0003איש בער לא ידע\u0004 וגו', כמה כסילים הם בני העולם שאינם משגיחים ואינם יודעים ואינם מסתכלים לדעת דרכיו של הקב״ה, על מה נמצאים בעולם. מי מעכב אותם להכיר בכסילות שלהם, הוא משום שאינם עוסקים בתורה, כי אלו היו עוסקים בתורה, היו יודעים דרכיו של הקב״ה."]],[[0,"","שֶׁלָּמַדְנוּ, לֹא יְכוֹלִים שׂוֹנְאֵיהֶם שֶׁל יִשְׂרָאֵל לְהַזִּיק לָהֶם עַד שֶׁיִּשְׂרָאֵל מַחֲלִישִׁים כֹּחַ הַשְּׁכִינָה מִלִּפְנֵי גְּדוֹלֵי הַמְמֻנִּים שֶׁל שְׁאָר הָעַמִּים, וְאָז יְכוֹלִים לָהֶם שׂוֹנְאֵי יִשְׂרָאֵל וְשׁוֹלְטִים עֲלֵיהֶם וְגוֹזְרִים עֲלֵיהֶם כַּמָּה גְזֵרוֹת רָעוֹת. וּכְשֶׁהֵם שָׁבִים אֵלֶיהָ, הִיא מְשַׁבֶּרֶת הַכֹּחַ וְהַתֹּקֶף שֶׁל שׂוֹנְאֵי יִשְׂרָאֵל וְנִפְרַעַת לָהֶם מִן הַכֹּל."],[1,"","וְעַל כֵּן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ, שֶׁצָּרִיךְ אָדָם שֶׁלֹּא יִטְמָא בַחֲטָאָיו וְיַעֲבֹר עַל דִּבְרֵי תוֹרָה. שֶׁאִם הוּא עוֹשֶׂה כָּךְ, מְטַמְּאִים אוֹתוֹ, כְּמוֹ שֶׁכָּתוּב וְנִטְמֵתֶם בָּם, בְּלִי א'. וְלָמַדְנוּ, מָאתַיִם אַרְבָּעִים וּשְׁמוֹנָה אֵיבָרִים בַּגּוּף, וְכֻלָּם נִטְמָאִים כְּשֶׁהוּא נִטְמָא. כְּלוֹמַר, כְּשֶׁהוּא רוֹצֶה לְהִטָּמֵא. וְעַל כֵּן וְהָיָה מַחֲנֶיךְ קָדוֹשׁ. מַה זֶּה מַחֲנֶיךְ? אֵלּוּ הֵם אֵיבְרֵי הַגּוּף. וְלֹא יִרְאֶה בְךְ עֶרְוַת דָּבָר, מַה זֶּה עֶרְוַת דָּבָר? עֶרְוָה נָכְרִיָּה שֶׁזֶּה (שהוא) דְּבַר רֶמֶז, לַדָּבָר הַזֶּה, כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁאִם כָּךְ, וְשָׁב מֵאַחֲרֶיךְ וַדַּאי. וְעַל כֵּן עֶרְוַת אֵשֶׁת אָבִיךְ לֹא תְגַלֵּה. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב עֶרְוַת אָבִיךְ הִוא, כְּמוֹ שֶׁבֵּאַרְנוּ."],[2,"","לָמַדְנוּ, עַל שְׁלֹשָׁה דְבָרִים מִתְעַכְּבִים יִשְׂרָאֵל בַּגָּלוּת: עַל שֶׁעוֹשִׂים קָלוֹן בַּשְּׁכִינָה בַּגָּלוּת, וּמַחֲזִירִים פְּנֵיהֶם מֵהַשְּׁכִינָה, וְעַל שֶׁמְּטַמְּאִים אֶת עַצְמָם לִפְנֵי הַשְּׁכִינָה, וְאֶת כֻּלָּם בֵּאַרְנוּ בְמִשְׁנָתֵנוּ."],[3,"","רַבִּי אַבָּא הָיָה הוֹלֵךְ לְקַפּוּטְקִיָּא, וְהָיָה עִמּוֹ רַבִּי יוֹסֵי. עַד שֶׁהָיוּ הוֹלְכִים, רָאוּ אִישׁ אֶחָד שֶׁהָיָה בָּא עִם רֹשֶׁם אֶחָד בְּפָנָיו. אָמַר רַבִּי אַבָּא, נִסְטֶה מֵהַדֶּרֶךְ הַזּוֹ, שֶׁהֲרֵי פָּנָיו שֶׁל זֶה מְעִידִים עָלָיו שֶׁעָבַר עַל עֶרְוָה שֶׁל הַתּוֹרָה, כִּי כָּךְ רָשׁוּם בְּפָנָיו. אָמַר לוֹ רַבִּי יוֹסֵי, אִם הָרֹשֶׁם הַזֶּה הָיָה לוֹ כְּשֶׁהָיָה תִּינוֹק, אֵיזוֹ עֶרְוָה תִּמְצָא בּוֹ? אָמַר לוֹ, אֲנִי רוֹאֶה בְפָנָיו שֶׁמְּעִידִים עַל עֶרְוָה שֶׁל הַתּוֹרָה."],[4,"","קָרָא לוֹ רַבִּי אַבָּא, אָמַר לוֹ, אֱמֹר דְּבָרְךְ, הָרֹשֶׁם הַזֶּה שֶׁבְּפָנֶיךְ מַה זֶּה? אָמַר לָהֶם, בְּבַקָּשָׁה מִכֶּם, אַל תַּעֲנִישׁוּ יוֹתֵר אֶת אוֹתוֹ אָדָם, שֶׁהֲרֵי חֲטָאָיו גָּרְמוּ לוֹ. אָמַר רַבִּי אַבָּא, מַהוּ? אָמַר לוֹ, יוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ אֲנִי וַאֲחוֹתִי, וְשָׁהִינוּ בְמָלוֹן אֶחָד וְשָׁתִיתִי יַיִן, וְכָל אוֹתוֹ הַלַּיְלָה אָחַזְתִּי בַאֲחוֹתִי. בַּבֹּקֶר קַמְנוּ, וּבַעַל בֵּית הַמָּלוֹן הִתְקוֹטֵט עִם אִישׁ אֶחָד, וְנִכְנַסְתִּי בֵינֵיהֶם, וְקָשְׁרוּ אוֹתִי זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, וְהָרֹשֶׁם הַזֶּה הָיָה נִכְנָס לַמֹּחַ, וְנִצַּלְתִּי עַל יְדֵי רוֹפֵא אֶחָד שֶׁיֵּשׁ בְּתוֹכֵנוּ."],[5,"","אָמַר לוֹ, מִי הָרוֹפֵא? אָמַר לוֹ, זֶה רַבִּי שַׂמְלַאי. אָמַר לוֹ, אֵיזוֹ רְפוּאָה נָתַן לְךְ? אָמַר לוֹ, רְפוּאַת הַנֶּפֶשׁ. וּמֵאוֹתוֹ יוֹם חָזַרְתִּי בִתְשׁוּבָה. וּבְכָל יוֹם אֲנִי רוֹאֶה אֶת פָּנַי בְּמַרְאָה אַחַת, וַאֲנִי בּוֹכֶה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא רִבּוֹן הָעוֹלָמִים, עַל אוֹתוֹ הַחֵטְא, וּמֵאוֹתָן דְּמָעוֹת רָחַצְתִּי פָנַי. אָמַר רַבִּי אַבָּא, אִם לֹא שֶׁנִּמְנְעָה מִמְּךְ תְּשׁוּבָה, הָיִיתִי מַעֲבִיר מִפָּנֶיךְ אֶת אוֹתוֹ הָרֹשֶׁם, אֲבָל אֲנִי קוֹרֵא עָלֶיךְ, (ישעיה ו) וְסָר עֲוֹנֶךְ וְחַטָּאתְךְ תְּכֻפָּר. אָמַר לוֹ, אֱמֹר שָׁלֹשׁ פְּעָמִים. אָמַר לוֹ שָׁלֹשׁ פְּעָמִים וְהָרֹשֶׁם עָבַר."],[6,"","אָמַר רַבִּי אַבָּא, וַדַּאי אֲדוֹנְךְ רָצָה לְהַעֲבִירוֹ מִמְּךְ, שֶׁוַּדַּאי נִמְצֵאתָ בִּתְשׁוּבָה. אָמַר לוֹ, נָדַרְתִּי מֵהַיּוֹם הַזֶּה לַעֲסֹק בַּתּוֹרָה יוֹמָם וָלַיְלָה. אָמַר לוֹ, מַה שִּׁמְךְ? אָמַר לוֹ, אֶלְעָזָר. אָמַר לוֹ, אֵל עָזַר, וַדַּאי שֶׁהַשֵּׁם גּוֹרֵם שֶׁאֱלֹקֶיךְ סִיַּע לְךְ וְהָיָה בְעֶזְרְךְ. שָׁלַח אוֹתוֹ רַבִּי אַבָּא וּבֵרַךְ אוֹתוֹ."],[7,"","בְּפַעַם אַחֶרֶת הָיָה רַבִּי אַבָּא הוֹלֵךְ אֶל רַבִּי שִׁמְעוֹן, נִכְנַס לְעִירוֹ, מָצָא אוֹתוֹ שֶׁהָיָה יוֹשֵׁב וְדוֹרֵשׁ (תהלים צב) אִישׁ בַּעַר לֹא יֵדָע וּכְסִיל לֹא יָבִין אֶת זֹּאת. אִישׁ בַּעַר לֹא יֵדָע וְגוֹ', כַּמָּה טִפְּשִׁים אוֹתָם בְּנֵי הָעוֹלָם שֶׁלֹּא מַשְׁגִּיחִים וְלֹא יוֹדְעִים וְלֹא מִסְתַּכְּלִים לָדַעַת אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מַה הֵם עוֹמְדִים בָּעוֹלָם, מִי מְעַכֵּב אוֹתָם לָדַעַת? טִפְּשׁוּתָם, כִּי לֹא עוֹסְקִים בַּתּוֹרָה. שֶׁאִלּוּ עוֹסְקִים בַּתּוֹרָה, הָיוּ יוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא."]]],[["וּכְסִיל לֹא יָבִין אֶת זֹאת, דְּלָא מִסְתָּכַל וְלָא יָדַע נִימוּסֵי דְּזֹאת בְּעָלְמָא. (דאף על גב) דְּדָאִין עָלְמָא בְּדִינוֹי וְחַמָאן לְדִינוֹי דְּהַאי זֹאת, דְּמָטָאן עַל בְּנֵי נָשָׁא דְּאִינּוּן זַכָּאִין, וְלָא מָטָאן עַל רַשִׁיעֲיָיא חַיָּיבִין, דְּעַבְרִין עַל פִּתְגָּמֵי אוֹרַיְיתָא, דִּכְתִּיב, (תהילים צ״ב:ח׳) בִּפְרוֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. דְּהַאי עָלְמָא יָרְתִין לֵיהּ בְּכָל סִטְרוֹי, וְדִינִין לָא מָטוּן עָלוֹי בְּהַאי עָלְמָא. וְאִלְמָלֵא דְּדָוִד מַלְכָּא אוֹדְעֵיהּ בְּסוֹפֵיהּ דִּקְרָא, לָא יַדְעֵינָן, דִּכְתִּיב לְהִשָּׁמְדָם עֲדֵי עַד, לְשֵׁיצָאָה לְהוֹן מֵהַהוּא עָלְמָא, וּלְמֶהֱוִי עַפְרָא תְּחוֹת רַגְלֵיהוֹן דְּצַדִּיקַיָּיא, דִּכְתִּיב, (מלאכי ג׳:כ״א) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם.","תּוּ פָּתַח וְאָמַר, (איוב ט״ז:ח׳) וַיָּקָם בִּי כַחֲשִׁי בְּפָנַי יַעֲנֶה. בְּמַאי קָא מַיְירֵי. אֶלָּא, זַכָּאָה חוּלָקֵיהּ דְּבַּר נָשׁ דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, לְמִנְדַע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא. דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא, כְּאִלּוּ אִשְׁתָּדַּל בִּשְׁמֵיהּ מַמָּשׁ. מַה שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד נִימוּסִין. אוּף אוֹרַיְיתָא הָכִי נָמֵי. תָּא חֲזֵי, הַאי מַאן דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, אוֹרַיְיתָא סַלְּקָא וְנַחְתָּא וְעַבְדָא בֵּיהּ בְּבַּר נָשׁ רְשִׁימִין בְּאַנְפּוֹי, בְּגִין דְּיִסְתַּכְּלוּן בֵּיהּ עִלָּאֵי וְתַתָּאֵי, וְכֻלְּהוּ אוֹשְׁדָן לְוָוטִין עַל רֵישֵׁיהּ.","וְתָאנָא, כָּל אִינּוּן עֵינֵי יְיָ', דְּאַזְלִין וְשָׁאטִין בְּעָלְמָא לְמִנְדַּע אוֹרְחוֹי דִּבְנֵי נָשָׁא, כֻּלְּהוֹן זַקְפִין עַיְינִין, וּמִסְתַּכְּלִין בְּאַנְפּוֹי דְּהַהוּא בַּר נָשׁ, וְחָמָאן לְהוּ, וְכֻלְּהוּ פַּתְחִין עָלֵיהּ וַוי וַוי. וַוי לֵיהּ בְּהַאי עָלְמָא, וַוי לֵיהּ בְּעָלְמָא דְּאָתֵי. אִסְתְּלָקוּ מִסּוֹחֲרָנֵיהּ דִּפְלַנְיָא, דְּהָא סַהֲדוּתָא בְּאַנְפּוֹי, וְרוּחָא דִּמְסָאֲבָא שַׁרְיָא עֲלוֹי. וְכָל אִינּוּן יוֹמִין דְּאִשְׁתְּכַח רְשִׁימוּ בְּאַנְפּוֹי לְסַהֲדוּתָא, אִי אוֹלִיד בַּר, אַשְׁלִיף לֵיהּ רוּחָא מִסִּטְרָא דִּמְסָאֲבָא. וְאִלֵּין אִינּוּן חַיָּיבֵי דָּרָא, תַּקִיפֵי אַנְפִּין, דְּמָארֵיהוֹן שָׁבִיק לְהוֹן בְּהַאי עָלְמָא, לְשֵׁיצָאָה לְהוּ בְּעָלְמָא דְּאָתֵי.","תָּנֵינָן, הַאי צַדִּיקָא זַכָּאָה דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא יְמָמָא וְלֵילְיָא, קוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ עָלֵיהּ חַד חוּטָא דְּחֶסֶד, וְאִתְרְשִׁים לֵיהּ בְּאַנְפּוֹי, וּמֵהַהוּא רְשִׁימָא דַּחֲלֵי עִלָּאֵי וְתַתָּאֵי. הָכִי נָמֵי מַאן דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, מַשְׁכָאן עָלֵיהּ רוּחָא דִּמְסָאֲבָא, וְאִתְרְשִׁים לֵיהּ בְּאַנְפּוֹי, וּמִנֵּיהּ עַרְקִין עִלָּאֵי וְתַתָּאֵי. וְכֹלָּא מַכְרְזֵי עָלֵיהּ, אִסְתְּלָקוּ מִסָּחֲרָנֵיהּ דִּפְלַנְיָא, דְּעָבַר עַל פִּתְגָּמֵי אוֹרַיְיתָא, וְעַל פִּקּוּדֵי דְּמָארֵיהּ, וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ. הַאי אַשְׁלִיף רוּחָא דִּמְסָאֲבָא, דְּאִשְׁתְּכַח עִמֵּיהּ, וְאוֹרִית לֵיהּ לִבְרֵיהּ, וְהַאי הוּא דְקוּדְשָׁא בְּרִיךְ הוּא לֵית לֵיהּ בֵּיהּ חוּלָקָא, וְשָׁבִיק לֵיהּ, לְשֵׁיצָאָה לֵיהּ לְעָלְמָא דְּאָתֵי.","אָמַר לֵיהּ רִבִּי אַבָּא, שַׁפִּיר קָאַמְרַת, מְנָא לָךְ הַאי. אָמַר לֵיהּ הָכִי אוֹלִיפְנָא. וְאוֹלִיפְנָא, דְּהַאי יְרוּתָא בִּישָׁא, אַחֲסִינוּן כֻּלְּהוּ בְּנוֹי, אִי לָא יְתוּבוּן, דְּהָא לֵית מִלָּה קַיְּימָא קָמֵי תְּשׁוּבָה. וַאֲנָא הָכִי אוֹלִיפְנָא, דְּאַסוּותָא דָּא יָהֲבוּ לִי זִמְנָא חֲדָא, דַּהֲוִינָא רְשִׁים בְּאַנְפָּאי, וְיוֹמָא חַד הֲוִינָא אָזִיל בְּאוֹרְחָא, וְאִעַרְעָנָא בְּחַד זַכָּאָה, וְעַל יְדוֹי אִתְעַבָּר מִנַּאי הַהוּא רְשִׁימָא. אָמַר לִי, מַה שְׁמָךְ. אָמַר לֵיהּ אֶלְעָזָר, וְקָרֵי עָלַי אֶלְעָזָר אָחֳרָא. אָמַר לֵיהּ, בְּרִיךְ רַחֲמָנָא, דַּחֲמֵינָא לָךְ, וְזָכֵינָא לְמֵחֱמֵי לָךְ בְּהַאי. זַכָּאָה חוּלָקָךְ בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, (אמר ליה) אֲנָא הוּא דְּאִעְרַעְנָא לָךְ.","אִשְׁתָּטַּח קָמֵיהּ, אַיְיתֵיהּ לְבֵיתֵיהּ, אַתְקִין קָמֵיהּ קוּרְטִיסָא (ס\"א טרכוסא) (טרטיסאי) דְּנַהֲמָא, וּבִשְׂרָא דְּעֶגְלָא תְּלִיתָאָה. בָּתַר דְּאָכְלוּ, אָמַר לֵיהּ הַהוּא גַּבְרָא, רִבִּי, אֵימָא לִי חַד מִלָּה, חָדָּא תּוֹרָתָא סוּמָקָא אִית לִי, אִימָּא דְּעֶגְלָא דְּבִישְׂרָא דָּא דַּאֲכִילְנָא, וְיוֹמָא חַד עַד לָא אִתְעַבְּרַת וְאוֹלִידַת, אֲזִילְנָא בַּתְרָאָה לְמַרְעָא לְמַדְבְּרָא, עַד דְּדָבַּרְנָא לָהּ אַעְבָּר קָמַאי חַד גַּבְרָא, אָמַר לֵיהּ, מַה שְׁמָהּ דְּתוֹרָתָא דָּא. אֲמֵינָא, מִן יוֹמָא דְּאִתְיְילִידַת לָא קָרֵינָּא לָהּ בִּשְׁמָא. אָמַר לֵיהּ, בַּת שֶׁבַע אֵם שְׁלֹמֹה אִתְקְרֵי, אִי תִּזְכֶּה לְכַפָּרָה. וַאֲנָא בְּעוֹד דְּאָהָדַרְנָא רֵישָׁאי, לָא חֲמֵינָא לֵיהּ, וְחָיִיכְנָא מֵהַהוּא מִלָּה."],[[0,"וכסיל לא יבין את זאת:","היינו שאינו מסתכל ואינו יודע מנהגי ה \u0003זאת,\u0004 שהיא המלכות הנקראת זאת, בעולם. שאע״פ שהקב״ה דן העולם בדיניו, ואנשים רואים דיניה של \u0003זאת\u0004 זו, שבאים על בני אדם שהם צדיקים, ואינם באים על הרשעים החייבים העוברים על דברי תורה. שכתוב, בפרוח רשעים כמו עשב וגו', שיורשים העולם הזה מכל צדדיו ודינים אינם באים עליהם בעולם הזה. והאנשים אינם יודעים למה. ואם דוד המלך לא הודיע בסוף המקרא לא היינו יודעים, שכתוב, להשמדם עדי עד. שמשלם להם שכר מעשיהם הטובים בעולם הזה, כדי לכלותם מהעולם ההוא, ושיהיו שם עפר תחת רגלי הצדיקים, שכתוב, ועסותם רשעים כי יהיו אפר תחת כפות רגליכם."],[1,"תו פתח ואמר וכו׳:","עוד פו״א, ויקם בי כחשי בפני יענה. שואל, במה עוסק הכתוב. ומשיב, אלא אשרי חלקו של אדם העוסק בתורה לדעת דרכיו של הקב״ה, שכל מי שעוסק בתורה הוא כאלו עוסק בשמו ממש, מה שמו של הקב״ה עושה הנהגות בעולם אף התורה כן. בוא וראה, מי שעבר על דברי תורה, התורה עולה ויורדת ועושה רשימות בפניו של האדם, כדי שיסתכלו בו עליונים ותחתונים, וכולם שופכים קללות על ראשו. וז\"ש, ויקם בי כחשי בפניו יענה, דהיינו הרשימות שהתורה עושה בפניו."],[2,"ותאנא כל אינון וכו׳:","ולמדנו, כל אלו עיני ה׳, דהיינו מלאכי ההשגחה, ההולכות ומשוטטות בעולם לדעת דרכיו של בני אדם, כולם נושאים עיניהם ומסתכלים בפניו של אדם ההוא ורואים אותו, וכולם פותחים עליו אוי אוי, אוי לו בעולם הזה ואוי לו בעולם הבא, העלו מסביב לפלוני, כי העדות בפניו, שרוח הטומאה שורה עליו. וז\"ש בפניו יענה, שהכחש מעיד בפניו. וכל אלו הימים, שהרושם נמצא בפניו לעדות, אם מוליד בן הוא מושך לו רוח מצד הטומאה. ואלו הם רשעי הדור עזי הפנים שאדונם עוזב אותם בעולם הזה כדי לכלותם בעולם הבא."],[3,"תנינן האי צדיקא וכו׳:","למדנו, צדיק זכאי ההוא העוסק בתורה יום ולילה, הקב״ה מושך עליו חוט אחד של חסד, ונרשם לו בפניו, ומאותו הרושם יראים העליונים והתחתונים. אף כך, מי שעובר על דברי תורה, מושכים עליו רוח הטומאה ונרשם לו בפניו, שממנו בורחים העליונים ותחתונים, והכל מכריזים עליו, העלו מסביב לפלוני, שעבר על דברי תורה, ועל מצות אדונו, אוי לו אוי לנפשו. זה מושך רוח הטמאה הנמצא עמו, ומורישו לבנו. וזה הוא שהקב״ה אין לו חלק בו, ועוזב אותו לכלותו לעולם הבא."],[4,"אמר ליה ר׳ אבא וכו׳:","א״ל ר״א, יפה אמרת. מאין לך זה. א\"ל כך למדתי. ולמדתי שאותה ירושה הרעה, של רוח הטומאה, יורשים כל בניו, אם אינם חוזרים בתשובה, כי אין לך דבר העומד בפני תשובה. ואני כך למדתי, שרפואה זו, דהיינו תשובה, נתנו לי פעם אחת בעת שהייתי נרשם בפני. ויום אחד הייתי הולך בדרך ופגשתי בזכאי אחד, ועל ידו נעבר ממני רושם ההוא. אמר לי מה שמך. אמרתי לו אלעזר. וקרא עלי אלעזר אחר. אמר לו ר׳ אבא, ברוך הרחמן שראיתי אותך, וזכיתי לראותך בזה. אשרי חלקך בעולם הזה ובעולם הבא. אני הוא שפגשתי אותך."],[5,"אשתטח קמיה אייתיה וכו׳:","השתטח לפניו. אותו האיש אלעזר, הביאו לביתו, ועשה לפניו שלש סאים לחם, ועגל משולש. אחר שאכלו, אמר לו אותו האיש, רבי, אמור לי דבר אחד. פרה אדומה אחת היתה לי, אמו של העגל, שאנו אוכלים את בשרו, ויום אחד, מטרם שנתעברה והולידה, הלכתי אחריה למרעה אל המדבר, ובעוד שהנהגתי אותה, עבר לפני אדם אחד, אמר לי מה שמה של פרה זו. אמרתי, מיום שנולדה לא קראתיה בשם. אמר לי, בת שבע אם שלמה נקראת, אם תזכה לכפרה על עונותיך. ואני, בעוד שהחזרתי ראשי, לא ראיתי אותו. וצחקתי מדבר ההוא. \u0003טרטיסאי\u0004 פירושה שלש סאים, כי מורכבת מב' מלות, \u0003טרטי\u0004 פירושה שלש. בלע״ז, \u0003סאי\u0004 היינו סאים."]],[[0,"","וּכְסִיל לֹא יָבִין אֶת זֹּאת, שֶׁלֹּא מִתְבּוֹנֵן וְלֹא יוֹדֵעַ הַהַנְהָגוֹת שֶׁל זֹּאת בָּעוֹלָם. (שאף על גב) שֶׁדָּן אֶת הָעוֹלָם בְּדִינָיו וְרוֹאִים אֶת דִּינֶיהָ שֶׁל זֹּאת הַזּוֹ שֶׁמַּגִּיעִים לִבְנֵי אָדָם שֶׁהֵם צַדִּיקִים, וְלֹא מַגִּיעִים עַל הָרְשָׁעִים הַחַיָּבִים שֶׁעוֹבְרִים עַל דִּבְרֵי הַתּוֹרָה, שֶׁכָּתוּב בִּפְרוֹחַ רְשָׁעִים כְּמוֹ עֵשֶׂב וְגוֹ'. שֶׁאֶת הָעוֹלָם הַזֶּה הֵם יוֹרְשִׁים אוֹתוֹ בְּכָל צְדָדָיו, וְהַדִּינִים לֹא מַגִּיעִים אֲלֵיהֶם בָּעוֹלָם הַזֶּה. וְאִלְמָלֵא שֶׁדָּוִד הַמֶּלֶךְ הוֹדִיעַ אוֹתוֹ בְּסוֹף הַכָּתוּב, לֹא הָיִינוּ יוֹדְעִים, שֶׁכָּתוּב לְהִשָּׁמְדָם עֲדֵי עַד, לְהַשְׁמִידָם מֵאוֹתוֹ הָעוֹלָם, וְשֶׁיִּהְיוּ עָפָר תַּחַת רַגְלֵי הַצַּדִּיקִים, שֶׁכָּתוּב (מלאכי ג) וְעַסּוֹתֶם רְשָׁעִים כִּי יִהְיוּ אֵפֶר תַּחַת כַּפּוֹת רַגְלֵיכֶם."],[1,"","עוֹד פָּתַח וְאָמַר, (איוב טז) וַיָּקָם בִּי כַחֲשִׁי בְּפָנַי יַעֲנֶה. בַּמֶּה מְדֻבָּר? אֶלָּא אַשְׁרֵי חֶלְקוֹ שֶׁל אָדָם שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לָדַעַת אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּאִלּוּ הִשְׁתַּדֵּל בִּשְׁמוֹ מַמָּשׁ. מַה שְּׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה הַנְהָגוֹת, אַף הַתּוֹרָה גַּם כֵּן. בּא וּרְאֵה, מִי שֶׁעוֹבֵר עַל דִּבְרֵי תוֹרָה, הַתּוֹרָה עוֹלָה וְיוֹרֶדֶת וְעוֹשָׂה בָּאָדָם רִשּׁוּמִים בְּפָנָיו, כְּדֵי שֶׁיִּסְתַּכְּלוּ בוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכֻלָּם שׁוֹפְכִים קְלָלוֹת עַל רֹאשׁוֹ."],[2,"","וְלָמַדְנוּ, כָּל אוֹתָם עֵינֵי ה' שֶׁהוֹלְכִים וּמְשׁוֹטְטִים בָּעוֹלָם לָדַעַת אֶת דַּרְכֵי בְּנֵי אָדָם, כֻּלָּם זוֹקְפִים עֵינַיִם וּמִסְתַּכְּלִים בִּפְנֵי אוֹתוֹ הָאִישׁ, וְרוֹאִים אוֹתָם, וְכֻלָּם פּוֹתְחִים עָלָיו: וַי וַי. אוֹי לוֹ בָּעוֹלָם הַזֶּה, וְאוֹי לוֹ בָּעוֹלָם הַבָּא. הִסְתַּלְּקוּ מִסָּבִיב לִפְלוֹנִי, שֶׁהֲרֵי עֵדוּת בְּפָנָיו, וְרוּחַ טֻמְאָה שׁוֹרָה עָלָיו. וְכָל אוֹתָם יָמִים שֶׁנִּמְצָא רֹשֶׁם בְּפָנָיו לְעֵדוּת, אִם מוֹלִיד בֵּן, הוּא שׁוֹלֵף לוֹ רוּחַ מִצַּד הַטֻּמְאָה, וְאֵלּוּ הֵם הָרְשָׁעִים שֶׁל הַדּוֹר, עַזֵּי הַפָּנִים, שֶׁרִבּוֹנָם עוֹזֵב אוֹתָם בָּעוֹלָם הַזֶּה לְהַשְׁמִידָם לָעוֹלָם הַבָּא."],[3,"","שָׁנִינוּ, הַצַּדִּיק הַזַּכַּאי הַזֶּה שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשֵׁךְ עָלָיו חוּט אֶחָד שֶׁל חֶסֶד וְנִרְשָׁם לוֹ בְּפָנָיו, וּמֵאוֹתוֹ רֹשֶׁם פּוֹחֲדִים עֶלְיוֹנִים וְתַחְתּוֹנִים. כָּךְ גַּם מִי שֶׁעוֹבֵר עַל דִּבְרֵי תוֹרָה, מוֹשְׁכִים עָלָיו רוּחַ טֻמְאָה וְנִרְשָׁם לוֹ בְּפָנָיו, וּמִמֶּנּוּ בּוֹרְחִים עֶלְיוֹנִים וְתַחְתּוֹנִים. וְכֻלָּם מַכְרִיזִים עָלָיו: הִסְתַּלְּקוּ מִסָּבִיב לִפְלוֹנִי, שֶׁעָבַר עַל דִּבְרֵי תוֹרָה וְעַל מִצְווֹת רִבּוֹנוֹ. אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ! הֲרֵי שָׁלַף רוּחַ טֻמְאָה שֶׁנִּמְצֵאת עִמּוֹ וְהוֹרִישָׁהּ לִבְנוֹ, וְזֶהוּ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אֵין לוֹ בּוֹ חֵלֶק, וְעוֹזֵב אוֹתוֹ לְהַשְׁמִידוֹ לָעוֹלָם הַבָּא."],[4,"","אָמַר לוֹ רַבִּי אַבָּא, יָפֶה אָמַרְתָּ, אֲבָל מִנַּיִן לְךְ אֶת זֶה? אָמַר לוֹ, כָּךְ לָמַדְתִּי, וְלָמַדְתִּי שֶׁהַיְרֻשָּׁה הָרָעָה הַזּוֹ יוֹרְשִׁים כָּל בָּנָיו, אִם לֹא שֶׁיָּשׁוּבוּ, שֶׁהֲרֵי אֵין דָּבָר שֶׁעוֹמֵד לִפְנֵי תְשׁוּבָה. וַאֲנִי כָּךְ לָמַדְתִּי, שֶׁרְפוּאָה זוֹ נָתְנוּ לִי פַּעַם אַחַת, שֶׁהָיִיתִי רָשׁוּם בְּפָנַי, וְיוֹם אֶחָד הָיִיתִי הוֹלֵךְ בַּדֶּרֶךְ וּפָגַשְׁתִּי צַדִּיק אֶחָד, וְעַל יָדוֹ עָבַר מִמֶּנּוּ אוֹתוֹ הָרֹשֶׁם. אָמַר לִי, מַה שִּׁמְךְ? אָמַרְתִּי לוֹ, אֶלְעָזָר, וְקָרָא עָלַי אֶלְעָזָר אַחֵר. אָמַר לוֹ, בָּרוּךְ הָרַחֲמָן שֶׁרָאִיתִי אוֹתְךְ וְזָכִיתִי לִרְאוֹתְךְ בָּזֶה. אַשְׁרֵי חֶלְקְךְ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. (אמר לו,) אֲנִי הוּא שֶׁפָּגַשְׁתִּי בְּךְ."],[5,"","הִשְׁתַּטַח לְפָנָיו וֶהֱבִיאוֹ לְבֵיתוֹ. הִתְקִין לְפָנָיו חַלַּת (טרכוסא) לֶחֶם וּבָשָׂר שֶׁל עֶגְלָה מְשֻׁלֶּשֶׁת. אַחַר שֶׁאָכְלוּ, אָמַר לוֹ אוֹתוֹ הָאִישׁ: רַבִּי, אֱמֹר לִי דָּבָר אֶחָד, פָּרָה אֲדֻמָּה יֵשׁ לִי, אִמּוֹ שֶׁל הָעֵגֶל שֶׁאֶת בְּשָׂרוֹ זֶה עַתָּה אָכַלְנוּ, וְיוֹם אֶחָד טֶרֶם שֶׁהִתְעַבְּרָה וְהוֹלִידָה, הָלַכְתִּי אַחֲרֶיהָ לַמִּרְעֶה בַּמִּדְבָּר, בְּעוֹד שֶׁאֲנִי מַנְהִיג אוֹתָהּ עָבַר לְפָנַי אִישׁ אֶחָד, אָמַר לִי, מַה שְּׁמָהּ שֶׁל הַפָּרָה הַזּוֹ? אָמַרְתִּי, מִיּוֹם שֶׁנּוֹלְדָה לֹא קְרָאתִיהָ בְשֵׁם. אָמַר לִי, הִיא נִקְרֵאת בַּת שֶׁבַע אֵם שְׁלֹמֹה, אִם תִּזְכֶּה לְכַפָּרָה. וַאֲנִי, בְּעוֹד שֶׁהֶחֱזַרְתִּי אֶת רֹאשִׁי, לֹא רָאִיתִי אוֹתוֹ, וְצָחַקְתִּי מֵאוֹתוֹ הַדָּבָר."]]],[["וְהַשְׁתָּא דְּזָכִינָא בְּאוֹרַיְיתָא, אִתְּעַרְנָא עַל הַהִיא מִלָּה, וּמִן יוֹמָא דְּאִתְפְּטָר רִבִּי שַׂמְלָאי מֵהָכָא, לָא הֲוָה בַּר נָשׁ דְּיַנְהִיר לָן בְּאוֹרַיְיתָא כְּוָותֵיהּ. וַאֲנָא דָּחִילְנָא לְמֵימַר מִלָּה דְּאוֹרַיְיתָא דְּלָא אוֹלִיפְנָא. וּמִלָּה דָּא דְּאִסְתַּכַּלְנָא דְּמִלָּה דְּחָכְמְתָא הִיא, וְלָא יְדַעְנָא. אָמַר לֵיהּ, וַדַּאי מִלָּה דְּחָכְמְתָא הִיא, וּרְמִיזָא עִלָּאָה הִיא לְעֵילָּא וּלְתַתָּא.","אֲבָל תָּא חֲזֵי, בַּת שֶׁבַע אִתְקְרֵי מַמָּשׁ בְּרָזָא דְּחָכְמְתָא. בְּגִין כָּךְ כְּתִיב בָּהּ כֹּלָּא בְּשֶׁבַע. ז' פָּרוֹת. ז' שְׂרֵפוֹת. ז' הֲזָאוֹת. ז' כִּבּוּסִים. ז' טְמֵאִים. ז' טְהוֹרִים. ז' כֹּהֲנִים. וּמֹשֶׁה וְאַהֲרֹן בְּחוּשְׁבְּנָא דְּהָא כְּתִיב, וַיְדַבֵּר יְיָ' אֶל מֹשֶׁה וְאַהֲרֹן וְגוֹ'. וְשַׁפִּיר קָאָמַר הַהוּא גַּבְרָא, דְּאָמַר בַּת שֶׁבַע, וְכֹלָּא רָזָא דְּחָכְמְתָא הִיא.","אָמַר לֵיהּ, בְּרִיךְ רַחֲמָנָא דְּשָׁמַעְנָא מִלָּה דָּא. בְּרִיךְ הוּא דְּהָא אַקְדִּים לִי שְׁלָם בְּקַדְמִיתָא, לְמִזְכֵּי לְהַאי. דִּכְתִּיב (ישעיהו נ״ז:י״ט) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר יְיָ'. אֲנָא כַּד הֲוִינָא רָחוֹק, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים לִי שְׁלָם לְמֶהֱוִי קָרוֹב. קָרָא עָלֵיהּ רִבִּי אַבָּא, (שמואל א כ״ה:ו׳) אַתָּה שָׁלוֹם וּבֵיתְךָ שָׁלוֹם וְכֹל אֲשֶׁר לְךָ שָׁלוֹם.","(ויקרא ח\"י) עֶרְוַת אֲחוֹת אָבִיךָ לֹא תְגַלֵּה. רִבִּי חִיָּיא פָּתַח, וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחוֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְרָאָה אֶת עֶרְוָתָהּ וְגוֹ'. תַּמָּן תָּנֵינָן, מְאָה וּתְלָתִין שְׁנִין, אִתְפְּרַשׁ אָדָם מְאִתְּתֵיהּ, וְלָא הֲוָה אוֹלִיד. מִדְּקָטַל קַיִן לְהֶבֶל, לָא בָּעָא אָדָם לְאִזְדַּוְּוגָא בְּאִתְּתֵיהּ. רִבִּי יוֹסֵי אָמַר, מִשַׁעֲתָא דְּאִתְגְּזַר עָלֵיהּ וְעַל כָּל עָלְמָא מִיתָה, אָמַר, אֲמַאי אֲנָא אוֹלִיד לִבְעַתּוּתָא. מִיַּד אִתְפְּרַשׁ מֵאִתְּתֵיהּ.","וּתְרֵין רוּחִין נוּקְבִין, הֲווֹ אַתְיָין וְאִזְדַּוְּוגָן עִמֵּיהּ, וְאוֹלִידוּ. וְאִינּוּן דְּאוֹלִידוּ הֲווֹ מַזִּיקִין דְּעָלְמָא, וְאִקְרוּן נִגְעֵי בְּנֵי אָדָם. וְאִלֵּין סָאטָן לִבְנֵי אָדָם, וְשַׁרְיָין בְּפִתְחָא דְּבֵיתָא, וּבְבִירָאֵי, וּבְבָתֵּי כִּסְאֵי. וְעַל דָּא בַּר נָשׁ, דְּאִשְׁתְּכַח בְּפִתְחָא דְּבֵיתֵיהּ שְׁמָא קַדִּישָׁא שַׁדַּי בְּכִתְרִין עִלָּאִין, כֻּלְּהוּ עַרְקָאן וְאִתְרַחֲקָן מִנֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י׳) וְנֶגַע לָא יִקְרַב בְּאָהֳלֶךָ. מַאי וְנֶגַע לָא יִקְרַב. אִלֵּין נִגְעֵי בְּנֵי אָדָם.","וְתָאנָא, בְּשַׁעֲתָא דְּנָחַת אָדָם בְּדִיּוּקְנָא עִלָּאָה, בְּדִיּוּקְנָא קַדִּישָׁא, וְחָמוּ לֵיהּ עִלָּאֵי וְתַתָּאֵי, כֻּלְּהוּ קְרִיבוּ גַּבֵּיהּ, וְאַמְלְכוּהוּ עַל הַאי עָלְמָא. בָּתַר דְּאָתָא חִוְיָא עַל חַוָּה, וְאָטִיל בָּהּ זוּהֲמָא, לְבָתַר אוֹלִידַת קַיִן. (בראשית קע\"ח ע\"א) מִתַּמָּן (ס\"א נתייחסו) נִתְחַיְיבוּ כָּל דָּרִין חַיָּיבִין דְּעָלְמָא. וּמָדוֹרָא דְּשֵׁדִין וְרוּחִין, מִתַּמָּן אִשְׁתְּכָחוּ, וּמִסִּטְרוֹי. וּבְגִּינֵי כַּךְ כָּל רוּחִין וְשֵׁדִין, פַּלְגּוּתָא אִית בְּהוּ מִבְּנֵי נָשָׁא דִּלְתַתָּא, וּפַלְגּוּתָא מִמַּלְאֲכֵי עִלָּאֵי דִּלְעֵילָּא. וְכֵן כַּד אִתְיְילִידוּ מֵאָדָם אִינּוּן אָחֳרָנִין, כֻּלְּהוּ אִשְׁתְּכָחוּ כְּהַאי גַּוְונָא, פַּלְגוּ מִתַּתָּאֵי, וּפַלְגּוּ מֵעִלָּאֵי.","בָּתַר דְּאִתְיְילִידוּ מֵאָדָם, (ס\"א אהדרו ליה קצת מאינון רוחין דנפקו מתיאובתיה בחלמא) אוֹלִיד מֵאִינּוּן רוּחֵי בְּנָתָן, דְּדַמְיָן לִשְׁפִּירוּ דְּעִלָאֵי, וּלִשְׁפִּירוּ דְּתַתָּאֵי. וְעַל דָּא כְּתִיב, (בראשית ו׳:ב׳) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טוֹבוֹת הֵנָּה וְגוֹ', וְטָעָן כֹּלָּא בַּתְרַיְיהוּ. וְחַד דְּכוּרָא אִשְׁתְּכַח, דְּאָתָא לְעָלְמָא מִרוּחֵיהּ דְּסִטְרָא דְּקַיִן, וְקָרוּן לֵיהּ תּוּבַל קַיִן. וַחֲדָא נוּקְבָּא נָפְקַת עִמֵּיהּ, וַהֲווּ בִּרְיָין וְטָעָאן בַּתְרָאָה, וְאִתְקְרֵי נַעֲמָ\"ה. מִינָּהּ נַפְקוּ רוּחִין וְשֵׁדִין אָחֳרָנִין. וְאִינּוּן (בראשית צ\"ב ע\"א, י\"ו ע\"א, קמ\"ג ע\"ב, ר\"ה ע\"א) תַּלְיָין בַּאֲוִירָא, וְאוֹדְעִין מִלִּין לְאִינּוּן אָחֳרָנִין דִּשְׁכִיחִין לְתַתָּא.","וְדָא תּוּבַל קַיִן, אַפִּיק זַיְינֵי קִטּוּלָא לְעָלְמָא. וְדָא נַעֲמָה אִתְרְגִישַׁת בְּרִיגְשָׁהָא, וְאִתְדַּבְּקַת בְּסִטְרָהָא. וְעַד כְּעַן הִיא קַיְּימָא, וּמָדוֹרָהָא בֵּין רִיגְשֵׁי יַמָּא רַבָּא, וְנַפְקַת וְחַיְּיכַת בִּבְנֵי נָשָׁא, וְאִתְחַמְּמַת מִנַּיְיהוּ בְּחֶלְמָא, בְּהַהוּא תִּיאוּבְתָּא דְּבַּר נָשׁ, וְאִתְדַּבְּקַת בֵּיהּ. תִּיאוּבְתָּא נַטְלַת וְלָא יַתִּיר. וּמֵהַהוּא תִּיאוּבְתָּא אִתְעַבְּרַת, וְאַפִּיקַת זַיְנִין אָחֳרָנִין לְעָלְמָא.","וְאִלֵּין בְּנִין דְּאוֹלִידַת מִבְּנֵי נָשָׁא, מִשְׁתַּכְּחִין לָקֳבְלֵי נוּקְבֵי בְּנֵי נָשָׁא, וּמִתְעַבְּרָן מִנַּיְיהוּ, וְאוֹלִידָן רוּחִין, וְכֻלְּהוּ אַזְלִין לְלִילִית קַדְמִיתָא, וְהִיא מְגַדֶּלֶת לוֹן. וְהִיא נַפְקַת לְעָלְמָא, וּבַעְיָא רַבְיָיהָא, וְחָמַת רַבְיֵי בְּנֵי נָשָׁא, וְאִתְדַּבְּקַת בְּהוּ, לְקָטְלָא לְהוּ, וּלְאִשְׁתְּאֲבָא בְּרוּחַיְיהוּ דְּרַבְיֵי בְּנֵי נָשָׁא וְהִיא אַזְלַת בְּהַהוּא רוּחָא (נ\"א רביא), וְאִזְדַמְּנָן תַּמָּן ג' רוּחִין קַדִּישִׁין, וְטָאסִין קַמָּהּ, וְנַטְלִין הַהוּא רוּחָא (נ\"א רביא) מִנָּהּ, וּמַנִיחִין לֵיהּ קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, וְתַמָּן מִתְגַּלְּפֵי (ס\"א מתאלפי) קַמֵּיהּ."],[[0,"והשתא דזכינא וכו׳:","ועתה שזכיתי בתורה, נתעוררתי על דבר ההוא. ומיום שנפטר ר׳ שמלאי מכאן, לא היה אדם שיאיר לנו בתורה כמותו, ואני מפחד לומר דבר תורה שלא למדתי, ודבר זה שאמר לי האיש, הסתכלתי בו שהוא דבר חכמה. ואיני יודע. אמר לו, ודאי דבר חכמה הוא. והוא רמז עליון למעלה ולמטה."],[1,"אבל ת״ח בת שבע וכו׳:","אבל בוא וראה, היא, הפרה האדומה נקראת ממש בת שבע, בסוד החכמה, שהיא המלכות הנקראת פרה מבחינת השמאל שבה, שהזכר שור והנקבה פרה. והיא אדומה, מחמת הגבורות. משום זה כתוב בה הכל בשבע, שבע פרות, שנזכר בפרשה ז׳ פעמים פרה. וכן שבן שרפות, ז׳ הזאות, ז׳ כבוסים, ז׳ טמאים, ז׳ טהורים ז׳ כהנים ומשה ואהרן בחשבון הז', שגם הם נקראים כהנים, כי כתוב בפרשה, וידבר ה׳ אל משה ואהרן וגו'. ויפה אמר אותו האיש, שאמר בת שבע. והכל הוא סוד החכמה."],[1,"","פירוש. אותו אדם שראה אצלו פרה אדומה, רמז לו על שורש פרה אדומה למעלה, שהוא המלכות, שקרא אותה בת שבע. מפני שהיא כלולה מז' ספירות חג״ת נהי״מ. ומשום זה כתוב בפרשת פרה אדומה ז׳ פרות ז׳ שרפות וכו׳ לרמז על ז׳ ספירות שלה. ואין להקשות הרי רק ז׳ פעמים טהור וז׳ כהנים נמצאים בפרשה, וכן ז״פ טמא. משא״כ השאר, אינו נמצא רק ה׳ פעמים בפרשה. והענין הוא כי בספירות העליונות מספר ה׳ ומספר שבע שוים. כי בז' ספירות אין יותר מה׳ ספירות חג״ת נ״ה, וספירת היסוד אינה מוסיף כלום, להיותו רק כולל ה׳ ספירות חג״ת נ״ה, וכן המלכות היא כולל ב׳ של ה״ס חג״ת נ״ה. הרי שבז״ס אין יותר מה״ס, וכן בה״ס יש כל הז׳ ספירות."],[2,"א״ל בריך רחמנא וכו׳:","אמר לו, ברוך הרחמן ששמעתי דבר זה. ברוך הוא שהקדים לי שלום בתחילה כדי לזכות לזה. שכתוב, שלום שלום לרחוק ולקרוב אמר ה'. אני כשהייתי רחוק הקב״ה הקדים לי שלום, דהיינו שקרב אותי, להיות קרוב. קרא עליו ר׳ אבא. אתה שלום וביתך שלום וכל אשר לך שלום."],[3,"ערות אחות אביך לא תגלה וכו׳:","ר׳ חייא פתח, ואיש אשר יקח את אחותו בת אביו או בת אמו וראה את ערותה וגו'. שם למדנו. מאה ושלשים שנה פירש עצמו אדם מאשתו, ולא היה מוליד. מאחר שהרג קין את הבל, לא רצה אדם להזדווג באשתו. ר׳ יוסי אמר, משעה שנגזרה המיתה עליו ועל כל העולם, אמר למה אני מוליד לכליון, מיד נפרש מאשתו."],[4,"ותרין רוחין נוקבין וכו׳:","וב׳ רוחות נקבות היו באות ומזדווגות עמו, והולידו. ואלו שהולידו, היו מזיקי עולם, ונקראים נגעי בני אדם. ואלו מעופפים לבני אדם, ושורים בפתח הבית ובבורות ובבתי כסא. וע״כ אדם, שבפתח ביתו נמצא השם הקדוש \u0003שדי,\u0004 שבספירות עליונות, כל המזיקים בורחים ומתרחקים ממנו. ז\"ש ונגע לא יקרב באהלך. מהו ונגע לא יקרב. הוא, נגעי בני אדם, הנזכרים."],[5,"ותאנא בשעתא דנחית וכו׳:","ולמדנו, בשעה שירד אדם בצורה העליונה, בצורה הקדושה, וראו אותו עליונים ותחתונים, קרבו אליו כולם, והמליכוהו על העולם הזה. אחר שבא הנחש על חוה, והטיל בה זוהמא, הולידה אחר כך את קין ומאותו הזוהמא של הנחש יצא קין. משם נתיחסו כל דורות רשעי העולם, והמדורים של שדים ורוחות נמצאים משם ומצדדיו. ומשום זה כל הרוחות והשדים שבעולם חצים יש בהם מבני אדם למטה, וחצים ממלאכי עליונים שלמעלה. כי הם נולדו חצים מזוהמת הנחש, שמלאך סמאל היה רוכב עליו (כנ״ל ב״א אות תל״ז) וע״כ חצים ממלאכים. וחצים האחר הוא כבני אדם משום שנולדו מקין, שהיה אדם. וכן אלו שדים האחרים כשנולדו מאדם, ע\"י ב׳ רוחות נוקבין הנ״ל, נמצאים כולם באותו אפן, שחצים מתחתונים וחצים מעליונים."],[6,"בתר דאתילידו מאדם וכו׳:","אחר שנולדו השדים מאדם, הוליד בנות מאלו הרוחות שהיו דומות ליופי של העליונים ויופי של התחתונים. וע״כ כתוב, ויראו בני האלהים את בנות האדם כי טובות הנה וגו'. והכל היו טועים אחריהן. וזכר אחד נמצא, שבא לעולם מן הרוח שמצד קין, וקראו אותו, \u0003תובל קין.\u0004 ונקבה אחת יצאה עמו, והיו הבריות טועים אחריה, ונקראת \u0003נעמה,\u0004 ממנה יצאו רוחות ושדים אחרים. והם תלוים באויר, ומודיעים דברים לאלו האחרים הנמצאים למטה, בעולם."],[7,"ודא תובל קין וכו׳:","ותובל קין זה, הוציא כלי הריגה לעולם, שהיה לוטש כל חרש נחשת וברזל. ונעמה זו היתה מתרגשת ברגשיה, ונתדבקת בצד שלה. ועד עתה היא עומדת ושוכנת בין שאון הים הגדול, ויוצאת ומצחקת בבני אדם ומתחממת מהם בחלום באותה התשוקה של האדם, ומתדבקת בו. היא לוקחת ממנו התשוקה, ולא יותר. ומאותה התשוקה, היא מתעברת ומוציאה מינים שדים אחרים לעולם."],[8,"ואלין בנין וכו׳:","ואלו הבנים דהיינו השדים והרוחות, שהיא מולידה מבני אדם, נמצאים, נראים בחלום, כנגד הנקבות מבני אדם, ומתעברות מהם ומולידות רוחות. וכולם הולכים ללילית הראשונה, והיא מגדלת אותם. והיא יוצאת לעולם ומבקשת ילדים, ורואה ילדי בני אדם ומתדבקת בהם להרג אותם, ולהתדבק ברוחם של ילדי בני אדם, והיא הולכת עם הרוח ההוא. ומזדמנים שם ג׳ רוחות קדושים ומעופפים לפניה, ולוקחים ממנה רוח ההוא, ומניחים אותו לפני הקב\"ה, ושם לומדים לפניו."]],[[0,"","וְעַכְשָׁו שֶׁזָּכִיתִי בַּתּוֹרָה, הִתְעוֹרַרְתִּי עַל הַדָּבָר הַהוּא, ף וּמִיּוֹם שֶׁנִּפְטַר מִכָּאן רַבִּי שַׂמְלַאי, לֹא הָיָה אִישׁ שֶׁיָּאִיר לָנוּ בַּתּוֹרָה כְּמוֹתוֹ, וַאֲנִי פָחַדְתִּי לוֹמַר דְּבַר תּוֹרָה שֶׁלֹּא לָמַדְתִּי. וְהַדָּבָר הַזֶּה שֶׁהִסְתַּכַּלְתִּי שֶׁדְּבַר חָכְמָה הוּא, וְלֹא יָדַעְתִּי. אָמַר לוֹ, וַדַּאי שֶׁזֶּהוּ דְּבַר חָכְמָה, וְרֶמֶז עֶלְיוֹן הוּא לְמַעְלָה וּלְמַטָּה."],[1,"","אֲבָל בֹּא רְאֵה, בַּת שֶׁבַע נִקְרֵאת מַמָּשׁ בְּסוֹד הַחָכְמָה, מִשּׁוּם כָּךְ כָּתוּב בָּהּ הַכֹּל בְּשֶׁבַע: שֶׁבַע פָּרוֹת, שֶׁבַע שְׂרֵפוֹת, שֶׁבַע הַזָּאוֹת, שִׁבְעָה כִבּוּסִים, שִׁבְעָה טְמֵאִים, שִׁבְעָה טְהוֹרִים, שִׁבְעָה כֹהֲנִים. וּמֹשֶׁה וְאַהֲרֹן בַּחֶשְׁבּוֹן, שֶׁכָּתוּב וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאַהֲרֹן וְגוֹ'. וְיָפֶה אָמַר אוֹתוֹ הָאִישׁ שֶׁאָמַר בַּת שֶׁבַע, וְהַכֹּל הוּא סוֹד שֶׁל חָכְמָה."],[2,"","אָמַר לוֹ, בָּרוּךְ הָרַחֲמָן שֶׁשָּׁמַעְתִּי דָּבָר זֶה, בָּרוּךְ הוּא, שֶׁהֲרֵי הִקְדִּים לִי שָׁלוֹם בָּרִאשׁוֹנָה לִזְכּוֹת לָזֶה, שֶׁכָּתוּב (ישעיה נז) שָׁלוֹם שָׁלוֹם לָרָחוֹק וְלַקָּרוֹב אָמַר ה'. כְּשֶׁאֲנִי הָיִיתִי רָחוֹק, הִקְדִּים לִי הַקָּדוֹשׁ בָּרוּךְ הוּא שָׁלוֹם לִהְיוֹת קָרוֹב. קָרָא עָלָיו רַבִּי אַבָּא, (שמואל א כה) אַתָּה שָׁלוֹם וּבֵיתְךְ שָׁלוֹם וְכֹל אֲשֶׁר לְךְ שָׁלוֹם."],[3,"","עָרְוַת אֲחוֹת אָבִיךְ לֹא תְגַלֵּה. רַבִּי חִיָּיא פָּתַח, וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְרָאָה אֶת עֶרְוָתָהּ וְגוֹ'. שָׁם שָׁנִינוּ, מֵאָה וּשְׁלֹשִׁים שָׁנָה פָּרַשׁ אָדָם מֵאִשְׁתּוֹ וְלֹא הָיָה מוֹלִיד. מִשֶּׁהָרַג קַיִן אֶת הֶבֶל לֹא רָצָה אָדָם לְהִזְדַּוֵּג עִם אִשְׁתּוֹ. רַבִּי יוֹסֵי אָמַר, מִשָּׁעָה שֶׁנִּגְזְרָה עָלָיו וְעַל כָּל הָעוֹלָם מִיתָה. אָמַר, לָמָּה אֲנִי אוֹלִיד לַבֶּהָלָה? מִיָּד פָּרַשׁ מֵאִשְׁתּוֹ."],[4,"","וּשְׁתֵּי רוּחוֹת נְקֵבוֹת הָיוּ בָאוֹת וּמִזְדַּוְּגוֹת עִמּוֹ וְהוֹלִידוּ. וְאוֹתָם שֶׁהוֹלִידוּ הָיוּ הַמַּזִּיקִים שֶׁל הָעוֹלָם, וְנִקְרָאִים נִגְעֵי בְּנֵי אָדָם, וְאֵלֶּה מְסִיתִים בְּנֵי אָדָם וְשׁוֹרִים בְּפֶתַח הַבַּיִת וּבְבוֹרוֹת וּבְבָתֵּי הַכִּסֵּא. וְעַל כֵּן בֶּן אָדָם שֶׁנִּמְצָא בְּפֶתַח בֵּיתוֹ הַשֵּׁם הַקָּדוֹשׁ שַׁדַּי בִּכְתָרִים עֶלְיוֹנִים, כֻּלָּם בּוֹרְחִים וּמִתְרַחֲקִים מִמֶּנּוּ. זֶהוּ שֶׁכָּתוּב (תהלים צא) וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. מַה זֶּה וְנֶגַע לֹא יִקְרַב? אֵלּוּ נִגְעֵי בְּנֵי אָדָם."],[5,"","וְלָמַדְנוּ, בְּשָׁעָה שֶׁיָּרַד אָדָם בִּדְיוֹקָן עֶלְיוֹן, בִּדְיוֹקָן קָדוֹשׁ, וְרָאוּ אוֹתוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים, כֻּלָּם קָרְבוּ אֵלָיו וְהִמְלִיכוּהוּ עַל הָעוֹלָם הַזֶּה. לְאַחַר שֶׁבָּא הַנָּחָשׁ עַל חַוָּה וְהִטִּיל בָּהּ זֻהֲמָה, אַחַר כָּךְ הוֹלִידָה אֶת קַיִן, וּמִשָּׁם (נתיחסו) נִתְחַיְּבוּ כָּל דּוֹרוֹת הָרְשָׁעִים בָּעוֹלָם. וּמְדוֹר הַשֵּׁדִים וְהָרוּחוֹת מִשָּׁם נִמְצְאוּ, וּמִצִּדּוֹ. וּמִשּׁוּם כָּךְ כָּל הַשֵּׁדִים וְהָרוּחוֹת, חֲצִי יֵשׁ בָּהֶם מִבְּנֵי אָדָם שֶׁלְּמַטָּה, וַחֲצִי מִמַּלְאָכִים עֶלְיוֹנִים שֶׁלְּמַעְלָה. וְכֵן כְּשֶׁנּוֹלְדוּ מֵאָדָם אוֹתָם אֲחֵרִים, כֻּלָּם נִמְצְאוּ כְּגוֹן זֶה - חֲצִי מֵהַתַּחְתּוֹנִים, וַחֲצִי מֵהָעֶלְיוֹנִים."],[6,"","אַחַר שֶׁנּוֹלְדוּ מֵאָדָם, (חזרו לו קצת מאותן רוחות שיצאו מתשוקתו בחלום) הוֹלִיד מֵאוֹתָן רוּחוֹת בָּנוֹת שֶׁדּוֹמוֹת לִיפִי הָעֶלְיוֹנִים וְלִיפִי הַתַּחְתּוֹנִים, וְעַל זֶה כָּתוּב, (בראשית ו) וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה וְגוֹ', וְטָעוּ כֻלָּם אַחֲרֵיהֶן. וְזָכָר אֶחָד נִמְצָא שֶׁבָּא לָעוֹלָם מֵרוּחוֹ שֶׁל צַד קַיִן, וְקָרְאוּ לוֹ תּוּבַל קַיִן, וּנְקֵבָה אַחַת יָצְאָה עִמּוֹ, וְהָיוּ הַבְּרִיּוֹת טוֹעִים אַחֲרֶיהָ, וְנִקְרֵאת נַעֲמָ\"ה. מִמֶּנָּה יָצְאוּ רוּחוֹת וְשֵׁדִים אֲחֵרִים, וְהֵם תְּלוּיִים בָּאֲוִיר וּמוֹדִיעִים דְּבָרִים לְאוֹתָם אֲחֵרִים שֶׁמְּצוּיִים לְמַטָּה."],[7,"","וְתוּבַל קַיִן הַזֶּה הוֹצִיא כְּלֵי זַיִן לַהֲרֹג לָעוֹלָם, וְנַעֲמָה הַזּוֹ הִתְרַעֲשָׁה בְּרִגְשָׁהּ, וְנִדְבְּקָה בְצִדָּהּ. וְעַד עַכְשָׁו הִיא קַיֶּמֶת, וּמְדוֹרָהּ בֵּין שְׁאוֹן הַיָּם הַגָּדוֹל, וְיוֹצֵאת וְצוֹחֶקֶת עִם בְּנֵי אָדָם, וּמִתְחַמֶּמֶת מֵהֶם בַּחֲלוֹם בְּאוֹתָהּ הַתְּשׁוּקָה שֶׁל אָדָם, וְנִדְבֶּקֶת בּוֹ. תְּשׁוּקָה הִיא נוֹטֶלֶת, וְלֹא יוֹתֵר. וּמֵאוֹתָהּ תְּשׁוּקָה הִיא מִתְעַבֶּרֶת, וּמוֹצִיאָה מִינִים אֲחֵרִים לָעוֹלָם."],[8,"","וְהַבָּנִים הַלָּלוּ שֶׁמּוֹלִידָה מִבְּנֵי אָדָם נִמְצָאִים כְּנֶגֶד נְקֵבוֹת בְּנֵי הָאָדָם, וּמִתְעַבְּרוֹת מֵהֶם וּמוֹלִידוֹת רוּחוֹת, וְכֻלָּם הוֹלְכִים אֶל לִילִית הָרִאשׁוֹנָה, וְהִיא מְגַדֶּלֶת אוֹתָם. וְהִיא יוֹצֵאת לָעוֹלָם וְרוֹצָה תִינוֹקוֹתֶיהָ. וְרוֹאָה תִינוֹקוֹת שֶׁל בְּנֵי אָדָם וְנִדְבֶּקֶת לָהֶם לַהֲרֹג אוֹתָם, וּלְהִשָּׁאֵב לְרוּחוֹת תִּינוֹקוֹת בְּנֵי הָאָדָם, וְהוֹלֶכֶת עִם אוֹתָהּ הָרוּחַ (תינוק), וּמִזְדַּמְּנִים שָׁם שָׁלֹשׁ רוּחוֹת קְדוֹשׁוֹת, וְטָסִים לְפָנֶיהָ, וְנוֹטְלִים מִמֶּנָּה אוֹתָהּ הָרוּחַ (תינוק), וּמַנִּיחִים אוֹתָהּ לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְשָׁם נֶחְקָקִים (לומדים) לְפָנָיו."]]],[["בְּגִינֵי כַּךְ אוֹרַיְיתָא אַזְהֲרַת לְהוּ לִבְנֵי נָשָׁא, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים וַדַּאי. אִי אִשְׁתְּכַח בַּר נָשׁ קַדִּישָׁא, לָא מִסְתָּפֵי מִינָּהּ, דִּכְדֵין זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִלֵּין ג' מַלְאֲכִין קַדִּישִׁין דְּאַמָרָן, וְנַטְרִין לֵיהּ לְהַהוּא רַבְיָיא, וְהִיא לָא יַכְלָא לְאַבְאָשָׁא לֵיהּ, הֲדָא הוּא דִכְתִיב, (תהילים צ״א:י׳) לֹא תְאוּנֶּה אֵלֶיךָ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךָ. מַאי טַעֲמָא לֹא תְאוּנֶּה אֵלֶיךָ רָעָה. בְּגִין כִּי מַלְאָכָיו יְצַוְּה לָּךְ, וּכְתִיב (תהלים צ) כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ.","דְּאִי בַּר נָשׁ לָא אִשְׁתְּכַח קַדִּישָׁא, וְאַשְׁלִיף רוּחָא מִסִּטְרָא דִּמְסָאֲבָא, כְּדֵין הִיא אַתְיָא וְחַיְּיכַת בֵּיהּ בְּהַהוּא רַבְיָא. וְאִי קַטִּילַת לֵיהּ, אִשְׁתְּאֲבַת בְּהַהוּא רוּחָא, וְלָא תַּעְדֵי מִנֵיהּ לְעָלְמִין. וְאִי תֵּימָא אִינּוּן אָחֳרָנִין, דְּקַטִּילַת לוֹן, וְאִזְדָּמְנוּ קַמָּהּ אִינּוּן תְּלָתָא קַדִּישִׁין, וְנַטְלִין מִנָּהּ הַהוּא רוּחָא, הָא לָא בְּסִטְרָא דִּמְסָאֲבָא אִשְׁתְּכָחוּ, אֲמַאי שַׁלְטָא לְקָטְלָא לְהוּ. אֶלָּא, הַאי כַּד בַּר נָשׁ לָא אִתְקַדָּשׁ, אֲבָל לָא אִתְכַּוָּון לְאִסְתַּאֲבָא וְלָא אִסְתְּאַב, בְּגִין כַּךְ יַכְלָא לְשַׁלְּטָאָה בְּגוּפָא, וְלָא בְּרוּחָא.","וְזִמְנִין אִשְׁתְּכַח דְּנָפְקָת נַעֲמָה לְעָלְמָא, לְאִתְחַמְמָא מִבְּנֵי נָשָׁא, ואִשְׁתְּכַח בַּר נָשׁ בְּקִשְׁרָא (נ\"א בקשויא) דְּתִיאוּבְתָא עִמָּהּ, וְאִתְּעַר מִשֵּׁנָתֵיהּ, וְאָחִיד בְּאִנְתְּתֵיהּ, וְשָׁכִיב עִמָה, וּרְעוּתָא דִילֵיה בְּהַהוּא תִיאוּבְתָא דְּהַוִה לְיֵהּ בְּחַלְמֵיה, כְּדֵין הַהוּא בַּר דְּאוֹלִיד, מִסִּטְרָא דְּנַעֲמָה קָא אַתְיָא, דְּהָא בְּתִיאוּבְתָּא דִּילָהּ אִשְׁתְּכַח הַאי, כַּד נַפְקָא לִילִי\"ת וְחָמָאת לֵיהּ, יַדְעַת מִלָּה, וְהִיא אִתְקְטָרַת בֵּיהּ, וּמַגְדְּלַת לֵיהּ כְּאִינּוּן אָחֳרָנִין בְּנוֹי דְּנַעֲמָ\"ה, וְאִשְׁתְּכָחַת עִמֵּיהּ זִמְנִין סַגִּיאִין, וְלָא קַטָלָא לֵיהּ.","הַאי הוּא בַּר נָשׁ, דִּבְכָל סִיהֲרָא וְסִיהֲרָא אִתְפְּגִים, וְלָא אִתְיָאֲשָׁא מִנֵּיהּ לְעָלְמִין, דְּהָא בְּכָל סִיהֲרָא וְסִיהֲרָא כַּד אִתְחַדְּשָׁא בְּעָלְמָא, לִילִי\"ת נָפְקָא, וּפַקְדָּא עַל כֻּלְּהוּ דְּהִיא מַגְדְּלַת, וְחַיְּיכָא בְּהוּ, וּכְדֵין הַהוּא בַּר נָשׁ פָּגִים בְּהַהוּא זִמְנָא, זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּמִתְקַדְּשֵׁי בִּקְדוּשָּׁה דְּמַלְכָּא, עָלַיְיהוּ כְּתִיב (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ וְגוֹ'.","מִלִּין אִלֵּין גַּלֵּי שְׁלֹמֹה מַלְכָּא, בְּסִפְרָא דְּאַשְׁמְדָאי מַלְכָּא, וְאַשְׁכַּחְנָא בֵּיהּ (ע\"ט ע\"א) אֶלַף וְאַרְבַּע מְאָה וַחֲמֵשׁ זִינֵי מְסַאֲבוּתָא, דְּמִסְתַּאֲבֵי בְּהוּ בְּנֵי נָשָׁא. דְּגַלֵּי דָּא אַשְׁמְדָאי לִשְׁלֹמֹה מַלְכָּא.","וַוי לְהוּ לִבְנֵי נָשָׁא, דְּכֻלְּהוּ אֲטִימִין וּסְתִימִין עַיְינִין, וְלָא יַדְעִין, וְלָא שַׁמְעִין, וְלָא מַשְׁגִּיחִין, הֵיךְ קַיְימִין בְּעָלְמָא. וְהָא עֵיטָא וְאַסְווּתָא קָמַיְיהוּ, וְלָא מִסְתַּכְּלִין. דְּהָא לָא יַכְלִין בְּנֵי נָשָׁא לְאִשְׁתְּזָבָא, אֶלָּא בְּעֵיטָא דְּאוֹרַיְיתָא. דִּכְתִּיב, (דברים כ״ג:י״א) כִּי יִהְיֶה בְךָ אִישׁ אֲשֶׁר לֹא יִהְיֶה טָהוֹר מִקְּרֵה לָיְלָה. אֲשֶׁר לֹא יִהְיֶה טָהוֹר דַּיְיקָא, מִקְּרֵה לָיְלָה דַּיְיקָא, וְהָא אוֹקִימְנָא מִלֵּי, בְּעֵיטָא דְּאוֹרַיְיתָא קַדִּישָׁא. דְּהָכִי כְּתִיב בְּאוֹרַיְיתָא קַדִּישָׁא, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים כִּי אֲנִי יְיָ' אֱלֹהֵיכֶם.","תָּאנָא, בָּתַר דְּאִסְתָּלָקוּ קַיִן וְהֶבֶל, אִתְהַדָּר אָדָם לְאִנְתְּתֵיהּ, וְאִתְלָבָּשׁ בְּרוּחָא אָחֳרָא, וְאוֹלִיד לְשֵׁת. מִכָּאן אִתְיַיחֲסוּ דָּרֵי דְּצַדִּיקַיָּיא בְּעָלְמָא. וְאַסְגֵּי קוּדְשָׁא בְּרִיךְ הוּא חֶסֶד בְּעָלְמָא, וּבְכָל חַד אִתְיְילִידַת נוּקְבָּא עִמֵּיהּ, לְאִתְיַישְּׁבָא עָלְמָא כְּגַוְונָא דִּלְעֵילָּא. וְהָא אוּקְמוּהָ חַבְרַיָּיא בִּסְתִּימָאָה דְּמַתְנִיתִין, דִּכְתִּיב, (ויקרא כ׳:י״ז) וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחוֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְגוֹ', חֶסֶד הוּא. חֶסֶד הוּא ודַּאי, וּבָתַר דְּשָׁארִי חֶסֶד, גִּזְעִין וְשָׁרָשִׁין נָפְקִין מִתְּחוֹת לְעֵילָּא, וְאִתְפָּרְשָׁן עַנְפִּין, וְקָרִיב אִתְרְחַק. כְּדֵין עַנְפָּא אַסְגֵּי, וְאָתֵי לְאִתְחַבְּרָא בְּזִוּוּגָא חַד בְּאִילָנָא. הַאי בְּקַדְמִיתָא, הַאי בִּסְתִּימָא דְּעָלְמָא. בְּגִין דִּכְתִּיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִכָּאן וּלְהָלְאָה בְּנֵי נָשָׁא דְּיִשְׁתַּכְחוּן בֵּיהּ, וְנִכְרְתוּ לְעֵינֵי בְּנֵי עַמָּם."],[[0,"בגיני כך אורייתא וכו׳:","משום זה, התורה מזהירה לבני אדם, והתקדשתם והייתם קדושים. ודאי. אם האדם הוא קדוש אינו מפחד ממנה, מלילית, כי אז מזמין הקב״ה אלו ג׳ מלאכים הקדושים שאמרנו, ושומרים אותו הילד, והיא אינה יכולה להזיק אותו. ז״ש, לא תאונה אליך רעה ונגע לא יקרב באהלך. מהו הטעם, אשר, לא תאונה אליך רעה, משום כי מלאכיו יצוה לך לשמרך. וכתוב, כי בי חשק ואפלטהו."],[1,"דאי בר נש וכו׳:","כי אם בן אדם אינו נמצא קדוש, ומושך רוח מצד הטומאה, אז היא הלילית, באה ומצחקת עם אותו הילד. ואם הורגת אותו, היא מתדבקת ברוח ההוא של הילד, ואינה סרה ממנו לעולם. ואם תאמר אלו האחרים, שלא נמשך להם רוח מצד הטומאה, שהורגת אותם ומזדמנים לפניה אלו שלשה הרוחות הקדושים, ולוקחים ממנו אותו הרוח (כנ״ל אות שס\"ב) הרי לא נמצאו בצד הטומאה, ולמה שולטת להרוג אותם. ומשיב, אלא זה הוא כשאדם לא נתקדש, וע״כ הורגת אותם, אבל לא נתכוון להטמא ולא נטמא, משום זה יכלה לשלוט בגוף, להורגו, אבל לא ברוח. כי הרוח מובא לפני הקב״ה. (כנ״ל אות שס״ב)."],[2,"וזמנין אשתכח דנפקת וכו׳:","ולפעמים נמצא, שנעמה יוצאת לעולם להתחמם מבני אדם, ואדם נמצא בקשר התשוקה עמה, ומקיץ משנתו ומתאחד באשתו ושוכב עמה, והרצון שלו עודנו בתשוקה ההיא שהיתה לו בחלומו, אז אותו בן שמוליד בא מצד נעמה, כי זה נמצא בתשוקה שלה. וכשלילית יוצאת ורואה אותו, היא יודעת הדבר, שבא מצד נעמה, והיא נקשרת בו ומגדלת אותו כשאר האחרים בניה של נעמה (כנ״ל אות שס״ב) ונמצאת עמו ימים רבים ואינה הורגת אותו. להיותו מן הצד שלה."],[3,"האי הוא ב״נ וכו׳:","זה הוא אדם, שבכל חידוש לבנה ולבנה, נפגם, ואינה מתיאשת ממנו לעולם. כי כשמתחדשת כל לבנה ולבנה בעולם, דהיינו בראש חדש, יוצאת לילית ופוקדת כל הילדים שהיא מגדלת, ומצחקת בהם. ואז האיש ההוא פגום בעת ההיא. אשרי הם הצדיקים שמתקדשים בקדושת המלך. עליהם כתוב, והיה מדי חדש בחדשו ומדי שבת בשבתו וגו׳."],[4,"מלין אלין גלי וכו׳:","דברים אלו גילה שלמה המלך, בספרו של אשמדאי מלך השדים. ומצאתי בו אלף וארבע מאות וחמש מיני טומאה, שבני אדם נטמאים בהם. וזה גילה אשמדאי לשלמה המלך."],[5,"ווי להו לבני נשא וכו׳:","אוי להם לבני אדם שכולם אטומים וסתומי עינים ואינם יודעים ואינם שומעים ואינם משגיחים, איך נמצאים בעולם. והרי עצה ורפואה לפניהם ואינם מסתכלים. כי בני אדם אינם יכולים להנצל רק בעצה של התורה. שכתוב, כי יהיה בך איש אשר לא יהיה טהור מקרה לילה. \u0003אשר לא יהיה טהור\u0004 הוא בדיוק, דהיינו שנמשך לידתו ברוח הטומאה כנ״ל. \u0003מקרה לילה,\u0004 הוא בדיוק, דהיינו בעת שינה בחלומו. וכבר העמדנו הדברים בעצת התורה הקדושה, כי כך כתוב בתורה, והתקדשתם והייתם קדושים כי אני ה׳ אלקיכם. שאז לא יאונה לו כל רע. (כנ״ל אות שס״ג)."],[6,"תאנא כתר דאסתלקו וכו׳:","למדנו, אחר שנסתלקו קין והבל חזר אדם לאשתו ונתלבש ברוח אחר, והוליד את שת. מכאן נתיחסו דורות הצדיקים בעולם. והרבה הקב״ה חסד בעולם, ובכל אחד נולדה נקבה עמו לישוב העולם, כעין של מעלה. שז״א ומלכות היו אח ואחות, והרי העמידו החברים בסתם משנה, שעליהם כתוב, ואיש אשר יקח את אחותו בת אביו או בת אמו וגו׳ חסד הוא. חסד הוא ודאי, כי אחר ששורה החסד, יצאו גזעים ושרשים מתחת, דהיינו מאחורים, שלמעלה, ונפרשו הענפים, שהם ז״א ומלכות, ומה שהיה קרוב נתרחק, דהיינו מה שז״א ומלכות היו מקודם לכן דבוקים אחורים באחורים נתרחקו עתה ע״י החסד. כמו שנתבאר כל זה באורך לעיל (ויקרא אות ק׳ בהסולם ע״ש) אז נתגדלו הענפים, ז״א ומלכות, ובאו להתחבר בזווג אחד באילן (כמ״ש שם). זה היה בתחילה במצב הא׳ של המלכות, וזה היה בסתום של העולם, דהיינו רק במצב האחוריים הסתומים, שאז בלבד היו ז״א ומלכות אח ואחות, ששניהם בני הבינה אז, (כמ״ש שם) ומשום שכתוב אמרתי עולם חסד יבנה, שהחסד מפרידם זה מזה, והמלכות יורדת מתחת ז״א, ואינה עוד אחותו אלא מדרגה נמוכה ממנו. וע״כ, אבל מכאן ולהלאה, בני אדם שימצאו בו, שיקחו אחותם, ונכרתו לעיני בני עמם."]],[[0,"","מִשּׁוּם כָּךְ הַתּוֹרָה מַזְהִירָה אֶת בְּנֵי הָאָדָם, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדֹשִׁים, וַדַּאי. אִם נִמְצָא אָדָם קָדוֹשׁ, לֹא פוֹחֵד מִמֶּנָּה, שֶׁאָז מַזְמִין הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת אוֹתָם שְׁלֹשֶׁת הַמַּלְאָכִים הַקְּדוֹשִׁים שֶׁאָמַרְנוּ, וְשׁוֹמְרִים אֶת אוֹתוֹ הַתִּינוֹק, וְהִיא לֹא יְכוֹלָה לְהָרַע לוֹ. זֶהוּ שֶׁכָּתוּב לֹא תְאֻנֶּה אֵלֶיךְ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךְ. מָה הַטַּעַם לֹא תְאֻנֶּה אֵלֶיךְ רָעָה? מִשּׁוּם שֶׁכִּי מַלְאָכָיו יְצַוֶּה לָּךְ. וְכָתוּב כִּי בִי חָשַׁק וַאֲפַלְּטֵהוּ."],[1,"","שֶׁאִם אָדָם לֹא נִמְצָא קָדוֹשׁ, וְשׁוֹלֵף רוּחַ מִצַּד הַטֻּמְאָה, אֲזַי הִיא בָּאָה וְצוֹחֶקֶת עִם אוֹתוֹ תִינוֹק. וְאִם הִיא הוֹרֶגֶת אוֹתוֹ, הִיא נִשְׁאֶבֶת לְאוֹתָהּ הָרוּחַ וְלֹא זָזָה מִמֶּנָּה לְעוֹלָמִים. וְאִם תֹּאמַר, אוֹתָם הָאֲחֵרִים שֶׁהָרְגָה אוֹתָם וְהִזְדַּמְּנוּ לְפָנֶיהָ הֵם אוֹתָם שְׁלֹשָׁה קְדוֹשִׁים, וְנוֹטְלִים מִמֶּנָּה אוֹתָהּ הָרוּחַ, הֲרֵי לֹא נִמְצְאוּ בְּצַד הַטֻּמְאָה, לָמָּה הִיא שׁוֹלֶטֶת לַהֲרֹג אוֹתָם? אֶלָּא זֶה כְּשֶׁהָאִישׁ הַזֶּה אֵינוֹ מִתְקַדֵּשׁ, אֲבָל לֹא מִתְכַּוֵּן לְהִטָּמֵא וְלֹא נִטְמָא, כִּי כָּךְ הִיא יְכוֹלָה לִשְׁלֹט בַּגּוּף וְלֹא בָרוּחַ."],[2,"","וְלִפְעָמִים נִמְצָא שֶׁיּוֹצֵאת נַעֲמָה לָעוֹלָם לְהִתְחַמֵּם עִם בְּנֵי אָדָם, וְנִמְצָא אָדָם בְּקֶשֶׁר (בקשוי) שֶׁל תְּשׁוּקָה עִמָּהּ, וּמִתְעוֹרֵר מִשְּׁנָתוֹ, וְאוֹחֵז בְּאִשְׁתּוֹ וְשׁוֹכֵב עִמָּהּ, וְהָרָצוֹן שֶׁלּוֹ בְּאוֹתָהּ תְּשׁוּקָה שֶׁהָיְתָה לוֹ בַּחֲלוֹמוֹ, אָז אוֹתוֹ הַבֵּן שֶׁמּוֹלִיד בָּא מִצִּדָּהּ שֶׁל נַעֲמָה, שֶׁהֲרֵי בַּתְּשׁוּקָה שֶׁלָּהּ זֶה נִמְצָא. כְּשֶׁיּוֹצֵאת לִילִי\"ת וְרוֹאָה אוֹתוֹ, הִיא יוֹדַעַת הַדָּבָר וְנִקְשֶׁרֶת בּוֹ, וּמְגַדֶּלֶת אוֹתוֹ כְּמוֹ הָאֲחֵרִים בְּנֵי נַעֲמָה, וְנִמְצֵאת עִמּוֹ זְמַנִּים רַבִּים וְלֹא הוֹרֶגֶת אוֹתוֹ."],[3,"","זֶהוּ אִישׁ, שֶׁבְּכָל לְבָנָה וּלְבָנָה נֶחְסָר, וְלֹא מִתְיָאֶשֶׁת מִמֶּנּוּ לְעוֹלָמִים, שֶׁהֲרֵי בְּכָל לְבָנָה וּלְבָנָה כְּשֶׁהִיא מִתְחַדֶּשֶׁת בָּעוֹלָם, לִילִי\"ת יוֹצֵאת, וּפוֹקֶדֶת עַל כָּל אֵלֶּה שֶׁהִיא מְגַדֶּלֶת וְצוֹחֶקֶת בָּהֶם, וְאָז אוֹתוֹ הָאִישׁ פָּגוּם בְּאוֹתוֹ זְמַן. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁמִּתְקַדְּשִׁים בִּקְדֻשַּׁת הַמֶּלֶךְ, עֲלֵיהֶם כָּתוּב, (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ וְגוֹ'."],[4,"","אֶת הַדְּבָרִים הַלָּלוּ גִּלָּה שְׁלֹמֹה הַמֶּלֶךְ בְּסִפְרוֹ שֶׁל אַשְׁמְדַאי הַמֶּלֶךְ, וּמָצָאנוּ בוֹ אֶלֶף וְאַרְבַּע מֵאוֹת וַחֲמִשָּׁה מִינֵי טֻמְאָה שֶׁנִּטְמָאִים בָּהֶם בְּנֵי אָדָם. אֶת זֶה גִּלָּה אַשְׁמְדַאי לַמֶּלֶךְ שְׁלֹמֹה."],[5,"","אוֹי לָהֶם לִבְנֵי אָדָם, שֶׁכֻּלָּם אֲטוּמִים וּסְתוּמֵי עֵינַיִם, וְלֹא יוֹדְעִים וְלֹא שׁוֹמְעִים וְלֹא מַשְׁגִּיחִים אֵיךְ הֵם עוֹמְדִים בָּעוֹלָם. וְהִנֵּה עֵצָה וּרְפוּאָה לִפְנֵיהֶם, וְאֵינָם מִסְתַּכְּלִים. שֶׁהֲרֵי אֵין אֲנָשִׁים יְכוֹלִים לְהִנָּצֵל אֶלָּא בָּעֵצָה שֶׁל הַתּוֹרָה, שֶׁכָּתוּב (דברים כג) כִּי יִהְיֶה בְךְ אִישׁ אֲשֶׁר לֹא טָהוֹר מִקְּרֵה לָיְלָה. אֲשֶׁר לֹא יִהְיֶה טָהוֹר דַּוְקָא, מִקְּרֵה לָיְלָה דַּוְקָא, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים בַּעֲצַת הַתּוֹרָה הַקְּדוֹשָׁה. שֶׁכָּךְ כָּתוּב בַּתּוֹרָה הַקְּדוֹשָׁה, וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדשִׁים כִּי אֲנִי ה' אֱלֹהֵיכֶם."],[6,"","לָמַדְנוּ, אַחַר שֶׁהִסְתַּלְּקוּ קַיִן וְהֶבֶל, חָזַר אָדָם לְאִשְׁתּוֹ, וְהִתְלַבֵּשׁ בְּרוּחַ אַחֶרֶת, וְהוֹלִיד אֶת שֵׁת. מִכָּאן הִתְיַחֲסוּ דוֹרוֹת הַצַּדִּיקִים בָּעוֹלָם, וְהִגְדִּיל הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הַחֶסֶד בָּעוֹלָם, וּלְכָל אֶחָד נוֹלְדָה עִמּוֹ נְקֵבָה, שֶׁיִּתְיַשֵּׁב הָעוֹלָם כְּמוֹ שֶׁלְּמַעְלָה. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים בִּסְתַם מִשְׁנָה, שֶׁכָּתוּב וְאִישׁ אֲשֶׁר יִקַּח אֶת אֲחֹתוֹ בַּת אָבִיו אוֹ בַת אִמּוֹ וְגוֹ', חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. וְאַחַר שֶׁשָּׁרָה הַחֶסֶד, יָצְאוּ גְזָעִים וְשָׁרָשִׁים מִתַּחַת לְמַעְלָה, וְנִפְרְדוּ הָעֲנָפִים, וְהַקָּרוֹב הִתְרַחֵק. אָז גָּדֵל הֶעָנָף וּבָא לְהִתְחַבֵּר בְּזִוּוּג אֶחָד עִם הָאִילָן. זֶה בָּרִאשׁוֹנָה, וְזֶה בְּסֵתֶר הָעוֹלָם, מִשּׁוּם שֶׁכָּתוּב (תהלים פב) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה. אֲבָל מִכָּאן וָהָלְאָה, אֲנָשִׁים שֶׁיִּמָּצְאוּ בוֹ - וְנִכְרְתוּ לְעֵינֵי בְּנֵי עַמָּם."]]],[["תָּאנָא עֶרְוַת אֲחוֹת אָבִיךָ, כְּמָה דְּאִתְגַּלְיָיא בִּסְתִּימָא. כְּתִיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ' וְצַדִּיקִים יֵלְכוּ בָם וְגוֹ', זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְּיַדְעֵי אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאַזְלִין בְּהוּ, וְאִשְׁתְּמוֹדְעָן גַּבַּיְיהוּ. זַכָּאָה חוּלָקֵיהוֹן.","תָּאנָא, אִתְעַבְּרַת הֵ\"א עִלָּאָה בִּרְחִימוּתָא וַחֲבִיבוּתָא דְּלָא מִתְפְּרַשׁ מִנָּהּ יוֹ\"ד לְעָלְמִין. אִתְעַבְּרַת וְאַפִּיקַת וָא\"ו, לְבָתַר קָאִים קַמָּהּ, וְיַנְקָא לֵיהּ. וְדָא (נ\"א ודאין בעלמא) וָא\"ו כַּד נָפְקָא, בַּת זוּגוֹ נַפְקָא עִמֵּיהּ. אַתְיָא חֶסֶד אִתְּעַר גַּבֵּיהּ, וּפָרִישׁ לוֹן, וְנַפְקוּ גִּזְעִין מִתְּחוֹת לְעֵילָּא, וְאִתְפָּשָּׁטוּ עַנְפִין, וְאַסְגִּיאוּ, וְאִתְעָבִידַת הֵ\"א תַּתָּאָה. וְאִתְרַבִּיאַת בְּעַנְפָּהָא לְעֵילָּא לְעֵילָּא, עַד דְּאִזְדַּוְּוגַת בְּאִילָנָא עִלָּאָה, וְאִתְחַבָּרוּ וָא\"ו עִם הֵ\"א, מַאן גָּרִים לוֹן. חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. דְּחִבֵּר לוֹן כַּחֲדָא.","יוֹ\"ד עִם הֵ\"א עִלָּאָה. לָא תַּלְיָא חִבּוּרָא דִּלְהוֹן בְּחֶסֶד, אֶלָּא בְּמַזָּלָא תַּלְיָיא חִבּוּרָא דִּלְהוֹן, וַחֲבִיבוּתָא דִּלְהוֹן, דְּלָא (ס\"א ע\"ב) מִתְפָּרְשָׁן לְעָלְמִין. יוֹ\"ד אִתְקָשַׁר בְּהֵ\"א, וְהֵ\"א אִתְקָשַׁר בְּוָא\"ו, וָא\"ו אִתְקָשַׁר בְּהֵ\"א, וְהֵ\"א אִתְקָשַׁר בְּכֹלָּא. וְכֹלָּא חַד קִשּׁוּרָא הוּא, וְחַד מִלָּה. לָא אִתְפְּרָשׁוּ דָּא מִן דָּא לְעָלְמִין. כִּבְיָכוֹל, מַאן דְּגָרִים פִּרוּדָא, כְּאִלּוּ חָרִיב עָלְמָא, וְאִקְרֵי עֶרְיָיתָא דְּכֹלָּא.","וּלְזִמְנָא דְּאָתֵי, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאָתָבָא שְׁכִינְתָּא לְאַתְרָהָא, וּלְאִשְׁתַּכְּחָא כֹּלָּא בְּזִוּוּגָא חַד דִּכְתִּיב (זכריה י״ד:כ׳) בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וְגוֹ'. וְאִי תֵּימָא הַשְׁתָּא לָאו הוּא אֶחָד. לָא, דְּהָא הַשְׁתָּא חַיָּיבֵי עָלְמָא גָּרְמוּ, דְּלָא אִשְׁתְּכַח חַד. דְּהָא מַטְרוֹנִיתָא אִתְרָחֲקַת מִן מַלְכָּא, וְלָא מִשְׁתַּכְּחֵי בְּזִוּוּגָא. אִמָּא עִלָּאָה אִתְרָחֲקַת מִן מַלְכָּא וְלָא יַנְקָא לֵיהּ.","בְּגִין דְּמַלְכָּא בְּלָא מַטְרוֹנִיתָא, לָא מִתְעַטֵּר בְּעִטְרוֹי עִמָּהּ (ס\"א דאמא), כְּמָה בְּקַדְמִיתָא כַּד אִתְחַבָּר בְּמַטְרוֹנִיתָא, דְּעַטְּרָא לֵיהּ, בְּכַמָּה עִטְרִין, בְּכַמָּה זְהִירִין בְּעִטְרִין קַדִּישִׁין עִלָּאִין. דִּכְתִּיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן (ס\"א ע\"ב, שמות פ\"ד ע\"א) בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ', דְּאִזְדְּוַּוג בְּמַטְרוֹנִיתָא, כְּדֵין עַטְּרָא לֵיהּ אִימָּא עִלָּאָה כְּדְקָא יֵאוֹת. וְהַשְׁתָּא דְּלָא אִשְׁתְּכַח מַלְכָּא בְּמַטְרוֹנִיתָא, כְּדֵין אִימָּא עִלָּאָה נַטְלַת כִּתְרָאָה (נ\"א עטראה) וּמָנָעַת מִנֵּיהּ מַבּוּעֵי דְּנַחֲלִין, וְלָא אִשְׁתְּכַח בְּקִשּׁוּרָא חַד. כִּבְיָכוֹל לָא אִשְׁתְּכַח חַד.","וּבְזִמְנָא דְּתֵיתוּב מַטְרוֹנִיתָא לַאֲתַר הֵיכָלָא, וּמַלְכָּא יִזְדַּוִּוג עִמָּהּ בְּזִוּוּגָא חַד. כְּדֵין, יִתְחַבָּר כֹּלָּא כַּחֲדָא, בְּלָא פִּרוּדָא, וְעַל דָּא כְּתִיב, בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד. בַּיוֹם הַהוּא: בְּזִמְנָא (קע\"א) דִּיְתוּב מַטְרוֹנִיתָא לְהֵיכָלָא, כְּדֵין כֹּלָּא אִשְׁתְּכַח חַד בְּלָא פִּרוּדָא. וּכְדֵין (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפּוֹט וְגוֹ'.","דְּתַנְיָא, אָמַר רִבִּי שִׁמְעוֹן, לָא תֵּיעוּל מַטְרוֹנִיתָא בְּחֶדְוָותָא בְּהֵיכָלֵיהּ עַד דְּיִתְדָּן מַלְכוּתָא דְּעֵשָׂו, וְתִיסַב מִנֵּיהּ נוּקְמִין דְּגַרְמָא כָּל הַאי. לְבָתַר תִּזְדַּוִּוג בְּמַלְכָּא, וִיהֵא חֵדוּ שְׁלִים, הֲדָא הוּא דִכְתִיב, וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפּוֹט אֶת הַר עֵשָׂו בְּקַדְמִיתָא, וּלְבָתַר וְהָיְתָה לַיְיָ' הַמְּלוּכָה. מַאן מְלוּכָה, דָּא מַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב, וְהָיְתָה לַיְיָ' הַמְּלוּכָה. וּלְבָתַר דְּיִזְדַּוְּוגֻן כַּחֲדָא, מַה כְּתִיב. וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד.","(ויקרא ח\"י) עֶרְוַת אֲחִי אָבִיךָ לֹא תְגַלֵּה. תָּאנֵי רִבִּי יְהוּדָה, דָּא יִשְׂרָאֵל לְתַתָּא. וַאֲחוֹת אִמְּךָ: דָּא יְרוּשָׁלַם דִּלְתַתָּא. דִּבְחוֹבִין אִלֵּין, יִגְלוּן יִשְׂרָאֵל בֵּינֵי עֲמְמַיָיא, וְיִתְחֲרִיב יְרוּשָׁלַ ם לְתַתָּא. וְעַל דָּא תָּנֵינָן, רְחִימוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּקָרָא לְיִשְׂרָאֵל אַחִים, שֶׁנֶּאֱמַר (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא וְגוֹ'. (ואוקימנא מילין ותמן (ס\"א מילי תמן) בת בנה ובת בתה וכו' ואף על גב דאינון באתגלייא ובאתכסיא וכן בתריה. דהא עלמא איצטריך לון, ואינון ישובא דעלמא כמה דכתיב (משלי כ\"ז) רעך ורע אביך) וְהַאי רָזָא דְמִלָה. דְּאָמַר רַבִּי שִׁמְעוֹן","אָמַר רִבִּי יְהוּדָה, אִי אַחַי לָמָּה רֵעַי, וְאִי רֵעַי לָמָּה אַחַי. אֶלָּא תָּאנָא, הַהוּא מִלָּה דְּלָא אִתְעָדֵי לְעָלְמִין, אִקְרֵי רֵעַ, כְּמָה דְאַתְּ אָמֵר רֵעֲךָ וְרֵעַ אָבִיךָ אַל תַּעֲזוֹב. וְהַאי רָזָא דְּמִלָּה דְּאָמַר רַבִּי שִׁמְעוֹן, אִימָא עִלָּאָה, רַעְיָא אִקְרֵי, בְּגִין דְּלָא אִתְעָדֵי (ס\"א ע\"ב) רְחִימוּתָא דְּאַבָּא מִנָּהּ לְעָלְמִין. וְאִימָא תַּתָּאָה כַּלָה אִקְרֵי, וְאִקְרֵי אֲחוֹת, כְּמָה דְּאוֹקִימְנָא (שיר השירים ח׳:ח׳) אֲחוֹת לָנוּ קְטַנָּה."],[[0,"תאנא ערות אחות וגו׳:","למדנו, ערות אחות אביך, פירושו כמו שנתגלה בסתום, דהיינו כמו שנתגלה במצב האחורים, שהמלכות היתה אז אחות ז״א, שהוא אביך. ושיעור הכתוב היא שלא יגלה ערות המלכות, ממצב האחורים, שהיתה אז אחות אביך, שהוא ז״א. כתוב, כי ישרים דרכי ה׳ וצדיקים ילכו בם וגו'. אשרי חלקם של צדיקים, שיודעים דרכי הקב״ה והולכים בהם, ונודעים אליהם, אשרי חלקם."],[1,"תאנא אתעברת ה״א וכו׳:","למדנו, נתעברה \u0003ה'\u0004 העליונה שהיא בינה, באהבה ובחביבות, שה \u0003י׳,\u0004 שהיא חכמה אינה נפרדת ממנה לעולם. היא נתעברה והוציאה \u0003ו׳,\u0004 שהיא ז״א, שה״ס ה \u0003ו׳\u0004 שבתוך ה \u0003ה׳,\u0004 ואחר כך, עמד לפניה, דהיינו, ה \u0003ו׳\u0004 שלאחר י״ה בשם הויה, וינקה אותו. ו \u0003ו׳\u0004 זו כשיצאה מן הבינה, בת זוגו, שהיא המלכות. היתה יוצאת עמו, ונמצא ששניהם הם אח ואחות בני הבינה, והם אז דבוקים אחורים באחורים, בא החסד ונתעורר אליו אל ז״א, והפריד אותם זה מזה, ויצאו הגזעים ממטה למעלה, ונתפשטו הענפים, שהם ז״א ומלכות, ונתגדלו ונעשית \u0003ה׳\u0004 תחתונה. ונתרבו בענפיה למעלה למעלה, עד, שהמלכות, נזדווגת באילן העליון, שהוא ז״א, ונתחברה ה \u0003ו׳\u0004 שהיא ז״א עם ה \u0003ה׳\u0004 שהיא המלכות. כמ״ש כל זה לעיל (ויקרא אות ק') והם אותם הדברים שאמר לעיל (באות שס״ט) אלא שם אמר בקיצור, וכאן מרחיב הדברים. מי גרם לכל זה, \u0003חסד הוא.\u0004 חסד, הוא ודאי שחבר אותם יחד. (כמ״ש שם)."],[2,"יו״ד עם ה״א וכו׳: י׳","עם \u0003ה׳\u0004 עליונה, שהם חכמה ובינה, החיבור שלהם אינו תלוי בחסד, כמו בז״א ומלכות, אלא החיבור שלהם והחביבות שלהם תלויים במזלא, שהוא דיקנא דא״א המיחד חו״ב (כמ״ש בתלמוד ע״ס שיעור י״ג דף א׳ קט״ו אות ה׳ ע״ש) שאינם נפרדים לעולם. ה \u0003י׳\u0004 נקשרת ב \u0003ה׳,\u0004 ו \u0003ה׳\u0004 נקשרת ב \u0003ו׳,\u0004 וה \u0003ו׳\u0004 נקשרת ב \u0003ה׳\u0004 אחרונה, וה \u0003ה׳\u0004 נקשרת בכל, \u0003יה״ו.\u0004 והכל קשר אחד הוא, ודבר אחד, אינם נפרדים זה מזה לעולם. כביכול, מי שגורם פירוד, הוא כאלו מחריב העולם. וזה נקרא ערות הכל."],[3,"ולזמנא דאתי זמין וכו׳:","ולעתיד לבא, עתיד הקב״ה להחזיר השכינה למקומה שימצא הכל בזווג אחד. שכתוב, ביום ההוא יהיה ה׳ אחד ושמו אחד וגו'. ואם תאמר, עתה אין הוא אחד. לא, כי עתה רשעי העולם גורמים, שז״א ומלכות, לא נמצאו אחד, כי המלכה מתרחקת מן המלך, ואינם נמצאים בזווג. ואמא עלאה, שהיא בינה, מתרחקת מן המלך ואינה מניקה אותו."],[4,"בגין דמלכא בלא וכו׳:","וע״כ הבינה אינה יונקת לז״א, משום שהמלך בלי המטרוניתא אינו מתעטר בעטרות של אמא, כמו בתחילה כשנתחבר במטרוניתא, שאמא היתה מעטרת אותו בכמה עטרות, בכמה אורות, בעטרות הקדושות העליונות, שכתוב, צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו וגו'. כשנזדווג במטרוניתא העטירה אותו אמא עלאה כראוי, ועתה שהמלך אינו נמצא עם המטרוניתא, אז אמא עלאה לוקחת עטרותיה, ומונעת ממנו מבועי הנחלים, ואינו נמצא בקשר אחד. וע״כ כביכול לא נמצא אחד."],[5,"ובזמנא דתיתוב וכו׳:","ובזמן שהמטרוניתא תשוב למקום ההיכל, והמלך יזדווג עמה בזווג אחד, אז יתחבר הכל כאחד בלי פירוד. וע״כ כתוב, ביום ההוא יהיה ה׳ אחד ושמו אחד. \u0003ביום ההוא,\u0004 היינו בזמן שתשוב המטרוניתא להיכל, אז ימצא הכל אחד בלא פירוד. ואז, ועלו מושיעים בהר ציון לשפוט את הר עשו."],[6,"דתניא אר״ש וכו׳:","שלמדנו, אמר ר׳ שמעון, המטרוניתא לא תכנוס בשמחה בהיכלו עד שתהיה נשפטת מלכותו של עשו, ותקח ממנה נקמות, על שגרמה לכל זה. ואח״כ תזדווג עם המלך ותהיה השמחה בשלמות. ז״ש ועלו מושיעים בהר ציון לשפוט את הר עשו בתחילה, ואח״כ והיתה לה׳ המלוכה, מה היא מלוכה, זו היא המלכה, ז״ש והיתה לה׳ המלוכה. ואחר שיזדווגו יחד מה כתוב, והיה ה׳ למלך על כל הארץ ביום ההוא יהיה ה׳ אחד ושמו אחד."],[7,"ערות אחי אביך לא תגלה:","תאני רבי יהודה, זהו ישראל למטה, שישראל הם אחי ז״א, שהוא אביך. ואחות אמך, זו היא ירושלים של מטה, שהיא אחות המלכות שלמעלה, שהיא אמך, כי בעונות אלו יגלה ערות ישראל, דהיינו שיגלו ישראל בין העמים. ויגלה ערות ירושלים, דהיינו שתחרב ירושלים שלמטה. ועל זה למדנו אהבת הקב״ה, שקרא את ישראל אחים, שנאמר למען אחי ורעי אדברה נא וגו'. וע״כ אומר הכתוב עליהם ערות אחי אביך כנ״ל."],[8,"א״ר יהודה אי וכו׳:","א״ר יהודה, אם אחי, למה כתוב רעי, ואם רעי, למה כתוב אחי. ומשיב. אלא למדנו, הדבר ההוא שלא נפסק לעולם נקרא \u0003רעי.\u0004 כש״א רעך ורע אביך אל תעזוב. וזהו סוד הדבר שאמר ר׳ שמעון, אמא עלאה שהיא בינה. נקראת \u0003רעיה,\u0004 משום שאהבת אבא אינה נפסקת ממנה לעולם. ואמא תחתונה, דהיינו מלכות, נקראת כלה, ונקראת אחות. כמו שהעמדנו הכתוב, אחות לנו קטנה. שהיא מלכות."]],[[0,"","לָמַדְנוּ, עֶרְוַת אֲחוֹת אָבִיךְ, כְּמוֹ שֶׁנִּתְגַּלָּה בְנִסְתָּר. כָּתוּב (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים יֵלְכוּ בָם וְגוֹ'. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁיּוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְהוֹלְכִים בָּהֶם וְנוֹדָעִים אֲלֵיהֶם. אַשְׁרֵי חֶלְקָם."],[1,"","לָמַדְנוּ, הִתְעַבְּרָה ה' עֶלְיוֹנָה בְּאַהֲבָה וַחֲבִיבוּת שֶׁאֵין נִפְרָד מִמֶּנָּה יוֹ\"ד לְעוֹלָמִים. הִתְעַבְּרָה וְהוֹצִיאָה וָא\"ו, אַחַר כָּךְ עָמַד לְפָנֶיהָ וְהֵינִיקָה אוֹתוֹ, וְזוֹ (ודן בעולם) הַוָּא\"ו כְּשֶׁיָּצְאָה, בַּת זוּגוֹ יָצְאָה עִמּוֹ. בָּא הַחֶסֶד וְהִתְעוֹרֵר אֵלָיו, וְהִפְרִיד אוֹתָם, וְיָצְאוּ גְזָעִים מִתַּחַת לְמַעְלָה, וְהִתְפַּשְּׁטוּ עֲנָפִים וְהִתְרַבּוּ, וְנֶעֶשְׂתָה הֵ\"א תַּחְתּוֹנָה. וְהִתְרַבְּתָה בַּעֲנָפֶיהָ לְמַעְלָה לְמַעְלָה, עַד שֶׁהִזְדַּוְּגָה בָּאִילָן הָעֶלְיוֹן, וְהִתְחַבְּרוּ וָא\"ו עִם הֵ\"א. מִי גָרַם לָהֶם? חֶסֶד הוּא. חֶסֶד הוּא וַדַּאי. שֶׁחִבְּרָם כְּאֶחָד."],[2,"","יוֹ\"ד עִם הֵ\"א עֶלְיוֹנָה, אֵין תָּלוּי חִבּוּרָן בְּחֶסֶד, אֶלָּא חִבּוּרָן תָּלוּי בְּמַזָּל, וַחֲבִיבוּתָן, שֶׁלֹּא נִפְרָדוֹת לְעוֹלָמִים. יוֹ\"ד נִקְשֶׁרֶת לְהֵ\"א, וְהֵ\"א נִקְשֶׁרֶת לְוָא\"ו, וָא\"ו נִקְשֶׁרֶת בְּהֵ\"א, וְהֵ\"א נִקְשֶׁרֶת בַּכֹּל. וְהַכֹּל הוּא קֶשֶׁר אֶחָד וְדָבָר אֶחָד. לֹא נִפְרָדוֹת זוֹ מִזּוֹ לְעוֹלָמִים. כִּבְיָכוֹל מִי שֶׁגּוֹרֵם אֶת הַפֵּרוּד כְּאִלּוּ הֶחֱרִיב עוֹלָם, וְנִקְרָא עֶרְוַת הַכֹּל."],[3,"","וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהָשִׁיב שְׁכִינָה לִמְקוֹמָהּ, וְשֶׁיִּמָּצֵא הַכֹּל בְּזִוּוּג אֶחָד, שֶׁכָּתוּב (זכריה יד) בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד וְגוֹ'. וְאִם תֹּאמַר, עַכְשָׁו אֵינוֹ אֶחָד?! לֹא, שֶׁהֲרֵי עַכְשָׁו הָרְשָׁעִים שֶׁל הָעוֹלָם גָּרְמוּ שֶׁלֹּא יִמָּצֵא אֶחָד, שֶׁהֲרֵי הַגְּבִירָה הִתְרַחֲקָה מִן הַמֶּלֶךְ, וְלֹא נִמְצָאִים בְּזִוּוּג. הָאֵם הָעֶלְיוֹנָה הִתְרַחֲקָה מֵהַמֶּלֶךְ וְלֹא מֵינִיקָה אוֹתוֹ."],[4,"","כִּי מֶלֶךְ בְּלִי גְבִירָה לֹא מִתְעַטֵּר בְּעַטְרוֹתָיו עִמָּהּ (של האם) כְּמוֹ בָּרִאשׁוֹנָה כְּשֶׁהִתְחַבֵּר עִם הַגְּבִירָה, שֶׁעִטְּרָה אוֹתוֹ בְּכַמָּה עֲטָרוֹת, בְּכַמָּה זְהָרִים בַּעֲטָרוֹת קְדוֹשׁוֹת עֶלְיוֹנוֹת, שֶׁכָּתוּב (שיר ג) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלֹמֹה וְגוֹ', שֶׁהִזְדַּוֵּג עִם הַגְּבִירָה, אָז עִטְּרָה אוֹתוֹ הָאֵם הָעֶלְיוֹנָה כָּרָאוּי. וְכָעֵת שֶׁאֵין נִמְצָא הַמֶּלֶךְ עִם הַגְּבִירָה, אֲזַי הָאֵם הָעֶלְיוֹנָה נוֹטֶלֶת אֶת כִּתְרָהּ (עטרתה) וּמוֹנַעַת מִמֶּנּוּ אֶת מַעַיְנוֹת הַנְּחָלִים, וְלֹא נִמְצָא בְקֶשֶׁר אֶחָד. כִּבְיָכוֹל אֵינוֹ בַּנִּמְצָא אֶחָד."],[5,"","וּבִזְמַן שֶׁתָּשׁוּב הַגְּבִירָה לִמְקוֹם הֵיכָלָהּ וְהַמֶּלֶךְ יִזְדַּוֵּג עִמָּהּ בְּזִוּוּג אֶחָד, אָז יִתְחַבֵּר הַכֹּל כְּאֶחָד בְּלִי פֵרוּד. וְעַל זֶה כָּתוּב, בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד. בַּיּוֹם הַהוּא, בִּזְמַן שֶׁתָּשׁוּב הַגְּבִירָה לַהֵיכָל, אָז הַכֹּל יִמָּצֵא אֶחָד בְּלִי פֵרוּד. וְאָז - (עובדיה א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט וְגוֹ'."],[6,"","שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, לֹא תִכָּנֵס הַגְּבִירָה בְּשִׂמְחָה לְהֵיכָלוֹ עַד שֶׁתִּדּוֹן מַלְכוּת עֵשָׂו וְתִקַּח מִמֶּנּוּ נְקָמוֹת שֶׁגָּרְמָה כָּל זֶה. אַחַר כָּךְ תִּזְדַּוֵּג עִם הַמֶּלֶךְ וְתִהְיֶה שִׂמְחָה שְׁלֵמָה. זֶהוּ שֶׁכָּתוּב וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו - בָּרִאשׁוֹנָה, וְאַחַר כָּךְ - וְהָיְתָה לַה' הַמְּלוּכָה. מִי הַמְּלוּכָה? זוֹ הַגְּבִירָה. זֶהוּ שֶׁכָּתוּב וְהָיְתָה לַה' הַמְּלוּכָה. וְאַחַר שֶׁיִּזְדַּוְּגוּ כְאֶחָד מַה כָּתוּב? וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמוֹ אֶחָד."],[7,"","עָרְוַת אֲחִי אָבִיךְ לֹא תְגַלֵּה, שָׁנָה רַבִּי יְהוּדָה - זֶהוּ יִשְׂרָאֵל לְמַטָּה. וַאֲחוֹת אִמְּךְ - זוֹ יְרוּשָׁלַיִם שֶׁלְּמַטָּה. בַּחֲטָאִים הַלָּלוּ יִגְלוּ יִשְׂרָאֵל לְבֵין הָעַמִּים וְתֶחֱרַב יְרוּשָׁלַיִם לְמַטָּה. וְעַל זֶה שָׁנִינוּ, אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁקָּרָא לְיִשְׂרָאֵל אַחִים, שֶׁנֶּאֱמַר (תהלים קכב) לְמַעַן אַחַי וְרֵעָי אֲדַבְּרָה נָא וְגוֹ'. (ובארנו הדברים, ושם (דּבָרים שָם) בת בנה ובת בתה. ואף על גב שהם בנגלה ובנסתר וכן אחריו. שהרי העולם צריך להם, והם ישוב העולם, כמו שכתוב (משלי כז) רעך ורע אביך) וְזֶה סוֹד הַדָּבָר. שֶׁאָמַר רַבִּי שִׁמְעוֹן."],[8,"","אָמַר רַבִּי יְהוּדָה, אִם אַחַי, לָמָּה רֵעָי? וְאִם רֵעָי, לָמָּה אַחַי? אֶלָּא לָמַדְנוּ, אוֹתוֹ דָבָר שֶׁלֹּא סָר לְעוֹלָמִים נִקְרָא רֵעַ, כְּמוֹ שֶׁנֶּאֱמַר רֵעֲךְ וְרֵעַ אָבִיךְ אַל תַּעֲזֹּב. וְזֶהוּ סוֹד הַדָּבָר שֶׁאָמַר רַבִּי שִׁמְעוֹן, הָאֵם הָעֶלְיוֹנָה נִקְרֵאת רַעְיָה, כִּי לֹא זָזָה אַהֲבַת הָאָב מִמֶּנָּה לְעוֹלָמִים. וְהָאֵם הַתַּחְתּוֹנָה נִקְרֵאת כַּלָּה, וְנִקְרֵאת אָחוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ (שיר ח) אָחוֹת לָנוּ קְטַנָּה."]]],[["וְהַיְינוּ סְתָם מַתְנִיתָא דִּילָן, דִּכְתִּיב הָכָא, עֶרְוַת אֲחוֹתְךָ בַת אָבִיךָ אוֹ בַת אִמֶּךָ, כֵּיוָן דְּאָמַר בַת אָבִיךָ, מַאי אוֹ בַת אִמֶּךָ. אֶלָּא, אִי מִסִּטְרָא דְּאַבָּא אִשְׁתְּכַחַת, חָכְמָה אִתְקְרֵי. וְאִי מִסִּטְרָא דְּאִימָא, בִּינָה אִתְקְרֵי. וְעַל כָּל פָּנִים בֵּין הַאי וּבֵין הַאי, מֵאִימָא וְאַבָּא אִשְׁתְּכַחַת. דְּהָא יוֹ\"ד לָא אִתְעָדֵי מִן ה' לְעָלְמִין. וְדָא הוּא רָזָא דְּמִלָּה, מוֹלֶדֶת בַּיִת: מִסִּטְרָא דְּאַבָּא. אוֹ מוֹלֶדֶת חוּץ: מִסִּטְרָא דְּאִימָא.","רִבִּי אַבָּא אָמַר, (משלי כ״ד:ג׳) בְּחָכְמָה יִבָּנֶה בָּיִת, מַאן הוּא בַּיִת דְּאִתְבְּנֵי בְּחָכְמָה. הֲוִי אֵימָא דָּא נָהָר דְּנָפִיק מְעֵדֶן, בְּגִינֵי כַּךְ מוֹלֶדֶת בַּיִת. אוֹ מוֹלֶדֶת חוּץ. כַּד נַפְקַת מִן ו', כְּמָה דִּכְתִּיב, (בראשית ב׳:כ״ג) עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. וּכְתִיב (בראשית ב׳:כ״א) וַיִקַּח אַחַת מִצַּלְעוֹתָיו, וְדָא הוּא מוֹלֶדֶת חוּץ, מֵאֲתַר דִּזְעֵיר אַנְפִּין אִשְׁתְּכַח, כְּמָה דְּאִתְּמַר.","וְעַל דָּא אָמַר רִבִּי יְהוּדָה, יִשְׂרָאֵל אָחִין אִקְרוּן לְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא אַעְדֵּי רְחִימוּתָא דִּלְהוֹן לְעָלְמִין. יְרוּשָׁלַם דִּלְתַתָּא אָחוֹת אִמְּךָ אִתְקְרֵי, כְּמָה דִּכְתִּיב, (תהילים קכ״ב:ג׳) יְרוּשָׁלַ ם הַבְּנוּיָה כְּעִיר שֶׁחוּבְּרָה לָהּ יַחְדָּיו וְגוֹ'. מַאי שֶׁחוּבְּרָה לָהּ יַחְדָּיו. בְּגִין דְּאִזְדְּוַּוג בָּהּ מַלְכָּא מִשִּׁית סִטְרִין, בְּכָל סִטְרֵי מַלְכָּא, בְּדַרְגָּא דְּצַדִּיק, וְכָל כִּתְרֵי מַלְכָּא כְּלִילָן בֵּיהּ. וְהַיְינוּ שֶׁחוּבְּרָה לָהּ יַחְדָּיו.","רִבִּי יִצְחָק אָמַר, (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ. מַאן שְׁבָטִים. אִלֵּין תְּרֵיסָר תְּחוּמִין, דְּמִתְפָּרְשָׁן מֵהַהוּא אִילָנָא רַבָּא וְתַקִּיף, דְּאַחֲסִין לוֹן מִסִּטְרָא דְּאַבָּא וְאִימָּא. הֲדָא הוּא דִכְתִיב שִׁבְטֵי יָהּ, מִשְׁפַר סַהֲדוּתָא, דְּאַסְהִיד בְּרָא קַדִּישָׁא (רצ\"ה) (נ\"א דאסהיד אבא ואימא בברא קדישא) דִּכְתִּיב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, וְאִינּוּן נַהֲרִין עֲמִיקִין, דְּנַגְדִּין וְאִתְמַשְּׁכָן מִן יָהּ. וְכֹלָּא (ס\"א וכל כך למה). לְהוֹדוֹת לְשֵׁם יְיָ'. (ס\"א ובגין כך) כִּי שָׁמָּה יָשְׁבוּ כִסְאוֹת לְמִשְׁפָּט כִּסְאוֹת לְבֵית דָּוִד, לְאַחְסְנָא מַלְכוּתָא קַדִּישָׁא הוּא וּבְנוֹי לְדָרֵי דָּרִין, וְדָא הִיא שִׁירָתָא דְּאָמַר דָּוִד עַל מָלְכוּ עִלָּאָה קַדִּישָׁא.","רִבִּי חִזְקִיָּה אָמַר, כֹּלָּא בְּרָזָא עִלָּאָה הוּא, לְאַחֲזָאָה דְּמַאן דְּפָגִים לְתַתָּא, פָּגִים לְעֵילָּא. עֶרְוַת כַּלָּתְךָ לֹא תְגַלֵּה, דְּתָנֵינָן עוֹנָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת. בְּגִין דְּיַדְעִין רָזָא דְּמִלָּה, וִיכַוְּונוּן לִבָּא, וְיִשְׁתְּכַּח רְעוּתְהוֹן שְׁלִים. וּבְנִין דְּאוֹלִידוּ אִקְרוּן בְּנִין דְּמַלְכָּא. וְאִי אִלֵּין פְּגִימוּ מִלָּה לְתַתָּא, כִּבְיָכוֹל פַּגְמִין אִינּוּן בְּכַלָּה דִּלְעֵילָּא, כְּדֵין כְּתִיב עֶרְוַת כַּלָּתְךָ לֹא תְגַלֵּה. דָּא בְּגִין אִינּוּן דְּיַדְעִין אוֹרְחִין דְּאוֹרַיְיתָא. שְׁאָר עַמָּא הַהוּא דְּאִתְגַּלְיָא, כַּלָּתְךָ מַמָּשׁ, וּבְחוֹבָא דָּא שְׁכִינְתָּא אִסְתְּלָקַת מִבֵּינַיְיהוּ.","תָּאנָא, אִתְגַלִיף שְׁמָא קַדִּישָׁא בְּסִטְרִין יְדִיעָן, בְּאַתְוָון רְשִׁימִין דְּעֶשְׂרִין וּתְרֵין (ס\"א י' בא', א' בי', י' בב', ב' בי', י' בא', ב' בה', ו' בג', י' בה', י' בג', ה' בי', ג' בה', ה' בד' אלו השני נוסחאות מצאנו בהעתקות אשר לפנינו) י' בְּא', א' בְּי'. י' בְּב', ב' בְּי'. ו' בְּא' ה' בְּג', יו\"ד בְּה\"א, יו\"ד בְּגימ\"ל, ה\"א בְּיו\"ד גימ\"ל בְּה\"א, ה\"א בְּדל\"ת (י' בד', ד' בי'. י' בה'. י' בג'. ה' בי'. ג' בי'. ו' בי'). כֻּלְּהוּ מִתְגַּלְּפֵי בְּיוֹ\"ד, יוֹ\"ד סָלִיק לוֹן.","הֵ\"א כָּלִיל בְּיוֹ\"ד, מִנֵּיהּ נָפְקַת, כְּדֵין מְעַטְּרִין לַאֲבָהָן. אִתְפַּתְּחַת הֵ\"א בְּנַחְלוֹי, וְאַעְטַּר לְרֵישָׁא דְּו', דְּתַמָּן שַׁרְיָין אֲבָהָן.","ו' כָּלִיל שִׁית אַתְוָון, וְכֻלְּהוּ כָּלִיל יוֹ\"ד. י' (יו\"ד) אִתְגְּלִיף בְּגִלוּפוֹי, וְסָלִיק לְאִתְעַטְּרָא בִּתְרֵיסַר אַתְוָון אָחֳרָנִין, מִנֵּיהּ נַפְקוּ עֶשֶׂר אֲמִירָן בְּגִלוּפוֹי, וְכֻלְּהוּ שְׁבִילִין דְּאוֹרְחָא עִלָּאָה, (ס\"א דאורחן דאורייתא) יַקִּירָא דְּכֹלָּא. כְּדֵין הֵ\"א אָחֳרָא אִתְכְּלִילַת מִן כֻּלְּהוּ, גְּלִיפָא מִסִּטְרָא מְתִיחָא (ס\"א מתייחדא) טְמִירָא, לְאוֹלָדָא לְתַתָּא.","אִתְגְּלִיפוּ (ס\"א אתפליגו) כֻּלְּהוּ בְּאַרְבְּעִין וּתְרֵין אַתְוָון, וְכֻלְּהוּ פָּרִישְׁנָא בְּמַתְנִיתָא דִּידָן, וְכֻלְּהוּ סַלְקָן בְּרֵישָׁא דְּמַלְכָּא.","שֶׁבַע שַׁבָתִּין שְׁלֵימִין, מִתְפָּרְשִׁין בְּשִׁבְעִין אַתְוָון. שִׁבְעִין וּתְרֵין אִסְתְּלָקוּ, וְאִסְתְּלָּקוּ בְּאוֹת ו' (ס\"א יו\"ד), רְשִׁימָן בפ' וַיְהִי בְּשַׁלַּח פַּרְעֹה בְּקְרָא וַיִּסַּע וַיָּבֹא וַיֵּט. כַּד נַטְלַת שְׁכִינְתָּא, וְז' רְשִׁימִין אִתְרְשִׁימוּ בֵּיהּ, שִׁבְעָה אִסְתְּלָקוּ מִנֵּיהּ, בְּאַתְוָון רְשִׁימִין. תָּאנָא, אִסְתְּלָקוּ אַתְוָון בִּרְשִׁימִין יְדִיעָן, וְאָרְחִין סְתִימִין, בַּר לְזַכָּאֵי קְשׁוֹט, סַמְכֵי עָלְמָא."],[[0,"והיינו סתם מתניתא וכו׳:","והיינו סתם משנה שלנו, כלומר עם הנזכר, שאו\"א אינם נפרדים לעולם, יובנו דברי המשנה הנאמרים סתם. שכתוב כאן, ערות אחותך בת אביך או בת אמך. כיון שאמר בת אביך, מהו, או בת אמך. פירוש, ששואל, כיון שאו״א אינם נפרדים לעולם, א״כ אם המלכות היא בת אביך, שהוא אבא עלאה, היא בהכרח גם בת אמך, שהיא אמא עלאה. כי זווגם אינו נפסק לעולם. ומשיב, אלא אם מצד אבא היא נמצאת, כלומר ששולט בה צד אבא, נקראת המלכות חכמה. ואם מצד אמא, דהיינו ששולט בה צד אמא, היא נקראת בינה. ועל כל פנים בין זה ובין זה, היא נמצאת מאבא ואמא ביחד. כי ה \u0003י׳,\u0004 שהיא אבא, אינה נפרדת מן \u0003ה׳,\u0004 שהיא אמא, לעולם. וזה הוא סוד הדבר, \u0003מולדת בית,\u0004 כשהיא מצד אבא, או מולדת חוץ, כשהיא מצד אמא. כי אמא נבחנת לחיצוניות אבא. וסוף הפסוק מפרש תחלתו."],[1,"ר׳ אבא אמר וכו׳:","רא״א, בחכמה יבנה בית. מי הוא בית שנבנה בחכמה. הוי אומר, שזהו נהר היוצא מעדן, שהוא בינה. משום זה כתוב, \u0003מולדת בית,\u0004 דהיינו המלכות שנולדה מן הבינה שהיא \u0003בית\u0004 לחכמה. \u0003או מולדת חוץ,\u0004 היינו כשהמלכות יוצאת מן ה \u0003ו׳\u0004 שהיא ז״א, כמו שכתוב, שאדם, שהוא ז״א, אמר על חוה, שהיא המלכות, עצם מעצמי ובשר מבשרי. וכתוב, ויקח אחת מצלעותיו, הרי שהמלכות יוצאת מז״א, וזה הוא \u0003מולדת חוץ,\u0004 ממקום שזעיר אנפין נמצא, שהוא נבחן לחיצון מאמא. כמו שלמדנו."],[2,"וע״ד אמר ר׳ יהודה וכו׳:","וע״כ אמר ר״י (לעיל אות שע״א) ישראל נקראים אחים להקב״ה, שלא נפסקה אהבתם לעולם. ירושלים שלמטה נקראת \u0003אחות אמך\u0004 (כנ״ל אות שע״ז) כמו שכתוב, ירושלים הבנויה כעיר שחוברה לה יחדיו. וגו'. דהיינו שירושלים שלמטה, היא כעיר שחוברה לה יחדיו, שהיא המלכות. מהו, שחוברה לה יחדיו. הוא משום שנזדווג המלך מששה קצוות, שהוא ז״א, בכל צדדי המלך, במדרגת צדיק, שהוא יסוד, שכל ספירות המלך כלולות בו. והיינו שחוברה לה יחדיו. דהיינו בכל הספירות דז״א."],[3,"ר׳ יצחק אמר וכו׳:","רי״א, ששם עלו שבטים שבטי יה. מי הם שבטים. ומשיב, אלו הם י״ב גבולים, המפורשים מאילן ההוא הגדול והחזק, שהוא ז״א, שה״ס ד׳ ספירות חו\"ג תו״מ, שבכל אחת ג׳ קוין, שהם י״ב גבולים. ומז״א הם נמשכים להמלכות, שנקראים בה בשם י״ב שבטים. שהוא ירש אותם מצד אבא ואמא. ז״ש, \u0003שבטי יה,\u0004 דהיינו מטוב העדות שמעיד בן הקדוש, שכתוב, \u0003שבטי יה עדות לישראל,\u0004 כי אלו י״ב גבולים ה״ס \u0003עדות,\u0004 דהיינו הארת העדן שהוא חכמה והם נהרות עמוקים הנוזלים ונמשכים מן י״ה. שהם אבא ואמא, והכל הוא להודות לשם ה'. ומשום זה, כי שמה ישבו כסאות למשפט כסאות לבית דוד. כדי להוריש המלכות הקדושה לו ולבניו לדורי דורות, וזו היא שירה שאמר דוד על המלכות הקדושה העליונה."],[4,"ר׳ חזקיה אמר וכו׳:","רח״א, הכל הוא בסוד העליון, להראות שמי שפוגם למטה פוגם למעלה. ערות כלתך לא תגלה. שלמדנו, עונתם של תלמידי חכמים משבת לשבת. משום שהם יודעים סוד הדבר, ויכוונו הלב ורצונם יהיה שלם. והבנים שמולידים נקראים בני המלך. ואם אלו פוגמים דבר למטה, כביכול הם פוגמים בכלה העליונה, שהיא המלכות. אז כתוב, ערות כלתך לא תגלה. הפירוש הזה הוא בשביל אלו היודעים דרכי התורה. לשאר העם, הפירוש הוא, אותו שבנגלה, דהיינו כלתך ממש, אשת בנו. ובעון הזה השכינה מסתלקת מביניהם. כלומר שרומז גם לכלה העליונה המסתלקת מפגם הזה שלמטה."],[5,"תאנא אתגליף שמא וכו׳:","למדנו, השם הקדוש נחקק בבחינות ידועות, באותיות רשומות של כ״ב אותיות. ה \u0003י׳\u0004 ב \u0003א׳, א׳\u0004 ב \u0003י. י׳\u0004 ב \u0003ב', ב׳\u0004 ב \u0003י'. י׳\u0004 ב \u0003ד׳, ד׳\u0004 ב \u0003י' י׳\u0004 ב \u0003ה'. י׳ בג'. ה׳\u0004 ב \u0003י'. ג׳\u0004 ב \u0003י'. ו׳\u0004 ב \u0003י'.\u0004 וכן כולם נחקקים ב \u0003י'.\u0004 ה \u0003י׳\u0004 מעלה אותם. שהיא מעלה כל כ״ב האותיות."],[5,"","פירוש. ה \u0003י׳\u0004 רומזת לחכמה, והיא שורש לכל כ\"ב אותיות. כי כשמתחילים לכתוב איזו אות, עושים בתחלתה נקודה, שהיא \u0003י׳,\u0004 ואח״כ ממשיכים כתיבת האות. שהסו״ה כולם בחכמה עשית. וגם השם הקדוש הוי״ה מתחיל ב \u0003י׳.\u0004 שהיא חכמה. ומפרש כאן, איך כ״ב אותיות נכללות בשם הקדוש הויה. וז״ש, \u0003אתגליף שמא קדישא\u0004 וכו׳ \u0003באתוון רשימין דכ״ב.\u0004 ואומר, שתחילה נכללת ה \u0003י׳\u0004 דשם הויה, בכל כ״ב האותיות, להיותה שורש להם כנ״ל, וז״ש, \u0003י׳\u0004 ב \u0003א׳,\u0004 שה \u0003י׳\u0004 מאירה לאות \u0003א'.\u0004 ו \u0003א׳\u0004 ב \u0003י'.\u0004 ואח״כ עולה ה \u0003א׳\u0004 ונכללת בי׳ וכן כל האותיות, \u0003י׳\u0004 ב \u0003ב׳\u0004 ו \u0003ב׳\u0004 ב \u0003י'. י׳\u0004 ב \u0003ג׳\u0004 ו \u0003ג׳\u0004 ב \u0003י'. י׳\u0004 ב \u0003ד׳\u0004 ו \u0003ד׳ בי'. י׳\u0004 ב \u0003ה׳\u0004 ו \u0003ה' בי'. י׳\u0004 ב \u0003ו'.\u0004 (כצ״ל ובדפו״י, מעורבים צירופים האחרונים) וכן, \u0003כלהו מתגלפי\u0004 ב \u0003י'.\u0004 שעד״ז נחקקים כל האותיות ב \u0003י׳\u0004 שה \u0003י׳\u0004 מאירה להם, ואח״כ \u0003יוד סליק לון,\u0004 שהם עולים לה \u0003י׳\u0004 ונכללים בה. ונמצאת ה \u0003י׳\u0004 של שם הויה כלולה מכל כ״ב אותיות."],[6,"ה״א כליל ביו״ד וכו׳:","ה \u0003ה׳\u0004 של שם הויה, שהיא בינה, היא כלולה ב \u0003י׳\u0004 דהויה, מבחינת התכללות כ״ב אותיות ב \u0003י׳\u0004 כנ״ל. וממנה היא יוצאת, כי הבינה נאצלת מן החכמה. אז החכמה והבינה שהם י״ה דהויה מעטרים את האבות, דהיינו חג״ת דז\"א הנקראים אברהם יצחק יעקב. ה \u0003ה׳\u0004 נפתחת בנחליה, דהיינו בחמשים שערי בינה שבה, והיא מעטרת את הראש של ה \u0003ו',\u0004 דהיינו שמשפעת ג״ר. לז״א שה״ס \u0003ו׳\u0004 דהוי״ה, ששם שורים האבות, כלומר, שהאבות שהם חג״ת, עולים ונעשים ראש, דהיינו חב״ד, ע״י הארת נ׳ שערי בינה."],[7,"ו׳ כליל שית אתוון וכו׳:","אחר שביאר איך ה \u0003י׳\u0004 דהויה, האצילה בכללות כ״ב אותיות שבה, את \u0003ה׳ ו׳\u0004 דהויה, מבאר עתה איך \u0003ה׳\u0004 האחרונה דהוי״ה, שהיא המלכות נמשכת מכללות כ״ב אותיות שב \u0003י׳\u0004 דהויה. ואומר, \u0003ו׳\u0004 כוללת שש אותיות, דהיינו שהיא כלולה משש אותיות, מן ה \u0003א׳\u0004 עד ה \u0003ו',\u0004 הקודמות לה. וכולן כוללת ה \u0003י׳,\u0004 כי ה \u0003י׳\u0004 כוללת כל ט׳ האותיות הקודמות לה, אשר ה \u0003ו׳\u0004 ושש אותיותיה נכללות בתוכם. והיינו ה \u0003י׳\u0004 שעל ה \u0003ו',\u0004 הנ״ל. ה \u0003י׳\u0004 הזו נחקקה בחקיקותיה, דהיינו עם התכללות מט' אותיות הקודמות לה, ועולה, אל ה \u0003י׳\u0004 דהויה הכוללת כל כ״ב האותיות, להתעטר בי״ב אותיות האחרות שמ \u0003י׳\u0004 עד \u0003ת׳.\u0004 ואז נכללת גם היא מכ״ב אותיות כמו ה \u0003י׳\u0004 דהויה. ואז יוצאים ממנה עשרה מאמרות, דהיינו עשר ספירות, בחקיקותיהם, וכל השבילים של אורח העליון היקר מכל. שהם ל״ב שבילי החכמה, המתגלים מיסוד דישסו״ת הנקרא \u0003ארח\u0004 (כנ״ל ב״א דף רנ״א ד״ה נחית) אז נכללת \u0003ה׳\u0004 האחרת דהויה, שהיא המלכות, מן כולם, דהיינו שמקבלת מכל האורות הנ״ל, ונחקקה מצד היתד הנעלם, שהוא יסוד דז״א, להוליד למטה. דהיינו שתהיה ראיה להולדת נשמות. \u0003מתיחא\u0004 פירושו יתד. כי על יתדות, מתרגם ירושלמי, מתחי (שמות כ״ז י״ט)."],[8,"אתגליפו כלהו בארבעין וכו׳:","נחקקו כל האורות, שב \u0003י׳\u0004 שעל ה \u0003ו׳,\u0004 שהיא ג״ר דז״א, בארבעים ושתים אותיות. כי הכתר דז״א, הוא ד׳ אותיות הויה. והחכמה דז״א היא עשר אותיות דהויה במילואה, דהיינו יוד הא ואו הא. והבינה דז״א, היא כ״ח אותיות דמילוי המילוי, דהיינו, יוד ואו דלת, הא אלף, ואו אלף ואו, הא אלף, שהם כ״ח אותיות. וביחד הם מ\"ב אותיות. וכלם בארנו במשנה שלנו. וכולם עולים. בראש המלך, דהיינו בג״ר דז״א כנ״ל."],[9,"שבע שבתין שלימין וכו׳:","שבע שבתות שלמות, דהיינו ז׳ ספירות המלכות הנקראת שבת, כשהן בשלמות, מפורשים בשבעים אותיות של השם ע״ב, שעיקרם הוא ע', וב' הנוספים ה״ס עדים או סופרים (כנ״ל בשלח אות קס״ג) ומפרש דבריו. ע״ב עלו, והם עלו באות \u0003ו',\u0004 שהוא ז״א, בחג״ת שלו, שהם רשומים בפרשת ויהי בשלח פרעה, בכתובים, ויסע, ויבא, ויט. (בשלח אות קע״ג) וכשהשכינה מקבלת מז\"א, ושבעה רשומות נרשמו בה ממנו, דהיינו שבע ספירות שלמות, כנ״ל, אז מתעלות ממנה שבעים באותיות רשומות, של השם ע״ב. למדנו, נתעלו האותיות של השם ע״ב, ברשימות ידועות ודרכים סתומים, ומגולים רק לצדיקי אמת, עמודי העולם."]],[[0,"","וְהַיְנוּ סְתַם מִשְׁנָה שֶׁלָּנוּ, שֶׁכָּתוּב כָּאן עֶרְוַת אֲחוֹתְךְ בַת אָבִיךְ אוֹ בַת אִמֶּךְ. כֵּיוָן שֶׁאָמַר בַת אָבִיךְ, מַה זֶּה אוֹ בַת אִמֶּךְ? אֶלָּא, אִם הִיא נִמְצֵאת מִצַּד הָאָב, נִקְרֵאת חָכְמָה. וְאִם מִצַּד הָאֵם, נִקְרֵאת בִּינָה. וְעַל כָּל פָּנִים, בֵּין כָּךְ וּבֵין כָּךְ, הִיא נִמְצֵאת מֵהָאָב וְהָאֵם. שֶׁהֲרֵי יוֹ\"ד אֵינָהּ זָזָה מֵה' לְעוֹלָמִים. וְזֶהוּ סוֹד הַדָּבָר, מוֹלֶדֶת בַּיִת - מִצַּד הָאָב. אוֹ מוֹלֶדֶת חוּץ - מִצַּד הָאֵם."],[1,"","רַבִּי אַבָּא אָמַר, (משלי כד) בְּחָכְמָה יִבָּנֶה בָּיִת. מִי הַבַּיִת שֶׁנִּבְנֶה בְחָכְמָה? הֱוֵי אוֹמֵר זֶה הַנָּהָר שֶׁיּוֹצֵא מֵעֵדֶן. מִשּׁוּם כָּךְ מוֹלֶדֶת בַּיִת אוֹ מוֹלֶדֶת חוּץ, כְּשֶׁיָּצְאָה מִו', כְּמוֹ שֶׁכָּתוּב (בראשית ב) עֶצֶם מֵעֲצָמַי וּבָשָׂר מִבְּשָׂרִי. וְכָתוּב וַיִּקַּח אַחַת מִצַּלְעֹתָיו, וְזֶהוּ מוֹלֶדֶת חוּץ, מִמָּקוֹם שֶׁל זְעֵיר אַנְפִּין נִמְצָא, כְּמוֹ שֶׁנִּתְבָּאֵר."],[2,"","וְעַל זֶה אָמַר רַבִּי יְהוּדָה, יִשְׂרָאֵל נִקְרָאִים אַחִים לַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא סָרָה אַהֲבָתָם לְעוֹלָמִים. יְרוּשָׁלַיִם שֶׁלְּמַטָּה נִקְרֵאת אֲחוֹת אִמֶּךְ, כְּמוֹ שֶׁכָּתוּב (תהלים קכב) יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ יַחְדָּו וְגוֹ'. מַה זֶּה שֶׁחֻבְּרָה לָּהּ יַחְדָּו? כְּדֵי שֶׁיִּזְדַּוֵּג עִמָּהּ הַמֶּלֶךְ מִשִּׁשָּׁה צְדָדִים, בְּכָל צִדְדֵי הַמֶּלֶךְ, בְּדַרְגַּת הַצַּדִּיק, וְכָל כִּתְרֵי הַמֶּלֶךְ שֶׁכְּלוּלִים בּוֹ. וְהַיְנוּ שֶׁחֻבְּרָה לָּהּ יַחְדָּו."],[3,"","רַבִּי יִצְחָק אָמַר, שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ. מִי הַשְּׁבָטִים? אֵלּוּ שְׁנֵים עָשָׂר תְּחוּמִים שֶׁנִּפְרָדִים מֵאוֹתוֹ אִילָן גָּדוֹל וְחָזָק שֶׁיָּרַשׁ אוֹתָם מִצַּד הָאָב וְהָאֵם. זֶהוּ שֶׁכָּתוּב שִׁבְטֵי יָהּ, מִיפִי הָעֵדוּת שֶׁמֵּעִיד הַבֵּן הַקָּדוֹשׁ, (שמעיד אבא ואמא בבן הקדוש) שֶׁכָּתוּב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, וְהֵם נְהָרוֹת עֲמֻקִּים שֶׁשּׁוֹפְעִים וְנִמְשָׁכִים מִן יָ\"הּ. וְהַכֹּל (וכל כך למה,,) לְהוֹדוֹת לְשֵׁם ה'. כִּי שָׁמָּה יָשְׁבוּ כִסְאוֹת לְמִשְׁפָּט כִּסְאוֹת לְבֵית דָּוִד, לָרֶשֶׁת אֶת הַמַּלְכוּת הַקְּדוֹשָׁה הוּא וּבָנָיו לְדוֹרֵי דוֹרוֹת, וְזוֹהִי הַשִּׁירָה שֶׁאָמַר דָּוִד עַל הַמַּלְכוּת הָעֶלְיוֹנָה הַקְּדוֹשָׁה."],[4,"","רַבִּי חִזְקִיָּה אָמַר, הַכֹּל בְּסוֹד עֶלְיוֹן הוּא, לְהַרְאוֹת שֶׁמִּי שֶׁפּוֹגֵם לְמַטָּה - פּוֹגֵם לְמַעְלָה. עֶרְוַת כַּלָּתְךְ לֹא תְגַלֵּה, שֶׁשָּׁנִינוּ, עוֹנָתָן שֶׁל תַּלְמִידֵי חֲכָמִים מִשַּׁבָּת לְשַׁבָּת. מִכֵּיוָן שֶׁיּוֹדְעִים אֶת סוֹד הַדָּבָר וִיכַוְּנוּ אֶת הַלֵּב, וְיִמָּצֵא רְצוֹנָם שָׁלֵם, וְהַבָּנִים שֶׁמּוֹלִידִים נִקְרָאִים הַבָּנִים שֶׁל הַמֶּלֶךְ. וְאִם אֵלֶּה פּוֹגְמִים דָּבָר לְמַטָּה, כִּבְיָכוֹל הֵם פּוֹגְמִים בְּכַלָּה שֶׁלְּמַעְלָה, וְאָז כָּתוּב עֶרְוַת כַּלָּתְךְ לֹא תְגַלֵּה. זֶה בִּשְׁבִיל אֵלּוּ שֶׁיּוֹדְעִים אֶת דִּינֵי הַתּוֹרָה. שְׁאָר הָעָם אוֹתוֹ שֶׁבַּנִּגְלֶה, כַּלָּתְךְ מַמָּשׁ, וּבַחֵטְא הַזֶּה הַשְּׁכִינָה מִסְתַּלֶּקֶת מִבֵּינֵיהֶם."],[5,"","לָמַדְנוּ, נֶחְקָק הַשֵּׁם הַקָּדוֹשׁ בִּצְדָדִים יְדוּעִים, בְּאוֹתִיּוֹת רְשׁוּמוֹת שֶׁל עֶשְׂרִים וּשְׁתַּיִם (י' בא', א' בי', י' בב', ב' בי', י' בא', ב' בה', ו' בג', י' בה', י' בג', ה' בי', ג' בה', ה' בד') י' בְּא', א' בְּי'. י' בְּב', ב' בְּי'. י' בְּא' ה' בְּג', יו\"ד בְּה\"א, יו\"ד בְּגימ\"ל, ה\"א בְיו\"ד גימ\"ל בְּה\"א, ה\"א בְּדל\"ת. כֻּלָּן נֶחְקָקוֹת בְּיוֹ\"ד, יוֹ\"ד מַעֲלֶה אוֹתָן."],[6,"","הֵ\"א כְּלוּלָה בְּיוֹ\"ד, מִמֶּנּוּ יוֹצֵאת, אָז מְעַטְּרִים אֶת הָאָבוֹת. נִפְתַּחַת הֵ\"א בַּנְּחָלִים שֶׁלָּהּ, וּמְעַטֶּרֶת אֶת רֹאשׁ הַו', שֶׁשָּׁם שְׁרוּיִים הָאָבוֹת."],[7,"","ו' כּוֹלֶלֶת שֵׁשׁ אוֹתִיּוֹת, וְאֶת כֻּלָּם כּוֹלֶלֶת יוֹ\"ד. יוֹ\"ד נֶחְקֶקֶת בְּגִלּוּפֶיהָ, וְעוֹלֶה לְהִתְעַטֵּר בִּשְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת אֲחֵרוֹת, מִמֶּנּוּ יוֹצְאוֹת עֶשֶׂר אֲמִירוֹת בַּגִּלּוּפִים שֶׁלּוֹ, וְכֻלָּם שְׁבִילִים שֶׁל הַדֶּרֶךְ הָעֶלְיוֹנָה, (של דרכי התורה) הַנִּכְבָּדָה מֵהַכֹּל. אֲזַי הֵ\"א אַחֶרֶת נִכְלֶלֶת מִכֻּלָּם, חֲקוּקָה מִצַּד מָתוּחַ (מתיחדת) טָמִיר לְהוֹלִיד לְמַטָּה."],[8,"","נֶחְקְקוּ (נחלקו) כֻלָּם בְּאַרְבָּעִים וּשְׁתַּיִם אוֹתִיּוֹת, וְאֶת כֻּלָּם פֵּרַשְׁנוּ בְמִשְׁנָתֵנוּ, וְכֻלָּם עוֹלִים לְרֹאשׁ הַמֶּלֶךְ."],[9,"","שֶׁבַע שַׁבָּתוֹת שְׁלֵמוֹת מִתְפָּרְשׁוֹת בְּשִׁבְעִים אוֹתִיּוֹת. שִׁבְעִים וּשְׁתַּיִם עָלוּ, וְהֵן עָלוּ בָּאוֹת ו' (יו\"ד), רְשׁוּמוֹת בְּפָרָשַׁת וַיְהִי בְּשַׁלַּח פַּרְעֹה בְּפָסוּק וַיִּסַּע וַיָּבא וַיֵּט. כְּשֶׁהַשְּׁכִינָה נוֹטֶלֶת וְשִׁבְעָה רִשּׁוּמִים נִרְשְׁמוּ בָהּ, מִתְעַלּוֹת שֶׁבַע מִמֶּנָּה בְּמַעֲשִׂים רְשׁוּמִים. לָמַדְנוּ שֶׁהִתְעַלּוּ הָאוֹתִיּוֹת בִּרְשָׁמִים יְדוּעִים וּדְרָכִים סְתוּמוֹת, פְּרָט לְצַדִּיקֵי אֱמֶת, עַמּוּדֵי הָעוֹלָם."]]],[["אָמַר רִבִּי שִׁמְעוֹן לְרִבִּי אֶלְעָזָר, תָּא חֲזֵי, הָנֵי עֶשְׂרִין וּתְרֵין אַתְוָון דִּגְלִיפִין בְּאוֹרַיְיתָא, כֻּלְּהוּ מִתְפָּרְשָׁן בְּהָנֵי (נ\"א מאלין) עֶשֶׂר אֲמִירָן. כָּל אֲמִירָה וַאֲמִירָה מֵאִלֵּין עֶשֶׂר, דְּאִינּוּן כִּתְרֵי מַלְכָּא כֻּלְּהוּ גְּלִיפִין בְּאַתְוָון יְדִיעָן (ד\"א אחרנין), בְּגִינֵי כַּךְ שְׁמָא קַדִּישָׁא אִתְכַּסְּיָיא בְּאַתְוָון אָחֳרָנִין, וְכָל אֲמִירָה, אוֹזִיף לַאֲמִירָה עִלָּאָה מִנָּהּ אַתְווֹי, בְּגִין דְּאִתְכְּלִיל הַאי בְּהַאי. וְעַל דָּא שְׁמָא קַדִּישָׁא, גָּלִיפְנָא לֵיהּ בְּאַתְוָון אָחֳרָנִין, בְּגִין דְּאִתְכַּסְיָין דָּא בְּדָא, וְדָא בְּדָא, עַד דְּמִתְקַשְּׁרָן כֻּלְּהוּ כַּחֲדָא.","וּמַאן דְּבָעֵי לְמִנְדַּע צִרוּפֵי שְׁמָהָן קַדִּישִׁין, לִינְדַע אִינּוּן אַתְוָון דִּרְשִׁימִין בְּכָל כִּתְרָא וְכִתְרָא, וּכְדֵין לִינְדַע וְיִתְקְיָּים בְּכֹלָּא. וְהָא גָּלִיפְנָא לוֹן, בְּכָל אִינּוּן אַתְוָון דִּרְשִׁימָן וִידִיעָן בְּכָל כִּתְרָא וְכִתְרָא, מִסִּפְרָא עִלָאָה דִּשְׁלֹמֹה. וְהָכִי סָלִיק בִּידָן, וְחַבְרַיָּיא גְּלִיפִין לוֹן, (ס\"א ולחברייא גלינן לון) וְשַׁפִּיר הוּא, דְּהָא כָּל כִּתְרָא וְכִתְרָא אוֹזִיף לְחַבְרֵיהּ אַתְווֹי, כְּמָה דְּאוֹקִימְנָא, וּלְזִמְנִין דְּלָא אִצְטְרִיךְ אֶלָּא, בְּאַתְווֹי אִינּוּן דִּרְשִׁימִין בֵּיהּ. וְכֻלְּהוּ יְדִיעָן לְגַבֵּי חַבְרַיָּיא וְהָא אוֹקִימְנָא לוֹן.","זַכָּאִין אִינּוּן צַדִּיקַיָּיא בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי בִּיקָרֵיהוֹן, וּמְגַּלֵי לְהוֹן רָזִין עִלָּאִין דִּשְׁמֵיהּ קַדִּישָׁא, דְּלָא גַּלֵּי לְעִלָּאִין קַדִּישִׁין, וְעַל דָּא יָכִיל מֹשֶׁה, לְאִתְעַטְּרָא בֵּינֵי קַדִּישִׁין, וְכֻלְּהוּ לָא יַכְלֵי לְמִקְרַב בַּהֲדֵיהּ, כְּנוּרָא יָקִידְתָּא, וְגוּמְרֵי דְּאֶשָּׁא. דְּאִי לָאו הָכִי, מַאן הֲוָה לֵיהּ לְמֹשֶׁה, לְמֵיקָם בֵּינַיְיהוּ. אֶלָּא זַכָּאָה חוּלָקָא דְּמֹשֶׁה, דְּהָא כַּד שָׁארֵי לְמַלְּלָא עִמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, בָּעָא לְמִנְדַּע שְׁמֵיהּ קַדִּישָׁא (ס\"א שמוי קדישין), סָתִים וְגַלְיָא, בְּכָל חַד וְחַד כַּדְקָא חֲזֵי, וּכְדֵין אַדְבַּק וְיָדַע יַתִּיר מִכָּל בְּנֵי עָלְמָא.","תָּא חֲזֵי, בְּשַׁעֲתָא דְּסָלִיק מֹשֶׁה גּוֹ עֲנָנָא יַקִּירָא, עָאל בֵּינֵי קַדִּישִׁין. פָּגַע בֵּיהּ חַד מַלְאָכָא בְּשַׁלְהוֹבֵי נוּרָא, בְּעַיְינִין מְלַהֲטָן, וְגַדְפּוֹי מוֹקְדָן, בָּעָא לְשַׁאֲפָא לֵיהּ בְּגַוִּויהּ. וְהַהוּא מַלְאָכָא גַּבְרִיאֵל (ס\"א גזריא\"ל) (ס\"א גזרנא\"ל) (קמוא\"ל) שְׁמֵיהּ, כְּדֵין אַדְכַּר מֹשֶׁה חַד שְׁמָא קַדִּישָׁא. דְּהֲוָה גָּלִיף בִּתְרֵיסַר אַתְוָון, וְאִזְדַּעְזָע וְאִתְרְגַשׁ, עַד דְּסָלִיק מֹשֶׁה בֵּינַיְיהוּ. וְכֵן לְכָל חַד וְחַד, זַכָּאָה חוּלָקֵיהּ (שמות נח ע\"א) וְהָא אוֹקִימְנָא מִלֵי.","עֶרְוַת אִשָּׁה, וּבִתָּהּ לֹא תְגַלֵּה. תָּאנָא, בְּתִקּוּנֵי מַטְרוֹנִיתָא אוֹקִימְנָא אִלֵּין עֶרְיָין, אַף עַל גַּב דְּאִינּוּן (נ\"א עריין אינון) בְּאִתְגַּלְיָיא וּבִסְתִּימָא, וְתַמָּן בַּת בְּנָהּ וּבַת בִּתָּהּ. דְּהָא עָלְמָא אִצְטְרִיךְ לוֹן, וְאִינּוּן יִשּׁוּבָא דְּעָלְמָא, כְּמָה דְּאוֹקִימְנָא. וּמַאן דְּגַלֵּי חַד עֶרְיָיתָא מִנַּיְיהוּ, וַוי לֵיהּ, וַוי לְנַפְשֵׁיהּ, דְּהָא גַּלֵּי בְּגִין דָּא עֶרְיָין אָחֳרָנִין.","וְתַנְיָא מִלָּה בַּתְרָאָה דְּעֶשֶׂר אַמִירָן דְּאוֹרַיְיתָא, (שמות כ׳:י״ד) לֹא תַחְמוֹד אֵשֶׁת רֵעֶךָ, בְּגִין דְּהַאי כְּלָלָא דְּכֻלְּהוּ. וּמַאן דְּחָמִיד אִתְּתָא אָחֳרָא, כְּאִלּוּ אַעְבָּר עַל אוֹרַיְיתָא כֻּלָּא. בְּרַם לָא אִית מִלָּה דְּקַיְּימָא קָמֵי תְּשׁוּבָה. וְכָּל שֶׁכֵּן אִי קַבִּיל עוֹנְשֵׁיהּ כְּדָוִד מַלְכָּא. אָמַר רִבִּי יוֹסֵי, תָּנֵינָן, כָּל מַאן דְּחָב וְאִתְפְּרַשׁ מֵהַהוּא חוֹבָא, תְּשׁוּבָה קָא מְעַלְּיָיא לֵיהּ טְפֵי. וְאִי לָאו, לָא סָלִיק בִּידֵיהּ תְּשׁוּבָה, וְלָא מְעַלְּיָיא לֵיהּ. אִי הָכִי, דָּוִד הֵיךְ לָא אִתְפְּרַשׁ מִבַּת שֶׁבַע לְבָתַר. אָמַר לֵיהּ, בַּת שֶׁבַע דִּידֵיהּ הֲוַת, וְדִידֵיהּ נָטִיל, דְּהָא מִית בַּעְלָהּ.","דְּתַנְיָא, אִזְדַּמְּנַת הֲוַת בַּת שֶׁבַע לְדָוִד, מִיּוֹמָא דְּאִתְבְּרֵי עָלְמָא, וּמָה עַכְּבַא לֵיהּ. דְּנָטַל בְּרָתֵיהּ דְּשָׁאוּל מַלְכָּא, וְהַהוּא יוֹמָא נָטַל לָהּ אוּרִיָּה בְּרַחֲמֵי, אַף עַל גַּב דְּלָא הֲוַת דִּילֵיהּ. לְבָתַר אָתָא דָּוִד, וְנָטִיל דִּילֵיהּ, וְעַל דְּדָוִד דָּחִיק שַׁעֲתָא קָמֵי קוּדְשָׁא בְּרִיךְ הוּא לְקָטְלָא לְאוּרִיָּה וּלְמֶעְבַּד הָכִי. אַבְאִישׁ קָמֵיהּ, וְאַעְנָשׁ לֵיהּ לְדָוִד, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאָתָבָא לֵיהּ לְדָוִד, לְקַיְּימָא לֵיהּ מַלְכוּתָא קַדִּישָׁא עִלָּאָה. וְכַד תָּאַב, לְדִידֵיהּ תָּאַב.","תָּאנָא, אָמַר רִבִּי יוֹסֵי, מַאי דִּכְתִּיב אֲנִי יְיָ'. אֲנִי יְיָ': עָתִיד לִיתֵּן שָׂכָר טוֹב לַצַדִּיקִים לֶעָתִיד לָבֹא. אֲנִי יְיָ' עָתִיד לְהִפָּרַע מִן הָרְשָׁעִים לֶעָתִיד לָבֹא. אִינּוּן דִּכְתִּיב בְּהוּ (ישעיהו ס״ו:כ״ד) הַפּוֹשְׁעִים בִּי. כְּתִיב אֲנִי יְיָ', וּכְתִיב (דברים ל״ב:ל״ט) אֲנִי אָמִית וַאֲחַיֶּה. אַף עַל פִּי שֶׁאֲנִי בְּמִדַּת הָרַחֲמִים, הָרְשָׁעִים הוֹפְכִים אוֹתִי לְמִדַּת הַדִין. דְּתַנְיָא, שֵׁם מָלֵא: יְיָ' אֱלֹהִים. זָכוּ יְיָ', וְאִי לָאו אֱלֹהִים. אָמַר רִבִּי שִׁמְעוֹן, חַיָּיבִין עַבְדֵי פְּגִימוּתָא לְעֵילָּא. מַאי פְּגִימוּתָא. כְּמָה דְּאוֹקִימְנָא פְּגִימוּתָא מַמָּשׁ, וְהָא אִתְּמַר."],[[0,"אר\"ש לר״א וכו׳:","א״ר שמעון לר״א, בוא וראה, אלו כ״ב אותיות החקוקות בתורה, כולם מתבארים באלו עשרה מאמרות, שהם עשר ספירות, כח״ב חג״ת נהי״מ. כל אמירה ואמירה מאלו העשרה, שהם ספירות המלך, כולם חקוקות באותיות ידועות, כי האותיות, ה״ס הכלים של הספירות, וכל ספירה יש לה כלים מיוחדים לה. משום זה, השם הקדוש הויה, מתכסה באותיות אחרות, דהיינו באדנ״י. כי הכלים דז״א שה״ס הויה, מלובשים ומכוסים בכלים של המלכות שה״ס אדני. וכל אמירה משאלת אותיות לאמירה עליונה ממנה, משום שנכללות זו בזו. וע״כ אנו מבטאים השם הקדוש הויה, באותיות אחרות אדני, משום שמכוסים ומתלבשים זה בזה וזה בזה עד שמתקשרים כולם יחד. \u0003גליפנא\u0004 פירושו אנו מבטאים. כי הביטוי, הוא חיתוך אותיות כמו חקיקה."],[0,"","פירוש. נודע, שהקו האמצעי שבכל ספירה, הוא מעלית התחתונה לעליונה. כי כל ספירה כלולה מעשר ספירות, ובעת קטנות נופלים בינה ותו״מ שלה לספירה התחתונה, ומחמת זה, בעת גדלות, כשבינה ותו״מ חוזרים להספירה, לוקחים עמהם גם הספירה התחתונה, ומעלים אותה עמהם להספירה העליונה. (כנ״ל בהקסה״ז דף כ׳ ד״ה ואמא ע״ש) ואז הכו\"ח שבספירה נעשו לקו ימין, ובינה ותו״מ לקו שמאל, וספירה התחתונה שעלתה אליהם נעשתה לקו האמצעי. וסדר זה הוא בכל ספירה וספירה. ונמצא שכל ספירה שואלת כלים מן ספירה תחתונה כדי להשלים את הקו האמצעי שבה. וז״ש, \u0003וכל אמירה אוזיף לאמירה עלאה מנה אתווי.\u0004 שכל ספירה משאלת אותיות, שהם כלים לספירה עליונה ממנה, כדי להשלים בה קו האמצעי. \u0003בגין דאתכליל האי בהאי,\u0004 כי מתוך שבינה ותו״מ של כל עליון נפלו והיו בספירה תחתונה בעת קטנות \u0003ונתכללו\u0004 בה, ע״כ בעת גדלות כשבינה ותו״מ אלו חוזרים למדרגתם, לוקחים עמהם התחתונה ומעלים אותם למדרגתם, שעי״ז \u0003נכללה\u0004 כל תחתונה בעליונה, והיתה שמה לקו האמצעי."],[0,"","ומאותו הטעם, כל ספירה תחתונה כשחוזרת ויורדת למקומה, לוקחת עמה למקומה המוחין דעליונה. וגם חלק מכלים דבינה ותו״מ דעליונה, משום שהתחתונה נכללה בה בעת היותה בעליונה, והם נעשו לה כלים להלבשת המוחין. שה״ס נה״י דעליונה המתלבשים בתחתונה (כנ״ל ויקהל אות שכ״ב ואות ש״י ד״ה צריך) וז״ש, \u0003וע״ד שמא קדישא גליפנא ליה באתוון אחרנין, בגין דאתכסיין דא בדא,\u0004 שכל נה״י דעליונה מתכסים ומתלבשים בתחתונה, ובזה, \u0003מתקשרן כלהו כחדא,\u0004 שכל ספירה מתקשרת עי״ז בחברתה. דהיינו כל עליונה בתחתונה. וכל תחתונה בעליונה. וע״כ השם \u0003הויה,\u0004 שהוא ז״א מתלבש ומתכסה בשם \u0003אדני,\u0004 שהיא מלכות, דהיינו במדרגה תחתונה."],[1,"ומאן דבעי למנדע וכו׳:","ומי שרוצה לדעת להבין צרופי שמות הקדושים, צריך לדעת אלו אותיות הרשומים בכל ספירה וספירה, ואז ידע ויתקיים בכל. והרי כתבנו אותן, בכל אלו האותיות הרשומות וידועות בכל ספירה וספירה, מתוך ספרו העליון של שלמה. וכך עלה בידינו. והחברים כתבו אותם. ויפה הוא, שכתבו אותם, כי כל ספירה וספירה משאלת אותיות לחברתה, שצריכים לדעת ולזכור אותם, כמו שהעמדנו בדבור הסמוך. ולפעמים שלא צריכים לדעת אלא האותיות הרשומות בהספירה בלבד, ולא אותיות שמשאילות זו לזו. והכל ידוע לחברים. והרי העמדנו אותם."],[2,"זכאין אינון צדיקיא וכו׳:","אשריהם הצדיקים בעולם הזה ובעולם הבא, שהקב״ה רוצה בכבודם, ומגלה להם סודות עליונים של שמו הקדוש, שלא גילה למלאכים העליונים הקדושים. וע״כ יכול משה להתעטר בין המלאכים הקדושים, וכולם לא יכלו לקרב אליו כאש שורף וגחלי אש. משום שהזכיר שמות הקדושים, שהמלאכים לא ידעום. שאם לא כן, מה היה לו למשה, שיוכל לעמוד ביניהם, אלא אשרי חלקו של משה, כי כשהתחיל הקב״ה לדבר עמו, רצה לדעת שמו הקדוש הסתום והגלוי כל אחד ואחד כראוי לו. ואז נתדבק וידע יותר מכל בני העולם."],[3,"ת״ח בשעתא דסליק וכו׳:","בוא וראה, בשעה שעלה משה תוך הענן, נכנס בין מלאכים הקדושים. פגע בו מלאך אחד בשלהבת אש, בעינים לוהטות, וכנפיו שורפות, ורצה לבלוע אותו לתוכו. קמואל שמו. אז הזכיר משה שם אחד קדוש, שהיה חקוק בי״ב אותיות, ונזדעזע ונתרגש. עד שעלה משה ביניהם. וכן לכל אחד ואחד. אשרי חלקו. וכבר העמדנו הדברים לעיל (בשלח אות רצ״ח. וע״ש בהסולם פירוש הדברים)."],[4,"ערות אשה ובתה לא מגלה:","למדנו, בתקוני המלכה העמדנו אלו העריות, אע״פ שהם בגלוי ובסתום, ושם בת בנה בת בתה. כי העולם צריך להם, והם ישוב העולם, כמו שהעמדנו. ומי שמגלה ערוה אחת מהם, אוי לו אוי לנפשו, כי מגלה בשביל זה עריות אחרות."],[4,"","פירוש. אשה ובתה, ה״ס בינה ומלכות. אשר בינה היא סתומה מהארת חכמה, והמלכות, היא בגלוי, שהארת החכמה מתגלית בה. אמנם המלכות עצמה מתחלקת ג״כ לב' בחינות סתומה וגלויה. כי מחזה ולמעלה היא סתומה, ורק מחזה ולמטה מתגלית בה הארת החכמה. ועל דרך זה גם ז״א, הוא סתום וגלוי, שמחזה ולמעלה הוא סתום, ומחזה ולמטה הוא גלוי, דהיינו שהארת חכמה מתגלית שם. והטעם הוא. משום שמחזה ולמטה מאיר אור נקבה, דהיינו ממטה למעלה. והחכמה אינה מאירה אלא ממטה למעלה, (כנ״ל ב״א דף ס׳ ד״ה מחלוקת) ע״כ הן בז״א והן במלכות, אין החכמה מתגלה רק מחזה ולמטה, ששם אור נקבה. ומשום זה מכונה בחינת מחזה ולמטה בשם \u0003בת,\u0004 כלומר אור נקבה, הן בז״א והן במלכות. ונמצא שבחינת מחזה ולמטה של המלכות, נבחנת לבת בתה של הבינה. כי אשה ובתה, היא בינה ומלכות. ומחזה ולמטה, שהיא בחינת בת של המלכות היא \u0003בת בתה של הבינה.\u0004 ומחזה ולמטה של ז״א, נבחן לבת בנה של הבינה. כי בינה וז״א, הם אשה ובנה. ומחזה ולמטה דז״א ששם בת ז״א, היא \u0003בת בנה של הבינה.\u0004"],[4,"","וז״ש, \u0003בתקוני מטרוניתא אוקימנא אלין עריין, אע\"ג דאינון באתגליא ובסתימא,\u0004 כלומר אע״פ שאשה ובתה שהם בינה ומלכות, נמצאת הבינה בסתימא, והמלכות באתגליא. וא״כ היה אפשר לחשוב שאין נוהג גילוי ערוה במלכות. רק בבינה בלבד להיותה סתומה ונעלמה. ומכל שכן, \u0003ותמן, בת בנה ובת בתה,\u0004 שהם מחזה ולמטה דז״א ומחזה ולמטה של המלכות ששם עיקר מקום התגלות החכמה, א״כ לא שייך האיסור דגילוי ערוה. משום, \u0003דהא עלמא אצטריך לון, ואינון ישובא דעלמא,\u0004 כי העולם צריך לגילוי החכמה אשר שם. שזהו כל ישוב העולם. כי אם לא היתה מתגלית שם הארת החכמה, לא היו נולדות הנשמות, כי אין הולדת נשמות אלא אחר שנתגלתה שם הארת החכמה. וא״כ היה אפשר לחשוב שלא שייך שם גילוי ערוה. וז״ש. \u0003ומאן דגלי חד ערייתא ווי ליה ווי לנפשיה דהא גלי בגין דא עריין אחרנין.\u0004 פירוש. כי גילוי ערוה, פירושו, שממשיך הארת החכמה ממעלה למטה כדרך הס״א, שהוא בחינת אור זכר, המשפיע מלמעלה למטה, ונמצא שהמגלה ערוה, אפילו במקום מחזה ולמטה דז״א ומלכות, דהיינו שממשיך משם ממעלה למטה, הרי הוא מגלה ערוה במקום מחזה ולמעלה ובמקום בינה, ששם אור זכר הנעלם ומכוסה. שהרי הוא המשיך אור זכר, שהיא בחינת מחזה ולמעלה. ונמצא אע״פ שהוא נאחז במקום המותר, שהוא אור נקבה, אמנם אם ממשיך ממעלה למטה, הרי הוא מגלה אור זכר, ומתגלות העריות במקום האסור. וז״ש, \u0003דהא גלי בגין דא עריין אחרנין.\u0004 אמנם אם אינו ממשיך ממעלה למטה, אלא ממטה למעלה, אינו ח״ו מגלה ערוה, אלא אדרבא, שהוא ישוב העולם, כמ״ש, \u0003ואינון ישובא דעלמא.\u0004 כי אין הולדת נשמות אלא בגילוי החכמה ממטה למעלה."],[5,"ותניא מלה בתראה וכו׳:","ולמדנו המלה האחרונה, של עשרת הדברות של התורה, היא לא תתמוד אשת רעך. משום שזה הוא כלל כולם. ומי שחומד אשה, אחרת, כאלו עבר על התורה כולה. אמנם אין לך דבר שעומד בפני התשובה. וכל שכן אם קבל ענשו כדוד המלך. א״ר יוסי, למדנו כל מי שחטא ונפרש מהחטא ההוא, התשובה מועילה לו ביותר. ואם לא נפרש אין התשובה עולה בידו, ואינה מועילה לו. ושואל, אם כן, דוד, איך לא נפרש מבת שבע לאחר כך. אמר לו בת שבע שלו היתה, ושלו לקח, כי בעלה מת."],[6,"דתניא אזדמנת הוה וכו׳:","שלמדנו, מוכנת היתה בת שבע לדוד מיום שנברא העולם. ומה עיכב אותו שלא לקחה, הוא משום שלקח בת שאול המלך. ויום ההוא לקחה אוריה ברחמים, אע״פ שלא היתה שלו. (כמ\"ש בהקדסה״ז דף ק״ז ד״ה והענין ע״ש) ואח״כ בא דוד ולקח את שלו. ומשום שדוד דחק את השעה לפני הקב״ה להרג את אוריה, ולעשות כך, חטא לפניו, וענש את דוד. כי הקב״ה רצה להשיב את בת שבע לדוד, כדי לקיים לו מלכות הקדושה העליונה. כי בת שבע היתה מרכבה למלכות (כמ״ש שם) וכשחשק, אל שלו חשק."],[7,"תאנא א״ר יוסי וכו׳:","למדנו, אר״י, מה שכתוב, \u0003אני ה׳,\u0004 פירושו, אני ה׳, עתיד לתת שכר טוב לצדיקים לעתיד לבא, אני ה׳ עתיד להפרע מן הרשעים לעתיד לבא, דהיינו אותם שכתוב בהם, הפושעים בי. שואל, כתוב אני הויה, שיורה על מדת הרחמים, וכתוב, אני אמית ואחיה, שיורה על מדת הדין. ומשיב, שפירושו, אע״פ שאני במדת הרחמים, הרשעים הופכים אותי למדת הדין. שלמדנו, הויה אלקים הוא שם מלא, שהויה הוא רחמים ואלקים הוא דין, ופירושו, זכו, הויה. ואם לא זכו. אלקים. א״ר שמעון, הרשעים עושים פגם למעלה. מהו הפגם. הוא כמו שהעמדנו, פגם ממש. וכבר נתבאר. לעיל (ויקרא אות ר״ע)"]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן לְרַבִּי אֶלְעָזָר, בֹּא רְאֵה, עֶשְׂרִים וּשְׁתַּיִם הָאוֹתִיּוֹת שֶׁחֲקוּקוֹת בַּתּוֹרָה, כֻּלָּן מִתְפָּרְשׁוֹת (מאלו) בְּעֶשֶׂר הָאֲמִירוֹת הַלָּלוּ, כָּל אֲמִירָה וַאֲמִירָה מֵאוֹתָן הָעֶשֶׂר, שֶׁהֵן כִּתְרֵי הַמֶּלֶךְ, כֻּלָּן חֲקוּקוֹת בְּאוֹתִיּוֹת יְדוּעוֹת (אחרות). מִשּׁוּם כָּךְ הַשֵּׁם הַקָּדוֹשׁ מִתְכַּסֶּה בְּאוֹתִיּוֹת אֲחֵרוֹת, וְכָל אֲמִירָה מַלְוָה לַאֲמִירָה יוֹתֵר עֶלְיוֹנָה אֶת אוֹתִיּוֹתֶיהָ, מִשּׁוּם שֶׁנִּכְלָלוֹת זוֹ עִם זוֹ. וְלָכֵן אֶת הַשֵּׁם הַקָּדוֹשׁ חָקַקְנוּ אוֹתוֹ בְּאוֹתִיּוֹת אֲחֵרוֹת, מִשּׁוּם שֶׁהִתְכַּסּוּ זוֹ בְּזוֹ וְזוֹ בָּזוֹ, עַד שֶׁכֻּלָּן נִקְשָׁרוֹת כְּאַחַת."],[1,"","וּמִי שֶׁרוֹצֶה לָדַעַת אֶת צֵרוּפֵי הַשֵּׁמוֹת הַקְּדוֹשִׁים, שֶׁיֵּדַע אֶת אוֹתָן הָאוֹתִיּוֹת הָרְשׁוּמוֹת בְּכָל כֶּתֶר וְכֶתֶר, וְאָז יֵדַע וְיִתְקַיֵּם בַּכֹּל. וַהֲרֵי חָקַקְנוּ אוֹתָם בְּכָל אוֹתָן הָאוֹתִיּוֹת שֶׁרְשׁוּמוֹת וִידוּעוֹת בְּכָל כֶּתֶר וְכֶתֶר מֵהַסֵּפֶר הָעֶלְיוֹן שֶׁל שְׁלֹמֹה. וְכָךְ עָלָה בְיָדֵינוּ, וְהַחֲבֵרִים חָקְקוּ אוֹתָם, (ולחברים גלינו אותם) וְיָפֶה הוּא. שֶׁהֲרֵי כָּל כֶּתֶר וְכֶתֶר מַלְוֶה לַחֲבֵרוֹ אֶת אוֹתִיּוֹתָיו, כְּמוֹ שֶׁבֵּאַרְנוּ, וְלִפְעָמִים שֶׁלֹּא צָרִיךְ אֶלָּא בָּאוֹתִיּוֹת אוֹתָם שֶׁרְשׁוּמִים בּוֹ. וְכֻלָּם יְדוּעִים לַחֲבֵרִים, וַהֲרֵי בֵּאַרְנוּ אוֹתָם."],[2,"","אַשְׁרֵי הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בִּכְבוֹדָם וּמְגַלֶּה לָהֶם סוֹדוֹת עֶלְיוֹנִים שֶׁל שְׁמוֹ הַקָּדוֹשׁ, שֶׁלֹּא גִלָּה לְעֶלְיוֹנִים קְדוֹשִׁים, וְעַל זֶה יָכֹל מֹשֶׁה לְהִתְעַטֵּר בֵּין קְדוֹשִׁים, וְכֻלָּם לֹא יָכְלוּ לְהִתְקָרֵב אֵלָיו, כְּאֵשׁ יוֹקֶדֶת וְגַחֲלֵי אֵשׁ. שֶׁאִם לֹא כָּךְ, מִי הָיָה לוֹ לְמֹשֶׁה לַעֲמֹד בֵּינֵיהֶם? אֶלָּא אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה, שֶׁהֲרֵי כְּשֶׁהִתְחִיל לְדַבֵּר עִמּוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, רָצָה לָדַעַת אֶת שְׁמוֹ הַקָּדוֹשׁ (שמותיו הקדושים), נִסְתָּר וְנִגְלֶה, בְּכָל אֶחָד וְאֶחָד כָּרָאוּי, וְאָז נִדְבַּק וְיָדַע יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם."],[3,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה מֹשֶׁה לְתוֹךְ הֶעָנָן הַנִּכְבָּד, נִכְנַס לְבֵין קְדוֹשִׁים. פָּגַע בּוֹ מַלְאָךְ אֶחָד בְּשַׁלְהֲבוֹת אֵשׁ, בְּעֵינַיִם לוֹהֲטוֹת, וּכְנָפָיו שׂוֹרְפוֹת. רָצָה לִשְׁאֹף אוֹתוֹ לְתוֹכוֹ. וְשֵׁם אוֹתוֹ מַלְאָךְ גַּבְרִיאֵל (גזריא\"ל) (גזרנא\"ל). אָז הִזְכִּיר מֹשֶׁה שֵׁם קָדוֹשׁ אֶחָד שֶׁהָיָה חָקוּק עִם שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת, וְהִזְדַּעֲזַע וְהִתְרַגֵּשׁ, עַד שֶׁעָלָה מֹשֶׁה בֵּינֵיהֶם, וְכֵן לְכָל אֶחָד וְאֶחָד. אַשְׁרֵי חֶלְקוֹ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים."],[4,"","עָרְוַת אִשָּׁה וּבִתָּהּ לֹא תְגַלֵּה. לָמַדְנוּ, בְּתִקּוּנֵי הַגְּבִירָה בֵּאַרְנוּ אֶת הָעֲרָיוֹת הַלָּלוּ, אַף עַל גַּב שֶׁהֵם (עריות הם) בַּנִּגְלֶה וּבַנִּסְתָּר, וְשָׁם בַּת בְּנָהּ וּבַת בִּתָּהּ. שֶׁהֲרֵי הָעוֹלָם צָרִיךְ אוֹתָם, וְהֵם יִשּׁוּבוֹ שֶׁל עוֹלָם, כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִי שֶׁמְּגַלֶּה עֶרְוָה אַחַת מֵהֶן, אוֹי לוֹ וְאוֹי לְנַפְשׁוֹ, שֶׁהֲרֵי גִּלָּה בִּשְׁבִיל זֶה עֲרָיוֹת אֲחֵרוֹת."],[5,"","וְלָמַדְנוּ, הַדִּבּוּר הָאַחֲרוֹן שֶׁל עֶשֶׂר הָאֲמִירוֹת שֶׁל הַתּוֹרָה - (שמות כ) לֹא תַחְמֹד אֵשֶׁת רֵעֶךְ, כִּי זֶהוּ הַכְּלָל שֶׁל כֻּלָּם. וּמִי שֶׁחוֹמֵד אִשָּׁה אַחֶרֶת כְּאִלּוּ עָבַר עַל כָּל הַתּוֹרָה. בְּרַם, אֵין דָּבָר שֶׁעוֹמֵד לִפְנֵי תְשׁוּבָה, וְכָל שֶׁכֵּן אִם קִבֵּל עָנְשׁוֹ כְּמוֹ דָּוִד הַמֶּלֶךְ. אָמַר רַבִּי יוֹסֵי, שָׁנִינוּ, כָּל מִי שֶׁחָטָא וּפָרַשׁ מֵאוֹתוֹ חֵטְא, הַתְּשׁוּבָה מוֹעִילָה לוֹ יוֹתֵר. וְאִם לֹא, לֹא עוֹלָה בְיָדוֹ תְּשׁוּבָה וְלֹא מוֹעִילָה לוֹ. אִם כָּךְ, אָז אֵיךְ דָּוִד לֹא פָרַשׁ מִבַּת שֶׁבַע לְאַחַר מִכֵּן? אָמַר לוֹ, בַּת שֶׁבַע הָיְתָה שֶׁלּוֹ, וְאֶת שֶׁלּוֹ הוּא לָקַח, שֶׁהֲרֵי מֵת בַּעְלָהּ."],[6,"","שֶׁלָּמַדְנוּ, מְזֻמֶּנֶת הָיְתָה בַּת שֶׁבַע לְדָוִד מִיּוֹם שֶׁנִּבְרָא הָעוֹלָם, וּמָה עִכֵּב אוֹתוֹ? שֶׁנָּשָׂא אֶת בִּתּוֹ שֶׁל שָׁאוּל הַמֶּלֶךְ, וְאוֹתוֹ יוֹם נָשָׂא אוֹתָהּ אוּרִיָּה בְּרַחֲמִים, אַף עַל גַּב שֶׁלֹּא הָיְתָה שֶׁלּוֹ. אַחַר כָּךְ בָּא דָוִד וְנָטַל אֶת שֶׁלּוֹ. וְעַל שֶׁדָּוִד דָּחַק אֶת הַשָּׁעָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לַהֲרֹג אֶת אוּרִיָּה וְלַעֲשׂוֹת כָּךְ, הֵרַע לְפָנָיו, וְהֶעֱנִישׁ אֶת דָּוִד, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לַהֲשִׁיבָהּ לְדָוִד, לְקַיֵּם לוֹ אֶת הַמַּלְכוּת הַקְּדוֹשָׁה הָעֶלְיוֹנָה. וּכְשֶׁהִשְׁתּוֹקֵק, לְשֶׁלּוֹ הִשְׁתּוֹקֵק."],[7,"","לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, מַהוּ שֶׁכָּתוּב אֲנִי ה' - אֲנִי ה' עָתִיד לִתֵּן שָׂכָר טוֹב לַצַּדִּיקִים לֶעָתִיד לָבא. אֲנִי ה' עָתִיד לְהִפָּרַע מִן הָרְשָׁעִים לֶעָתִיד לָבֹא, אוֹתָם שֶׁכָּתוב בָּהֶם הַפֹּשְׁעִים בִּי. כָּתוּב אֲנִי ה', וְכָתוּב (דברים לב) אֲנִי אָמִית וַאֲחַיֶּה. אַף עַל פִּי שֶׁאֲנִי בְּמִדַּת הָרַחֲמִים, הָרְשָׁעִים הוֹפְכִים אוֹתִי לְמִדַּת הַדִּין. שֶׁלָּמַדְנוּ, שֵׁם מָלֵא - ה' אֱלֹהִים. זָכוּ - ה', וְאִם לֹא - אֱלֹהִים. אָמַר רַבִּי שִׁמְעוֹן, הָרְשָׁעִים עוֹשִׂים פְּגָם לְמַעְלָה. אֵיזֶה פְּגָם? כְּמוֹ שֶׁבֵּאַרְנוּ פְּגָם מַמָּשׁ, וַהֲרֵי נִתְבָּאֵר."]]],[["תָּאנָא כְּתִיב וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ, תָּנֵי רִבִּי יְהוּדָה, דָּרָא דְּרִבִּי שִׁמְעוֹן בֶּן יוֹחָאי שָׁארֵי בְּגַוִּיהּ, כֻּלְּהוּ זַכָּאִין, חֲסִידִין, כֻּלְּהוּ דַּחֲלֵי חַטָּאָה נִינְהוּ. שְׁכִינְתָּא שַׁרְיָא בֵּינַיְיהוּ, מַה דְּלֵית כֵּן בְּדָרִין אָחֳרָנִין. בְּגִינֵי כַּךְ מִילִּין אִינּוּן מִתְפָּרְשָׁן, וְלָא אִתְטַמְּרָן. בְּדָרִין אָחֳרָנִין לָאו הָכִי, וּמִלִּין דְּרָזֵי עִלָּאָה לָא יַכְלִין לְגַלָּאָה, וְאִינּוּן דְּיַדְעֵי מִסְתָּפוּ. דְּרַבִּי שִׁמְעוֹן כַּד הֲוָה אָמַר רָזָא דְּהַאי קְרָא, חַבְרַיָּיא כֻּלְּהוּ עֵינֵיהוֹן נַבְעִין דִּמְעִין, וְכֻלְהוּ מִילִּין דְּאָמַר הֲווֹ בְּעֵינַיְיהוּ גַּלְיָין, כְּמָה דִּכְתִּיב, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ וּמַרְאֶה וְלֹא בְחִידוֹת.","דְּיוֹמָא חַד שָׁאִיל רִבִּי יֵיסָא אָמַר, בֵּיעָא דְּקוּשְׁטָא (ס\"א דקוסטא), דְּנָפְקָא מֵעוֹפָא דְּשַׁרְיָא (ס\"א דשדי) בְּנוּרָא, וְאִתְבָּקַע לְאַרְבַּע סִטְרִין. תְּרֵין סַלְּקִין מִנַּיְיהוּ, וְחַד מָאִיךְ, וְחַד רְבִיעַ בִּרְבִיעָא (ס\"א נביעי נביעא) דְּיַמָּא רַבָּא. אָמַר רִבִּי אַבָּא, עַבְדַת קַמֵּיהּ דְּרַבִּי שִׁמְעוֹן, קֹדֶשׁ חוֹל, דְּהָא כְּתִיב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, עַד לָא יִתְבְּקַע בֵּיעָא, (שמות ס\"א ע\"ב, קע\"ד ע\"א) תִּסְתָּלַּק מֵעָלְמָא. וְכַךְ הֲוָה בְּאִדָּרָא דְּרַבִּי שִׁמְעוֹן.","תָּאנָא, בְּיוֹמוֹי דְּרַבִּי שִׁמְעוֹן הֲוָה אָמַר בַּר נָשׁ לְחַבְרֵיהּ, פְּתַח פִּיךָ וְיָאִירוּ דְּבָרֶיךָ. בָּתַר דְּשָׁכִיב רַבִּי שִׁמְעוֹן, הֲווֹ אַמְרֵי (קהלת ה׳:ה׳) אַל תִּתֵּן אֶת פִּיךָ לַחֲטִיא אֶת בְּשָׂרֶךָ.","תַּנְיָא אָמַר רַבִּי שִׁמְעוֹן, אִי בְּנֵי עָלְמָא מִסְתַּכְּלָן בְּמָה דִּכְתִּיב בְּאוֹרַיְיתָא, לָא יֵיתוּן לְאַרְגָּזָא קָמֵי מָארֵיהוֹן. תָּאנָא, כַּד מִתְעָרִין דִּינִין קַשְׁיָין לְאַחֲתָא בְּעָלְמָא, וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ וְגוֹ', הָכָא כְּתִיב (תהלים כה) סוֹד יְיָ' לִירֵאָיו, (ר\"צ ע\"ב ובאדרא ס\"א ובהאי דרא) וּבְאִדָרָא קַדִּישָׁא אִתְּמַר, הָכָא אִצְטְרִיכְנָא לְגַלָּאָה, דְּהָא לַאֲתַר דָּא אִסְתַּלָּק.","דְּתָנֵינָן, בְּשַׁעֲתָא דְּחִוְיָא תַּקִּיפָא דִּלְעֵילָּא אִתְּעַר, בְּגִין חוֹבֵי עָלְמָא, שָׁארֵי וְאִתְחַבָּר עִם נוּקְבָּא, וְאָטִיל בָּהּ זוּהֲמָא, אִתְפְּרַשׁ דְּכוּרָא מִינָּהּ, בְּגִין דְּהָא אִסְתְּאָבַת, וְאִתְקְרִיאַת מִסְאֲבָא, וְלָא אִתְחֲזֵי לִדְכוּרָא לְמִקְרַב בַּהֲדָהּ, דְּוַוי אִי אִסְתְּאַב הוּא בַּהֲדָהּ, בְּזִמְנָא דְּאִיהִי אִסְתְּאָבַת.","וְתָאנָא, (תשא קצ\"ב) מְאָה וְעֶשְׂרִין וַחֲמֵשׁ זִינֵי מְסַאֲבוּתָא נַחְתּוּ לְעָלְמָא, דְּמִתְאַחֲדָן מִסִּטְרָא דְּחִוְיָא תַּקִּיפָא, וְשִׁבְעָה וְעֶשְׂרִין רַבְרְבִין מִנַּיְיהוּ, מִתְאַחֲדָן בְּנוּקְבֵי, וְאִתְדַּבְּקָן בְּהוּ. וַוי לְמַאן דְּיִקְרַב בַּהֲדָהּ בְּהַהוּא זִמְנָא, דְּמַאן דְּיִקְרַב בַּהֲדָהּ, אַחְזֵי פְּגִימוּתָא לְעֵילָּא, דְּהָא בְּחוֹבָא דָּא, אִתְּעַר חִוְיָא תַּקִּיפָא לְעֵילָּא, וְאַשְׁדֵּי זוּהֲמָא בַּאֲתַר דְּלָא אִצְטְרִיךְ, וְאִתְחַבָּר בְּנוּקְבָּא, וְאִתְרַבֵּי שַׂעֲרֵיהּ לִדְכוּרָא, בְּנוּקְבָּא אִסְתְּאָבַת, וְשַׂעְרָהָא רַבָּא, וְטוּפְרָהָא סַגִיאוּ, וּכְדֵין דִּינִין שַׁרְיָין לְאִתְּעָרָא בְּעָלְמָא, וְיִסְתַּאֲבוּן כֹּלָּא. הֲדָא הוּא דִכְתִיב, (במדבר י״ט:כ׳) כִּי אֶת מִקְדַּשׁ יְיָ' טִמֵּא, מִקְדַּשׁ יְיָ' אִסְתְּאַב, בְּחוֹבַיְיהוּ דִּבְנֵי נָשָׁא.","תָּאנָא, מַאי דִּכְתִּיב, (בראשית ג׳:ט״ו) וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה, אַרְבָּעָה וְעֶשְׂרִים זִינֵי מְסַאֲבוּתָא אַטִּיל חִוְיָא בְּנוּקְבָּא, כַּד אִתְחַבָּר עִמָּהּ, כְּחוּשְׁבָּן וְאֵיבָה, וְעֶשְׂרִין וְד' זִינִין (ס\"א דינין) מִתְעָרִין לְעֵילָּא, וְעֶשְׂרִין וְאַרְבַּע לְתַתָּא. וְשַׂעֲרָא רַבָּא, וְטוּפְרִין סְגִיאוּ, וּכְדֵין דִּינִין מִתְעָרִין בְּכֹלָּא. וְתָאנָא כַּד בָּעַת אִתְּתָא לְאִתְדַכְּאָה, בַּעְיָא לְסַפְּרָא הַהוּא שַׂעֲרָא דְּרַבֵּי בְּיוֹמָא דְּאִיהִי מִסְאֲבָא, וּלְסַפְּרָא טוּפְרָהָא, וְכָל הַהוּא זוּהֲמָא דִּי בְּהוֹן.","דְּתָאנָא בְּרָזֵי דִּמְסָאֲבוּתָא, זוּהֲמָא דְּטוּפְרִין, יִתְּעַר זוּהֲמָא אָחֳרָא, וּבְגִּינֵי כַּךְ, בַּעְיָין גְּנִיזָא, וּמַאן דְּאַעְבָּר לוֹן לְגַמְרֵי, כְּאִלּוּ אִתְּעַר חֶסֶד בְּעָלְמָא. דְּתַנְיָא לָא לִבְעֵי לֵיהּ לְאִינִישׁ לְמֵיהַב דּוּכְרָנָא לְזִינִין בִּישִׁין. דְּתָנֵינָן (ע\"ז ע\"א) אֶלַף וְאַרְבַּע מְאָה וְה' זִינִין בִּישִׁין, מִתְאַחֲדָן בְּהַהוּא זוּהֲמָא, דְּאָטִיל חִוְיָא תַּקִּיפָא, וְכֻלְּהוּ מִתְעָרִין בְּהַהוּא זוּהֲמָא דְּטוּפְרִין."],[[0,"תאנא כתיב וכו׳:","למדנו כתוב, ואל אשה בנדת טומאתה לא תקרב לגלות ערותה. למד ר׳ יהודה, הדור, שר״ש בן יוחאי שורה בו, כולם זכאים, כולם חסידים יראי חטא הם, השכינה שורה ביניהם. מה שאין כן בדורות אחרים. משום זה דברים אלו מתבארים ואינם נסתרים, בדורו, בדורות אחרים אינו כן, ודברי סודות עליונים אינם יכולים להתגלות. ואלו שיודעים יראים לגלות, כי ר״ש, כשהיה אומר הסוד של המקרא הזה, החברים כולם, היו עיניהם נוזלות דמעות, וכל הדברים שאמר, היו מגולים בעיניהם. כמ״ש, פה אל פה אדבר בו במראה ולא בחידות."],[1,"דיומא חד שאיל וכו׳:","שיום אחד שאל ר׳ ייסא, אמר, ביצה של אמת, היוצאת מעוף השורה באש, ונתבקע לארבע צדדים, שנים עולים מהם, ואחד הושפל, ואחד רובץ ברביצה של ים הגדול. א״ר אבא, עשית לפני ר״ש, הקודש לחול, שהרי כתוב, פה אל פה אדבר בו. אמר לו ר׳ שמעון, עד העת שלא תתבקע הביצה, תסתלק מן העולם. וכך היה באדרא של ר״ש. כמובא בסוף אדרא רבה."],[1,"","ביאור הדברים. קו השמאל כשהוא בלי ימין הוא בחינת דינים קשים, ומכונה עוף השורה באש. והמלכות נבנית בעיקרה מקו שמאל. והמלכות מכונה ביצה של אמת, כי אפרוחים הם בחינת ז״א, וביצים הם בחינת המלכות כנודע. וז״ש, \u0003ביעא דקושטא דנפקא מעופא דשריא בנורא\u0004 דהיינו מלכות היוצאת ונמשכת מקו שמאל השורה באש הדינים. והעצה לזה לבטל הדינים האלו הוא ע״י הקו האמצעי, שהוא מעלה את המסך דחירק, המחזיר המלכות לבינה, וחוזרים ונבקעים המדרגות לב׳ חצאים (כמ״ש לעיל פרשת לך אות כ״ה בהסולם ד״ה אשגח ע״ש כל ההמשך) ונקבע פרסא בין ג״ר לו״ק, שבכל בחינות הג״ר נעלמת החכמה, ואינה מאירה אלא בו״ק. ומשום זה גם ז״א שהוא בחינת ג״ר, הוא בחסדים מכוסים, והמלכות שהיא בבחינת ו\"ק היא בהארת ו\"ק דחכמה."],[1,"","וז״ש \u0003ואתבקעא לד׳ סטרין,\u0004 שע״י הקו האמצעי שהעלה המלכות לבינה נבקעה הביצה לארבע צדדים שהם חו״ב תו״מ, אשר הג״ר דחכמה שה״ס חו״ב נעלמו, ולא נשאר אלא ו״ק דחכמה, שהם תו״מ. וז\"ש \u0003תרין סלקין מנייהו,\u0004 דהיינו חכמה ובינה, הנעלמים מחכמה. \u0003וחד מאיך,\u0004 היינו ז״א שהוא ת״ת הושפל, שאין לו חכמה אלא חסדים מכוסים מחכמה. \u0003וחד רביע, ברביעא דימא רבא.\u0004 רובצת פירושו ו\"ק, כי מדרך הרובץ שמסתיר הרגלים שלו, שה\"ס נה״י, והחסר נה״י דכלים, יחסרו לו ג״ר דאורות. ונמצאה המלכות אע״פ שיש לה חכמה אין לה אלא ו״ק דחכמה שהיא בחינת \u0003רובצת, ברביצה דים הגדול,\u0004 כלומר רביצה דבחינת חכמה המכונה ים הגדול."],[1,"","אמנם באמת אינו כן, כי אע״פ שז\"א הוא בחסדים מכוסים, לא הושפל מחמת זה, ואדרבא, שהשיג בזה בחינת מוחין דקדש דאו״א עלאין, שהחסדים שלהם מעולים יותר מחכמה, כי מהם יוצאת החכמה לישסו״ת כנודע. ואו״א מכונים קדש. וז\"ש, \u0003א״ר אבא עבדת קמיה דר״ש קדש חול.\u0004 כי על מוחין דקדש דז״א, אמר \u0003חד מאיך,\u0004 שהושפל ונעשה חול. ור״ש היה מרכבה לז״א, והיה לו המוחין ההם דאו״א עלאין, שה״ס פה אל פה. וז\"ש \u0003דהא כתיב פה אל פה אדבר בו.\u0004 שאין עוד מוחין יותר חשובים מהם. ואתה אמרת עליו \u0003וחד מאיך,\u0004 שהוא חול."],[1,"","והנה בגמר התקון יתבטל ענין בקיעת המדרגה והפרסא המבדלת בין למעלה מחזה ובין למטה מחזה, שפירושה הגבול שנעשה מחמת בקיעת המדרגה, וע״כ מ״ה וב״ן ישובו להיות כמו ע״ב ס״ג, ותו״מ כמו חו״ב. וכשר״ש ותלמידיו גמרו את אדרא רבה, האיר עליהם בחינת גמר התקון, דהיינו ביטול הבקיעה והפרסא. ולפיכך, אותם ג׳ החברים ר׳ יוסי ב״ר יעקב ורבי חזקיה ורבי ייסא, שהיו נשמתם מבחינת למטה מפרסא, נסתלקו תיכף, מחמת שנתעלו למעלה, מפרסא, וצורתם שלמטה מפרסא, נסתלקה עם הפרסא שנתבטלה. וז״ס שכתוב שם (נשא קמ״ד ע״א, ד״י) וחמו חבריא דהוו נטלין מלאכין קדישין \u0003בההוא פרסא.\u0004 ע״ש. כי נשמתם נסתלקה בסבת הסתלקות הפרסא."],[1,"","וז״ש, א״ל ר״ש, \u0003עד לא יתבקע ביעא תסתלק מעלמא,\u0004 דהיינו עד, שיבא התקון, שלא יתבקע הביצה, דהיינו בגמר התקון, שתתבטל בקיעת המדרגה, \u0003תסתלק מעלמא,\u0004 כי תתבטל ותכלול אז עם ביטול הבקיעה והפרסא. ואז תבחין בין קדש לחול. כי תסתלק, ותהיה כמו המדרגות שלמעלה מפרסא, שהם בחינות או״א עלאין. שה״ס חו״ב וע״ב ס\"ג. הנקראים קדש. וז״ש, \u0003וכך הוה באדרא דר״ש,\u0004 כי אז האיר גמר התקון, כנ״ל."],[2,"תאנא ביומוי דר״ש וכו׳:","למדנו בימיו של ר׳ שמעון, היה אומר אדם לחבירו, פתח פיך ויאירו דבריך: אחר שנפטר ר׳ שמעון, היו אומרים, אל תתן את פיך לחטיא את בשרך. דהיינו שלא יגלו סוד."],[3,"תניא אר״ש וכו׳:","למדנו, א״ר שמעון, אם בני העולם היו מסתכלים במה שכתוב בתורה לא היו באים להרגיז לפני רבונם. למדנו, כשמתעוררים דינים קשים לרדת בעולם, כתוב, ואל אשה בנדת טומאתה וגו'. על זה כתוב, סוד ה׳ ליראיו. ובאדרא קדישא למדנו זה, וכאן אני צריך לגלות הסוד, כי למקום זה הוא עולה. כלומר שכאן הוא המקום לגלותו."],[4,"דתנינן בשעתא דחויא וכו׳:","שלמדנו, בשעה שהנחש החזק שלמעלה נתעורר בשריל עונות העולם, הוא שורה ומתחבר עם הנוקבא, ומטיל בה זוהמא, ואז נפרש הדכר ממנה, משום שנטמאה, ונקראת טמאה, ואין ראוי לדכר שיקרב אליה, כי אוי לעולם, אם הוא נטמא עמה בזמן שהיא טמאה."],[4,"","פירוש. ב׳ נקודות הן במלכות, מנעולא, שה״ס מלכות דמדת הדין דצמצום א׳ שאינה ראויה לקבלת אור העליון, ומפתחא, שה״ס מלכות הממותקת בבינה, הראויה לקבל אורות עליונים, וע״כ נקראת המלכות עץ הדעת טו״ר, שאם זכה האדם, נגנזת נקודה דמנעולא, ונקודת המפתחא שולטת, ואז המלכות מקבלת אורות עליונים בשביל התחתונים. ואם לא זכה האדם, מתגלית במלכות נקודה דמנעולא, וכל האורות מסתלקים ממנה, כי נגלה שאינה ראויה לקבל שום אור. (כנ״ל ויצא דף י״ג ד״ה סתרא) וזה נבתן, שהמלכות כביכול, נטמאה, ואינה ראויה להזדווג עם ז״א, כי ז״א אינו יכול להשפיע בה אור העליון. ועוד, כי אם יתחבר בה ז״א בעת ההיא תתעורר גם בו נקודת המנעולא ויסתלקו האורות גם ממנו (ועי׳ כל זה לעיל נח אות ק״ג בהסולם)."],[4,"","וז״ש \u0003בשעתא דחויא תקיפא דלעילא אתער,\u0004 דהיינו, בעונות התחתונים, \u0003שארי ואתחבר עם נוקבא ואטיל בה זוהמא,\u0004 דהיינו שניתנה לו רשות לגלות נקודת המנעולא במלכות, שמחמתה מסתלקים ממנה כל האורות, ואינה ראויה עוד לקבל אור, שזה נבחן, \u0003שהטיל בה זוהמא.\u0004 ואז \u0003אתפרש דכורא מינה, בגין דהא אסתאבת, ואתקריאת מסאבא,\u0004 שז״א נפרש ממנה, ואינו משפיע לה אור, משום גילוי המנעולא, הנחשב כמו שנטמאה, \u0003ולא אתחזי לדכורא למקרב בהדה,\u0004 כי אם יקרב ויתחבר עמה, תתדבק גם בו בחינת המנעולא, ויסתלקו אורותיו, \u0003דווי אי אסתאב הוא בהדה בזמנא דאיהי אסתאבת,\u0004 כי אם יסתלקו גם אורות דז״א, יחרב העולם, שלא יהיה להם ממי לקבל חיותם (ועי׳ ב״א דף ז׳ ד״ה וכבר)."],[5,"ותאנא מאה ועשרין וחמש וכו׳:","ולמדנו מאה ועשרים וחמשה מיני טומאה ירדו לעולם, המתאחדים ונאחזים מצד הנחש החזק. ושבעה ועשרים הגדולים שבהם נאחזים בנוקבא, ומתדבקים בה. אוי למי שיקרב אליה בזמן ההוא, שמי שיקרב אליה, מראה פגם למעלה, כי בעון הזה מתעורר הנחש החזק למעלה, ומטיל זוהמא במקום שאינו צריך, ומתחבר בנוקבא, ושערותיו של הדכר גודלות, והנוקבא נטמאת, ושערותיה מגודלות, וצפרניה גדולות, ואז דינים מתחילים להתעורר בעולם, והכל נטמאים. ז״ש, כי את מקדש ה׳ טמא. מקדש ה׳ נטמא בעונות בני אדם. (הביאור הוא באות ת״ד)"],[6,"תאנא מאי דכתיב וכו׳:","למדנו מה שכתוב, ואיבה אשית בינך ובין האשה. כ״ד מיני טומאה הטיל הנחש בנוקבא כשנתחבו עמה, כחשבון, \u0003ואיבה,\u0004 וכ״ד מינין מתעוררים למעלה וכ״ד למטה. והשערות גדלות, והצפרנים גדולות, ואז מתעוררים דינים בעולם. ולמדנו, כשהאשה רוצה להטהר, צריכה לגזוז אותו שיעור השערות שגדלו בימים שהיתה בטומאתה, וצריכה לקצץ צפרניה וכל אותו הזוהמא שבהם."],[7,"דתאנא ברזי דמסאבותא וכו׳:","שלמדנו בסודות הטומאה, הזוהמא של הצפרנים יעוררו זוהמא אחרא דהיינו זוהמת הנחש, ומשום זה צריכים לגנוז אותן. ומי שמעבירן לגמרי, דהיינו ששורפן, הוא כאלו מעורר חסד בעולם. שלמדנו, אין האדם צריך לתת זכרון למינים הרעים. כי למדנו, אלף וארבע מאות וחמשה מינים רעים נאחזים בזוהמא ההיא שהטיל הנחש החזק, וכולם מתעוררים באותה זוהמא של הצפרנים."],[7,"","ביאור הדברים. סוד הצפרנים וזוהמתן, כבר נתבאר לעיל (ויקהל אות רע״ג ורע״ד בהסולם) וענין הזוהמא שהטיל הנחש בנוקבא, ופגם כל אורותיה, כבר נתבאר לעיל (אות ת״א) כי עם גילוי המנעולא נפגמים כל האורות דנוקבא, שהיא המלכות. כמ״ש שם. ומביא כאן ג׳ מספרים, שהם קכ״ה זיני מסאבותא (באות ת\"ב) וכ״ד זיני מסאבותא (באות ת״ג) ואלף ת״ה זינין בישין, כאן. והם כנגד ג׳ בחינות של אורות שהם בג׳ שמות של הנוקבא, דהיינו אלקים, אדני, את״ה, שהס״א יונקת ונאחזת בהם. בסו״ה זה לעומת זה עשה אלקים."],[7,"","ונודע שמן השם אלקים דקדושה עד אלהים אחרים מתפשטים ק״כ צירופי אלקים דקדושה, שאחריהם מתחילים אלהים אחרים. שה״ס ש \u0003מסכה\u0004 היא בגימטריא קכ״ה, שהם ק״ך צירופי אלקים וה׳ אותיות אלקים, שהס״א יונקת מהם. (כנ״ל כי תשא דף כ״ט ד״ה ויעשהו) גם מתבאר באפן אחר. כי ה׳ אותיות אלקים הם ה׳ ספירות כח״ב תו״מ, וב׳ התכללויות נוהגות בהם, שבהתכללות א׳, נכללות ה׳ ספירות כח״ב תו״מ זו מזו, והם כ״ה ספירות. ובהתכללות ב׳ נכללו כח״ב תו״מ בכל אחת מכ״ה ספירות, והם קכ״ה ספירות. דהיינו ה׳ מערכות של כ״ה ספירות, שהמערכה הא׳ היא מכתר. והמערכה הב׳, מחכמה. והמערכה הג', מבינה. והמערכה הד׳, מת״ת. והמערכה הה׳ ממלכות."],[7,"","וז״ש (באות ת״ב) \u0003מאה ועשרין וחמש זיני מסאבותא וכו׳ מסטרא דחויא תקיפא,\u0004 דהיינו שנאחז ויונק מה׳ מערכות הנ״ל, שבהם קכ״ה בחינות. \u0003ושבעה ועשרין רברבין מנייהו מתאחדן בנוקבי\u0004 דהיינו אותן כ״ה בחינות שבמערכה האחרונה, שהיא מבחינת מלכות, שהיא נוקבא. וגם ב׳ בחינות אחרונות ממערכה הד', שהם ת״ת ומלכות מן מלכות דת״ת. שהם ג״כ בחינת מלכות שהיא נוקבא. אמנם למעלה מזה דהיינו בבינה דמלכות שבמערכת ת״ת, אינה יכולה לינק. ומה שקורא אותן \u0003רברבין,\u0004 הוא, כי בס״א כל היותר נמוך הוא יותר גדול, ומזיק יותר. וע״כ כיון שהם כ״ז בחינות האחרונות מן קכ״ה בחינות, ע״כ הן רברבין."],[7,"","ונודע שבשם \u0003אדנ״י,\u0004 יש כ״ד צירופים. וז״ש (באות ת״ג) \u0003ארבע ועשרין זיני מסאבותא אטיל חויא בנוקבא\u0004 וכו'. שנאחז ויונק מכ״ד צירופים ההם שנסתלקו מן הנוקבא מכח זוהמת הנחש. וסוד כ״ד צירופי אדני אלו, ה״ס י״ב שבז״א, שה״ס חו״ב תו״מ שבכל אחד ג׳ קוין, שהם י״ב. וכן יש אותם י״ב במלכות דהיינו חו״ב תו״מ שלה ובכל אחד ג׳ קוין. וכשנכללים זה מזה, יש כ״ד בז״א, וכ״ד במלכות, ונמצא, כיון שהנחש נאחז בכ״ד דמלכות, נאחז ג״כ בכ״ד דז״א באותו שיעור שהוא נכלל מן המלכות. וז״ש, \u0003ועשרין וארבע זינין מתערין לעילא,\u0004 מכ״ד שבז״א. \u0003ועשרין וארבע לתתא\u0004 דהיינו מכ״ד שבמלכות."],[7,"","גם המלכות נקראת בשם \u0003אתה,\u0004 שזה מורה על שיעור המוחין שבה. כי המוחין הם חכמה ובינה, שהם ימין ושמאל. וחסד וגבורה, שהם ימין ושמאל שבדעת. והנה המלכות עיקרה היא מקו שמאל, וע״כ אין לה בשלמות רק בחינת מוחין דבינה, דהיינו חו״ב תו״מ דבינה, שהיא שמאל. וכיון שספירות הבינה הן בסוד מאות, ע״כ אומר ארבע מאות. אמנם יש לה ג״כ הארה מחכמה, שספירותיה בסוד אלף, וע״כ יש לה אלף וארבע מאות. והדעת כוללת ה׳ חסדים מימין, וה׳ גבורות משמאל. והמלכות אין לה אלא ה׳ גבורות שבשמאל בלבד. וז״ש \u0003אלף, ות' וה׳ זינין בישין\u0004 וכו'. דהיינו \u0003אלף.\u0004 מהארת החכמה. ת', חו״ב תו״מ דבינה. \u0003ה',\u0004 ה׳ גבורות דשמאל דדעת. שז״ס \u0003את״ה.\u0004 וע״כ נקראת המלכות בשם את״ה. ובעת שהנחש מטיל זוהמא, דהיינו שמגלה בחינת מנעולא הגנוזה במלכות (כנ״ל אות ת׳׳א) אז מסתלקים ממנה מוחין אלו. והנחש נאחז במקום החסרון. וע״כ יש אלף ת״ה זינין בישין."]],[[0,"","לָמַדְנוּ, כָּתוּב וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב לְגַלּוֹת עֶרְוָתָהּ. שָׁנָה רַבִּי יְהוּדָה, דּוֹר שֶׁרַבִּי שִׁמְעוֹן בַּר יוֹחַאי שָׁרוּי בְּתוֹכוֹ, כֻּלָּם צַדִּיקִים, חֲסִידִים, כֻּלָּם הֵם יִרְאֵי חֵטְא, וּשְׁכִינָה שׁוֹרָה בֵינֵיהֶם, מַה שֶּׁאֵין כֵּן בְּדוֹרוֹת אֲחֵרִים. מִשּׁוּם כָּךְ הַדְּבָרִים הַלָּלוּ מִתְפָּרְשִׁים וְלֹא נִטְמָנִים. בְּדוֹרוֹת אֲחֵרִים לֹא כֵן, וּדְבָרִים שֶׁל סוֹדוֹת עֶלְיוֹנִים לֹא יְכוֹלִים לְגַלּוֹת, וְאוֹתָם שֶׁיּוֹדְעִים פּוֹחֲדִים. שֶׁכַּאֲשֶׁר הָיָה רַבִּי שִׁמְעוֹן אוֹמֵר סוֹד הַפָּסוּק הַזֶּה, עֵינֵי כָּל הַחֲבֵרִים נָבְעוּ דְמָעוֹת, וְכָל הַדְּבָרִים שֶׁאָמַר הָיוּ בְעֵינֵיהֶם גְּלוּיִים, כְּמוֹ שֶׁכָּתוּב (במדבר יב) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ וּמַרְאֶה וְלֹא בְחִידת."],[1,"","שֶׁיּוֹם אֶחָד שָׁאַל רַבִּי יֵיסָא, אָמַר, בֵּיצָה שֶׁל אֱמֶת (מדה) שֶׁיָּצְאָה מֵעוֹף שֶׁשָּׁרוּי (שנזרק) בְּאוּר, וְהִתְבַּקְּעָה לְאַרְבָּעָה צְדָדִים, שְׁנַיִם עוֹלִים מֵהֶם, וְאֶחָד מִתְנַמֵּךְ, וְאֶחָד רוֹבֵץ בְּמִרְבָּץ (מבועי המעין) שֶׁל הַיָּם הַגָּדוֹל. אָמַר רַבִּי אַבָּא, עָשִׂיתָ לִפְנֵי רַבִּי שִׁמְעוֹן קֹדֶשׁ חֹל, שֶׁהֲרֵי כָּתוּב פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ. אָמַר לוֹ רַבִּי שִׁמְעוֹן, טֶרֶם שֶׁתִּתְבַּקַּע הַבֵּיצָה, תִּסְתַּלֵּק מִן הָעוֹלָם. וְכָךְ הָיָה בָּאִדְּרָא שֶׁל רַבִּי שִׁמְעוֹן."],[2,"","לָמַדְנוּ, בִּימֵי רַבִּי שִׁמְעון הָיָה אומֵר אָדָם לַחֲבֵרוֹ: פְּתַח פִּיךְ וְיָאִירוּ דְבָרֶיךְ. אַחַר שֶׁנִּפְטַר רַבִּי שִׁמְעוֹן, הָיוּ אוֹמְרִים: (קהלת ה) אַל תִּתֵּן אֶת פִּיךְ לַחֲטִיא אֶת בְּשָׂרֶךְ."],[3,"","לָמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, אִם בְּנֵי הָעוֹלָם מִסְתַּכְּלִים בְּמַה שֶּׁכָּתוּב בַּתּוֹרָה, לֹא יָבוֹאוּ לְהַרְגִּיז לִפְנֵי רִבּוֹנָם. לָמַדְנוּ, כְּשֶׁמִּתְעוֹרְרִים הַדִּינִים הַקָּשִׁים לָרֶדֶת לָעוֹלָם, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ וְגוֹ'. כָּאן כָּתוּב (תהלים כה) סוֹד ה' לִירֵאָיו, וּבָאִדְּרָא (ובדור הזה) הַקְּדוֹשָׁה נֶאֱמַר, כָּאן הִצְטָרַכְנוּ לְגַלּוֹת, שֶׁהֲרֵי לַמָּקוֹם הַזֶּה הִסְתַּלֵּק."],[4,"","שֶׁשָּׁנִינוּ, בְּשָׁעָה שֶׁהַנָּחָשׁ הַתַּקִּיף שֶׁל מַעְלָה הִתְעוֹרֵר בִּשְׁבִיל חֲטָאֵי בְּנֵי הָאָדָם, הִתְחִיל לְהִתְחַבֵּר עִם נְקֵבָה וְהִטִּיל בָּהּ זֻהֲמָה, נִפְרָד מִמֶּנָּה הַזָּכָר, מִשּׁוּם שֶׁהֲרֵי נִטְמְאָה וְנִקְרֵאת טְמֵאָה, וְאֵין רָאוּי לַזָּכָר לִקְרַב אֵלֶיהָ. שֶׁאוֹי אִם הוּא נִטְמָא עִמָּהּ בִּזְמַן שֶׁהִיא טְמֵאָה."],[5,"","וְלָמַדְנוּ, מֵאָה עֶשְׂרִים וַחֲמִשָּׁה מִינֵי טֻמְאָה יָרְדוּ לָעוֹלָם שֶׁאֲחוּזִים מִצִּדּוֹ שֶׁל הַנָּחָשׁ הֶחָזָק, וְשִׁבְעָה וְעֶשְׂרִים גְּדוֹלִים מֵהֶם נֶאֱחָזִים בַּנְּקֵבוֹת וְנִדְבָּקִים בָּהֶם. אוֹי לְמִי שֶׁיִּקְרַב אֵלֶיהָ בְּאוֹתוֹ זְמַן, שֶׁמִּי שֶׁיִּקְרַב עִמָּהּ, מַרְאֶה פְגָם לְמַעְלָה, שֶׁהֲרֵי בַּחֵטְא הַזֶּה מִתְעוֹרֵר הַנָּחָשׁ הַקָּשֶׁה לְמַעְלָה וּמַטִּיל זֻהֲמָה בְּמָקוֹם שֶׁלֹּא צָרִיךְ, וּמִתְחַבֵּר עִם הַנְּקֵבָה, וּגְדֵלוֹת שַׂעֲרוֹתָיו שֶׁל הַזָּכָר, וְהַנְּקֵבָה נִטְמֵאת, וּשְׂעָרָהּ גָּדוֹל וְצִפָּרְנֶיהָ גְּדוֹלוֹת, וְאָז הַדִּינִים שׁוֹרִים לְהִתְעוֹרֵר בָּעוֹלָם וְנִטְמָאִים הַכֹּל. זֶהוּ שֶׁכָּתוּב (במדבריט) כִּי אֶת מִקְדַּשׁ ה' טִמֵּא, מִקְדַּשׁ ה' נִטְמָא בַּחֲטָאֵי בְּנֵי הָאָדָם."],[6,"","לָמַדְנוּ, מַה שֶּׁכָּתוּב (בראשית ג) וְאֵיבָה אָשִׁית בֵּינְךְ וּבֵין הָאִשָּׁה, אַרְבָּעָה וְעֶשְׂרִים מִינֵי טֻמְאָה הִטִּיל הַנָּחָשׁ בַּנְּקֵבָה כְּשֶׁהִתְחַבֵּר עִמָּהּ, כְּחֶשְׁבּוֹן וְאֵיבָה, וְעֶשְׂרִים וְאַרְבָּעָה מִינִים (דינים) מִתְעוֹרְרִים לְמַעְלָה, וְעֶשְׂרִים וְאַרְבָּעָה לְמַטָּה. וְשֵׂעָר גָּדוֹל וְצִפָּרְנַיִם גְּדוֹלוֹת, וְאָז מִתְעוֹרְרִים הַדִּינִים בַּכֹּל. וְלָמַדְנוּ, כְּשֶׁרוֹצָה אִשָּׁה לְהִטָּהֵר, צְרִיכָה לְסַפֵּר אוֹתוֹ שֵׂעָר שֶׁגָּדַל בַּיּוֹם שֶׁהִיא טְמֵאָה, וּלְסַפֵּר אֶת צִפָּרְנֶיהָ, וְכָל אוֹתָהּ זֻהֲמָה שֶׁבָּהֶן."],[7,"","שֶׁלָּמַדְנוּ בְּסוֹדוֹת הַטֻּמְאָה, שֶׁזֻּהֲמַת הַצִּפָּרְנַיִם מְעוֹרֶרֶת זֻהֲמָה אַחֶרֶת, וּמִשּׁוּם כָּךְ צְרִיכִים גְּנִיזָה, וּמִי שֶׁמַּעֲבִירָם לְגַמְרֵי, כְּאִלּוּ הֵעִיר חֶסֶד בָּעוֹלָם. שֶׁלָּמַדְנוּ, אֵין צָרִיךְ אָדָם לָתֵת זֵכֶר לְמִינִים רָעִים. שֶׁשָּׁנִינוּ, אֶלֶף וְאַרְבַּע מֵאוֹת וַחֲמִשָּׁה מִינִים רָעִים נֶאֱחָזִים בְּאוֹתָהּ הַזֻּהֲמָה שֶׁהִטִּיל הַנָּחָשׁ הֶחָזָק, וְכֻלָּם מִתְעוֹרְרִים בְּאוֹתָהּ זֻהֲמַת הַצִּפָּרְנַיִם."]]],[["וַאֲפִילּוּ מַאן דְּבָעֵי, יַעְבִיד בְּהוּ חַרְשִׁין לִבְנֵי נָשָׁא, מִשּׁוּם אִינּוּן דְּתַּלְיָין בְּהוּ, וּמַאן דְּאַעְבָּר לוֹן, כְּאִלּוּ אַסְגֵּי חֶסֶד בְּעָלְמָא, וְדִינִין בִּישִׁין לָא מִשְׁתַּכְּחִין. וְיַּעְבַּר הַהוּא זוּהֲמָא וְטוּפְרָהָא דְּרָשִׁים בֵּיהּ. דְּתַנְיָא, מַאן דְּדָרִיךְ בְּרַגְלֵיהּ, אוֹ בִּמְסָאנֵיהּ עָלַיְיהוּ, יָכִיל לְאִתְזְקָא. וּמַה בְּהַאי שִׁיּוּרֵי דְּשִׁיּוּרֵי דְּזוּהֲמָא דִּלְעֵילָּא כַּךְ, אִתְּתָא דִּמְקַבְּלָא וְאִתְחֲבָּרַת בְּחִוְיָא, וְאָטִיל בָּהּ זוּהֲמָא, עַל אַחַת כַּמָּה וְכַמָּה. וַוי לְעָלְמָא דִּמְקַבְּלָא מִינָּהּ מֵהַהוּא זוּהֲמָא, בְּגִינֵי כַּךְ וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִּקְרַב.","אָמַר רִבִּי שִׁמְעוֹן, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, הָבִיאוּ עָלַי כַּפָּרָה בְּרֹאשׁ חֹדֶשׁ. עָלַי וַדַּאי, בְּגִין דְּיִתְעַבָּר הַהוּא חִוְיָא, וְיִתְבָּסַם מַאן דְּבַעְיָא. עָלַי: כְּמָה דִּכְתִּיב, (ישעיהו ו׳:ב׳) שְׂרָפִים עוֹמְדִים מִמַּעַל לוֹ. וְעַל דָּא כְּתִיב בְּקֹרַח, (במדבר טז) הַנּוֹעָדִים עַל יְיָ', דִּבְגִינֵיהוֹן אִתְעַר מַאן דְּאִתְעַר דְּאַתֵי מִסִטְרַיְיהוּ. אוּף הָכָא הָבִיאוּ עָלַי כַּפָרָה, עָלַי מַמָשׁ. בְּגִין דְּיִתְבְּסַם וְיִתְעֲבָר וְלָא אִשְׁתְּכַח חִוְיָא בַּאֲתַר דְּשָׁארֵי. וְכָּל כַּךְ לָמָּה. עַל שֶׁמִּעַטְתִּי אֶת הַיָּרֵחַ, וְשַׁלְטָא בָּהּ מַאן דְּלָא אִצְטְרִיךְ. וּבְגִין כָּךְ כְּתִיב וְאֶל אִשָּׁה בְּנִדַּת טוּמְאָתָהּ לֹא תִקְרַב.","זַכָּאָה דָּרָא, דְּרַבִּי שִׁמְעוֹן בֶּן יוֹחָאי שָׁארֵי בְּגַוִּיהּ. זַכָּאָה עַדְבֵיהּ בֵּין עִלָּאִין וְתַתָּאִין. עָלֵיהּ כְּתִיב, (קהלת י׳:י״ז) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִין. מַהוּ בֶּן חוֹרִין. דְּזָקִיף רֵישָׁא לְגַלָּאָה, וּלְפָרְשָׁא מִלִּין וְלָא דָּחִיל. כְּהַאי דְּאִיהוּ בֶּן חוֹרִין, וְיֵימָּא מַאי דְּבַעְיָא וְלָא דָּחִיל. מַהוּ מַלְכֵּךְ. דָּא הוּא רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, מָארֵיהּ דְּאוֹרַיְיתָא, מָארֵיהּ דְּחָכְמְתָא. דְּכַד הֲוָה רִבִּי אַבָּא וְחַבְרַיָּיא חָמָאן לְרִבִּי שִׁמְעוֹן, הֲווֹ רַהֲטֵי אֲבַתְרֵיהּ, וְאַמְרֵי, (הושע י) אַחֲרֵי יְיָ' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג.","אָמַר רִבִּי שִׁמְעוֹן, כְּתִיב (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתוֹ, אֲמַאי שָׁקִיל דָּא בְּדָא. אֶלָּא כֹּלָּא בְּחַד דַּרְגָּא סְלִיקוּ, דָּא אִזְדְּוַּוג בְּדָא. וְחֶדְוָותָא דְּדָא בְּדָא לָא אִשְׁתְּכַח, אֶלָּא כַּד אִתְגְּלֵי עַתִּיקָא קַדִּישָׁא, וּכְדֵין חֶדְוָותָא דְּכֹלָּא. וְתָנֵינָן, כְּתִיב (תהילים צ״ב:א׳) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, לְיוֹם הַשַׁבָּת מַמָּשׁ. שְׁבָחָא דְּקָא מְשַׁבָּח קוּדְשָׁא בְּרִיךְ הוּא. כְּדֵין חֶדָוָותָא אִשְׁתְּכַח, וְנִשְׁמְתָא אִתּוֹסֶפֶת. דְּהָא עַתִּיקָא אִתְגְּלֵי וְזִוּוּגָא יִזְדָּמַן.","אוּף הָכִי בְּחַדְתּוּתֵי סִיהֲרָא, דְּהָא נָהִיר לָהּ שִׁמְשָׁא בְּחֶדְוָותָא דִּנְהִירוּ דְעַתִּיקָא לְעֵילָּא. בְּגִינֵי כַּךְ הַאי קָרְבְּנָא הוּא לְעֵילָּא, בְּגִין דְּיִתְבְּסַם כֹּלָּא, וְיִשְׁתְּכַּח חֶדְוָותָא בְּעָלְמָא, וְעַל דָּא הָבִיאוּ עָלַי כַּפָּרָה, דַּיְיקָא מִלָּה.","תָּאנָא, כְּתִיב (במדבר כ״ח:י׳) עוֹלַת שַׁבַּת בְּשַׁבַּתוֹ עַל עוֹלַת הַתָּמִיד, דְּבָעֵי לְכַוְּונָא לִבָּא לְעֵילָּא לְעֵילָּא, יַתִּיר מִשְּׁאַר יוֹמִין. וְעַל דָּא עַל עוֹלַת הַתָּמִיד דַּיְיקָא. תַּנְיָא, כְּתִיב בְּחַנָּה (שמואל א א) וַתִּתְפַּלֵּל עַל יְיָ', עַל דַּיְיקָא, בְּגִין דִּבְנִין בְּמַזָּלָא קַדִּישָׁא תַּלְיָין, כְּמָה דְּאוֹקִימְנָא וְלֵית לָךְ מִלָּה בְּאוֹרַיְיתָא, אוֹ אָת זְעֵירָא בְּאוֹרַיְיתָא. דְּלָא רְמִיזָא בְּחָכְמְתָא עִלָּאָה, וְתַלְיָין מִנֵּיהּ תִּלֵי תָּלִין רָזִין דְּחָכְמְתָא עִלָּאָה, הֲדָא הוּא דִכְתִיב, (שיר השירים ה׳:י״א) קְווּצּוֹתָיו תַּלְתַּלִּים, וְהָא אִתְּמַר.","רִבִּי יוֹסֵי אַשְׁכָּחֵיהּ לְרִבִּי אַבָּא, דְּהֲוָה יָתִיב וְקָארִי, הַאי קְרָא דִּכְתִּיב, (תהילים נ״ה:כ״ג) הַשְׁלֵךְ עַל יְיָ' יְהָבְךָ, עַל דַּיְיקָא, דְּהָא מְזוֹנֵי בְּמַזָּלָא תַּלְיָין. רִבִּי יְהוּדָה הֲוָה קָארֵי, (תהילים ל״ב:ו׳) עַל זֹאת יִתְפַּלֵּל כָּל חָסִיד אֵלֶיךָ לְעֵת מְצֹא. עַל זֹאת וַדַּאי. לְעֵת מְצֹא, הָא אוֹקִימְנָא. אֲבָל לְעֵת מְצֹא, כְּמָה דִּכְתִּיב, (ישעיהו נ״ה:ו׳) דִּרְשׁוּ יְיָ' בְּהִמָצְאוֹ קְרָאוּהוּ בִּהְיוֹתוֹ קָרוֹב. דָּבָר אַחֵר לְעֵת מְצֹא, בְּשַׁעֲתָא דְּנַהֲרִין נַגְדִּין וְאִתְמַשְׁכָאן, וּמִסְתַּפְּקֵי אֲבָהָן, וּמִתְבַּרְכָאן כֹּלָא. רַק לְשֵׁטֶף מַים רַבִּים, מַאן שֵׁטֶף מַים רַבִּים, דָּא עַמִיקָא דְּמַבּוּעִין וְנַהֲרִין, דְּמַאן יִזְכֶּה לֵיהּ, וּמַאן יִזְכֶּה לְקָרְבָא וּלְסַלְּקָא תַּמָּן. הֲדָא הוּא דִכְתִיב בֵּיהּ, (תהילים ל״ב:ו׳) רַק לְשֵׁטֶף מַיִם רַבִּים אֵלָיו לֹא יַגִּיעוֹ דְּהָא לָא זַכָּאָן, וְלָא יַכְלִין.","רִבִּי יִצְחָק אָמַר, כְּתִיב (תהילים כ״ז:ד׳) אַחַת שָׁאַלְתִּי מֵאֵת יְיָ' אוֹתָהּ אֲבַקֵּשׁ וְגוֹ'. זַכָּאִין אִינּוּן צַדִּיקַיָּיא, דְּכַמָּה גְּנִיזִין עִלָּאִין טְמִירִין לְהוּ בְּהַהוּא עָלְמָא, דְּקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתַּעֲשֵׁעַ בְּהוּ בְּאִינוּן עָלְמִין, כְּמָה דְּאוֹקִימְנָא בְּנֹעַם יְיָ', וְהָא אִתְּמַר. רִבִּי חִזְקִיָּה אָמַר מֵהָכָא, (ישעיהו ס״ד:ג׳) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךָ יַעֲשֶׂה לִמְחַכֵּה לוֹ. יַעֲשֶׂה, תַּעֲשֶׂה מִבָּעֵי לֵיהּ. אֶלָּא יַעֲשֶׂה וַדַּאי, הַיְינוּ (ישעיהו ל״ח:ה׳) יוֹסִיף עַל יָמֶיךָ חֲמֵשׁ עֶשְׂרֵה שָׁנָה. וְהַיְינוּ הַשְׁלֵךְ עַל ה' יְהָבְךָ. וּכְתִיב וַתִּתְפַּלֵּל עַל יְיָ'. וְכֹלָּא חַד."],[[0,"ואפילו מאן דבעי וכו׳:","ואפילו מי שרוצה, יכול לעשות בהן כשפים לבני אדם, משום אלו המזיקים התלוים בהן, ומי שמעביר אותן, דהיינו ששורפן, הוא כאלו מרבה חסד בעולם, ודינים רעים אינם נמצאים, ותתבטל הזוהמא ההיא, וצפרניה הרשומות בה. בזוהמא. שלמדנו, מי שדורך ברגליו או במנעליו על הצפרנים, יכול להנזק. ומה בשירים אלו של שיורי זוהמא שלמעלה, כך, האשה שקבלה ונתחברה בנחש, והטיל בה זוהמא, על אחת כמה וכמה. אוי לעולם המקבל ממנה, בשעה זו, שמקבל מהזוהמא ההיא. משום כך, ואל אשה בנדת טומאתה לא תקרב. דהיינו שלא לקבל מן המלכות בשעה שהנחש מתחבר בה בעון התחתונים, ומטיל בה זוהמא (כנ״ל אות ת\"א)."],[1,"אמר רבי שמעון וכו׳:","אר״ש, אמר הקב״ה, הביאו עלי כפרה בראש חדש, על שמיעטתי את הירח שהיא המלכות (כנ\"ל בראשית א׳ אות קי״ג) \u0003עלי\u0004 ודאי, דהיינו למעני. כדי להעביר הנחש מיניקת המלכות ויתבשם מי שצריך, דהיינו המלכות. \u0003עלי\u0004 פירושו כמו שרפים עומדים ממעל לו, שאין פירושו למעלה ממנו, ח״ו, אלא למענו, ולכבודו. אף עלי, פירושו למעני. וע״כ כתוב בקרח, הנועדים על ה׳, שפירושו ג״כ בשביל ה׳, דהיינו שבשבילם, מחמת החטא של קרח ועדתו, נתעורר מי שמתעורר, הבא מצדם, שהוא הס״א לפגום בה׳ אף כאן, הביאו עלי כפרה, עלי ממש, דהיינו למעני בשבילי, כדי שהמלכות תתבשם, והנחש יהיה נעבר ממנה, ולא יהיה נמצא במקום ששורה. דהיינו במקום החסרון של מיעוט הירח. וכל כך למה, בשביל שמיעטתי את הירח, שהוא המלכות, ושולט בה מי שאינו צריך. ומשום זה, ואל אשה בנדת טומאתה לא תקרב. כנ״ל בדבור הסמוך."],[2,"זכאה דרא דר״ש וכו׳:","אשרי הדור שר׳ שמעון בן יוחאי שורה בו. אשרי חלקו בין עליונים ותחתונים. עליו כתוב, אשריך ארץ שמלכך בן חורין. מהו בן חורין. היינו, שזוקף ראשו לגלות ולבאר דברים ואינו מפחד, כמי שהוא בן חורין ואומר מה שרוצה, ואינו מפחד. מי הוא \u0003מלכך.\u0004 זה הוא ר״ש בן יוחאי, בעל התורה, בעל החכמה. כי כשהיו ר׳ אבא והחברים רואים את ר׳ שמעון, היו רצים אחריו, ואומרים, אחרי ה׳ ילכו כאריה ישאג."],[3,"אמר ר׳ שמעון וכו׳:","אר״ש, כתוב, והיה מדי חדש בחדשו ומדי שבת בשבתו. שואל, למה שקול זה בזה, כלומר למה שניהם שקולים יחד בכתוב. ומשיב, אלא הכל במדרגה אחת עולה, זה מזדווג בזה, יום השבת שהוא ז״א מזדווג בחדש, שהוא מלכות. ושמחה של זה בזה אינו נמצא, דהיינו שאינם מזדווגים, אלא כשנגלה עליהם עתיקא קדישא, שהוא הכתר, ואז הוא שמחת הכל. ולמדנו, כתוב, מזמור שיר ליום השבת, ליום השבת ממש, דהיינו ז\"א, שה״ס יום השבת. שהוא שבח שהקב״ה משבח. אז נמצאת שמחה, ונתוספת נשמה, כי עתיקא נתגלה, והזווג דז״א ומלכות מזדמן."],[4,"אוף הכי בחדתותי וכו׳:","אף כך הוא בחידוש הלבנה, דהיינו בראש חדש, שהשמש, שהוא ז״א, מאיר לה בשמחת אור עתיקא למעלה, משום זה, קרבן זה של ר״ח, הוא למעלה, כדי שהכל יתבשם, ותמצא שמחה בעולם. וע״כ הביאו עלי כפרה. הדבר הוא בדיוק. כדי לעורר הזווג."],[5,"תאנא, כתיב עולת וכו':","למדנו, כתוב עולת שבת בשבתו על עולת התמיד. היינו שצריך לכוון לבו למעלה למעלה יותר מבשאר הימים. וע״כ \u0003על\u0004 עולת התמיד הוא בדיוק, כי \u0003על\u0004 פירושו למעלה מתמיד. שלמדנו, כתוב בחנה, ותתפלל \u0003על\u0004 ה', על, הוא בדיוק, שפירושו למעלה מה', שהוא ז״א, משום שבנים תלוים במזל הקדוש, שהוא דיקנא דא״א, כמו שהעמדנו. (לעיל ב״א אות ק״י) שהוא למעלה מז״א. ואין לך דבר בתורה או אות קטנה שבתורה, שאינה רמוזה בחכמה עליונה, ותלוים ממנה תלי תלים סודות של חכמה עליונה, ז״ש קווצותיו תלתלים. וכבר למדנו."],[6,"ר' יוסי אשכחיה וכו׳:","רבי יוסי מצא את ר׳ אבא שהיה יושב וקורא מקרא זה, שכתוב, השלך \u0003על\u0004 ה׳ יהבך. \u0003על,\u0004 הוא מדויק. דהיינו למעלה מה׳, שהוא ז\"א, כי מזון תלוי במזל. שהוא דיקנא דא״א. ר׳ יהודה היה קורא, \u0003על\u0004 זאת יתפלל כל חסיד אליך לעת מצא. \u0003על\u0004 זאת ודאי, דהיינו למעלה ממלכות הנקראת זאת, שהוא ת״ת שהוא למעלה ממלכות. \u0003לעת מצוא,\u0004 הרי העמדנו שהוא אשה (ברכות ח.) אבל לעת מצא הוא כמ״ש, דרשו ה׳ בהמצאו קראוהו בהיותו קרוב. דהיינו בעשרת ימי תשובה. פירוש אחר, \u0003לעת מצא,\u0004 היינו בשעה שהנהרות, שהם אורות הבינה, נוזלים ונמשכים, והאבות, שהם חג״ת, מקבלים, והכל מתברכים. שע״ז יתפלל כל חסיד. \u0003רק לשטף מים רבים.\u0004 מהו, שטף מים רבים. ומשיב, זה הוא עומק המבועים והנהרות, שהוא עתיקא קדישא, שמשם נמשכים האורות והמבועים לבינה. שמי יזכה לו ומי יזכה לקרב ולעלות שם. זהו שכתוב בו, רק לשטף מים רבים אליו לא יגיעו. כי אינם זוכים ואינם יכולים. לקבל מעתיקא."],[7,"ר׳ יצחק אמר וכו׳:","רי״א, כתוב אחת שאלתי מאת ה׳ אותה אבקש וגו׳ לחזות בנועם ה'. אשרי הם הצדיקים שכמה אוצרות עליונים צפונים להם בעולם ההוא, שהוא בינה, שהקב״ה משתעשע בהם באלו העולמות, כמו שהעמדנו, שעליהם בקש, לחזות בנועם ה׳. וכבר למדנו, דהיינו הארת עתיקא הנמשכת בבינה. ור׳ יצחק חולק על ר׳ יהודה, שאמר אשר, רק לשטף מים רבים אליו לא יגיעו, מורה על אורות דעתיקא, שאי אפשר להשיג. אלא שיש צדיקים שזוכים גם לזה. רבי חזקיה אמר, מכאן נשמע, שיש צדיקים שזוכים לאור עתיקא, שכתוב, עין לא ראתה אלקים זולתך יעשה למחכה לו שואל, יעשה, תעשה היה צריך לומר כיון שכתוב \u0003זולתך\u0004 לשון נוכח. ומשיב, אלא \u0003יעשה\u0004 ודאי, דהיינו שרומו על עתיקא, ע״כ מדבר בלשון נסתר, יעשה. והיינו הנני יוסיף על ימיך חמש עשרה שנה, שהיה צריך לומר אוסיף, כיון שאומר הנני, אלא שרומז על עתיקא, ע״כ מדבר בלשון נסתר הנני יוסיף. והוא מטעם שחיים נמשכים ממזל, דהיינו מדיקנא דעתיקא. והיינו השלך על ה׳ יהבך. שפירושו, למעלה מה׳, שהוא מזל. להיותו תפלה על מזונות כנ״ל. וכתוב, ותתפלל על ה׳. שהוא ג״כ מזל, שהוא למעלה מה׳, להיותה תפלה על בנים, והכל אחד, שמושכים ממזלא שהיא דיקנא דעתיקא קדישא. הרי שיכולים לקבל ולמשוך שפע גם מעתיקא קדישא, דלא כרבי יהודה."]],[[0,"","וַאֲפִלּוּ מִי שֶׁרוֹצֶה, יַעֲשֶׂה בָהֶם כְּשָׁפִים לִבְנֵי אָדָם, מִשּׁוּם אוֹתָם שֶׁתְּלוּיִים בָּהֶם. וּמִי שֶׁמַּעֲבִירָם, כְּאִלּוּ הִרְבָּה חֶסֶד בָּעוֹלָם, וְדִינִים רָעִים לֹא נִמְצָאִים, וְתַעֲבֹר אוֹתָהּ זֻהֲמָה וְצִפָּרְנֶיהָ שֶׁרְשׁוּמוֹת בָּהּ. שֶׁלָּמַדְנוּ, מִי שֶׁדּוֹרֵךְ בְּרַגְלוֹ אוֹ בְּנַעֲלוֹ עֲלֵיהֶן, יָכוֹל לְהִנָּזֵק. וּמַה בְּשִׁיּוּרֵי הַשִּׁירַיִם שֶׁל הַזֻּהֲמָה שֶׁלְּמַעְלָה כָּךְ - אִשָּׁה שֶׁמְּקַבֶּלֶת וּמִתְחַבֶּרֶת עִם הַנָּחָשׁ וְהִטִּיל בָּהּ זֻהֲמָה עַל אַחַת כַּמָּה וְכַמָּה. אוֹי לָעוֹלָם שֶׁמְּקַבֵּל מִמֶּנָּה אוֹתָהּ זֻהֲמָה. מִשּׁוּם כָּךְ, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב."],[1,"","אָמַר רַבִּי שִׁמְעוֹן, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא: הָבִיאוּ עָלַי כַּפָּרָה בְּרֹאשׁ חֹדֶשׁ. עָלַי וַדַּאי, כְּדֵי שֶׁיָּעֳבַר אוֹתוֹ הַנָּחָשׁ וְיִתְבַּשֵּׂם מִי שֶׁצָּרִיךְ. עָלַי, כְּמוֹ שֶׁכָּתוּב (ישעיה ו) שְׂרָפִים עֹמְדִים מִמַּעַל לוֹ. וְעַל זֶה כָּתוּב בְּקֹרַח, (במדבר טז) הַנֹּעָדִים עַל ה', שֶׁבִּגְלָלָם מִתְעוֹרֵר מִי שֶׁמִּתְעוֹרֵר שֶׁבָּא מִצִּדָּם. אַף כָּאן הָבִיאוּ עָלַי כַּפָּרָה, עָלַי מַמָּשׁ, כְּדֵי שֶׁיִּתְבַּשֵּׂם וְיָעֳבַר וְלֹא יִמָּצֵא הַנָּחָשׁ בְּמָקוֹם שֶׁשּׁוֹרֶה. וְכָל כָּךְ לָמָּה? עַל שֶׁמִּעַטְתִּי אֶת הַיָּרֵחַ וְשׁוֹלֵט בָּהּ מִי שֶׁלֹּא צָרִיךְ. וּמִשּׁוּם כָּךְ כָּתוּב, וְאֶל אִשָּׁה בְּנִדַּת טֻמְאָתָהּ לֹא תִקְרַב."],[2,"","אַשְׁרֵי הַדּוֹר שֶׁרַבִּי שִׁמְעוֹן בֶּן יוֹחַאי שָׁרוּי בְּתוֹכוֹ. אַשְׁרֵי גּוֹרָלוֹ בֵּין עֶלְיוֹנִים וְתַחְתּוֹנִים. עָלָיו כָּתוּב (קהלת י) אַשְׁרֵיךְ אֶרֶץ שֶׁמַּלְכֵּךְ בֶּן חוֹרִים. מַהוּ בֶּן חוֹרִים? שֶׁזּוֹקֵף רֹאשׁ לְגַלּוֹת וּלְפָרֵשׁ דְּבָרִים וְאֵינוֹ פּוֹחֵד. כָּזֶה שֶׁהוּא בֶּן חוֹרִין, וְיֹאמַר מַה שֶּׁהוּא רוֹצֶה וְלֹא פוֹחֵד. מִי זֶה מַלְכֵּךְ? זֶה הוּא רַבִּי שִׁמְעוֹן בֶּן יוֹחַאי, בַּעַל הַתּוֹרָה, בַּעַל הַחָכְמָה. שֶׁכְּשֶׁהָיָה רַבִּי אַבָּא וְהַחֲבֵרִים רוֹאִים אֶת רַבִּי שִׁמְעוֹן, הָיוּ רָצִים אַחֲרָיו וְאוֹמְרִים: (הושע יא) אַחֲרֵי ה' יֵלְכוּ כְּאַרְיֵה יִשְׁאָג."],[3,"","אָמַר רַבִּי שִׁמְעוֹן, כָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ. לָמָּה שָׁקוּל זֶה בָּזֶה? אֶלָּא הַכֹּל בְּדַרְגָּה אַחַת עוֹלֶה. זֶה מִזְדַּוֵּג עִם זֶה, וְשִׂמְחָה שֶׁל זֶה עִם זֶה לֹא נִמְצֵאת, אֶלָּא כְּשֶׁמִּתְגַּלֶּה הָעַתִּיק הַקָּדוֹשׁ, אָז זוֹהִי חֶדְוַת הַכֹּל. וְשָׁנִינוּ, כָּתוּב (תהלים צב) מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת, לְיוֹם הַשַּׁבָּת מַמָּשׁ. הַשֶּׁבַח שֶׁמְּשַׁבֵּחַ הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲזַי נִמְצֵאת שִׂמְחָה, וּנְשָׁמָה מִתּוֹסֶפֶת. שֶׁהֲרֵי הָעַתִּיק הִתְגַּלָּה, וְהַזִּוּוּג יִזְדַּמֵּן."],[4,"","אַף כָּךְ בְּחִדּוּשׁ הַלְּבָנָה, שֶׁהֲרֵי מֵאִיר הַשֶּׁמֶשׁ בְּשִׂמְחַת הָאוֹר שֶׁל הָעַתִּיק לְמַעְלָה. מִשּׁוּם כָּךְ הַקָּרְבָּן הַזֶּה הוּא לְמַעְלָה, כְּדֵי שֶׁהַכֹּל יִתְבַּשֵּׂם וְתִמָּצֵא שִׂמְחָה בָּעוֹלָם, וְעַל כֵּן הָבִיאוּ עָלַי כַּפָּרָה, דָּבָר מְדֻיָּק."],[5,"","לָמַדְנוּ, כָּתוּב (במדבר כח) עֹלַת שַׁבַּת בְּשַׁבַּתּוֹ עַל עֹלַת הַתָּמִיד, שֶׁצָּרִיךְ לְכַוֵּן אֶת הַלֵּב לְמַעְלָה לְמַעְלָה יוֹתֵר מִבִּשְׁאָר הַיָּמִים. וְעַל זֶה עַל עֹלַת הַתָּמִיד דַּוְקָא. לָמַדְנוּ, כָּתוּב בְּחַנָּה (שמואל א א) וַתִּתְפַּלֵּל חַנָּה עַל ה', עַל דַּוְקָא, מִשּׁוּם שֶׁהַבָּנִים תְּלוּיִים בַּמַּזָּל הַקָּדוֹשׁ, כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵין לְךְ דָּבָר בַּתּוֹרָה אוֹ אוֹת קְטַנָּה בַּתוֹרָה שֶׁלֹּא רְמוּזָה בַּחָכְמָה הָעֶלְיוֹנָה, וּתְלוּיִים מִמֶּנָּה תִּלֵּי תִלִּים שֶׁל סוֹדוֹת הַחָכְמָה הָעֶלְיוֹנָה. זֶהוּ שֶׁכָּתוּב (שיר ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים, וַהֲרֵי נִתְבָּאֵר."],[6,"","רַבִּי יוֹסֵי מָצָא אֶת רַבִּי אַבָּא שֶׁהָיָה יוֹשֵׁב וְקוֹרֵא אֶת הַפָּסוּק שֶׁכָּתוּב, (תהלים נה) הַשְׁלֵךְ עַל ה' יְהָבְךְ, עַל דַּוְקָא. שֶׁהֲרֵי מְזוֹנוֹת תְּלוּיִים בְּמַזָּל. רַבִּי יְהוּדָה הָיָה קוֹרֵא, (שם לב) על זאת יתפלל כל חסיד אליך לְעֵת מְצֹא. עַל זֹּאת וַדַּאי. לְעֵת מְצֹא, הֲרֵי בֵּאַרְנוּ. אֲבָל לְעֵת מְצֹא, כְּמוֹ שֶׁכָּתוּב (ישעיה נה) דִּרְשׁוּ ה' בְּהִמָּצְאוֹ קְרָאֻהוּ בִּהְיוֹתוֹ קָרוֹב. דָּבָר אַחֵר לְעֵת מְצֹא - בְּשָׁעָה שֶׁנְּהָרוֹת שׁוֹפְעִים וְנִמְשָׁכִים, וְהָאָבוֹת נֶהֱנִים, וְהַכֹּל מִתְבָּרְכִים. רַק לְשֵׁטֶף מַיִם רַבִּים, מִי זֶה הַשֵּׁטֶף מַיִם רַבִּים? זֶהוּ עֹמֶק הַנְּחָלִים וְהַנְּהָרוֹת, שֶׁמִּי יִזְכֶּה לוֹ וּמִי יִזְכֶּה לְהִתְקָרֵב וְלַעֲלוֹת לְשָׁם. זֶהוּ שֶׁכָּתוּב בּוֹ, (תהלים לה) רַק לְשֵׁטֶף מַיִם רַבִּים אֵלָיו לֹא יַגִּיעוּ, שֶׁהֲרֵי לֹא זוֹכִים וְלֹא יְכוֹלִים."],[7,"","רַבִּי יִצְחָק אָמַר, כָּתוּב (שם כז) אַחַת שָׁאַלְתִּי מֵאֵת ה' אוֹתָהּ אֲבַקֵּשׁ וְגוֹ'. אַשְׁרֵיהֶם הַצַּדִּיקִים שֶׁכַּמָּה גְנָזִים עֶלְיוֹנִים שְׁמוּרִים לָהֶם בְּאוֹתוֹ הָעוֹלָם, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִשְׁתַּעֲשֵׁעַ עִמָּם בְּאוֹתָם הָעוֹלָמוֹת, כְּמוֹ שֶׁבֵּאַרְנוּ בְּנֹעַם ה', וַהֲרֵי נִתְבָּאֵר. רַבִּי חִזְקִיָּה אָמַר, מִכָּאן (ישעיה סד) עַיִן לֹא רָאָתָה אֱלֹהִים זוּלָתְךְ יַעֲשֶׂה לִמְחַכֵּה לוֹ. יַעֲשֶׂה?! תַּעֲשֶׂה הָיָה צָרִיךְ לִהְיוֹת! אֶלָּא יַעֲשֶׂה וַדַּאי. הַיְנוּ (שם לח) יוֹסִף עַל יָמֶיךְ חֲמֵשׁ עֶשְׂרֵה שָׁנָה. וְהַיְנוּ הַשְׁלֵךְ עַל ה' יְהָבְךְ. וְכָתוּב וַתִּתְפַּלֵּל עַל ה'. וְהַכֹּל אֶחָד."]]],[["זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, בְּעָלְמָא דֵּין וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (תהילים ה׳:י״ב) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךָ אוֹהֲבֵי שְׁמֶךָ. וּכְתִיב (תהילים ק״מ:י״ד) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ. וּכְתִיב (תהילים ט׳:י״א) וְיִבְטְחוּ בְךָ יוֹדְעֵי שְׁמֶךָ כִּי לֹא עָזַבְתָּ דוֹרְשֶׁךָ יְיָ'. בָּרוּךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ' לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"זכאה חולקיהון דצדיקיא וכו׳:","אשרי חלקם של הצדיקים בעולם הזה ובעולם הבא. עליהם כתוב, וישמחו כל חוסי בך לעולם ירננו ותסך עלימו ויעלצו בך אוהבי שמך. וכתוב, אך צדיקים יודו לשמך ישבו ישרים את פניך. וכתוב, ויבטחו בך יודעי שמך כי לא עזבת דורשיך ה'. ברוך ה׳ לעולם אמן ואמן. ימלוך ה׳ לעולם אמן ואמן."]],[[0,"","אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. עֲלֵיהֶם כָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ. וְכָתוּב (שם קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ. וְכָתוּב (שם ט) וְיִבְטְחוּ בְךְ יוֹדְעֵי שְׁמֶךְ כִּי לֹא עָזַבְתָּ דֹּרְשֶׁיךְ ה'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלֹךְ יְיָ לְעוֹלָם אָמֵן וִאָמֵן."]]]]};
